INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1, 'AN0110', 'Analytic 0110', 'Monitor /var/log/audit/audit.log and DNS resolver logs for repeated failed lookups or connections to high-entropy domain names. Correlate suspicious DNS queries with process lineage (e.g., Python, bash, or unusual system daemons).', '{Linux}', 'x-mitre-analytic--00112bcc-174f-4201-ac81-fe3edd1292e6', 'DET0039', '[{"name": "auditd:SYSCALL", "channel": "socket/connect", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "linux:syslog", "channel": "Query to suspicious domain with high entropy or low reputation", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "DomainReputationFeed", "description": "Whitelist/blacklist tuned with external threat intel sources"}, {"field": "ProcessWhitelist", "description": "Known safe daemons that frequently query domains"}]', '2026-05-01 15:26:34.362831');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (2, 'AN0613', 'Analytic 0613', 'Detection of Linux container escape attempts via syscalls (`unshare`, `keyctl`, `mount`) or process execution outside container namespaces. Defenders may correlate unusual system calls from containerized processes with subsequent process creation on the host or modification of host resources.', '{Linux}', 'x-mitre-analytic--0021ecae-778a-4726-aa66-1cf4ca01943e', 'DET0219', '[{"name": "auditd:SYSCALL", "channel": "unshare, mount, keyctl, setns syscalls executed by containerized processes", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "linux:Sysmon", "channel": "process creation events linked to container namespaces executing host-level binaries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SyscallWhitelist", "description": "Expected syscalls by containerized workloads. Deviations may signal an escape attempt."}, {"field": "TimeWindow", "description": "Defines correlation window (e.g., 60s) between suspicious syscalls and follow-on host process activity."}]', '2026-05-01 15:26:34.366547');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (3, 'AN0769', 'Analytic 0769', 'The adversary invokes built-in scripting or decoding tools like base64, plutil, or AppleScript-based utilities to decode files embedded in staging artifacts. Decoding often occurs post-download or as part of post-exploitation payload deployment via zsh, python, or osascript.', '{macOS}', 'x-mitre-analytic--0029e7e7-d42c-4a91-8d00-6bf6fd72962f', 'DET0275', '[{"name": "macos:unifiedlog", "channel": "base64 -d or osascript invoked on staged file", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "DecodeInterpreter", "description": "Could involve base64, osascript, python, perl, or plutil"}, {"field": "ExecutionContext", "description": "Deobfuscation may happen within GUI app context or LaunchAgent/Daemon"}, {"field": "UserContext", "description": "May differ depending on local user, root escalation, or persistence method"}]', '2026-05-01 15:26:34.368009');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (4, 'AN0068', 'Analytic 0068', 'Detection of packed Mach-O binaries unpacking into memory and transferring control to dynamically modified code segments.', '{macOS}', 'x-mitre-analytic--003c2ca3-a9a8-4a56-9163-f6733f19b41d', 'DET0023', '[{"name": "macos:unifiedlog", "channel": "process::exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_MMAP", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "SignedBinaryContext", "description": "Helps to distinguish between signed/unsigned packed binaries (common in legitimate vs. malicious cases)."}, {"field": "UserContext", "description": "Can be used to scope to specific users or service accounts targeted in attacks."}]', '2026-05-01 15:26:34.369333');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (5, 'AN0887', 'Analytic 0887', 'Execution of commands that stop or kill processes associated with logging or security daemons (auditd, syslog, falco). Detect modifications to iptables or disabling SELinux/AppArmor enforcement. Correlate sudo/root context with abrupt service halts.', '{Linux}', 'x-mitre-analytic--003dd2ae-b156-4ebd-8a59-76f993056552', 'DET0317', '[{"name": "auditd:EXECVE", "channel": "systemctl stop auditd, kill -9 <pid>, or modifications to /etc/selinux/config", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "kill syscalls targeting logging/security processes", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}, {"name": "linux:syslog", "channel": "iptables or nftables rule changes", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}]', '[{"field": "ServiceList", "description": "Adjust monitored security service names depending on host configuration."}, {"field": "TimeWindow", "description": "Correlate multiple kill/stop events in short succession."}]', '2026-05-01 15:26:34.371478');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (6, 'AN0061', 'Analytic 0061', 'Adversary disables or stops critical services (e.g., Exchange, SQL, AV, endpoint monitoring) using native utilities or API calls, often preceding destructive actions (T1485, T1486). Behavioral chain: Elevated execution context + stop-service or sc.exe or ChangeServiceConfigW + terminated or disabled service + possible follow-up file manipulation.', '{Windows}', 'x-mitre-analytic--00449d4c-48c7-4977-bf38-86fbc4e79285', 'DET0021', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:System", "channel": "EventCode=7036", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=4", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "TimeWindow", "description": "Time span between elevated privilege use and critical service stop"}, {"field": "ServiceName", "description": "Service names of interest (e.g., MSExchangeIS, SQLSERVERAGENT)"}, {"field": "ParentProcess", "description": "Upstream process lineage leading to service stop"}]', '2026-05-01 15:26:34.373008');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (7, 'AN1421', 'Analytic 1421', 'Detects use of vulnerable kernel extensions or entitlements abused via setuid or AppleScript injection chains.', '{macOS}', 'x-mitre-analytic--0066bac9-599a-4f7b-a667-9cb1dca94347', 'DET0514', '[{"name": "macos:unifiedlog", "channel": "process:exec and kext load events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_KEXTLOAD", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "EntitlementList", "description": "Entitlements vary by app and OS version; some allow unexpected behavior."}, {"field": "TimeWindow", "description": "Correlate SUID execution or AppleScript injection with privilege gain or module load."}]', '2026-05-01 15:26:34.374766');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (8, 'AN0295', 'Analytic 0295', 'Sudden valid logins from accounts that previously had credentials dumped but had not authenticated successfully in the past; correlated with timeline of suspected hash cracking', '{"Identity Provider"}', 'x-mitre-analytic--0084089f-6e5f-42c4-8b0d-78e95cd55d0f', 'DET0105', '[{"name": "azure:signinlogs", "channel": "Success logs from high-risk accounts", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "PostDumpTimeWindow", "description": "Detection window after credential dumping to watch for successful logins"}, {"field": "LoginLocationRisk", "description": "Use IP/geolocation risk scoring to flag unusual access"}]', '2026-05-01 15:26:34.376323');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (9, 'AN0534', 'Analytic 0534', 'Suspicious sign-ins to Graph API or sensitive resources using non-browser scripting agents (e.g., Python, PowerShell), often for programmatic access to mailbox or OneDrive content.', '{SaaS}', 'x-mitre-analytic--00b2801f-752e-4b70-95fd-c2644ccef671', 'DET0186', '[{"name": "azure:signinlogs", "channel": "Operation=UserLogin", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "UserAgentFilter", "description": "Filter for scripting agents (e.g., Python, PowerShell) which may vary by org."}, {"field": "ExpectedClientIPList", "description": "Set of known internal or managed IPs to filter benign automation."}, {"field": "DeviceProperties", "description": "Expected managed device profiles used to detect unmanaged devices."}]', '2026-05-01 15:26:34.37799');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (10, 'AN0010', 'Analytic 0010', 'User modification of the $PATH environment variable in shell configuration files or direct runtime PATH changes, followed by execution of binaries from user-controlled directories. Defender observes file edits to ~/.bashrc, ~/.profile, or /etc/paths.d and process execution resolving to unexpected binary locations.', '{Linux}', 'x-mitre-analytic--00b5d9a8-a794-4d7c-90df-71c4021e0a46', 'DET0004', '[{"name": "auditd:SYSCALL", "channel": "open/write calls modifying ~/.bashrc, ~/.profile, or /etc/paths.d", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:osquery", "channel": "Execution of binary resolved from $PATH not located in /usr/bin or /bin", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredShellConfigs", "description": "Set of shell startup files where PATH changes should be flagged."}, {"field": "AllowedUserBins", "description": "Directories (e.g., /usr/local/bin) considered safe to avoid FP."}]', '2026-05-01 15:26:34.379208');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (11, 'AN0491', 'Analytic 0491', 'Flood of incoming TLS or HTTP(S) connections to macOS-hosted services (e.g., MAMP, Apache), causing high CPU usage and system unresponsiveness.', '{macOS}', 'x-mitre-analytic--00bf6b2e-444a-4a83-aafd-43bc8eea4594', 'DET0173', '[{"name": "macos:unifiedlog", "channel": "Web service process (e.g., httpd) entering crash loop or consuming excessive CPU", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "macos:unifiedlog", "channel": "Rapid incoming TLS handshakes or HTTP requests in quick succession", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TLSHandshakeRate", "description": "Number of renegotiations per minute considered suspicious"}, {"field": "ServiceCrashFrequency", "description": "Threshold of crashes before alerting on instability"}]', '2026-05-01 15:26:34.380436');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (12, 'AN1104', 'Analytic 1104', 'Adversary uses ''esxcli software vib list'' to enumerate installed VIBs, drivers, and modules.', '{ESXi}', 'x-mitre-analytic--0119786d-ee1e-4857-b31a-3a43830e28e7', 'DET0392', '[{"name": "esxi:shell", "channel": "esxcli software vib list", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:hostd", "channel": "Host daemon command log entries related to vib enumeration", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "HostAccessMode", "description": "Detection may vary based on whether enumeration is local or remote."}, {"field": "ScriptChain", "description": "Presence of enumeration in broader scripted sequence."}]', '2026-05-01 15:26:34.38184');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (13, 'AN1112', 'Analytic 1112', 'Detects suspicious access to macOS Keychain files and APIs. Observes processes invoking the ''security'' utility or accessing Keychain databases directly, correlates these with abnormal parent process lineage or unexpected user context. Monitors attempts to dump, unlock, or read credential storage beyond normal application workflows.', '{macOS}', 'x-mitre-analytic--015260e0-432e-4eaf-978e-b1a32fa6af6a', 'DET0396', '[{"name": "macos:unifiedlog", "channel": "execution of security or osascript", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "access or unlock attempt to keychain database", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "macos:unifiedlog", "channel": "read access to ~/Library/Keychains/login.keychain-db", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "AllowedApplications", "description": "Whitelist of applications (e.g., Safari, Mail) normally permitted to access Keychain"}, {"field": "AlertThreshold", "description": "Number of failed keychain unlock attempts before raising an alert"}, {"field": "ParentProcessContext", "description": "Legitimate parent-child process relationships for security tool invocations"}]', '2026-05-01 15:26:34.383172');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (14, 'AN1532', 'Analytic 1532', 'Use of hcitool, bluetoothctl, or rfcomm to initialize Bluetooth connection paired with recent file reads by the same user or session.', '{Linux}', 'x-mitre-analytic--01588556-4b25-4418-b746-9bca0279be2c', 'DET0554', '[{"name": "auditd:SYSCALL", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:syslog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "linux:osquery", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "BluetoothUtility", "description": "List of CLI tools to monitor (e.g., hcitool, rfcomm, obexftp)."}, {"field": "SessionWindow", "description": "Amount of time after interface config a file must be accessed to be linked."}]', '2026-05-01 15:26:34.384469');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (98, 'AN0244', 'Analytic 0244', 'Detects non-system processes accessing /dev/input/* or issuing ptrace/evdev syscalls used for reading keystroke buffers directly.', '{Linux}', 'x-mitre-analytic--0c122a8e-bcb0-4756-8a63-193c52d61d90', 'DET0089', '[{"name": "auditd:SYSCALL", "channel": "open, read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "ptrace, ioctl", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "ProcessName", "description": "Exclude known good applications (e.g. Xorg, GNOME Shell)"}, {"field": "DevicePath", "description": "Typically /dev/input/event*, but tunable to match custom input buses"}]', '2026-05-01 15:26:34.506873');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (15, 'AN0417', 'Analytic 0417', 'Adversary gains access to cloud-hosted services such as AWS SES, SNS, or OpenAI API, enables or modifies usage policies, and initiates resource-intensive actions (e.g., mass email/SMS or LLM queries), often from unauthorized regions or under anomalous identity conditions.', '{SaaS}', 'x-mitre-analytic--01967eb2-5169-4113-aff0-ac2180fd14d9', 'DET0147', '[{"name": "AWS:CloudTrail", "channel": "PutIdentityPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "AWS:CloudTrail", "channel": "SendEmail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "AWS:CloudTrail", "channel": "AssumeRole", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "TimeWindow", "description": "Define threshold period over which request spikes are measured. E.g., 10 min or 1 hour windows."}, {"field": "UserContext", "description": "Alert only if role/user is outside expected automation identity list."}, {"field": "RequestVolumeThreshold", "description": "Customize the number of emails/SMS or API calls considered anomalous."}, {"field": "GeoVelocityThreshold", "description": "Tune geolocation jump logic (e.g., login from US, then use service in Asia within minutes)."}, {"field": "ModelUsageQuotaSpike", "description": "Set maximum allowable deviation from past 7-day average OpenAI/GPT token usage."}]', '2026-05-01 15:26:34.385631');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (16, 'AN0726', 'Analytic 0726', 'Detects staged data aggregated in /Users/Shared, /private/tmp with compression tools like ditto or zip, initiated via Terminal or AppleScript.', '{macOS}', 'x-mitre-analytic--01a3cc24-df78-4ff7-8a25-67545d830229', 'DET0261', '[{"name": "macos:unifiedlog", "channel": "file events", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "exec logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "StagingTargets", "description": "Shared dirs commonly abused for local collection"}, {"field": "CompressionBinaries", "description": "zip, tar, ditto"}, {"field": "TimeWindow", "description": "Seconds/minutes between source file read and output staging write"}]', '2026-05-01 15:26:34.386897');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (17, 'AN0469', 'Analytic 0469', 'Detects PowerShell `Clear-History` invocation or deletion of `ConsoleHost_history.txt` to erase past PowerShell session history.', '{Windows}', 'x-mitre-analytic--01b79770-a269-4b4d-bf09-a4760bae9c94', 'DET0165', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=23", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "HistoryFilePath", "description": "Path to PSReadLine file, typically in APPDATA."}, {"field": "UserContext", "description": "User account or role performing deletion (e.g., low-priv user deleting history)."}, {"field": "CommandPattern", "description": "Support detection of `Clear-History` and variations."}]', '2026-05-01 15:26:34.388106');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (18, 'AN0053', 'Analytic 0053', 'A process loads a shared object (.so) via dlopen/LD_PRELOAD/open from non-standard or temporary locations (e.g., /tmp, /dev/shm), especially shortly after that .so is written or fetched, or linked via manipulated environment variables (LD_PRELOAD/LD_LIBRARY_PATH).', '{Linux}', 'x-mitre-analytic--01c969ef-7057-44bd-bced-9b64a98234ec', 'DET0018', '[{"name": "auditd:SYSCALL", "channel": "openat/read/mmap: Open/mmap .so files from non-standard paths", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "auditd:EXECVE", "channel": "execve: Processes launched with LD_PRELOAD/LD_LIBRARY_PATH pointing to non-system dirs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "sudo or service accounts invoking loaders with suspicious env vars", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "NSM:Flow", "channel": "http/file-xfer: Inbound/outbound transfer of ELF shared objects", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "SuspiciousDirs", "description": "(/tmp, /dev/shm, /var/tmp, user home dirs) – adjust to your environment."}, {"field": "TimeWindow", "description": "Correlate write/fetch of .so to its load (e.g., 0–30 minutes)."}, {"field": "EnvVarWatchlist", "description": "LD_PRELOAD, LD_LIBRARY_PATH, LD_AUDIT."}, {"field": "AllowedSigning/HashList", "description": "Known-good signed or hashed shared objects."}]', '2026-05-01 15:26:34.389593');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (19, 'AN0860', 'Analytic 0860', 'Access to local credential/config files (e.g., ~/.aws/credentials) followed by metadata API calls or cloud role assumptions.', '{IaaS}', 'x-mitre-analytic--01d19202-019e-43c9-a5e9-e1e2a38eb738', 'DET0307', '[{"name": "CloudTrail:GetObject", "channel": "sensitive credential files in buckets or local image storage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "AWS:CloudTrail", "channel": "command-line execution invoking credential enumeration", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "AWS:CloudTrail", "channel": "sudden role assumption after credential file access", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "CredentialFilePattern", "description": "Regex to match common credential files (e.g., *.aws/credentials, token.txt)"}, {"field": "RoleAssumptionScope", "description": "Adjust scope of roles monitored (e.g., admin, service accounts)"}, {"field": "TimeWindow", "description": "Correlation timing between file access and AssumeRole"}]', '2026-05-01 15:26:34.391624');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (20, 'AN0876', 'Analytic 0876', 'Correlates interface mode changes to promiscuous with execution of sniffing tools like tcpdump, tshark, or custom pcap libraries. Detects abnormal NIC configurations and unauthorized sniffing from non-root sessions.', '{Linux}', 'x-mitre-analytic--01ef3337-0585-4eaa-acb2-df363f7d5463', 'DET0314', '[{"name": "auditd:SYSCALL", "channel": "execve, setifflags", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "promiscuous mode transitions (ioctl or ifconfig)", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkconfig ", "channel": "interface flag PROMISC, netstat | ip link | ethtool", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "InterfaceList", "description": "Limit analysis to external interfaces (e.g., eth0, wlan0) and exclude virtual adapters."}, {"field": "PromiscuousSessionThreshold", "description": "Raise alerts if interface remains in PROMISC longer than threshold duration."}]', '2026-05-01 15:26:34.393335');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (21, 'AN0595', 'Analytic 0595', 'Adversary modifies or replaces the Terminal Services DLL (`termsrv.dll`) or changes the associated `ServiceDll` Registry value to load an arbitrary or patched DLL that enables persistent and enhanced RDP access. This may include binary replacement, registry tampering, and unexpected module loads by the `svchost.exe -k termsvcs` process.', '{Windows}', 'x-mitre-analytic--01f18cc1-2948-4ea7-adaf-017da939b9ff', 'DET0212', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetDLLPath", "description": "Defenders may tune for non-standard DLLs loaded by svchost.exe or termsrv.exe processes."}, {"field": "RegistryKeyTarget", "description": "Environment-specific variations in the path to `ServiceDll` registry key (e.g., nested group policies)."}, {"field": "TimeWindow", "description": "Correlation time window for registry change followed by DLL load or svchost restart."}, {"field": "ParentProcessName", "description": "Some environments may spawn registry changes from automation tools or administrative scripts."}]', '2026-05-01 15:26:34.394725');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (22, 'AN0656', 'Analytic 0656', 'Phishing attachments executed on Linux systems are detected by linking email logs to file creation in mail directories and subsequent suspicious process execution. Look for unexpected binaries or scripts spawned from user mail directories and anomalous outbound network activity.', '{Linux}', 'x-mitre-analytic--02309791-384c-4ca9-b25c-6a6bc754795f', 'DET0236', '[{"name": "Application:Mail", "channel": "Inbound email attachments logged from MTAs with suspicious metadata", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "auditd:SYSCALL", "channel": "execve: Execution of files saved in mail or download directories", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Outbound traffic from suspicious new processes post-attachment execution", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AttachmentStoragePaths", "description": "Monitored directories for email attachments (e.g., /var/mail, ~/Maildir, ~/Downloads)."}, {"field": "ScriptInterpreters", "description": "List of interpreters to monitor when spawned by mail clients (e.g., bash, python, perl)."}]', '2026-05-01 15:26:34.396571');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (23, 'AN1063', 'Analytic 1063', 'Execution of unsigned kernel extensions (KEXTs), tampering with LaunchDaemons, or userspace hooks into system libraries.', '{macOS}', 'x-mitre-analytic--0248d3dc-266e-45c3-89e4-4865f9174cfd', 'DET0377', '[{"name": "macos:unifiedlog", "channel": "subsystem=com.apple.kextd", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "macos:osquery", "channel": "launch_daemons", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "fs:fsevents", "channel": "Extensions", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "KextSignatureStatus", "description": "Allowable level of unsigned/3rd-party kernel extensions varies by organization."}, {"field": "KextLoadOrigin", "description": "Detect whether the extension was loaded by an untrusted process or non-root user."}, {"field": "AnomalousLaunchAgent", "description": "Detection tuned based on deviation from known/approved LaunchDaemon plist files."}]', '2026-05-01 15:26:34.397879');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (24, 'AN1079', 'Analytic 1079', 'Detects adversary creation of cloud or IdP accounts whose names resemble existing privileged or service accounts. May indicate preparation for privilege escalation or defense evasion.', '{"Identity Provider"}', 'x-mitre-analytic--0252a0ff-a4fb-4196-9b43-d759af950d55', 'DET0383', '[{"name": "azure:audit", "channel": "Add user", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "azure:audit", "channel": "Rename user", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "saas:okta", "channel": "User lifecycle events", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "RoleScope", "description": "Whether created users have privileged or scoped roles assigned at creation."}, {"field": "NamingHeuristics", "description": "Regex patterns or heuristics for detecting suspicious naming conventions (e.g., helpdesk_support_, root-admin)."}]', '2026-05-01 15:26:34.39914');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (25, 'AN1503', 'Analytic 1503', 'Detects anomalous authentication activity such as sign-ins from impossible geolocations or legacy protocols from high-privileged accounts.', '{"Identity Provider"}', 'x-mitre-analytic--02571f27-8fa6-47cb-9097-0b84016a1dda', 'DET0546', '[{"name": "azure:signinlogs", "channel": "Sign-in activity", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "saas:okta", "channel": "user.authentication.sso", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "AnomalousLocationThreshold", "description": "Defines geographic separation (e.g., impossible travel) considered suspicious."}, {"field": "ProtocolType", "description": "Filter based on legacy or deprecated authentication mechanisms."}]', '2026-05-01 15:26:34.400426');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (26, 'AN0036', 'Analytic 0036', 'Opening of Office files where VBA source code appears benign or missing, but p-code remains active. Defender perspective: process execution of Office apps with macro execution lacking visible source components.', '{macOS}', 'x-mitre-analytic--025e89c6-9383-48b5-b9f2-85ab31b6a7bb', 'DET0012', '[{"name": "macos:unifiedlog", "channel": "Process execution of Microsoft Word, Excel, PowerPoint with macro execution attempts", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Detection of altered _VBA_PROJECT or PerformanceCache streams", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "OfficeVersionScope", "description": "Adjust for specific Office versions in use across macOS endpoints."}]', '2026-05-01 15:26:34.401638');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (611, 'AN0936', 'Analytic 0936', 'Execution of `erase`, `format`, and `reload` in immediate sequence from a privileged AAA session', '{"Network Devices"}', 'x-mitre-analytic--55a0743e-cdc1-44d1-94c7-cf3837e3ef2f', 'DET0329', '[{"name": "networkdevice:syslog", "channel": "command sequence: erase → format → reload", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandSequenceWindow", "description": "Time between erase and reload command to establish causality"}, {"field": "UserPrivilegeLevel", "description": "Filter for high-privilege user sessions"}]', '2026-05-01 15:26:35.259716');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (27, 'AN0856', 'Analytic 0856', 'Correlated file access to insecure credential files (e.g., *.env, *.xml, *.ps1) followed by suspicious process execution or authentication using retrieved credentials. Detected through Sysmon logs and Windows Security Event logs.', '{Windows}', 'x-mitre-analytic--0277e29a-af6d-4242-a187-32673328664a', 'DET0307', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "FileNamePattern", "description": "Patterns like *.env, *credential* can be tuned to reduce noise or catch custom implementations"}, {"field": "ProcessAccessScope", "description": "Defines scope of access (e.g., only untrusted parent processes or high-risk processes)"}, {"field": "TimeWindow", "description": "Time delta between credential file access and use in logon attempt"}]', '2026-05-01 15:26:34.402935');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (28, 'AN0736', 'Analytic 0736', 'Abuse of launchctl to execute or manage Launch Agents and Daemons. Defender perspective: correlation of suspicious plist file creation or modification in LaunchAgents/LaunchDaemons directories with subsequent execution of the launchctl command. Abnormal executable paths (e.g., /tmp, /Shared) or launchctl activity followed by network connections are highly suspicious.', '{macOS}', 'x-mitre-analytic--0297fd45-97bc-4913-8d38-218eae431544', 'DET0265', '[{"name": "macos:unifiedlog", "channel": "execution of launchctl load/unload/start commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "write of plist files in /Library/LaunchAgents or /Library/LaunchDaemons", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "launchctl spawning new processes", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "creation or loading of new launchd services", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "MonitoredPaths", "description": "Paths to monitor for suspicious plist files, such as /Library/LaunchAgents, /Library/LaunchDaemons, ~/Library/LaunchAgents."}, {"field": "SuspiciousExecPaths", "description": "Uncommon executable paths (e.g., /tmp, /Shared) that should raise alerts when associated with launchctl services."}, {"field": "TimeWindow", "description": "Correlation window for detecting plist file creation and subsequent launchctl execution."}]', '2026-05-01 15:26:34.404246');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (29, 'AN0296', 'Analytic 0296', 'Offline cracking inferred by subsequent successful CLI or web-based authentications into routers or switches from previously dumped accounts', '{"Network Devices"}', 'x-mitre-analytic--029db14d-fb94-49ee-9d6d-3c7212671377', 'DET0105', '[{"name": "networkdevice:syslog", "channel": "config access, authentication logs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "LogonTimeCorrelation", "description": "Window to link credential theft and reuse"}, {"field": "SourceDeviceTag", "description": "Filters based on where cracking may have occurred externally"}]', '2026-05-01 15:26:34.405702');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (30, 'AN1531', 'Analytic 1531', 'Detection of non-interactive or suspicious processes accessing Bluetooth interfaces and transmitting outbound traffic following file access or staging activity.', '{Windows}', 'x-mitre-analytic--02fb4d83-d2db-4d49-acbc-85eff3b517d6', 'DET0554', '[{"name": "WinEventLog:System", "channel": "EventCode=8001", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Defines how quickly a file access and Bluetooth activity must occur to be correlated."}, {"field": "InterfaceType", "description": "May focus on Bluetooth-specific interfaces or drivers like ''bthport.sys''."}, {"field": "FileSizeThreshold", "description": "Tune to trigger only on significant exfiltratable file reads."}]', '2026-05-01 15:26:34.407516');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (31, 'AN1115', 'Analytic 1115', 'Observation of LaunchAgents or LaunchDaemons establishing periodic external connections indicative of automated data transfer.', '{macOS}', 'x-mitre-analytic--031ed94b-50d9-451e-a853-29ee8d845773', 'DET0397', '[{"name": "macos:unifiedlog", "channel": "process: exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "network", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "macos:cron", "channel": "cron/launchd", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}]', '[{"field": "LaunchInterval", "description": "Frequency of task recurrence linked to external communication."}, {"field": "DestinationPort", "description": "Port number used for detection filtering."}]', '2026-05-01 15:26:34.409395');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (32, 'AN0530', 'Analytic 0530', 'Compromised service account tokens mounted inside containers and reused for external API calls or lateral movement across services.', '{Containers}', 'x-mitre-analytic--03216652-ada9-4c1e-88c4-923c2cb60614', 'DET0185', '[{"name": "kubernetes:apiserver", "channel": "serviceAccount token used in API requests not tied to workload identity", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "AWS:CloudTrail", "channel": "AssumeRoleWithWebIdentity", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "NamespaceScope", "description": "Restrict token use to specific namespaces or workloads"}]', '2026-05-01 15:26:34.410828');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (33, 'AN1365', 'Analytic 1365', 'Monitor email and document management systems for fraudulent invoices, impersonation of vendors, or BEC-style payment redirections. Detect abnormal editing of invoice templates, or emails containing known fraud language combined with attachment delivery.', '{"Office Suite"}', 'x-mitre-analytic--03364dc1-4b76-4a30-83cf-ae101b960d8e', 'DET0495', '[{"name": "m365:unified", "channel": "MailSend: Outlook messages with suspicious subject/body terms (e.g., urgent payment, wire transfer) targeting finance teams", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:office", "channel": "Anomalous editing of invoice or payment document templates", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "FraudTerms", "description": "Adjustable keyword list for email and document fraud detection."}]', '2026-05-01 15:26:34.412496');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (34, 'AN0008', 'Analytic 0008', 'macOS clients joined to AD via LDAP may script account provisioning via `dsconfigad`, `dscl`, or LDAP scripts. Detection occurs when such tools run on a domain-joined system, followed by authentication attempts by a previously unseen account.', '{macOS}', 'x-mitre-analytic--03513eb2-6dbd-4160-94dd-25d2bce349be', 'DET0003', '[{"name": "macos:unifiedlog", "channel": "dsconfigad or dscl with create or append options for AD-bound users", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "UserLoggedIn", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "EnrollmentStatus", "description": "Only flag on AD-bound systems with valid LDAP context"}, {"field": "AccountType", "description": "Distinguish between user accounts and computer accounts"}]', '2026-05-01 15:26:34.413759');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (35, 'AN1488', 'Analytic 1488', 'Detects anomalous SaaS application integration activity across environments such as Slack, Salesforce, or other enterprise SaaS services. Focus is on unauthorized app additions, unusual permission grants, and persistence through service principal tokens.', '{SaaS}', 'x-mitre-analytic--036a6a5d-bd87-45c7-bd68-43df76167786', 'DET0539', '[{"name": "saas:integration", "channel": "New or modified third-party application integrations with elevated permissions", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "saas:audit", "channel": "Application added or consent granted: Integration persisting after original user disabled", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "AppWhitelist", "description": "Defines approved SaaS integrations for the enterprise; deviations indicate suspicious persistence."}, {"field": "ConsentDelegationPolicy", "description": "Threshold for which users can self-consent integrations; lowering this may reduce false positives."}]', '2026-05-01 15:26:34.414974');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (36, 'AN1473', 'Analytic 1473', 'Detects anomalous CI/CD workflow execution originating from forked repositories, with pull request (PR) metadata or commit messages containing suspicious patterns (e.g., encoded payloads), coupled with the use of insecure pipeline triggers like `pull_request_target` or excessive API usage of CI/CD secrets. Correlation with unusual artifact generation or secret exfiltration via encoded or external network destination URLs confirms suspicious behavior.', '{SaaS}', 'x-mitre-analytic--0391c880-fcb3-457f-b625-18f9453659b8', 'DET0533', '[{"name": "saas:github", "channel": "Workflow triggered via pull_request_target from forked repo", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "saas:github", "channel": "CI/CD secret accessed or exported", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"name": "saas:github", "channel": "Artifact generated includes base64/encoded exfil payload or URL", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"name": "saas:RepoEvents", "channel": "New file added or modified in PR targeting CI/CD or build config (e.g., `gitlab-ci.yml`, `build.gradle`, `pom.xml`, `.github/workflows/*.yml`)", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "saas:PRMetadata", "channel": "Commit message or branch name contains encoded strings or payload indicators", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindow", "description": "Time delta between PR creation and workflow execution to flag rapid attempts"}, {"field": "UserContext", "description": "Forked or external user accounts triggering workflows; may differ across orgs"}, {"field": "TriggerTypeAllowlist", "description": "CI trigger types (e.g., `pull_request_target`) that should or shouldn''t be used for forks"}, {"field": "ArtifactEntropyThreshold", "description": "Entropy threshold for detecting encoded payloads in artifacts"}, {"field": "SecretAccessRateThreshold", "description": "Rate of secret access in a single workflow run that might indicate abuse"}]', '2026-05-01 15:26:34.416159');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (37, 'AN0867', 'Analytic 0867', 'Detects use of `dseditgroup` or `dscl` to add users to privileged macOS groups (e.g., admin).', '{macOS}', 'x-mitre-analytic--03b0d93e-955a-49f6-83ad-8cf72b678367', 'DET0310', '[{"name": "macos:unifiedlog", "channel": "Process execution or directory service changes", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "GroupName", "description": "Focus on ''admin'' or ''com.apple.access_ssh''"}, {"field": "UserContext", "description": "Detect unknown or transient users making group changes"}, {"field": "TimeWindow", "description": "Detect group modifications at suspicious times"}]', '2026-05-01 15:26:34.418737');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (38, 'AN1061', 'Analytic 1061', 'Unauthorized or anomalous loading of kernel-mode drivers or DLLs, concealed services, or abnormal modification of boot components indicative of rootkit activity.', '{Windows}', 'x-mitre-analytic--03f2259d-45c2-4422-83ad-58955f89350c', 'DET0377', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "DriverSignatureStatus", "description": "Signed vs unsigned drivers; many environments restrict unsigned drivers, but some legacy systems allow them."}, {"field": "TargetDirectory", "description": "Suspicious driver or DLL drop locations, e.g., \\System32\\Drivers\\ or \\Temp\\"}, {"field": "UserContext", "description": "Rootkit installation via admin or SYSTEM account."}]', '2026-05-01 15:26:34.419957');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (39, 'AN0679', 'Analytic 0679', 'Database enumeration and export activity (e.g., `SELECT * FROM`, `SHOW DATABASES`) issued via ephemeral VMs, admin APIs, or cloud shell from non-monitoring accounts. Defender correlates audit logs (CloudTrail, GCP Admin, AzureDiagnostics), storage write ops, and cross-region transfers by identities not tied to DB operations.', '{IaaS}', 'x-mitre-analytic--041812fa-5446-47cc-8ca0-1106f4874c10', 'DET0242', '[{"name": "AWS:CloudTrail", "channel": "rds:ExecuteStatement: Large data access via RDS or Aurora with unknown session context", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"name": "AWS:CloudTrail", "channel": "PutObject: S3 writes with .sql/.csv extension by same identity or within 5 min of DB access", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"name": "AWS:VPCFlowLogs", "channel": "Large transfer volume (>20MB) from RDS IP range to external public IPs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "IAMAccessPatterns", "description": "Define which IAM roles/accounts are allowed DB operations"}, {"field": "S3ExportThreshold", "description": "Size threshold (MB) or file pattern for S3-based exfil monitoring"}, {"field": "DBQueryVerbosityThreshold", "description": "Number of rows/columns or duration to flag long-running queries"}]', '2026-05-01 15:26:34.421115');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (99, 'AN1204', 'Analytic 1204', 'Detects suspicious inbound mail traffic where SPF/DKIM/DMARC authentication fails or where sender and return-path domains mismatch, observable in Apple Mail unified logs or MDM-controlled logging pipelines.', '{macOS}', 'x-mitre-analytic--0c4a2cfd-a064-4f45-9c07-eb5c1044dd61', 'DET0431', '[{"name": "macos:unifiedlog", "channel": "SPF fail OR DKIM fail OR DMARC fail OR mismatched header vs envelope domains", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "RecipientSensitivity", "description": "Allows tuning based on which users (e.g., executives, finance staff) receive stricter spoofing detection policies."}, {"field": "HeaderMismatchTolerance", "description": "Defines tolerance for minor discrepancies in domain alignment, balancing detection with usability."}]', '2026-05-01 15:26:34.50861');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (40, 'AN0809', 'Analytic 0809', 'Detects successful login to cloud identity portals (e.g., Okta, Azure AD, Google Identity) from atypical geolocations, devices, or user agents immediately followed by dashboard/portal navigation to sensitive pages such as user or app configuration.', '{"Identity Provider"}', 'x-mitre-analytic--041c0b93-fda4-478f-b847-d10619db729c', 'DET0291', '[{"name": "azure:signinlogs", "channel": "Sign-in with unfamiliar location/device + portal navigation", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "saas:okta", "channel": "user.session.start", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "saas:okta", "channel": "WebUI access to administrator dashboard", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "GeoIPAnomalyThreshold", "description": "Threshold for location anomalies per user profile"}, {"field": "UserAgentReputation", "description": "Unknown browser/device fingerprint list"}, {"field": "PrivilegedPageAccess", "description": "List of sensitive dashboard views for alerting"}]', '2026-05-01 15:26:34.422486');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (41, 'AN0771', 'Analytic 0771', 'Detection of new IAM roles or policies attached to a user/service in AWS/GCP/Azure outside normal patterns or hours, often following account compromise.', '{IaaS}', 'x-mitre-analytic--04412d94-62ac-4484-9408-c4ca1c206f1b', 'DET0277', '[{"name": "AWS:CloudTrail", "channel": "AttachUserPolicy, CreatePolicyVersion, PutRolePolicy", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "RoleScope", "description": "IAM Role type or privilege level assigned (e.g., Admin, Billing, Viewer)"}, {"field": "UserContext", "description": "User, service account, or external federated identity context performing the action"}, {"field": "PolicyChangeTimeWindow", "description": "How quickly multiple roles or policies are added after initial access"}, {"field": "ExternalRoleOrigin", "description": "Cross-account roles from outside trusted tenant list"}]', '2026-05-01 15:26:34.424107');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (42, 'AN1209', 'Analytic 1209', 'Detection focuses on identifying abuse of LD_PRELOAD and related linker variables. Defender perspective: monitor unexpected setting or modification of LD_PRELOAD in shell initialization scripts or environment exports, file creation of suspicious shared libraries, and correlation of these modifications with anomalous process execution. Key signals include execve events with LD_PRELOAD defined, newly created .so files in user directories, and processes hooking libc functions exhibiting abnormal behavior.', '{Linux}', 'x-mitre-analytic--048adb6e-49a1-463e-bc0d-0a9a543cf0ce', 'DET0435', '[{"name": "auditd:SYSCALL", "channel": "execve with LD_PRELOAD or linker-related environment variables set", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PATH", "channel": "creation of .so files in non-standard directories (e.g., /tmp, /home/*)", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "linux:osquery", "channel": "process environment variables containing LD_PRELOAD", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "WatchedEnvVars", "description": "Environment variables like LD_PRELOAD, LD_LIBRARY_PATH. Defenders can tune based on development vs. production systems."}, {"field": "MonitoredDirectories", "description": "Non-standard library paths (e.g., /tmp, user home dirs). May be tuned to reduce false positives from benign development activity."}, {"field": "CorrelationWindow", "description": "Timeframe to correlate suspicious library creation with process execution that loads it."}]', '2026-05-01 15:26:34.425665');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (43, 'AN0478', 'Analytic 0478', 'Script or binary performs a rapid sequence of system discovery checks (e.g., CPU count, RAM size, registry keys, running processes) indicative of VM detection', '{Windows}', 'x-mitre-analytic--04bcbbb7-bfa9-41a5-9fb8-72a6df9ad50b', 'DET0168', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "TimeWindow", "description": "Sequence of system enumeration events within X seconds"}, {"field": "ProcessAncestry", "description": "Parent-child lineage to identify potentially suspicious launch sources (e.g., Office, browser, WMI, PowerShell)"}, {"field": "UserContext", "description": "Limit to non-admin or interactive sessions if desired"}]', '2026-05-01 15:26:34.426959');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (44, 'AN1251', 'Analytic 1251', 'Detects suspicious changes to macOS authorization and PAM plugin files. Correlates file modifications under /etc/pam.d/ or /Library/Security/SecurityAgentPlugins with unexpected authentication attempts or anomalous account usage.', '{macOS}', 'x-mitre-analytic--04cd1c76-d01d-482c-83e2-4bb5109e9764', 'DET0454', '[{"name": "macos:unifiedlog", "channel": "authentication plugin load or modification events", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "macos:osquery", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "WatchedPlugins", "description": "Expected set of PAM and authorization plugins; unknown additions may indicate malicious insertion."}, {"field": "CorrelatedSources", "description": "Cross-correlation with VPN/physical access logs to identify impossible or anomalous login patterns."}]', '2026-05-01 15:26:34.428144');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (45, 'AN0447', 'Analytic 0447', 'Insertion of USB-based hardware proxies (e.g., PiKVM) which register under predictable names (e.g., tinypilot) or mount under known paths (e.g., /opt/tinypilot-privileged).', '{Linux}', 'x-mitre-analytic--04e9470e-676f-4af0-add4-8103300ebd19', 'DET0159', '[{"name": "auditd:SYSCALL", "channel": "udev events or drive enumeration involving TinyPilot paths or device classes", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "FriendlyName", "description": "Different hardware may present differently; names like ''TinyPilot'' may need expanding to cover custom implants."}, {"field": "MountPath", "description": "Path matching (e.g., /opt/tinypilot) is mutable based on distro, customization, and staging."}]', '2026-05-01 15:26:34.429284');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (174, 'AN1435', 'Analytic 1435', 'Flooding tools like hping3 or nping sending large volumes of packets across multiple ports or IPs', '{Linux}', 'x-mitre-analytic--1578f892-0644-4974-bf55-9abb802612fa', 'DET0518', '[{"name": "auditd:SYSCALL", "channel": "Execution of network stress tools or anomalies in socket/syscall behavior", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "High volume flows with incomplete TCP sessions or single-packet bursts", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "PacketRateThreshold", "description": "Packets per second beyond normal behavior"}]', '2026-05-01 15:26:34.61738');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (46, 'AN1007', 'Analytic 1007', 'Connections to exposed container services (e.g., Docker API, Kubernetes API server) from unauthorized external IPs → abnormal container creation/start → lateral activity within cluster nodes.', '{Containers}', 'x-mitre-analytic--04fcf3d4-4547-4e64-bbb7-9faa46dda1f6', 'DET0354', '[{"name": "ApplicationLog:API", "channel": "Docker/Kubernetes API access from external sources", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "kubernetes:audit", "channel": "Unauthorized container creation or kubelet exec logs", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "NSM:Flow", "channel": "External access to container ports (2375, 6443)", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AllowedCIDRs", "description": "Approved external IP ranges for container APIs."}, {"field": "TimeWindow", "description": "Correlation window for API calls and container starts."}]', '2026-05-01 15:26:34.430464');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (47, 'AN0075', 'Analytic 0075', 'Detects unexpected or high-volume HTTP/S/WebSocket communication from suspicious processes (e.g., PowerShell, rundll32) using uncommon user agents or mimicking browser traffic to unusual domains or IPs.', '{Windows}', 'x-mitre-analytic--04fe83c3-d8d3-4c96-91a4-9167fa8f405a', 'DET0027', '[{"name": "NSM:Flow", "channel": "http.log, ssl.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ProcessNameExclusions", "description": "Filter out legitimate browser/network utilities"}, {"field": "UserAgentAnomalies", "description": "Detect non-browser user-agents or spoofed headers"}, {"field": "OutboundByteRatioThreshold", "description": "Flag when outbound > inbound volume by 90%+"}]', '2026-05-01 15:26:34.431907');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (48, 'AN0032', 'Analytic 0032', 'Previously unseen applications generating outbound connections with atypical data flow characteristics, such as excessive data with no return response.', '{macOS}', 'x-mitre-analytic--0519edaf-6485-40b2-8b91-13db29fb8cb8', 'DET0011', '[{"name": "macos:unifiedlog", "channel": "connection attempts", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "session behavior", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ParentProcessCheck", "description": "Allow filtering based on parent-child relationship for benign services."}, {"field": "HostWhitelist", "description": "Known legitimate C2-like patterns (e.g., Apple telemetry)."}]', '2026-05-01 15:26:34.433044');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (49, 'AN0121', 'Analytic 0121', 'Detection of system calls or commands accessing system locale (e.g., ''defaults read -g AppleLocale'', ''systemsetup -gettimezone''). Correlate with unusual parent processes or execution contexts.', '{macOS}', 'x-mitre-analytic--0521835b-bc02-41ed-8e6a-153e6422ee9c', 'DET0043', '[{"name": "macos:unifiedlog", "channel": "defaults read -g AppleLocale, systemsetup -gettimezone", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExecutionPath", "description": "Restrict known binaries allowed to query system locale on macOS."}]', '2026-05-01 15:26:34.434187');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (50, 'AN1339', 'Analytic 1339', 'Sign-in failures across enterprise SSO applications or SaaS platforms from same IP address using the same password against multiple user identities', '{"Identity Provider"}', 'x-mitre-analytic--0527196a-1551-445c-bdd7-943dfda9b718', 'DET0487', '[{"name": "azure:signinlogs", "channel": "Failure Reason + UserPrincipalName", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "GeoIPAnomalyCheck", "description": "Use geolocation mismatches to strengthen signal"}, {"field": "FailedUserRatio", "description": "Proportion of total user base affected to filter noise"}]', '2026-05-01 15:26:34.435427');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (51, 'AN0437', 'Analytic 0437', 'Processes such as curl, wget, or custom scripts initiating POST requests to webhook endpoints with encoded or bulk data. Defender perspective: abnormal chaining of file compression or access followed by outbound data to webhook URLs.', '{Linux}', 'x-mitre-analytic--053dd0c5-9746-46ea-bdeb-b385bf5cbbf8', 'DET0153', '[{"name": "auditd:EXECVE", "channel": "curl -X POST, wget --post-data", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "read/open of sensitive files", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "large HTTPS POST requests to webhook endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AllowedTools", "description": "Expected command-line utilities allowed to interact with webhooks in enterprise environments."}, {"field": "TimeWindow", "description": "Expected timeframe for legitimate webhook traffic (e.g., CI/CD deployments)."}]', '2026-05-01 15:26:34.436659');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (52, 'AN1987', 'Analytic 1987', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (53, 'AN0699', 'Analytic 0699', 'Execution of `pip.exe`, `npm.cmd`, or MSI installers within user context, followed by script interpreter startup (e.g., python.exe) or PowerShell with unusual child processes or file writes in `%APPDATA%`, `%TEMP%`, or `%LOCALAPPDATA%`. Defender correlates command-line install tools with Sysmon and Event Logs to trace downstream behavior.', '{Windows}', 'x-mitre-analytic--05985fc7-44cf-4b28-8d4f-14c1662bc5ea', 'DET0252', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AllowedParentProcesses", "description": "Filter expected automation tools (e.g., enterprise installers, known IDEs)"}, {"field": "InstallPathsToWatch", "description": "Suspicious post-install write paths (e.g., %APPDATA%, %TEMP%)"}, {"field": "ExecutableEntropyThreshold", "description": "Used for evaluating if dropped files are packed/obfuscated"}]', '2026-05-01 15:26:34.43937');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (54, 'AN1187', 'Analytic 1187', 'Detection focuses on correlating snapshot creation events with subsequent instance creation and mounting activities. From a defender perspective, suspicious sequences include snapshot creation by unexpected or newly created IAM users, snapshots created from sensitive volumes without preceding change-control activity, or snapshots immediately followed by mounting to unauthorized instances. Cross-referencing with user behavior, IP geolocation, and automation context helps distinguish benign backup operations from adversary-driven snapshot exploitation.', '{IaaS}', 'x-mitre-analytic--05af7b9b-ec1a-4d6c-a944-64a7ad0eb2f5', 'DET0423', '[{"name": "AWS:CloudTrail", "channel": "CreateSnapshot", "x_mitre_data_component_ref": "x-mitre-data-component--3da222e6-53f3-451c-a239-0b405c009432"}, {"name": "AWS:CloudTrail", "channel": "DescribeSnapshots", "x_mitre_data_component_ref": "x-mitre-data-component--8bc66f94-54a9-4be4-bdd1-fe90df643774"}]', '[{"field": "UserContext", "description": "IAM user, service account, or role performing snapshot creation. Tuned to allowlist known backup automation services."}, {"field": "TimeWindow", "description": "Frequency of snapshot creation in a defined period. Adjusted for environments with frequent automated backups."}, {"field": "GeoLocation", "description": "Unusual regions or IPs from which snapshot creation API calls originate. Helps identify cross-region snapshot abuse."}, {"field": "VolumeSensitivity", "description": "Tagging or classification of volumes being snapshotted. Tuned to prioritize alerts when sensitive volumes are copied."}]', '2026-05-01 15:26:34.440928');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (55, 'AN1291', 'Analytic 1291', 'Detects rogue DHCP activity by monitoring syslog for dhclient messages assigning unauthorized DNS/gateway values. Packet capture or IDS can detect multiple competing DHCP OFFERs from non-authorized servers.', '{Linux}', 'x-mitre-analytic--05d8ce15-eaeb-47f5-abb7-8f8868dd8aaa', 'DET0468', '[{"name": "linux:syslog", "channel": "suspicious DHCP lease assignment with unexpected DNS or gateway", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Gratuitous or duplicate DHCP OFFER packets from non-legitimate servers", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AllowedDHCPMACs", "description": "Expected MAC addresses of DHCP servers on subnet."}, {"field": "DHCPLeaseChangeThreshold", "description": "Number of suspicious DHCP leases before raising an alert."}]', '2026-05-01 15:26:34.443436');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (56, 'AN0917', 'Analytic 0917', 'Detection of suspicious use of ioctl/sysfs calls to access device firmware, unexpected flashing tools execution, and anomalous firmware checksums logged by SMART or kernel audit mechanisms.', '{Linux}', 'x-mitre-analytic--062580eb-eb79-4b31-b3fd-e500ebcfc128', 'DET0323', '[{"name": "auditd:SYSCALL", "channel": "ioctl/write: Direct firmware update or device memory manipulation syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"name": "linux:syslog", "channel": "Driver load events or firmware load failures for hardware devices", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}]', '[{"field": "FirmwareImageBaseline", "description": "Baseline firmware checksums for comparison"}, {"field": "AlertThresholds", "description": "Tolerance levels for SMART errors before triggering alerts"}]', '2026-05-01 15:26:34.444877');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (57, 'AN0797', 'Analytic 0797', 'Cause→effect chain: (1) A client app (browser, Office, PDF/Flash/reader) experiences a crash/abnormal exit or loads from an unusual location, then (2) drops or modifies a file in user-writable paths, and/or (3) spawns an unexpected child (e.g., powershell/cmd/mshta/rundll32/wscript/installer), and (4) establishes outbound C2-like connections shortly after. Correlate application logs, file writes, process lineage, and network egress within a short window.', '{Windows}', 'x-mitre-analytic--065f2c96-6903-4cd1-a737-99ecf1fdc73e', 'DET0287', '[{"name": "WinEventLog:Application", "channel": "EventCode=1000", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Correlation window (e.g., 15m) between crash/write/child/network."}, {"field": "HighRiskChildren", "description": "List of child processes that should rarely spawn from Office/browsers (powershell.exe, cmd.exe, wscript.exe, mshta.exe, rundll32.exe, regsvr32.exe, msiexec.exe, curl.exe)."}, {"field": "UserPaths", "description": "Writable paths to watch (Downloads, %TEMP%, %APPDATA%, OneDrive, Office startup folders)."}, {"field": "AllowedPlugins", "description": "Known add-ins/extensions and updater binaries to reduce noise."}, {"field": "EgressAllowlist", "description": "Known update/CDN domains and proxy egress CIDRs for suppression."}]', '2026-05-01 15:26:34.446801');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (58, 'AN0224', 'Analytic 0224', 'Adversary exploits exposed OpenSLP on ESXi or vCenter public endpoints. Chain: inbound request pattern to mgmt service → hostd/vpxd error/crash/restart → unexpected process behavior or datastore access → outbound callback.', '{ESXi}', 'x-mitre-analytic--0668f39a-d319-427f-b29b-160399e6f79a', 'DET0080', '[{"name": "esxi:hostd", "channel": "/var/log/hostd.log anomalies (faults, crashes, restarts) around inbound connections", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Connections to TCP 427 (SLP) or vCenter web services from untrusted sources", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MgmtCIDR", "description": "Only trusted admin networks should reach ESXi/vCenter."}, {"field": "TimeWindow", "description": "Join errors and inbound flows."}]', '2026-05-01 15:26:34.448086');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (67, 'AN0308', 'Analytic 0308', 'Observation of chmod commands setting setuid/setgid bits, paired with launch of binaries under elevated execution context (e.g., root-owned binaries launched by unprivileged users).', '{macOS}', 'x-mitre-analytic--08314a8b-becd-4853-8a6c-dd5a947b36c0', 'DET0110', '[{"name": "macos:unifiedlog", "channel": "chmod command with arguments including ''+s'', ''u+s'', or numeric values 4000–6777", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "exec of binary with setuid/setgid and EUID != UID", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "UserContext", "description": "Monitor execution chains where UID != EUID or child process inherits root without known sudo context"}, {"field": "ExecutionPath", "description": "Focus on binaries in user-writable locations or abnormal directories"}, {"field": "ChmodPattern", "description": "Tailor detection to chmod commands that imply privilege elevation via numeric mode or symbolic mode"}]', '2026-05-01 15:26:34.460148');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (59, 'AN0834', 'Analytic 0834', 'Sequential behavioral chain of privilege escalation through permission modification: (1) Process creation of permission-modifying utilities (icacls, takeown, attrib, cacls), (2) Correlation with unusual user context or timing, (3) DACL modification events targeting sensitive files/directories, (4) Subsequent file access or modification attempts indicating successful privilege bypass', '{Windows}', 'x-mitre-analytic--0669b8b5-8888-45aa-acf8-819dfb7d00a2', 'DET0299', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindow", "description": "Temporal correlation window for linking permission modification with subsequent access attempts (default: 300 seconds)"}, {"field": "SensitivePathList", "description": "Environment-specific critical file and directory paths requiring permission change monitoring"}, {"field": "TrustedUserContext", "description": "Administrative accounts authorized to perform legitimate permission modifications"}, {"field": "BusinessHoursThreshold", "description": "Time-based threshold for elevated alerting on permission changes outside business hours"}]', '2026-05-01 15:26:34.4492');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (60, 'AN1427', 'Analytic 1427', 'Programmatic access to user content via stolen access tokens in platforms like Slack, GitHub, Google Workspace — especially from new IPs, apps, or excessive resource access.', '{SaaS}', 'x-mitre-analytic--0677b819-0586-454c-9f4d-c861ccaf1b73', 'DET0515', '[{"name": "saas:googleworkspace", "channel": "Access via OAuth credentials with unusual scopes or from anomalous IPs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "saas:slack", "channel": "OAuth token use by unknown app client_id accessing private channels or files", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "GeoVelocity", "description": "Flag when token use appears across geographically distant logins"}, {"field": "OAuthScopeSensitivity", "description": "Weight certain scopes (admin, file.read) as higher risk"}]', '2026-05-01 15:26:34.45042');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (61, 'AN1976', 'Analytic 1976', 'Consider use of services that may aid in the tracking of certificates in use on sites across the Internet. In some cases it may be possible to pivot on known pieces of certificate information to uncover other adversary infrastructure.(Citation: Splunk Kovar Certificates 2017)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (62, 'AN1619', 'Analytic 1619', 'Account discovery via VBA macros, COM objects, or embedded scripting.', '{"Office Suite"}', 'x-mitre-analytic--06e0501e-a87e-452d-9ab5-93ed9a5eade5', 'DET0587', '[{"name": "m365:unified", "channel": "Scripted Activity", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "MacroName", "description": "Alert on auto-running macros accessing directory or user info."}, {"field": "ExecutionScope", "description": "Focus on macros invoking LDAP, ADODB, or WMI queries."}]', '2026-05-01 15:26:34.452735');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (63, 'AN1247', 'Analytic 1247', 'Detection monitors extended attribute manipulation (xattr) to strip quarantine or trust metadata, anomalous installation of root certificates in /etc/ssl or /usr/local/share/ca-certificates, and unauthorized modification of system trust stores. Correlates with unexpected process execution involving package managers or custom certificate utilities.', '{Linux}', 'x-mitre-analytic--06ec22c9-b32f-49bc-81cc-ed5cee622493', 'DET0452', '[{"name": "auditd:SYSCALL", "channel": "chmod, chown, setxattr, or file writes to /etc/ssl/* or /usr/local/share/ca-certificates/*", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "auditd:EXECVE", "channel": "Process execution of update-ca-certificates or openssl with suspicious arguments", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CertificatePathList", "description": "Paths to monitor for changes depending on distro-specific trust locations"}, {"field": "RegexPatterns", "description": "Regex patterns for suspicious use of xattr or openssl parameters"}]', '2026-05-01 15:26:34.45391');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (64, 'AN1132', 'Analytic 1132', 'Unauthorized mirroring sessions initiated on routers/switches (e.g., via `monitor session`, `mirror port`) coupled with outbound traffic from mirrored interface to unexpected destinations.', '{"Network Devices"}', 'x-mitre-analytic--0729dd54-2fda-460a-8bb3-eee02f0f3c4e', 'DET0403', '[{"name": "networkdevice:syslog", "channel": "Config change: CLI/NETCONF/SNMP – ''monitor session'', ''mirror port''", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "networkdevice:Flow", "channel": "Traffic from mirrored interface to mirror target IP", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ConfigChangeType", "description": "Tune based on accepted interface config changes (e.g., audit only mirror session creation)"}, {"field": "MirrorDestinationPort", "description": "Define high-risk ports used for exfil (e.g., 4443, 8443, 2055)"}, {"field": "DeviceRole", "description": "Define whether mirroring is expected on edge vs core vs distribution devices"}]', '2026-05-01 15:26:34.45524');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (65, 'AN0817', 'Analytic 0817', 'Detects tenant-wide authentication or conditional access changes that weaken hybrid identity enforcement, including disabling AD FS or bypassing hybrid MFA policies.', '{"Office Suite"}', 'x-mitre-analytic--07b8a45e-6435-4c67-ac15-47db21c1d1b9', 'DET0293', '[{"name": "m365:unified", "channel": "Modify Federation Settings or Update Authentication Policy", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "PolicyScope", "description": "Scope of authentication and federation policies to be monitored."}]', '2026-05-01 15:26:34.456946');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (66, 'AN0145', 'Analytic 0145', 'Identifies custom or previously unseen userland processes initiating high-volume HTTP connections with low response volume.', '{Linux}', 'x-mitre-analytic--07deb060-c373-4059-b73b-736688a25c80', 'DET0053', '[{"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "UserProcessBaseline", "description": "Defines what is considered abnormal for a user-initiated process context"}]', '2026-05-01 15:26:34.458605');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (68, 'AN0211', 'Analytic 0211', 'Detects abuse of Mono/.NET Core environments to execute VB-like scripts, often in environments with Office emulation or WINE. Focus is on rare invocations of scripting hosts like mono.exe or .NET shells, often seen in spam filtering or forensic labs with Office support.', '{Linux}', 'x-mitre-analytic--08318de4-1327-48ac-a686-403162d3891f', 'DET0076', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "/var/log/syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "InterpreterPath", "description": "Mono/.NET Core binary location may differ per distro or Docker container."}, {"field": "FileExtension", "description": ".vbs, .vb, or .vba run under non-standard interpreters."}, {"field": "ExecContext", "description": "Execution by low-privilege users or from /tmp/."}]', '2026-05-01 15:26:34.46165');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (69, 'AN1037', 'Analytic 1037', 'Detects tampered Mac hardware/firmware by analyzing unified logs, EndpointSecurity events, and Apple Mobile File Integrity (AMFI) checks. Behavioral chain: (1) Boot process reports firmware signature mismatch; (2) Secure Boot policy altered; (3) new EFI drivers or hardware devices appear in inventory; (4) system extension loads from unapproved developer IDs post-boot.', '{macOS}', 'x-mitre-analytic--0834f268-5810-4a90-8ef6-279dc0482471', 'DET0368', '[{"name": "macos:unifiedlog", "channel": "EFI firmware integrity check failed", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "macos:endpointsecurity", "channel": "es_event_authentication", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "AllowedTeamIDs", "description": "Developer Team IDs approved for kext/system extension loads."}, {"field": "FirmwareVersionBaseline", "description": "Expected EFI/firmware version for Mac model."}]', '2026-05-01 15:26:34.464328');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (70, 'AN1023', 'Analytic 1023', 'Outbound encrypted traffic initiated from hypervisor shell or via VM backdoor mechanisms to relays in VPS infrastructure, especially if traversing multiple nodes before reaching Internet destination. Packet captures or firewall logs show non-VM communication paths.', '{ESXi}', 'x-mitre-analytic--08370ff8-9442-42c0-bfb5-c7f5792c74ea', 'DET0359', '[{"name": "esxi:esxupdate", "channel": "/var/log/esxupdate.log or /var/log/vmksummary.log", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "esxi:vmkernel", "channel": "/var/log/vmkernel.log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "Relay patterns across IP hops", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "HopCount", "description": "Threshold on number of IPs contacted in sequence without DNS resolution."}, {"field": "ShellAccess", "description": "Flag if relay communication initiated by ESXi shell or unknown VM agent."}, {"field": "VPSIPRange", "description": "Filter for known Tor/VPS egress networks."}]', '2026-05-01 15:26:34.465581');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (71, 'AN1448', 'Analytic 1448', 'A remote host sends a short sequence of failed connection attempts (RST/ICMP unreachable) to a set of closed ports. Within a brief window the endpoint (a) adds/enables a firewall rule or (b) a sniffer-backed process begins listening or opens a new socket, after which a successful connection occurs. Also detects Wake-on-LAN magic packets seen on local segment.', '{Windows}', 'x-mitre-analytic--0848a778-7bcf-48d9-a14a-d29d1e71e656', 'DET0524', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Microsoft-Windows-Windows Firewall With Advanced Security/Firewall", "channel": "EventCode=2004, 2005, 2006", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindowKnock", "description": "Window to correlate knock sequence → rule change → successful connect (e.g., 120s)."}, {"field": "PortSequenceMinLen", "description": "Minimum number of distinct closed ports hit before success (e.g., 3)."}, {"field": "SuspiciousProcesses", "description": "List of binaries that commonly toggle firewall/sniff (netsh.exe, powershell.exe, npcapservice.exe, windivert, rawsock tools)."}, {"field": "AllowedFirewallChangers", "description": "Service accounts or software update agents allowed to change firewall."}, {"field": "WoLAllowedWindows", "description": "Maintenance windows when magic packets are expected."}]', '2026-05-01 15:26:34.466782');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (72, 'AN1090', 'Analytic 1090', 'Access to organizational directories via Google Workspace Directory API, Slack SCIM, or Okta SCIM by apps or identities outside normal roles.', '{SaaS}', 'x-mitre-analytic--089d588f-a6aa-4083-a900-ebcae97b5bfa', 'DET0386', '[{"name": "Google Admin Audit", "channel": "users.list, groups.list", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "saas:okta", "channel": "System API Call: user.read, group.read", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "APIRequestRate", "description": "Detect rapid enumeration attempts or recursive group expansion."}, {"field": "AppIntegrationID", "description": "Tag expected SCIM clients and suppress false positives from enterprise sync tools."}, {"field": "GeoContext", "description": "Trigger alerts if enumeration occurs from anomalous IPs or regions."}]', '2026-05-01 15:26:34.468018');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (73, 'AN0997', 'Analytic 0997', 'Detection of execution of legacy scripting runtimes (e.g., older versions of Python, Bash, or PowerShell Core) lacking auditing. Monitoring for changes to EFI or system boot files indicative of downgrade-based persistence or bypass of integrity features.', '{macOS}', 'x-mitre-analytic--08a391a7-1ce6-4f11-b060-fca06ef03328', 'DET0350', '[{"name": "macos:unifiedlog", "channel": "Execution of older or non-standard interpreters", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Modifications or writes to EFI system partition for downgraded bootloaders", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "ApprovedInterpreterVersions", "description": "Defines the minimal version of interpreters expected; older versions flagged as downgrade attempts."}]', '2026-05-01 15:26:34.469236');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1502, 'AN1990', 'Analytic 1990', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (74, 'AN1143', 'Analytic 1143', 'Cloud-hosted VM or container generates spoofed UDP requests to third-party services on known amplifier ports, with high outbound-to-inbound traffic ratios in VPC Flow Logs', '{IaaS}', 'x-mitre-analytic--08c69003-044c-46a5-b17a-7cb5b25f2d50', 'DET0408', '[{"name": "AWS:CloudTrail", "channel": "Create egress rule allowing UDP to port 53, 123, 11211", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"name": "AWS:VPCFlowLogs", "channel": "Large outbound UDP traffic to multiple public reflector IPs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "AWS:CloudWatch", "channel": "Sudden spike in network output without a corresponding inbound request ratio", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "EgressRulePorts", "description": "Cloud security group rules permitting UDP to reflector protocols"}, {"field": "OutboundToInboundRatio", "description": "Ratio threshold to flag traffic as potential reflection behavior"}, {"field": "VMInstanceTagContext", "description": "Cloud metadata that can help scope anomalous behavior to development, testing, or external-facing services"}]', '2026-05-01 15:26:34.470525');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (75, 'AN0775', 'Analytic 0775', 'Detection of writes to /boot or EFI directories outside of expected package manager updates. Monitoring kernel log and auditd events for attempts to overwrite bootloader binaries (e.g., grub, shim). Unexpected execution of efibootmgr or dd writing to /dev/sdX devices followed by boot parameter changes.', '{Linux}', 'x-mitre-analytic--08dd2c3b-e07c-4b47-bae6-aa09c2a86d87', 'DET0278', '[{"name": "auditd:SYSCALL", "channel": "open, write: Modification of /boot/grub/* or /boot/efi/*", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:EXECVE", "channel": "exec: Execution of dd, efibootmgr, or flashrom modifying firmware/boot partitions", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "PackageManagerUpdateWhitelist", "description": "Allowlist of legitimate grub/shim updates via apt, yum, or rpm."}, {"field": "FilesystemPaths", "description": "Directories (e.g., /boot/efi, /boot/grub) monitored for unauthorized modification."}]', '2026-05-01 15:26:34.471816');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (76, 'AN0928', 'Analytic 0928', 'Shell scripts or binaries implement custom mapping tables (tr/sed/awk/golang/rust/python encode loops), or emit long high-entropy tokens that fail Base64/Hex validation → correlated with egress showing asymmetric flow, protocol-mismatch payloads, or DNS/HTTP bodies containing low-diversity-but-long custom alphabets.', '{Linux}', 'x-mitre-analytic--09125bb1-29eb-4d40-994a-2e1aa7bcd105', 'DET0326', '[{"name": "auditd:SYSCALL", "channel": "execve of interpreters (python, perl), custom binaries, or shell utilities with long arguments containing non-standard tokens", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "http: HTTP bodies/headers contain long tokens with non-standard alphabets or constant-size periodic POSTs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "EntropyThreshold", "description": "Payload entropy minimum."}, {"field": "TokenLengthThreshold", "description": "Length threshold for suspect tokens."}, {"field": "BytesOutToInRatio", "description": "Asymmetry cutoff for flows."}, {"field": "TimeWindow", "description": "Correlation join window."}, {"field": "KnownEncoders", "description": "Legitimate internal tools/agents."}]', '2026-05-01 15:26:34.473392');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (77, 'AN1965', 'Analytic 1965', 'Consider analyzing self-signed code signing certificates for features that may be associated with the adversary and/or their developers, such as the thumbprint, algorithm used, validity period, and common name. Malware repositories can also be used to identify additional samples associated with the adversary and identify patterns an adversary has used in crafting self-signed code signing certificates.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (78, 'AN1244', 'Analytic 1244', 'Detect user-initiated kextload commands or modifications to /Library/Extensions. Correlate with changes to KextPolicy database or unauthorized developer signing identities. Alert on attempts to disable SIP or load legacy extensions from unsigned sources.', '{macOS}', 'x-mitre-analytic--092689c7-be8a-4d11-99d8-7dd96afa938d', 'DET0450', '[{"name": "macos:unifiedlog", "channel": "kextload execution from Terminal or suspicious paths", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "Processes executing kextload, spctl, or modifying kernel extension directories", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "New kext entries not signed by Apple or outside standard identifier prefix", "x_mitre_data_component_ref": "x-mitre-data-component--23e4ee78-26f3-4fcf-ba43-ab953962f96c"}, {"name": "macos:osquery", "channel": "Modifications to /var/db/SystemPolicyConfiguration/KextPolicy or kext_policy table", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "DeveloperIDAllowlist", "description": "Approved developer IDs whose kexts should not trigger alerts"}, {"field": "KextLoadTimeWindow", "description": "Threshold for detecting kext loads outside standard install/update operations"}, {"field": "SignatureCheckFlag", "description": "Flag to enforce strict signing checks depending on SIP status"}]', '2026-05-01 15:26:34.477045');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (85, 'AN0192', 'Analytic 0192', 'Phishing attempts targeting IdPs often manifest as anomalous login attempts from suspicious email invitations or fake SSO prompts. Detection correlates login flows, MFA bypass attempts, and anomalous geographic patterns following phishing email delivery.', '{"Identity Provider"}', 'x-mitre-analytic--09df0b88-e1ae-4a1e-86c4-8bb00e79baed', 'DET0070', '[{"name": "azure:signinlogs", "channel": "Failed MFA attempts, unusual conditional access triggers, login attempts from unexpected IP ranges", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "GeoAnomalyThreshold", "description": "Allowed distance/time delta between user sign-ins."}, {"field": "MFABypassIndicators", "description": "Signals of repeated or anomalous MFA failures linked to phishing campaigns."}]', '2026-05-01 15:26:34.488003');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (79, 'AN1253', 'Analytic 1253', 'A process (often after stealing/creating a token) calls CreateProcessWithTokenW/CreateProcessAsUserW or uses runas to spawn a **new** process whose security context (SID/LogonId/IntegrityLevel) differs from its parent. Chain: (1) suspicious command/API → (2) privileged handle or token duplication/open → (3) new child process running as another user / higher integrity → (4) optional follow‑on privileged/lateral actions.', '{Windows}', 'x-mitre-analytic--0929e9c5-2e1a-4cc1-a9c5-df081b180201', 'DET0456', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "ETW:ProcThread", "channel": "api_call: CreateProcessWithTokenW, CreateProcessAsUserW", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672, 4634", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Security", "channel": "EventCode=5136", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}]', '[{"field": "TimeWindow", "description": "Correlation window between API/handle access and the spawned process (default 5–10 minutes)."}, {"field": "AllowedImpersonators", "description": "Service accounts/binaries legitimately using CreateProcessWithTokenW (e.g., PsExec service, SCCM, backup agents)."}, {"field": "IntegrityEscalationDelta", "description": "Minimum jump in integrity level (e.g., Medium→System) to flag."}, {"field": "ParentChildUserMismatch", "description": "Treat any parent/child SID or LogonId mismatch as suspicious unless on allow-list."}, {"field": "SensitiveTargets", "description": "List of processes (e.g., lsass.exe, winlogon.exe, services.exe) whose token access prior to the spawn raises score."}]', '2026-05-01 15:26:34.478502');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (80, 'AN1089', 'Analytic 1089', 'Bulk enumeration of cloud user email identities through `Get-Recipient`, `Get-Mailbox`, `Get-User`, or Graph API directory listings by abnormal accounts or suspicious sessions.', '{"Office Suite"}', 'x-mitre-analytic--0961ff0c-8c36-4820-948d-12855b7f5cc7', 'DET0386', '[{"name": "WinEventLog:PowerShell", "channel": "CmdletName: Get-Recipient, Get-User", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "Microsoft Graph API Logs", "channel": "users.list, directoryObjects.getByIds", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "CmdletVolume", "description": "Tune threshold for recipient/mailbox queries by volume per hour."}, {"field": "UserAgent", "description": "Match known admin consoles and exclude sanctioned tools like MSOL PowerShell."}, {"field": "SessionContext", "description": "Elevate sessions from unmanaged or external endpoints."}]', '2026-05-01 15:26:34.480282');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (81, 'AN0256', 'Analytic 0256', 'Adversary uses `dscl`, `who`, or environment variables like `$USER` to identify accounts or sessions via Terminal or malicious LaunchAgents.', '{macOS}', 'x-mitre-analytic--0979e7f1-9d0a-4549-be8f-88979df5c8d7', 'DET0093', '[{"name": "macos:unifiedlog", "channel": "subsystem:com.apple.Terminal", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "LaunchAgentPersistence", "description": "Correlate dscl usage with known persistence vectors"}, {"field": "CommandExecutionPath", "description": "Distinguish between user-initiated terminal vs. script execution"}, {"field": "UsernameEnumerationPattern", "description": "Regex-based pattern tuning for `dscl . -list /Users` + grep filters"}]', '2026-05-01 15:26:34.481781');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (82, 'AN1628', 'Analytic 1628', 'Detects timestamp changes using `touch`, `SetFile`, or direct metadata tampering (e.g., xattr manipulation) from Terminal, scripts, or low-level APIs.', '{macOS}', 'x-mitre-analytic--097ce8cb-9a38-4c8a-836c-cee15ccdf258', 'DET0591', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "CommandMatch", "description": "Touch/setfile and backdated timestamps"}, {"field": "UserContext", "description": "Detects execution under non-interactive/system accounts"}]', '2026-05-01 15:26:34.483125');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (83, 'AN2030', 'Analytic 2030', 'A process with no prior history or outside of known whitelisted tools initiates file or registry modifications to configure exclusion rules for antivirus, backup, or file-handling systems. Or a file system enumeration for specific file names andcritical extensions like .dll, .exe, .sys, or specific directories such as ''Program Files'' or security tool paths or system component discovery for the exclusion of the files or components.', '{Windows}', 'x-mitre-analytic--098f0607-df17-4291-a1b1-a8e3374c075a', 'DET0897', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "TimeWindow", "description": "Correlate multiply discovery activities and file enumeration activities."}, {"field": "DiscoveryActivityThreshold", "description": "Minimum number of different discovery techniques within time window to trigger detection - balance between false positives and coverage (default: 4 activities)"}, {"field": "ExclusionTargetList", "description": "List of extensions or folders considered suspicious when excluded (e.g., .dll, .exe, C:\\\\Program Files\\\\)"}, {"field": "AuthorizedExclusionModifiers", "description": "Whitelist of known system management tools/processes allowed to modify exclusion settings"}]', '2026-05-01 15:26:34.484539');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (84, 'AN0142', 'Analytic 0142', 'Correlate command executions involving ''sudo'' with elevated effective user ID (euid=0), especially when tty_tickets is disabled or timestamp_timeout is actively abused.', '{Linux}', 'x-mitre-analytic--0994985d-1d45-478e-9f1c-f407eb297007', 'DET0052', '[{"name": "auditd:SYSCALL", "channel": "execve call for sudo where euid != uid", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "auditd:SYSCALL", "channel": "execve call for modification of /etc/sudoers or writing to /var/db/sudo", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "timestamp_timeout_threshold", "description": "Tune the valid sudo session duration to reduce false positives"}, {"field": "command_allowlist", "description": "Filter benign sudo usage (e.g., approved admin scripts)"}]', '2026-05-01 15:26:34.485802');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (86, 'AN0184', 'Analytic 0184', 'Adversary installs or modifies IIS components (ISAPI filters, extensions, or modules) using DLL files registered via configuration changes or administrative tools like AppCmd.exe. These components intercept or manipulate HTTP requests/responses for persistence or C2.', '{Windows}', 'x-mitre-analytic--09ef4725-8e20-452d-b08c-f7db3cbee174', 'DET0068', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:System", "channel": "Changes to applicationhost.config or DLLs loaded by w3wp.exe", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Microsoft-IIS-Configuration", "channel": "Module or ISAPI filter registration events", "x_mitre_data_component_ref": "x-mitre-data-component--66531bc6-a509-4868-8314-4d599e91d222"}]', '[{"field": "TimeWindow", "description": "Adjustable time frame for detecting chained events (e.g., config change + module load)"}, {"field": "UserContext", "description": "Scope detection to specific users or roles allowed to modify IIS components"}, {"field": "WatchedPaths", "description": "Specific directories such as %windir%\\System32\\inetsrv\\ for DLL monitoring"}, {"field": "DLLNameEntropyThreshold", "description": "Entropy or name patterns to flag suspicious DLLs registered as components"}, {"field": "ParentProcessName", "description": "Restrict to DLLs loaded by w3wp.exe or invoked via AppCmd.exe"}]', '2026-05-01 15:26:34.489685');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (87, 'AN0046', 'Analytic 0046', 'Detects adversary attempts to monopolize control of compromised systems by issuing service stop commands, unloading vulnerable modules, or forcefully killing competing processes. Defenders should monitor audit logs and syslog for administrative utilities (systemctl, service, kill) being invoked outside of normal change management.', '{Linux}', 'x-mitre-analytic--0a1f9686-4fd6-4719-84ef-7a590d02d1fb', 'DET0015', '[{"name": "auditd:SYSCALL", "channel": "execve: Commands like systemctl stop <service>, service <service> stop, or kill -9 <pid>", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:syslog", "channel": "Unexpected termination of daemons or critical services not aligned with admin change tickets", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "CriticalProcessList", "description": "Defines specific Linux daemons and processes that should not be terminated outside maintenance windows."}, {"field": "AdminUserContext", "description": "Defines expected accounts permitted to execute service stop commands; deviations may be suspicious."}]', '2026-05-01 15:26:34.49163');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (88, 'AN1211', 'Analytic 1211', 'Modification or replacement of service executables due to weak file or directory permissions. Defender observes file writes to service binary paths, unexpected modifications of executables associated with registered services, and subsequent service execution of attacker-supplied binaries under elevated permissions.', '{Windows}', 'x-mitre-analytic--0a847430-f140-419e-b0fe-bd891bde85a6', 'DET0436', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredServices", "description": "List of critical services and their expected executable paths for integrity checking."}, {"field": "HashBaseline", "description": "Baseline hashes of legitimate service executables for tamper detection."}, {"field": "TimeWindow", "description": "Correlation interval between file modification of service executables and service execution."}, {"field": "PrivilegedAccounts", "description": "Accounts allowed to legitimately modify service executables."}]', '2026-05-01 15:26:34.493285');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (89, 'AN0732', 'Analytic 0732', 'Anomalous or bulk download activity from private or restricted repositories by non-developer or privileged accounts, often preceded by unusual login behavior (e.g., unfamiliar geo, OAuth token use, elevated API rate).', '{SaaS}', 'x-mitre-analytic--0aa20e10-ec46-4acf-810e-e8ed038d7744', 'DET0263', '[{"name": "saas:github", "channel": "repo.download, repo.clone, oauth.authorize, repo.getContent", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"name": "saas:github", "channel": "Login from unusual IP, device fingerprint, or location; access token creation from new client", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "saas:github", "channel": "Bulk access to multiple files or large volume of repo requests within short time window", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TimeWindow", "description": "Threshold for file access volume over short duration (e.g., 10+ repos accessed in <5 min)"}, {"field": "UserContext", "description": "Role or permission profile expected to interact with repositories (e.g., developers vs. admins)"}, {"field": "GeoAnomalyThreshold", "description": "Distance or variance allowed before a login is flagged as anomalous"}, {"field": "RepoSensitivityTag", "description": "Whether a repository is labeled sensitive or restricted"}]', '2026-05-01 15:26:34.494668');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (90, 'AN1074', 'Analytic 1074', 'Adversaries accessing datastore or configuration files via `vim-cmd`, `esxcli`, or SCP to extract logs, VMs, or host configurations.', '{ESXi}', 'x-mitre-analytic--0abb4122-0795-46ef-b162-7570db42596a', 'DET0380', '[{"name": "esxis:vmkernel", "channel": "Datastore Access", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "esxi:hostd", "channel": "Command Execution", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AccessPathRegex", "description": "Regex for filtering targeted VM paths or files like *.vmdk, *.vmx."}, {"field": "InteractiveShellUsage", "description": "Tune to distinguish between interactive and script-driven data access."}]', '2026-05-01 15:26:34.495957');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (91, 'AN0459', 'Analytic 0459', 'Chain: (1) IdP policy/read operations by a principal (e.g., Microsoft Entra/Graph requests to read password or authentication policies); (2) adjacent risky changes (role assignment, app consent) by same principal. Use IdP audit logs.', '{"Identity Provider"}', 'x-mitre-analytic--0b0d50a0-d07b-4cf1-9cb0-23c95e8321b2', 'DET0161', '[{"name": "azure:audit", "channel": "operation contains ''Get*Password*Policy'' OR ''List*Authentication*Policy'' OR ''Get-ADDefaultDomainPasswordPolicy''", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "TrustedPartnerAppIds", "description": "Legitimate partner apps that enumerate policies."}, {"field": "GeoRiskTolerance", "description": "Raise risk for unusual geo or TOR/VPN egress."}]', '2026-05-01 15:26:34.497214');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (92, 'AN1165', 'Analytic 1165', 'Repeated invocation of high-resource application endpoints or GUI components causing CPU and memory spikes, logged as elevated request volumes, prolonged handle locks, or frequent crash recoveries.', '{Windows}', 'x-mitre-analytic--0b514d96-12ce-41e2-b870-b35933d7faa6', 'DET0415', '[{"name": "WinEventLog:Application", "channel": "High-frequency errors or hangs from resource-intensive application components (e.g., .NET, IIS, Office Suite)", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "Windows:perfmon", "channel": "Sudden spikes in CPU/Memory usage linked to specific application processes", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "CPUThreshold", "description": "Define what percentage of CPU usage indicates abnormal behavior."}, {"field": "MemoryConsumptionWindow", "description": "Window (e.g., 5 mins) during which sustained memory usage may be abnormal."}, {"field": "AppCrashFrequency", "description": "Threshold for frequency of application faults within a specific interval."}]', '2026-05-01 15:26:34.498425');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (93, 'AN0496', 'Analytic 0496', 'Detects exploitation of vulnerabilities in cloud identity providers (IdPs) such as Azure AD or Okta for credential access. Defender perspective includes anomalous token creation or renewal, authentication bypass events, and API abuse to mint unauthorized tokens. Correlation highlights exploitation attempts tied to absent or inconsistent audit logs.', '{"Identity Provider"}', 'x-mitre-analytic--0b8b8557-0393-4c63-963f-e5a3b5cc6ad8', 'DET0174', '[{"name": "azure:signinlogs", "channel": "TokenIssued, TokenRenewed: Unexpected or anomalous token issuance events", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "m365:unified", "channel": "ConsentGranted: Abuse of application integrations to mint tokens bypassing MFA", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TokenAnomalyThreshold", "description": "Threshold for anomalous token creation or renewal before alerting."}, {"field": "MonitoredAppIntegrations", "description": "Applications with privileged access that should be tightly monitored for misuse."}]', '2026-05-01 15:26:34.499974');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (94, 'AN0892', 'Analytic 0892', 'Changes to security configurations such as disabling MFA requirements, reducing session token lifetimes, or turning off risk-based policies. Correlate admin logins with sudden policy downgrades.', '{"Identity Provider"}', 'x-mitre-analytic--0ba25127-85e4-46ef-8173-96aa9df90c22', 'DET0317', '[{"name": "azure:policy", "channel": "DisableMfaPolicy or change to ConditionalAccess rules", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "PolicyList", "description": "Adjust for the critical identity provider security policies to monitor."}]', '2026-05-01 15:26:34.501225');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (95, 'AN0134', 'Analytic 0134', 'Detects deletion or overwriting of logs/configs that store SSH or proxy activity, such as /var/log/auth.log or custom .bash_history clearing tied to SSH sessions or firewall rule changes.', '{Linux}', 'x-mitre-analytic--0bd02555-3b54-4425-84c8-118b95857df1', 'DET0049', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "CommandMatchPattern", "description": "Commands like `> /var/log/auth.log`, `rm ~/.bash_history`, `iptables -F`"}, {"field": "LogPathFilter", "description": "Focus on /var/log/auth.log, /etc/ssh/, ~/.bash_history"}]', '2026-05-01 15:26:34.502531');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (96, 'AN0871', 'Analytic 0871', 'Multi-event correlation of Registry creation under Active Setup with anomalous execution of processes at user logon. Behavioral patterns include creation/modification of HKLM Active Setup keys with non-standard StubPath values, followed by process execution from uncommon paths, unsigned binaries, or unusual parent-child lineage post-user login.', '{Windows}', 'x-mitre-analytic--0be2ac94-5f56-4bdc-bf07-ec9ea08c8bb7', 'DET0312', '[{"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}]', '[{"field": "TimeWindow", "description": "Correlate registry change and process execution within a specific user logon session (e.g., 5–10 minutes)"}, {"field": "ParentProcessName", "description": "Expected parent processes for Active Setup launched binaries (e.g., explorer.exe). Deviations may indicate abuse."}, {"field": "StubPathValueEntropy", "description": "Degree of randomness/uncommonness in StubPath values. High entropy may indicate obfuscation."}, {"field": "SignedBinaryStatus", "description": "Flag if launched binary in StubPath is unsigned or uncommon for baseline"}, {"field": "RegistryKeyOwner", "description": "Check which user/context added the Active Setup key to detect privilege abuse"}]', '2026-05-01 15:26:34.503863');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (97, 'AN0147', 'Analytic 0147', 'Sequence of internal email sent from a recently compromised user account (preceded by abnormal logon or device activity), with attachments or links leading to execution or credential harvesting. Defender observes: internal mail delivery to peers with high entropy attachments, followed by click events, process initiation, or credential prompts.', '{Windows}', 'x-mitre-analytic--0bf5b548-50d0-4e73-bb3c-413cbdfafd97', 'DET0054', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4625", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "m365:unified", "channel": "SendOnBehalf, MessageSend, ClickThrough, MailItemsAccessed", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Expected time between internal email and link execution or file dropper"}, {"field": "UserContext", "description": "Baseline logon locations and device usage for sender accounts"}, {"field": "AttachmentEntropyThreshold", "description": "Entropy value over which attachment is considered suspicious"}]', '2026-05-01 15:26:34.505135');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (100, 'AN1357', 'Analytic 1357', 'Detects anomalous use of COM, DDE, or named pipes for execution. Correlates creation or access of IPC mechanisms (e.g., named pipes, COM objects) with unusual parent-child process relationships or code injection patterns (e.g., Office spawning cmd.exe via DDE).', '{Windows}', 'x-mitre-analytic--0c6a8e7a-f9d0-479a-88c1-4ce26edba81c', 'DET0493', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=17", "x_mitre_data_component_ref": "x-mitre-data-component--b9a1578e-8653-4103-be23-cb52e0b1816e"}]', '[{"field": "PipeNamePattern", "description": "Environment-specific pipe names used legitimately vs anomalous (e.g., \\\\.\\pipe\\svcctl)."}, {"field": "AllowedParentChildPairs", "description": "Expected parent-child process lineage to minimize false positives (e.g., explorer.exe spawning outlook.exe)."}]', '2026-05-01 15:26:34.510113');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (101, 'AN1566', 'Analytic 1566', 'Suspicious access to Microsoft Teams chat messages via eDiscovery, Graph API, or export methods after rare or compromised sign-in. Often associated with excessive file access, sensitive content review, or anomaly from expected user behavior.', '{"Office Suite"}', 'x-mitre-analytic--0c833a56-ca8e-41d8-b79a-3f3c89c63a48', 'DET0567', '[{"name": "m365:unified", "channel": "TeamsMessagesAccessedViaEDiscovery, TeamsGraphMessageExport", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:signinlogs", "channel": "UserLoggedIn", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "UserRole", "description": "Whether user is part of InfoSec, Legal, or expected to use Teams eDiscovery tools"}, {"field": "GeoRiskScore", "description": "Unusual country/IP sign-in patterns prior to Teams data export"}, {"field": "AccessVolume", "description": "Message or file threshold for triggering alert"}]', '2026-05-01 15:26:34.511513');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (102, 'AN0925', 'Analytic 0925', 'ESXi shell or guest VM tools initiate external connections via scripted traffic forwarding to Internet-based proxies. Detected by firewall or shell audit logs showing outbound connection spikes from hypervisor or guest VM to remote proxy nodes.', '{ESXi}', 'x-mitre-analytic--0c8a9540-51d7-4ba3-8594-8860b3fa8485', 'DET0325', '[{"name": "esxi:shell", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "esxi:vmkernel", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "VMOutboundPatterns", "description": "Detect when VMs communicate with Internet IPs not in workload profiles."}, {"field": "ProxyHostPattern", "description": "Regex for proxy-related tools/scripts executed on the host."}, {"field": "ConnectionDirectionality", "description": "Outbound only connections from ESXi to new IPs."}]', '2026-05-01 15:26:34.514079');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (103, 'AN1995', 'Analytic 1995', 'Monitor for logged domain name system (DNS) registry data that may hijack domains and/or subdomains that can be used during targeting.  In some cases, abnormal subdomain IP addresses (such as those originating in a different country from the root domain) may indicate a malicious subdomain.(Citation: Palo Alto Unit 42 Domain Shadowing 2022) Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (104, 'AN0872', 'Analytic 0872', 'Detection of browser-based or email client-driven file creation (often from temp directories) following navigation to or execution of HTML files containing JavaScript Blob APIs or base64 Data URLs, with follow-on execution of the dropped payload. Leveraging Sysmon EventID 15 to inspect Zone.Identifier ADS for HostUrl/ReferrerUrl indicators (e.g., HostUrl=about:internet). Optional: absence of a large HTTP download record for the same URL/client in proxy logs (suggests local assembly)', '{Windows}', 'x-mitre-analytic--0cb02d2e-dcea-4195-80e7-81ec29b4d546', 'DET0313', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "EDR:detection", "channel": "App reputation telemetry", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "Network Traffic", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Time range between HTML file open and file drop + execution (e.g., 1–10 minutes)"}, {"field": "DroppedFileExtensionWatchlist", "description": "Tunable list of file extensions of interest (e.g., .js, .hta, .exe)"}, {"field": "ParentProcessName", "description": "Expected processes that may drop files (e.g., browser, Outlook); tune for normal behavior"}]', '2026-05-01 15:26:34.516637');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (105, 'AN0969', 'Analytic 0969', 'High-volume packet generation by local processes (e.g., PowerShell, cmd, curl.exe) or network service processes resulting in excessive outbound traffic over short time window, correlated with abnormal resource usage or degraded host responsiveness.', '{Windows}', 'x-mitre-analytic--0de81d5a-ffba-4eba-915d-c4f4d8b30f9a', 'DET0343', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PacketRateThreshold", "description": "Defines the burst threshold (e.g., 10,000 pps) above which activity should be flagged as anomalous."}, {"field": "TimeWindow", "description": "Duration over which to aggregate and analyze flow volume."}]', '2026-05-01 15:26:34.517936');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (106, 'AN0197', 'Analytic 0197', 'Detects remote writes or snapshots mounted from other systems into a central ESXi VMFS path or NFS store used for remote staging of files before exfiltration.', '{ESXi}', 'x-mitre-analytic--0e2094fe-6912-4bde-9e5a-9d95c640646a', 'DET0071', '[{"name": "esxi:vmkernel", "channel": "VMFS file creation", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "esxi:vob", "channel": "NFS/remote access logs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "esxi:shell", "channel": "invoked remote scripts (esxcli)", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SnapshotFrequency", "description": "How often snapshots are mounted or restored from peer nodes"}, {"field": "RemoteWriteVolume", "description": "Threshold for staging behavior vs. backup/operational activity"}, {"field": "StorageMountPaths", "description": "Common local destinations for incoming data"}]', '2026-05-01 15:26:34.519139');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (107, 'AN0665', 'Analytic 0665', 'Adversary defaces internal VM-hosted portals or web UIs by modifying static content on datastore-mounted paths.', '{ESXi}', 'x-mitre-analytic--0e7e1861-14be-4862-8cba-6344e6e196f2', 'DET0238', '[{"name": "esxi:vmkernel", "channel": "Unauthorized file modifications within datastore volumes via shell access or vCLI", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "DatastoreVolumeName", "description": "Each environment’s VMFS/volume mounts will vary in name and path."}]', '2026-05-01 15:26:34.520696');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (108, 'AN0239', 'Analytic 0239', 'Detection of encoded payloads being decoded and executed in-memory using scripting tools or third-party decoders.', '{macOS}', 'x-mitre-analytic--0e832ea1-a261-4bdd-8fc8-ae049468c347', 'DET0087', '[{"name": "macos:unifiedlog", "channel": "log stream", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:endpointsecurity", "channel": "es_event_exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "memory mapping", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "ScriptContent", "description": "Encoded payload content varies across adversaries."}, {"field": "ExecutionChain", "description": "Sequence of tools or scripts executed can differ."}, {"field": "UserContext", "description": "May depend on whether user is admin, daemon, or system account."}]', '2026-05-01 15:26:34.522035');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (109, 'AN1229', 'Analytic 1229', 'Suspicious process spawning (e.g., `rundll32`, `svchost`, `powershell`, or `netsh`) followed by network connection creation to internal hosts or uncommon external endpoints on high or non-standard ports.', '{Windows}', 'x-mitre-analytic--0e9add05-93bd-47b2-acf5-1817f03e804a', 'DET0445', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "Outbound Connection", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ParentProcessName", "description": "Legitimate system processes that may rarely spawn network-capable child processes (e.g., `rundll32`, `svchost`)."}, {"field": "DestinationPort", "description": "Watch for high-numbered ports or well-known proxy ports like 1080, 8080, 4444."}, {"field": "TimeWindow", "description": "Capture unusual spikes in outbound connections over a short period."}]', '2026-05-01 15:26:34.523726');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (110, 'AN0034', 'Analytic 0034', 'Discrepancies between VBA source code and p-code inside Office documents. Defender perspective: anomalies in file metadata streams, execution of Office processes loading macros without source code consistency, and script execution with no corresponding source metadata.', '{Windows}', 'x-mitre-analytic--0ea214f3-5d66-4170-b33d-58a6577bb074', 'DET0012', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredExtensions", "description": "Expand or restrict which Office file types (.docm, .xlsm, .pptm) are flagged for VBA project analysis."}, {"field": "TimeWindow", "description": "Correlate Office process execution with subsequent script execution within a narrow window."}]', '2026-05-01 15:26:34.525276');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (111, 'AN0266', 'Analytic 0266', 'Use of native tools or scripting (e.g., `usermod`, `passwd`, `groupmod`) to escalate permissions or persist access on existing users, correlated with login or process events.', '{Linux}', 'x-mitre-analytic--0eb6cf59-4ba8-4cea-b64a-686ce7c69f70', 'DET0096', '[{"name": "auditd:SYSCALL", "channel": "usermod, groupmod, passwd", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "auditd:PATH", "channel": "/etc/passwd or /etc/group file write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "SudoPath", "description": "Common sudo or privilege escalation paths (e.g., `/usr/bin/passwd`)."}, {"field": "ModifiedShellList", "description": "Detect if user shell is changed to unusual one (e.g., /bin/sh -> /bin/bash)."}]', '2026-05-01 15:26:34.526751');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (112, 'AN0467', 'Analytic 0467', 'Detects adversary behavior clearing command history via `history -c`, deletion or modification of ~/.bash_history, or manipulation of the HISTFILE environment variable post-login.', '{Linux}', 'x-mitre-analytic--0ebcdeba-7b02-4f1c-96c9-a602b3663446', 'DET0165', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "TimeWindow", "description": "Detect shell history clearing shortly after login or command execution."}, {"field": "UserContext", "description": "Elevated shell sessions (e.g., root or sudo) without command history may be more suspicious."}, {"field": "HistoryFilePath", "description": "Bash/Zsh history file paths (e.g., ~/.bash_history, ~/.zsh_history)."}]', '2026-05-01 15:26:34.528154');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (175, 'AN1455', 'Analytic 1455', 'Execution of `esxcli system hostname get`, `esxcli system version get`, or `esxcli hardware` commands through SSH or local shell.', '{ESXi}', 'x-mitre-analytic--164a04c5-db61-477f-b3fa-8bf806631fbb', 'DET0525', '[{"name": "esxi:vmkernel", "channel": "/var/log/vmkernel.log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SessionOrigin", "description": "Track SSH or console-based entry points."}, {"field": "CommandString", "description": "Customize detection for expected CLI queries."}]', '2026-05-01 15:26:34.618497');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (113, 'AN1156', 'Analytic 1156', 'Unusual web-based access or API scraping of password managers, single sign-on sessions, or credential sync services via browser automation or anomalous API tokens.', '{SaaS}', 'x-mitre-analytic--0ec40b2f-4969-443f-bad5-4bc6239fec29', 'DET0412', '[{"name": "saas:googleworkspace", "channel": "Accessed third-party credential management service", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "saas:zoom", "channel": "unusual web session tokens and automation patterns during login", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TokenAnomalyThreshold", "description": "Scoring threshold for access token entropy, reuse, or bot-like patterns"}, {"field": "AccessGeoLocation", "description": "Region anomalies in SaaS portal access"}]', '2026-05-01 15:26:34.529872');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (114, 'AN1434', 'Analytic 1434', 'Executable or script generating large outbound network traffic targeting remote hosts or known amplification ports', '{Windows}', 'x-mitre-analytic--0eff49de-834e-42d3-9a7a-3ac032aa9836', 'DET0518', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ThresholdEventVolume", "description": "Number of connections per second that should trigger anomaly logic"}, {"field": "DestinationDiversity", "description": "Count of unique destination IPs or ports"}]', '2026-05-01 15:26:34.531377');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (115, 'AN1567', 'Analytic 1567', 'Detects suspicious USB HID device enumeration and keystroke injection patterns, such as rapid sequences of input with no user context, scripts executed through simulated keystrokes, or rogue devices presenting themselves as keyboards.', '{Windows}', 'x-mitre-analytic--0f05915c-e146-4921-840b-1a08774ca4d2', 'DET0568', '[{"name": "WinEventLog:System", "channel": "EventCode=2003", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AuthorizedUSBDevices", "description": "List of known, legitimate USB vendor/product IDs authorized for use in the enterprise."}, {"field": "ExecutionTimeWindow", "description": "Restrict detection to times when no user is logged in or activity is outside business hours."}, {"field": "ParentProcessWhitelist", "description": "List of legitimate parent processes expected to spawn PowerShell or scripting engines."}]', '2026-05-01 15:26:34.532833');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (116, 'AN0023', 'Analytic 0023', 'Developer tools (Homebrew, pip, npm/yarn, Xcode builds) install or update dependencies; new Mach-O or scripts appear under /usr/local, /opt/homebrew, ~/Library/Application Support, project dirs (node_modules/.bin, venv/bin). First run spawns sh/zsh/osascript/curl and new outbound flows; Gatekeeper/AMFI may flag unsigned components.', '{macOS}', 'x-mitre-analytic--0f186e7f-fe33-45d6-ba1e-02a334cf1cb3', 'DET0009', '[{"name": "macos:unifiedlog", "channel": "softwareupdated/homebrew/install logs, pkginstalld events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:endpointsecurity", "channel": "exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "First-time egress to non-approved registries after dependency install", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AllowedTeamIDs", "description": "Apple Developer Team IDs for approved dev tools (Xcode, JetBrains, etc.)."}, {"field": "BrewTapsAllowList", "description": "Homebrew taps allowed in your environment."}, {"field": "TimeWindow", "description": "Default 90 minutes."}]', '2026-05-01 15:26:34.534016');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (117, 'AN1460', 'Analytic 1460', 'Detects use of macOS-native archiving or encryption tools (zip, ditto, hdiutil) for staging collected data. Identifies unexpected invocation of archive utilities by Office apps, browsers, or background daemons. Correlates file creation of .zip/.dmg containers with process lineage anomalies.', '{macOS}', 'x-mitre-analytic--0f4789c9-7946-473f-967b-e8ca59fa3c8c', 'DET0526', '[{"name": "macos:unifiedlog", "channel": "Execution of zip, ditto, hdiutil, or openssl by non-terminal parent processes", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Creation of .zip or .dmg files in user-accessible or temporary directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AllowedArchiveUtilities", "description": "Business-approved applications (e.g., Time Machine, backup agents) that generate archives."}, {"field": "UserContext", "description": "Threshold for flagging archive creation under privileged or service accounts."}, {"field": "PayloadEntropyThreshold", "description": "Entropy threshold for detecting encrypted archives versus standard compressed files."}]', '2026-05-01 15:26:34.535291');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (118, 'AN0868', 'Analytic 0868', 'Detection of inconsistencies between reported sensor health and actual process/service state. For example, Windows Defender tray icon/UI showing healthy status while corresponding Defender services (WinDefend, MsMpEng) are stopped or disabled. Correlates process creation events with missing or terminated security processes and spoofed health events.', '{Windows}', 'x-mitre-analytic--0f4ec296-008e-42aa-95b2-6e4e351d730c', 'DET0311', '[{"name": "WinEventLog:System", "channel": "EventCode=7036", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ServiceNameList", "description": "Monitored list of critical security service names; environment-specific."}, {"field": "FakeUIProcessPatterns", "description": "Patterns of filenames or paths mimicking Windows Security GUI elements."}]', '2026-05-01 15:26:34.53667');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (119, 'AN0312', 'Analytic 0312', 'Detection of changes or execution of shell initialization scripts like .bashrc, .profile, or /etc/profile for persistence.', '{Linux}', 'x-mitre-analytic--0f8a0af6-7544-4f29-8e08-6b07dda1337e', 'DET0112', '[{"name": "auditd:SYSCALL", "channel": "EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PATH", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "linux:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "FilePath", "description": "Initialization script path that can differ across user and system profiles."}, {"field": "UserContext", "description": "User-level vs root-level configuration."}, {"field": "TimeWindow", "description": "Useful to correlate between file change and subsequent execution."}]', '2026-05-01 15:26:34.53786');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (120, 'AN0791', 'Analytic 0791', 'A remote DCOM invocation by a privileged account using RPC (port 135), followed by abnormal process instantiation or module loading on the remote system indicative of code execution.', '{Windows}', 'x-mitre-analytic--0f94823c-ac95-48d8-9716-58f59d39974c', 'DET0285', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TimeWindow", "description": "Correlate RPC activity with remote process creation within a configurable time window (e.g., 300s)"}, {"field": "UserContext", "description": "Identify rare or first-time DCOM invocations by specific accounts"}, {"field": "ProcessName", "description": "List of suspicious executables commonly abused via DCOM (e.g., excel.exe, wmiprvse.exe)"}, {"field": "RemoteHostList", "description": "Known set of systems that should or should not be invoking DCOM activity"}]', '2026-05-01 15:26:34.540225');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (121, 'AN1499', 'Analytic 1499', 'VMware services (hostd, vpxa) unexpectedly negotiating asymmetric crypto sessions to external endpoints outside vCenter or update servers. Defender sees encrypted handshakes in logs inconsistent with baseline ESXi communication patterns.', '{ESXi}', 'x-mitre-analytic--0f9943f2-0e7e-44da-b7dd-e1a7cd52aae0', 'DET0543', '[{"name": "esxi:vpxd", "channel": "ESXi process initiating asymmetric handshake with external host", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "esxcli:network", "channel": "Socket inspection showing RSA key exchange outside baseline endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "BaselineMgmtHosts", "description": "Expected external endpoints (vCenter, update repos)."}]', '2026-05-01 15:26:34.54216');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (122, 'AN1093', 'Analytic 1093', 'Detects anomalous ARP cache changes and unsolicited ARP broadcasts using unified logs and packet capture. Behavioral detection includes multiple IP addresses mapped to the same MAC address and repeated gratuitous ARP traffic.', '{macOS}', 'x-mitre-analytic--0f996058-7524-4759-9d88-a8997e90ff3c', 'DET0387', '[{"name": "macos:unifiedlog", "channel": "ARP table updates inconsistent with expected gateway or DHCP lease assignments", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "Excessive gratuitous ARP replies on local subnet", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "GatewayMACBaseline", "description": "Known MAC addresses for gateways or DHCP servers; used to detect spoofed ARP entries."}, {"field": "CorrelationDepth", "description": "How many ARP inconsistencies to tolerate before escalating detection."}]', '2026-05-01 15:26:34.543708');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (123, 'AN1179', 'Analytic 1179', 'Identify processes issuing repeated DNS queries to random-looking domains with abnormal entropy or word concatenations. Correlate resolver logs with high NXDOMAIN rates and auditd socket connections.', '{Linux}', 'x-mitre-analytic--0faa41a3-0d4c-42d1-885a-12436fbee9c1', 'DET0419', '[{"name": "auditd:SYSCALL", "channel": "socket/connect", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "linux:syslog", "channel": "Multiple NXDOMAIN responses and high entropy domains", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "NXDOMAINThreshold", "description": "Ratio of failed queries triggering alert (e.g., >40%)"}, {"field": "DomainAge", "description": "Flag queries to domains registered in last 7–30 days"}]', '2026-05-01 15:26:34.545084');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (124, 'AN0027', 'Analytic 0027', 'Monitors cloud function creation triggered by specific audit log events (e.g., IAM changes, object creation), followed by anomalous behavior from new service accounts.', '{IaaS}', 'x-mitre-analytic--0fb1d87b-e993-447e-8a2f-e9d42f6859c0', 'DET0010', '[{"name": "AWS:CloudTrail", "channel": "CreateFunction", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "AWS:CloudTrail", "channel": "InvokeFunction", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TriggerEventType", "description": "Specific cloud event (e.g., PutObject, CreateRole) that causes function invocation"}, {"field": "ServiceAccountRole", "description": "Expected permissions for roles used in function execution"}]', '2026-05-01 15:26:34.546737');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (125, 'AN0805', 'Analytic 0805', 'Detects creation or modification of crontab entries by non-root users or from abnormal parent processes, followed by the execution of uncommon binaries at scheduled intervals.', '{Linux}', 'x-mitre-analytic--0fbbc547-37a7-4d00-a8a4-5fbcf3d27a1e', 'DET0290', '[{"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CronFilePath", "description": "System-specific crontab paths may vary across distros or deployments."}, {"field": "RunUser", "description": "Define if only root or specific admin users are allowed to schedule jobs."}, {"field": "ExecutionFrequency", "description": "Threshold for suspicious repetition (e.g., every minute jobs)."}]', '2026-05-01 15:26:34.54818');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (126, 'AN2006', 'Analytic 2006', 'Once adversaries have provisioned software on a compromised server (ex: for use as a command and control server), internet scans may reveal servers that adversaries have compromised. Consider looking for identifiable patterns such as services listening, certificates in use, SSL/TLS negotiation features, or other response artifacts associated with adversary C2 software.(Citation: ThreatConnect Infrastructure Dec 2020)(Citation: Mandiant SCANdalous Jul 2020)(Citation: Koczwara Beacon Hunting Sep 2021)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (127, 'AN0209', 'Analytic 0209', 'Detects execution of VB-based scripts or macros (VBS/VBA/VBScript) through cscript.exe/wscript.exe, Office-based process chains, or HTA usage. Focuses on chained behavior: Office or HTML container spawns script host > script host spawns PowerShell, network connections, or process injection.', '{Windows}', 'x-mitre-analytic--0fe7a1db-759d-4d27-8ef1-a71509643594', 'DET0076', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ParentProcess", "description": "Microsoft Word/Excel or mshta.exe spawning wscript.exe/cscript.exe."}, {"field": "UserContext", "description": "Script execution by non-admin users or service accounts."}, {"field": "TimeWindow", "description": "Script execution outside normal business hours or patching cycle."}, {"field": "PayloadEntropyThreshold", "description": "High entropy indicative of obfuscation or encoding in the script."}, {"field": "ModuleName", "description": "Loading of vbscript.dll, scrrun.dll, or other scripting engine modules."}]', '2026-05-01 15:26:34.550559');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (128, 'AN1207', 'Analytic 1207', 'Abuse of mavinject.exe to inject DLLs or import descriptors into another running process. Chain: (1) mavinject.exe starts with /INJECTRUNNING or /HMODULE → (2) mavinject obtains high-access handles to a target process (VM_WRITE/CREATE_THREAD) → (3) target process loads attacker DLL (module load) → (4) optional follow-on child activity or network egress from the target process.', '{Windows}', 'x-mitre-analytic--0fff438f-1aa9-4424-be94-a08b400adcb0', 'DET0433', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Correlation interval (e.g., 5–10 minutes) linking mavinject start → ProcessAccess → module load/network from the target process."}, {"field": "DLLPathRegex", "description": "Patterns for suspicious DLL locations (e.g., %TEMP%, Downloads, UNC shares) to reduce noise from legitimate injections."}, {"field": "TargetProcessAllowList", "description": "Common legitimate targets for App-V (if used) to suppress; flag unusual targets like browsers, LSASS, Winlogon, EDR processes."}, {"field": "MinGrantedAccessSet", "description": "Set of access rights that imply injection (VM_WRITE, VM_OPERATION, CREATE_THREAD). Tune for your EDR/sysmon formatting."}, {"field": "ParentProcessFilter", "description": "Legitimate parents starting mavinject (e.g., App-V services) vs. suspicious parents (Office, script hosts, browsers)."}, {"field": "ExternalIPAllowlist", "description": "Known enterprise update/CDN ranges to exclude when correlating post-injection network activity."}, {"field": "SignedToUnsignedTransition", "description": "Alerting when Microsoft-signed mavinject leads to loading unsigned DLLs in a target process."}]', '2026-05-01 15:26:34.552018');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (129, 'AN1176', 'Analytic 1176', 'Monitor pmset command executions altering sleep/hibernate/standby parameters. Unexpected modifications to /Library/Preferences/SystemConfiguration/com.apple.PowerManagement.plist or similar files should be correlated with process activity.', '{macOS}', 'x-mitre-analytic--101d4e7f-4282-4fea-89be-e17d97ca0b91', 'DET0417', '[{"name": "macos:unifiedlog", "channel": "Process creation events where command line = pmset with arguments affecting sleep, hibernatemode, displaysleep", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "write: File modification to com.apple.PowerManagement.plist or related system preference files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "AdminWhitelists", "description": "Allowlist expected pmset invocations by IT administrators for power policy enforcement."}]', '2026-05-01 15:26:34.553468');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (130, 'AN1960', 'Analytic 1960', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (131, 'AN1621', 'Analytic 1621', 'Detects enabling of reversible password encryption in Active Directory or Group Policy, suspicious PowerShell commands modifying AD user properties, and unusual account configuration changes correlated with policy modifications. Multi-event correlation links Group Policy edits, PowerShell command execution, and user account property changes to identify tampering with authentication encryption settings.', '{Windows}', 'x-mitre-analytic--105ca36e-c3e0-48c4-ada3-7f8c4aa4430f', 'DET0589', '[{"name": "WinEventLog:Security", "channel": "EventCode=4739", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "MonitoredOUs", "description": "Scope of Organizational Units where reversible encryption property monitoring is enabled."}, {"field": "TimeWindow", "description": "Time window in which to correlate Group Policy modification and subsequent user property changes."}, {"field": "SuspiciousCmdletList", "description": "List of PowerShell cmdlets to monitor for account configuration changes."}]', '2026-05-01 15:26:34.55615');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (132, 'AN0884', 'Analytic 0884', 'Abnormal invocation of diskutil or asr with destructive flags (eraseDisk, zeroDisk), or low-level IOKit calls that overwrite raw disk content. Detect correlation between elevated process execution and disk erase operations.', '{macOS}', 'x-mitre-analytic--1065ad69-8969-4ae0-9df6-dc7e7b1129c2', 'DET0316', '[{"name": "macos:unifiedlog", "channel": "diskutil eraseDisk/zeroDisk or asr restore with destructive flags", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "IOKit raw disk write activity targeting physical devices", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}]', '[{"field": "AdminToolWhitelist", "description": "Provisioning workflows may legitimately use diskutil/asr — whitelist by user or system context."}]', '2026-05-01 15:26:34.558068');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (902, 'AN0957', 'Analytic 0957', 'Unusual reuse of OAuth access tokens from different geographic regions, without full login events.', '{SaaS}', 'x-mitre-analytic--7fb5fe4f-ecd1-45a1-8a0f-dc913587e650', 'DET0338', '[{"name": "saas:googleworkspace", "channel": "access_token issued", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "saas:googleworkspace", "channel": "API access without user login", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "GeoIPDistanceThreshold", "description": "Minimum distance between token reuse events to trigger detection"}]', '2026-05-01 15:26:35.702027');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (133, 'AN0103', 'Analytic 0103', 'Adversary registers new devices to compromised user accounts to bypass MFA or conditional access policies via Azure Entra ID, Okta, or Duo self-enrollment portals.', '{"Identity Provider"}', 'x-mitre-analytic--108a10d2-4a9e-4c11-8a6f-42c8b60f0f52', 'DET0036', '[{"name": "azure:audit", "channel": "Operation IN (\"Add device\", \"Add registered users to device\", \"Add registered owner to device\")", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "ApplicationLog:EntraIDPortal", "channel": "DeviceRegistration events", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "azure:audit", "channel": "New device object creation", "x_mitre_data_component_ref": "x-mitre-data-component--18b236d8-7224-488f-9d2f-50076a0f653a"}]', '[{"field": "ActorUserPrincipalName", "description": "Define expected admin users to exclude known enrollment behavior"}, {"field": "IP Address", "description": "Scope internal vs. external device enrollment sources"}, {"field": "TimeWindow", "description": "Adjust for expected hours of legitimate self-enrollment"}]', '2026-05-01 15:26:34.559862');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (134, 'AN0396', 'Analytic 0396', 'Process creation involving suspicious delays (e.g., Sleep, ping -n loops, WaitForSingleObject), followed by sensitive system access or lateral movement behaviors.', '{Windows}', 'x-mitre-analytic--10c89810-d298-42d6-80dd-1228e737e33f', 'DET0141', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "SleepDurationThreshold", "description": "Defines maximum allowable sleep duration in milliseconds before triggering anomaly detection."}, {"field": "TimeBetweenExecutionAndNextStage", "description": "Temporal window between initial process and next stage (e.g., lateral movement or persistence), used to correlate dormant activity."}, {"field": "UserContext", "description": "Whether the activity occurs in SYSTEM or user context may affect legitimacy scoring."}]', '2026-05-01 15:26:34.561327');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (135, 'AN0466', 'Analytic 0466', 'Detects adversary behavior where the command-line arguments of a running process are overwritten in memory to spoof the process name, typically replacing it with a benign or misleading string. The detection correlates unexpected null byte sequences, discrepancies between `/proc/<pid>/cmdline` and process ancestry, and suspicious memory writes shortly after process start.', '{Linux}', 'x-mitre-analytic--10d8886b-6cf6-45af-b187-04541e2ffaa4', 'DET0164', '[{"name": "auditd:SYSCALL", "channel": "execve, prctl, or ptrace activity affecting process memory or command-line arguments", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "ebpf:tracepoints", "channel": "Runtime memory overwrite of argv[] memory region", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "TimeWindow", "description": "Time threshold after process creation during which argv memory manipulation is expected to be rare; anomalies occurring outside this window may be more suspicious."}, {"field": "AllowedArgvMismatchPatterns", "description": "List of known legitimate processes where argv[0] mismatch is expected due to application logic or packaging quirks."}, {"field": "ParentExecutableTrustList", "description": "Trusted parent binaries allowed to spawn processes with altered command-line names."}]', '2026-05-01 15:26:34.563948');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (136, 'AN0904', 'Analytic 0904', 'Detects use of netstat, ss, lsof, or custom shell scripts to list current network connections. Often paired with privilege escalation or staging.', '{Linux}', 'x-mitre-analytic--10dcfce8-70df-4682-ab04-90279d7292f9', 'DET0320', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:cli", "channel": "command logging", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "UtilityNameList", "description": "List of binaries used for discovery (e.g., netstat, ss, lsof)."}, {"field": "UserContextScope", "description": "Limit detection to non-administrative or service accounts performing enumeration."}, {"field": "ExecutionFrequencyThreshold", "description": "Unusual number of executions within a short time window."}]', '2026-05-01 15:26:34.565201');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (137, 'AN0081', 'Analytic 0081', 'User-initiated processes generating sustained outbound traffic over common or non-standard ports, often outside business hours, potentially linked to scanning or proxyjacking. Includes curl, wget, masscan, or proxy clients.', '{Linux}', 'x-mitre-analytic--10e9d109-0a17-41cd-9d0b-67c679bc94b7', 'DET0028', '[{"name": "auditd:SYSCALL", "channel": "execve calls with high-frequency or known bandwidth-intensive tools", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "large outbound data flows or long-duration connections", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ToolPattern", "description": "Can be tuned for specific bandwidth abuse tools (e.g., proxychains, 3proxy)."}, {"field": "TrafficRateThreshold", "description": "Baseline deviation thresholds must be environment-specific."}]', '2026-05-01 15:26:34.566511');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (138, 'AN0602', 'Analytic 0602', 'High-frequency file write operations using uncommon extensions, followed by ransom note creation, registry tampering, or shadow copy deletion. Often uses CLI tools like vssadmin, wbadmin, cipher, or PowerShell.', '{Windows}', 'x-mitre-analytic--1155df11-eee4-4fdf-a354-15eda0e90d4c', 'DET0215', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "FileExtension", "description": "Non-standard or randomly generated file extensions may indicate encrypted content."}, {"field": "TargetFolder", "description": "Focus on user document folders, network shares, or system paths like %System32%."}, {"field": "TimeWindow", "description": "Correlate rapid writes and renames within seconds across high file count."}, {"field": "CommandLine", "description": "Flag common ransomware tools or functions (vssadmin delete shadows /all /quiet)."}]', '2026-05-01 15:26:34.56779');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (139, 'AN0549', 'Analytic 0549', 'Detects MFA bypass attempts by modifying tenant-wide authentication policies or excluding high-value accounts from MFA enforcement.', '{"Office Suite"}', 'x-mitre-analytic--1193139d-0032-4d0b-88f1-c140abe2c964', 'DET0190', '[{"name": "m365:unified", "channel": "Set-CsOnlineUser or UpdateAuthPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MonitoredPolicies", "description": "Specific tenant or suite policies tied to MFA enforcement."}]', '2026-05-01 15:26:34.568934');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (140, 'AN1119', 'Analytic 1119', 'Detection of cron-based or script-based recurring transfers where the same script, user, or destination reappears at predictable intervals.', '{Linux}', 'x-mitre-analytic--11ac52fe-f8e0-4748-9fbc-2f85c43ad506', 'DET0399', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:cron", "channel": "cron activity", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}, {"name": "NSM:Flow", "channel": "Outbound Connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ScriptPathRegex", "description": "Path patterns for shell scripts responsible for scheduled transfers"}, {"field": "CronIntervalThreshold", "description": "Minimum repetition frequency (e.g., 24h for daily jobs)"}, {"field": "ExfilUserContext", "description": "Suspicious or unexpected users launching scheduled transfers"}]', '2026-05-01 15:26:34.570094');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (141, 'AN0130', 'Analytic 0130', 'Detection focuses on processes that attempt to locate, access, or exfiltrate local Outlook data files (.pst/.ost) using file system access, native Windows utilities (e.g., PowerShell, WMI), or remote access tools with file browsing capabilities. The behavior chain includes directory enumeration, file access, optional compression or staging, and network transfer.', '{Windows}', 'x-mitre-analytic--11cd0577-97e6-4def-a86b-fe167ae4e33d', 'DET0047', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TargetFilePathPattern", "description": "Regex or wildcard patterns for sensitive Outlook file paths (.ost/.pst) depending on organizational deployment."}, {"field": "TimeWindow", "description": "Timeframe used to correlate related file access, process creation, and exfiltration events."}, {"field": "UserContext", "description": "Limit detection to user accounts not normally interacting with Outlook file locations (e.g., service accounts, low-privileged users)."}, {"field": "ProcessAllowList", "description": "Filter known legitimate Outlook-accessing processes to reduce false positives."}]', '2026-05-01 15:26:34.571419');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (142, 'AN1125', 'Analytic 1125', 'Detects unusual outbound DNS traffic from ESXi hosts, often from shell scripts, custom daemons, or malicious VIBs interacting with external DNS infrastructure outside the management plane.', '{ESXi}', 'x-mitre-analytic--11d8dd9d-e8f3-40cd-b9fe-cc82b6c2e790', 'DET0400', '[{"name": "esxi:syslog", "channel": "/var/log/syslog.log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:FLow", "channel": "dns.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "OutboundDNSVolume", "description": "Threshold for data volume and frequency from ESXi IPs"}, {"field": "KnownGoodVIBs", "description": "Baseline known packages for allowlist comparison"}]', '2026-05-01 15:26:34.572758');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (143, 'AN1134', 'Analytic 1134', 'Correlates LNK file execution with embedded resource extraction or suspicious network activity following initial launch, often leading to payload delivery via disguised icons.', '{Windows}', 'x-mitre-analytic--11dd0dbf-e880-43d2-99f7-4b6bf9d821fa', 'DET0405', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ParentProcessName", "description": "Can be tuned to focus on common launcher processes like explorer.exe or winword.exe."}, {"field": "DestinationIP", "description": "Filtered to exclude known good domains and internal IPs to reduce false positives."}, {"field": "TimeWindow", "description": "Time between LNK execution and subsequent suspicious activity may vary based on adversary delay."}, {"field": "FileExtension", "description": "Could be used to focus on .lnk files only or track associated dropped payloads like .dat, .exe, etc."}]', '2026-05-01 15:26:34.574437');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (144, 'AN0975', 'Analytic 0975', 'Correlate registry modifications (e.g., UAC bypass registry keys), unusual parent-child process relationships (e.g., control.exe spawning cmd.exe), and unsigned elevated process executions with non-standard tokens or elevation flags.', '{Windows}', 'x-mitre-analytic--11f18771-dd49-45f7-8ef5-05d3426d82d5', 'DET0345', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "ElevatedProcessPath", "description": "Paths to monitor for unsigned or unexpected elevated binaries"}, {"field": "ParentProcessName", "description": "Parent-child execution chains that are suspicious in the local environment"}, {"field": "TimeWindow", "description": "Time between registry modification and elevated process spawn"}]', '2026-05-01 15:26:34.575774');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (145, 'AN0410', 'Analytic 0410', 'Detection of firewall ACL or rule base changes through CLI (e.g., no access-list, permit any any). Monitor configuration commits from unusual users or sessions.', '{"Network Devices"}', 'x-mitre-analytic--1216ae5e-bc5c-4672-a216-2706fb9ba3df', 'DET0145', '[{"name": "networkdevice:cli", "channel": "firewall disable commands or suspicious ACL modifications", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}]', '[{"field": "AuthorizedAdmins", "description": "List of approved admin accounts allowed to modify firewall ACLs."}]', '2026-05-01 15:26:34.576978');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (146, 'AN0982', 'Analytic 0982', 'Use of tools like xwd or import to generate screenshots, especially under non-GUI parent processes.', '{Linux}', 'x-mitre-analytic--121a5310-3157-47b1-925e-998767c0ec06', 'DET0346', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TerminalSession", "description": "Filter based on TTY sessions or remote terminal usage"}, {"field": "ExecutablePath", "description": "Match against known location of xwd/import binaries or renamed variants"}]', '2026-05-01 15:26:34.578485');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (147, 'AN1193', 'Analytic 1193', 'Processes accessing raw logical drives (e.g., \.\C:) to bypass file system protections or directly manipulate data structures.', '{Windows}', 'x-mitre-analytic--126a43e3-7b39-4312-ba15-aab0f7ce78f9', 'DET0426', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetObjectPattern", "description": "Regex pattern to detect access to raw disk volumes like `\\Device\\HarddiskVolume` or `\\.\\PhysicalDrive*`."}, {"field": "ParentProcess", "description": "Tune for known tools/scripts (e.g., powershell.exe, cmd.exe) often used in misuse scenarios."}, {"field": "TimeWindow", "description": "Correlate file access and creation across a short time window to avoid false positives."}]', '2026-05-01 15:26:34.57998');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (148, 'AN0203', 'Analytic 0203', 'Web session tokens reused in native Office apps (e.g., Outlook, Teams) without associated token refresh or login behavior on the endpoint.', '{"Office Suite"}', 'x-mitre-analytic--126cff4b-4ba7-4464-bfc8-4daabed5e05b', 'DET0074', '[{"name": "m365:unified", "channel": "UserLoggedIn", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "EndpointTokenSyncGap", "description": "Allowed delta between endpoint login and cloud token reuse"}]', '2026-05-01 15:26:34.581239');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (149, 'AN0372', 'Analytic 0372', 'Adversary-created named mutex using system APIs (e.g., CreateMutexW) followed by conditional process termination or alternate code path indicating malware avoiding reinfection.', '{Windows}', 'x-mitre-analytic--1282f497-ce04-4151-9bd0-4eedbf4530b6', 'DET0132', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "mutex_name_entropy_threshold", "description": "Filter out common benign mutex names; highlight suspicious high-entropy/dynamic names."}, {"field": "parent_process_path", "description": "Limit alerting to non-standard parent-child relationships indicative of malware staging or self-spawning."}, {"field": "TimeWindow", "description": "Correlate mutex creation + rapid process exit or lack of further activity within a short timeframe."}]', '2026-05-01 15:26:34.58243');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (150, 'AN1020', 'Analytic 1020', 'Suspicious processes (e.g., Tor clients, relays, unknown binaries) launch with sustained encrypted outbound traffic to known anonymity infrastructure (e.g., Tor, I2P), and may relay to additional internal systems via reverse proxying, ICMP tunneling, or socket forwarding.', '{Windows}', 'x-mitre-analytic--128315ea-6407-4c28-8528-209e799ad8e1', 'DET0359', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "dns:query", "channel": "Outbound resolution to hidden service domains (e.g., `.onion`)", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "DomainCategory", "description": "Can be tuned to `.onion`, I2P, or suspicious CDN domains."}, {"field": "ProcessParent", "description": "Detect known-good vs. abnormal launching binaries (e.g., mshta spawning Tor)."}, {"field": "ConnectionDuration", "description": "Threshold for persistent connections over known relay ports (e.g., 9050)."}]', '2026-05-01 15:26:34.583618');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (151, 'AN0178', 'Analytic 0178', 'Behavioral chain: (1) a user-facing app (browser/Office/email client) launches a URL or handles a link, then (2) the same process lineage makes an outbound connection to an untrusted domain/IP, (3) a file is downloaded or unpacked to a user-writable location shortly after the click. Optional enrichment: subsequent child execution by LOLBINs.', '{Windows}', 'x-mitre-analytic--12849ba4-39da-48c9-bf3d-c51a6cc3f85b', 'DET0066', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Suspicious URL patterns, uncommon TLDs, short-lived domains, URL shorteners; HTTP method GET/POST", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Correlation window (e.g., 15m) between link click / first egress / file write."}, {"field": "BrowserParents", "description": "Processes considered link sources: chrome.exe, msedge.exe, firefox.exe, winword.exe, outlook.exe, teams.exe."}, {"field": "UserPaths", "description": "User-writable directories to monitor (%USERPROFILE%\\Downloads, %TEMP%, %APPDATA%\\*, OneDrive caches)."}, {"field": "SuspiciousTLDs", "description": "High-risk TLD and domain list (e.g., .top .xyz .monster; newly observed domains/NOD)."}, {"field": "AllowedCDNs", "description": "Corporate CDNs/update hosts to reduce false positives."}]', '2026-05-01 15:26:34.58478');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (152, 'AN1085', 'Analytic 1085', 'A process outside of interactive shell context reads ~/.bash_history directly (e.g., using cat, less, grep), often shortly after privilege escalation or user switch (su/sudo). This may be followed by credential scanning in memory or file writes to new locations.', '{Linux}', 'x-mitre-analytic--12be6c5f-213a-464f-b780-ac06f20ab763', 'DET0385', '[{"name": "auditd:SYSCALL", "channel": "open/read access to ~/.bash_history", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:EXECVE", "channel": "cat|less|grep accessing .bash_history from a non-shell process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "write or create file after .bash_history access", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "UserContext", "description": "Filter by users with elevated privileges or service accounts"}, {"field": "TimeWindow", "description": "Correlate access to .bash_history within X seconds of user switch or privilege escalation"}, {"field": "ProcessNamePatterns", "description": "Add/remove CLI utilities used to read bash history"}]', '2026-05-01 15:26:34.585958');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1230, 'AN1278', 'Analytic 1278', 'Multiple failed authentications in unified logs (e.g., loginwindow or sshd)', '{macOS}', 'x-mitre-analytic--b31fc018-6fbc-4de7-9bf2-f545b5f8f0c2', 'DET0463', '[{"name": "macos:unifiedlog", "channel": "auth", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Scope of authentication failures (e.g., 10-15 mins)"}, {"field": "TargetUser", "description": "Filter known service or decoy accounts"}]', '2026-05-01 15:26:36.195341');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (153, 'AN0841', 'Analytic 0841', 'Execution of files originating from removable media after drive mount, with correlation to file write activity, autorun usage, or lateral spread via staged tools.', '{Windows}', 'x-mitre-analytic--12c748a0-3ce9-4fd2-8a65-f4362b69cafd', 'DET0301', '[{"name": "WinEventLog:System", "channel": "EventCode=1006", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Microsoft-Windows-Windows Defender/Operational", "channel": "Suspicious file execution on removable media path", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "DriveLetterMatch", "description": "Detect activity on mounted drives typically used by USB (e.g., E:, F:, G:). Tune based on enterprise usage."}, {"field": "FileExecutionWindow", "description": "Set timing threshold for execution shortly after drive mount (e.g., < 5 minutes)."}, {"field": "ParentProcess", "description": "Restrict detection to suspicious process lineage like explorer.exe, powershell.exe, or unsigned binaries."}, {"field": "FileEntropy", "description": "Use entropy thresholding to detect packed/obfuscated payloads dropped to removable media."}]', '2026-05-01 15:26:34.587171');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (154, 'AN0458', 'Analytic 0458', 'Chain: (1) cloud API calls that fetch tenant/organization password policy (e.g., AWS `GetAccountPasswordPolicy`, GCP/OCI equivalents or IAM settings reads); (2) within a short window, the same principal creates users, rotates creds, or changes auth settings. Use cloud audit logs.', '{IaaS}', 'x-mitre-analytic--12f9a28b-126d-48b1-bc93-5bc3c1635905', 'DET0161', '[{"name": "AWS:CloudTrail", "channel": "GetAccountPasswordPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "CloudReadOnlyApps", "description": "Approved security tooling principals that routinely read policy."}, {"field": "ApiClientIPAllowList", "description": "Corporate egress IPs for administrative API access."}]', '2026-05-01 15:26:34.588622');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (155, 'AN0794', 'Analytic 0794', 'Monitor Mail.app activity or unified logs for anomalous SMTP usage, including mismatches between display name and authenticated AppleID or Exchange credentials. Detect use of third-party mail utilities that attempt to send on behalf of corporate identities.', '{macOS}', 'x-mitre-analytic--1305f37f-8333-4d86-9714-340b66c65771', 'DET0286', '[{"name": "macos:unifiedlog", "channel": "Mail.app or third-party clients sending messages with mismatched From headers", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TrustedMailClients", "description": "Allowlist known third-party clients used for legitimate email activity."}]', '2026-05-01 15:26:34.590308');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (156, 'AN0959', 'Analytic 0959', 'Access token reuse to connect to SharePoint or Outlook APIs without interactive user context.', '{"Office Suite"}', 'x-mitre-analytic--1313533a-06c7-44ea-8d75-9a23d3ea23cc', 'DET0338', '[{"name": "m365:unified", "channel": "TokenIssued, FileAccessed", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}]', '[{"field": "UserAgentCheck", "description": "Tune to detect access from CLI agents or scripts rather than interactive browsers"}]', '2026-05-01 15:26:34.591923');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (157, 'AN0004', 'Analytic 0004', 'Detects osascript, curl, or custom binaries interacting with XMPP/MQTT brokers in unapproved destinations with encrypted payloads or frequent POST-like requests to broker URIs.', '{macOS}', 'x-mitre-analytic--131d3f89-e10d-4ac9-a9d0-fcb4e8e8760a', 'DET0002', '[{"name": "macos:unifiedlog", "channel": "log stream ''eventMessage contains pubsub or broker''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AppContextFilter", "description": "Applications not known to use pub/sub protocols"}, {"field": "URIPathRegex", "description": "Custom path patterns to message brokers over HTTPS"}]', '2026-05-01 15:26:34.593244');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (158, 'AN1420', 'Analytic 1420', 'Detects escalation via vulnerable setuid binaries or kernel modules, often chained with unusual access to /proc/kallsyms or /dev/kmem.', '{Linux}', 'x-mitre-analytic--1327b96f-73db-4a5e-8e71-e515fc030bf3', 'DET0514', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "ACCESS", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "auditd:SYSCALL", "channel": "dmesg", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "SetUIDBinaryList", "description": "Legitimate SUID binaries vary across distributions; false positives may arise."}, {"field": "TimeWindow", "description": "Allows chaining kernel module load with privilege spike or privilege-sensitive process activity."}, {"field": "EffectiveUIDThreshold", "description": "Default is uid=0, but environments may vary with containerized root-like accounts."}]', '2026-05-01 15:26:34.594481');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (159, 'AN0934', 'Analytic 0934', 'Shell utilities or scripts deleting `/etc/systemd/system/rescue.target`, `/etc/fstab` backups, or `/boot/efi` partitions; chattr used to block snapshot auto-recovery', '{Linux}', 'x-mitre-analytic--135452f6-c760-42a6-8a3f-d09c33f05369', 'DET0329', '[{"name": "auditd:SYSCALL", "channel": "chattr, rm, shred, dd run on recovery directories or partitions", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:CONFIG_CHANGE", "channel": "/etc/fstab, /etc/systemd/*", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "WatchedFilePaths", "description": "Modify to include specific OS backup configs or LVM snapshots"}, {"field": "ShellProcessUser", "description": "Restrict detection to root or sudo users"}]', '2026-05-01 15:26:34.595841');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (160, 'AN1525', 'Analytic 1525', 'Login attempt failures over SNMP, Telnet, or SSH interface, often reflected in logs or syslog events', '{"Network Devices"}', 'x-mitre-analytic--13556e3f-80f0-4aac-83f0-0d6c706e76ff', 'DET0551', '[{"name": "networkdevice:syslog", "channel": "login failed", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "InterfaceType", "description": "Specify monitoring of Telnet/SSH/SNMP for login activity"}, {"field": "FailedAttemptThreshold", "description": "How many failures in short succession should trigger alerting"}]', '2026-05-01 15:26:34.597063');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (161, 'AN0705', 'Analytic 0705', 'Monitor for use of native utilities such as wevtutil.exe or PowerShell cmdlets (Get-WinEvent, Get-EventLog) to enumerate or export logs. Unusual access to security or system event channels, especially by non-administrative users or processes, should be correlated with subsequent file export or network transfer activity.', '{Windows}', 'x-mitre-analytic--13810047-61f4-4cd0-aeda-6727d652da90', 'DET0255', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "WhitelistedAdminTools", "description": "Expected log management scripts executed by administrators should be excluded from alerts."}, {"field": "TimeWindow", "description": "Correlate enumeration attempts with file export or network transfer within a defined timeframe."}]', '2026-05-01 15:26:34.598223');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (162, 'AN0837', 'Analytic 0837', 'ESXi hypervisor permission modification behavioral chain: (1) SSH access to ESXi host, (2) chmod/chown execution on VMFS datastore files or system configuration, (3) Modification of VM configuration files (.vmx) or virtual disk permissions, (4) Hostd service log correlation, (5) vCenter permission change events if centrally managed', '{ESXi}', 'x-mitre-analytic--13a1653f-3d4e-4a4f-9619-f8e8a97ec60d', 'DET0299', '[{"name": "esxi:shell", "channel": "shell command execution for chmod, chown, or file permission modification on VMFS or system files", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:hostd", "channel": "host daemon events related to file or VM permission changes", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "esxi:vpxd", "channel": "permission change operations on datastores or VMs", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}]', '[{"field": "AuthorizedSSHUsers", "description": "ESXi user accounts authorized for shell access and file system operations"}, {"field": "CriticalVMFSPaths", "description": "VMFS datastore paths requiring permission change monitoring"}, {"field": "ShellAccessTimeWindow", "description": "Time correlation window for linking SSH access with permission modifications"}, {"field": "vCenterIntegrationScope", "description": "Scope of vCenter audit event correlation with ESXi host activities"}]', '2026-05-01 15:26:34.5995');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (163, 'AN1094', 'Analytic 1094', 'Detects a multi-event behavior chain involving UAC bypass attempts via known auto-elevated binaries (e.g., eventvwr.exe, sdclt.exe), unauthorized Registry changes to UAC-related keys, and anomalous process execution with elevated privileges but lacking standard parent-child lineage. Suspicious patterns include invocation of auto-elevated COM objects or manipulation of isolatedCommand Registry entries without consent prompts.', '{Windows}', 'x-mitre-analytic--13a875c4-87d2-448e-a46e-970e1f9ad5da', 'DET0388', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TimeWindow", "description": "Correlate registry tampering and elevation within a tunable time window (e.g., 30 seconds) to reduce noise from benign admin activity."}, {"field": "ElevatedProcessNameList", "description": "Tunable list of suspicious elevated binaries (e.g., sdclt.exe, eventvwr.exe, computerdefaults.exe) known to support UAC bypass."}, {"field": "ParentProcessAnomalyThreshold", "description": "Define logic for parent-child mismatch (e.g., non-elevated process spawning auto-elevated one) to flag uncommon elevation paths."}]', '2026-05-01 15:26:34.600727');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (164, 'AN0164', 'Analytic 0164', 'Detect manipulation of system or application files in `/Library`, `/System`, or user data directories using FSEvents and Unified Logs. Identify anomalous process execution modifying plist files, structured data, or logs outside expected update cycles.', '{macOS}', 'x-mitre-analytic--13f8d339-8239-4d84-adf2-1abf1a0f3d5d', 'DET0059', '[{"name": "macos:unifiedlog", "channel": "Anomalous plist modifications or sensitive file overwrites by non-standard processes", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:osquery", "channel": "open, execve: Unexpected processes accessing or modifying critical files", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "AllowedPlistEditors", "description": "Whitelisted processes authorized to modify plist or configuration files."}, {"field": "FileIntegrityBaseline", "description": "Baseline hash values for key files to support integrity validation."}]', '2026-05-01 15:26:34.603319');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (165, 'AN0284', 'Analytic 0284', 'Monitors for TCC-bypassing or unauthorized access to input services like IOHIDSystem or Quartz Event Services used in keylogging or screen monitoring.', '{macOS}', 'x-mitre-analytic--13f8fd10-3982-4a10-85c1-4641712c7286', 'DET0102', '[{"name": "macos:unifiedlog", "channel": "subsystem=com.apple.TCC", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "macos:osquery", "channel": "launchd or process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "Service", "description": "com.apple.accessibility, com.apple.quartz, etc. depending on the API path used"}, {"field": "ParentProcess", "description": "Unusual parent/child pairings can indicate malicious injection"}]', '2026-05-01 15:26:34.604746');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (166, 'AN1522', 'Analytic 1522', 'Repeated failed SSH login attempts followed by a possible success from the same remote host', '{Linux}', 'x-mitre-analytic--14390641-6cba-4351-a488-bf97c6eee8a7', 'DET0551', '[{"name": "linux:syslog", "channel": "sshd[pid]: Failed password", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "PortScope", "description": "Can be tuned to non-standard ports if SSH is moved from default"}, {"field": "UserScope", "description": "Filter high-value or restricted users (e.g., root, service)"}, {"field": "AttemptThreshold", "description": "Number of consecutive failures before flagging (e.g., >5 in 2 minutes)"}]', '2026-05-01 15:26:34.606314');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (167, 'AN1216', 'Analytic 1216', 'Detects the relocation of malicious executables via copy/move actions across suspicious folders (e.g., from Downloads to System32), followed by deletion of the original source or renaming to blend into legitimate binaries.', '{Windows}', 'x-mitre-analytic--143f3057-237e-427f-911a-2aa7d64721f0', 'DET0439', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=23", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "SuspiciousTargetPathRegex", "description": "Patterns like \\Windows\\*, \\System32\\*, or temp+execution directories"}, {"field": "TimeWindow", "description": "Correlate copy+rename+delete chains within 5-minute window"}, {"field": "FileExtensionFilter", "description": "Limit to .exe, .dll, .js, .bat unless context suggests otherwise"}]', '2026-05-01 15:26:34.607973');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (168, 'AN1017', 'Analytic 1017', 'Execution of ping, traceroute, or network utility tools to external destinations; may include `scutil` or system_profiler.', '{macOS}', 'x-mitre-analytic--1443f662-d249-4458-b8fe-2c2da7b64569', 'DET0357', '[{"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExecutionFrequency", "description": "Rare use of ICMP utilities may be tuned based on user/host baselines"}, {"field": "EnrichmentLevel", "description": "Tune data joins with parent process and user activity context"}]', '2026-05-01 15:26:34.609445');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (169, 'AN0676', 'Analytic 0676', 'Unusual database command-line access (e.g., `psql`, `mysql`, `mongo`) from non-admin users, occurring outside typical automation windows or without known service context. Often followed by data dumps to .sql/.csv files or outbound data transfers. Defender sees CLI tools launched interactively or by unusual parent processes, file writes to dump-like filenames, and external connections shortly after.', '{Linux}', 'x-mitre-analytic--147c0305-abff-4bc3-ae2a-acd69d0b87fd', 'DET0242', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of CLI tools like psql, mysql, mongo, sqlite3", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PATH", "channel": "Creation of files with extensions .sql, .csv, .sqlite, especially in user directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "http::post: Outbound HTTP POST from host shortly after DB export activity", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AllowedDBClients", "description": "List of user or automation accounts expected to use database clients"}, {"field": "DumpFilePattern", "description": "Filename patterns used to identify data dumps (e.g., *.sql, backup_*.csv)"}, {"field": "TimeWindow", "description": "Time threshold for correlating execution, file write, and outbound transfer"}]', '2026-05-01 15:26:34.610928');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (170, 'AN0195', 'Analytic 0195', 'Detects inbound SCP, rsync, or NFS mounts from remote systems followed by aggregation of files into known staging paths like /mnt/staging or /var/tmp.', '{Linux}', 'x-mitre-analytic--14ac0f26-e5db-42da-b730-9e115027f8e9', 'DET0071', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "SSH logins or scp activity", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "RemoteHosts", "description": "Expected inbound transfer hosts to filter normal activity from staging behavior"}, {"field": "MountTargets", "description": "Directory destinations used as centralized locations"}, {"field": "TransferVolumeThreshold", "description": "Threshold of transferred files or data volume over time"}]', '2026-05-01 15:26:34.612624');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (171, 'AN1006', 'Analytic 1006', 'Unexpected inbound or outbound VNC/SSH/Screen Sharing connections from external sources → repeated failed logins followed by success → remote interactive sessions or abnormal file transfers.', '{macOS}', 'x-mitre-analytic--14f4930e-a2a5-45ae-9552-837c0a35e06b', 'DET0354', '[{"name": "macos:unifiedlog", "channel": "Remote login (ssh) or screen sharing authentication attempts", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "macos:unifiedlog", "channel": "Inbound connections to VNC/SSH ports", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "PF:Logs", "channel": "External traffic to remote access services", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "KnownVNCServers", "description": "List of approved VNC/SSH sources."}, {"field": "TimeWindow", "description": "Time correlation between failed attempts and success."}]', '2026-05-01 15:26:34.613825');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (172, 'AN0367', 'Analytic 0367', 'Detects unusual outbound file transfer behavior using protocols like FTP, SMB, SMTP, or DNS, involving non-standard processes, off-hour activity, or uncommonly high volume.', '{Windows}', 'x-mitre-analytic--1543bc4a-7614-417a-85b9-d67e3da0350c', 'DET0131', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DataVolumeThresholdMB", "description": "Set threshold for outbound volume (e.g., >50MB in a single connection)."}, {"field": "ProtocolAllowList", "description": "Allow-listed protocols in use for specific machines or users (e.g., FTP allowed for backups)."}, {"field": "TimeWindow", "description": "Define allowed time-of-day windows (e.g., flag after-hours file transfer)."}, {"field": "ParentProcessAnomaly", "description": "Identify anomalous parent-child process relationships (e.g., `winword.exe` spawning `ftp.exe`)."}]', '2026-05-01 15:26:34.615054');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (173, 'AN0765', 'Analytic 0765', 'Correlates creation/modification of systemd service files or /etc/init.d scripts with outlier process behavior during boot', '{Linux}', 'x-mitre-analytic--156387d6-9b9a-49f8-834a-cf3cd5ede09c', 'DET0274', '[{"name": "auditd:SYSCALL", "channel": "creat", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "Execution of binaries located in /etc/init.d/ or systemd service paths", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "FilePath", "description": "Organizations may use different init systems or custom startup paths"}, {"field": "UserContext", "description": "Autostart scripts should run as root or system users; deviations are suspect"}]', '2026-05-01 15:26:34.616218');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (176, 'AN0045', 'Analytic 0045', 'Detects unusual command executions and service modifications that indicate self-patching or disabling of vulnerable services post-compromise. Defenders should monitor for service stop commands, suspicious process termination, and execution of binaries or scripts aligned with known patching or service management tools outside of expected admin contexts.', '{Windows}', 'x-mitre-analytic--16e57a41-f305-4aa7-9125-15272052419e', 'DET0015', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=5", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "ServiceList", "description": "Tunable list of critical or vulnerable services that defenders want to monitor for unexpected disabling."}, {"field": "TimeWindow", "description": "Defines correlation window (e.g., 5–15 minutes) between suspicious command execution and subsequent process termination."}]', '2026-05-01 15:26:34.619614');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (177, 'AN1170', 'Analytic 1170', 'Detects usage of FTP, SCP, or TFTP by non-interactive shells or automation scripts transferring large data volumes to untrusted IPs.', '{Linux}', 'x-mitre-analytic--170e84e2-fa22-4e8c-b2f3-3cafc0d96d7e', 'DET0416', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "ftp.log, conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TransferSizeThreshold", "description": "Bytes sent in FTP upload or SCP push"}, {"field": "CommandLinePatternMatch", "description": "e.g., scp -r /var/log/* or ftp upload scripts"}]', '2026-05-01 15:26:34.620802');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (178, 'AN0568', 'Analytic 0568', 'A non-standard process (or script-hosted process) loads camera/video-capture libraries (e.g., avicap32.dll, mf.dll, ksproxy.ax), opens the Camera Frame Server/device, writes video/image artifacts (e.g., .mp4/.avi/.yuv) to unusual locations, and optionally initiates outbound transfer shortly after.', '{Windows}', 'x-mitre-analytic--171803bb-8aa7-42df-861a-18d6d694f909', 'DET0197', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:Microsoft-Windows-Windows Camera Frame Server/Operational", "channel": "Process session start/stop events for camera pipeline by unexpected executables", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "TimeWindow", "description": "Correlation window (e.g., 0–20 minutes) between device access, file creation, and egress."}, {"field": "AllowedProcesses", "description": "Known legitimate camera consumers (e.g., Teams.exe, zoom.exe, obs64.exe) to suppress."}, {"field": "VideoExtensions", "description": "List of extensions to flag (.mp4, .avi, .mov, .yuv, .mkv, .h264) – tune for your estate."}, {"field": "RarePathRegex", "description": "Regex for unusual storage locations (e.g., %TEMP%\\*, C:\\Windows\\Tasks\\*, user profile hidden dirs)."}, {"field": "MinFileSizeMB", "description": "Minimum size to reduce FP from thumbnails/snapshots."}, {"field": "ParentProcessAllowList", "description": "Service/agent parents permitted to broker camera access."}]', '2026-05-01 15:26:34.622177');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (179, 'AN0219', 'Analytic 0219', 'Adversary sends crafted HTTP/S (or other service) input to an Internet-facing app (IIS/ASP.NET, API, device portal). Chain: (1) abnormal request patterns to public endpoint → (2) elevated 4xx/5xx or unusual methods/paths → (3) server process (w3wp.exe/other service) spawns shell/LOLbins or loads non-standard modules → (4) optional outbound callback from the host/container.', '{Windows}', 'x-mitre-analytic--17290910-5b25-477a-a0c0-c2661ff2585e', 'DET0080', '[{"name": "ApplicationLog:IIS", "channel": "IIS W3C logs in C:\\inetpub\\logs\\LogFiles\\W3SVC* (spikes in 5xx, RCE/SQLi/path traversal/JNDI patterns)", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "PublicVIPs", "description": "List of public IPs/hostnames that front apps; used to scope web log and Zeek/proxy data."}, {"field": "SuspiciousPatterns", "description": "Regex set for exploit-like inputs (../, union select, cmd=, ${jndi:, rO0AB (Java serialization), %00, ${env:}, ${${::-j}ndi})."}, {"field": "ErrorRateThreshold", "description": "Spike threshold for HTTP status 5xx/4xx per client or URI (e.g., >5 in 5m)."}, {"field": "TimeWindow", "description": "Correlation horizon between request, error, process spawn, and egress (e.g., 15 minutes)."}, {"field": "AllowedChildList", "description": "Known child processes of app pools (e.g., msbuild.exe in CI) to reduce false positives."}]', '2026-05-01 15:26:34.624085');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (180, 'AN0394', 'Analytic 0394', 'Detects removal of adversary artifacts via `rm`, `unlink`, or secure tools, with focus on shell sessions, temp files, and modified LaunchAgents or system directories.', '{macOS}', 'x-mitre-analytic--175bf607-fca6-4555-a30b-3d6cd4cfe876', 'DET0140', '[{"name": "fs:fsusage", "channel": "unlink, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "FilePathRegex", "description": "Focus on LaunchAgents, /tmp/, or user folders."}, {"field": "ToolUsageAnomaly", "description": "Detecting use of unfamiliar tools by common users."}]', '2026-05-01 15:26:34.625847');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (181, 'AN2026', 'Analytic 2026', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on behaviors relating to the use of exploits (i.e. [Exploit Public-Facing Application](https://attack.mitre.org/techniques/T1190), [Exploitation for Client Execution](https://attack.mitre.org/techniques/T1203), [Exploitation for Privilege Escalation](https://attack.mitre.org/techniques/T1068), [Exploitation for Stealth](https://attack.mitre.org/techniques/T1211), [Exploitation for Credential Access](https://attack.mitre.org/techniques/T1212), [Exploitation of Remote Services](https://attack.mitre.org/techniques/T1210), and [Application or System Exploitation](https://attack.mitre.org/techniques/T1499/004)).', '{PRE}', 'x-mitre-analytic--1762aa55-010b-4a26-b439-7afcfcc5613d', 'DET0894', NULL, NULL, '2026-05-01 15:26:34.627239');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (182, 'AN1031', 'Analytic 1031', 'Detects adversarial abuse of WMI to execute local or remote commands via WMIC, PowerShell, or COM API through a multi-event chain: process creation, command execution, and corresponding network connection if remote.', '{Windows}', 'x-mitre-analytic--17687fa0-bfbf-4ff2-9eb0-520538e6af31', 'DET0364', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:WMI", "channel": "EventCode=5857, 5858, 5860, 5861", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}]', '[{"field": "WMIQueryScope", "description": "Restrict detection scope to suspicious WMI namespaces like `\\root\\cimv2`, `\\root\\subscription`."}, {"field": "TimeWindow", "description": "Set maximum allowable time window to correlate WMI process creation and remote connections."}, {"field": "UserContext", "description": "Tune based on interactive vs. system-level execution (e.g., via SYSTEM or low-privileged users)."}, {"field": "RemoteDestinationThreshold", "description": "Number of unique remote hosts contacted using WMI within a time window."}, {"field": "SuspiciousCommandPatterns", "description": "Regex patterns to identify adversary-like usage (e.g., `wmic process call`, `powershell Invoke-WmiMethod`)."}]', '2026-05-01 15:26:34.629363');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (183, 'AN1514', 'Analytic 1514', 'Abnormal API calls from user accounts invoking file upload endpoints outside normal baselines (M365, Google Drive, Box). Defender perspective: monitor unified audit logs for elevated frequency of Upload, Create, or Copy operations from compromised accounts.', '{SaaS}', 'x-mitre-analytic--177bb119-93cc-4319-b9a7-e8d308d958c4', 'DET0548', '[{"name": "m365:unified", "channel": "FileUploaded or FileCopied events", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:box", "channel": "API calls exceeding baseline thresholds", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "APICallThreshold", "description": "Maximum number of API calls per user/session before triggering alert."}, {"field": "UserBaselineProfiles", "description": "Baseline normal data transfer patterns by user/role."}]', '2026-05-01 15:26:34.630977');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (184, 'AN0329', 'Analytic 0329', 'Detects exploitation targeting ESXi/vCenter by correlating attempts to reach known exploitable endpoints (OpenSLP 427, CIM 5989, Hostd/Vpxa HTTPS 443, ESXi SOAP) with vmkernel/hostd crashes, unexpected hostd/vpxa restarts, or new reverse/outbound connections from ESXi host/vCenter to internal assets.', '{ESXi}', 'x-mitre-analytic--17b82342-cc75-4dcd-ad98-f313cd2a2b69', 'DET0118', '[{"name": "esxi:hostd", "channel": "Keywords: ''Backtrace'',''Signal 11'',''PANIC'',''hostd restarted'',''assert'' or ''Service terminated unexpectedly'' in /var/log/hostd.log, /var/log/vmkernel.log, /var/log/syslog.log.", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Inbound to tcp/427 (OpenSLP), tcp/443 (vSphere APIs), tcp/902, tcp/5989 followed by new unexpected outbound sessions from the ESXi/vCenter host.", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ESXiServicePorts", "description": "427, 443, 902, 5989; modify per version/hardening."}, {"field": "MgmtCIDRs", "description": "Legit management networks for vCenter/ESXi."}, {"field": "RestartKeywords", "description": "Crash/restart patterns to match in logs."}]', '2026-05-01 15:26:34.632451');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (185, 'AN1437', 'Analytic 1437', 'Malicious VBA macros embedded in base templates like Normal.dotm or Personal.xlsb are automatically loaded and executed at startup. Template path may be hijacked to load a remote or attacker-controlled template via GlobalDotName registry setting.', '{"Office Suite"}', 'x-mitre-analytic--17bc7c97-7322-4619-84c5-50e45aa6627d', 'DET0519', '[{"name": "m365:unified", "channel": "Set-Mailbox, Set-MailboxPolicy, Set-TrustedLocation", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TemplateSource", "description": "Macros may be embedded in local user templates or retrieved from shared network paths"}, {"field": "MacroSecurityLevel", "description": "Macro execution policy (disabled, warn, enabled) varies by tenant or user configuration"}]', '2026-05-01 15:26:34.633756');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (186, 'AN0855', 'Analytic 0855', 'Defender observes configuration changes on firewall/network appliance involving rule creation, modification, or deletion from abnormal management IPs or non-console channels (e.g., remote CLI, API). These are often correlated with a spike in previously blocked outbound traffic, unexpected allow-all rules, or bulk rule deletions. Behavior often follows unauthorized login, privilege escalation, or API abuse.', '{"Network Devices"}', 'x-mitre-analytic--17ce541a-23fa-4b33-affc-c6ba906e9956', 'DET0306', '[{"name": "networkdevice:Firewall", "channel": "update_rule: Access control or NAT rule modified or disabled outside maintenance window", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"name": "networkdevice:Firewall", "channel": "Login from untrusted IP, or new admin account accessing firewall console/API", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "networkdevice:Firewall", "channel": "Audit trail or CLI/API access indicating commands like no access-list, delete rule-set, clear config", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "Outbound traffic spike through formerly blocked ports/subnets following config change", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TrustedAdminIPs", "description": "Allowlisted IPs/subnets where administrative access is expected (e.g., jump box, VPN mgmt)"}, {"field": "ConfigChangeWindow", "description": "Expected maintenance window (e.g., 02:00–04:00 UTC) to filter benign changes"}, {"field": "RuleScopeThreshold", "description": "Number of rules affected or port ranges modified to determine severity"}, {"field": "NewUserPrivilegeThreshold", "description": "Flag new users making changes without observed privilege elevation path"}]', '2026-05-01 15:26:34.635221');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (187, 'AN0223', 'Analytic 0223', 'Adversary targets cloud-hosted public endpoints. Chain: (1) ALB/ELB/Cloud LB logs show exploit-like inputs or error spikes → (2) workload spawns shell or reaches metadata API → (3) egress to new external hosts.', '{IaaS}', 'x-mitre-analytic--17f9487f-711d-4f28-9de8-209ae39d33d2', 'DET0080', '[{"name": "ALB:HTTPLogs", "channel": "AWS ALB/ELB/GCP/Azure Application Gateway HTTP logs with unusual methods, long URIs, serialized payloads, 4xx/5xx bursts", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "AWS:VPCFlowLogs", "channel": "VPC/NSG flow logs for pod/instance egress to Internet or metadata", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "LBProjects", "description": "Cloud accounts/subscriptions/regions to include."}, {"field": "ErrorBurst", "description": "5xx/4xx per client threshold."}]', '2026-05-01 15:26:34.636545');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (188, 'AN0782', 'Analytic 0782', 'Monitors for compression tool usage (e.g., 7zip, WinRAR, MakeCab) that follows or precedes file modification, suspicious file types (e.g., .exe, .dll) being compressed, or dropped from self-extracting archives followed by immediate execution.', '{Windows}', 'x-mitre-analytic--18253101-bce9-453e-ab03-603bbd174552', 'DET0281', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "CompressedFileType", "description": "Zip, .rar, .cab, .gz – tune based on expected legitimate use of compression in environment"}, {"field": "SFXExecutionDelay", "description": "Expected time between archive unpacking and first execution – short delays are suspicious"}, {"field": "UserContext", "description": "Restrict detection to non-admin or interactive users if excessive FPs from sys admin activity"}]', '2026-05-01 15:26:34.637795');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (189, 'AN0963', 'Analytic 0963', 'User pastes a multi-line or one-liner into a terminal (bash/zsh) that downloads/decodes and executes content. Chain: terminal exec of curl/wget/bash/sh with pipe to interpreter or base64-decode → transient file under /tmp|~/.cache → immediate outbound egress.', '{Linux}', 'x-mitre-analytic--1895e723-dcfb-45d4-80fc-aaa0c3963cc9', 'DET0340', '[{"name": "auditd:SYSCALL", "channel": "execve: exe in (/usr/bin/bash,/usr/bin/sh,/usr/bin/zsh,/usr/bin/python*) AND cmdline matches ''(curl|wget).*(\\||\\|\\s*sh|bash)|base64\\s*-d|python\\s*-c''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open: File creation under /tmp, /var/tmp, ~/.cache with executable bit or shell shebang", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "New egress to Internet by the same UID/host shortly after terminal exec", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TerminalProcessNames", "description": "Gui/tty terminals to monitor (gnome-terminal, konsole, iTerm2, tmux)."}, {"field": "RiskyFilePaths", "description": "Temp/cache paths to watch for first-stage drops."}, {"field": "AnomalousUserSet", "description": "Users who should never run curl/wget or compilers."}, {"field": "TimeWindow", "description": "Exec→file→egress correlation window (e.g., 10 minutes)."}]', '2026-05-01 15:26:34.639391');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (190, 'AN1641', 'Analytic 1641', 'Detection of suspicious access to password manager processes (KeePass, 1Password, LastPass, Bitwarden) through abnormal process injection, memory reads, or command-line usage of vault-related DLLs. Correlates process creation with OS API calls and file access to vault databases (.kdbx, .opvault, .ldb).', '{Windows}', 'x-mitre-analytic--18ab8a54-68bc-4d43-884d-2b9284eb723e', 'DET0597', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "PasswordManagerBinaries", "description": "List of monitored binaries and file formats for password managers in use (e.g., KeePass, 1Password, Bitwarden, LastPass)."}, {"field": "TimeWindow", "description": "Window to correlate process creation, API access, and file reads indicative of credential extraction."}, {"field": "UserContext", "description": "Filter for administrative accounts vs. expected users of password managers."}]', '2026-05-01 15:26:34.641106');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (191, 'AN1417', 'Analytic 1417', 'Detects adversary behavior accessing Windows cached domain credential files using tools like Mimikatz, reg.exe, or PowerShell, often combined with registry exports or LSASS memory scraping.', '{Windows}', 'x-mitre-analytic--18ba26d6-08e0-4370-8ef0-b2dd73bfe0b3', 'DET0513', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "TargetFilename", "description": "Location of cached credential files may vary with OS version or custom registry hive exports."}, {"field": "CommandLine", "description": "Patterns for reg save, secretsdump, or PowerShell dumping tools may be tuned to org-specific tooling."}, {"field": "TimeWindow", "description": "Temporal correlation window between process execution and registry/file access."}]', '2026-05-01 15:26:34.642562');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (192, 'AN0731', 'Analytic 0731', 'Analyze ESXi syslogs for management agents or VMs making outbound connections to dynamically calculated ports derived from DNS responses. Cross-check with VM traffic baselines to identify anomalies.', '{ESXi}', 'x-mitre-analytic--18c20664-b820-4a14-a7bf-5a75ac2fae92', 'DET0262', '[{"name": "esxi:syslog", "channel": "DNS resolution events leading to outbound traffic on unexpected ports", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ManagementPlaneIPs", "description": "Known trusted ESXi management plane IPs to exclude from alerts"}, {"field": "DomainReputationFeed", "description": "Integrate external feeds for reputation context on DNS-derived domains"}]', '2026-05-01 15:26:34.643943');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (193, 'AN0833', 'Analytic 0833', 'Detects invocation of macOS-native archiving utilities (zip, ditto, hdiutil) or openssl used for encryption. Correlates execution with archive or encrypted file creation (.zip, .dmg, .tar.gz) in user or temporary directories. Identifies anomalous use of archiving commands by Office applications or daemons.', '{macOS}', 'x-mitre-analytic--18cf5cf7-f46b-4258-a0aa-503881c9c88e', 'DET0298', '[{"name": "macos:unifiedlog", "channel": "Execution of zip, ditto, hdiutil, or openssl by processes not normally associated with archiving", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Creation of .zip, .dmg, .tar.gz files in /Users, /tmp, or application directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AllowedArchivers", "description": "Business-approved applications permitted to create archives (e.g., backup agents)."}, {"field": "UserContext", "description": "Flag archiving under privileged or service accounts as higher risk."}, {"field": "PayloadEntropyThreshold", "description": "Entropy threshold for detecting encrypted archives versus normal compression."}]', '2026-05-01 15:26:34.645197');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (194, 'AN1595', 'Analytic 1595', 'Monitor for suspicious usage of driver enumeration utilities (driverquery.exe) or API calls such as EnumDeviceDrivers(). Registry queries against HKLM\SYSTEM\CurrentControlSet\Services and HardwareProfiles that are abnormal may also indicate attempts to discover installed drivers and services. Correlate command execution, process creation, and registry access to build a behavioral chain of driver discovery.', '{Windows}', 'x-mitre-analytic--18e81e76-bae3-44c8-b573-dfd3564a00ad', 'DET0579', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "AllowedUtilities", "description": "Whitelist expected administrative usage of driverquery.exe or other enumeration utilities."}, {"field": "TimeWindow", "description": "Correlation window between process creation and registry queries to identify suspicious chaining of events."}]', '2026-05-01 15:26:34.64705');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (195, 'AN0652', 'Analytic 0652', 'Unusual use of steganographic or media processing binaries (e.g., `steghide`, `ffmpeg`, `imagemagick`) followed by outbound communication to external IPs with high data output and media MIME types.', '{Linux}', 'x-mitre-analytic--191d5ea7-ff08-4433-ba1b-1c0ed755ca67', 'DET0235', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Captured File Content", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "Observed File Transfers", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "ToolNameMatch", "description": "Specify which binaries to monitor (e.g., steghide, outguess)."}, {"field": "OutboundTrafficPattern", "description": "Adjust based on known normal file upload services."}]', '2026-05-01 15:26:34.648366');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (196, 'AN1940', 'Analytic 1940', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on behaviors relating to the potential use of exploits for vulnerabilities (i.e. [Exploit Public-Facing Application](https://attack.mitre.org/techniques/T1190), [Exploitation for Client Execution](https://attack.mitre.org/techniques/T1203), [Exploitation for Privilege Escalation](https://attack.mitre.org/techniques/T1068), [Exploitation for Stealth](https://attack.mitre.org/techniques/T1211), [Exploitation for Credential Access](https://attack.mitre.org/techniques/T1212), [Exploitation of Remote Services](https://attack.mitre.org/techniques/T1210), and [Application or System Exploitation](https://attack.mitre.org/techniques/T1499/004)).', '{PRE}', 'x-mitre-analytic--193167de-400a-4ea3-a8db-93e4bf628068', 'DET0808', NULL, NULL, '2026-05-01 15:26:34.649619');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (197, 'AN1356', 'Analytic 1356', 'Defenders should monitor for anomalous or unauthorized changes to cloud compute configurations that alter quotas, tenant-wide policies, subscription associations, or allowed deployment regions. From a defender’s perspective, suspicious behavior chains include a sudden increase in compute quota requests followed by new instance or resource creation, policy modifications that weaken security restrictions, or enabling previously unused/unsupported cloud regions. Correlation across identity, configuration, and subsequent provisioning logs is critical to distinguish legitimate administrative activity from adversarial abuse.', '{IaaS}', 'x-mitre-analytic--193f0293-0a53-430f-83c0-a69d0663479a', 'DET0492', '[{"name": "AWS:CloudTrail", "channel": "RequestServiceQuotaIncrease", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "UserContext", "description": "Identity performing the quota or configuration change; tuned to filter known admins or automation accounts."}, {"field": "TimeWindow", "description": "Correlation period for configuration change followed by resource creation; tuned to environment norms."}, {"field": "ChangeType", "description": "Type of configuration being modified (quota, policy, region); tuned to organization-specific risk thresholds."}, {"field": "GeoLocation", "description": "Region where the configuration change originates; tuned to enterprise’s expected operational geography."}]', '2026-05-01 15:26:34.650793');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (198, 'AN0342', 'Analytic 0342', 'Detects removable drive insertion followed by unusual file access, compression, or staging activity by unauthorized users or unexpected processes.', '{Windows}', 'x-mitre-analytic--198d4196-25f0-4e28-a95b-c89709f452ab', 'DET0123', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:System", "channel": "EventCode=1006, 10001", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "DriveTypeFilter", "description": "Filter on removable (e.g., USB) drives only."}, {"field": "ProcessNameExclusionList", "description": "Exclude known, approved backup or sync utilities."}, {"field": "TimeWindow", "description": "Limit correlation of file access and device mount to a defined window (e.g., <5 minutes)."}]', '2026-05-01 15:26:34.651971');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (199, 'AN1129', 'Analytic 1129', 'Discovery of SaaS services connected to productivity platforms (e.g., Microsoft 365, Google Workspace). Defender perspective includes unexpected enumeration of enabled services, API integrations, or OAuth applications tied to user accounts.', '{"Office Suite"}', 'x-mitre-analytic--19b6de3a-032f-4dc8-aa72-7cd952dfed59', 'DET0402', '[{"name": "m365:unified", "channel": "Get-MsolServicePrincipal, ListAppRoles: Service discovery operations executed by accounts not normally performing administrative tasks", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"name": "m365:signinlogs", "channel": "UserLogin: Discovery operations shortly after account logins from new geolocations", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "MonitoredAppIntegrations", "description": "Specific Office Suite applications or plugins that may be enumerated or targeted."}, {"field": "GeoLocationDeviation", "description": "Geographic deviation threshold for discovery actions linked to recent logins."}]', '2026-05-01 15:26:34.653439');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (200, 'AN0236', 'Analytic 0236', 'Monitor for creation of WMI EventFilter, EventConsumer, and FilterToConsumerBinding objects through WMI or MOF file execution. Detect command-line execution of `mofcomp.exe`, usage of `Register-WmiEvent` via PowerShell, and anomalous child processes of `WmiPrvSE.exe` that indicate triggered execution. Look for lateral anomalies in process lineage and WMI logging channels.', '{Windows}', 'x-mitre-analytic--1a0640f0-e286-405f-9ab3-507c1abb77da', 'DET0086', '[{"name": "WinEventLog:WMI", "channel": "EventCode=5857, 5858, 5860, 5861", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TimeWindow", "description": "Defines temporal correlation range between WMI creation and child process execution"}, {"field": "UserContext", "description": "Tune for specific accounts (e.g., SYSTEM or attacker-controlled users)"}, {"field": "ProcessNameAllowlist", "description": "Used to exclude known benign consumers triggered via WMI (e.g., backup tools)"}, {"field": "ParentProcessAnomalyThreshold", "description": "Defines what constitutes anomalous spawning from WmiPrvSE.exe"}]', '2026-05-01 15:26:34.655759');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (201, 'AN0107', 'Analytic 0107', 'Detects abnormal access to Safari credential stores (Keychain-backed) or Chrome/Firefox login databases. Observes processes executing `security dump-keychain` or directly reading credential files in `~/Library/Application Support`. Correlates file access with suspicious process ancestry or unsigned binaries.', '{macOS}', 'x-mitre-analytic--1a068df0-67d4-4521-aeda-75fa8e9f8d98', 'DET0037', '[{"name": "macos:unifiedlog", "channel": "execution of security, sqlite3, or unauthorized binaries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "~/Library/Application Support/Google/Chrome/*/Login Data OR ~/Library/Application Support/Firefox/*/logins.json", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "PrivilegedUsers", "description": "Expected user context authorized to unlock Keychain or browser databases"}, {"field": "TimeWindow", "description": "Correlation window for process execution and credential file access"}]', '2026-05-01 15:26:34.657424');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (202, 'AN0688', 'Analytic 0688', 'Detection of unauthorized keylogger behavior through access to `/dev/input`, loading kernel modules (e.g., via insmod), or polling user input devices from non-user shells', '{Linux}', 'x-mitre-analytic--1a13d795-7c26-44b6-ad1b-2ad732dc33c3', 'DET0246', '[{"name": "linux:syslog", "channel": "syscalls (open, read, ioctl) on /dev/input or /proc/*/fd/*", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "linux:syslog", "channel": "dmesg or syslog for module loads", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}]', '[{"field": "PathTarget", "description": "Can tune based on device paths accessed for keyboard input (e.g., /dev/input/event0)"}, {"field": "UserContext", "description": "Exclude root or admin-auth shell sessions if needed"}, {"field": "ModuleWhitelist", "description": "Set a known list of allowed kernel modules"}]', '2026-05-01 15:26:34.658989');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (203, 'AN1468', 'Analytic 1468', 'An SMB-based remote file share access followed by lateral movement actions such as remote service creation, task scheduling, or suspicious process execution on the target host using ADMIN$ or C$ shares.', '{Windows}', 'x-mitre-analytic--1a18402e-efb1-49c7-8615-dc907f838320', 'DET0530', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ShareName", "description": "Targeted admin share path, such as C$, ADMIN$, IPC$"}, {"field": "TimeWindow", "description": "Correlation window between remote file access and remote execution (e.g., 5-10 minutes)"}, {"field": "UserContext", "description": "Distinguish expected remote administrators vs. rare/first-time access by specific users"}, {"field": "ProcessList", "description": "List of suspicious binaries or tools executed post remote copy (e.g., cmd.exe, powershell.exe, runonce.exe)"}]', '2026-05-01 15:26:34.660442');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (204, 'AN1215', 'Analytic 1215', 'Detects custom archiving by monitoring execution of Swift/Objective-C apps or scripts producing high-entropy files with non-standard headers. Correlates unified logs of abnormal NSFileHandle/NSData operations, memory use of XOR/bitwise operations, and file creation events.', '{macOS}', 'x-mitre-analytic--1a39005f-28e7-4b07-85e2-14ffa0f6ea3b', 'DET0438', '[{"name": "macos:unifiedlog", "channel": "Suspicious Swift/Objective-C or scripting processes writing archive-like outputs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Creation of files with anomalous headers and entropy values", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "Abnormal memory operations (XOR/bitwise loops) during archive generation", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "UserContext", "description": "Flag if archiving occurs under privileged/system accounts."}, {"field": "EntropyThreshold", "description": "Entropy score cutoff for identifying custom compressed or encrypted files."}, {"field": "AllowedApps", "description": "Applications legitimately using custom archiving for business purposes."}]', '2026-05-01 15:26:34.66171');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (205, 'AN1158', 'Analytic 1158', 'Access to container image layers or mounted secrets (e.g., Docker secrets) by processes not tied to entrypoint or orchestration context.', '{Containers}', 'x-mitre-analytic--1a68a39c-c4e3-4ff1-88f5-db78575ce15e', 'DET0412', '[{"name": "auditd:SYSCALL", "channel": "read of /run/secrets or docker volumes by non-entrypoint process", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "containerd:Events", "channel": "unusual process spawned from container image context", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "EntrypointAllowlist", "description": "Container entrypoints that are permitted to read secrets"}, {"field": "VolumeMountPath", "description": "Paths to credentials/secrets inside container images"}]', '2026-05-01 15:26:34.66326');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (206, 'AN0537', 'Analytic 0537', 'Abnormal use of `lsblk`, `fdisk -l`, `lshw -class disk`, or `parted` by non-admin users or within non-interactive shells suggests suspicious disk enumeration activity.', '{Linux}', 'x-mitre-analytic--1a7052d7-84f1-4116-bdb1-49bbe8709e3d', 'DET0188', '[{"name": "auditd:SYSCALL", "channel": "execve call with argv matching known disk enumeration commands (lsblk, parted, fdisk)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:EXECVE", "channel": "command line arguments containing lsblk, fdisk, parted", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TTY_type", "description": "Detection can exclude interactive TTY sessions to reduce false positives from admin usage"}, {"field": "shell_parent", "description": "Differentiate between interactive user shells vs. script-based execution"}]', '2026-05-01 15:26:34.664596');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (207, 'AN0377', 'Analytic 0377', 'Detection of JetBrains or VSCode tunnel profile creation followed by unusual persistent SSH or IDE-based tunnel communications to devtunnel APIs.', '{macOS}', 'x-mitre-analytic--1a93a610-7389-4ea7-a053-e99d35a5477a', 'DET0133', '[{"name": "macos:unifiedlog", "channel": "process: code or jetbrains-gateway launching with --tunnel or --remote", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "creation of ~/.vscode-cli/code_tunnel.json", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "HTTPs connection to tunnels.api.visualstudio.com", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ParentProcessName", "description": "Helps scope tunnel launch context to non-interactive or suspicious parent processes."}, {"field": "RemoteTunnelPersistence", "description": "Allows tracking of tunnel re-establishment across reboots for persistence."}, {"field": "RemoteFlag", "description": "May include values like --remote, -R, or embedded ssh arguments passed by IDEs"}, {"field": "LaunchAgentPath", "description": "If the IDE uses persistence via LaunchAgents, defenders may choose where to monitor for tunnel auto-launching"}, {"field": "TunnelReconnectInterval", "description": "Frequency of retry attempts for tunnel reconnection can affect correlation window"}]', '2026-05-01 15:26:34.665773');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (208, 'AN2063', 'Analytic 2063', 'Detection identifies execution of scripts or files that appear visually benign (low printable character ratio) but result in runtime decoding, dynamic evaluation, and subsequent process or network activity. Correlation links script execution with abnormal Unicode density and follow-on behavior such as child process creation or outbound connections.', '{Windows}', 'x-mitre-analytic--1a9f097a-d5b9-424d-ae20-19ed73eb9dcf', 'DET0920', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "AllocationSizeThreshold", "description": "To tune for atypical virtual memory allocations that might indicate non-rendering characters in dense files"}, {"field": "ExecutionContext", "description": "Allows tuning for atypical processes from script execution (e.g., powershell.exe, wscript.exe, mshta.exe)"}, {"field": "UnicodeDensityThreshold", "description": "Tune for invisible characters, or atypical amounts of Unicode characters (U+...)"}]', '2026-05-01 15:26:34.666911');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (209, 'AN1623', 'Analytic 1623', 'Adversary compromises a Linux-based web server and modifies hosted web files by exploiting upload vulnerabilities, remote code execution, or replacing index.html via SSH/webshell.', '{Linux}', 'x-mitre-analytic--1affb8e9-25b4-49c1-b290-687e9696fa83', 'DET0590', '[{"name": "auditd:SYSCALL", "channel": "open/write syscalls targeting web directory files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Connections", "channel": "Successful sudo or ssh from unknown IPs", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "NSM:Flow", "channel": "Suspicious POSTs to upload endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "web_root", "description": "May differ (e.g., /var/www/html, /srv/http, etc.)"}, {"field": "payload_hash", "description": "Adversary content hash may change across campaigns"}, {"field": "UserContext", "description": "Can range from apache/nginx user to root if escalated"}]', '2026-05-01 15:26:34.668098');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (210, 'AN1969', 'Analytic 1969', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during [Phishing](https://attack.mitre.org/techniques/T1566), [Endpoint Denial of Service](https://attack.mitre.org/techniques/T1499), or [Network Denial of Service](https://attack.mitre.org/techniques/T1498).', '{PRE}', 'x-mitre-analytic--1b067cad-c75b-484e-8aaa-4b058c8ec9f7', 'DET0837', NULL, NULL, '2026-05-01 15:26:34.669354');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (211, 'AN1269', 'Analytic 1269', 'Use of leaked credential pairs against Outlook Web Access (OWA), Microsoft 365, or Exchange from a single client IP with multiple failures', '{"Office Suite"}', 'x-mitre-analytic--1b3bbeab-2000-47d6-88f9-8ed519f9bed6', 'DET0460', '[{"name": "m365:exchange", "channel": "Logon failure", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "PasswordSourceMatch", "description": "Optional: cross-reference to haveibeenpwned or internal credential dumps"}, {"field": "MailboxLoginThreshold", "description": "Tunable value for how many unique mailbox attempts trigger alert"}]', '2026-05-01 15:26:34.67061');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (239, 'AN1326', 'Analytic 1326', 'Execution of service management commands like `systemctl list-units`, `service --status-all`, or direct reading of `/etc/init.d`.', '{Linux}', 'x-mitre-analytic--20879a60-f16c-4a90-bd71-2c8865c99481', 'DET0483', '[{"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandPattern", "description": "Includes service enumeration commands like `systemctl`, `service`, or custom scripts."}, {"field": "ExecutionUser", "description": "Tunable by user context (e.g., root vs. standard user)."}, {"field": "TimeWindow", "description": "Used for correlation with privilege escalation or lateral movement."}]', '2026-05-01 15:26:34.71398');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (212, 'AN0348', 'Analytic 0348', 'ESXi shell (BusyBox) or VMware utilities (openssl, python if present) used to Base64/hex encode data from datastore or config files → followed by abnormal egress from the host (NSX/flow logs) with asymmetric bytes_out or HTTPS posts to non-management endpoints.', '{ESXi}', 'x-mitre-analytic--1b53dd1b-c98e-4b25-a7fd-70dad586ebf1', 'DET0124', '[{"name": "esxi:shell", "channel": "commands containing base64, openssl enc -base64, xxd -p", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "esxi:hostd", "channel": "unexpected script/command invocations via hostd", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSX:FlowLogs", "channel": "network_flow: bytes_out >> bytes_in to external", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "http: Base64/MIME looking payloads from ESXi host IP", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MgmtCIDRs", "description": "CIDRs for legitimate vCenter/NSX/backup endpoints."}, {"field": "BytesRatio", "description": "Out:In ratio deemed suspicious (e.g., ≥3 on ESXi)."}, {"field": "TimeWindow", "description": "Correlation window between shell command and egress."}]', '2026-05-01 15:26:34.671936');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (213, 'AN0057', 'Analytic 0057', 'Creation of run-only AppleScripts or Mach-O binaries lacking symbol table and string references, especially when dropped by user space scripting engines or staging apps.', '{macOS}', 'x-mitre-analytic--1b5b9ee8-69e6-41d4-a529-aa18afcdf453', 'DET0019', '[{"name": "macos:unifiedlog", "channel": "file write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "code_signing, file_metadata", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "RunOnlyFlag", "description": "AppleScript flag to disable reverse engineering (run-only compiled scripts)"}, {"field": "ParentProcess", "description": "Filter to isolate staging or suspicious scripting engines"}, {"field": "SignedStatus", "description": "Tuning based on unsigned vs. developer-signed payloads"}]', '2026-05-01 15:26:34.673845');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (214, 'AN1640', 'Analytic 1640', 'SSH login via hostd or `/var/log/auth.log`, followed by CLI access to host shell or file manipulation in restricted areas.', '{ESXi}', 'x-mitre-analytic--1b6eaec8-141f-44f8-ae1f-387c44635c38', 'DET0596', '[{"name": "esxi:auth", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "esxi:shell", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:vmkernel", "channel": "port 22 access", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AllowedUsers", "description": "Legitimate SSH users to this host"}, {"field": "TimeWindow", "description": "Correlate SSH login and unauthorized commands or shell access"}, {"field": "CommandList", "description": "Flag commands like esxcli, rm, chmod post-login"}]', '2026-05-01 15:26:34.675524');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (215, 'AN1036', 'Analytic 1036', 'Monitors for hardware or firmware tampering by correlating system boot logs, hardware inventory changes, and secure boot/firmware verification failures. Behavioral chain: (1) UEFI/BIOS version drift; (2) secure boot disabled or signature verification errors; (3) unexpected modules or hardware devices enumerated at boot; (4) new device firmware images loaded from non-approved sources.', '{Linux}', 'x-mitre-analytic--1c25310b-d8fa-472d-a10e-c327a8fba693', 'DET0368', '[{"name": "auditd:SYSCALL", "channel": "firmware_update, kexec_load", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "fwupd:logs", "channel": "Firmware updates applied or failed", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "ApprovedFirmwareHashes", "description": "List of SHA256/SHA512 firmware hashes allowed."}, {"field": "AllowedDeviceIDs", "description": "Known hardware component IDs per host baseline."}]', '2026-05-01 15:26:34.676955');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (216, 'AN1066', 'Analytic 1066', 'Monitors use of archive or encryption tools (zip, openssl) tied to user-scripted activity or binaries writing encoded payloads under /Users or /Volumes.', '{macOS}', 'x-mitre-analytic--1c2e527f-b9ff-4e1d-896d-0c1257f0abc1', 'DET0378', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate ''processImagePath contains \"zip\" OR \"base64\"''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "FilenameExtensionList", "description": "Tunable to identify uncommon or encrypted file formats (e.g., .enc, .b64, .xz)"}, {"field": "UserContext", "description": "Tune to prioritize unexpected file access by service accounts"}]', '2026-05-01 15:26:34.678301');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (217, 'AN1629', 'Analytic 1629', 'Detects abuse of busybox commands (e.g., `touch`) or log timestamp tampering during backdoor persistence or evasion.', '{ESXi}', 'x-mitre-analytic--1c3cb010-1c22-40c8-92d3-52e31353ad92', 'DET0591', '[{"name": "esxi:vmkernel", "channel": "/var/log/vmkernel.log", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "TimestampAgeComparison", "description": "Unusual backdating to match legit files"}, {"field": "PersistenceOverlap", "description": "Overlap with known persistence paths"}]', '2026-05-01 15:26:34.679834');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (218, 'AN1611', 'Analytic 1611', 'Detects credential dumping attempts targeting the NTDS.dit database by monitoring shadow copy creation, suspicious file access to %SystemRoot%\NTDS\ntds.dit, and the use of tooling like ntdsutil.exe or volume management APIs.', '{Windows}', 'x-mitre-analytic--1c715030-9564-482d-98b7-22072bf28c97', 'DET0586', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Microsoft-Windows-VSS", "channel": "Volume Shadow Copy Creation", "x_mitre_data_component_ref": "x-mitre-data-component--dad75cc7-5bae-4175-adb4-ca1962d8650e"}]', '[{"field": "TargetFilePath", "description": "Tunable for NTDS file location or backup paths if organization uses custom domain controller storage structure."}, {"field": "ParentProcessName", "description": "Can suppress backup-related parent processes to reduce false positives."}, {"field": "TimeWindow", "description": "Temporal correlation between shadow copy creation and NTDS file access (e.g., 5 min window)."}, {"field": "UserContext", "description": "Tune based on expected privileged user/service account behavior."}]', '2026-05-01 15:26:34.682077');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (219, 'AN1554', 'Analytic 1554', 'ESXi hypervisor environmental validation behavioral chain: (1) Virtual machine inventory and configuration enumeration through vim-cmd and esxcli commands, (2) Host hardware and network configuration discovery for hypervisor environment validation, (3) Datastore and storage configuration reconnaissance, (4) vCenter connectivity and cluster membership validation, (5) Selective malware deployment based on virtualization infrastructure characteristics and target VM validation', '{ESXi}', 'x-mitre-analytic--1cd8c844-575a-44be-9fee-80cd988dc781', 'DET0562', '[{"name": "esxi:shell", "channel": "shell command execution for system discovery (vim-cmd, esxcli, vmware-cmd) targeting VM inventory and host configuration", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:hostd", "channel": "host daemon events related to VM operations and configuration queries during reconnaissance", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ESXiDiscoveryCommands", "description": "ESXi commands commonly used for hypervisor and VM reconnaissance"}, {"field": "VMInventoryEnumerationThreshold", "description": "Number of VM inventory queries within time window indicating reconnaissance activity"}, {"field": "HypervisorEnvironmentBaseline", "description": "Normal hypervisor management activity patterns for distinguishing malicious reconnaissance"}, {"field": "DatastoreAccessPatterns", "description": "Unusual datastore access patterns indicating environmental validation or target selection"}]', '2026-05-01 15:26:34.683428');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (220, 'AN0716', 'Analytic 0716', 'Initiation of remote desktop sessions via AnyDesk, TeamViewer, or Chrome Remote Desktop accompanied by unexpected user logins or system modifications', '{macOS}', 'x-mitre-analytic--1d46bf4d-a090-4865-9205-e271d223da42', 'DET0259', '[{"name": "macos:unifiedlog", "channel": "launch of remote desktop app or helper binary", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "network sessions initiated by remote desktop apps", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "process_signature", "description": "App may be notarized and signed differently depending on distribution method (App Store vs .pkg)"}, {"field": "sandbox_exception", "description": "If the remote desktop tool circumvents sandbox, it may produce additional telemetry in local TCC logs"}]', '2026-05-01 15:26:34.684779');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (221, 'AN1526', 'Analytic 1526', 'Password guessing attempts against web-based apps (e.g., Dropbox, Google Workspace) reflected in API or sign-in logs', '{SaaS}', 'x-mitre-analytic--1d8bc80f-8719-41f0-a73e-127d6830f516', 'DET0551', '[{"name": "GCPAuditLogs:login.googleapis.com", "channel": "Failed sign-in events", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AppContext", "description": "Which SaaS apps should be monitored for brute force attempts"}, {"field": "EmailPattern", "description": "Limit scope to enterprise domains or service accounts"}]', '2026-05-01 15:26:34.686033');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (222, 'AN1360', 'Analytic 1360', 'Defenders may observe attempts to disable dedicated crypto hardware on network devices, often visible through anomalous CLI commands, unexpected firmware or configuration updates, and degraded encryption performance. Suspicious indicators include commands that alter hardware acceleration settings (e.g., disabling AES-NI or crypto engines), modification of system image files, or logs showing fallback from hardware to software encryption. Network traffic analysis may also reveal a sudden downgrade in throughput or cipher negotiation behavior consistent with the absence of hardware acceleration.', '{"Network Devices"}', 'x-mitre-analytic--1dd7c76f-ff71-4597-8785-f7a730101a00', 'DET0494', '[{"name": "networkdevice:cli", "channel": "Execution of commands disabling crypto hardware acceleration (e.g., ''no crypto engine enable'')", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:config", "channel": "Configuration changes referencing cryptographic hardware modules or disabling hardware acceleration", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Flow", "channel": "Degraded encryption throughput or switch to weaker cipher suites compared to historical baselines", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AuthorizedAdminAccounts", "description": "Defines trusted administrator accounts allowed to modify encryption hardware settings; deviations trigger alerts."}, {"field": "BaselineThroughput", "description": "Expected performance metrics with hardware acceleration enabled; drops may indicate tampering."}, {"field": "ApprovedFirmwareVersions", "description": "Whitelist of vendor-signed firmware versions; unexpected updates could signal malicious modification."}, {"field": "TimeWindow", "description": "Period of correlation between configuration change and observed traffic downgrade; tunable to reduce false positives."}]', '2026-05-01 15:26:34.687278');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (223, 'AN1064', 'Analytic 1064', 'Correlates script execution or suspicious parent processes with creation or modification of encoded, compressed, or encrypted file formats (e.g., .zip, .7z, .enc) and abnormal command-line syntax or PowerShell obfuscation.', '{Windows}', 'x-mitre-analytic--1dee558e-720e-4f3b-9414-192a63eb8909', 'DET0378', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PayloadEntropyThreshold", "description": "Tune entropy threshold to distinguish obfuscation from legitimate compression"}, {"field": "TimeWindow", "description": "Adjust correlation window between script execution and encoded file creation"}, {"field": "SuspiciousParentProcessList", "description": "Customize based on environment to include LOLBins or admin tools misused for obfuscation"}]', '2026-05-01 15:26:34.688662');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (224, 'AN0150', 'Analytic 0150', 'Internal spearphishing via SaaS applications (e.g., Slack, Teams, Gmail): message sent from compromised user with attachment or URL, followed by click and credential access behavior.', '{SaaS}', 'x-mitre-analytic--1e2211b9-1730-4645-89f6-11259b35e0a4', 'DET0054', '[{"name": "saas:slack", "channel": "file_upload, message_send, message_click", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "UserAnomalyThreshold", "description": "Volume or timing of messages sent after compromise"}, {"field": "FileRiskScoring", "description": "Whether SaaS DLP assigns risk scores to attachments"}]', '2026-05-01 15:26:34.69036');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (225, 'AN0596', 'Analytic 0596', 'Adversary uses a process to establish outbound connections that transmit uniform packet sizes at a consistent interval, avoiding threshold-based network alerts.', '{Windows}', 'x-mitre-analytic--1e9fdc71-d073-403a-9ee9-bab091318454', 'DET0213', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "NetFlow/sFlow/PCAP", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "PacketSizeThreshold", "description": "Minimum repetitive size in bytes to consider as anomalous behavior (e.g., 512B or 1024B)"}, {"field": "IntervalRepeatWindow", "description": "Timeframe over which repeated, evenly spaced transfers are flagged"}, {"field": "KnownServicePorts", "description": "Common ports expected to exhibit protocol behavior; outliers flagged if not matching expected usage"}]', '2026-05-01 15:26:34.692013');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (226, 'AN0101', 'Analytic 0101', 'Non-interactive system processes making encrypted HTTPS connections to well-known web services followed by high outbound traffic volume or scripted upload patterns.', '{Linux}', 'x-mitre-analytic--1edab644-3ec0-4c5d-bc26-18744fbc7a6e', 'DET0035', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "ssl.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "UploadDirectionality", "description": "Bias detection toward sessions with larger upload vs download volume"}, {"field": "HostnameRegexList", "description": "List of known public Web services used for dead drops or C2 (e.g., GitHub, Twitter)"}, {"field": "ScriptParentName", "description": "Shell interpreter or automated job parent used for filtering (e.g., /usr/bin/python)"}]', '2026-05-01 15:26:34.693379');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (227, 'AN0079', 'Analytic 0079', 'Detects Web protocol misuse such as encoded HTTP headers, WebSocket upgrade requests with abnormal payloads, or TLS handshake anomalies suggesting embedded C2 channels.', '{"Network Devices"}', 'x-mitre-analytic--1f1ed319-a6f9-4f30-9254-e0b1927a6bd9', 'DET0027', '[{"name": "NSM:Flow", "channel": "http.log, ssl.log, websocket.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "HeaderEncodingPattern", "description": "Base64, hex, or UTF-16 encoding in URI, cookie, or host"}, {"field": "TLSFingerprintMismatch", "description": "JA3 hash deviation from known clients"}]', '2026-05-01 15:26:34.694722');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (228, 'AN1281', 'Analytic 1281', 'File access to NetworkManager connection configs and attempts to read PSK credentials from `/etc/NetworkManager/system-connections/*`.', '{Linux}', 'x-mitre-analytic--1f3a6d61-9658-4c9b-92af-5c711206e3fa', 'DET0464', '[{"name": "auditd:PATH", "channel": "file read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "FilenamePattern", "description": "Filter for filenames like *.nmconnection or profiles containing SSID names"}, {"field": "UserContext", "description": "Distinguish between root/admin script usage vs. non-privileged terminal access"}]', '2026-05-01 15:26:34.69669');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (229, 'AN1008', 'Analytic 1008', 'Detect abnormally high volume of inbound email messages or repetitive attachments being delivered to a single mailbox within a short time window. Defenders should look for anomalous spikes in message counts and repetitive attachment file creation events correlated with targeted users.', '{Windows}', 'x-mitre-analytic--1f515cf2-91a5-4bed-95a1-ed8fc8b24a87', 'DET0355', '[{"name": "m365:unified", "channel": "Send/Receive: Unusual spikes in inbound messages to a single recipient", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "TimeWindow", "description": "Defines the aggregation interval (e.g., 5 minutes, 1 hour) for detecting spikes in inbound email traffic."}, {"field": "RecipientThreshold", "description": "Defines maximum number of acceptable messages per user before triggering anomaly."}, {"field": "AttachmentSizeThreshold", "description": "Defines the size threshold for repetitive attachments to be flagged."}]', '2026-05-01 15:26:34.69824');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (230, 'AN1555', 'Analytic 1555', 'Detection of environment variable tampering (HISTFILE, HISTCONTROL, HISTFILESIZE) and absence of expected bash history writes. Correlation of unset or zeroed history variables with active shell sessions is indicative of adversarial evasion.', '{Linux}', 'x-mitre-analytic--1f69e126-e849-43a1-9fca-b5c63a154daa', 'DET0563', '[{"name": "auditd:SYSCALL", "channel": "execve calls modifying HISTFILE or HISTCONTROL via unset/export", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:osquery", "channel": "processes modifying environment variables related to history logging", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredUsers", "description": "Specific accounts or groups where history logging must always be enforced."}, {"field": "TimeWindow", "description": "Correlation period to detect unset/export of history variables during active shells."}]', '2026-05-01 15:26:34.699676');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (231, 'AN0521', 'Analytic 0521', 'Detects deletion or overwriting of bash history, syslog, audit logs, and .ssh metadata following privilege elevation or suspicious process spawning.', '{Linux}', 'x-mitre-analytic--1fbe9da1-a760-4ac9-8ab0-59203a50fb82', 'DET0184', '[{"name": "auditd:SYSCALL", "channel": "unlink, rename, open", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "linux:cli", "channel": "cleared or truncated .bash_history", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MonitoredPaths", "description": "Adjust based on syslog/auditd file paths (/var/log/messages, /var/log/audit/audit.log)"}, {"field": "UserContext", "description": "Scope to root/sudo usage or anomalous user behavior"}]', '2026-05-01 15:26:34.701038');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (240, 'AN0291', 'Analytic 0291', 'Detects unauthorized changes to IAM authentication configurations such as disabling MFA, creating backdoor access keys, or altering trust policies. Correlates identity policy updates with unusual login behavior.', '{IaaS}', 'x-mitre-analytic--20b6d23a-d1cc-494c-ac67-e7358835c674', 'DET0104', '[{"name": "AWS:CloudTrail", "channel": "UpdateLoginProfile", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "AWS:CloudTrail", "channel": "UpdateAccountPasswordPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "ApprovedAccounts", "description": "Baseline list of service accounts expected to modify IAM authentication policies."}]', '2026-05-01 15:26:34.715133');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (232, 'AN1305', 'Analytic 1305', 'Windows-specific environmental keying behavioral chain: (1) Rapid system information discovery through multiple techniques (WMI queries, registry enumeration, network share discovery, hostname/domain checks), (2) Target validation through specific environmental artifact collection (AD domain membership, network topology, installed software versions), (3) Cryptographic operation correlation indicating payload decryption based on collected environmental values, (4) Subsequent malicious code execution following successful environmental validation, (5) Temporal clustering of discovery activities suggesting automated environmental assessment', '{Windows}', 'x-mitre-analytic--1fd68bec-86cb-4457-b0cd-56fc724fd578', 'DET0474', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=25", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:WMI", "channel": "EventCode=5857, 5858, 5860, 5861", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "DiscoveryTimeWindow", "description": "Time window for correlating multiple discovery activities as part of environmental assessment - adjust based on observed attack patterns and system performance (default: 300 seconds)"}, {"field": "CriticalDiscoveryThreshold", "description": "Minimum number of distinct discovery techniques within time window to trigger detection - tune based on environment''s normal administrative activity levels"}, {"field": "TargetSpecificArtifacts", "description": "Organization-specific environmental elements that adversaries might target (domain names, network shares, specific hostnames, software versions)"}, {"field": "CryptographicIndicatorPatterns", "description": "Process names, command lines, and API calls indicating potential decryption operations - customize based on observed cryptographic tool usage in environment"}, {"field": "LegitimateAdminAccounts", "description": "User accounts authorized to perform extensive system discovery - maintain current list to reduce false positives from legitimate administrative activities"}, {"field": "BusinessHoursBaseline", "description": "Normal business hours for risk scoring adjustment - discovery activities outside these hours receive higher risk scores"}, {"field": "WMIQueryComplexityThreshold", "description": "Complexity metric for WMI queries to identify sophisticated environmental assessment versus simple system checks"}]', '2026-05-01 15:26:34.702447');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (233, 'AN1971', 'Analytic 1971', 'If infrastructure or patterns in malware, tooling, certificates, or malicious web content have been previously identified, internet scanning may uncover when an adversary has staged their capabilities.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (234, 'AN0409', 'Analytic 0409', 'Detection of firewall changes using esxcli network firewall set or vSphere API modifications. Sudden disabling of firewall rules across management interfaces is a strong adversarial signal.', '{ESXi}', 'x-mitre-analytic--1fecb6f7-e72f-452e-a078-3298cba8d481', 'DET0145', '[{"name": "esxi:hostd", "channel": "esxcli network firewall set commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:hostd", "channel": "vSphere API calls modifying firewall settings", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}]', '[{"field": "APIMethods", "description": "Whitelist of authorized vSphere API methods for firewall configuration."}]', '2026-05-01 15:26:34.705147');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (235, 'AN1396', 'Analytic 1396', 'Detection of obfuscated commands via shell, osascript, or AppleScript interpreters using unusual tokens, encoding, variable substitution, or runtime string reconstruction.', '{macOS}', 'x-mitre-analytic--20157d55-1760-483c-a3b1-c6e219eeb75c', 'DET0505', '[{"name": "macos:unifiedlog", "channel": "process:spawn, process:exec", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "InterpreterParentFilter", "description": "Limits detection scope to shell or scripting interpreters like zsh, bash, osascript"}, {"field": "ScriptEntropyThreshold", "description": "Minimum entropy required to consider the command or script obfuscated"}, {"field": "ArgumentLengthDeviation", "description": "Deviation from baseline for long or highly nested arguments"}]', '2026-05-01 15:26:34.707812');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (236, 'AN0386', 'Analytic 0386', 'Abnormal invocation of diskutil, asr, or low-level APIs (IOKit) to erase/partition drives. Correlate process execution with unified log entries showing destructive disk operations.', '{macOS}', 'x-mitre-analytic--2016853a-07eb-4df4-a471-69b55f82b34d', 'DET0137', '[{"name": "macos:unifiedlog", "channel": "diskutil eraseDisk / asr restore with destructive flags", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "IOKit disk write calls targeting raw devices", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}]', '[{"field": "AdminToolWhitelist", "description": "System administrators may legitimately use diskutil/asr for provisioning — whitelist by user or context."}]', '2026-05-01 15:26:34.709457');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (237, 'AN0605', 'Analytic 0605', 'Ransomware encrypts .vmdk, .vmx, .log, or VM config files in VMFS datastores. May rename to .locked or delete/overwrite with encrypted versions. Often correlates with shell commands run through `dcui`, SSH, or vSphere.', '{ESXi}', 'x-mitre-analytic--203586e5-e178-4d41-bbae-93a86f04977b', 'DET0215', '[{"name": "esxi:vmkernel", "channel": "rename .vmdk to .*.locked|datastore write spike", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "esxi:shell", "channel": "openssl|tar|dd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "FileType", "description": "Detect renames or write patterns involving .vmdk, .vmx, .nvram."}, {"field": "UserContext", "description": "Identify shell sessions opened by root or unexpected users outside maintenance window."}]', '2026-05-01 15:26:34.710805');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (238, 'AN0378', 'Analytic 0378', 'Detects unauthorized access to Windows Credential Manager through anomalous process execution (vaultcmd.exe, rundll32.exe keymgr.dll), suspicious API calls (CredEnumerateA), or direct file access to Credential Locker files. Correlates process creation with subsequent file reads of .vcrd/.vpol files under user Credential Locker directories.', '{Windows}', 'x-mitre-analytic--207b58a9-7e3b-41ca-bb5a-c66b24210a83', 'DET0134', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "MonitoredPaths", "description": "Credential Locker paths such as %Systemdrive%\\Users\\*\\AppData\\Local\\Microsoft\\Credentials and %Systemdrive%\\Users\\*\\AppData\\Local\\Microsoft\\Vault"}, {"field": "TimeWindow", "description": "Correlation window between process execution, file access, and API calls"}, {"field": "PrivilegedUsers", "description": "Baseline of expected administrative/service accounts with legitimate Credential Manager access"}]', '2026-05-01 15:26:34.712636');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (241, 'AN1478', 'Analytic 1478', 'Detects unauthorized Wi-Fi associations and SSID scanning activity using unified logs and airport command telemetry. Anomalies include rapid SSID switching, connections to unapproved SSIDs, or repeated authentication failures.', '{macOS}', 'x-mitre-analytic--20c2cbdf-2a02-40d1-9d10-b91d9bbe3004', 'DET0536', '[{"name": "macos:unifiedlog", "channel": "Association and authentication events including failures and new SSIDs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "macos:osquery", "channel": "query: Historical list of associated SSIDs compared against baseline", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "BaselineSSIDHistory", "description": "Historical record of corporate SSID associations per device; deviations may indicate rogue AP usage."}]', '2026-05-01 15:26:34.716494');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (242, 'AN0980', 'Analytic 0980', 'Unusual use of screen capture APIs (e.g., CopyFromScreen) or command-line tools to write image files to disk.', '{Windows}', 'x-mitre-analytic--20e00aff-6389-4c8a-8e38-3b63924e1612', 'DET0346', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ParentProcessName", "description": "Depends on allowed parent process behaviors in the environment (e.g., explorer.exe vs powershell.exe)"}, {"field": "TimeWindow", "description": "Can tune alert thresholds for rapid or scheduled screenshots (e.g., interval-based screen capture)"}, {"field": "ImageExtension", "description": "To detect file writes (e.g., .bmp, .png) that deviate from typical user activity"}]', '2026-05-01 15:26:34.717732');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (243, 'AN1416', 'Analytic 1416', 'Detects unexpected encrypted outbound connections from management components or guest VMs using TLS, particularly after data volume spikes or script-based orchestration from within guest environments.', '{ESXi}', 'x-mitre-analytic--20ecf7be-864a-4ae0-be66-cf26ffa9a217', 'DET0512', '[{"name": "esxi:hostd", "channel": "event stream", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:vmkernel", "channel": "egress logs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "VMToEgressPathWatchlist", "description": "Expected traffic routes for monitored VMs."}, {"field": "TLSClientAppIdentifier", "description": "Applications allowed to initiate TLS sessions from hypervisor level."}]', '2026-05-01 15:26:34.718955');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (244, 'AN0958', 'Analytic 0958', 'Container process uses mounted cloud credentials or token cache to authenticate without known orchestration.', '{Containers}', 'x-mitre-analytic--2127b359-24b0-40e2-a202-67e53d5be3b0', 'DET0338', '[{"name": "docker:runtime", "channel": "execution of cloud CLI tool (e.g., aws, az) inside container", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "AWS:CloudTrail", "channel": "AssumeRole", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "ContainerLabel", "description": "Restrict to prod workloads or certain namespaces"}, {"field": "CredentialPath", "description": "Path used to mount sensitive tokens (e.g., /.aws/credentials)"}]', '2026-05-01 15:26:34.720264');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (245, 'AN0941', 'Analytic 0941', 'Detects the use of message-based injection by monitoring for sequences involving FindWindow (EnumWindows or EnumChildWindows), VirtualAllocEx or related API calls, combined with suspicious PostMessage/SendMessage (e.g., LVM_SETITEMPOSITION) use to SysListView32 controls, followed by LVM_SORTITEMS invocation instead of WriteProcessMemory.', '{Windows}', 'x-mitre-analytic--217128c5-144d-492b-ab72-bd0704348221', 'DET0331', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "etw:Microsoft-Windows-Win32k", "channel": "SendMessage, PostMessage, LVM_*", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "TimeWindow_PostMessage_to_LVM_SORTITEMS", "description": "Defines temporal distance between payload copy and execution trigger"}, {"field": "TargetWindowClassName", "description": "Restrict detection to SysListView32 or similar GUI elements"}, {"field": "UserContextAnomalyThreshold", "description": "Adjusts detection sensitivity to users sending window messages across session boundaries"}, {"field": "InterprocessWindowMessagingFrequency", "description": "Raise alert when rate of message-passing to foreign GUI processes exceeds baseline"}]', '2026-05-01 15:26:34.721846');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (246, 'AN1183', 'Analytic 1183', 'Access to shell history or GUI input state (xdotool, xinput) for presence validation prior to payload execution.', '{Linux}', 'x-mitre-analytic--21773356-1c94-4edc-b368-008c86a5929e', 'DET0420', '[{"name": "auditd:SYSCALL", "channel": "Reads of ~/.bash_history, ~/.mozilla, or access to /dev/input", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "Execution of xev, xdotool, or input activity emulators", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ArtifactCountThreshold", "description": "Number of distinct user files accessed before trigger"}, {"field": "KnownToolSignatures", "description": "Suppress expected automation tools"}]', '2026-05-01 15:26:34.723523');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (247, 'AN1565', 'Analytic 1565', 'Atypical access to Slack or Teams conversations via APIs, automation tokens, or bulk message export functionality, particularly after an account takeover or rare sign-in pattern. Often includes mass retrieval of chat history, download of message content, or scraping of workspace/channel metadata.', '{SaaS}', 'x-mitre-analytic--222cf26f-e5cc-4b60-a7b2-39118b5c20d6', 'DET0567', '[{"name": "saas:slack", "channel": "conversations.history, files.list, users.info, audit_logs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:signinlogs", "channel": "UserLoggedIn", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "TimeWindow", "description": "Time interval to observe post-login message scraping behavior"}, {"field": "MessageExportThreshold", "description": "Number of messages or files accessed/downloaded to flag for review"}, {"field": "UserContext", "description": "User privilege level, team membership, or role context to suppress false positives"}, {"field": "AccessMethod", "description": "Direct user access vs API token, OAuth app, or bot interaction"}]', '2026-05-01 15:26:34.725238');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (248, 'AN0698', 'Analytic 0698', 'User-initiated installation of Python (pip), NodeJS (npm), or other language libraries, followed by unexpected network connections, credential access, or startup file modifications. Defender sees `pip install` or `npm install` commands run by a non-root user, followed shortly by new `.py`, `.sh`, or `.js` files in hidden directories, or interpreter-based execution during boot/login.', '{Linux}', 'x-mitre-analytic--223a39c8-d194-456e-be99-2db9e97ab7da', 'DET0252', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of pip, npm, gem, or similar package managers", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PATH", "channel": "New .py/.js/.sh files written to ~/.local/, ~/.cache/, or /tmp/ within 5 min of package install", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "http::request: Network connection to package registry or C2 from interpreter shortly after install", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "PackageManagerList", "description": "Monitored package managers (e.g., pip, npm, gem, poetry, conda)"}, {"field": "InstallWritePaths", "description": "Directories to watch for post-install execution artifacts (e.g., ~/.local/, /usr/lib/python3.8/site-packages/)"}, {"field": "UserContextScope", "description": "Filter to focus on non-system accounts (e.g., interactive shell users)"}, {"field": "TimeWindow", "description": "Correlate install command to subsequent network/file activity (default: 5 min)"}]', '2026-05-01 15:26:34.726703');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (249, 'AN0795', 'Analytic 0795', 'Monitor SaaS mail platforms (Google Workspace, M365, Okta-integrated apps) for SendAs/SendOnBehalfOf operations where the delegated permissions are unusual or newly granted. Detect impersonation attempts where adversaries configure rules to auto-forward or auto-reply with impersonated content.', '{SaaS}', 'x-mitre-analytic--2266c86a-a47e-46ac-aa6d-c1eb6d49a1e5', 'DET0286', '[{"name": "gcp:workspaceaudit", "channel": "SendAs: Outbound messages with alias identities that differ from primary account", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "DelegationBaseline", "description": "Maintain baseline of normal SendAs/SendOnBehalf relationships to reduce false positives."}]', '2026-05-01 15:26:34.729556');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (250, 'AN0263', 'Analytic 0263', 'Adversary uses a tool like Ruler or MFCMapi to create a malicious Outlook rule that triggers execution upon receipt of a crafted email. On email delivery, Outlook executes the rule, resulting in code execution (e.g., launching mshta.exe or PowerShell). Outlook spawns a non-standard child process, often unsanctioned, without user interaction.', '{Windows}', 'x-mitre-analytic--22cba5f6-b3d5-4a1a-9275-ed7db0bd4c7c', 'DET0095', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Application", "channel": "Outlook rule execution failure or abnormal rule execution context", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:PowerShell", "channel": "PowerShell launched from outlook.exe or triggered without user invocation", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ChildProcessName", "description": "Outlook may spawn mshta.exe, powershell.exe, or wscript.exe depending on attacker payload"}, {"field": "RuleTriggerCondition", "description": "Rule execution may depend on message subject, sender, or message header content"}, {"field": "ParentProcessName", "description": "Legitimate Outlook activity should not spawn scripting or interpreter processes"}, {"field": "TimeWindow", "description": "Execution may occur with delay after message receipt or folder interaction"}]', '2026-05-01 15:26:34.730851');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (251, 'AN1333', 'Analytic 1333', 'Use unified logs to identify processes issuing repeated DNS queries where the resolved IP addresses change frequently within very short TTL values. Correlate with outbound network traffic to validate C2-like patterns.', '{macOS}', 'x-mitre-analytic--22d28e80-ecae-4fa4-8901-ef9125c99e9f', 'DET0485', '[{"name": "macos:unifiedlog", "channel": "Rapid domain-to-IP resolution changes for same domain", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:unifiedlog", "channel": "Unexpected apps generating frequent DNS queries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DNSRotationRate", "description": "Rate of IP churn per domain to trigger detection"}, {"field": "NewDomainThreshold", "description": "Flag if domain was registered recently (e.g., < 30 days)"}]', '2026-05-01 15:26:34.732211');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (252, 'AN1592', 'Analytic 1592', 'Modification of Thunderbird message filters file or execution of CLI tools (e.g., formail/procmail) that alter .forward behavior.', '{Linux}', 'x-mitre-analytic--22e6f5f4-e4cc-449c-9dba-280788935ce5', 'DET0576', '[{"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:cli", "channel": "/home/*/.bash_history", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": ".forwardPath", "description": "User-based home directories; tune for specific user patterns."}, {"field": "ExecContext", "description": "Expected email client behavior may trigger similar file edits."}]', '2026-05-01 15:26:34.733469');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (253, 'AN0842', 'Analytic 0842', 'A remote source rapidly touches a short sequence of closed ports (SYN→RST/S0) on a Windows host. Within a short window the host changes firewall state (WFP rule added/modified or service starts listening) and then the same source completes the first successful handshake to the newly opened port.', '{Windows}', 'x-mitre-analytic--22ff1717-6ba8-4908-b795-edf0c41a997e', 'DET0302', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Microsoft-Windows-Windows Firewall With Advanced Security/Firewall", "channel": "EventCode=2004, 2005, 2006", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "Seconds to correlate knock sequence → rule change → successful connect (60–300s typical)."}, {"field": "MinSequenceLen", "description": "Minimum number of distinct destination ports in the sequence (≥3 by default)."}, {"field": "RuleChangeAllowList", "description": "Accounts/processes allowed to adjust Windows Firewall (e.g., update agents)."}, {"field": "WatchedPorts", "description": "Ports of interest to flag when opened (e.g., 22,23,2323,8022,3389,8080)."}]', '2026-05-01 15:26:34.734609');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (254, 'AN0500', 'Analytic 0500', 'Correlated evidence where Safari/Chrome/WebKit-based processes issue network requests for uncommon or obfuscated JS resources followed by spawning of script interpreters, launchd or ad-hoc binaries, unusual child processes, or dynamic library loads into browser processes. Defender sees: proxy/HTTP logs with suspicious resource content + unifiedlogs/ASL showing browser/plugin crashes or extension loads + process events indicating child process creation and file writes to /var/folders or /tmp shortly after the fetch.', '{macOS}', 'x-mitre-analytic--230a55ce-4584-4588-a006-5532a9efdbd8', 'DET0176', '[{"name": "macos:unifiedlog", "channel": "Logs from unifiedlogging that show browser crashes, plugin enumerations, extension installs or errors around the same time as suspicious network fetches", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "process_create: Process creation where parent is Safari/Google Chrome and child is script interpreter or signed-but-unusual helper binary", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "New files written to /var/folders, /tmp, ~/Library/Caches, or ~/Downloads by browser context or its children", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "HTTP/HTTPS requests for script resources flagged by content inspection (excessive obfuscation, eval usage, unusual redirects)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:unifiedlog", "channel": "Anomalous dyld dynamic library loads or RWX memory mappings in browser process", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "SleepyUserThreshold", "description": "Volume thresholds for interactive user browsing vs. automated systems (e.g., shared kiosks) — tune to reduce FP in heavy-browsing employees."}, {"field": "ExtensionInstallPolicy", "description": "Policy setting that influences how extension installs are treated: strict policy reduces FP from known extension behavior."}]', '2026-05-01 15:26:34.735817');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (255, 'AN1948', 'Analytic 1948', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (256, 'AN1025', 'Analytic 1025', 'Detection of domain group enumeration through command-line utilities such as ''net group /domain'' or PowerShell cmdlets, followed by suspicious access to API calls or LSASS memory.', '{Windows}', 'x-mitre-analytic--2385f397-5d17-4b37-ba07-bb52a52ff66c', 'DET0360', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindow", "description": "Adjustable window to track chained discovery activity (e.g., 5-10 minutes)."}, {"field": "UserContext", "description": "Tune to focus on non-admin users or service accounts performing enumeration."}, {"field": "ProcessLineageDepth", "description": "How far back the parent-child process chain is correlated."}]', '2026-05-01 15:26:34.738427');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (257, 'AN0557', 'Analytic 0557', 'Monitor sensitive data files such as plist-based storage, mail archives, or Office files for unexpected modifications. Detect anomalous processes modifying stored data outside expected update cycles using FSEvents and Unified Logs.', '{macOS}', 'x-mitre-analytic--23b6aee9-90fc-46b8-bf8b-36043218f393', 'DET0193', '[{"name": "macos:unifiedlog", "channel": "Unexpected creation or modification of stored data files in protected directories", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:osquery", "channel": "CREATE, DELETE, WRITE: Stored data manipulation attempts by unauthorized processes", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "FileIntegrityBaseline", "description": "Baseline hash values or metadata for stored data files to detect manipulation."}, {"field": "AllowedEditors", "description": "Whitelisted applications permitted to update stored data (e.g., Outlook, MySQL)."}]', '2026-05-01 15:26:34.740043');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (258, 'AN1106', 'Analytic 1106', 'Token creation or access delegation where a user impersonates a higher-privileged service account or performs domain-wide delegation actions, such as GCP''s serviceAccountTokenCreator or Workspace impersonation.', '{"Identity Provider"}', 'x-mitre-analytic--23b9a5cd-9c49-48d8-9d0d-71e35ad78337', 'DET0393', '[{"name": "gcp:iam", "channel": "PrincipalEmail with serviceAccountTokenCreator impersonating new identity", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "gcp:workspaceaudit", "channel": "Token Generation via Domain Delegation", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "userEmailFilter", "description": "Tune based on legitimate service accounts allowed to impersonate user accounts."}, {"field": "delegatedScope", "description": "Limit delegated access to specific scopes relevant to business functions."}]', '2026-05-01 15:26:34.741577');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (259, 'AN2007', 'Analytic 2007', 'Consider analyzing code signing certificates for features that may be associated with the adversary and/or their developers, such as the thumbprint, algorithm used, validity period, common name, and certificate authority. Malware repositories can also be used to identify additional samples associated with the adversary and identify patterns an adversary has used in procuring code signing certificates.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (260, 'AN1268', 'Analytic 1268', 'Credential stuffing attempts against Kubernetes API or containerized login shells using stolen or leaked user credentials', '{Containers}', 'x-mitre-analytic--23c7fff8-de08-49dd-a101-0c35ad40bd7e', 'DET0460', '[{"name": "kubernetes:apiserver", "channel": "authentication.k8s.io/v1beta1", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "PodAccessScope", "description": "Detect attempts across multiple pods/namespaces using same IP"}, {"field": "CredentialSetSize", "description": "Number of username/password pairs used in attack attempt"}]', '2026-05-01 15:26:34.7443');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (267, 'AN1614', 'Analytic 1614', 'Detection of account enumeration through directory service queries or system utilities accessing account metadata stores, followed by structured enumeration output.', '{macOS}', 'x-mitre-analytic--24aa5ee9-ba7f-4991-b32a-27d40ee2d010', 'DET0587', '[{"name": "macos:unifiedlog", "channel": "process event", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "DirectoryService queries retrieving account information", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "CommandLine", "description": "Tune for dscl -list, dscacheutil -q user, id -un, etc."}, {"field": "ExecutionContext", "description": "Alert if enumeration is performed in non-console session or by unusual users."}]', '2026-05-01 15:26:34.753949');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (261, 'AN0968', 'Analytic 0968', 'Execution of hh.exe to open a .chm file followed by suspicious child processes or script engine invocation (VBScript, JScript, mshta, powershell). Behavior includes loading a CHM file from untrusted locations, or immediately spawning commands indicative of payload execution.', '{Windows}', 'x-mitre-analytic--23e84bf6-70d1-4c49-97b8-0fff9c6efa8f', 'DET0342', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "CHMPathRegex", "description": "Regex matching CHM file locations; tune to exclude trusted internal software help files"}, {"field": "ChildProcessList", "description": "List of suspicious children of hh.exe (powershell.exe, cmd.exe, mshta.exe, wscript.exe)"}, {"field": "NetworkDestinationAllowlist", "description": "Filter for legitimate update/help servers accessed by hh.exe"}, {"field": "TimeWindow", "description": "Threshold time between hh.exe execution and suspicious follow-on activity"}]', '2026-05-01 15:26:34.745849');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (262, 'AN1027', 'Analytic 1027', 'Enumeration of domain groups using dscacheutil or dscl commands, often following initial login or domain trust queries.', '{macOS}', 'x-mitre-analytic--23fa40ac-79d0-400a-a017-8e06cfc67e6c', 'DET0360', '[{"name": "macos:unifiedlog", "channel": "process events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandSignatureThreshold", "description": "Defines how strictly command patterns must match known enumeration syntax."}, {"field": "TimeWindow", "description": "Adjustable window to correlate chained behavior such as group enumeration followed by user targeting."}]', '2026-05-01 15:26:34.747066');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (263, 'AN1944', 'Analytic 1944', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (264, 'AN1021', 'Analytic 1021', 'Tools such as `tor`, `nglite`, `proxychains`, `chisel`, or custom daemons repeatedly initiate outbound sessions to multiple nodes before final destination. This behavior is abnormal for Linux services outside of VPN, monitoring, or CDN relay contexts.', '{Linux}', 'x-mitre-analytic--2416a634-3ad9-4f91-a894-8fb0d9d83b76', 'DET0359', '[{"name": "auditd:SYSCALL", "channel": "execve for proxy tools", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "conn.log + ssl.log with Tor fingerprinting", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "Netfilter/iptables", "channel": "Forwarded packets log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ExecutablePath", "description": "Match known proxy tools, tuned for environment."}, {"field": "RelayCount", "description": "Detect outbound chaining behavior through >2 IPs in short succession."}, {"field": "ProtocolType", "description": "Allow filtering by ICMP, TCP/443, UDP for obfuscation channels."}]', '2026-05-01 15:26:34.750084');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (265, 'AN0838', 'Analytic 0838', 'Detect anomalous chains of memory allocation and execution inside the same process (e.g., VirtualAlloc → memcpy → VirtualProtect → CreateThread). Unlike process injection, reflective code loading does not perform cross-process memory writes — the suspicious activity occurs entirely within the process’s own PID context.', '{Windows}', 'x-mitre-analytic--2432f5a3-ddae-4138-9981-f916ad23a1e1', 'DET0300', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "etw:Microsoft-Windows-DotNETRuntime", "channel": "AssemblyLoad/ModuleLoad (Loader keyword) from Microsoft-Windows-DotNETRuntime", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "etw:Microsoft-Antimalware-Scan-Interface", "channel": "Amsi/Script content + API verdicts during in-memory staging", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "ParentProcessWhitelist", "description": "Certain processes may legitimately use Assembly.Load(); defenders may whitelist known developer/admin tools."}, {"field": "MemoryRegionPermissions", "description": "Detection logic can tune for RWX memory allocations; some legitimate tools may allocate with RW permissions only."}]', '2026-05-01 15:26:34.751353');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (266, 'AN0609', 'Analytic 0609', 'Unusual modifications to service binary paths, registry keys, or DLL load paths resulting in alternate execution flow. Defender observes registry key modifications, suspicious file writes into system directories, and processes loading libraries from abnormal paths.', '{Windows}', 'x-mitre-analytic--248be939-35f5-4c8a-9e21-b6de514da577', 'DET0218', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ServiceBaseline", "description": "Expected registry keys and service paths for comparison."}, {"field": "AllowedDllPaths", "description": "Directories considered valid for DLL loading."}, {"field": "TimeWindow", "description": "Correlation interval between registry/file modification and process execution."}]', '2026-05-01 15:26:34.752719');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1302, 'AN1044', 'Analytic 1044', 'Execution of file discovery commands (e.g., ''dir'', ''show flash'', ''nvram:'') from CLI interfaces, especially by unauthorized users or from abnormal source IPs.', '{"Network Devices"}', 'x-mitre-analytic--be6e5f23-0e29-430f-83f7-d76c58de3a2d', 'DET0370', '[{"name": "networkdevice:syslog", "channel": "CLI Command Logging", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandWhitelist", "description": "Filter allowed commands by account or IP"}, {"field": "SessionOrigin", "description": "Tunable to restrict detection to remote terminal or Telnet/SSH"}]', '2026-05-01 15:26:36.304978');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (268, 'AN0517', 'Analytic 0517', 'Monitor scp, rsync, curl, sftp, or ftp processes initiating transfers to internal systems combined with file creation events in unusual directories. Correlate transfer activity with subsequent execution of those binaries.', '{Linux}', 'x-mitre-analytic--24af9441-602e-4202-a2e7-04a46c008406', 'DET0183', '[{"name": "auditd:SYSCALL", "channel": "execve: Invocation of scp, rsync, curl, or sftp", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:FILE", "channel": "create: New file created in system binaries or temp directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AllowedTools", "description": "Define legitimate transfer utilities expected in the environment"}, {"field": "DestinationDirectories", "description": "Restrict to suspicious or non-standard directories for transferred files"}]', '2026-05-01 15:26:34.755168');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (269, 'AN1963', 'Analytic 1963', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (270, 'AN1265', 'Analytic 1265', 'Same source IP performing multiple authentication attempts using known breached username/password combinations across different identities in Azure AD, Okta, or Duo', '{"Identity Provider"}', 'x-mitre-analytic--24e6cefb-6e1c-4676-9bb8-74f6a731703c', 'DET0460', '[{"name": "azure:signinlogs", "channel": "status = failure", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "BreachedCredentialSourceMatch", "description": "Optional enrichment using known leaked credentials database"}, {"field": "SSOServiceScope", "description": "Targeting only federated or hybrid identity auth flows"}]', '2026-05-01 15:26:34.758591');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (271, 'AN0796', 'Analytic 0796', 'Monitor Office Suite applications (Outlook, Word mail merge, Excel macros) for abnormal automated message sending, especially when macros or scripts trigger email delivery. Detect patterns of impersonation language (urgent, payment, executive request) combined with anomalous execution of Office macros.', '{"Office Suite"}', 'x-mitre-analytic--250d2977-7b94-4041-a299-0f2f1532eb95', 'DET0286', '[{"name": "m365:unified", "channel": "SendOnBehalf/SendAs: Office Suite initiated messages using impersonated identities", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MacroExecutionThreshold", "description": "Threshold for correlating macro execution with email sending activity."}]', '2026-05-01 15:26:34.760026');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (272, 'AN0432', 'Analytic 0432', 'Process/script execution of systemsetup -gettimezone, date, ioreg, or API usage (timeIntervalSinceNow, gettimeofday) followed by time-based scheduling (launchd plist modification) or sleep-based execution.', '{macOS}', 'x-mitre-analytic--252e5c07-8ae0-4ef8-9a98-c11b6c6d4d46', 'DET0151', '[{"name": "macos:unifiedlog", "channel": "process exec events of systemsetup, date, ioreg with command_line parameters indicating time discovery", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "New/modified launchd plist (persistence/scheduling) within TimeWindow after time query", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}]', '[{"field": "LaunchdPaths", "description": "Organization-specific list of allowed launchd write locations to filter benign agents."}, {"field": "TimeWindow", "description": "Correlation window to link time discovery to launchd persistence/scheduling."}, {"field": "AllowedCallers", "description": "Known management agents (e.g., JAMF) that legitimately call systemsetup/date."}]', '2026-05-01 15:26:34.761314');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (273, 'AN0879', 'Analytic 0879', 'Detects execution of capture commands via CLI (`monitor capture`, `debug packet`, etc.) or unauthorized CLI access followed by logging configuration changes on Cisco/Juniper/Arista gear.', '{"Network Devices"}', 'x-mitre-analytic--25403649-ce66-4fb0-9957-8c319b10e9d7', 'DET0314', '[{"name": "networkdevice:syslog", "channel": "admin login events", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "networkdevice:syslog", "channel": "exec command=''monitor capture''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "config change (e.g., logging buffered, pcap buffers)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AdminSessionDuration", "description": "Tunable alerting threshold for interactive CLI sessions."}, {"field": "CaptureCommandList", "description": "Define set of known capture/debug commands per vendor to flag unexpected usage."}]', '2026-05-01 15:26:34.76261');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (274, 'AN2062', 'Analytic 2062', 'Much of this takes place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (275, 'AN1051', 'Analytic 1051', 'Detection of anomalous or unauthorized mailbox delegation activity (e.g., Add-MailboxPermission, Default/Anonymous mailbox permissions, Gmail delegation setup).', '{"Office Suite"}', 'x-mitre-analytic--25bd8222-a9c0-4771-8250-7d6ce7b2d176', 'DET0373', '[{"name": "m365:unified", "channel": "Add-MailboxPermission, UpdateFolderPermissions", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "DelegatePermissionLevel", "description": "Threshold for unexpected delegate roles such as FullAccess or SendAs."}, {"field": "FolderTargetScope", "description": "Mailbox folder targeted by delegation (Inbox, Root, Calendar, etc.)."}, {"field": "DelegatorToDelegatePairing", "description": "Pairings of delegate and delegator users that are expected."}, {"field": "MailflowAnomalyThreshold", "description": "Spike in outbound mail after delegate addition, used to catch phishing or mass exfil."}]', '2026-05-01 15:26:34.765228');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (282, 'AN1154', 'Analytic 1154', 'Reading of sensitive files like .bash_history, /etc/shadow, or private key directories by unauthorized users or unusual processes.', '{Linux}', 'x-mitre-analytic--27213df4-c761-4745-b8ef-f91a46966eb9', 'DET0412', '[{"name": "auditd:SYSCALL", "channel": "open/read system calls to ~/.bash_history or /etc/shadow", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execution of tools like cat, grep, or awk on credential files", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SensitivePaths", "description": "Paths to credential files such as /etc/shadow or ~/.bash_history"}, {"field": "UserContext", "description": "Whether the process runs under a privileged or non-interactive session"}]', '2026-05-01 15:26:34.776297');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (276, 'AN0322', 'Analytic 0322', 'Phishing attempts via iCloud Mail, Gmail, or social media apps accessed on macOS systems. Defender view includes Mail.app or Safari downloads of files followed by osascript, Terminal, or abnormal child process execution.', '{macOS}', 'x-mitre-analytic--262ce2a7-2c09-4f6d-8e9f-de57b814a2a2', 'DET0115', '[{"name": "macos:unifiedlog", "channel": "Received messages containing embedded links or attachments from non-enterprise services", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "Execution of osascript, bash, or Terminal initiated from Mail.app or Safari", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Suspicious outbound HTTPS requests to domains flagged as newly registered or untrusted after spearphishing message interaction", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CertificateChecks", "description": "Flagging mismatched or self-signed certificates during outbound connections initiated after spearphishing messages."}, {"field": "ExecutionDelay", "description": "Window of time between attachment download and subsequent suspicious execution."}]', '2026-05-01 15:26:34.767462');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (277, 'AN0735', 'Analytic 0735', 'Detects Node.js or JavaScript interpreter execution from web shells, cron jobs, or local users. Correlates execution with reverse shell behavior, file modifications, or abnormal outbound connections.', '{Linux}', 'x-mitre-analytic--26520d1c-1e0a-443b-817e-7ec1846a0476', 'DET0264', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "/var/log/syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "ScriptPath", "description": "Script launched from /tmp, /var/tmp, or hidden dot directories."}, {"field": "BinaryName", "description": "Custom compiled JS binaries like node_shell or interpreter disguises."}, {"field": "UserExecutionContext", "description": "Execution by service accounts or low-privilege users running cron scripts."}, {"field": "NetworkFollowUp", "description": "Connection attempts to C2 post-node.js execution."}]', '2026-05-01 15:26:34.768809');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (278, 'AN1418', 'Analytic 1418', 'Detects access to SSSD or Quest VAS cached credential databases using tdbdump or other file access patterns, requiring sudo/root access.', '{Linux}', 'x-mitre-analytic--26940057-e464-49f9-8f76-ceaca4b9d982', 'DET0513', '[{"name": "auditd:SYSCALL", "channel": "file", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:EXECVE", "channel": "EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "filepath", "description": "SSSD and Quest cache paths differ by deployment and OS variant."}, {"field": "CommandLine", "description": "Tunable to capture specific tools (e.g., tdbdump, cat) or scripts accessing cache files."}, {"field": "TimeWindow", "description": "Time between elevation and file access can be adjusted to account for legitimate system behavior."}]', '2026-05-01 15:26:34.770149');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (279, 'AN1224', 'Analytic 1224', 'Detects execution patterns where a child process is detached from its original parent, often showing up under ''launchd'' (PID 1) with no parent lineage. These breakages in the process tree are indicative of evasive techniques using `daemon()`, `fork()` or background execution flags.', '{macOS}', 'x-mitre-analytic--269ab5e4-4c45-4f7a-8d82-c235492ff83a', 'DET0443', '[{"name": "macos:unifiedlog", "channel": "Process creation with parent PID of 1 (launchd)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "Detached process execution with no associated parent", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "AnomalyParentPID", "description": "Triggering PID used to flag abnormal child adoption (commonly PID 1)"}, {"field": "AllowedServices", "description": "Allowlist of background daemons legitimately using launchd as parent"}, {"field": "ProcessNameEntropy", "description": "Entropy score threshold for abnormal process names in detached state"}]', '2026-05-01 15:26:34.771477');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (280, 'AN1138', 'Analytic 1138', 'Detects interactive or service logins from local accounts outside expected operational context or at anomalous times.', '{Linux}', 'x-mitre-analytic--269f36b6-77fa-4959-9e63-e30036c991d7', 'DET0407', '[{"name": "auditd:USER_LOGIN", "channel": "USER_LOGIN", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "linux:auth", "channel": "sshd login", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Define operational hours or expected login times per host."}, {"field": "HostRole", "description": "Differentiate expected behavior for server vs. workstation."}]', '2026-05-01 15:26:34.773034');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (281, 'AN0822', 'Analytic 0822', 'Detects hijacking of an existing thread (OpenThread) through a behavioral chain involving thread suspension (SuspendThread), memory modification (VirtualAllocEx + WriteProcessMemory), context manipulation (SetThreadContext), and thread resumption—all within another live process''s address space (ResumeThread).', '{Windows}', 'x-mitre-analytic--26ef9aef-33eb-4df2-ba82-6ace95173c80', 'DET0295', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "API Calls", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetProcessList", "description": "Sensitive processes that should never be targeted for thread hijack attempts"}, {"field": "TimeWindow", "description": "Expected delay between SuspendThread and ResumeThread events; tight thresholds reduce evasion"}, {"field": "SuspiciousThreadContextRegions", "description": "Memory regions or offsets that should not be targeted for SetThreadContext"}, {"field": "ParentProcessAnomalyThreshold", "description": "Score deviation of the parent/child relationship in a thread injection chain"}]', '2026-05-01 15:26:34.774937');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (283, 'AN0227', 'Analytic 0227', 'Execution of trusted system binaries (e.g., `split`, `tee`, `bash`, `env`) used in uncommon sequences or chained behaviors to execute malicious payloads or perform actions inconsistent with normal system or script behavior.', '{Linux}', 'x-mitre-analytic--273d7b27-6b7d-4017-a7f6-0cd02fd3a128', 'DET0081', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TrustedBinaryList", "description": "Binaries like `split`, `tee`, `env`, `awk`, `gzip`, often used in benign scripts"}, {"field": "AnomalyScore", "description": "Outlier model for process tree and command arguments"}]', '2026-05-01 15:26:34.777655');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (284, 'AN0486', 'Analytic 0486', 'Forged cookies on macOS may show up as abnormal access to Safari/Chrome cookie databases in ~/Library/Cookies, combined with unexpected logon sessions authenticated by those cookies. Unified Logs may show cookie injection events or abnormal access patterns to Keychain when linked to browser authentication flows.', '{macOS}', 'x-mitre-analytic--27a0146c-0af8-4323-9c41-fbd3df9af1fa', 'DET0171', '[{"name": "macos:unifiedlog", "channel": "Abnormal process access to Safari or Chrome cookie storage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "New session initiated using cookies without normal MFA or password validation", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}]', '[{"field": "AuthorizedKeychainApps", "description": "Applications permitted to use Keychain to generate cookies or tokens."}]', '2026-05-01 15:26:34.779304');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (285, 'AN0100', 'Analytic 0100', 'Suspicious processes initiating encrypted HTTPS connections to common web service domains, followed by abnormal data upload behavior or automated posting behavior indicative of C2 bidirectional traffic.', '{Windows}', 'x-mitre-analytic--27bd3e33-9a61-4dfb-9fba-205a6c880264', 'DET0035', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "etw:Microsoft-Windows-WinINet", "channel": "HTTPS Inspection", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Timeframe for evaluating multiple network connections tied to the same process"}, {"field": "DomainPattern", "description": "Regex or string patterns used to identify common Web service infrastructure (e.g., *.googleapis.com)"}, {"field": "PayloadSizeThreshold", "description": "Minimum data upload size before flagging anomaly"}, {"field": "ProcessNameExclusionList", "description": "Known benign updaters or service processes to reduce false positives"}]', '2026-05-01 15:26:34.780695');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (286, 'AN0727', 'Analytic 0727', 'Detects local staging behavior via snapshot creation or files written into VMFS partitions by scripts or unauthorized shell access.', '{ESXi}', 'x-mitre-analytic--27caeb90-1cf0-4650-a3f3-c8a1edaecbab', 'DET0261', '[{"name": "esxi:vmkernel", "channel": "snapshot create/write events", "x_mitre_data_component_ref": "x-mitre-data-component--3da222e6-53f3-451c-a239-0b405c009432"}, {"name": "esxi:shell", "channel": "CLI usage logs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SnapshotThreshold", "description": "Rapid creation or deletion of snapshots"}, {"field": "CLIInvoker", "description": "Unexpected CLI/script invocation outside maintenance windows"}, {"field": "VMFSWriteRate", "description": "Volume of data written locally in short time"}]', '2026-05-01 15:26:34.782065');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (287, 'AN0672', 'Analytic 0672', 'Monitor for file access to certificate directories, commands invoking OpenSSL or PKCS#12 utilities to export or modify certificates, and processes accessing sensitive key storage paths.', '{Linux}', 'x-mitre-analytic--27cbe2a7-25a0-4f6d-b2b0-dff50b2c0883', 'DET0240', '[{"name": "auditd:SYSCALL", "channel": "open, read: /etc/ssl/, /etc/pki/, ~/.pki/nssdb/", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execve: openssl pkcs12, certutil, keytool", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "PathExclusions", "description": "Exempt trusted automated services regularly accessing PKI stores."}, {"field": "UserContext", "description": "Differentiate root/system accounts versus user-level access to key material."}]', '2026-05-01 15:26:34.783294');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (288, 'AN1249', 'Analytic 1249', 'Defenders may observe suspicious SNMP MIB enumeration through abnormal queries for large sets of OIDs, repeated SNMP GETBULK/GETNEXT requests, or queries originating from non-administrative IP addresses. Anomalous use of community strings, authentication failures, or enumeration activity outside maintenance windows may also indicate attempts to dump MIB contents. Correlation across syslog, NetFlow, and SNMP audit data can reveal chains of behavior such as repeated authentication failures followed by successful large-scale OID retrieval.', '{"Network Devices"}', 'x-mitre-analytic--282d9231-942a-4b97-875c-659aa2c41971', 'DET0453', '[{"name": "networkdevice:syslog", "channel": "Authentication failures, unexpected community string usage, or unauthorized SNMPv1/v2 requests", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "High-volume or repeated SNMP GETBULK/GETNEXT queries from untrusted or external IPs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "networkdevice:audit", "channel": "SNMP configuration changes, such as enabling read/write access or modifying community strings", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "AuthorizedAdminIPs", "description": "Expected IP ranges allowed to query SNMP. Deviation indicates possible misuse."}, {"field": "NormalSNMPQueryRate", "description": "Baseline frequency and volume of SNMP queries; anomalies above threshold may indicate dumping."}, {"field": "CommunityStringPatterns", "description": "Expected community strings (e.g., hashed or custom values). Unrecognized strings may signal abuse."}, {"field": "TimeWindow", "description": "Time periods during which SNMP queries are authorized. Queries outside these hours may be malicious."}]', '2026-05-01 15:26:34.784493');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (289, 'AN1497', 'Analytic 1497', 'Processes (e.g., bash, python, custom binaries) dynamically linking libcrypto/libssl for RSA key exchange, then creating external connections with abnormal certificate validation or handshake anomalies. Defender observes syscall traces and outbound asymmetric key exchanges from non-SSL-native processes.', '{Linux}', 'x-mitre-analytic--284edcb8-0141-4fe6-afb2-9fd8a2b82b49', 'DET0543', '[{"name": "auditd:SYSCALL", "channel": "execve or socket/connect system calls for processes using RSA handshake", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Non-standard processes negotiating SSL/TLS key exchanges", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "linux:osquery", "channel": "Processes linked with libssl/libcrypto performing network activity", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ExpectedCryptoLibs", "description": "Baseline libraries that normally handle asymmetric crypto."}, {"field": "TrafficAsymmetryRatio", "description": "Threshold for client-heavy data sending vs server."}]', '2026-05-01 15:26:34.785745');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (290, 'AN1058', 'Analytic 1058', 'Detects use of network scanning utilities or scripts performing rapid connections to multiple services or hosts using auditd and netflow/pcap telemetry.', '{Linux}', 'x-mitre-analytic--287661d0-714e-4bb4-a9f7-c272ad0018b1', 'DET0376', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Outbound TCP SYN or UDP to multiple ports/hosts", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "PortScanThreshold", "description": "Defines number of ports targeted per host within a short period."}, {"field": "ToolPatternRegex", "description": "Regex to match common scanner arguments (e.g., `nmap -sS`, `nc -zv`)."}, {"field": "ExpectedScanSources", "description": "Trusted IPs or systems performing routine discovery."}]', '2026-05-01 15:26:34.786989');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (291, 'AN1407', 'Analytic 1407', 'Detects suspicious SVG file creation or download events followed by script engine execution (e.g., wscript.exe, mshta.exe, rundll32.exe), network callbacks, or browser-based credential collection.', '{Windows}', 'x-mitre-analytic--288a28ac-e1e4-4e7e-9156-d3b975ed45ed', 'DET0510', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Threshold between SVG file write and script execution (e.g., < 60s)"}, {"field": "ParentProcessWhitelist", "description": "Allowlisted script engines that may invoke browsers or JS in benign cases"}, {"field": "FileExtensionPattern", "description": "Regex or string match for .svg, .svgz, or embedded .svg inside HTML or PDF"}]', '2026-05-01 15:26:34.788201');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (292, 'AN0196', 'Analytic 0196', 'Detects rsync or scp inbound from other hosts that then aggregate content into /Users/Shared or /private/tmp, often involving compressed files or scripts.', '{macOS}', 'x-mitre-analytic--2891bd53-5a81-4330-bb05-ffd731868d06', 'DET0071', '[{"name": "macos:unifiedlog", "channel": "exec logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "file events", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "remote login and transfer", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "StagingPaths", "description": "Monitored remote-to-local write destinations such as /Users/Shared"}, {"field": "CompressionIndicators", "description": "Presence of .zip, .7z, or tar.gz indicating consolidation"}, {"field": "TimeWindow", "description": "Temporal correlation of transfer and staging write operations"}]', '2026-05-01 15:26:34.789697');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (293, 'AN0988', 'Analytic 0988', 'Identifies suspicious outbound traffic volume mismatches from processes that typically do not generate network activity, particularly over C2 protocols like HTTPS, DNS, or custom TCP/UDP ports, following file or data access.', '{Windows}', 'x-mitre-analytic--28c16139-9ce1-4dd7-b26a-e257f37e246c', 'DET0348', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Flow/PCAP analysis for outbound payloads", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "DataVolumeThreshold", "description": "Set threshold for outbound transfer size exceeding typical C2 traffic (e.g., >1MB in <5min)."}, {"field": "KnownBenignProcesses", "description": "List of approved processes that may exhibit high outbound traffic (e.g., updates)."}]', '2026-05-01 15:26:34.791366');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (294, 'AN1048', 'Analytic 1048', 'Correlated use of sleep/delay mechanisms (e.g., kernel32!Sleep, NTDLL APIs) in short-lived processes, combined with parent processes invoking suspicious scripts (e.g., wscript, powershell) with minimal user interaction.', '{Windows}', 'x-mitre-analytic--28e26a6a-e470-4f1c-845f-f2cbd816a1f7', 'DET0372', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TimeWindow", "description": "Delay duration that distinguishes benign scripts from evasive behavior."}, {"field": "ParentProcessName", "description": "Legitimate parent-child combinations may differ across environments."}, {"field": "SleepFunctionPattern", "description": "Different APIs may be used to invoke sleep (e.g., Sleep, NtDelayExecution)."}]', '2026-05-01 15:26:34.793778');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (295, 'AN1059', 'Analytic 1059', 'Detects Bonjour-based mDNS enumeration or use of system tools (e.g., dns-sd, nmap) to find active services via multicast probing or targeted scans.', '{macOS}', 'x-mitre-analytic--28fbe1b0-9663-4997-9d4e-ef43803be114', 'DET0376', '[{"name": "macos:unifiedlog", "channel": "dns-sd, mDNSResponder, socket activity", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MDNSServiceQueryPatterns", "description": "mDNS queries such as _ssh._tcp.local that may indicate service discovery."}, {"field": "UserContext", "description": "Adjust alerting based on whether discovery activity originates from a background daemon vs. interactive session."}, {"field": "ScanToolList", "description": "Expected tools that could trigger mDNS or TCP/UDP scans (e.g., dns-sd, nmap)."}]', '2026-05-01 15:26:34.795315');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (309, 'AN1084', 'Analytic 1084', 'Detects Unix shell usage on network appliances (e.g., routers, firewalls, embedded Linux) through rare console commands, CLI interfaces, or script injection via exposed APIs or SSH.', '{"Network Devices"}', 'x-mitre-analytic--2adf0c92-5d0a-459d-affc-f4abd4d406d0', 'DET0384', '[{"name": "networkdevice:syslog", "channel": "CLI Command Audit", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "remote access", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "Interface", "description": "Flags command line access via remote console (telnet/SSH/API) from non-whitelisted source."}, {"field": "CommandString", "description": "Monitors rare/privileged shell commands (e.g., enable, tftp, firmware mod)."}]', '2026-05-01 15:26:34.814436');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (296, 'AN0650', 'Analytic 0650', 'Unsigned processes accessing system memory or launching known credential scraping tools (e.g., osascript, dylib injections) to access the Keychain or sensitive memory regions.', '{macOS}', 'x-mitre-analytic--29370f2b-0877-458c-8ade-a9a23b8fb7b2', 'DET0234', '[{"name": "macos:unifiedlog", "channel": "Code Execution & Entitlement Access", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "macos:keychain", "channel": "Access to Keychain DB or system.keychain", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "Invocation of osascript or dylib injection", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "KeychainAccessPath", "description": "Path to watch for abnormal access, e.g., /Library/Keychains/"}, {"field": "SignedBinaryStatus", "description": "Filter out signed/trusted binaries."}]', '2026-05-01 15:26:34.797013');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (297, 'AN0531', 'Analytic 0531', 'Automated execution of native utilities and scripts to discover, enumerate, and exfiltrate files and clipboard content. Focus is on detecting repeated file access, scripting engine use, and use of command-line utilities commonly leveraged by collection scripts.', '{Windows}', 'x-mitre-analytic--29433de9-360e-4189-9f6d-fb00c9a57e41', 'DET0186', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "TimeWindow", "description": "Defines the lookback period for identifying burst activity or patterns in process/file events."}, {"field": "SuspiciousFileExtensions", "description": "Tunable list of file extensions associated with collection (e.g., .pdf, .docx)."}, {"field": "ProcessCountThreshold", "description": "The number of times a process executes before considered anomalous."}]', '2026-05-01 15:26:34.798173');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (298, 'AN1245', 'Analytic 1245', 'Defenders can identify PowerShell profile-based persistence by correlating file creation or modification in known profile locations with subsequent PowerShell process launches that do not use the `-NoProfile` flag. Profile scripts loading unusual modules or launching external programs, particularly under elevated contexts, are suspicious and may represent adversary persistence or privilege escalation.', '{Windows}', 'x-mitre-analytic--298d1a46-ec12-4cd2-acce-7e0f849c384d', 'DET0451', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "Execution of PowerShell without -NoProfile flag", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ProfilePathList", "description": "Custom PowerShell host profiles or redirection to alternate profile paths"}, {"field": "ExecutionContext", "description": "Whether profile execution occurs under elevated user (e.g., Administrator, SYSTEM)"}, {"field": "ModuleOrScriptName", "description": "Specific modules or external programs loaded within profile"}, {"field": "TimeWindow", "description": "Correlation time between profile modification and PowerShell process start"}]', '2026-05-01 15:26:34.799348');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (299, 'AN0351', 'Analytic 0351', 'Insertion of public keys into authorized_keys using bash/zsh or editor tools, correlated with suspicious process ancestry.', '{macOS}', 'x-mitre-analytic--29988e3f-2f65-4fe5-9bf7-dae0cb869fc6', 'DET0126', '[{"name": "macos:unifiedlog", "channel": "process: exec + filewrite: ~/.ssh/authorized_keys", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:auth", "channel": "~/.ssh/authorized_keys", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "ParentProcess", "description": "Track unusual parent process writing to SSH config (e.g., curl -> bash)"}, {"field": "InteractiveSessionFlag", "description": "Flag whether shell session was interactive (normal) or spawned remotely (potential abuse)"}]', '2026-05-01 15:26:34.800488');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (300, 'AN0763', 'Analytic 0763', 'Unusual TLS tunnels through ports not normally encrypted (e.g., TLS on port 8080, 53). Defender sees NetFlow/IPFIX or packet inspection indicating high-entropy traffic volumes and asymmetric client/server exchange ratios.', '{"Network Devices"}', 'x-mitre-analytic--29a00bef-79bd-4eb9-bf92-01651cffe9b0', 'DET0273', '[{"name": "NSM:Flow", "channel": "Session records with TLS-like byte patterns", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Connections", "channel": "Abnormal certificate chains or non-standard ports carrying TLS", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "PortProfiles", "description": "Define expected TLS port usage to flag anomalies."}, {"field": "TrafficAsymmetryRatio", "description": "Sent/received byte thresholds to catch hidden C2."}]', '2026-05-01 15:26:34.801617');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (301, 'AN2032', 'Analytic 2032', 'Observation of scripted network requests (e.g., using osascript, curl, or python) that include mismatched or spoofed browser User-Agent strings compared to the typical macOS Safari or Chrome baseline, especially when triggered by non-interactive launch agents, login hooks, or background daemons.', '{macOS}', 'x-mitre-analytic--29ca0e06-e848-44cd-821a-24576276a8af', 'DET0898', '[{"name": "macos:unifiedlog", "channel": "network connection events", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Inbound HTTP POST with suspicious payload size or user-agent", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:unifiedlog", "channel": "exec logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserAgentFingerprint", "description": "Flag browser-based sessions"}, {"field": "HeaderSignatureMatch", "description": "Specific HTTP header anomalies or patterns (e.g., spoofed User-Agent)."}]', '2026-05-01 15:26:34.802796');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (612, 'AN1510', 'Analytic 1510', 'Use of ESXi web interface plugins or vSphere extensions to embed persistent malicious scripts or services.', '{ESXi}', 'x-mitre-analytic--55b8622a-795b-41d8-9b11-5576a0fb8f0f', 'DET0547', '[{"name": "esxi:hostd", "channel": "New extension/module install with unknown vendor ID", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "esxi:vmkernel", "channel": "Unexpected restarts of management agents or shell access", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "PluginVendorName", "description": "Whitelist known vendor plug-in names for extension correlation"}, {"field": "AccessVector", "description": "Limit exposure of plugin installation via HTTPS or SSH"}]', '2026-05-01 15:26:35.261027');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (302, 'AN0190', 'Analytic 0190', 'Detection of phishing through anomalous Mail app activity, such as attachments saved to disk and immediately executed, or Safari/Preview launching URLs and files linked from email messages. Correlate UnifiedLogs events with subsequent process execution.', '{macOS}', 'x-mitre-analytic--2a0cc1a9-db3b-4f05-8c85-29d69507418b', 'DET0070', '[{"name": "macos:unifiedlog", "channel": "Inbound email activity with suspicious domains or mismatched sender information", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "Preview.app, Safari.app, or Mail.app spawning new processes outside normal patterns", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SuspiciousDomains", "description": "List of domains known for phishing activity or suspicious sender infrastructure."}, {"field": "ExecutionDelayWindow", "description": "Time threshold between file save and execution considered suspicious."}]', '2026-05-01 15:26:34.80404');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (303, 'AN1465', 'Analytic 1465', 'Unusual or suspicious processes loading critical native API DLLs (e.g., ntdll.dll, kernel32.dll) followed by direct syscall behavior, memory manipulation, or hollowing.', '{Windows}', 'x-mitre-analytic--2a23296d-70f2-4e04-9a97-62d093ad1765', 'DET0529', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DllName", "description": "May tune DLL filters to focus on low-level API providers (e.g., ntdll.dll)"}, {"field": "Image", "description": "Tune for expected parent processes (e.g., explorer.exe, winlogon.exe)"}, {"field": "TargetProcess", "description": "Scope to suspicious targets like LSASS, csrss, etc."}]', '2026-05-01 15:26:34.805413');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (304, 'AN2004', 'Analytic 2004', 'Consider analyzing malware for features that may be associated with the adversary and/or their developers, such as compiler used, debugging artifacts, or code similarities. Malware repositories can also be used to identify additional samples associated with the adversary and identify development patterns over time.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (305, 'AN0889', 'Analytic 0889', 'Modification of container runtime security profiles (AppArmor, seccomp) or removal of monitoring agents within containers. Detect unauthorized mounting/unmounting of host /proc or /sys to disable logging or auditing.', '{Containers}', 'x-mitre-analytic--2a4f23d7-3f80-45b7-90ec-b13fdd7f8d70', 'DET0317', '[{"name": "kubernetes:audit", "channel": "seccomp or AppArmor profile changes", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "docker:runtime", "channel": "Termination of monitoring sidecar or security container", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "RuntimeProfiles", "description": "Specify which security profiles should be monitored for modification."}]', '2026-05-01 15:26:34.808703');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (306, 'AN1556', 'Analytic 1556', 'Detection of bash/zsh history suppression via HISTFILE/HISTCONTROL manipulation and absence of ~/.bash_history updates. Observing environment variable changes tied to terminal processes is a strong indicator.', '{macOS}', 'x-mitre-analytic--2a5f1993-7035-4d94-b9d1-7edb1850d4e1', 'DET0563', '[{"name": "macos:unifiedlog", "channel": "Set or unset HIST* variables in shell environment", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ShellProfiles", "description": "Different shells (bash, zsh, fish) may require customized monitoring for history tampering."}]', '2026-05-01 15:26:34.810075');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (307, 'AN1422', 'Analytic 1422', 'Detects container breakout behavior via exploitation (e.g., DirtyPipe, CVE-2022-0847), followed by host OS interaction or escalated capability assignment.', '{Containers}', 'x-mitre-analytic--2a93100f-6332-4c91-bad9-fd371d638309', 'DET0514', '[{"name": "auditd:SYSCALL", "channel": "capset or setns", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "containerd:runtime", "channel": "e.g., containerd, Docker events", "x_mitre_data_component_ref": "x-mitre-data-component--91b3ed33-d1b5-4c4b-a896-76c55eb3cfd8"}]', '[{"field": "NamespaceEscapePattern", "description": "May vary with CVE technique or custom syscall wrapper."}, {"field": "TimeWindow", "description": "Controls correlation of breakout → host interaction."}]', '2026-05-01 15:26:34.811552');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (308, 'AN0070', 'Analytic 0070', 'Detects abnormal interaction with memory-based Kerberos ccache (API:{uuid}) or file-based overrides. Focus on processes attempting to enumerate or extract Kerberos tickets outside of built-in utilities. Detects use of open-source tools (e.g., Bifrost, modified Mimikatz ports) that interact with the Kerberos framework APIs.', '{macOS}', 'x-mitre-analytic--2a9d296d-6b36-42de-870c-9d851c0471ed', 'DET0024', '[{"name": "macos:unifiedlog", "channel": "Kerberos framework calls to API:{uuid} cache outside normal process lineage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "Execution of non-standard binaries accessing Kerberos APIs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "KerberosAPIProcessBaseline", "description": "Expected processes using the Kerberos framework (e.g., loginwindow, kinit)."}, {"field": "SuspiciousBinaryList", "description": "List of tools or binaries not normally expected to query Kerberos ccache entries."}, {"field": "TimeWindow", "description": "Window to link suspicious process activity with Kerberos authentication anomalies."}]', '2026-05-01 15:26:34.8131');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (310, 'AN0913', 'Analytic 0913', 'Detects the presence of executables with high NOP padding, unusually large binary size for their function, and follow-on execution or memory injection from such files, especially when originating from temp or user-space paths.', '{Windows}', 'x-mitre-analytic--2ae1dd34-c666-488f-8ad6-752b8a6acae1', 'DET0322', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "NOPThreshold", "description": "High proportion of 0x90 opcodes indicating junk code – tune to suppress noise from some packing tools"}, {"field": "ExecutableSizeThreshold", "description": "Size range for abnormally large binaries relative to their runtime behavior"}, {"field": "TimeWindow", "description": "Window between file creation and execution – short intervals may indicate staged payload execution"}]', '2026-05-01 15:26:34.815786');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (311, 'AN1030', 'Analytic 1030', 'A non-privileged or abnormal process attempts to open a handle with full access (0x1F0FFF) to lsass.exe and subsequently invokes memory dump, file creation, or registry modification indicative of credential scraping. This behavior chain reflects staged credential theft activity.', '{Windows}', 'x-mitre-analytic--2b0dd3b6-6949-4dd5-b0dd-7b0b6f431dbe', 'DET0363', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4673", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "AccessMask", "description": "Set to 0x1F0FFF to detect full memory access attempts; can be scoped down to reduce noise."}, {"field": "TimeWindow", "description": "Defines time between LSASS access and dump file creation or registry modification (e.g., 5 minutes)."}, {"field": "ParentProcessName", "description": "Allowlist known legitimate tools (e.g., AV/EDR) accessing lsass.exe."}, {"field": "DumpFilePath", "description": "Paths where memory dumps are written, e.g., %TEMP%, C:\\Windows\\Temp."}, {"field": "CommandLinePattern", "description": "Common dumping syntax like rundll32, procdump, comsvcs.dll, Invoke-Mimikatz."}]', '2026-05-01 15:26:34.816998');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (312, 'AN1337', 'Analytic 1337', 'Authentication failures across different accounts using a repeated or similar password via SSH or PAM stack within a short window', '{Linux}', 'x-mitre-analytic--2b751817-3de2-4388-b8b9-d43b5ecda671', 'DET0487', '[{"name": "linux:syslog", "channel": "Failed password for invalid user", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "PasswordReusePattern", "description": "Repetition or minor variation of the same password across user attempts"}, {"field": "IPAggregationWindow", "description": "Length of time to observe distributed spray attempts from single source"}]', '2026-05-01 15:26:34.819253');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (313, 'AN2044', 'Analytic 2044', 'Detects esxcli commands disabling syslog, firewall, lockdown mode, or stopping hostd/vpxa; correlates command execution with reduced forwarding activity.', '{ESXi}', 'x-mitre-analytic--2b990a38-dedf-4a9a-9bd2-9a805c2f1b46', 'DET0497', '[{"name": "esxi:shell", "channel": "esxcli system syslog config set/reload, services.sh restart/stop", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:hostd", "channel": "service state change", "x_mitre_data_component_ref": "x-mitre-data-component--66531bc6-a509-4868-8314-4d599e91d222"}]', '[{"field": "ExpectedAdminIPs", "description": "Authorized management sources."}]', '2026-05-01 15:26:34.820624');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (314, 'AN0397', 'Analytic 0397', 'Script-based execution of sleep loops or time delay commands (e.g., sleep, ping delay, while-loops) followed by file creation or network connections.', '{Linux}', 'x-mitre-analytic--2bbe41df-b8a6-4503-8fb0-028b7387cb1d', 'DET0141', '[{"name": "auditd:SYSCALL", "channel": "execve of sleep or ping command within script interpreted by bash/python", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "file write after sleep delay", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "SleepLoopCount", "description": "Defines how many loop iterations or sleep cycles are considered anomalous in the monitored environment."}, {"field": "ExecutionScriptType", "description": "Identifies which scripting interpreter is used (e.g., bash, python, perl) to adjust detection logic."}]', '2026-05-01 15:26:34.821929');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (315, 'AN0632', 'Analytic 0632', 'Detects binaries disguised as media or document types through extension-only masquerading or by modifying the file signature. Observes execution of files whose extension is not typically executable (.jpg, .txt), yet have valid Mach-O headers or execute via Terminal or launch services.', '{macOS}', 'x-mitre-analytic--2bce7f8d-90c1-4835-9ce9-832e5e3a37d6', 'DET0226', '[{"name": "macos:unifiedlog", "channel": "launchservices events for misleading extensions", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "LaunchAgentScope", "description": "Scope of services monitored for unusual launches (e.g., Finder, Terminal, Preview)"}, {"field": "SignatureEnforcementLevel", "description": "How strictly the detection checks header validity vs. file extension"}, {"field": "TimeWindow", "description": "Time range for linking file modification and execution events"}]', '2026-05-01 15:26:34.823545');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (316, 'AN1200', 'Analytic 1200', 'Monitors Keychain database access and suspicious invocations of security and osascript utilities. Correlates process execution with attempts to dump or unlock Keychain data.', '{macOS}', 'x-mitre-analytic--2bec56a7-957c-44b4-b730-00dd55ff99f8', 'DET0430', '[{"name": "macos:unifiedlog", "channel": "access to keychain database", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "execution of security or osascript", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AllowedApplications", "description": "Whitelist of legitimate processes accessing the Keychain"}, {"field": "AlertThreshold", "description": "Number of failed access attempts before raising an alert"}]', '2026-05-01 15:26:34.825153');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (317, 'AN0304', 'Analytic 0304', 'Processes use built-in encoding utilities (e.g., `base64`, `xxd`, or `plutil`) to encode file contents followed by HTTP/HTTPS transfer via curl or custom applications.', '{macOS}', 'x-mitre-analytic--2bf1ce64-970b-4d0d-bf5f-a854fc6d7235', 'DET0108', '[{"name": "macos:unifiedlog", "channel": "base64 or curl processes chained within short execution window", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "HTTP POST with encoded content in user-agent or cookie field", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "EncodedCommandLengthThreshold", "description": "Minimum byte size of encoded strings to treat as suspicious"}, {"field": "SuspiciousProcessChainDepth", "description": "Number of chained processes within a short window to treat as a correlated behavior"}]', '2026-05-01 15:26:34.826659');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (318, 'AN0451', 'Analytic 0451', 'Detect repeated failed login events followed by MFA challenges triggered in rapid succession, especially if originating from service accounts or anomalous IP addresses.', '{Windows}', 'x-mitre-analytic--2c0df764-d9bd-4a91-808a-aa13df13511a', 'DET0160', '[{"name": "WinEventLog:Security", "channel": "EventCode=4625", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "ServiceAccountExclusion", "description": "Exclude specific accounts where automated MFA requests are legitimate"}]', '2026-05-01 15:26:34.827968');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (319, 'AN1385', 'Analytic 1385', 'Hidden file creation using leading ''.'' or file attribute changes with chattr (immutable/hidden flags). Defender view: detect execution of chattr, lsattr anomalies, and unusual hidden files appearing in system directories.', '{Linux}', 'x-mitre-analytic--2c3ec402-b9e9-4091-a04d-3b73f260e669', 'DET0502', '[{"name": "auditd:EXECVE", "channel": "Execution of chattr to set +i or +a attributes", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:FILE", "channel": "Creation of hidden files (.*) in sensitive directories (/etc, /var, /usr/bin)", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "DirectoryScope", "description": "Restrict hidden file detection to privileged system directories."}, {"field": "AttributeFlags", "description": "Tune for specific chattr flags (+i immutable, +a append-only) most abused for persistence."}]', '2026-05-01 15:26:34.829265');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (320, 'AN0337', 'Analytic 0337', 'Invocation of esxcli ''system account remove'' from vCLI, SSH, or vSphere API with anomalous user access or outside maintenance windows.', '{ESXi}', 'x-mitre-analytic--2c5d3103-2b9c-4b56-b415-c01e055fff64', 'DET0120', '[{"name": "esxi:hostd", "channel": "method=RemoveUser or esxcli system account remove invocation", "x_mitre_data_component_ref": "x-mitre-data-component--d6257b8e-869c-41c0-8731-fdca40858a91"}, {"name": "esxi:vpxa", "channel": "user login from unexpected IP or non-admin user role", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "RemoteUserRole", "description": "ESXi role triggering the change (e.g., Administrator vs. Viewer)"}, {"field": "ExpectedIPs", "description": "IP ranges authorized to conduct admin-level actions"}]', '2026-05-01 15:26:34.830549');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (321, 'AN0473', 'Analytic 0473', 'Adversary installs or modifies email content filters or transport scripts (e.g., Postfix milter, Sendmail milter, Exim filters) using shell access or configuration manipulation.', '{Linux}', 'x-mitre-analytic--2c64ece9-c40f-4d1a-babf-106f587454d0', 'DET0166', '[{"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:syslog", "channel": "milter configuration updated, transport rule initialized, unexpected script execution", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "auditd:EXECVE", "channel": "/usr/sbin/postfix, /usr/sbin/exim, /usr/sbin/sendmail", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "linux:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "MailTransportScriptPath", "description": "Path to custom scripts or filters depends on mail daemon (e.g., /etc/postfix/milter/, /etc/exim4/)."}, {"field": "UserContext", "description": "Mail agents may run under different service users (postfix, exim, etc.), which should be scoped."}, {"field": "ExecFrequencyThreshold", "description": "Frequency of filter script re-execution per daemon restart or reload may vary."}]', '2026-05-01 15:26:34.831696');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (322, 'AN1201', 'Analytic 1201', 'Detects attempts to access or enumerate cloud password/secrets storage services such as AWS Secrets Manager, Azure Key Vault, or GCP Secret Manager. Monitors API calls for abnormal enumeration or bulk retrieval of secrets.', '{IaaS}', 'x-mitre-analytic--2c8326bd-dd59-4715-87ef-dc3bdef919fb', 'DET0430', '[{"name": "AWS:CloudTrail", "channel": "GetSecretValue", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"name": "AWS:CloudTrail", "channel": "Decrypt", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "UserContext", "description": "Correlate cloud API calls with IAM role, user, or service account context"}, {"field": "AccessThreshold", "description": "Number of secret retrievals within a time window before flagging"}]', '2026-05-01 15:26:34.832922');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (323, 'AN0540', 'Analytic 0540', 'Detection of known tools or malware flagged by antivirus, followed by a near-term drop of a similar binary with modified signature and resumed activity (execution, C2, or persistence).', '{Windows}', 'x-mitre-analytic--2c94147a-a556-4fa1-92f8-d3c4367f6f2e', 'DET0189', '[{"name": "WinEventLog:Application", "channel": "EventCode=1000", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AVAlertMessage", "description": "Vendor-specific signature string or detection message that can be correlated to threat intel context."}, {"field": "TimeWindow", "description": "The time between AV alert and similar file/process activity (e.g., 5–30 minutes)"}, {"field": "FilenameSimilarityThreshold", "description": "String or hash similarity thresholds between original and modified binary."}]', '2026-05-01 15:26:34.834164');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (324, 'AN1308', 'Analytic 1308', 'Detects rundll32.exe invoked with atypical arguments (.dll, .cpl, javascript:, mshtml). DLLs not normally loaded by rundll32 are mapped into memory. Control_RunDLL or RunHTMLApplication invoked. Suspicious DLLs or scripts accessed from disk or network. Rundll32 reaches out to external domains (e.g., fetching .sct or .hta).', '{Windows}', 'x-mitre-analytic--2cb33f68-48f8-4ffe-86e1-bc857a300398', 'DET0475', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Correlating rundll32 invocation with DLL load or network activity within X seconds."}, {"field": "ParentProcessFilter", "description": "Limit detection to suspicious parent processes (e.g., explorer.exe, office apps) vs. trusted installers."}, {"field": "AllowedDLLs", "description": "Baseline list of legitimate DLLs frequently executed by rundll32 in the environment."}, {"field": "ExternalIPRange", "description": "Scope of external IP ranges considered anomalous for rundll32 network connections."}]', '2026-05-01 15:26:34.835342');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (325, 'AN0571', 'Analytic 0571', 'Detection correlates anomalous Docker or Kubernetes API requests with access to logs, secrets, or service accounts. Observes unauthorized use of `docker logs`, `kubectl get secrets`, or direct API calls to Kubernetes API server endpoints. Identifies behavioral patterns where adversaries escalate from basic pod/container interaction to privileged API calls exposing sensitive credential material.', '{Containers}', 'x-mitre-analytic--2d054232-8968-4d11-b742-536b70bbb1ba', 'DET0198', '[{"name": "docker:api", "channel": "docker logs access or container inspect commands from non-administrative users", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "kubernetes:apiserver", "channel": "get/list requests to /api/v1/secrets or /api/v1/namespaces/*/serviceaccounts", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "kubernetes:apiserver", "channel": "exec into pod followed by secret retrieval via API", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "kubernetes:orchestrator", "channel": "Access to orchestrator logs containing credentials (Docker/Kubernetes logs)", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "UserContext", "description": "Tune to exclude known orchestrator admin service accounts or CI/CD pipelines that legitimately access secrets"}, {"field": "NamespaceScope", "description": "Restrict detection to sensitive namespaces (e.g., kube-system, production apps)"}, {"field": "TimeWindow", "description": "Adjust correlation timing between pod execution and subsequent API secret retrieval"}, {"field": "SourceIP", "description": "Filter based on allowed internal API calls vs anomalous external or cross-cluster access"}]', '2026-05-01 15:26:34.836568');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (326, 'AN1146', 'Analytic 1146', 'Unusual access or copying of files from mounted network drives (e.g., NFS, CIFS/SMB) by user shells or scripts followed by large data transfer.', '{Linux}', 'x-mitre-analytic--2d1d5482-b82b-45ff-9563-959766d373ff', 'DET0410', '[{"name": "auditd:SYSCALL", "channel": "open,read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:syslog", "channel": "mount/umount or file copy logs", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}]', '[{"field": "MountPoint", "description": "Organization-specific share mount paths may vary (/mnt/share1, /srv/data etc.)"}, {"field": "UID", "description": "May need to scope to service accounts or user ID patterns specific to enterprise policy."}]', '2026-05-01 15:26:34.837865');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (327, 'AN0999', 'Analytic 0999', 'macOS permission and attribute manipulation behavioral chain: (1) Process execution of permission utilities (chmod, chown, chgrp) or macOS-specific tools (chflags) with suspicious parameters, (2) System Integrity Protection (SIP) bypass attempts through permission modifications, (3) File flags manipulation (uchg, schg, hidden) for evasion or persistence, (4) Extended attribute (xattr) modifications affecting security metadata, (5) Unified log correlation with file system events and subsequent access patterns, (6) Gatekeeper and code signing bypass through permission/attribute manipulation', '{macOS}', 'x-mitre-analytic--2d21fb1f-f9c3-4e72-a6dd-3d7872be3294', 'DET0351', '[{"name": "macos:unifiedlog", "channel": "process execution events for chmod, chown, chflags with parameter analysis and target path examination", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsevents", "channel": "file system events indicating permission, ownership, or extended attribute changes on critical paths. File system modification events with kFSEventStreamEventFlagItemChangeOwner, kFSEventStreamEventFlagItemXattrMod flags", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "OpenBSM:AuditTrail", "channel": "BSM audit events for file permission, ownership, and attribute modifications with user context", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "SIPProtectedPaths", "description": "macOS system paths protected by SIP that should never have permission modifications - maintain current list based on macOS version (/System, /usr, /bin, /sbin)"}, {"field": "SuspiciousFileFlags", "description": "chflags parameter combinations indicating potential evasive behavior - customize based on security requirements (uchg, schg, hidden, archived)"}, {"field": "CriticalExtendedAttributes", "description": "Extended attributes requiring monitoring for unauthorized removal or modification (com.apple.quarantine, com.apple.metadata, com.apple.FinderInfo)"}, {"field": "GatekeeperBypassIndicators", "description": "Patterns in permission/attribute changes that may indicate Gatekeeper bypass attempts"}, {"field": "ApplicationBundleMonitoring", "description": "Scope of .app directory monitoring for internal permission modifications indicating bundle tampering"}, {"field": "UnifiedLogRetentionPeriod", "description": "Log retention period for correlating permission changes with subsequent access patterns - balance storage with detection capability"}, {"field": "FSEventsFilteringThreshold", "description": "File system event filtering threshold to manage high-volume environments while maintaining detection coverage"}]', '2026-05-01 15:26:34.839409');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (328, 'AN0493', 'Analytic 0493', 'Detects adversary exploitation of authentication mechanisms or credential validation processes. Defender perspective includes forged Kerberos tickets (e.g., MS14-068), abnormal LSASS memory access, replayed authentication attempts, and unexpected crashes of authentication services. Multi-event correlation ties exploitation attempts to abnormal process creation, service instability, and suspicious authentication events.', '{Windows}', 'x-mitre-analytic--2d4a40e4-359f-49ac-9e3f-58e29497aa41', 'DET0174', '[{"name": "WinEventLog:Security", "channel": "EventCode=4768, 4769, 4770", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "MonitoredAccounts", "description": "High-value accounts (e.g., Domain Admins) for anomalous ticket issuance or replay activity."}, {"field": "ReplayDetectionWindow", "description": "Time window for correlating duplicate or replayed Kerberos authentications."}]', '2026-05-01 15:26:34.841056');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (620, 'AN0508', 'Analytic 0508', 'Detection of group enumeration using commands like ''id'', ''groups'', or ''getent group'', often followed by privilege escalation or SSH lateral movement.', '{Linux}', 'x-mitre-analytic--56a17328-c6b0-4e3d-9404-d4b8ba967a14', 'DET0179', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLine", "description": "Variations of enumeration commands tailored to different Linux distros (e.g., ''getent group'', ''cut -d'' in /etc/group parsing)."}, {"field": "TTYSession", "description": "TTY context or source terminal (remote shell vs local login) to reduce noise."}]', '2026-05-01 15:26:35.271468');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (329, 'AN0514', 'Analytic 0514', 'CLI tools (smbclient -L, smbmap, rpcclient, nmblookup) or custom scripts enumerate SMB shares on many internal hosts → corresponding SMB connections (445/139) captured by Zeek/Netflow within a short window.', '{Linux}', 'x-mitre-analytic--2de35397-ef03-4ffe-b531-d7ad61a6f41d', 'DET0182', '[{"name": "auditd:SYSCALL", "channel": "execve of smbclient, smbmap, rpcclient, nmblookup, crackmapexec smb", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "connection: TCP connections to ports 139/445 to multiple hosts", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "smb_command: TreeConnectAndX to \\\\*\\IPC$ / srvsvc or Trans2/NT_CREATE for listing shares", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "BurstHostThreshold", "description": "Minimum unique hosts to flag (e.g., ≥5)."}, {"field": "TimeWindow", "description": "Correlation window between tool exec and SMB fan-out (default 10m)."}, {"field": "ApprovedInventoryHosts", "description": "IPs of vulnerability scanners or config mgmt systems."}]', '2026-05-01 15:26:34.843808');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (330, 'AN0512', 'Analytic 0512', 'SQL stored procedures that invoke OS-level commands via `xp_cmdshell` equivalent or via UDF (User-Defined Functions) mechanisms.', '{Linux}', 'x-mitre-analytic--2e039fd4-a1f6-4c4b-b47a-56c257335298', 'DET0181', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "ApplicationLogs:SQL", "channel": "Stored procedure creation or modification with shell invocation (e.g., system(), exec())", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "CommandRegex", "description": "Regex used to detect suspicious OS commands via SQL"}, {"field": "TimeWindow", "description": "Window for correlating procedure creation and command execution"}]', '2026-05-01 15:26:34.845137');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (331, 'AN0433', 'Analytic 0433', 'Interactive or remote shell/API invocation of esxcli system clock get or querying time parameters via hostd/vpxa shortly followed by time/ntp configuration checks or scheduled task creation, executed by non-standard accounts or outside maintenance windows.', '{ESXi}', 'x-mitre-analytic--2e51d33e-28d3-4e3f-a68a-38bc2d4abdde', 'DET0151', '[{"name": "esxi:shell", "channel": "/var/log/shell.log entries containing \"esxcli system clock get\"", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:hostd", "channel": "/var/log/hostd.log API calls reading/altering time/ntp settings", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "esxi:syslog", "channel": "/var/log/vpxa.log task invocations tied to time configuration", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}]', '[{"field": "MaintenanceWindow", "description": "Only alert if outside approved ops windows."}, {"field": "PrivilegedAccountsAllowList", "description": "Suppress alerts for known service accounts."}, {"field": "RemoteIPAllowList", "description": "Whitelist management station IPs."}, {"field": "TimeWindow", "description": "Correlation between esxcli time query and subsequent hostd/vpxa config calls."}]', '2026-05-01 15:26:34.846629');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (332, 'AN0626', 'Analytic 0626', 'Detects cloud-native software deployment or management (e.g., SSM Run Command, Intune) initiating script execution on endpoints outside expected org IDs, admin groups, or maintenance windows.', '{SaaS}', 'x-mitre-analytic--2e6218d1-1f84-4dc5-8ab5-c24835aafbab', 'DET0223', '[{"name": "AWS:CloudTrail", "channel": "SSM RunCommand", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "IAMRoleAllowList", "description": "Approved deployment administrators or service accounts"}, {"field": "ExecutionTargetList", "description": "Expected endpoints targeted by SaaS deployments"}]', '2026-05-01 15:26:34.847912');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (333, 'AN0163', 'Analytic 0163', 'Detect unauthorized manipulation of log files, database entries, or system configuration files through auditd and syslog. Correlate shell commands that alter HISTFILE or data-related processes with abnormal file access patterns.', '{Linux}', 'x-mitre-analytic--2e700f3b-bf9c-427c-a099-b80d233c1ccb', 'DET0059', '[{"name": "auditd:SYSCALL", "channel": "open, unlink, rename: Suspicious file access, deletion, or modification of sensitive paths", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:syslog", "channel": "Unexpected SQL or application log entries showing tampered or malformed data", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "WatchedDirectories", "description": "Specific log or data directories critical to integrity; tune per organization."}, {"field": "CommandExclusions", "description": "Legitimate scripts/tools excluded from data manipulation monitoring."}]', '2026-05-01 15:26:34.849119');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (334, 'AN1449', 'Analytic 1449', 'Closed-port knock sequence from a remote IP followed by on-host firewall change (iptables/nftables) or daemon starts listening (socket open) and a successful TCP/UDP connect. Optional detection of libpcap/raw-socket sniffers spawning to watch for secret values.', '{Linux}', 'x-mitre-analytic--2e7a9609-3e4b-477b-828f-f486561d7fa7', 'DET0524', '[{"name": "auditd:SYSCALL", "channel": "execve: Commands altering firewall or enabling listeners (iptables, nft, ufw, firewall-cmd, systemctl start *ssh*/*telnet*, ip route add, tcpdump, tshark)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "socket/bind: Process binds to a new local port shortly after knock", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Knock pattern: multiple REJ/S0 to distinct closed ports then successful connection to service_port", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "Packets with unusual flags or payloads outside established flows (e.g., WoL magic FF×6 + 16×MAC)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ServicePort", "description": "Port that becomes available post-knock (e.g., 22/8022/2323)."}, {"field": "KnockResetRatio", "description": "Percentage of failed attempts with RST/ICMP vs SYN/SYN-ACK to qualify as closed-port probing."}, {"field": "ProcessAllowList", "description": "Automation expected to touch firewall/daemon configs (config-mgmt agents)."}]', '2026-05-01 15:26:34.850339');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (335, 'AN2005', 'Analytic 2005', 'Monitor and analyze traffic patterns and packet inspection associated to protocol(s) that do not follow the expected protocol standards and traffic flows (e.g extraneous packets that do not belong to established flows, gratuitous or anomalous traffic patterns, anomalous syntax, or structure). Consider correlation with process monitoring and command line to detect anomalous processes execution and command line arguments associated to traffic patterns (e.g. monitor anomalies in use of files that do not normally initiate connections for respective protocol(s)).
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (336, 'AN1107', 'Analytic 1107', 'Detection of ApplicationImpersonation role assignment or delegated mailbox access to service principals or rarely used users, especially outside of normal hours or geographic norms.', '{"Office Suite"}', 'x-mitre-analytic--2ec84f0f-1148-4821-acf0-a5527381865f', 'DET0393', '[{"name": "m365:unified", "channel": "Add-MailboxPermission or Set-ManagementRoleAssignment", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:signinlogs", "channel": "Unusual sign-in from service principal to user mailbox", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TargetMailbox", "description": "Mailbox of interest where impersonation or access delegation occurs."}, {"field": "UserAgent", "description": "Tune based on expected application or script-based mailbox access."}, {"field": "GeoLocation", "description": "Restrict based on corporate geography or travel expectations."}]', '2026-05-01 15:26:34.852995');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (337, 'AN0522', 'Analytic 0522', 'Detects clearing of unified logs, deletion of plist files tied to persistence, and manipulation of Terminal history after initial execution.', '{macOS}', 'x-mitre-analytic--2f0f5c7a-18ee-462e-b364-b1d8df3b2c02', 'DET0184', '[{"name": "macos:unifiedlog", "channel": "log stream cleared or truncated", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "fs:fsusage", "channel": "unlink, fs_delete", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "macos:osquery", "channel": "File modifications in ~/Library/Preferences/", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "PlistTargetPaths", "description": "Define which plist paths relate to LaunchAgents or LaunchDaemons"}, {"field": "ExecutionChainDepth", "description": "Allow tuning for multi-process persistence chains"}]', '2026-05-01 15:26:34.854186');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (338, 'AN0758', 'Analytic 0758', 'Detects unauthorized modification of network device authentication by correlating OS image file changes, checksum mismatches, or memory verification failures with anomalous authentication events. Focus is on behaviors where patched images introduce hardcoded passwords or bypass native authentication.', '{"Network Devices"}', 'x-mitre-analytic--2f39584b-59bd-43ec-bd0a-5c2eba258ae2', 'DET0272', '[{"name": "networkconfig", "channel": "unexpected OS image file upload or modification events", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "network:auth", "channel": "repeated successful authentications with previously unknown accounts or anomalous password acceptance", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "BaselineChecksums", "description": "Trusted baseline cryptographic hashes for OS images, used to detect unauthorized modifications."}, {"field": "AuthFailureThreshold", "description": "Threshold for correlating unusual authentication successes following failed attempts or unknown account use."}, {"field": "VerificationInterval", "description": "Frequency of runtime OS image and memory integrity checks."}]', '2026-05-01 15:26:34.855571');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (339, 'AN0851', 'Analytic 0851', 'User or remote input triggers application crash or segmentation fault (e.g., SIGSEGV) with service recovery attempts, observed via audit logs and systemd journaling.', '{Linux}', 'x-mitre-analytic--2f4d199c-4d62-4d7d-8c6e-3ec358c22e76', 'DET0304', '[{"name": "auditd:SYSCALL", "channel": "Process segfault or abnormal termination after invoking vulnerable syscall sequence", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}, {"name": "journald:Application", "channel": "Segfault or crash log entry associated with specific application binary", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Unusual request pattern leading up to service crash (e.g., malformed or oversized payload)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CrashPattern", "description": "Specific binary fault signature or stack trace identifiers unique to the application context"}, {"field": "ExploitSourceIP", "description": "Suspect source IPs for correlation across requests and service failure timing"}]', '2026-05-01 15:26:34.857312');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (340, 'AN1533', 'Analytic 1533', 'Observation of `blueutil`/`networksetup` commands or low-level APIs toggling Bluetooth or initiating transfers, especially if paired with recent large file read activity by non-GUI processes.', '{macOS}', 'x-mitre-analytic--2f6dd4a5-b0cc-4c13-abb8-e2d747d591b2', 'DET0554', '[{"name": "macos:unifiedlog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "macos:osquery", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ProcessContext", "description": "Limit to background processes or scripts with no GUI interaction."}, {"field": "PayloadType", "description": "Focus on specific sensitive file types (e.g., zip, docx, keychain db)."}]', '2026-05-01 15:26:34.858885');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (341, 'AN0939', 'Analytic 0939', 'Detection of maintainer scripts (e.g., postinst, preinst) being modified or executed during dpkg or rpm operations. Watch for script content that spawns additional processes or writes outside package scope.', '{Linux}', 'x-mitre-analytic--2f9c7e44-de3a-4fbd-955a-482ef9f341ed', 'DET0330', '[{"name": "auditd:SYSCALL", "channel": "Execution of dpkg or rpm followed by fork/execve from within postinst, prerm, etc.", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ScriptName", "description": "May be postinst, preinst, prerm, or postrm depending on packaging system"}, {"field": "PackageManager", "description": "Depends on system: dpkg, apt, rpm, yum, etc."}]', '2026-05-01 15:26:34.860398');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (342, 'AN1537', 'Analytic 1537', 'Detects suspicious use of ESXi native CLI tools like esxcli and vim-cmd by unauthorized users or outside expected maintenance windows. Focus is on actions such as stopping VMs, reconfiguring network/firewall settings, and enabling SSH or logging.', '{ESXi}', 'x-mitre-analytic--2fa4d134-8583-4cbe-bc84-bfc799205116', 'DET0558', '[{"name": "esxi:vmkernel", "channel": "esxcli, vim-cmd invocation", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:auth", "channel": "SSH session/login", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Helps scope detection to off-hours or change control gaps."}, {"field": "UserContext", "description": "Environment-specific users may run these commands as part of normal ops."}, {"field": "CommandPattern", "description": "CLI commands vary by adversary intent (e.g., ''stop'', ''reboot'', ''firewall set'')"}]', '2026-05-01 15:26:34.861821');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (343, 'AN1312', 'Analytic 1312', 'Correlates unusual auto-forwarding rule creation via Exchange Web Services or Outlook rules engine, presence of X-MS-Exchange-Organization-AutoForwarded headers, and logon session anomalies from abnormal IPs.', '{"Office Suite"}', 'x-mitre-analytic--2faaefb9-7816-4eb5-a9f5-b4006c99c20b', 'DET0476', '[{"name": "m365:unified", "channel": "Set-Mailbox, New-InboxRule", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "m365:exchange", "channel": "MessageTrace logs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "azure:ad", "channel": "SignInEvents", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "UserAgentList", "description": "Restrict rules from non-browser agents"}, {"field": "ExternalSMTPDomainList", "description": "Allow listing for org-sanctioned forwarding domains"}, {"field": "TimeWindow", "description": "Time delta between rule creation and suspicious sign-in"}]', '2026-05-01 15:26:34.865185');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (344, 'AN0083', 'Analytic 0083', 'Containerized apps or sidecar containers generating excessive outbound traffic or being leveraged for proxy networks. Includes sudden increases in network interface stats, especially in dormant or low-util apps.', '{Containers}', 'x-mitre-analytic--2fe9bf69-b1a8-4c60-8b20-c11054d31158', 'DET0028', '[{"name": "containers:osquery", "channel": "bandwidth-intensive command execution from within a container namespace", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "docker:stats", "channel": "unusual network TX/RX byte deltas", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ContainerBaselineNetworkUsage", "description": "Baseline per container must be defined by app purpose and normal traffic."}, {"field": "ImageName", "description": "Certain image names or registries may be prone to abuse (e.g., public image hosting mining or proxyware)."}]', '2026-05-01 15:26:34.86662');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (345, 'AN1287', 'Analytic 1287', 'Login activity from default admin credentials (e.g., ''admin'', ''cisco'') on routers, firewalls, and switches.', '{"Network Devices"}', 'x-mitre-analytic--305b6a70-6d5b-4b32-a40b-ae0cae342e62', 'DET0465', '[{"name": "networkdevice:syslog", "channel": "authentication logs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "Username", "description": "Default usernames vary by vendor; defenders should adapt logic to their specific appliance list."}, {"field": "InterfaceType", "description": "Telnet and HTTP-based access to network devices should be blocked and monitored if enabled."}]', '2026-05-01 15:26:34.868022');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (346, 'AN0484', 'Analytic 0484', 'Forged web cookies on Windows endpoints can be detected by monitoring unusual modifications of browser cookie stores (e.g., Chrome SQLite DB, Edge cache) by processes outside of browsers, followed by authentication events to SaaS or IaaS services. Defenders may observe processes writing directly to cookie storage paths or injecting tokens into browser sessions.', '{Windows}', 'x-mitre-analytic--305c684a-2b36-4209-9d00-778ed16de763', 'DET0171', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "BrowserCookiePaths", "description": "List of monitored cookie file paths on Windows systems."}, {"field": "ProcessWhitelist", "description": "Approved processes allowed to write to browser cookie stores."}]', '2026-05-01 15:26:34.869507');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (347, 'AN0545', 'Analytic 0545', 'Detects API calls to cloud secrets/MFA configurations where MFA enforcement policies are disabled or bypassed.', '{IaaS}', 'x-mitre-analytic--3090db89-83c0-44bc-a17d-7cb2a6aecb87', 'DET0190', '[{"name": "AWS:CloudTrail", "channel": "UpdateIdentityPolicy or DisableMFA", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "MonitoredServices", "description": "Specific cloud services or IAM policies relevant to MFA enforcement."}]', '2026-05-01 15:26:34.87081');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (348, 'AN0873', 'Analytic 0873', 'Detection of browser-based downloads from HTML sources that trigger file creation in temp or user directories followed by execution of new files within short timeframes and suspicious parent-child lineage.', '{Linux}', 'x-mitre-analytic--30ae2215-5dd5-4ef2-82bd-965781ef1f42', 'DET0313', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "DownloadPathRegex", "description": "Regular expressions for common download paths (e.g., /tmp/, ~/Downloads/)"}, {"field": "ExecutableTriggerWindow", "description": "Tunable range for follow-up process execution from dropped file (e.g., 5–15 minutes)"}]', '2026-05-01 15:26:34.872168');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (349, 'AN1552', 'Analytic 1552', 'Linux environmental validation behavioral chain: (1) Intensive system enumeration through command execution (uname, hostname, ifconfig, lsblk, mount), (2) File system reconnaissance targeting specific paths, network configurations, and installed packages, (3) Process and user enumeration to validate target environment characteristics, (4) Conditional script execution or binary activation based on environmental criteria, (5) Network connectivity validation and external IP address resolution for geolocation verification', '{Linux}', 'x-mitre-analytic--31027842-f02c-4bc3-8cd6-3e4b533da5ac', 'DET0562', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "openat,connect -k discovery", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "auditd:PROCTITLE", "channel": "command-line execution patterns for system discovery utilities (uname, hostname, ifconfig, netstat, lsof, ps, mount)", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:syslog", "channel": "authentication and authorization events during environmental validation phase", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "SystemDiscoveryCommandList", "description": "Linux commands commonly used for system reconnaissance - customize based on environment-specific discovery patterns"}, {"field": "ReconnaissanceBurstThreshold", "description": "Number of discovery commands within time window indicating reconnaissance burst - tune based on legitimate administrative activity"}, {"field": "EnvironmentalCheckPatterns", "description": "File paths and system properties commonly validated by environmental keying - adapt to organizational infrastructure"}, {"field": "NetworkDiscoveryBaseline", "description": "Normal network discovery activity patterns to distinguish from malicious reconnaissance"}, {"field": "ConditionalExecutionIndicators", "description": "Script patterns and conditional logic indicating environment-based execution decisions"}]', '2026-05-01 15:26:34.873947');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (350, 'AN0584', 'Analytic 0584', 'Excessive resource exhaustion or service crash induced by processes launched by users or scripts that rapidly consume CPU/memory or attempt malformed service interactions.', '{Windows}', 'x-mitre-analytic--3102edb4-6947-4cef-9660-4a35d582a716', 'DET0208', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Application", "channel": "Service crash, unhandled exception, or application hang warnings for critical services (e.g., IIS, DNS, SQL Server)", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:System", "channel": "System shutdowns due to bugcheck (Event ID 1001) or watchdog timer expirations", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "TimeWindow", "description": "Number of service crashes or high-CPU events within a defined time period"}, {"field": "ServiceTarget", "description": "Specific service name or executable targeted for DoS (e.g., svchost.exe, w3wp.exe)"}, {"field": "CPUThresholdPercent", "description": "CPU usage percent considered anomalous over duration"}]', '2026-05-01 15:26:34.875773');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (351, 'AN0877', 'Analytic 0877', 'Detects enabling of interface sniffing via packet capture tools or AppleScript triggering `tcpdump`. Leverages Unified Logs and process lineage to identify suspicious use of `pfctl`, `tcpdump`, or `libpcap` libraries.', '{macOS}', 'x-mitre-analytic--31098e90-e2a0-477f-80ca-e969430d54c2', 'DET0314', '[{"name": "macos:unifiedlog", "channel": "eventMessage = ''promiscuous''", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "process_events where path like ''%tcpdump%''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "access to BPF devices or interface IOCTLs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AllowedTools", "description": "Whitelist Apple-native tools used by IT admins and mobile device management (MDM)."}, {"field": "UserContext", "description": "Prioritize detections from non-admin or low-privilege users performing packet captures."}]', '2026-05-01 15:26:34.877322');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (352, 'AN1351', 'Analytic 1351', 'A process explicitly forges its parent using EXTENDED_STARTUPINFO + PROC_THREAD_ATTRIBUTE_PARENT_PROCESS (UpdateProcThreadAttribute → CreateProcess[A/W]/CreateProcessAsUserW) or other Native API paths, resulting in **mismatched/implausible lineage** across ETW EventHeader ProcessId, Security 4688 Creator Process ID/Name, and sysmon ParentProcessGuid. Often paired with privilege escalation when the chosen parent runs as SYSTEM.', '{Windows}', 'x-mitre-analytic--312f9f86-b987-483c-8b1d-955415eea946', 'DET0489', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "api_call: UpdateProcThreadAttribute (PROC_THREAD_ATTRIBUTE_PARENT_PROCESS) and CreateProcess* with EXTENDED_STARTUPINFO_PRESENT / StartupInfoEx", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "process_start: EventHeader.ProcessId true parent vs reported PPID mismatch", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "TimeWindow", "description": "Correlation window between UpdateProcThreadAttribute/CreateProcess* and the resulting process (default 5–10 minutes)."}, {"field": "AllowedSpoofers", "description": "Legitimate binaries that commonly use StartupInfoEx/PPID assignment (e.g., consent.exe, svchost.exe during UAC)."}, {"field": "ParentPrivilegeDeltaThreshold", "description": "Minimum privilege/integrity gap between chosen parent and real caller to raise severity."}, {"field": "LineageMismatchTolerance", "description": "Number of mismatched sources (0–3) before alerting to reduce noise."}, {"field": "SensitiveParents", "description": "List of SYSTEM parents that, if spoofed, auto‑escalate severity (e.g., lsass.exe, services.exe, wininit.exe)."}]', '2026-05-01 15:26:34.879163');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (353, 'AN0042', 'Analytic 0042', 'Detects files collected into user temp or shared directories followed by compression with ditto, zip, or custom scripts.', '{macOS}', 'x-mitre-analytic--313de6ca-629b-4f77-b58f-5cf7b490a62e', 'DET0014', '[{"name": "macos:unifiedlog", "channel": "file events", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "exec logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CompressionUtilityList", "description": "e.g., ''ditto'', ''zip'', ''tar''"}, {"field": "SharedDirectoryIndicators", "description": "e.g., /Users/Shared/ or /private/tmp/"}, {"field": "ScriptInvocationContext", "description": "osascript or Terminal automation by non-GUI processes"}]', '2026-05-01 15:26:34.880545');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (361, 'AN0664', 'Analytic 0664', 'Adversary modifies internal or external site content through manipulated application bundles, hosted content, or web server configs.', '{macOS}', 'x-mitre-analytic--3258db60-8500-4935-837c-78b23f2d83d1', 'DET0238', '[{"name": "macos:unifiedlog", "channel": "Execution of unexpected terminal or web scripts modifying /Library/WebServer/Documents", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "File creation or overwrite in common web-hosting folders", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "TargetDirectoryPath", "description": "Web root folders will vary depending on how services are configured on macOS (e.g., /Library/WebServer/Documents)."}]', '2026-05-01 15:26:34.892785');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (354, 'AN0501', 'Analytic 0501', 'Post-compromise identity & session anomalies that follow a drive-by compromise: token reuse from new/unfamiliar IPs, anomalous sign-in patterns for previously inactive users, unexpected consent/grant events, or provisioning changes. Defender sees an endpoint/browser compromise (network + endpoint signals) followed by unusual IdP events: new refresh token issuance, consent/consent-grant events, odd MFA bypass patterns, or unusual OAuth client registrations.', '{"Identity Provider"}', 'x-mitre-analytic--3154acf3-a5df-40bd-b4bc-3a210b6e5e0e', 'DET0176', '[{"name": "azure:signinlogs", "channel": "SignIn: Sign-ins flagged as atypical (new geographic region, unfamiliar device id) shortly after correlated endpoint/browser compromise times", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "m365:unified", "channel": "Application Consent grants, new OAuth client registrations, or unusual admin-level activities executed by a user account shortly after suspected drive-by compromise", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:auth", "channel": "Refresh token issuance or refresh token usage from new IPs or user agents", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "AWS:CloudTrail", "channel": "ConsoleLogin: If IdP backed by cloud provider, Console login from new IP/agent after correlated endpoint compromise", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "IdpAlertWindow", "description": "Time window to correlate IdP events to endpoint compromise alerts (default 30 minutes to 2 hours)."}, {"field": "HighRiskCountryList", "description": "List of countries/IP zones considered high risk for sign-ins; used to tune geo-anomalies."}, {"field": "DeviceTrustLevel", "description": "Device trust scoring thresholds that influence whether a sign-in is considered suspicious."}]', '2026-05-01 15:26:34.88192');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (355, 'AN0112', 'Analytic 0112', 'Monitor esxcli and syslog records for DNS resolver changes or repeated queries to unusual external domains by management agents. Detect unauthorized changes to VM or host network settings that redirect DNS lookups.', '{ESXi}', 'x-mitre-analytic--3166927d-91e4-4e08-bfec-abda2783be8c', 'DET0039', '[{"name": "esxi:syslog", "channel": "esxcli network vswitch or DNS resolver configuration updates", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ResolverConfigPaths", "description": "Expected resolvers or DNS forwarders in ESXi configurations"}, {"field": "ExternalDomainWhitelist", "description": "Set of trusted external domains expected for ESXi host activity"}]', '2026-05-01 15:26:34.883306');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (356, 'AN0356', 'Analytic 0356', 'Adversary drops renamed binaries in uncommon directories (e.g., /tmp, /dev/shm) or uses special characters in names (e.g., trailing space, Unicode RLO). Execution or cronjob registration follows shortly after file drop.', '{Linux}', 'x-mitre-analytic--3191336e-8cdb-4d41-80a4-aa2ab869f7bf', 'DET0127', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "rename", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "DropLocationPattern", "description": "Directories where new binaries are suspicious (e.g., /tmp)"}, {"field": "FilenameAnomalies", "description": "Regex for Unicode/RLO/space abuse in filenames"}, {"field": "ExecutionDelayWindow", "description": "Time range between file write and execution used for joining"}]', '2026-05-01 15:26:34.88451');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (357, 'AN1114', 'Analytic 1114', 'Background scripts (e.g., via cron) or daemons transmitting data repeatedly to remote IPs or URLs.', '{Linux}', 'x-mitre-analytic--31adce9b-8935-4abf-aaf2-0a13047e25e4', 'DET0397', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Outbound Connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "CronJobInterval", "description": "Tunable time range for recurring tasks seen creating outbound connections."}, {"field": "UserContext", "description": "Tunable for scope — service accounts vs user accounts."}]', '2026-05-01 15:26:34.88567');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (358, 'AN1009', 'Analytic 1009', 'Monitor mail server logs (e.g., Postfix, Sendmail) for excessive connections or inbound message counts targeting a single recipient. Correlate with repetitive attachment storage in /var/mail or /var/spool/mail directories.', '{Linux}', 'x-mitre-analytic--31e4c4dc-3094-45b2-9d4d-1b0bf8311498', 'DET0355', '[{"name": "auditd:SYSCALL", "channel": "File creation events in /var/mail or /var/spool/mail exceeding baseline thresholds", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "Application:Mail", "channel": "High-frequency inbound mail activity to a specific recipient address", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MailVolumeThreshold", "description": "Tunable value for the maximum acceptable emails per minute per user."}, {"field": "AttachmentPatternList", "description": "List of suspicious attachment extensions that may be abused for repetitive delivery."}]', '2026-05-01 15:26:34.886865');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (359, 'AN0314', 'Analytic 0314', 'Detection of modification to ESXi rc.local.d or rc scripts that are used to execute on boot.', '{ESXi}', 'x-mitre-analytic--32199f21-430f-4c91-b2d7-a0b7409cd5f0', 'DET0112', '[{"name": "esxi:vmkernel", "channel": "boot", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "esxi:hostd", "channel": "boot", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "ScriptName", "description": "Script path or name may vary across hypervisor versions."}, {"field": "LogSeverity", "description": "Log verbosity settings may alter visibility of activity."}]', '2026-05-01 15:26:34.888358');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (360, 'AN1174', 'Analytic 1174', 'Monitor command execution of powercfg.exe with arguments modifying sleep, hibernate, or display timeouts. Abnormal or repeated modifications to power settings outside administrative baselines may indicate persistence attempts. Correlate process creation with registry and system configuration changes to build behavioral chains.', '{Windows}', 'x-mitre-analytic--3234a537-0ad5-449f-87f4-25fd949c97e7', 'DET0417', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AllowedAdminTools", "description": "Whitelist expected administrative scripts that legitimately modify power settings."}, {"field": "TimeWindow", "description": "Correlation period between powercfg.exe invocation and registry/policy changes."}]', '2026-05-01 15:26:34.89005');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (362, 'AN0819', 'Analytic 0819', 'User opens a file delivered by email, web, chat, or share. The handler application (Word/PDF reader/archiver) creates a file in user-controlled paths (Downloads, Temp, Desktop) and then spawns a new or unusual child process (e.g., powershell.exe, wscript.exe, cmd.exe, regsvr32.exe, rundll32.exe, msiexec.exe). Optional precursors include FileStreamCreated (URL/UNC) and Office → system32 batch writes.', '{Windows}', 'x-mitre-analytic--328d639e-6b8d-400c-9cdd-3c255d343e47', 'DET0294', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "TimeWindow", "description": "Seconds/minutes to correlate file write to child spawn (e.g., 0–5m)."}, {"field": "SuspiciousExtensions", "description": "Extensions and double-extension patterns to flag (exe,scr,lnk,pif,cpl,js,vbs,bat,cmd,ps1,hta,iso,lnk->cmd,docm,xlsm,pdf->exe, etc.)."}, {"field": "UserPaths", "description": "Paths considered user-controlled (Downloads, Temp, Desktop, profile AppData staging)."}, {"field": "ParentApps", "description": "List of user-facing apps that commonly open attachments for your org (reduce FPs or add weight)."}, {"field": "SignerAllowList", "description": "Trusted code signers/publishers to suppress benign admin tools."}]', '2026-05-01 15:26:34.89438');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (363, 'AN0202', 'Analytic 0202', 'Session cookie reuse on unmanaged browsers, devices, or client types deviating from user baseline (e.g., switching from Chrome to curl).', '{SaaS}', 'x-mitre-analytic--32ace35c-66c4-48d7-a8bc-d81c65f4451b', 'DET0074', '[{"name": "m365:unified", "channel": "SessionId reused from different device/browser fingerprint", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "saas:okta", "channel": "session.impersonation.start", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "BrowserFingerprintMatch", "description": "Tolerance for accepting small differences in user-agent headers"}, {"field": "SessionReuseTimeout", "description": "Time gap threshold between valid session creation and reuse"}]', '2026-05-01 15:26:34.895926');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (364, 'AN0499', 'Analytic 0499', 'Correlated evidence of browser or webview fetches to uncommon domains or mutated JS resources (proxy/NGFW logs + Zeek/HTTP logs) followed by unexpected interpreters or script engines executing (python, ruby, sh) spawned from browser processes or user sessions, rapid on-disk staging in /tmp, and outbound connections that deviate from baseline. Defender sees: uncommon resource fetch → short-lived child process executions from user browser context → file writes in temp directories → anomalous outbound C2-like connections.', '{Linux}', 'x-mitre-analytic--32b5b330-2a40-4117-8999-395c23490614', 'DET0176', '[{"name": "auditd:SYSCALL", "channel": "execve: execve calls where a browser/webview process is parent and child is interpreter (python, sh, ruby) or downloader (curl, wget)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Application or browser logs (webview errors, plugin enumerations) indicating suspicious script evaluation or plugin loads", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "http::response: HTTP responses with suspicious content-type for scripts, long obfuscated javascript bodies, or redirects to exploit kit domains", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "linux:Sysmon", "channel": "New files in /tmp, /var/tmp, $HOME/.cache, executed within TimeWindow after browser HTTP fetch", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Connections", "channel": "Outbound connections from newly spawned child processes or from the browser to uncommon endpoints or on anomalous ports", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TempPathPatterns", "description": "Paths used for staging differ by distro and package manager; tune to include company-specific temp paths or exclude known benign build machines."}, {"field": "UserShellWhitelist", "description": "Whitelist known server/service accounts or CI/CD runners where shell executions are expected."}, {"field": "DomainRarityThreshold", "description": "Threshold for flagging domains based on internal popularity vs global rarity."}]', '2026-05-01 15:26:34.897325');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (365, 'AN1214', 'Analytic 1214', 'Detects custom archive routines by correlating script execution (Python, Perl, Bash) with creation of high-entropy files in temporary or user directories. Flags processes performing unusual bitwise operations or writing files without standard compression headers.', '{Linux}', 'x-mitre-analytic--32ca8e2c-9c1e-4883-aa98-439efbfc76e4', 'DET0438', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of interpreters creating archive-like outputs without calling tar/gzip", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:FILE", "channel": "create: Creation of files with anomalous headers and entropy levels in /tmp or user directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "linux:osquery", "channel": "Detection of bitwise operations or custom encryption functions in memory traces", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "ArchivePaths", "description": "Directories monitored for anomalous archive creation (e.g., /tmp, /home)."}, {"field": "EntropyThreshold", "description": "Entropy score to flag files lacking recognizable compression headers."}, {"field": "ScriptAllowlist", "description": "Scripts/processes known to use custom compression methods."}]', '2026-05-01 15:26:34.898775');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (366, 'AN0015', 'Analytic 0015', 'From a defender’s perspective, suspicious bridging is observed when network devices begin allowing traffic that contradicts existing segmentation or access policies. Observable behaviors include sudden modifications to ACLs or firewall rules, unusual cross-boundary traffic flows (e.g., east-west communications across separated VLANs), or simultaneous ingress/egress anomalies. Multi-event correlation is key: configuration changes on a router/firewall followed by unexpected traffic patterns, especially from unusual sources, is a strong indicator of compromise.', '{"Network Devices"}', 'x-mitre-analytic--32d56b42-ff83-46d2-aeea-57a6958d3e83', 'DET0006', '[{"name": "NSM:Flow", "channel": "Unexpected flows between segmented networks or prohibited ports", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "networkdevice:syslog", "channel": "ACL/Firewall rule modification or new route injection", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Correlation window between configuration changes and abnormal traffic; tuned to match expected administrative change cycles."}, {"field": "ApprovedChangeList", "description": "Known authorized ACL/firewall changes; suppresses noise from legitimate maintenance."}, {"field": "GeoLocation", "description": "Geographic origin of new traffic patterns; helps distinguish benign remote offices from suspicious foreign access."}, {"field": "TrafficVolumeThreshold", "description": "Volume of cross-segment traffic; tuned to detect large-scale lateral flows without flagging small test connections."}]', '2026-05-01 15:26:34.900222');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (387, 'AN1517', 'Analytic 1517', 'User or script-based access to ~/.ssh or other directories containing private keys followed by unusual shell activity or network connections.', '{Linux}', 'x-mitre-analytic--3577f79d-0891-451b-a861-1a03a3688a93', 'DET0549', '[{"name": "auditd:SYSCALL", "channel": "openat", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "FilePathRegex", "description": "Directory/file path regex for ~/.ssh, *.pem, *.key, *.p12"}, {"field": "CommandLineMatch", "description": "Script or user agent seen accessing keys (e.g., cat ~/.ssh/id_rsa, tar ~/.gnupg)"}]', '2026-05-01 15:26:34.930739');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (367, 'AN0330', 'Analytic 0330', 'Ties inbound access to exposed services (ARD/VNC 5900, SSH 22, ScreenSharing, web services) with process crashes in unified logs and abnormal child processes spawned under those services (e.g., bash, curl) to indicate exploitation.', '{macOS}', 'x-mitre-analytic--32ef36a3-3112-40a1-84d0-323b7b86cb5b', 'DET0118', '[{"name": "macos:unifiedlog", "channel": "process ''crashed''|''EXC_BAD_ACCESS'' for sshd, screensharingd, httpd; launchd restarts of these daemons.", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:osquery", "channel": "parent_name in (''sshd'',''httpd'',''screensharingd'') spawning shells or scripting runtimes.", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Inbound to 22/5900/8080 and follow-on internal connections.", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ServicePortSet", "description": "22, 5900, 8080/8443 by default."}, {"field": "AllowedAdmins", "description": "MDM/jump-host IPs allowed to manage endpoints."}, {"field": "TimeWindow", "description": "Default: 10 minutes."}]', '2026-05-01 15:26:34.901525');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (368, 'AN0407', 'Analytic 0407', 'Detection of iptables, nftables, or firewalld rule modifications. Correlation of sudden drops in active firewall rules with suspicious processes suggests adversarial evasion.', '{Linux}', 'x-mitre-analytic--3327048a-e90c-47e5-9b67-d2ecaa89523c', 'DET0145', '[{"name": "auditd:SYSCALL", "channel": "execve: iptables, nft, firewall-cmd modifications", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:osquery", "channel": "execution of known firewall binaries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AllowedScripts", "description": "Baseline admin scripts allowed to make firewall modifications."}]', '2026-05-01 15:26:34.903072');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (369, 'AN0013', 'Analytic 0013', 'Execution of renamed or relocated native macOS utilities with uncommon names or non-default paths (e.g., renamed `osascript`, `bash`, or `curl`).', '{macOS}', 'x-mitre-analytic--3349af7c-3cea-4424-b2a4-056fedb63831', 'DET0005', '[{"name": "macos:unifiedlog", "channel": "subsystem=com.apple.process", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fileevents", "channel": "/var/log/quarantine.log", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "PathDeviation", "description": "Path deviation from expected directory (e.g., /usr/bin/ vs /tmp/)"}, {"field": "BinaryHashReputation", "description": "Enable tuning based on hash matching known signed versions vs suspicious clones"}, {"field": "UserRole", "description": "Scope detections based on non-admin users using admin-level tools"}]', '2026-05-01 15:26:34.904449');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (370, 'AN2061', 'Analytic 2061', 'Much of this takes place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (371, 'AN0259', 'Analytic 0259', 'Detects creation or modification of cron jobs via crontab, /etc/cron.* directories, or systemd timer units with execution by unusual users or non-standard intervals.', '{Linux}', 'x-mitre-analytic--3374a404-06f9-4b32-bf94-5ac688fb9dad', 'DET0094', '[{"name": "auditd:SYSCALL", "channel": "write, rename", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "crontab, systemd_timers", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}]', '[{"field": "CronSchedulePattern", "description": "Look for high-frequency or off-hour scheduling patterns."}, {"field": "ServiceUser", "description": "Unusual users scheduling jobs (e.g., www-data, nobody)."}, {"field": "BinaryEntropy", "description": "Abnormal scripts or binaries tied to the scheduled job."}]', '2026-05-01 15:26:34.907868');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (372, 'AN1399', 'Analytic 1399', 'Detects process injection by correlating memory manipulation API calls (e.g., VirtualAllocEx, WriteProcessMemory), suspicious thread creation (e.g., CreateRemoteThread), and unusual DLL loads within another process''s context.', '{Windows}', 'x-mitre-analytic--337976cc-5fd5-49e8-abcb-79f27d19382c', 'DET0508', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "API calls", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "AccessMask", "description": "Specific access rights used during process handle acquisition, e.g., PROCESS_VM_WRITE"}, {"field": "TimeWindow", "description": "Time correlation window between API calls and thread creation events"}, {"field": "InjectedProcessList", "description": "Known high-value targets often abused for injection (e.g., lsass.exe, explorer.exe)"}]', '2026-05-01 15:26:34.909487');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (373, 'AN0544', 'Analytic 0544', 'Detects conditional access policy changes, exclusion of accounts from MFA enforcement, or registration of new MFA factors by non-admin or anomalous users.', '{"Identity Provider"}', 'x-mitre-analytic--33b7f7b2-b79c-4893-bd5c-2d5638bf5786', 'DET0190', '[{"name": "azure:signinlogs", "channel": "Modify Conditional Access Policy", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:unified", "channel": "User excluded from MFA or MFA method registered", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "PrivilegedRoles", "description": "Roles permitted to modify MFA settings in IdP; helps tune detection of unauthorized changes."}]', '2026-05-01 15:26:34.910863');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (409, 'AN0049', 'Analytic 0049', 'Adversary runs discovery commands such as `ps aux`, `systemctl status`, or `cat /etc/init.d/` to enumerate security software or services. Often occurs alongside privilege escalation or bash script execution.', '{Linux}', 'x-mitre-analytic--3928ff9c-961e-455c-a2b1-d79ca788591f', 'DET0016', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExecutableName", "description": "Adjust for custom script names or wrappers used in the environment"}, {"field": "TimeWindow", "description": "Tuning threshold for multiple enumeration commands within short duration"}]', '2026-05-01 15:26:34.964664');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (374, 'AN1604', 'Analytic 1604', 'Adversary uses built-in OS tools or API calls to create local or domain accounts for persistence or lateral movement. Tools such as ''net user'', PowerShell, or MMC snap-ins may be used. Detection focuses on Event ID 4720 paired with process lineage and user context.', '{Windows}', 'x-mitre-analytic--33d574c3-8e9b-462d-b3d1-09e64c2fa8c7', 'DET0583', '[{"name": "WinEventLog:Security", "channel": "EventCode=4720", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Correlation between Event ID 4720 and creating process may vary by environment and automation delays"}, {"field": "ParentProcessName", "description": "Tools like net.exe or powershell.exe can be normal or malicious depending on user context"}, {"field": "UserContext", "description": "System vs. administrator vs. low-privilege user context changes alert criticality"}]', '2026-05-01 15:26:34.912409');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (375, 'AN1026', 'Analytic 1026', 'Behavioral detection of domain group enumeration via ldapsearch or custom scripts leveraging LDAP over the network.', '{Linux}', 'x-mitre-analytic--3415a6fa-a447-42f3-8155-68cf5d7cbcb3', 'DET0360', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "sshd logs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "ldap.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "LDAPQueryDepth", "description": "Tunable based on number of LDAP queries before flagging suspicious behavior."}, {"field": "CommandPattern", "description": "Pattern matching against common ldapsearch or shell enumeration flags."}]', '2026-05-01 15:26:34.913716');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (376, 'AN0814', 'Analytic 0814', 'Detects injection or tampering of DLLs in hybrid identity agents (e.g., AzureADConnectAuthenticationAgentService), registry or configuration changes tied to PTA/AD FS, and anomalous LSASS or AD FS module loads correlated with authentication anomalies.', '{Windows}', 'x-mitre-analytic--344f0add-d372-4e0e-88c6-f48e6b424434', 'DET0293', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Security", "channel": "EventCode=5136", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:Security", "channel": "Anomalous logon without MFA enforcement", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "WatchedServices", "description": "Hybrid identity services monitored for tampering, e.g., PTA agent, AD FS."}, {"field": "TimeWindow", "description": "Window correlating DLL/module load events with logon anomalies."}]', '2026-05-01 15:26:34.914905');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (377, 'AN0827', 'Analytic 0827', 'Processes attempting raw disk access to overwrite sensitive structures such as the MBR or partition table using \\.\PhysicalDrive notation. Detection relies on correlating process creation, privilege escalation, and raw sector writes in Sysmon and Security logs.', '{Windows}', 'x-mitre-analytic--34560ac3-2e05-4394-8145-0cd6071c1680', 'DET0297', '[{"name": "WinEventLog:Security", "channel": "EventCode=4673", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "WinEventLog:Sysmon", "channel": "Raw write attempts targeting \\\\.\\PhysicalDrive0 or sector 0 (MBR/partition table)", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}]', '[{"field": "SectorRange", "description": "Specify which sectors are considered critical (MBR, partition table) to reduce noise."}, {"field": "ProcessWhitelist", "description": "Exclude legitimate low-level disk management or imaging tools used by administrators."}]', '2026-05-01 15:26:34.917149');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (378, 'AN0686', 'Analytic 0686', 'Correlate MFA push fatigue or unusual consent grant attempts with call activity where adversaries may have socially engineered the user over voice.', '{"Identity Provider"}', 'x-mitre-analytic--345af006-d658-4f22-aef6-b1cfc0058875', 'DET0245', '[{"name": "m365:unified", "channel": "Unusual MFA requests or OAuth consent events temporally aligned with user-reported vishing call", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MFARequestThreshold", "description": "Number of MFA push requests within a timeframe aligned to a suspicious call"}, {"field": "ConsentGrantPatterns", "description": "Unusual OAuth consent URLs or delegated scopes"}]', '2026-05-01 15:26:34.918414');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (379, 'AN0750', 'Analytic 0750', 'Logon via RDP or WMI by a user account followed by uncommon command execution, file manipulation, or lateral network connections.', '{Windows}', 'x-mitre-analytic--34c5e959-876b-4851-8ebf-bfaf97e9e609', 'DET0269', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Correlation window between remote login and post-access activity"}, {"field": "LogonUser", "description": "Limit to service accounts or privileged users for higher fidelity"}, {"field": "RemoteHostList", "description": "Allowlisting known admin jumpboxes or deployment tools"}]', '2026-05-01 15:26:34.91968');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (380, 'AN0518', 'Analytic 0518', 'Detect anomalous use of scp, rsync, curl, or third-party sync apps transferring executables into user directories. Correlate new file creation with immediate execution events.', '{macOS}', 'x-mitre-analytic--34d6af16-fe37-458c-b15c-413ff2d5b2f7', 'DET0183', '[{"name": "macos:unifiedlog", "channel": "Execution of scp, rsync, curl with remote destination", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "File created in ~/Library/LaunchAgents or executable directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "SyncApplications", "description": "Whitelisted apps like Dropbox or OneDrive if sanctioned"}, {"field": "EntropyThreshold", "description": "Adjust threshold for unusual filenames/hashes transferred internally"}]', '2026-05-01 15:26:34.920976');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (381, 'AN0770', 'Analytic 0770', 'Detection of rogue Domain Controller registration and Active Directory replication abuse by correlating: (1) creation/modification of nTDSDSA and server objects in the Configuration partition, (2) unexpected usage of Directory Replication Service SPNs (GC/ or E3514235-4B06-11D1-AB04-00C04FC2DCD2), (3) replication RPC calls (DrsAddEntry, DrsReplicaAdd, GetNCChanges) originating from non-DC hosts, and (4) Kerberos authentication by non-DC machines using DRS-related SPNs. These events in combination, especially from hosts outside the Domain Controllers OU, may indicate DCShadow or rogue DC activity.', '{Windows}', 'x-mitre-analytic--34fecfa5-24fb-46c1-955f-68ecd4cc402c', 'DET0276', '[{"name": "WinEventLog:Security", "channel": "EventCode=4928", "x_mitre_data_component_ref": "x-mitre-data-component--18b236d8-7224-488f-9d2f-50076a0f653a"}, {"name": "WinEventLog:Security", "channel": "EventCode=4929", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"name": "WinEventLog:Security", "channel": "EventCode=4662", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}, {"name": "m365:dirsync", "channel": "Replication cookie changes involving Configuration partition with new server/nTDSDSA objects.", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "NSM:Flow", "channel": "DrsAddEntry, DrsReplicaAdd, GetNCChanges calls between non-DC and DCs.", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Window (seconds) between nTDSDSA object creation and subsequent replication traffic from same host (default 300s)."}, {"field": "AllowedReplicationPartners", "description": "List of legitimate DCs authorized for replication to reduce false positives."}, {"field": "SuspiciousSPNs", "description": "SPNs indicating replication service usage (GC/, GUID E3514235-4B06-11D1-AB04-00C04FC2DCD2)."}, {"field": "NonDCObjectCreationAlert", "description": "Trigger alerts only when AD object creation is by accounts not in Domain Admins or Enterprise Admins groups."}]', '2026-05-01 15:26:34.922733');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (382, 'AN0710', 'Analytic 0710', 'Suspicious reuse of SSH agent sockets across multiple users or processes, anomalous access to ~/.ssh/ or /tmp/ssh-* sockets, and abnormal patterns of lateral movement via SSH without new authentication events. Defender view: detect when one process accesses another user''s SSH agent or when an existing SSH connection is used to pivot unexpectedly.', '{Linux}', 'x-mitre-analytic--3517708a-f80e-4335-a122-65b9b3505e8d', 'DET0256', '[{"name": "auditd:SYSCALL", "channel": "open or connect syscalls on /tmp/ssh-* or $SSH_AUTH_SOCK", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "auditd:EXECVE", "channel": "Execution of ssh/scp/sftp without corresponding authentication log", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "Missing new login event but session activity continues", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "UserContext", "description": "Tune alerts for cross-user access to SSH agent sockets."}, {"field": "TimeWindow", "description": "Correlate lack of authentication with lateral SSH activity within a short timeframe."}]', '2026-05-01 15:26:34.924324');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (383, 'AN1272', 'Analytic 1272', 'Unusual mounting of loopback or pseudo file systems not aligned with legitimate administrative activity. Defender view: monitoring auditd and syslog for mount commands involving suspicious mount points, reserved blocks, or device mappings indicative of hidden partitions.', '{Linux}', 'x-mitre-analytic--35300a0c-e135-4865-9fe5-9d65a1c77dda', 'DET0461', '[{"name": "auditd:SYSCALL", "channel": "mount or losetup commands creating hidden or encrypted FS", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:syslog", "channel": "Sudo or root escalation followed by filesystem mount commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AllowedMountPoints", "description": "Whitelist standard mount points to reduce false positives."}, {"field": "UserContext", "description": "Flag root escalation during mount operations."}]', '2026-05-01 15:26:34.925667');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (384, 'AN0149', 'Analytic 0149', 'Abnormal Apple Mail use, including internal email relays followed by file execution or script events (e.g., attachments launched via Preview, terminal triggered from Mail.app)', '{macOS}', 'x-mitre-analytic--3533fba3-e80d-4ad0-be45-62460b28ad7c', 'DET0054', '[{"name": "macos:unifiedlog", "channel": "com.apple.mail.* exec.*", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "curl|osascript.*open location", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ExecutionChainDepth", "description": "Number of child processes stemming from Mail.app"}, {"field": "MailScriptFlag", "description": "Toggle on scripting detection within mail context"}]', '2026-05-01 15:26:34.92684');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (385, 'AN0039', 'Analytic 0039', 'Scripting or CLI tool access to ~/Library/Application Support/Google/Chrome or ~/Library/Safari bookmarks, cookies, or history databases. Detection relies on unexpected processes accessing or reading from these locations.', '{macOS}', 'x-mitre-analytic--353e902d-b33c-466b-9276-5f224a259934', 'DET0013', '[{"name": "macos:unifiedlog", "channel": "Access to ~/Library/*/Safari or Chrome directories by non-browser processes", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "process reading browser configuration paths", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "BrowserDBPath", "description": "System-specific paths to browser databases in user Library folders"}, {"field": "NonBrowserProcessList", "description": "Processes not expected to touch browser DBs (e.g., curl, bash, python)"}]', '2026-05-01 15:26:34.928238');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (386, 'AN0498', 'Analytic 0498', 'Correlated evidence of anomalous browser/network behavior (suspicious external resource fetches and script injection patterns) followed by atypical child processes, ephemeral execution contexts, memory modification or process injection, and unexpected file drops. Defender sees network requests to previously unseen/suspicious domains or resources + browser process spawning unusual children or loading unsigned modules + file writes or registry changes shortly after those requests.', '{Windows}', 'x-mitre-analytic--35701083-a327-4f68-a426-13751b9743c3', 'DET0176', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Application", "channel": "Browser or plugin/application logs showing script errors, plugin enumerations, or unusual extension load events", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "Memory Modification / Unmapped module load or suspicious RWX allocations in the process space of a browser process", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "http.request: HTTP requests and responses for specific script resources, unexpected content-types (application/octet-stream for script URLs), suspicious referrers, or obfuscated javascript resources", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Correlation time window between suspicious network fetch and subsequent process/file events. Tweak for environment latency and caching; default 2 minutes."}, {"field": "KnownGoodDomainsList", "description": "Allowlist of high-volume, benign domains used by corporate sites or CDNs to reduce false positives."}, {"field": "PayloadEntropyThreshold", "description": "Entropy threshold for downloaded script/binary content to surface likely obfuscated/packed payloads."}, {"field": "UserContext", "description": "Exclude or treat differently known administrative service accounts or build machines versus end-user contexts."}]', '2026-05-01 15:26:34.929442');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (388, 'AN1485', 'Analytic 1485', 'launchd or user-invoked processes (ssh, socat) encapsulating traffic via SSH tunnels, VPN-style tooling, or DNS-over-HTTPS clients. Defender sees outbound TLS traffic with embedded DNS or RDP payloads.', '{macOS}', 'x-mitre-analytic--359ab8ab-f306-4e67-8ff4-f8e1c8ec7db3', 'DET0538', '[{"name": "macos:unifiedlog", "channel": "process execution of ssh with -L/-R forwarding flags", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "encrypted outbound traffic carrying unexpected application data", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ExpectedDoHResolvers", "description": "Known legitimate DoH resolvers used in environment."}, {"field": "PayloadEntropyThreshold", "description": "Flag excessive randomness in payloads on standard ports."}]', '2026-05-01 15:26:34.932051');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (389, 'AN0082', 'Analytic 0082', 'Suspicious long-lived or high-throughput connections by non-Apple signed apps or processes not commonly associated with network uploads. Detect background processes using open sockets for data egress.', '{macOS}', 'x-mitre-analytic--35a5d72b-6c69-498a-9118-14cd6c85a57a', 'DET0028', '[{"name": "macos:unifiedlog", "channel": "process + network metrics correlation for bandwidth saturation", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:unifiedlog", "channel": "exec or spawn calls to proxy tools or torrent clients", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ProcessSignedStatus", "description": "Non-signed or non-Apple signed binaries can raise confidence levels."}, {"field": "DataRateThreshold", "description": "Observed data rate per process over time (e.g., MB/s)."}]', '2026-05-01 15:26:34.933294');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (390, 'AN1246', 'Analytic 1246', 'Detection correlates abnormal installation or modification of root or code-signing certificates, creation/modification of suspicious registry keys for trust providers, and unusual module loads from non-standard locations. Identifies unsigned or improperly signed executables bypassing trust prompts, combined with persistence artifacts.', '{Windows}', 'x-mitre-analytic--35b0b263-f85d-4e6a-8bcb-5e2c1a9da080', 'DET0452', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TrustedPublisherList", "description": "Baseline list of approved certificate authorities that should not change frequently"}, {"field": "FilePathAllowList", "description": "Exclusions for legitimate enterprise-signed binaries stored in unusual directories"}, {"field": "TimeWindow", "description": "Correlation window for registry + file + process activity"}]', '2026-05-01 15:26:34.934583');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (391, 'AN1166', 'Analytic 1166', 'Automated scripts or repeated CLI/API requests that trigger application backends to consume high CPU or memory (e.g., Apache/PHP, MySQL, mail servers), resulting in syslog errors and excessive process spawning.', '{Linux}', 'x-mitre-analytic--35c7be24-c1c0-4ddc-9356-dec5e39414be', 'DET0415', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Error/warning logs from services indicating load spike or worker exhaustion", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Sustained abnormal inbound request rate targeting application ports (e.g., 80/443/25)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "SyslogErrorRate", "description": "Defines number of critical errors in logs within time window."}, {"field": "PortRequestSpikeThreshold", "description": "Spike rate on monitored service port triggering alert."}, {"field": "ProcessSpawnRate", "description": "Rate of process creation that may overwhelm the system."}]', '2026-05-01 15:26:34.935893');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (392, 'AN0090', 'Analytic 0090', 'Binaries or applications executed with tampered or unverifiable code signatures. Often tied to Gatekeeper bypasses, App Translocation, or use of unsigned launch daemons by untrusted users.', '{macOS}', 'x-mitre-analytic--35d9b6e6-aed8-4e9e-b6ee-e683d9c17fd0', 'DET0031', '[{"name": "macos:unifiedlog", "channel": "subsystem:syspolicyd", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fileevents", "channel": "/var/log/install.log", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "CodeSigningStatus", "description": "Filters such as ''Unsigned'', ''NotTrusted'', or ''ModifiedSinceSigning'' may vary by policy enforcement level"}, {"field": "UserContext", "description": "Tune whether detection applies to all users or excludes trusted admin accounts"}, {"field": "ExecutablePathPrefix", "description": "Enable tuning for known valid locations (e.g., /Applications) vs. suspicious paths (/Users/Shared)"}]', '2026-05-01 15:26:34.937332');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (393, 'AN2059', 'Analytic 2059', 'Much of this takes place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (394, 'AN0141', 'Analytic 0141', 'Suspicious file creation or modification in directories ignored by XProtect or AV exclusions (e.g., ~/Library, temporary cache directories). Defender perspective: monitor file events in ignored paths with correlation to execution or persistence activity.', '{macOS}', 'x-mitre-analytic--3643a313-1aa7-44d1-b3e2-e97ad65c6837', 'DET0051', '[{"name": "macos:unifiedlog", "channel": "file creation in AV exclusion directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "process writes or modifies files in excluded paths", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AVExclusionPaths", "description": "Paths ignored by AV/XProtect that should be monitored for abnormal writes."}, {"field": "ProcessContext", "description": "Expected user or application context writing to excluded directories."}]', '2026-05-01 15:26:34.940326');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (395, 'AN0069', 'Analytic 0069', 'Detects unauthorized access, copying, or modification of Kerberos ccache files (krb5cc_%UID% or krb5.ccache) in /tmp or custom paths defined by KRB5CCNAME. Correlates file access with suspicious processes (e.g., credential dumping tools) and subsequent anomalous Kerberos authentication requests from non-standard processes.', '{Linux}', 'x-mitre-analytic--3651d7d0-dfc7-4b36-aaf2-4eb0eb39167d', 'DET0024', '[{"name": "auditd:SYSCALL", "channel": "open: File access attempt on /tmp/krb5cc_* or /tmp/krb5.ccache", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execve: Execution of klist, kinit, or tools interacting with ccache outside normal user context", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CcachePathBaseline", "description": "Expected directories or environment variable (KRB5CCNAME) paths for ccache files in the environment."}, {"field": "AllowedProcesses", "description": "Baseline list of processes legitimately interacting with ccache (e.g., klist, kinit)."}, {"field": "TimeWindow", "description": "Correlation window for linking file access, process execution, and Kerberos requests."}]', '2026-05-01 15:26:34.942023');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (396, 'AN1162', 'Analytic 1162', 'Abuse of SaaS platforms such as Confluence, GitHub, SharePoint Online, or Slack to access excessive internal documentation or export source code/data. Includes use of tokens or browser automation from unapproved IPs.', '{SaaS}', 'x-mitre-analytic--3655f892-ed0d-4b76-9173-ecb7eebacd8a', 'DET0413', '[{"name": "saas:confluence", "channel": "access.content", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:slack", "channel": "Exported file or accessed admin API", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "APIUsageThreshold", "description": "Number of API calls or files accessed before triggering detection."}, {"field": "KnownSafeIPs", "description": "Whitelist of internal IPs/users that may be excluded from detection."}]', '2026-05-01 15:26:34.943528');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (397, 'AN0956', 'Analytic 0956', 'Token replay or impersonation in federated logins without interactive browser session or MFA prompts.', '{"Identity Provider"}', 'x-mitre-analytic--367cfbd9-fcfd-4336-863e-b6917ff71cb4', 'DET0338', '[{"name": "azure:signinlogs", "channel": "TokenIssuanceStart, TokenIssuanceSuccess", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "m365:unified", "channel": "login using refresh_token with no preceding authentication context", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "MFAContextRequired", "description": "Customize for accounts where MFA must always precede token issuance"}, {"field": "RefreshTokenReuseThreshold", "description": "Threshold for number of times a refresh token is reused without re-auth"}]', '2026-05-01 15:26:34.945047');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (398, 'AN0294', 'Analytic 0294', 'Unsigned or scripting-based processes invoking password cracking binaries or accessing hashed credential artifacts post-login', '{macOS}', 'x-mitre-analytic--3682e3c9-33a7-4328-b0c5-73c8bbcb9b53', 'DET0105', '[{"name": "macos:unifiedlog", "channel": "process and file events via log stream", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UnsignedBinaryPath", "description": "Path to untrusted binaries launched by user"}, {"field": "UserPrivilegeLevel", "description": "Helps distinguish between system and user-launched activity"}]', '2026-05-01 15:26:34.946926');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (399, 'AN1338', 'Analytic 1338', 'Multiple failed login attempts across different users using common password patterns (e.g., ''Welcome2023'')', '{macOS}', 'x-mitre-analytic--36c2c2fb-0bea-40fe-9032-c0758d381de5', 'DET0487', '[{"name": "macos:unifiedlog", "channel": "Login Window and Authd errors", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "RetryCountThreshold", "description": "Total number of attempts before alerting"}, {"field": "CommonPasswordList", "description": "List of passwords considered suspicious due to widespread use"}]', '2026-05-01 15:26:34.948414');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (400, 'AN1570', 'Analytic 1570', 'Defenders may observe adversary attempts to downgrade system images by monitoring for anomalous file transfers of OS image files (via TFTP, FTP, SCP), configuration changes pointing boot system variables to older image files, unexpected OS version strings after reboot, and checksum mismatches against approved baseline images. Suspicious chains include transfer of an older image, alteration of boot configuration, and reboot/reload of the device. Adversaries may also tamper with CLI output to disguise downgrade attempts, requiring independent validation of OS version and integrity.', '{"Network Devices"}', 'x-mitre-analytic--370daadc-e640-4487-8ba0-c897f46459bc', 'DET0569', '[{"name": "networkdevice:cli", "channel": "Execution of commands such as ''copy tftp flash'', ''boot system <image>'', ''reload''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:config", "channel": "Configuration changes referencing older image versions or unexpected boot parameters", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "networkdevice:syslog", "channel": "OS version query results inconsistent with expected or approved version list", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "ApprovedFirmwareVersions", "description": "Whitelist of supported and validated OS versions for devices; helps reduce false positives."}, {"field": "ChecksumBaseline", "description": "Baseline cryptographic hashes of valid OS images; deviations indicate possible downgrade or tampering."}, {"field": "TimeWindow", "description": "Correlation period to detect the chain of file transfer → boot config change → reboot event."}, {"field": "AuthorizedAdminAccounts", "description": "Accounts authorized to perform OS upgrades/downgrades; anomalies suggest misuse or compromise."}]', '2026-05-01 15:26:34.94994');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (401, 'AN0439', 'Analytic 0439', 'VMware services or management daemons generating HTTP POST requests to webhook endpoints, chained with unusual datastore or log access. Defender perspective: exfiltration from VM logs or disk images over webhook URLs.', '{ESXi}', 'x-mitre-analytic--37166782-8770-4812-b70c-27f3c705489b', 'DET0153', '[{"name": "esxi:hostd", "channel": "datastore file access", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "esxi:vmkernel", "channel": "HTTPS POST connections to webhook endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "DatastoreExfilThreshold", "description": "Minimum data volume to flag exfiltration attempts from VM files."}, {"field": "ApprovedIntegrations", "description": "Whitelisted CI/CD or automation webhooks tied to vSphere/ESXi."}]', '2026-05-01 15:26:34.951526');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (402, 'AN1501', 'Analytic 1501', 'Detects adversary abuse of Transactional NTFS (TxF) and undocumented process loading mechanisms (e.g., NtCreateProcessEx) to create a hollowed process from an uncommitted, maliciously tainted file image in memory, later executed via NtCreateThreadEx.', '{Windows}', 'x-mitre-analytic--37d6450b-6c90-48dd-b69d-161099913851', 'DET0544', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "CreateTransaction, CreateFileTransacted, RollbackTransaction, NtCreateProcessEx, NtCreateThreadEx", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "TransactionExecutableNamePattern", "description": "Pattern of legitimate executables often used as doppelgänging targets (e.g., svchost.exe, calc.exe)"}, {"field": "TimeWindow_TransactionToExecution", "description": "Time delta between TxF rollback and thread creation in hollowed process"}, {"field": "ThreadStartEntropyThreshold", "description": "Entropy level of thread start address in memory used to detect obfuscated shellcode"}, {"field": "TxF API Call Frequency Threshold", "description": "Limit on CreateTransaction + RollbackTransaction sequences per process"}]', '2026-05-01 15:26:34.952947');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (403, 'AN0371', 'Analytic 0371', 'Detects outbound traffic from hostd/vpxa or guest VM interfaces using unauthorized protocols such as FTP, HTTP POST bursts, or long-lived DNS tunnels.', '{ESXi}', 'x-mitre-analytic--3810988a-78be-4628-a9a5-500020f9c075', 'DET0131', '[{"name": "esxi:hostd", "channel": "logline inspection", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:vmkernel", "channel": "protocol egress", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "GuestTrafficBaseline", "description": "Expected protocols used by VMs attached to host interfaces."}, {"field": "ServiceAccountProfile", "description": "Unexpected network activity from hypervisor processes or monitoring agents."}]', '2026-05-01 15:26:34.954356');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (404, 'AN0078', 'Analytic 0078', 'Detects HTTP or HTTPS communication initiated by shell-based scripts or management daemons, especially those reaching public IPs over ports 80/443 using embedded curl or wget.', '{ESXi}', 'x-mitre-analytic--38205f16-18da-4d04-ae54-f5143b75c938', 'DET0027', '[{"name": "NSM:Flow", "channel": "SPAN or port-mirrored HTTP/S", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "esxi:shell", "channel": "/root/.ash_history or /etc/init.d/*", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ShellScriptMatch", "description": "Match on commands like `wget https://*`, `curl -s`"}, {"field": "ExternalConnectionFilter", "description": "Public IPs or external DNS hostnames"}]', '2026-05-01 15:26:34.955725');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (405, 'AN0966', 'Analytic 0966', 'Detection of pbpaste/pbcopy clipboard access by processes without terminal sessions or linked to launch agents, potentially staged for collection.', '{macOS}', 'x-mitre-analytic--38252d77-0b46-4e00-8732-3ce1f8491472', 'DET0341', '[{"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExecutionChainLength", "description": "How many chained or embedded processes to track for correlation."}, {"field": "TerminalSession", "description": "Whether the pbpaste/pbcopy action is tied to a user terminal."}, {"field": "BinaryPath", "description": "Adjust if clipboard tooling is relocated (e.g., /opt/empyre/pbpaste)."}]', '2026-05-01 15:26:34.957444');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (406, 'AN1203', 'Analytic 1203', 'Detects spoofed emails by analyzing mail server logs (e.g., Postfix, Sendmail) for mismatched header fields, failed SPF/DKIM checks, and anomalies in SMTP proxy logs. Defender observes discrepancies between sending domain, return-path domain, and message metadata.', '{Linux}', 'x-mitre-analytic--38300670-8c96-4f80-bc1b-d69242023a20', 'DET0431', '[{"name": "linux:syslog", "channel": "SPF fail OR DKIM fail OR DMARC fail OR mismatched from_domain vs return_path_domain", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "SenderDomainWhitelist", "description": "Defines approved sender domains to suppress alerts for expected mismatches, reducing false positives."}, {"field": "TimeWindow", "description": "Sets correlation period for repeated spoofing attempts to flag campaigns vs. isolated misconfigurations."}]', '2026-05-01 15:26:34.959027');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (407, 'AN1580', 'Analytic 1580', 'Detects snapshot sharing, backup exports, or data object transfers from victim-owned cloud accounts to other cloud identities within the same provider (e.g., AWS, Azure) using snapshot sharing, S3 bucket policy updates, or SAS URI generation.', '{IaaS}', 'x-mitre-analytic--383dda28-1d76-4605-a53d-07829f3d7ef8', 'DET0573', '[{"name": "AWS:CloudTrail", "channel": "ModifySnapshotAttribute", "x_mitre_data_component_ref": "x-mitre-data-component--f1eb6ea9-f3ab-414f-af35-2d5427199984"}, {"name": "AWS:CloudTrail", "channel": "PutBucketPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}, {"name": "AWS:CloudTrail", "channel": "CreateSnapshot", "x_mitre_data_component_ref": "x-mitre-data-component--3da222e6-53f3-451c-a239-0b405c009432"}, {"name": "AWS:CloudTrail", "channel": "CopySnapshot", "x_mitre_data_component_ref": "x-mitre-data-component--8bc66f94-54a9-4be4-bdd1-fe90df643774"}, {"name": "AWS:VPCFlowLogs", "channel": "High volume internal-to-internal IP transfer or cross-account cloud transfer", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CrossAccountIDList", "description": "List of external cloud accounts authorized for snapshot or bucket sharing"}, {"field": "Region", "description": "Geographic region in which the sharing occurs (may impact logging availability)"}, {"field": "VolumeSizeThresholdGB", "description": "Threshold to alert on snapshot size or object volume"}, {"field": "TimeWindow", "description": "Temporal window between snapshot creation and external sharing"}]', '2026-05-01 15:26:34.960484');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (408, 'AN0408', 'Analytic 0408', 'Detection of PF firewall rule modifications via pfctl, socketfilterfw, or defaults write to com.apple.alf. Adversaries often disable firewall profiles entirely or whitelist malicious processes.', '{macOS}', 'x-mitre-analytic--38c74fcf-2a4d-45cd-8465-b5d80a605bd8', 'DET0145', '[{"name": "macos:unifiedlog", "channel": "pfctl -d, socketfilterfw --setglobalstate off, or modifications to com.apple.alf", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "PFConfigFiles", "description": "Monitor for baseline pf.conf and custom rule file modifications."}]', '2026-05-01 15:26:34.961764');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (410, 'AN1352', 'Analytic 1352', 'Detection of adversary attempts to enumerate containers, pods, nodes, and related resources within containerized environments. Defenders may observe anomalous API calls to Docker or Kubernetes (e.g., ''docker ps'', ''kubectl get pods'', ''kubectl get nodes''), unusual account activity against the Kubernetes dashboard, or unexpected queries against container metadata endpoints. These events should be correlated with user context and network activity to reveal resource discovery attempts.', '{Containers}', 'x-mitre-analytic--3947e311-cada-4eab-b4fd-1ea1f3fc3485', 'DET0490', '[{"name": "kubernetes:apiserver", "channel": "list or get requests against pods, deployments, or nodes", "x_mitre_data_component_ref": "x-mitre-data-component--07688e40-a7fa-4436-937f-1216674341a0"}, {"name": "docker:daemon", "channel": "docker ps, docker inspect, or docker images commands", "x_mitre_data_component_ref": "x-mitre-data-component--91b3ed33-d1b5-4c4b-a896-76c55eb3cfd8"}]', '[{"field": "UserAllowList", "description": "Defines which service accounts and admin roles are expected to perform discovery actions. Activity by non-allowlisted identities may indicate adversary discovery."}, {"field": "TimeWindow", "description": "Specifies correlation period (e.g., 10m) for linking multiple discovery attempts across API and daemon logs."}, {"field": "PodQueryThreshold", "description": "Defines threshold for number of pod/node enumeration requests by a single user. Excessive queries may indicate scanning activity."}]', '2026-05-01 15:26:34.965894');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (411, 'AN1002', 'Analytic 1002', 'Use of gsettings or direct Display Manager modifications to hide users from greeter login screen. Defender view: anomalous command execution modifying org.gnome.login-screen or other greeter configurations.', '{Linux}', 'x-mitre-analytic--397a553d-c08d-497e-8fb0-9526f5a205bc', 'DET0353', '[{"name": "auditd:EXECVE", "channel": "Execution of gsettings set org.gnome.login-screen disable-user-list true", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:FILE", "channel": "Modification of Display Manager configuration files (/etc/gdm3/*, /etc/lightdm/*)", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "DisplayManagerScope", "description": "Specify which Display Managers are in use to minimize noise."}]', '2026-05-01 15:26:34.967285');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (412, 'AN1217', 'Analytic 1217', 'Detects binary movement or copying between untrusted and trusted paths (e.g., /tmp/ → /usr/bin/ or /etc/init.d/) that may indicate persistence attempts or cleanup of origin traces.', '{Linux}', 'x-mitre-analytic--39aa9168-6f3b-4179-84f9-a6b8dcf90900', 'DET0439', '[{"name": "auditd:SYSCALL", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "RelocationPathPatterns", "description": "Match movement into known persistence or exclusion directories"}, {"field": "BinaryEntropyThreshold", "description": "Apply threshold to detect high-entropy relocations (e.g., packed malware)"}]', '2026-05-01 15:26:34.968734');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (413, 'AN1319', 'Analytic 1319', 'Modification of COR_PROFILER-related environment variables or Registry keys (COR_ENABLE_PROFILING, COR_PROFILER, COR_PROFILER_PATH), combined with anomalous .NET process creation or unmanaged DLL loads. Defender observes registry modifications, suspicious process creation with altered environment variables, and profiler DLLs loaded unexpectedly into .NET CLR processes.', '{Windows}', 'x-mitre-analytic--39d115fc-5e7b-423f-94da-a3b4242e07b8', 'DET0479', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AllowedProfilers", "description": "List of known good COR_PROFILER CLSIDs and DLLs expected in developer or monitoring environments."}, {"field": "ProcessScope", "description": "Processes expected to load COR_PROFILER (e.g., Visual Studio) for baseline comparison."}, {"field": "TimeWindow", "description": "Interval between registry modification or file creation and profiler DLL load into .NET processes."}, {"field": "ProfilerDllPaths", "description": "Directories considered legitimate for profiler DLLs; deviations should raise alerts."}]', '2026-05-01 15:26:34.970205');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (414, 'AN0477', 'Analytic 0477', 'Firmware image uploaded via TFTP/SCP or web interface followed by reboot or unexpected loss of connectivity.', '{"Network Devices"}', 'x-mitre-analytic--39d675d5-548d-4b35-8a8f-a6605ae3835d', 'DET0167', '[{"name": "NSM:Flow", "channel": "large upload to firmware interface port or path", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "networkdevice:firmware", "channel": "Firmware update initiated or bootloader tampering detected", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}]', '[{"field": "UploadSizeThreshold", "description": "Size of firmware images varies by vendor"}, {"field": "RebootWindow", "description": "Reboots outside of patch maintenance may be suspicious"}]', '2026-05-01 15:26:34.971574');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (415, 'AN0844', 'Analytic 0844', 'A source performs a closed-port sequence; the endpoint enables a PF/socketfilterfw rule or a background process binds a port; then a successful connection completes from the same source.', '{macOS}', 'x-mitre-analytic--39da0718-fa22-4f77-8bd2-ea8300087658', 'DET0302', '[{"name": "macos:unifiedlog", "channel": "exec: Execution of pfctl, socketfilterfw, launchctl start ssh/telnet, libpcap consumers.", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Firewall/PF anchor load or rule change events.", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "Sequence of REJ/S0 then SF success from same src_ip within TimeWindow.", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "PFAnchorPaths", "description": "Anchors/confs to monitor (/etc/pf.conf, /etc/pf.anchors/*)."}, {"field": "DevMode", "description": "Suppress expected PF testing on developer devices."}]', '2026-05-01 15:26:34.973315');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (770, 'AN0285', 'Analytic 0285', 'Detects web-based credential phishing by analyzing traffic to suspicious URLs that mimic login portals and POST credential content.', '{"Network Devices"}', 'x-mitre-analytic--6db136be-4e41-4cb7-8237-eee81ee6a3cd', 'DET0102', '[{"name": "NSM:Flow", "channel": "http.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Firewall", "channel": "proxy or TLS inspection logs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "UserAgent", "description": "Mismatched browser identifiers used by phishing kits"}, {"field": "URL_Path", "description": "Paths resembling known login forms but hosted on unknown domains"}]', '2026-05-01 15:26:35.500812');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (416, 'AN0623', 'Analytic 0623', 'Detects SCCM, Intune, or remote push execution spawning scripts or binaries from SYSTEM context or unusual consoles (e.g., cmtrace.exe launching PowerShell or cmd.exe).', '{Windows}', 'x-mitre-analytic--39ec0aa6-935a-44d3-b206-211981dec3bd', 'DET0223', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Application", "channel": "SCCM, Intune logs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ParentImageList", "description": "Allowlist of known SCCM-related binary spawners (e.g., ''CCMExec.exe'')"}, {"field": "UserContext", "description": "Expected deployment activity from scheduled system accounts"}, {"field": "TimeWindow", "description": "Unusual deployment timing outside standard maintenance hours"}]', '2026-05-01 15:26:34.975081');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (417, 'AN0547', 'Analytic 0547', 'Detects modifications to authorization plugins responsible for MFA enforcement and correlates with suspicious login sessions missing MFA prompts.', '{macOS}', 'x-mitre-analytic--3a19d0ff-833f-47ae-81a0-2516e91c7b25', 'DET0190', '[{"name": "macos:unifiedlog", "channel": "Modification of /Library/Security/SecurityAgentPlugins", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Login success without MFA step", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "WatchedPluginPaths", "description": "Paths to organization-deployed MFA authorization plugins."}]', '2026-05-01 15:26:34.976829');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (418, 'AN1494', 'Analytic 1494', 'Detects adversary behavior where a process enumerates and modifies another process''s memory using /proc/[pid]/maps and /proc/[pid]/mem files. This includes identifying gadgets via memory mappings and overwriting process memory via low-level file modification or dd usage.', '{Linux}', 'x-mitre-analytic--3a57e109-235d-497a-9c90-952ab8b749b6', 'DET0541', '[{"name": "auditd:SYSCALL", "channel": "open/write to /proc/*/mem or /proc/*/maps", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve of dd or sed targeting /proc/*/mem", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "linux:osquery", "channel": "/proc/*/maps access", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "TargetProcNameRegex", "description": "Regex list of high-value processes attackers may inject into, such as `sshd`, `nginx`, or `sleep`"}, {"field": "TimeWindowBetweenMapAccessAndMemWrite", "description": "Time span (e.g., <15s) between map read and memory write that may indicate enumeration-to-injection"}, {"field": "InvokerBinaryAllowlist", "description": "Allowlist of processes allowed to access /proc/[pid]/mem (e.g., gdb, strace)"}, {"field": "FileWriteThreshold", "description": "Alert if written bytes to /proc/[pid]/mem exceed a suspicious threshold (e.g., >4096 bytes)"}]', '2026-05-01 15:26:34.978231');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (419, 'AN1610', 'Analytic 1610', 'Abuse of JamPlus.exe to launch malicious payloads via crafted .jam files, resulting in abnormal process creation, command execution, or artifact generation outside of standard development workflows.', '{Windows}', 'x-mitre-analytic--3a5eea3b-b447-47c5-832d-6ced137b1597', 'DET0585', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "channel": "Unsigned or untrusted modules loaded during JamPlus.exe runtime", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "TimeWindow", "description": "Correlation time window (e.g., 0–30 minutes) for JamPlus.exe execution, child processes, and file/network events."}, {"field": "AllowedBuildHosts", "description": "Known developer systems where JamPlus.exe usage is expected; alerts are raised if executed elsewhere."}, {"field": "SuspiciousChildList", "description": "Child processes considered anomalous (e.g., PowerShell, cmd, wscript) when spawned by JamPlus.exe."}, {"field": "RarePathRegex", "description": "Regex patterns for non-standard or user-writable paths where JamPlus.exe drops artifacts."}]', '2026-05-01 15:26:34.979931');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (420, 'AN1317', 'Analytic 1317', 'Cause→effect chain in CI/dev desktops: (1) user triggers container run/pull after opening a doc/link/script, (2) newly created image/container uses unexpected external registry or entrypoint, (3) container starts and immediately egresses to suspicious destinations.', '{Containers}', 'x-mitre-analytic--3a6fdd1a-59c6-4f46-a761-0de502229da0', 'DET0478', '[{"name": "docker:events", "channel": "created,started: new container from untrusted registry or unexpected entrypoint", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"name": "docker:events", "channel": "start", "x_mitre_data_component_ref": "x-mitre-data-component--5fe82895-28e5-4aac-845e-dc886b63be2e"}, {"name": "NSM:Flow", "channel": "container egress to unknown IPs/domains", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TrustedRegistries", "description": "Approved registries/namespaces."}, {"field": "AllowedEntrypoints", "description": "Expected CMD/ENTRYPOINT for known images."}, {"field": "TimeWindow", "description": "Correlate user action → docker/podman run within 10 minutes."}]', '2026-05-01 15:26:34.981459');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (421, 'AN0170', 'Analytic 0170', 'Detects modification of registry keys used for default file handlers, followed by anomalous process execution from user-initiated file opens. This includes tracking changes under HKCU and HKCR for file extension mappings, and correlating them with new or suspicious handler paths launching unusual child processes (e.g., PowerShell, cmd, wscript).', '{Windows}', 'x-mitre-analytic--3ac58f14-32d6-4ce2-8aa7-e7c429dd6405', 'DET0061', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "TimeWindow", "description": "Defines how long after the registry modification to correlate a suspicious process execution"}, {"field": "UserContext", "description": "Tune to ignore known admin or installer behavior in specific user profiles"}, {"field": "SuspiciousHandlerPathRegex", "description": "Pattern match for suspicious handler paths (e.g., powershell.exe, rundll32.exe)"}]', '2026-05-01 15:26:34.982681');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (422, 'AN0620', 'Analytic 0620', 'Processes accessing ALSA/PulseAudio devices or executing audio capture binaries like ''arecord'', followed by file creation or suspicious child process spawning.', '{Linux}', 'x-mitre-analytic--3ac9b4c2-9137-4d20-9619-01029d656874', 'DET0221', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ExecutableName", "description": "Capture binaries like arecord, parecord, or ffmpeg."}, {"field": "DevicePath", "description": "Log attempts to access /dev/snd/*, /dev/dsp, /proc/asound/*."}, {"field": "UserContext", "description": "Whether the user has audio access rights or is running under elevated privileges."}]', '2026-05-01 15:26:34.983887');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (423, 'AN0938', 'Analytic 0938', 'Correlation of package install event with execution of postinstall scripts containing unknown binaries or abnormal CLI usage. Look for `/usr/sbin/installer` execution followed by child processes originating from postinstall script.', '{macOS}', 'x-mitre-analytic--3ae8f3c1-c3a1-4c45-9231-1bb6f9c61ee1', 'DET0330', '[{"name": "macos:unifiedlog", "channel": "Execution of /usr/sbin/installer spawning child process from within /private/tmp or package contents", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Creation or modification of postinstall scripts within .pkg or .mpkg contents", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ScriptLocation", "description": "Path to postinstall script varies depending on .pkg packaging and user temp directories."}, {"field": "ParentProcessName", "description": "Installers may vary (e.g., /usr/sbin/installer, Jamf, Munki)."}]', '2026-05-01 15:26:34.986318');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (424, 'AN0059', 'Analytic 0059', 'Detects modification of shell startup/logout scripts such as ~/.bashrc, ~/.bash_profile, or /etc/profile, followed by anomalous process execution or network connections upon interactive or remote shell login.', '{Linux}', 'x-mitre-analytic--3ae99176-ce61-4598-834b-f48d13802dcb', 'DET0020', '[{"name": "auditd:SYSCALL", "channel": "AUDIT_SYSCALL (open, write, rename, unlink)", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:EXECVE", "channel": "execution of unexpected binaries during user shell startup", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "unexpected network activity initiated shortly after shell session starts", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Defines how soon after shell startup process execution or network activity is considered suspicious."}, {"field": "TargetUser", "description": "Limits detection to specific user accounts or roles such as root or service accounts."}, {"field": "FilePathRegex", "description": "Defines what shell configuration paths are considered relevant (e.g., .bashrc, .bash_logout, etc.)"}]', '2026-05-01 15:26:34.987562');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (425, 'AN0132', 'Analytic 0132', 'Monitors programmatic access to user mailboxes in cloud-based email systems (e.g., O365, Exchange Online) using APIs or tokens. Focuses on OAuth misuse, suspicious MailItemsAccessed patterns, scripted keyword searches, and connections from untrusted agents or locations.', '{"Office Suite"}', 'x-mitre-analytic--3af413c2-5b26-4f43-b198-11b4dce97a0a', 'DET0048', '[{"name": "m365:purview", "channel": "MailItemsAccessed, Search-Mailbox events", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "azure:signinlogs", "channel": "Suspicious login to cloud mailbox system", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "m365:unified", "channel": "Search-Mailbox, Get-MessageTrace, eDiscovery requests", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "MailAccessVolumeThreshold", "description": "Number of emails accessed within time window to flag anomaly."}, {"field": "OAuthClientIDAllowList", "description": "Allows tuning based on known app registrations."}, {"field": "KeywordSearchFrequency", "description": "Flag high volumes of message searches using suspicious patterns."}, {"field": "LoginGeolocationVariance", "description": "Trigger when IP geolocation varies significantly from user''s historical profile."}]', '2026-05-01 15:26:34.988854');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (426, 'AN1429', 'Analytic 1429', 'Detects use of shell interpreters (e.g., bash, sh, python, perl) initiated by users or processes not normally executing them, especially when chaining suspicious utilities like netcat, curl, or ssh.', '{Linux}', 'x-mitre-analytic--3b02d81a-8684-4fc8-8364-127f30359282', 'DET0516', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "InterpreterName", "description": "Regex to identify which interpreters (bash, python, ruby) to monitor based on typical usage."}, {"field": "UserContext", "description": "Scope to users or service accounts not expected to run interpreters interactively."}, {"field": "ExecutionChainLength", "description": "Defines maximum process tree depth to correlate interpreter execution with its effects."}]', '2026-05-01 15:26:34.990603');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (427, 'AN0604', 'Analytic 0604', 'Userland or kernel-level ransomware encrypting user files (Documents, Desktop) using `srm`, `gpg`, or compiled payloads. Often correlated with ransom note creation in multiple directories.', '{macOS}', 'x-mitre-analytic--3b18d20b-94c7-41e7-8f82-99148945a74f', 'DET0215', '[{"name": "macos:unifiedlog", "channel": "file encrypted|new file with .encrypted extension|disk write burst", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "exec srm|exec openssl|exec gpg", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExtensionPattern", "description": "Encrypted files may use .locked, .enc, or ransom-specific extensions."}, {"field": "VolumeTargeted", "description": "Detect activity targeting mounted external or backup volumes."}]', '2026-05-01 15:26:34.992192');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (799, 'AN1218', 'Analytic 1218', 'Detects movement of binaries to `~/Library/`, `/System/`, or app bundle locations, especially after initial execution or download from Safari or Mail.', '{macOS}', 'x-mitre-analytic--72540cd1-3ba6-4a4a-8866-a3113094196a', 'DET0439', '[{"name": "macos:unifiedlog", "channel": "log stream", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "TargetBundlePathPattern", "description": "Monitor relocation to .app/Contents/MacOS/ or ~/Library/Launch*"}, {"field": "QuarantineFlagCheck", "description": "Check for disappearance of com.apple.quarantine attribute post-move"}]', '2026-05-01 15:26:35.547254');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (428, 'AN0313', 'Analytic 0313', 'Monitoring for modification and execution of login hook scripts or LaunchAgents/LaunchDaemons used for persistence.', '{macOS}', 'x-mitre-analytic--3b218f49-59ce-44a5-a10b-889c99e78934', 'DET0112', '[{"name": "macos:unifiedlog", "channel": "log", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "fs:fsusage", "channel": "file", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "launchd", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "Label", "description": "LaunchAgent or LaunchDaemon label name, often environment-specific."}, {"field": "ProgramArguments", "description": "Arguments passed to scripts, which may need tuning by environment."}, {"field": "UserContext", "description": "Distinguish between user login and system startup agents."}]', '2026-05-01 15:26:34.993572');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (429, 'AN1937', 'Analytic 1937', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders. 
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (430, 'AN1442', 'Analytic 1442', 'Detects AppleScript or Objective-C usage to generate fake authentication windows (e.g., using display dialog or NSAlert) from user-launched or persistence-related processes.', '{macOS}', 'x-mitre-analytic--3b327a8f-0ea3-4848-b34a-58029e5edf57', 'DET0521', '[{"name": "macos:unifiedlog", "channel": "subsystem=com.apple.Security or com.apple.applescript", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ScriptContent", "description": "AppleScript snippets like ''display dialog'' or ''with hidden answer''"}, {"field": "ProcessPath", "description": "Tune out Apple-signed and expected automation tasks"}]', '2026-05-01 15:26:34.996889');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (431, 'AN1364', 'Analytic 1364', 'Monitor SaaS financial systems (e.g., QuickBooks, Workday, SAP S/4HANA cloud) for unauthorized access, rule changes, or mass export of financial data. Detect anomalous transfers initiated via SaaS APIs or new MFA-disabled logins targeting finance apps.', '{SaaS}', 'x-mitre-analytic--3bac57c4-1539-4048-b325-88032c78ed08', 'DET0495', '[{"name": "saas:finance", "channel": "Transaction/Transfer: Unusual or large transactions initiated outside business hours or by unusual accounts", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TransactionThreshold", "description": "Customizable monetary threshold above which financial transactions should be flagged."}]', '2026-05-01 15:26:34.99832');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (432, 'AN0216', 'Analytic 0216', 'Detection of anomalous RDP or remote service session activity where a logon session is hijacked rather than newly created. Indicators include mismatched user credentials vs. active session tokens, service session takeovers without corresponding successful logon events, or RDP shadowing activity without user consent.', '{Windows}', 'x-mitre-analytic--3c320df0-2a99-4bc4-b0f4-7af1675ccdb9', 'DET0079', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ExpectedUserSessionMap", "description": "Mapping of users to hosts they are expected to access; deviations indicate possible hijacking."}, {"field": "TimeWindow", "description": "Threshold for detecting rapid pivoting via hijacked sessions."}]', '2026-05-01 15:26:34.999755');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (433, 'AN2060', 'Analytic 2060', 'Much of this takes place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (434, 'AN0067', 'Analytic 0067', 'Correlates ELF file execution with high-entropy writable memory segments and self-modifying code patterns.', '{Linux}', 'x-mitre-analytic--3cb4d3f4-df71-474c-a9f0-438dbf26bf66', 'DET0023', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "mprotect", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "EntropyThreshold", "description": "Useful for tuning unpacked sections containing high entropy indicative of compression or encryption."}, {"field": "TimeWindow", "description": "Can be tuned to correlate file writes to execution within a set timeframe."}]', '2026-05-01 15:26:35.002358');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (435, 'AN0418', 'Analytic 0418', 'Forged SAML tokens can be observed as authentication attempts with valid signatures but missing expected preceding Kerberos or authentication events. Defenders may correlate SAML assertions with absent Event IDs 4769, 1200, or 1202, or tokens issued with abnormal lifetimes, issuers, or claims compared to baseline.', '{"Identity Provider"}', 'x-mitre-analytic--3cb835e5-ded1-42c4-a5cc-38911078b0a5', 'DET0148', '[{"name": "azure:signinlogs", "channel": "SAML-based login with anomalous issuer or NotOnOrAfter lifetime", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Security", "channel": "EventCode=4769, 1200, 1202", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TokenLifetimeThreshold", "description": "Defines the maximum expected lifetime of a SAML token (e.g., >1 hour considered anomalous)."}, {"field": "TrustedIssuerList", "description": "List of approved SAML issuers and certificate thumbprints."}]', '2026-05-01 15:26:35.003886');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (436, 'AN1103', 'Analytic 1103', 'Adversary uses cloud-native APIs or CLI (e.g., AWS Systems Manager, Azure Resource Graph) to list installed software on cloud workloads.', '{IaaS}', 'x-mitre-analytic--3ccd6662-c579-494f-bbfa-ffc3530e3db2', 'DET0392', '[{"name": "AWS:CloudTrail", "channel": "ssm:ListInventoryEntries", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"name": "AWS:CloudTrail", "channel": "ssm:GetCommandInvocation", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "UserAgent", "description": "Differentiate access from automated scripts vs. authorized console."}, {"field": "InventoryType", "description": "May focus on Application or Platform inventory only."}]', '2026-05-01 15:26:35.005238');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (437, 'AN1381', 'Analytic 1381', 'Detects compilation activity using csc.exe, ilasm.exe, or msbuild.exe initiated by user-space processes outside typical development environments, followed by execution or network activity from newly written binaries.', '{Windows}', 'x-mitre-analytic--3cd889a5-7955-4d38-a49b-89e8d276ceab', 'DET0501', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ParentProcessName", "description": "Filter for unexpected users (non-dev) launching compilers like csc.exe or msbuild.exe"}, {"field": "OutputDirectoryPath", "description": "Adjust paths for sensitive file write zones (e.g., `C:\\Users\\Public\\`, `%TEMP%`, or Desktop)"}, {"field": "TimeWindow", "description": "Tune the correlation window between compilation and subsequent execution or C2"}]', '2026-05-01 15:26:35.006974');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (438, 'AN0824', 'Analytic 0824', 'Detects unauthorized edits to /etc/hosts, /etc/resolv.conf, or suspicious ARP broadcasts. Correlates file modifications with subsequent unexpected network sessions or service creation.', '{Linux}', 'x-mitre-analytic--3cdef7d3-4ca6-4d4a-933b-656af73f8433', 'DET0296', '[{"name": "auditd:SYSCALL", "channel": "open, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Flow", "channel": "Unexpected ARP replies or DNS responses inconsistent with authoritative servers", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MonitoredFiles", "description": "List of system files shaping traffic flow (hosts, resolv.conf, PAM modules)."}, {"field": "ARPThreshold", "description": "Rate/volume thresholds for ARP/DNS anomalies tuned per subnet."}]', '2026-05-01 15:26:35.008662');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (439, 'AN1952', 'Analytic 1952', 'Internet scanners may be used to look for patterns associated with malicious content designed to collect client configuration information from visitors.(Citation: ThreatConnect Infrastructure Dec 2020)(Citation: ATT ScanBox)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (440, 'AN1088', 'Analytic 1088', 'Use of AWS CLI (`aws iam list-users`, `list-roles`), Azure CLI (`az ad user list`), or GCP CLI (`gcloud iam service-accounts list`) from endpoints or cloud shells where such activity is unexpected.', '{IaaS}', 'x-mitre-analytic--3d124174-1e58-44e2-9f5b-f63394fb7a2e', 'DET0386', '[{"name": "AWS:CloudTrail", "channel": "AWS IAM: ListUsers, ListRoles", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "azure:activity", "channel": "Azure CLI Operation: Microsoft.Graph/users/read", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "CallerType", "description": "Suppress known admin accounts and alert on developer/test/service identities."}, {"field": "CLIUserAgent", "description": "Correlate unexpected CLI user-agents and geolocation anomalies."}, {"field": "CloudRegion", "description": "Suppress noise from known IP ranges or whitelisted accounts per region."}]', '2026-05-01 15:26:35.011429');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (441, 'AN0429', 'Analytic 0429', 'Detection of suspicious write operations to block devices, modifications of bootloader files (GRUB, initrd, vmlinuz), and unexpected changes within the EFI System Partition. Monitors privileged execution of utilities like dd, grub-install, or efibootmgr that modify boot sectors or loader entries.', '{Linux}', 'x-mitre-analytic--3d209345-1676-4170-b1d0-d6538bce06c4', 'DET0150', '[{"name": "auditd:SYSCALL", "channel": "open, write: Write operations targeting /dev/sda, /dev/nvme0n1, or EFI partition mounts", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:syslog", "channel": "Block device write errors or unusual bootloader activity", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}]', '[{"field": "BootloaderHashBaseline", "description": "Baseline checksums of GRUB, kernel, and initramfs images"}, {"field": "EFIFileAllowlist", "description": "Trusted EFI executables for Linux environments"}, {"field": "AlertThresholds", "description": "Tunable thresholds for triggering alerts on repeated EFI/bootloader writes"}]', '2026-05-01 15:26:35.012719');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (442, 'AN0362', 'Analytic 0362', 'Modification of plist files to set apple.awt.UIElement or similar flags hiding app icons and windows, and dscl/command-line activity that suppresses visibility. Defender view: correlation of plist modifications with unexpected hidden user applications.', '{macOS}', 'x-mitre-analytic--3d9fb03c-fcc9-4f19-9c49-09d8321f28b9', 'DET0128', '[{"name": "macos:unifiedlog", "channel": "Modification of plist with apple.awt.UIElement set to TRUE", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Execution of Java apps or other processes with hidden window attributes", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PlistScope", "description": "Restrict detection to application plists where UIElement flag is unexpected."}, {"field": "UserContext", "description": "Correlate plist modifications with the creating/modifying user to tune results."}]', '2026-05-01 15:26:35.015674');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (449, 'AN1065', 'Analytic 1065', 'Detects use of gzip, base64, tar, or openssl in scripts or commands that encode/encrypt files after file staging or system enumeration.', '{Linux}', 'x-mitre-analytic--3e7ff1f9-57e2-44f4-8dc1-20d1a1652f73', 'DET0378', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:cli", "channel": "Shell history logs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandRegex", "description": "Customize for tools seen in environment (e.g., gzip, bzip2, xz)"}, {"field": "SensitivePathList", "description": "Specify file paths likely targeted for obfuscation (e.g., /etc/, /home/)"}]', '2026-05-01 15:26:35.02567');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (443, 'AN0399', 'Analytic 0399', 'Detects unauthorized or anomalous use of command-line interfaces (CLI) on network devices. Focuses on remote access sessions (e.g., SSH/Telnet), privilege escalation within CLI sessions, execution of high-risk commands (e.g., config replace, terminal monitor, no logging), and configuration changes outside of approved windows.', '{"Network Devices"}', 'x-mitre-analytic--3dc28690-699a-4f6d-ad4b-278aa2dd8c59', 'DET0142', '[{"name": "networkdevice:syslog", "channel": "command_exec", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "remote CLI session detection", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "networkdevice:syslog", "channel": "authorization/accounting logs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Config changes made outside of maintenance windows are more suspicious."}, {"field": "UserContext", "description": "Unexpected CLI activity by service accounts or users not assigned to manage network devices."}, {"field": "CommandPattern", "description": "Regex or keyword match on dangerous or unusual commands (e.g., ''no logging'', ''reload'', ''copy tftp'', ''config replace'')."}, {"field": "SourceIP", "description": "Remote CLI sessions originating from untrusted networks or jump hosts."}, {"field": "SessionDuration", "description": "Abnormally short or long SSH/Telnet CLI sessions compared to baseline."}]', '2026-05-01 15:26:35.017409');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (444, 'AN1157', 'Analytic 1157', 'Unauthorized API or console calls to retrieve or reset password credentials, download key material, or modify SSO settings.', '{"Identity Provider"}', 'x-mitre-analytic--3e30007c-fc51-447f-850a-c8378427be3d', 'DET0412', '[{"name": "azure:signinlogs", "channel": "Reset password or download key from portal", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "AWS:CloudTrail", "channel": "GetSecretValue", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}]', '[{"field": "SSOSettingScope", "description": "Subset of IdP settings monitored for unauthorized changes"}, {"field": "SecretType", "description": "Which secrets (passwords, keys, tokens) are monitored"}]', '2026-05-01 15:26:35.018752');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (445, 'AN0228', 'Analytic 0228', 'Use of system binaries such as `osascript`, `bash`, or `curl` to download or execute unsigned code or files in conjunction with application proxying.', '{macOS}', 'x-mitre-analytic--3e461dab-922c-48cc-aafc-51f20025bf27', 'DET0081', '[{"name": "macos:unifiedlog", "channel": "exec of osascript, bash, curl with suspicious parameters", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "execution of trusted tools interacting with external endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TrustedUtilityList", "description": "macOS binary whitelist including `/usr/bin/osascript`, `/bin/bash`, `/usr/bin/curl`"}, {"field": "SignedToUnsignedTransition", "description": "Used to detect proxy execution from signed binary to unsigned payload"}]', '2026-05-01 15:26:35.020028');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (446, 'AN1500', 'Analytic 1500', 'Encrypted sessions detected with asymmetric key exchange anomalies on non-standard ports or with invalid/malformed certs. Defender correlates NetFlow/IPFIX with IDS/IPS detecting RSA exchanges outside expected TLS flows.', '{"Network Devices"}', 'x-mitre-analytic--3e5930bf-6d79-4f75-9b9e-97cad9bf9232', 'DET0543', '[{"name": "NSM:Flow", "channel": "Flow records with RSA key exchange on unexpected port", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "IDS:TLSInspection", "channel": "Malformed certs, incomplete asymmetric handshakes, or invalid CAs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "PortProfiles", "description": "Define expected ports for asymmetric cryptography (e.g., 443, 993)."}, {"field": "CertValidationPolicy", "description": "Thresholds for rejecting untrusted/self-signed certs."}]', '2026-05-01 15:26:35.021297');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (447, 'AN1186', 'Analytic 1186', 'Registry key modifications under IFEO paths (e.g., Debugger value set under Image File Execution Options), especially for security-related or accessibility binaries, followed by anomalous process execution with debugger flags or SYSTEM-level access at login. Detectable by correlating registry modifications, process creation, and parent-child anomalies with unusual command-line usage or access tokens.', '{Windows}', 'x-mitre-analytic--3e5b15b0-e6b2-402a-9c4f-e483c968a38e', 'DET0422', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}]', '[{"field": "TimeWindow", "description": "Time delta for correlating registry modification and debugger-triggered execution"}, {"field": "TargetBinary", "description": "Specific executables that trigger defenders’ alerts when IFEO values are set"}, {"field": "ParentProcessAnomaly", "description": "Tunable logic for detecting parent-child anomalies (e.g., non-standard parent processes)"}, {"field": "TokenElevationContext", "description": "May require tuning based on normal SYSTEM or admin process elevation patterns"}]', '2026-05-01 15:26:35.022624');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (448, 'AN1378', 'Analytic 1378', 'Outbound fallback traffic from low-profile or background launch agents using unusual protocols or destinations after primary channel inactivity.', '{macOS}', 'x-mitre-analytic--3e682b33-5064-4202-aad7-ca1900fde1a5', 'DET0499', '[{"name": "macos:unifiedlog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "LaunchAgentContext", "description": "Used to suppress known legitimate agents."}, {"field": "PayloadEntropy", "description": "Can help isolate covert or encrypted fallback traffic."}]', '2026-05-01 15:26:35.024174');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (816, 'AN0281', 'Analytic 0281', 'Detects embedded Lua interpreter execution or script injection on devices supporting Lua scripting (e.g., routers, firewalls), often seen in modified firmware or abused APIs.', '{"Network Devices"}', 'x-mitre-analytic--755fb4b5-903f-4694-b591-04078afa27aa', 'DET0101', '[{"name": "networkdevice:runtime", "channel": "runtime", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "FirmwareBuildHash", "description": "Used to baseline known good versions versus injected scripts."}, {"field": "ScriptInjectionPath", "description": "Path to where scripts are allowed or denied based on config."}]', '2026-05-01 15:26:35.570484');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (450, 'AN0030', 'Analytic 0030', 'Processes generating large outbound connections with disproportionate send/receive ratios, often to uncommon ports or hosts, potentially inserting meaningless data into protocol payloads.', '{Windows}', 'x-mitre-analytic--3e852bb9-785d-4bc4-9f7e-b7e43a5d8bc8', 'DET0011', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "NSM:Flow", "channel": "TCP/UDP", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "PayloadEntropyThreshold", "description": "Tunable threshold for Shannon entropy of network payloads."}, {"field": "TimeWindow", "description": "Duration of outbound data transfer to evaluate disproportionate upload size."}, {"field": "UserContext", "description": "Filter based on user accounts allowed to generate outbound traffic."}]', '2026-05-01 15:26:35.027089');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (451, 'AN0678', 'Analytic 0678', 'Execution of Java-based or CLI database tools (e.g., DBeaver, Beekeeper, mysql, psql) from user profiles not tied to dev/admin roles, especially when followed by file writes and cloud sync activity. Defender correlates GUI tool launches, file write events in ~/Downloads or ~/Documents, and outbound API calls to known cloud services.', '{macOS}', 'x-mitre-analytic--3e87713d-d062-413c-9643-97df331ba651', 'DET0242', '[{"name": "macos:unifiedlog", "channel": "Process start of Java or native DB client tools", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Writes of .sql/.csv/.xlsx files to user documents/downloads", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "HTTPS API requests to Dropbox, iCloud, Google Drive, OneDrive shortly after DB tool usage", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CloudSyncDomainList", "description": "FQDNs of sync services used to detect likely outbound DB leakages"}, {"field": "UserPrivilegeLevel", "description": "Whether to treat low-privilege users accessing DB tools as higher risk"}]', '2026-05-01 15:26:35.028589');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (452, 'AN0171', 'Analytic 0171', 'Disabling or modifying the Linux Audit system through process termination (auditd killed), service management (systemctl stop auditd), or tampering with rule/configuration files (/etc/audit/audit.rules, audit.conf). Defender view: suspicious execution of auditctl/systemctl commands, file modifications to audit rules, or sudden absence of audit logs correlated with privileged execution.', '{Linux}', 'x-mitre-analytic--3e9734aa-b9b4-4716-927c-27c2c2aa972e', 'DET0062', '[{"name": "auditd:EXECVE", "channel": "Execution of auditctl, systemctl stop auditd, or kill -9 auditd", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "kill syscalls targeting auditd process", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "auditd:FILE", "channel": "Modification or deletion of /etc/audit/audit.rules or /etc/audit/audit.conf", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:syslog", "channel": "auditd service stopped or disabled", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "ServiceWhitelist", "description": "Exclude legitimate administrative service stops during system maintenance."}, {"field": "FilePathScope", "description": "Specify monitored paths (/etc/audit/audit.rules, audit.conf) to avoid false positives from unrelated file writes."}, {"field": "TimeWindow", "description": "Correlate suspicious commands, file modifications, and audit log gaps in short succession."}]', '2026-05-01 15:26:35.030558');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (453, 'AN0807', 'Analytic 0807', 'Detects direct modification of crontab entries in /var/spool/cron/crontabs/root or /etc/rc.local.d/local.sh followed by execution of scripts linked to lateral movement or malware persistence.', '{ESXi}', 'x-mitre-analytic--3ea6b02e-47e0-4815-9190-4e95eb51e779', 'DET0290', '[{"name": "esxi:hostd", "channel": "modification of crontab or local.sh entries", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "esxi:cron", "channel": "execution of scheduled job", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "esxi:vmkernel", "channel": "spawned shell or execution environment activity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CrontabFileMonitored", "description": "Admins may customize paths in hardened deployments."}, {"field": "ShellCommandPayload", "description": "Flag shell-based persistence indicators in local.sh or cron payloads."}, {"field": "JobInterval", "description": "Time interval of task repetition for outlier identification."}]', '2026-05-01 15:26:35.031974');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (454, 'AN0003', 'Analytic 0003', 'Detects CLI tools (e.g., mosquitto_pub, nc, python scripts) interacting with pub/sub brokers using unusual topic names, high-frequency publication rates, or obfuscated payloads to non-standard hosts.', '{Linux}', 'x-mitre-analytic--3ecc4ba2-bf4f-481c-b813-69c169c28c83', 'DET0002', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "mqtt.log or AMQP custom log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "BrokerAllowList", "description": "Known-good brokers used by approved apps and daemons"}, {"field": "TopicAnomalyScore", "description": "Payload length, entropy, or topic name patterns"}]', '2026-05-01 15:26:35.033356');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (455, 'AN1992', 'Analytic 1992', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (456, 'AN0542', 'Analytic 0542', 'Detection of XProtect or AV quarantining a known tool, followed by modification (file size, hash, string) and subsequent re-execution by the same or related user.', '{macOS}', 'x-mitre-analytic--3ef92295-ecbf-417a-b72a-f6cd189ca3a1', 'DET0189', '[{"name": "macos:unifiedlog", "channel": "quarantine or AV-related subsystem", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "BinaryChangeThreshold", "description": "File hash delta or binary string diff score to tolerate renamed/mutated variants."}, {"field": "UserContext", "description": "User or group expected to use dev tools; reduce false positives from legitimate repacking."}]', '2026-05-01 15:26:35.035844');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (457, 'AN0733', 'Analytic 0733', 'Detects JavaScript execution through WSH (wscript.exe, cscript.exe) or HTA (mshta.exe), particularly when spawned from Office macros, web browsers, or abnormal user paths. Correlates script execution with outbound network activity or system modification.', '{Windows}', 'x-mitre-analytic--3f257014-01d4-487d-980c-77d4d2130315', 'DET0264', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "m365:defender", "channel": "ScriptBlockLogging + AMSI", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ParentProcess", "description": "Execution of wscript.exe, cscript.exe, or mshta.exe from suspicious parent like Excel or Outlook."}, {"field": "ScriptPath", "description": "Script loaded from %TEMP%, user download folder, or via UNC/web path."}, {"field": "TimeWindow", "description": "Execution of JavaScript during non-business or patch windows."}, {"field": "UserContext", "description": "Execution by accounts not typically authorized for scripting (e.g., non-admin users)."}, {"field": "EntropyScore", "description": "Obfuscated JS with high entropy detected by AMSI or ScriptBlock logging."}]', '2026-05-01 15:26:35.037046');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (458, 'AN1300', 'Analytic 1300', 'Detects modification of shared network folders via .app bundles or scripting files with hidden extensions (e.g., double extensions like docx.app).', '{macOS}', 'x-mitre-analytic--3f36a861-3be2-4f6d-bfad-f044cdc01b15', 'DET0471', '[{"name": "fs:fsevents", "channel": "Directory events (kFSEventStreamEventFlagItemCreated)", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "file writes", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "FileExtensionDeception", "description": "Monitors use of hidden extensions or double extensions."}, {"field": "TargetSharedFolder", "description": "Defines sensitive shared folders (e.g., /Users/Shared/HR)."}]', '2026-05-01 15:26:35.038554');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (459, 'AN0494', 'Analytic 0494', 'Detects exploitation of authentication daemons or PAM modules. Defender perspective includes failed or anomalous PAM authentications, abnormal segfaults in authentication services, and exploitation attempts followed by successful unauthorized logins. Correlation identifies memory corruption, replay attempts, and privilege escalation tied to credential services.', '{Linux}', 'x-mitre-analytic--3f3ae0da-3005-42d7-afa3-8eaa8da3f700', 'DET0174', '[{"name": "auditd:SYSCALL", "channel": "execve: Suspicious binaries or scripts interacting with authentication binaries (sshd, gdm, login)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "Repeated failed authentication attempts or replay patterns", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AuthServiceList", "description": "List of monitored authentication services (e.g., sshd, gdm, PAM modules)."}, {"field": "FailureThreshold", "description": "Number of failed authentications within a window before escalating to replay suspicion."}]', '2026-05-01 15:26:35.040231');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (460, 'AN1359', 'Analytic 1359', 'Detects anomalous use of Mach ports, Apple Events, or XPC services for inter-process execution or code injection. Focuses on unexpected processes attempting to send privileged Apple Events (e.g., automation scripts injecting into security-sensitive apps).', '{macOS}', 'x-mitre-analytic--3f42390d-2a44-4094-9cea-429f1286f8aa', 'DET0493', '[{"name": "macos:unifiedlog", "channel": "Unusual Mach port registration or access attempts between unrelated processes", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "macos:osquery", "channel": "exec: Unexpected execution of osascript or AppleScript targeting sensitive apps", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "AllowedAppleEventTargets", "description": "Whitelisted app-to-app Apple Event communications (e.g., Finder automation)."}, {"field": "MachPortBaseline", "description": "Baseline of Mach ports and XPC services normally used in the environment."}]', '2026-05-01 15:26:35.042836');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (461, 'AN1213', 'Analytic 1213', 'Detects suspicious custom compression/encryption routines through anomalous script or binary execution that produces high-entropy files without standard archiving utilities. Correlates script execution, memory API usage (bitwise ops, CryptoAPI calls), and creation of archive-like files with uncommon headers.', '{Windows}', 'x-mitre-analytic--3f47f3e9-2856-4830-9762-7ca0c3924f6d', 'DET0438', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "EntropyThreshold", "description": "Minimum entropy level that flags suspicious custom archives."}, {"field": "AllowedProcesses", "description": "Known business processes performing encryption or compression."}, {"field": "TimeWindow", "description": "Correlation timeframe between script execution and file creation."}]', '2026-05-01 15:26:35.04443');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (462, 'AN0395', 'Analytic 0395', 'Detects manual or scripted removal of logs, artifacts, or malware droppings via `rm` or PowerCLI in ESXi shell. Focus on deletions from /tmp/, /var/core/, or /scratch.', '{ESXi}', 'x-mitre-analytic--3f53ca22-5efe-43b3-8225-5fdd4b8a8194', 'DET0140', '[{"name": "esxi:shell", "channel": "/var/log/shell.log", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "LogFilePath", "description": "Match deletion actions in system-critical locations or malware drop zones."}, {"field": "TimeWindow", "description": "Typically follows suspicious admin login or unexpected shell session."}]', '2026-05-01 15:26:35.045951');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (471, 'AN0124', 'Analytic 0124', 'Installation of malicious .mobileconfig profiles or browser extension plist entries followed by abnormal browser child process activity.', '{macOS}', 'x-mitre-analytic--41153f33-d415-4e1d-b3c8-7333b2f1915e', 'DET0044', '[{"name": "macos:unifiedlog", "channel": "profiles install -type=configuration", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "Creation or modification of browser extension .plist files", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "Unexpected child process of Safari or Chrome", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PlistPath", "description": "Different versions may store extensions in variant preference folders"}, {"field": "CommandLineFlags", "description": "May vary with OS version; some install flags deprecated in macOS 11+"}]', '2026-05-01 15:26:35.057246');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (463, 'AN0180', 'Analytic 0180', 'Behavioral chain: (1) Safari/Chrome/Firefox/Office handles a URL; unified logs show open/click or LSQuarantine assignment, (2) outbound connection to untrusted domain, (3) a new file appears in ~/Downloads or /private/var/folders/* with quarantine flag.', '{macOS}', 'x-mitre-analytic--3f615721-c62f-4229-9c6e-cb873b2591e5', 'DET0066', '[{"name": "macos:unifiedlog", "channel": "open URL|clicked link|LSQuarantineAttach", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Connections", "channel": "New outbound connection from Safari/Chrome/Firefox/Word", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "fs:fsevents", "channel": "Create in /Users/*/Downloads or /private/var/folders/* with quarantine attribute", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "TimeWindow", "description": "10–30m correlation."}, {"field": "QuarantinePolicy", "description": "Alert when com.apple.quarantine missing on newly downloaded executables."}, {"field": "SuspiciousTLDs", "description": "Org-specific risky domains/TLDs."}]', '2026-05-01 15:26:35.047172');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (464, 'AN1151', 'Analytic 1151', 'Inspect network telemetry for adversary attempts to blend malicious traffic with legitimate flows using VPNs, proxies, or geolocation spoofing. Defensive teams may observe anomalous tunnels, encrypted sessions to suspicious domains, or geo-mismatched IP activity.', '{"Network Devices"}', 'x-mitre-analytic--3f74d068-0a8b-4312-91f3-34da6c630c4a', 'DET0411', '[{"name": "NSM:Flow", "channel": "Encrypted tunnels or proxy traffic to non-standard destinations", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "GeoIPRanges", "description": "Regions to monitor for unexpected or mismatched geolocation activity."}]', '2026-05-01 15:26:35.048481');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (465, 'AN1404', 'Analytic 1404', 'Detects unauthorized access to browser cookie paths (e.g., `~/Library/Application Support/Google/Chrome/Default/Cookies`) or `task_for_pid`/`vm_read` calls to Safari/Chrome memory space.', '{macOS}', 'x-mitre-analytic--3fdd7ef4-b382-4880-9f72-bf0ad696af85', 'DET0509', '[{"name": "macos:unifiedlog", "channel": "vm_read, task_for_pid, or file open to cookie databases", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "fs:fsusage", "channel": "file open for known browser cookie paths", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "TargetBrowserList", "description": "List of processes considered web browsers on macOS"}, {"field": "BrowserCookiePathList", "description": "Cookie database paths specific to each browser"}]', '2026-05-01 15:26:35.049682');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (466, 'AN1457', 'Analytic 1457', 'Execution of `show version`, `show hardware`, or `show system` commands through CLI via SSH or console.', '{"Network Devices"}', 'x-mitre-analytic--3ff23082-b5c6-47c0-8d76-a2d6fa88e622', 'DET0525', '[{"name": "networkdevice:syslog", "channel": "Privilege-level command execution", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "Username", "description": "Highlight unexpected users issuing diagnostic commands."}, {"field": "CommandList", "description": "Tailor to vendor-specific command syntax."}]', '2026-05-01 15:26:35.050811');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (467, 'AN1121', 'Analytic 1121', 'Detects high-frequency or anomalous DNS queries initiated by non-browser, non-system processes (e.g., PowerShell, rundll32, python.exe) used to establish command and control via DNS tunneling.', '{Windows}', 'x-mitre-analytic--407bb9c9-0c31-4172-8dd3-bdd0547f2d1e', 'DET0400', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "dns.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "QueryLengthThreshold", "description": "Subdomain length for detecting base32/base64-encoded payloads"}, {"field": "ProcessImageFilter", "description": "Flag non-standard executables making DNS queries"}, {"field": "TimeWindow", "description": "Rate of queries in short interval per process"}]', '2026-05-01 15:26:35.051939');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (468, 'AN0757', 'Analytic 0757', 'Detects anomalous process access to LSASS on domain controllers, suspicious module loads of authentication DLLs, and registry or file modifications indicative of Skeleton Key–style patching. Correlates LSASS access attempts with subsequent abnormal logon activity patterns.', '{Windows}', 'x-mitre-analytic--40882c73-344f-4138-894e-049b9bb1f460', 'DET0271', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:System", "channel": "Unexpected modification to lsass.exe or cryptdll.dll", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "MonitoredDLLs", "description": "Specific authentication DLLs such as cryptdll.dll and samsrv.dll monitored for tampering."}, {"field": "TimeWindow", "description": "Correlation window between LSASS memory access, module load, and suspicious logons."}, {"field": "UserContext", "description": "Baseline expected accounts performing domain controller logon operations."}]', '2026-05-01 15:26:35.05313');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (469, 'AN0972', 'Analytic 0972', 'VM or cloud instance generating anomalously high network egress targeting same destination IP or service, especially using stateless protocols.', '{IaaS}', 'x-mitre-analytic--408b2724-079c-4636-9764-52f435726de7', 'DET0343', '[{"name": "AWS:VPCFlowLogs", "channel": "source instance sends large volume of traffic in short window", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "AWS:CloudWatch", "channel": "NetworkOut spike beyond baseline", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "InstanceTrafficThreshold", "description": "Alert when egress exceeds normal usage by X%."}, {"field": "ProtocolType", "description": "Prioritize alerts on stateless protocols such as UDP and ICMP."}]', '2026-05-01 15:26:35.054307');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (470, 'AN2012', 'Analytic 2012', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (472, 'AN0128', 'Analytic 0128', 'Execution of commands to enumerate virtualization-related files or processes (e.g., ''/sys/class/dmi/id/product_name'', dmesg, lscpu, lspci), or querying hypervisor interfaces prior to malware execution.', '{Linux}', 'x-mitre-analytic--412b76ec-d44e-4064-9dc1-32cf793f0176', 'DET0046', '[{"name": "auditd:SYSCALL", "channel": "execve or syscall invoking vm artifact check commands (e.g., dmidecode, lspci, dmesg)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "sleep function usage or loops (nanosleep, usleep) in scripts", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindow", "description": "Duration between VM discovery commands and payload execution"}, {"field": "CommandArtifactMatchList", "description": "Command-line regex patterns indicative of sandbox evasion (e.g., grep QEMU, strings vmware)"}]', '2026-05-01 15:26:35.058972');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (473, 'AN0315', 'Analytic 0315', 'Detection of changes to device startup-config files that include boot scripts or scheduled execution routines.', '{"Network Devices"}', 'x-mitre-analytic--416b5616-a16d-4ccc-b214-5873f96e5b1f', 'DET0112', '[{"name": "networkdevice:syslog", "channel": "config", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "Interface", "description": "Affected interface or subsystem; varies per device."}, {"field": "CommandPattern", "description": "Patterns of authorized config changes differ by vendor or policy."}]', '2026-05-01 15:26:35.060506');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (474, 'AN0567', 'Analytic 0567', 'Traffic originating from ESXi hosts or management interfaces displays SNI-to-Host mismatch behavior, particularly anomalous given typical infrastructure communication patterns.', '{ESXi}', 'x-mitre-analytic--4192b311-da7a-4ef1-b09a-a03a8c2a1670', 'DET0196', '[{"name": "NSM:Firewall", "channel": "TLS/HTTP inspection", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "esxi:shell", "channel": "/var/log/vmkernel.log, /var/log/vmkwarning.log", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AdminPortAccess", "description": "ESXi hosts should rarely initiate external HTTPS—threshold to alert."}, {"field": "TLSHandshakeOutliers", "description": "Define entropy or timing anomalies for TLS handshake."}, {"field": "DomainMismatchThreshold", "description": "SNI/Host mismatch occurrence tolerance."}]', '2026-05-01 15:26:35.061869');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (475, 'AN1959', 'Analytic 1959', '
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (476, 'AN0556', 'Analytic 0556', 'Detect suspicious file creation, modification, or deletion in stored data directories (e.g., `/var/lib/mysql/`, `/var/log/`, mail spools). Identify shell commands interacting directly with structured data files instead of legitimate database utilities.', '{Linux}', 'x-mitre-analytic--425a3e89-ac22-4ff3-bc1e-ca1672113075', 'DET0193', '[{"name": "auditd:SYSCALL", "channel": "open, unlink, rename: File creation or deletion involving critical stored data", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "write: Modification of structured stored data by suspicious processes", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "WatchedPaths", "description": "Environment-specific paths where business-critical stored data resides."}, {"field": "CommandExclusions", "description": "Legitimate scripts/utilities excluded to minimize false positives."}]', '2026-05-01 15:26:35.06476');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (477, 'AN0900', 'Analytic 0900', 'Adversaries use cloud API, CLI, or console to create IAM users or roles. Initial CreateUser is followed by policy/role attachment. Detection monitors temporal chains involving IAM:CreateUser, AttachUserPolicy, and credential generation, especially from automation or foreign IP ranges.', '{IaaS}', 'x-mitre-analytic--4264c6fb-20b2-4792-8939-c7d8f204338a', 'DET0319', '[{"name": "AWS:CloudTrail", "channel": "CreateUser", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "AWS:CloudTrail", "channel": "AttachUserPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "Region", "description": "Alert when creation happens in unexpected regions"}, {"field": "TimeWindow", "description": "Chain CreateUser → AttachPolicy → AccessKey within short timeframe"}, {"field": "UserAgent", "description": "Monitor API calls from non-console or automation tools"}]', '2026-05-01 15:26:35.067077');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (478, 'AN1042', 'Analytic 1042', 'Execution of file or directory discovery commands (e.g., ''ls'', ''find'') from terminal or script-based tooling, especially outside normal user workflows.', '{macOS}', 'x-mitre-analytic--42683860-d6df-4585-af65-31f783269f8f', 'DET0370', '[{"name": "macos:unifiedlog", "channel": "log collect --predicate", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "Filesystem Call Monitoring", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "PredicateScope", "description": "Adjust macOS unified log filter to include/exclude system paths"}, {"field": "TimeWindow", "description": "Tune based on burst access patterns"}]', '2026-05-01 15:26:35.068272');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (479, 'AN1123', 'Analytic 1123', 'Detects scripting environments (AppleScript, osascript, curl) or non-native tools performing DNS queries with encoded subdomains, often used for data exfiltration or beaconing.', '{macOS}', 'x-mitre-analytic--42a8c7a7-2773-4892-b647-40d3542ae4d2', 'DET0400', '[{"name": "macos:unifiedlog", "channel": "log stream ''eventMessage contains \"dns_request\"''", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "EntropyThreshold", "description": "Tunable threshold for randomness in subdomain labels"}, {"field": "UncommonProcessContext", "description": "Filters on user-launched or cron-based queries"}]', '2026-05-01 15:26:35.069374');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (480, 'AN0208', 'Analytic 0208', 'Configuration of internal NAT or proxy rules that redirect traffic between client segments internally (e.g., site-to-site port forwarding). Often used to relay internal beaconing or move traffic laterally through trust zones.', '{"Network Devices"}', 'x-mitre-analytic--42ba4dcf-0354-4d70-8c29-d0c3a8c90c23', 'DET0075', '[{"name": "Firewall Audit Logs", "channel": "Config Change", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"name": "NSM:Flow", "channel": "Inter-segment traffic", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "networkdevice:cli", "channel": "Policy Update", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ProxyTarget", "description": "Internal subnets or endpoint roles allowed for port forwarding."}, {"field": "ConfigChangeUser", "description": "Detect changes made outside scheduled or authorized windows."}, {"field": "FlowThreshold", "description": "Volume of data relayed through proxy exceeds historical norms."}]', '2026-05-01 15:26:35.070681');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (481, 'AN0708', 'Analytic 0708', 'Monitor for cloud API calls that export or collect guest or system logs. Abnormal use of Azure VM Agent’s CollectGuestLogs.exe or AWS CloudWatch GetLogEvents across multiple instances should be correlated with lateral movement or data staging.', '{IaaS}', 'x-mitre-analytic--42bae633-1033-40da-bf3a-87bcd1b0297f', 'DET0255', '[{"name": "AWS:CloudTrail", "channel": "GetLogEvents: High frequency log exports from CloudWatch or equivalent services", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "azure:activity", "channel": "CollectGuestLogs: Unexpected collection of guest logs by Azure VM Agent outside normal maintenance windows", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "LogExportThreshold", "description": "Define thresholds for volume/frequency of log export requests considered suspicious."}]', '2026-05-01 15:26:35.072071');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (482, 'AN1052', 'Analytic 1052', 'Execution of PowerShell commands that modify mailbox permissions using Exchange cmdlets (e.g., Add-MailboxPermission), often tied to BEC or post-compromise persistence.', '{Windows}', 'x-mitre-analytic--42d5a9d5-f897-4c45-b577-9b2c776c6c0d', 'DET0373', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "m365:unified", "channel": "PowerShell: Add-MailboxPermission", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "PowerShellCmdletFilter", "description": "Exchange cmdlets to include or exclude based on scope (e.g., Add-MailboxPermission, Set-MailboxFolderPermission)."}, {"field": "ExecutionParent", "description": "Flag suspicious script or interactive shell launch by non-admins."}, {"field": "TimeWindow", "description": "Window in which Add-MailboxPermission is followed by anomalous usage (e.g., SendAs events)."}]', '2026-05-01 15:26:35.073861');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (483, 'AN0381', 'Analytic 0381', 'Detects email-sending behavior via Terminal, AppleScript, or Automator that interfaces with SMTP or IMAP, typically using curl or mail-related APIs in unsanctioned contexts.', '{macOS}', 'x-mitre-analytic--43347e24-50d6-446e-923d-a6fd69805a22', 'DET0135', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate ''processImagePath CONTAINS \"curl\" OR \"osascript\"''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "UserContext", "description": "Monitor non-mail client users initiating SMTP/IMAP"}, {"field": "TimeWindow", "description": "Look for execution of mail commands during off-hours"}]', '2026-05-01 15:26:35.075402');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (484, 'AN0776', 'Analytic 0776', 'Abnormal modification of EFI firmware binaries in /System/Library/CoreServices/ or NVRAM parameters not associated with OS updates. Unified logs capturing calls to bless or nvram commands executed from untrusted parent processes. Sudden unsigned kext loads after EFI variable tampering.', '{macOS}', 'x-mitre-analytic--43834e1c-533a-4f08-b508-8632d35b10ad', 'DET0278', '[{"name": "macos:unifiedlog", "channel": "Execution of bless or nvram modifying boot parameters", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Modification of /System/Library/CoreServices/boot.efi", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "AllowedBootUtilities", "description": "Known Apple-signed processes responsible for firmware updates."}, {"field": "BootParamBaseline", "description": "Baseline set of allowed NVRAM boot parameters for anomaly detection."}]', '2026-05-01 15:26:35.076841');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (485, 'AN1991', 'Analytic 1991', 'Once adversaries leverage compromised network devices as infrastructure (ex: for command and control), it may be possible to look for unique characteristics associated with adversary software, if known.(Citation: ThreatConnect Infrastructure Dec 2020) Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle. ', '{PRE}', 'x-mitre-analytic--4384e648-0f49-442d-b989-6a47f2194130', 'DET0859', '[{"name": "Internet Scan", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--0dcbbf4f-929c-489a-b66b-9b820d3f7f0e"}]', NULL, '2026-05-01 15:26:35.078193');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (486, 'AN1410', 'Analytic 1410', 'Adversary mounts a USB device and begins enumerating, copying, or compressing files using scripting engines, cmd, or remote access tools.', '{Windows}', 'x-mitre-analytic--4385bff9-e730-48cd-bdfc-43de56c302aa', 'DET0511', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:System", "channel": "EventCode=2003", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "VolumeLabel", "description": "Can tune based on known removable device labels or whitelist"}, {"field": "TimeWindow", "description": "Controls timing between device mount and sensitive file access"}, {"field": "TargetFileType", "description": "Tune for sensitive file extensions (e.g., .docx, .pdf, .csv)"}]', '2026-05-01 15:26:35.079477');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (487, 'AN0526', 'Analytic 0526', 'Use of AWS STS or GCP IAM APIs to request temporary tokens or federation sessions inconsistent with normal account activity, including from unexpected principals or regions.', '{IaaS}', 'x-mitre-analytic--43ccb88d-8d8a-4ddb-9ffd-3d897fba76a3', 'DET0185', '[{"name": "AWS:CloudTrail", "channel": "AssumeRole, GetFederationToken, GetSessionToken", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "AWS:CloudTrail", "channel": "sts:GetFederationToken", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "GeoIPDistanceThreshold", "description": "Distance between token creation and resource use locations"}, {"field": "RoleScope", "description": "Limit scope of acceptable role assumptions by account type"}]', '2026-05-01 15:26:35.080912');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (488, 'AN1195', 'Analytic 1195', 'Unauthorized modification of service-related registry keys such as ImagePath, FailureCommand, ServiceDll, or Performance/Parameters keys. Defender correlates registry modifications, anomalous service metadata changes, and subsequent service process executions that deviate from baseline configurations.', '{Windows}', 'x-mitre-analytic--43f5598c-5c63-40f4-b936-2978bd0f3aa0', 'DET0427', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:System", "channel": "EventCode=7040", "x_mitre_data_component_ref": "x-mitre-data-component--66531bc6-a509-4868-8314-4d599e91d222"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredServiceKeys", "description": "Registry subkeys for critical services (ImagePath, ServiceDll, FailureCommand, Parameters)."}, {"field": "BaselineServiceConfig", "description": "Known good service registry configurations and paths for comparison."}, {"field": "TimeWindow", "description": "Correlation interval between registry/service modifications and service execution."}, {"field": "PrivilegedAccounts", "description": "Accounts permitted to modify service configurations."}]', '2026-05-01 15:26:35.082153');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (489, 'AN2008', 'Analytic 2008', 'Consider monitoring social media activity related to your organization. Suspicious activity may include personas claiming to work for your organization or recently modified accounts making numerous connection requests to accounts affiliated with your organization.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (490, 'AN1966', 'Analytic 1966', 'If infrastructure or patterns in tooling have been previously identified, internet scanning may uncover when an adversary has staged tools to make them accessible for targeting.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (491, 'AN1254', 'Analytic 1254', 'Anomalous use of ICMP or UDP by non-network service processes for data exfiltration or remote control, especially if traffic bypasses proxy infrastructure or shows unusual flow patterns.', '{Windows}', 'x-mitre-analytic--4412fb07-9a44-49de-80af-8746b0be3865', 'DET0457', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "ICMP/UDP traffic (Wireshark, Suricata, Zeek)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ProcessContextAllowList", "description": "Processes normally allowed to use ICMP/UDP (e.g., ping.exe, DNS resolver)."}, {"field": "ByteTransferAnomalyThreshold", "description": "Suspicion if client sends much more data than it receives (e.g., >90%)."}, {"field": "ProtocolUsageBaseline", "description": "Baseline which protocols are normal per host or segment (ICMP, UDP, etc.)."}]', '2026-05-01 15:26:35.086276');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (492, 'AN0520', 'Analytic 0520', 'Monitors sequences involving deletion/modification of logs, registry keys, scheduled tasks, or prefetch files following suspicious process activity or elevated access escalation.', '{Windows}', 'x-mitre-analytic--4416c78b-902b-4baa-9a5d-26f0b7e5d78d', 'DET0184', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=23", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "WinEventLog:Security", "channel": "EventCode=1102", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TimeWindow", "description": "Correlate indicator removal within X mins after persistence/setup activities"}, {"field": "TargetFilePathPattern", "description": "Customize detection to log file paths or common registry hives"}]', '2026-05-01 15:26:35.087537');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (498, 'AN1636', 'Analytic 1636', 'Detects exploitation of IaaS cloud security boundaries to evade defense controls. Defender perspective includes anomalous API calls that bypass audit logging, disable monitoring, or manipulate guardrails (e.g., CloudTrail tampering). Correlation highlights when exploitation attempts precede sudden absence of expected telemetry.', '{IaaS}', 'x-mitre-analytic--458038e6-60a2-47d2-bd55-675e77f0e279', 'DET0595', '[{"name": "AWS:CloudTrail", "channel": "StopLogging, DeleteTrail, UpdateTrail: API calls that disable or modify logging services", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "CriticalAPIs", "description": "List of sensitive cloud API operations that should be rare and tightly monitored."}, {"field": "TimeWindow", "description": "Duration for correlation of API exploitation with sudden logging gaps."}]', '2026-05-01 15:26:35.097162');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (493, 'AN1208', 'Analytic 1208', 'Detects creation or modification of user-level Launch Agents in monitored directories using `.plist` files with suspicious `ProgramArguments` or `RunAtLoad` keys. Correlates file write activity with execution of `launchctl` or unsigned binaries invoked at login.', '{macOS}', 'x-mitre-analytic--441bfb28-3fe5-410b-93a5-2280a7f19dad', 'DET0434', '[{"name": "macos:unifiedlog", "channel": "launchctl load or boot-time plist registration", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "fs:fsusage", "channel": "write or chmod to ~/Library/LaunchAgents/*.plist", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "fs:fsusage", "channel": "modification of existing LaunchAgents plist", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:osquery", "channel": "detection of new launch agents with suspicious paths or unsigned binaries", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "PlistDirectoryList", "description": "Monitored directories (e.g., `/Library/LaunchAgents`, `~/Library/LaunchAgents`) for plist drops"}, {"field": "PlistKeyMonitor", "description": "Monitored keys such as `RunAtLoad`, `KeepAlive`, or `ProgramArguments` for policy alignment"}, {"field": "ExecutablePathPattern", "description": "Patterns used to detect execution from non-standard or suspicious locations like `/tmp`, `/var`, or `/Users/Shared`"}, {"field": "UnsignedBinaryAlert", "description": "Raise alerts if the binary referenced in the Launch Agent is unsigned or unverified"}, {"field": "UserContextScope", "description": "List of users whose LaunchAgents are considered high-sensitivity (e.g., admins)"}]', '2026-05-01 15:26:35.088908');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (494, 'AN1289', 'Analytic 1289', 'Detects thread local storage (TLS) callback injection by monitoring memory modifications to PE headers and TLS directory structures during or after process hollowing events, followed by anomalous thread behavior prior to main entry point execution.', '{Windows}', 'x-mitre-analytic--44500eb7-01f2-4cab-8b76-1227bb48e13e', 'DET0467', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "EDR:memory", "channel": "MemoryWriteToExecutable", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "TargetProcessFilter", "description": "Subset of processes whose TLS callbacks should not change post-load (e.g., explorer.exe, lsass.exe)"}, {"field": "TimeWindowBetweenLoadAndTLSModification", "description": "Acceptable delay between image load and memory tampering in .tls or .data sections"}, {"field": "AnomalousThreadStartThreshold", "description": "Number of threads executing prior to main entry point that is considered suspicious"}, {"field": "PayloadEntropyThreshold", "description": "Optional threshold to distinguish injected shellcode from benign memory writes"}]', '2026-05-01 15:26:35.091781');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (495, 'AN0577', 'Analytic 0577', 'DLL hijacking behaviors including unexpected DLL loads from non-standard directories, replacement of DLLs, phantom DLL insertion, redirection file creation, and substitution of legitimate DLLs. Defender correlates file system modifications, registry changes, and module load telemetry to detect abnormal DLL behavior in trusted processes.', '{Windows}', 'x-mitre-analytic--448ecbfb-2b38-4ecc-9c63-f7dd87339271', 'DET0201', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AllowedDllPaths", "description": "Known safe DLL directories to suppress false positives (e.g., C:\\Windows\\System32)."}, {"field": "ProcessAllowList", "description": "Applications expected to load DLLs from non-standard locations (e.g., development tools)."}, {"field": "TimeWindow", "description": "Correlation interval between DLL file creation, registry changes, and module load."}, {"field": "HashBaseline", "description": "Baseline hashes for legitimate DLLs used to detect substitution."}]', '2026-05-01 15:26:35.093225');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (496, 'AN0572', 'Analytic 0572', 'Monitor for execution of hypervisor management commands such as `esxcli vm process list` or `vim-cmd vmsvc/getallvms` that enumerate virtual machines. Defenders observe unexpected users issuing VM listing commands outside normal administrative workflows.', '{ESXi}', 'x-mitre-analytic--44bb0cf8-12ee-4a8f-8701-6c787a008bd8', 'DET0199', '[{"name": "esxi:shell", "channel": "command IN (\"esxcli vm process list\", \"vim-cmd vmsvc/getallvms\")", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ExpectedAdminUsers", "description": "List of known administrators authorized to run ESXi enumeration commands."}, {"field": "UnexpectedCommandPaths", "description": "Defines restricted paths or contexts where VM enumeration should not occur."}]', '2026-05-01 15:26:35.094439');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (497, 'AN1142', 'Analytic 1142', 'Command-line initiated UDP traffic bursts to external reflection amplification ports using built-in scripting or binaries with network anomalies', '{macOS}', 'x-mitre-analytic--44c2e32e-bd34-4ba9-8105-28c14309207c', 'DET0408', '[{"name": "macos:unifiedlog", "channel": "Execution of ping, nping, or crafted network packets via bash or python to reflection services", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Outbound UDP spikes to external reflector IPs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ReflectionPorts", "description": "Ports known for reflection abuse — DNS, NTP, SSDP, Memcached"}, {"field": "TrafficSpikeThreshold", "description": "How much deviation in outbound traffic constitutes a suspicious spike"}]', '2026-05-01 15:26:35.095978');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (499, 'AN1490', 'Analytic 1490', 'Unusual long-running processes consuming high CPU cycles (e.g., via ''top'' or ''ps'') initiated via cron, shell scripts, or Docker. Connections to known mining pools or DNS over HTTPS usage as evasion.', '{Linux}', 'x-mitre-analytic--45a34d76-16aa-45ac-9419-ffbc5d2e090d', 'DET0540', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Outbound connection to mining pool port (3333, 4444, 5555)", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "linux:cron", "channel": "Scheduled execution of unknown or unusual script/binary", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}]', '[{"field": "CommandLine", "description": "The miner''s execution path and options may vary by campaign."}, {"field": "CPUThreshold", "description": "Environment-specific definition of anomalous CPU usage."}]', '2026-05-01 15:26:35.098303');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (500, 'AN1237', 'Analytic 1237', 'Account creation using ''dscl -create'' or via GUI tools. Detection involves command execution and file changes to the local directory services database.', '{macOS}', 'x-mitre-analytic--45e8fdaf-60cc-46db-a9fd-5dc18c8db6bb', 'DET0447', '[{"name": "macos:unifiedlog", "channel": "dscl -create", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "modification to /var/db/dslocal/nodes/Default/users/", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "UsernamePattern", "description": "Accounts like ''svc*'', ''backup*'' may blend into legit naming patterns"}, {"field": "SessionOrigin", "description": "Identify if dscl was run locally, via ARD, or Terminal.app"}]', '2026-05-01 15:26:35.099624');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (501, 'AN1415', 'Analytic 1415', 'Detects abnormal encrypted network connections (via TLS/HTTPS) initiated by non-browser binaries, particularly after sensitive file access or compression events.', '{macOS}', 'x-mitre-analytic--46585379-5be9-4ce0-9178-c3492f539e11', 'DET0512', '[{"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "log stream - file provider subsystem", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "ssl.log, x509.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "OutboundTrafficVolumeThreshold", "description": "Trigger detection for large amounts of outbound encrypted data."}, {"field": "FileSensitivityContext", "description": "Tagging and prioritizing high-value directories/files in detection logic."}]', '2026-05-01 15:26:35.100854');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (502, 'AN1344', 'Analytic 1344', 'Behavioral chain: (1) a login from a third-party account or untrusted source network establishes an interactive/remote session; (2) the session acquires elevated privileges or accesses sensitive resources atypical for that account; (3) subsequent lateral movement or data access occurs from the same session/device. Correlate Windows logon events, token elevation/privileged use, and resource access with third-party context.', '{Windows}', 'x-mitre-analytic--46630fc8-75de-4b73-b46e-0a4eeb7ad310', 'DET0488', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4776, 4771, 4770", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ThirdPartyCIDRs", "description": "Ranges used by MSPs/contractors/VPN egress; used to enrich logons and network flows."}, {"field": "ExpectedAdminHosts", "description": "Servers where third-party admins are allowed; deviations raise risk."}, {"field": "TimeWindow", "description": "Correlation window linking logon → elevation → access (e.g., 30–120 minutes)."}, {"field": "HighValueResources", "description": "File shares/AD objects/servers that should never be touched by third-party sessions."}]', '2026-05-01 15:26:35.102188');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (503, 'AN0985', 'Analytic 0985', 'Detects binaries or launch daemons in /System/Library or /Applications with mismatched bundle names, unexpected metadata, or improper installation origin.', '{macOS}', 'x-mitre-analytic--466a2102-fcb3-4372-9a8d-ad8fe34e94ec', 'DET0347', '[{"name": "macos:unifiedlog", "channel": "log collect from launchd and process start", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "fs:fsusage", "channel": "filesystem monitoring of exec/open", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "expected_bundle_names", "description": "List of known application names and paths to validate against"}, {"field": "signed_by_apple_check", "description": "Toggle to enforce checks for Apple-signed binaries in trusted directories"}]', '2026-05-01 15:26:35.103535');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (504, 'AN0191', 'Analytic 0191', 'Phishing via Office documents containing embedded macros or links that spawn processes. Detection relies on correlating Office application logs with suspicious child process execution and outbound network connections.', '{"Office Suite"}', 'x-mitre-analytic--46ecb875-0842-4171-bb36-9b361453a89f', 'DET0070', '[{"name": "m365:unified", "channel": "FileAccessed: Access of email attachments by Office applications", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ParentProcessList", "description": "Parent processes expected to execute child processes (e.g., Office apps)."}, {"field": "MacroExecutionThreshold", "description": "Threshold for number of macros executed before raising alerts."}]', '2026-05-01 15:26:35.104743');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (550, 'AN0193', 'Analytic 0193', 'Phishing delivered via SaaS services (chat, collaboration platforms) where messages contain malicious URLs or attachments. Detect anomalous link clicks, suspicious file uploads, or token misuse after SaaS-based phishing attempts.', '{SaaS}', 'x-mitre-analytic--4da63d13-d9bb-41c6-88c8-31bc9f2579fb', 'DET0070', '[{"name": "saas:collaboration", "channel": "MessagePosted: Suspicious links or attachment delivery via collaboration tools (Slack, Teams, Zoom)", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MonitoredSaaSApps", "description": "Scope of SaaS platforms under phishing monitoring."}, {"field": "LinkInspectionPolicy", "description": "Threshold for auto-expansion and detonation of URLs sent in SaaS messages."}]', '2026-05-01 15:26:35.171656');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (505, 'AN0587', 'Analytic 0587', 'Instance enters degraded/unhealthy state due to abnormal process load or memory exhaustion, often caused by automation or script-based attacks.', '{IaaS}', 'x-mitre-analytic--472f81b1-99ba-406a-b2ef-d70b2af5b527', 'DET0208', '[{"name": "AWS:CloudWatch", "channel": "StatusCheckFailed or StatusCheckFailed_System for burstable instances (t2/t3)", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "AWS:CloudTrail", "channel": "StartInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "VPCFlowLogs:All", "channel": "High volume internal traffic with low entropy indicating looped or malicious DoS script", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "InstanceType", "description": "Burstable vs compute-optimized instances impact DoS effect"}, {"field": "FailureThreshold", "description": "How many consecutive StatusCheckFailed events to consider critical"}]', '2026-05-01 15:26:35.106123');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (506, 'AN1256', 'Analytic 1256', 'Unsigned binaries or interpreted scripts initiating non-standard protocols (ICMP, UDP, SOCKS) outside of baseline network behavior.', '{macOS}', 'x-mitre-analytic--4742e058-a301-47e1-b594-8daa8eabfc79', 'DET0457', '[{"name": "macos:unifiedlog", "channel": "com.apple.network", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "ICMP/UDP monitoring (tcpdump, Wireshark, Zeek)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "UnsignedBinaryNetworkUsage", "description": "Detection threshold for unsigned or transient binaries making ICMP/UDP calls."}]', '2026-05-01 15:26:35.107897');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (507, 'AN1325', 'Analytic 1325', 'Enumeration of services via native CLI tools (e.g., `sc query`, `tasklist /svc`, `net start`) or API calls via PowerShell and WMI.', '{Windows}', 'x-mitre-analytic--475313b7-c26f-44f6-a8f3-09b57f03fcd8', 'DET0483', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ProcessName", "description": "Can be tuned to specific binaries used for service enumeration (e.g., `sc.exe`, `tasklist.exe`)."}, {"field": "CommandLineMatch", "description": "Filters for variations like `sc query`, `net start`, `Get-Service`."}, {"field": "ParentProcess", "description": "Used to suppress known admin scripts or automation jobs."}]', '2026-05-01 15:26:35.109229');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (508, 'AN1626', 'Analytic 1626', 'Detects attempts to modify file timestamps via API usage (e.g., `SetFileTime`), CLI tools (e.g., `w32tm`, PowerShell), or double-timestomp behavior where $SI and $FN timestamps are mismatched or reverted.', '{Windows}', 'x-mitre-analytic--475a8817-1ace-4bef-baaa-0f56979eb85a', 'DET0591', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "EDR:file", "channel": "SetFileTime", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "TimeWindow", "description": "Correlate timestamp change with preceding file creation or suspicious access"}, {"field": "APINamePattern", "description": "Include SetFileTime, NtSetInformationFile, or other timestamp APIs"}, {"field": "TimestampDeltaThreshold", "description": "Trigger on excessive backdating (e.g., >90 days)"}]', '2026-05-01 15:26:35.110624');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (509, 'AN1349', 'Analytic 1349', 'Behavioral chain: (1) third-party app or admin connects via OAuth/marketplace install; (2) high-privilege scopes granted; (3) anomalous actions (mass read/exports, admin changes).', '{SaaS}', 'x-mitre-analytic--4766bdc0-047a-4250-93c1-6d907178620e', 'DET0488', '[{"name": "saas:googleworkspace", "channel": "OAuth2 authorization grants / Admin role assignments", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:salesforce", "channel": "ConnectedApp OAuth policy change / Login as user", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "ApprovedApps", "description": "Catalog of sanctioned third-party apps and scopes."}, {"field": "ExportVolumeThreshold", "description": "Data export size/rate baselines to detect abnormal partner activity."}]', '2026-05-01 15:26:35.111941');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (510, 'AN0155', 'Analytic 0155', 'Detection of malicious certificate installation via monitoring execution of the `security add-trusted-cert` command and modifications to system keychains.', '{macOS}', 'x-mitre-analytic--477fb167-a388-4e85-856b-bdcb36e7fd95', 'DET0056', '[{"name": "macos:unifiedlog", "channel": "Execution of /usr/bin/security add-trusted-cert or keychain modifications to System.keychain", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "query: Enumeration of root certificates showing unexpected additions", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "MonitoredCommands", "description": "Commands related to certificate management (e.g., security, profiles) that can be tuned per environment."}, {"field": "KeychainBaseline", "description": "Baseline of expected certificates in System.keychain to reduce false positives from legitimate enterprise certificates."}]', '2026-05-01 15:26:35.114754');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (511, 'AN0539', 'Analytic 0539', 'Use of `esxcli storage` or `vim-cmd vmsvc/getallvms` by unusual sessions or through interactive shells unrelated to administrative maintenance tasks.', '{ESXi}', 'x-mitre-analytic--478e6298-d012-4337-b2ed-0f8d4909ee05', 'DET0188', '[{"name": "esxi:hostd", "channel": "execution of esxcli with args matching ''storage'', ''filesystem'', ''core device list''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "esxi:auth", "channel": "interactive shell or SSH access preceding storage enumeration", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "ssh_source_ip", "description": "Restrict alerts to unexpected remote sessions accessing host storage commands"}, {"field": "esxcli_command_scope", "description": "Tailor detection based on subcommands more likely to be abused"}]', '2026-05-01 15:26:35.116093');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1121, 'AN1425', 'Analytic 1425', 'Unusual OAuth app registration followed by user-granted OAuth tokens and subsequent high-privilege resource access via those tokens.', '{"Identity Provider"}', 'x-mitre-analytic--a064fdd2-4293-4aff-a91b-e06ac8bf9262', 'DET0515', '[{"name": "azure:audit", "channel": "App registrations or consent grants by abnormal users or at unusual times", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ConsentScope", "description": "Tunable based on risky or privileged scopes in the environment"}, {"field": "AppUserRatio", "description": "Threshold of how many users have authorized a given app"}]', '2026-05-01 15:26:36.035933');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (512, 'AN1355', 'Analytic 1355', 'Execution of system utilities like ''system_profiler'' and ''ioreg'' to enumerate hardware components or USB devices, particularly if followed by clipboard, file, or network activity.', '{macOS}', 'x-mitre-analytic--479e5749-a746-4b17-9543-ca4b9d41576a', 'DET0491', '[{"name": "macos:unifiedlog", "channel": "process exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "usb_devices", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}]', '[{"field": "BinaryList", "description": "Commands like ''system_profiler SPUSBDataType'', ''ioreg -p IOUSB'' that may indicate enumeration"}, {"field": "TimeWindow", "description": "Temporal grouping of enumeration with follow-on activity (e.g., clipboard capture, exfiltration)"}]', '2026-05-01 15:26:35.117562');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (513, 'AN2041', 'Analytic 2041', 'Detects exploitation of cloud-native security boundaries or management components followed by disabled logging, detached agents, changed security groups, policy bypass, or telemetry suppression. Correlates suspicious API activity with reduced control coverage.', '{IaaS}', 'x-mitre-analytic--47df93f9-b33f-4333-95b6-b3cca9418a4d', 'DET0900', '[{"name": "AWS:CloudTrail", "channel": "StopLogging, DeleteTrail, or DisableSecurityService", "x_mitre_data_component_ref": "x-mitre-data-component--ec0612c5-2644-4c50-bcac-82586974fedd"}, {"name": "AWS:CloudTrail", "channel": "ModifyInstanceAttribute", "x_mitre_data_component_ref": "x-mitre-data-component--45d0ff14-b9c4-41f5-8603-156657c20b75"}, {"name": "AWS:CloudTrail", "channel": "AuthorizeSecurityGroupIngress", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}]', '[{"field": "CriticalTrailList", "description": "Audit trails that must remain enabled"}, {"field": "ControlChangeWindow", "description": "Time after suspicious API sequence to inspect coverage loss"}]', '2026-05-01 15:26:35.118864');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (514, 'AN0306', 'Analytic 0306', 'Monitor for unexpected modifications of plist files in persistence or configuration directories (e.g., ~/Library/LaunchAgents, ~/Library/Preferences, /Library/LaunchDaemons). Detect when modifications are followed by execution of new or unexpected binaries. Track use of utilities such as defaults, plutil, or text editors making changes to Info.plist files. Correlate file modifications with subsequent process launches or service starts that reference the altered plist.', '{macOS}', 'x-mitre-analytic--481966ed-de78-42e4-9c51-c69281a21650', 'DET0109', '[{"name": "macos:unifiedlog", "channel": "write: File modifications to *.plist within LaunchAgents, LaunchDaemons, Application Support, or Preferences directories", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "exec: Execution of defaults, plutil, or common editors (vim/nano) targeting plist files", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "exec: Invocation of /usr/bin/defaults write or /usr/bin/plutil modifying plist keys", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "MonitoredDirectories", "description": "Set of directories where plist modifications are considered suspicious (e.g., ~/Library/LaunchAgents, /Library/LaunchDaemons)"}, {"field": "SuspiciousKeys", "description": "List of plist keys associated with evasion or persistence (e.g., LSUIElement, LSEnvironment, ProgramArguments)"}, {"field": "TimeWindow", "description": "Temporal correlation window to link plist file modifications with subsequent suspicious process launches"}]', '2026-05-01 15:26:35.120124');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (515, 'AN0553', 'Analytic 0553', 'Rule manipulation through local email clients (e.g., Evolution, Thunderbird) or server-side filtering scripts (e.g., sieve) creating conditions to move or discard emails with security-related keywords.', '{Linux}', 'x-mitre-analytic--487d9ddf-a790-4adc-9be4-ec5651e790f1', 'DET0192', '[{"name": "auditd:SYSCALL", "channel": "execve calls modifying local mail filter configuration files", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "ApplicationLog:MailServer", "channel": "Unexpected additions of sieve rules or filtering directives", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MailServerLogs", "description": "Customize based on mail server software (Postfix, Dovecot, Exim)."}]', '2026-05-01 15:26:35.121446');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (516, 'AN1970', 'Analytic 1970', 'Once adversaries have provisioned a VPS (ex: for use as a command and control server), internet scans may reveal servers that adversaries have acquired. Consider looking for identifiable patterns such as services listening, certificates in use, SSL/TLS negotiation features, or other response artifacts associated with adversary C2 software.(Citation: ThreatConnect Infrastructure Dec 2020)(Citation: Mandiant SCANdalous Jul 2020)(Citation: Koczwara Beacon Hunting Sep 2021) Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (517, 'AN0250', 'Analytic 0250', 'Behavioral chain involving suspicious use of GetProcAddress and LoadLibrary following memory allocation and manual mapping, often paired with low entropy strings, abnormal API use without static import tables, or delayed module load behaviors.', '{Windows}', 'x-mitre-analytic--48a818ac-077b-46ff-b615-bb2958536aef', 'DET0091', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "API tracing / stack tracing via ETW or telemetry-based EDR", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "APILoadWithoutImport", "description": "Tunable logic to flag suspicious modules used without static IAT entries"}, {"field": "TimeWindow", "description": "Correlates module load to suspicious memory allocation or API lookup within timeframe"}, {"field": "EntropyThreshold", "description": "Used to detect obfuscated strings or hashed function names"}, {"field": "StackTraceFilter", "description": "Optional filtering of known safe modules or patterns from telemetry"}]', '2026-05-01 15:26:35.124447');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (518, 'AN0085', 'Analytic 0085', 'Adversary uses a tool like Ruler to insert a malicious custom form into the user''s Outlook mailbox. The form is designed to auto-execute on Outlook startup or on receipt of a specially crafted email. This results in child processes launched from outlook.exe and possibly network connections or payload loading.', '{Windows}', 'x-mitre-analytic--48cc1694-568f-4602-96e4-cbbe099c6dae', 'DET0029', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Application", "channel": "Outlook errors loading or processing custom form templates", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:PowerShell", "channel": "Execution of Microsoft script to enumerate custom forms in Outlook mailbox", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "FormStorageLocation", "description": "Malicious forms may be stored in various user-specific locations in the Outlook mailbox (e.g., IPM.Note class)"}, {"field": "ChildProcessName", "description": "Child process spawned by outlook.exe may vary (e.g., powershell.exe, rundll32.exe, mshta.exe)"}, {"field": "TimeWindow", "description": "Form-triggered execution may happen immediately upon Outlook startup or with delay after crafted message arrival"}, {"field": "OutlookVersion", "description": "Form behavior and error logs may vary across Outlook 2013, 2016, and M365 builds"}, {"field": "UserContext", "description": "Attack may target only specific users; contextual correlation needed for account baselining"}]', '2026-05-01 15:26:35.125982');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (519, 'AN1450', 'Analytic 1450', 'Remote knock sequence followed by PF/socketfilterfw rule update or a background process listening on a new port; then a successful TCP session. Also flags WoL magic packets on local segment.', '{macOS}', 'x-mitre-analytic--48d2effa-7fc0-4790-9cc9-bbe573c29301', 'DET0524', '[{"name": "macos:unifiedlog", "channel": "exec: Execution of /sbin/pfctl, /usr/libexec/ApplicationFirewall/socketfilterfw, ifconfig, tcpdump, npcap/libpcap consumers", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Firewall rule enable/disable or listen socket changes", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "Closed-port hits followed by success from same src_ip", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "PFAnchorPaths", "description": "Anchors or conf files monitored for change (/etc/pf.conf, /etc/pf.anchors/*)."}, {"field": "DeveloperMode", "description": "Reduce noise on dev endpoints compiling or testing PF rules."}]', '2026-05-01 15:26:35.127551');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (520, 'AN0965', 'Analytic 0965', 'Detection of clipboard access via OS utilities (e.g., clip.exe, Get-Clipboard) by non-interactive or abnormal parent processes, potentially chained with staging or exfiltration commands.', '{Windows}', 'x-mitre-analytic--48e4aceb-38dd-4bf2-8074-9fee8436985b', 'DET0341', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "TimeWindow", "description": "Defines how far back to look for parent-child relationships and follow-on network activity."}, {"field": "UserContext", "description": "Filters based on service vs interactive users to reduce noise."}, {"field": "ParentProcessName", "description": "Tunable list of expected/benign clipboard accessors."}]', '2026-05-01 15:26:35.129279');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (521, 'AN1221', 'Analytic 1221', 'Detects the creation, modification, or deletion of scheduled tasks through Task Scheduler, WMI, PowerShell, or API-based methods followed by execution from svchost.exe or taskeng.exe. Includes detection of hidden or anomalous scheduled tasks, especially those created under SYSTEM or suspicious user contexts.', '{Windows}', 'x-mitre-analytic--4959f750-78db-4b4c-8d91-23027b386c2b', 'DET0441', '[{"name": "WinEventLog:Security", "channel": "EventCode=4698", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "WinEventLog:Security", "channel": "EventCode=4702", "x_mitre_data_component_ref": "x-mitre-data-component--faa34cf6-cf32-4dc9-bd6a-8f7a606ff65b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TimeWindow", "description": "Defines threshold for grouping task creation and associated execution within suspicious time proximity."}, {"field": "UserContext", "description": "Filters based on non-standard user accounts or execution under SYSTEM when not typical for the environment."}, {"field": "TaskNamePattern", "description": "Allows defenders to flag obfuscated, randomized, or suspicious task names outside normal conventions."}, {"field": "CommandLineEntropyThreshold", "description": "Flags tasks executing heavily obfuscated PowerShell or binary blobs via base64 or encoding."}]', '2026-05-01 15:26:35.130619');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (522, 'AN1155', 'Analytic 1155', 'Unusual access to ~/Library/Keychains, ~/.bash_history, or Terminal command history by unauthorized processes or users.', '{macOS}', 'x-mitre-analytic--49897e8e-8d14-4fcb-b305-328d44e58f35', 'DET0412', '[{"name": "macos:unifiedlog", "channel": "read access to ~/Library/Keychains or history files by terminal processes", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "execution of ''security'', ''cat'', or ''grep'' commands accessing credential storage", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ProcessName", "description": "Tool or command used to query credentials (e.g., security, grep)"}, {"field": "TargetPath", "description": "Credential file paths (e.g., ~/Library/Keychains)"}]', '2026-05-01 15:26:35.131898');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (564, 'AN1956', 'Analytic 1956', 'If infrastructure or patterns in malware have been previously identified, internet scanning may uncover when an adversary has staged malware to make it accessible for targeting.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (523, 'AN1583', 'Analytic 1583', 'Execution of network enumeration utilities (e.g., net.exe, ping.exe, tracert.exe) in short succession, often chained with lateral movement tools or system enumeration commands.', '{Windows}', 'x-mitre-analytic--498eb889-4468-4c55-9337-df219d5f142b', 'DET0574', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Define bursty execution patterns of enumeration commands (e.g., <30s)"}, {"field": "CommandLinePattern", "description": "Tunable per org’s scripting/IT tools (e.g., exclude SCCM, PsExec)"}, {"field": "ParentProcess", "description": "Flag suspicious process ancestry (e.g., Word.exe spawning net.exe)"}]', '2026-05-01 15:26:35.133043');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (524, 'AN1301', 'Analytic 1301', 'Detects upload of malicious or unusual file types into cloud-shared folders, followed by user downloads or interactions.', '{SaaS}', 'x-mitre-analytic--49e91c60-9b73-4a0a-9510-f94152a8ba5e', 'DET0471', '[{"name": "gcp:workspaceaudit", "channel": "drive.activity logs", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "m365:unified", "channel": "FileUploaded, FileAccessed", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}]', '[{"field": "UserUploadRateThreshold", "description": "Abnormal upload patterns into shared drives."}, {"field": "MaliciousFileIndicator", "description": "File hash or known-bad filename pattern matching."}]', '2026-05-01 15:26:35.134308');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (525, 'AN1430', 'Analytic 1430', 'Detects launch of command-line interpreters via Terminal, Automator, or hidden `osascript`, especially when parent process lineage deviates from user-initiated applications.', '{macOS}', 'x-mitre-analytic--4a32d0e6-9486-4bbb-8807-7f913f96f448', 'DET0516', '[{"name": "macos:unifiedlog", "channel": "log stream --info --predicate ''eventMessage CONTAINS \"exec\"''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "LaunchAgentName", "description": "Monitor for specific plist agents frequently abused for persistence or payload execution."}, {"field": "ScriptName", "description": "Path or script name pattern (e.g., hidden files, /tmp locations)."}, {"field": "TerminalAppUsage", "description": "Adjust based on whether Terminal.app use is common or restricted in user policy."}]', '2026-05-01 15:26:35.135798');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (526, 'AN0038', 'Analytic 0038', 'Unauthorized shell or script-based access to browser config or SQLite history files, typically in ~/.config/google-chrome/, ~/.mozilla/, or ~/.var/app folders, indicating enumeration of bookmarks or saved credentials.', '{Linux}', 'x-mitre-analytic--4a5abd9c-b4f3-4c29-9406-82aa3401c049', 'DET0013', '[{"name": "auditd:SYSCALL", "channel": "open, read, or stat of browser config files", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:syslog", "channel": "Suspicious script or command execution targeting browser folders", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "BrowserProfilePath", "description": "User-specific browser data folders, e.g., ~/.config/chromium/Default/History"}, {"field": "ShellRegex", "description": "Shell pattern detecting suspicious access to .sqlite or .json files"}]', '2026-05-01 15:26:35.136932');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (527, 'AN1113', 'Analytic 1113', 'Detection of automated tools or scripts periodically transmitting data to external destinations using scheduled tasks or background processes.', '{Windows}', 'x-mitre-analytic--4a92d2e9-fc28-4eac-9b3d-113e74d7bf2d', 'DET0397', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Used to detect repeated exfil activity over intervals (e.g., every 5 minutes)."}, {"field": "DestinationIP", "description": "Can be tuned to filter known internal or trusted destinations."}]', '2026-05-01 15:26:35.138113');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (528, 'AN1267', 'Analytic 1267', 'Router/firewall/syslog logs showing authentication failures with unique usernames and reused credentials from same source IP', '{"Network Devices"}', 'x-mitre-analytic--4a930e8d-75eb-469d-82d8-1e1d5764a6d4', 'DET0460', '[{"name": "networkdevice:syslog", "channel": "AAA, RADIUS, or TACACS authentication", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AuthProtocolFilter", "description": "Limit detection to interactive logins rather than SNMP/RPC"}, {"field": "FailedAuthBurst", "description": "Detection trigger when failure rate exceeds normal profile"}]', '2026-05-01 15:26:35.139599');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (529, 'AN0799', 'Analytic 0799', 'Cause→effect chain: (1) App crash/abnormal termination in unified logs for Safari/Chrome/Office/Preview, (2) new files/scripts in ~/Library, ~/Downloads, /private/var/folders/*, (3) unexpected child (osascript, zsh, bash, curl) spawned by those apps, (4) new outbound connections.', '{macOS}', 'x-mitre-analytic--4aaf0a98-c6a9-4b30-a9d9-3a014473bd0e', 'DET0287', '[{"name": "macos:unifiedlog", "channel": "process crash, abort, code signing violations", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "fs:fsevents", "channel": "create/write/rename under user-writable paths", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:osquery", "channel": "exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "new connections from exploited lineage", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "10–30m correlation window."}, {"field": "HighRiskChildren", "description": "osascript, bash, zsh, curl, python, pbpaste/pbcopy, open -a Terminal."}, {"field": "UserPaths", "description": "~/Library/LaunchAgents, ~/Library/Containers/*/Data, /private/var/folders/*."}, {"field": "QuarantineBypass", "description": "Flag files with missing com.apple.quarantine extended attribute when sourced from internet."}]', '2026-05-01 15:26:35.141441');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (591, 'AN1431', 'Analytic 1431', 'Detects use of ''esxcli system'' or direct interpreter commands (e.g., busybox shell) invoked from SSH or host terminal unexpectedly.', '{ESXi}', 'x-mitre-analytic--533d13df-5317-45dd-a544-c26d0192d6b2', 'DET0516', '[{"name": "esxi:vobd", "channel": "shell session start", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ShellEnabledFlag", "description": "Control alerting based on whether ESXi shell access is typically disabled."}, {"field": "SSHContext", "description": "Scope detection to SSH session origins or internal vs. remote access."}]', '2026-05-01 15:26:35.230133');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (530, 'AN0374', 'Analytic 0374', 'User-mode application uses flock() or NSDistributedLock to gain exclusive access to a resource file (e.g., /tmp/guard.lock), conditional logic alters execution if already locked.', '{macOS}', 'x-mitre-analytic--4ab12b3f-5c6a-42a6-8d9c-c10b7e814986', 'DET0132', '[{"name": "macos:unifiedlog", "channel": "flock|NSDistributedLock|FileHandle.*lockForWriting", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "macos:unifiedlog", "channel": "process.*exit.*code", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "lockfile_path", "description": "Path to mutex file (e.g., /tmp/*, /private/tmp/*), tune per environment."}, {"field": "user_context", "description": "Flag non-user processes using these APIs."}, {"field": "TimeWindow", "description": "Detection correlation across short time intervals between lock attempt and process exit."}]', '2026-05-01 15:26:35.142885');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (531, 'AN0444', 'Analytic 0444', 'Detects Kerberoasting attempts by monitoring for anomalous Kerberos TGS requests (Event ID 4769) with RC4 encryption (etype 0x17), accounts requesting an unusual number of service tickets in a short period, or service accounts targeted outside normal usage baselines. Also correlates suspicious process activity (e.g., Mimikatz invoking LSASS access) with Kerberos ticket anomalies.', '{Windows}', 'x-mitre-analytic--4ab972bf-623b-418b-9647-2c3a56b55083', 'DET0157', '[{"name": "WinEventLog:Security", "channel": "EventCode=4769", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "TGSRequestThreshold", "description": "Number of TGS requests per account within a defined window; higher than baseline may indicate Kerberoasting."}, {"field": "AllowedEncryptionTypes", "description": "Permitted Kerberos encryption algorithms; RC4 (etype 0x17) usage in modern environments is suspicious."}, {"field": "ServiceAccountBaselines", "description": "Expected SPNs requested by specific accounts; anomalies may indicate adversarial targeting."}, {"field": "TimeWindow", "description": "Correlation window for bursts of TGS requests; adjustable to reduce false positives."}]', '2026-05-01 15:26:35.144114');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (532, 'AN1152', 'Analytic 1152', 'Monitor VM-level DNS and network traffic logs for adversary-controlled domains or selective response behavior (e.g., dropped requests from security scanners).', '{ESXi}', 'x-mitre-analytic--4b16cb6e-7a81-4f97-a4ad-5e461e1cc154', 'DET0411', '[{"name": "esxi:vmkernel", "channel": "DNS lookups resolving to domains with rapid changes in registration metadata", "x_mitre_data_component_ref": "x-mitre-data-component--ff9b665a-598b-4bcb-8b2a-a87566aa1256"}, {"name": "esxi:vmkernel", "channel": "Suspicious traffic filtered or redirected by VM networking stack", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MonitoredVMs", "description": "Targeted virtual machines where adversaries may attempt to hide C2 traffic."}]', '2026-05-01 15:26:35.145358');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (533, 'AN1569', 'Analytic 1569', 'Detects abnormal HID device enumeration via I/O Registry (ioreg -p IOUSB) and keystroke injection targeting AppleScript, osascript, or PowerShell equivalents. Defender correlates new USB device connections with rapid script execution.', '{macOS}', 'x-mitre-analytic--4b47697b-ff9b-4af7-a079-d34210cebdab', 'DET0568', '[{"name": "macos:unifiedlog", "channel": "New IOUSB keyboard/HID device enumerated with suspicious attributes", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "macos:unifiedlog", "channel": "osascript, AppleScript, or Python execution triggered immediately after HID connection", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "AllowedAppleScripts", "description": "Whitelist of AppleScripts expected in the environment, to minimize false positives."}, {"field": "TimeWindow", "description": "Timeframe between HID injection and script execution considered suspicious."}]', '2026-05-01 15:26:35.146985');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (534, 'AN0280', 'Analytic 0280', 'Detects Lua script execution via native or 3rd party interpreters, chained with unsigned binaries or unexpected parent lineage.', '{macOS}', 'x-mitre-analytic--4b53b71f-16b4-483b-b64a-eacf6c9db077', 'DET0101', '[{"name": "macos:unifiedlog", "channel": "log stream", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ParentProcessName", "description": "Adjustable based on system activity patterns (e.g., Terminal vs GUI)"}, {"field": "SignatureStatus", "description": "Helps filter unsigned or self-signed Lua payloads."}]', '2026-05-01 15:26:35.148151');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (535, 'AN0440', 'Analytic 0440', 'Suspicious SaaS tenant activity involving webhook configurations pointing to external or untrusted domains. Defender perspective: repeated automated exports or suspicious webhook endpoint registrations.', '{SaaS}', 'x-mitre-analytic--4b72b349-f810-4e34-9185-b5550147147e', 'DET0153', '[{"name": "m365:unified", "channel": "Set-Mailbox, Add-InboxRule, RegisterWebhook", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:api", "channel": "Webhook registrations or repeated POST activity", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "WebhookRegistrations", "description": "Monitor new webhook creation events in SaaS environments."}, {"field": "ExternalDomains", "description": "Flag webhooks pointing to domains not owned by the enterprise."}]', '2026-05-01 15:26:35.14929');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (536, 'AN1949', 'Analytic 1949', 'Monitoring the content of network traffic can help detect patterns associated with active scanning activities. This can include identifying repeated connection attempts, unusual scanning behaviors, or probing activity targeting multiple IP addresses across a network.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (537, 'AN1979', 'Analytic 1979', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (538, 'AN0597', 'Analytic 0597', 'Outbound connections from non-network-facing processes repeatedly send similarly sized payloads within uniform time intervals.', '{Linux}', 'x-mitre-analytic--4baad14d-46b1-4e96-9e2a-138ae4e3ec75', 'DET0213', '[{"name": "auditd:SYSCALL", "channel": "connect/sendto", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Outbound Network Flow", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ProcessNetworkBaseline", "description": "Whitelist of typical binaries expected to generate outbound connections (e.g., wget, curl)"}, {"field": "PayloadLengthVariance", "description": "Deviation threshold to consider data ''fixed size'' (e.g., ±5% size delta)"}, {"field": "RepeatFrequencyThreshold", "description": "Number of observed transfers per minute/hour that signals anomalous repetition"}]', '2026-05-01 15:26:35.154394');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (539, 'AN0364', 'Analytic 0364', 'Domain account enumeration using ldapsearch, samba tools (e.g., ''wbinfo -u''), or winbindd lookups.', '{Linux}', 'x-mitre-analytic--4bad86cf-6cab-46f4-8748-28dc8c8ec81b', 'DET0129', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linuxsyslog", "channel": "nslcd or winbind logs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "LDAP Query", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ProcessName", "description": "Detect suspicious use of ldapsearch, wbinfo, getent passwd, or samba enumeration tools."}, {"field": "LDAPSearchFilter", "description": "Tune for high-volume or broad-scope LDAP queries."}, {"field": "UserContext", "description": "Apply filters for unexpected users or service accounts executing the behavior."}]', '2026-05-01 15:26:35.15597');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (540, 'AN1126', 'Analytic 1126', 'Creation or modification of `.plist` files in /Library/LaunchDaemons/, especially those with suspicious Program or ProgramArguments paths, combined with execution activity under launchd with elevated privileges. Detectable through correlated Unified Logs, file monitoring, and process telemetry.', '{macOS}', 'x-mitre-analytic--4bb5b68e-1a01-498e-ae39-94f951e01cd9', 'DET0401', '[{"name": "macos:unifiedlog", "channel": "launchd spawning processes tied to new or modified LaunchDaemon .plist entries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:launchdaemons", "channel": "file_create", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "fs:launchdaemons", "channel": "file_modify", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "launchd loading new LaunchDaemon or changes to existing daemon configuration", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "ProgramPathRegex", "description": "Regex patterns to match anomalous executable paths or names in .plist files"}, {"field": "TimeWindow", "description": "Correlation window between file modification and launchd process execution"}, {"field": "UserContext", "description": "Admin or root context used during daemon installation"}, {"field": "UnsignedBinaryFlag", "description": "Whether the binary associated with the LaunchDaemon is signed or trusted"}]', '2026-05-01 15:26:35.157669');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (541, 'AN0747', 'Analytic 0747', 'Detects adversarial archiving using libraries (zlib, zip APIs) invoked by scripts or binaries. Correlates process executions of Python, PowerShell, or custom .NET binaries with DLL/module loads linked to compression libraries, followed by archive file creation.', '{Windows}', 'x-mitre-analytic--4bdc0555-f7f0-4b5b-80c9-77f361881a01', 'DET0268', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "LibraryAllowlist", "description": "Known business applications using compression libraries."}, {"field": "SuspiciousExtensions", "description": "Archive extensions considered sensitive in monitored environments."}, {"field": "TimeWindow", "description": "Correlation window between script/library invocation and file creation."}]', '2026-05-01 15:26:35.159267');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (542, 'AN0691', 'Analytic 0691', 'CONTAINERS (Docker/K8s/containerd): A user pulls an untrusted image from a public/unknown registry and then creates/starts a container from that image. Shortly after start, the container spawns unexpected utilities (e.g., curl/wget/bash/python), or makes outbound network connections atypical for the namespace/workload. The analytic correlates Image Creation/Download → Container Creation → Container Start → Command Execution/Network activity within a short window and with a consistent image digest.', '{Linux}', 'x-mitre-analytic--4c16cebd-ac7e-472a-ae12-62966cbd19e2', 'DET0248', '[{"name": "containerd:events", "channel": "Image pull from untrusted registry (name NOT IN allowlist) or new digest never seen before", "x_mitre_data_component_ref": "x-mitre-data-component--b008766d-f34f-4ded-b712-659f59aaed6e"}, {"name": "kubernetes:audit", "channel": "create: Pod/Container created with image tag ''latest'' or mutable tag; imagePullPolicy=Always; noDigest=true", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"name": "kubernetes:events", "channel": "start: ContainerStarted or Pulling image → Started container", "x_mitre_data_component_ref": "x-mitre-data-component--5fe82895-28e5-4aac-845e-dc886b63be2e"}, {"name": "auditd:SYSCALL", "channel": "execve: Process in container namespace executes curl|wget|bash|sh|python|nc with outbound args", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "New egress from container IP/namespace to Internet or non-approved CIDRs/ASNs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ImageRegistryAllowList", "description": "Approved registries/namespaces (e.g., ECR/GCR/ACR org repos)."}, {"field": "TimeWindow", "description": "Correlation window from image pull to container activity (e.g., ≤15m)."}, {"field": "SuspiciousBinaries", "description": "Executables treated as high-risk when run in app containers (bash, sh, curl, wget, nc, powershell for Windows containers)."}, {"field": "NamespaceScope", "description": "K8s namespaces that should never pull from Internet or run mutable tags."}, {"field": "OutboundCIDRBlockList", "description": "Destination networks/domains that should not be contacted by containers."}]', '2026-05-01 15:26:35.160567');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (543, 'AN0878', 'Analytic 0878', 'Detects creation of traffic mirroring sessions (e.g., AWS VPC Traffic Mirroring, Azure vTAP) that redirect traffic from critical assets to other virtual instances, often followed by file creation or session establishment.', '{IaaS}', 'x-mitre-analytic--4c4941eb-b087-4710-8c88-ff537c2309ff', 'DET0314', '[{"name": "AWS:CloudTrail", "channel": "CreateTrafficMirrorSession / ModifyTrafficMirrorTarget", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "MirrorSourceList", "description": "Identify VMs or containers where mirror sessions are abnormal or unexpected."}, {"field": "TargetIAMRole", "description": "Monitor whether mirror target roles match administrative expectations."}]', '2026-05-01 15:26:35.162645');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (544, 'AN0694', 'Analytic 0694', 'Defenders observe command-line executions or API-based registry reads targeting sensitive paths like HKLM or HKCU with keyword filters such as ''password'', ''cred'', or ''logon''. Typically performed by Reg.exe, PowerShell, custom binaries, or offensive tools such as Cobalt Strike. Correlation with process ancestry and command-line arguments indicates suspicious credential discovery activity.', '{Windows}', 'x-mitre-analytic--4c744ac0-ba25-4b42-8397-9b398ba55eb8', 'DET0250', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "EDR:hunting", "channel": "Behavioral rule for registry enumeration under credential-related paths", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}]', '[{"field": "KeywordMatch", "description": "List of strings searched in registry queries (e.g., password, credential, login). May need to expand for localized OS or app-specific terms."}, {"field": "ParentProcessFilter", "description": "Parent process used for registry access. Can tune for suspicious ancestry (e.g., cmd.exe > reg.exe vs. services.exe > reg.exe)."}, {"field": "TimeWindow", "description": "Time-based correlation window for detecting chained activity between registry reads and subsequent credential use or exfiltration."}, {"field": "RegistryHiveScope", "description": "HKLM vs. HKCU vs. others. May limit scope to user or system context depending on risk appetite."}]', '2026-05-01 15:26:35.163882');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (545, 'AN0031', 'Analytic 0031', 'Outbound traffic with anomalous payload sizes and patterns from non-networking processes, often observed via packet inspection or connection logs.', '{Linux}', 'x-mitre-analytic--4c7d92bb-4b46-44e4-b070-43c46d3193c4', 'DET0011', '[{"name": "auditd:SYSCALL", "channel": "execve network tools", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "TCP session tracking", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "EntropyScore", "description": "Adjust based on expected entropy of typical outbound data."}, {"field": "ProcessWhitelist", "description": "Exclude known good binaries that generate high network output."}, {"field": "DataRatioThreshold", "description": "Minimum ratio of bytes_sent to bytes_received."}]', '2026-05-01 15:26:35.165232');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (546, 'AN0702', 'Analytic 0702', 'Monitor for anomalies in transmitted data streams, including mismatched file integrity checks, API interception, or man-in-the-middle modifications. Detect unexpected use of APIs that handle network I/O where transmitted data integrity could be manipulated.', '{Windows}', 'x-mitre-analytic--4cf44d48-1a0f-45a4-9a25-8bee9677ab52', 'DET0254', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "IntegrityBaseline", "description": "Hash baselines or digital signature references to validate transmitted data."}, {"field": "MonitoredPorts", "description": "List of ports/services where data integrity validation is enforced."}]', '2026-05-01 15:26:35.166367');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (547, 'AN0911', 'Analytic 0911', 'Execution of virtualization binaries (Parallels, VMware Fusion, VirtualBox) with arguments to hide UI. File monitoring for plist modifications indicating hidden virtualization behavior. Defender perspective: tracking process lineage and file modifications in system configs.', '{macOS}', 'x-mitre-analytic--4d76bcf2-0935-4f61-8dd9-57ee3713b840', 'DET0321', '[{"name": "macos:unifiedlog", "channel": "Process execution for VBoxHeadless, prl_vm_app, vmware-vmx", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Plist modifications containing virtualization run configurations", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "PlistKeyScope", "description": "Focus monitoring on UI suppression or VM auto-run keys."}]', '2026-05-01 15:26:35.167618');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (548, 'AN0354', 'Analytic 0354', 'Use of command-line like `ip ssh pubkey-chain` to bind SSH keys to privileged accounts on routers or switches.', '{"Network Devices"}', 'x-mitre-analytic--4d8e89c0-fbde-43fc-adc4-d2f50bec3193', 'DET0126', '[{"name": "networkdevice:cli", "channel": "ip ssh pubkey-chain", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CLIUserRole", "description": "Was the role allowed to push persistent config changes?"}, {"field": "DeviceModel", "description": "Variations in syntax or log behavior across device OS"}]', '2026-05-01 15:26:35.169015');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (549, 'AN0701', 'Analytic 0701', 'Detects the creation or modification of `.service` unit files in system/user-level directories, combined with execution of `systemctl`, `service`, or dynamically created drop-ins via systemd generators. Detects persistence by analyzing the `ExecStart` path, file entropy, and symlink usage, especially when paired with execution from `/tmp`, `/dev/shm`, or unmounted volumes.', '{Linux}', 'x-mitre-analytic--4da5660a-3b1c-4b4d-ad79-991bef456b20', 'DET0253', '[{"name": "auditd:SYSCALL", "channel": "write, open, or rename to /etc/systemd/system/*.service", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "modification of existing .service file", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execution of systemctl or service with enable/start parameters", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "fork/exec of service via PID 1 (systemd)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "newly registered unit file with ExecStart pointing to unknown binary", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "ServicePathRegex", "description": "Regex filters for systemd unit locations (e.g., `/etc/systemd/system/*.service`, `/lib/systemd/system/`)"}, {"field": "ExecStartPathAllowlist", "description": "Allowlist of trusted `ExecStart` binary paths (e.g., `/usr/bin/`, `/bin/`)"}, {"field": "UserContextFilter", "description": "List of usernames that are authorized to define user-level services"}, {"field": "FileEntropyThreshold", "description": "Entropy level of binaries referenced in `ExecStart` to detect packed or obfuscated payloads"}, {"field": "SystemctlOperationSet", "description": "Flags suspicious combinations such as `systemctl enable` + `systemctl start` within short interval"}]', '2026-05-01 15:26:35.170273');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (551, 'AN1014', 'Analytic 1014', 'Adversary tool/script issuing mass SYN/ACK floods that degrade OS responsiveness and interrupt service response on macOS endpoints.', '{macOS}', 'x-mitre-analytic--4db0f97c-a0c4-4c96-af56-86c6b227ea42', 'DET0356', '[{"name": "macos:unifiedlog", "channel": "network stack resource exhaustion, tcp_accept queue overflow, repeated resets", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "macos:osquery", "channel": "Execution of flooding tools or compiled packet generators", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Firewall", "channel": "Anomalous TCP SYN or ACK spikes from specific source or interface", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "SystemLoadThreshold", "description": "Observed CPU/network degradation level that triggers response"}, {"field": "ToolExecutionPath", "description": "Where DoS tools are commonly dropped or compiled"}]', '2026-05-01 15:26:35.173335');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (552, 'AN1986', 'Analytic 1986', 'Once adversaries have provisioned software on a compromised VPS (ex: for use as a command and control server), internet scans may reveal VPSs that adversaries have compromised. Consider looking for identifiable patterns such as services listening, certificates in use, SSL/TLS negotiation features, or other response artifacts associated with adversary C2 software.(Citation: ThreatConnect Infrastructure Dec 2020)(Citation: Mandiant SCANdalous Jul 2020)(Citation: Koczwara Beacon Hunting Sep 2021)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (553, 'AN1549', 'Analytic 1549', 'Adversary installs or abuses IDE extensions via CLI or direct write to profile directories and then communicates with marketplaces or remote tunnel services. Chain: auditd execve (code/idea/eclipse) with install/update flags or writes under ~/.vscode/extensions, ~/.config/JetBrains → outbound flows to *.visualstudio.com, marketplace.visualstudio.com, *.jetbrains.com, githubusercontent.com, or SSH/WebSocket tunnel endpoints → optional ssh/node processes spawned by IDE.', '{Linux}', 'x-mitre-analytic--4dff3c9a-4730-46de-af2f-dfa86b249167', 'DET0561', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open,creat,rename,write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Connections from IDE hosts to marketplace/tunnel domains", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "IDEPaths", "description": "Per-distro/profile extension directories differ; tune for Chromium/JetBrains snap/flatpak paths."}, {"field": "DomainAllowlist", "description": "Enterprise-approved repos and proxies to reduce FPs."}, {"field": "UserRoleScope", "description": "Limit to non-developer users or production servers."}, {"field": "TimeWindow", "description": "Join horizon across file, process, and network telemetry."}]', '2026-05-01 15:26:35.17661');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (554, 'AN0343', 'Analytic 0343', 'Detects mounted external devices (via /media or /mnt) followed by large file read or copy operations by shell scripts, unauthorized users, or staging tools (e.g., tar, rsync).', '{Linux}', 'x-mitre-analytic--4e288214-93b3-48a7-b51e-2b0136db8540', 'DET0123', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "device event logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "MountPointPattern", "description": "Monitor mount points like /media, /mnt, or /run/media."}, {"field": "UserGroupScope", "description": "Restrict detection to non-root or unexpected users."}, {"field": "AccessVolumeThreshold", "description": "Alert on large file access or copy events."}]', '2026-05-01 15:26:35.177814');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (555, 'AN0636', 'Analytic 0636', 'VM services or management daemons communicating on ports not defined by VMware defaults, such as vpxa or hostd processes initiating traffic over high-numbered or unexpected ports.', '{ESXi}', 'x-mitre-analytic--4e3afe58-e384-4b9e-9137-adaa0bac72af', 'DET0227', '[{"name": "esxi:vpxd", "channel": "ESXi service connections on unexpected ports", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "esxcli:network", "channel": "listening sockets bound to non-standard ports", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ESXiAllowedPorts", "description": "Default VMware service ports that should not be flagged."}]', '2026-05-01 15:26:35.180004');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (556, 'AN1994', 'Analytic 1994', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control.', '{PRE}', 'x-mitre-analytic--4e469a08-db8b-49c1-8bf6-f76ffa21860f', 'DET0862', NULL, NULL, '2026-05-01 15:26:35.181349');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (557, 'AN1235', 'Analytic 1235', 'Adversary uses built-in tools like ''net user /add'', PowerShell, or WMI to create a local user. Sequence: Account creation event (4720) follows process creation of a suspicious executable (e.g., powershell.exe or net.exe).', '{Windows}', 'x-mitre-analytic--4e4c318b-5da0-46f7-aed2-d37828e4831b', 'DET0447', '[{"name": "WinEventLog:Security", "channel": "EventCode=4720", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ParentProcessName", "description": "Attackers may use cmd.exe, wscript.exe, or renamed binaries to evade detection"}, {"field": "TimeWindow", "description": "Define time threshold between process start and user creation event (e.g., 5s–2m)"}, {"field": "UserContext", "description": "Correlate if process runs under SYSTEM, Administrator, or untrusted account"}]', '2026-05-01 15:26:35.182541');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (558, 'AN1389', 'Analytic 1389', 'Detects the execution of non-browser processes establishing outbound encrypted network connections using uncommon symmetric encryption protocols (e.g., AES via PowerShell or custom scripts) to alternate external destinations.', '{Windows}', 'x-mitre-analytic--4e5ffb58-75de-4305-a439-98ca3499f45e', 'DET0503', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PayloadEntropyThreshold", "description": "Flag high-entropy payloads sent over unexpected protocols."}, {"field": "TimeWindow", "description": "Define allowable transfer window (e.g., abnormal traffic outside business hours)."}, {"field": "ExecutableAllowlist", "description": "List of known-good binaries for encrypted traffic (e.g., Chrome, Outlook)."}]', '2026-05-01 15:26:35.183713');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (559, 'AN0787', 'Analytic 0787', 'Unexpected processes (e.g., powershell.exe, wscript.exe, office apps) initiating HTTP POST/PUT requests to text storage domains like pastebin.com or hastebin.com, particularly when preceded by file access in sensitive directories. Defender perspective: correlation of process lineage, large clipboard/file read operations, and outbound uploads to text storage services.', '{Windows}', 'x-mitre-analytic--4e8da615-4d12-4b53-8c7b-06d7c41e22a9', 'DET0284', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TextStorageDomains", "description": "Domains to monitor such as pastebin.com, hastebin.com, ghostbin.com."}, {"field": "UploadSizeThreshold", "description": "Minimum data size (e.g., >500KB) to trigger alerts for suspicious uploads."}, {"field": "UserContext", "description": "User accounts with legitimate business justification for posting to text storage sites."}]', '2026-05-01 15:26:35.185175');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (560, 'AN0091', 'Analytic 0091', 'Suspicious use of attrib.exe or PowerShell commands to set hidden attributes on files/directories. Defender view: processes modifying file attributes to ''hidden'' or creating files with ADS (alternate data streams).', '{Windows}', 'x-mitre-analytic--4ea80ec4-bfcc-4bd6-b986-aa2c9fe2d8d6', 'DET0032', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "MonitoredExtensions", "description": "Filter hidden file detection by sensitive file extensions (.exe, .dll, .bat)."}, {"field": "ADSMonitoring", "description": "Enable detection of alternate data streams depending on organizational usage."}]', '2026-05-01 15:26:35.186432');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (561, 'AN0953', 'Analytic 0953', 'Defenders can detect suspicious reversion of cloud compute instances by monitoring for unusual snapshot restores, rollback actions, or ephemeral storage resets that occur outside expected administrative workflows. From a defender’s perspective, relevant detection chains include: a snapshot restore triggered by a new or rarely used account, a sequence of snapshot creation immediately followed by a restore and instance start, or rollbacks performed from anomalous geographic or network locations. These patterns may indicate attempts to remove forensic evidence or re-establish a clean execution state for persistence.', '{IaaS}', 'x-mitre-analytic--4eaeffc2-bdfa-427c-a009-daadee39457d', 'DET0337', '[{"name": "AWS:CloudTrail", "channel": "RevertSnapshot", "x_mitre_data_component_ref": "x-mitre-data-component--45d0ff14-b9c4-41f5-8603-156657c20b75"}, {"name": "AWS:CloudTrail", "channel": "StartInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "AWS:CloudTrail", "channel": "StopInstances", "x_mitre_data_component_ref": "x-mitre-data-component--1361e324-b594-4c0e-a517-20cee32b8d7f"}]', '[{"field": "UserContext", "description": "Identity of the user or service account performing rollback actions; tuned to exclude automation or approved workflows."}, {"field": "TimeWindow", "description": "Threshold for correlating snapshot creation followed by reversion within minutes; tuned to environment activity norms."}, {"field": "GeoLocation", "description": "Region or source IP where the revert request originated; tuned to align with enterprise cloud geography."}, {"field": "ChangeTags", "description": "Use of administrative tags or headers to distinguish legitimate restores from malicious activity."}]', '2026-05-01 15:26:35.187644');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (562, 'AN1330', 'Analytic 1330', 'Internal user account accesses shared links outside org followed by mass file download', '{"Office Suite"}', 'x-mitre-analytic--4eca5ae6-797c-41cb-bacd-dc7a6da58fb0', 'DET0484', '[{"name": "m365:sharepoint", "channel": "AnonymousLinkCreated, FileDownloaded", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"name": "azure:signinlogs", "channel": "SigninSuccess", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "LinkVisibilityScope", "description": "Whether links allow anonymous/external access"}, {"field": "DownloadBurstThreshold", "description": "# of files downloaded within <5 mins (e.g., >50 files)"}]', '2026-05-01 15:26:35.188919');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (563, 'AN0749', 'Analytic 0749', 'Detects malicious archiving via system or third-party libraries (libz, libarchive) invoked by Python, Swift, or Objective-C binaries. Correlates unified logs of library loads with creation of compressed or encrypted archives (.zip, .gz, .bz2, .dmg).', '{macOS}', 'x-mitre-analytic--4ecd8727-bcf3-4fce-8c04-e8d0bad1267e', 'DET0268', '[{"name": "macos:unifiedlog", "channel": "Execution of Python, Swift, or other binaries invoking archiving libraries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Loading of libz.dylib, libarchive.dylib by non-standard applications", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "macos:unifiedlog", "channel": "Creation of .zip, .gz, .dmg archives in /Users, /tmp, or application directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AllowedProcesses", "description": "Applications allowed to load compression libraries (e.g., backup agents)."}, {"field": "UserContext", "description": "Flag archiving under privileged or system accounts as suspicious."}, {"field": "FileExtensionFilter", "description": "Targeted monitoring of sensitive file formats or compressed containers."}]', '2026-05-01 15:26:35.19057');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (565, 'AN0108', 'Analytic 0108', 'Executables written or modified in installer directories (e.g., %TEMP% subdirectories or Program Files installer paths) followed by execution under elevated context. Defender observes abnormal file replacement activity, process creation by installer processes pointing to attacker-supplied binaries, and unexpected module loads in elevated processes.', '{Windows}', 'x-mitre-analytic--4f132f21-1287-4fc2-a13e-d7770d856610', 'DET0038', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "MonitoredDirectories", "description": "Specific writable directories to monitor (e.g., %TEMP%, C:\\ProgramData, installer unpack paths)."}, {"field": "HashBaseline", "description": "Known good hashes of installer binaries to detect replacement."}, {"field": "TimeWindow", "description": "Correlation interval between file overwrite and execution event."}, {"field": "UserContext", "description": "Differentiate expected admin-installer execution vs. anomalous user writes."}]', '2026-05-01 15:26:35.193492');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (566, 'AN1309', 'Analytic 1309', 'Correlates creation of email forwarding rules or header anomalies (e.g., X-MS-Exchange-Organization-AutoForwarded) with suspicious process execution, file access of .pst/.ost files, and network connections to external SMTP servers.', '{Windows}', 'x-mitre-analytic--4f15b707-9b44-4716-bfcd-e3f28659077b', 'DET0476', '[{"name": "WinEventLog:Security", "channel": "EventCode=5145", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Application", "channel": "Exchange logs or header artifacts", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Defines correlation window across email rule creation and outbound SMTP."}, {"field": "UserContext", "description": "Filters for admin or service accounts to reduce false positives."}, {"field": "SMTPDomainList", "description": "Allows tuning based on expected external email domains."}]', '2026-05-01 15:26:35.195003');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (567, 'AN1292', 'Analytic 1292', 'Detects DHCP spoofing by monitoring unified logs for unexpected DHCP ACK/OFFER parameters and correlating with packet captures for multiple DHCP servers. Behavioral emphasis is on inconsistent DNS and gateway assignments that redirect traffic.', '{macOS}', 'x-mitre-analytic--4f2bc468-a57d-44e9-b9cd-d491df6b0daf', 'DET0468', '[{"name": "macos:unifiedlog", "channel": "new DHCP configuration with anomalous DNS or router values", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Multiple DHCP OFFER responses for a single DISCOVER", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "BaselineDNS", "description": "Expected DNS server list; deviations may indicate spoofing."}, {"field": "AlertSensitivity", "description": "Threshold for number of anomalous DHCP responses before alerting."}]', '2026-05-01 15:26:35.196667');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (568, 'AN1321', 'Analytic 1321', 'Detects tampering of IIS-based login pages (e.g., default.aspx, login.aspx) tied to VPN, OWA, or SharePoint via script injection or unexpected editor processes modifying web roots.', '{Windows}', 'x-mitre-analytic--4f33b538-1370-4df1-934f-fe3a609453fb', 'DET0480', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:iis", "channel": "IIS Logs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "FilePath", "description": "Define path to monitored IIS web root (e.g., C:\\inetpub\\wwwroot\\login.aspx)"}, {"field": "ProcessName", "description": "Exclude legitimate updates (e.g., msdeploy.exe) and alert on suspicious editors (e.g., notepad.exe, certutil.exe)"}]', '2026-05-01 15:26:35.197827');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (569, 'AN0973', 'Analytic 0973', 'Detects abuse of fileless storage mechanisms such as Registry keys, WMI classes, and Event Logs used to stage payloads, scripts, or encoded content outside traditional files.', '{Windows}', 'x-mitre-analytic--4f5f4b26-0bf0-4f3d-b8ac-1af660923bd2', 'DET0344', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Application", "channel": "WMI Object Creation Events", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}]', '[{"field": "RegistryPathFilter", "description": "Scoped to suspicious or abused paths like HKCU\\Software\\Classes\\ or HKLM\\SYSTEM\\CurrentControlSet\\Services\\"}, {"field": "PayloadEntropyThreshold", "description": "Minimum entropy level to flag suspicious registry or WMI content as encoded payloads"}, {"field": "TimeWindow", "description": "Temporal window for correlating WMI/registry modifications with process creation or network usage"}]', '2026-05-01 15:26:35.199086');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (570, 'AN1071', 'Analytic 1071', 'Adversaries using bash scripts or tools to recursively enumerate user home directories, config files, or SSH keys.', '{Linux}', 'x-mitre-analytic--4f5f64b3-bc1b-4573-b790-42b8adfdd609', 'DET0380', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Time span to correlate multiple file access events indicative of scripted or bulk access."}, {"field": "ScriptToolName", "description": "List of tools (e.g., `find`, `grep`, `tar`, `scp`) that may be benign but are context-sensitive."}]', '2026-05-01 15:26:35.200458');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (817, 'AN0685', 'Analytic 0685', 'Monitor Facetime, iMessage, or SIP client logs for anomalous voice call attempts. Link to subsequent user execution events (downloads, RMM installs) triggered post-call.', '{macOS}', 'x-mitre-analytic--756214e0-660d-4f32-a4f1-f8ff24a7852f', 'DET0245', '[{"name": "macos:unifiedlog", "channel": "Outgoing or incoming calls with non-standard caller IDs or unusual metadata", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "CallerIDPatterns", "description": "Patterns of spoofed caller IDs that must be tuned based on region and telecom provider"}, {"field": "PayloadCorrelation", "description": "Define what follow-on events (browser downloads, execution) to correlate with call logs"}]', '2026-05-01 15:26:35.571655');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (571, 'AN0457', 'Analytic 0457', 'Chain: (1) execution of `pwpolicy` or MDM/DirectoryService reads of account policies; (2) optional read of `/Library/Preferences/com.apple.loginwindow` or config profiles; (3) follow-on credential probing or lateral movement by same user/session. Use unified logs and process telemetry.', '{macOS}', 'x-mitre-analytic--4f71c7bd-dd25-43c7-ac5c-7a85c7588759', 'DET0161', '[{"name": "macos:unifiedlog", "channel": "pwpolicy|PasswordPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "exec /usr/bin/pwpolicy", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:MDM", "channel": "profiles -P|getaccountpolicies", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "MDMProfileIDs", "description": "Approved profiles reading/updating auth policies."}, {"field": "AdminConsoleHosts", "description": "Jamf or management hosts where queries are expected."}]', '2026-05-01 15:26:35.201667');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (572, 'AN0237', 'Analytic 0237', 'Detection of processes that load or decode encrypted/encoded files in memory and subsequently execute or inject them, indicating payload unpacking or memory-resident malware.', '{Windows}', 'x-mitre-analytic--4f985435-9144-4a8f-aca0-598f788855b7', 'DET0087', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "Image", "description": "Path of decoder utilities (e.g., certutil.exe, powershell.exe) can vary across environments."}, {"field": "CommandLine", "description": "Base64/hex strings used may change per encoded payload."}, {"field": "TimeWindow", "description": "The duration between file decode and execution may differ across implementations."}]', '2026-05-01 15:26:35.202858');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (573, 'AN0703', 'Analytic 0703', 'Detect alterations of transmitted data via monitoring syscalls (`send`, `recv`, `write`) or middleware interception. Identify mismatched file hashes when compared at origin vs. destination. Watch for anomalous activity from processes interacting with secure transmission services (e.g., OpenSSL, scp).', '{Linux}', 'x-mitre-analytic--500ae9f9-c6c2-4160-ac03-072d963eba63', 'DET0254', '[{"name": "auditd:SYSCALL", "channel": "send, recv, write: Abnormal interception or alteration of transmitted data", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "linux:syslog", "channel": "Integrity mismatch warnings or malformed packets detected", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "WatchedProcesses", "description": "List of processes authorized to handle transmitted data (e.g., sshd, nginx)."}, {"field": "HashCheckInterval", "description": "Frequency of out-of-band integrity verification checks."}]', '2026-05-01 15:26:35.204139');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (574, 'AN0403', 'Analytic 0403', 'ESXi daemons (hostd, vpxa) unexpectedly using symmetric encryption routines for external connections. Defender identifies logs of service traffic with encrypted payloads inconsistent with VMware management baselines.', '{ESXi}', 'x-mitre-analytic--50102ced-9c8f-47e6-b438-63b2a7fe983d', 'DET0143', '[{"name": "esxi:vpxd", "channel": "Symmetric crypto routines triggered for external session", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "esxcli:network", "channel": "Socket sessions with randomized payloads inconsistent with TLS", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AllowedMgmtHosts", "description": "Baseline list of approved vCenter and update endpoints."}]', '2026-05-01 15:26:35.20649');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (575, 'AN1572', 'Analytic 1572', 'Processes such as curl, wget, rclone, or custom scripts executing uploads to cloud storage endpoints. Defender perspective: detect chained events where tar/gzip is executed to compress files followed by HTTPS PUT/POST requests to known storage services.', '{Linux}', 'x-mitre-analytic--5012d2b2-bd36-431c-91d3-4c10b7d3a9d6', 'DET0570', '[{"name": "auditd:EXECVE", "channel": "curl -T, rclone copy", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "read/open of sensitive file directories", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "large HTTPS outbound uploads", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AllowedTools", "description": "Known tools used legitimately for backups (rclone, gsutil). Deviations raise suspicion."}, {"field": "WorkHours", "description": "Baseline normal data transfer hours to reduce false positives."}]', '2026-05-01 15:26:35.208072');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (576, 'AN0629', 'Analytic 0629', 'Unauthorized creation or modification of DLLs loaded by LSASS, abnormal registry values under LSA extensions, and anomalous DLL load activity into the lsass.exe process context—correlated during boot or logon events.', '{Windows}', 'x-mitre-analytic--5028303d-22d6-490c-b053-015e877d5829', 'DET0225', '[{"name": "WinEventLog:Security", "channel": "EventCode=3033", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TimeWindow", "description": "Correlate DLL file creation/modification with LSASS execution within a configurable timeframe (e.g., 5 min)"}, {"field": "ImagePathPattern", "description": "Tune based on known legitimate LSASS plugin DLL paths"}, {"field": "SignatureValidation", "description": "Flag unsigned DLLs loaded into lsass.exe or those signed by unexpected publishers"}, {"field": "RegistryKeyScope", "description": "Scope to specific registry keys: HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Authentication Packages"}, {"field": "FileHashAllowList", "description": "Exclude known-good LSASS plugin DLLs based on cryptographic hash"}]', '2026-05-01 15:26:35.209655');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1024, 'AN0960', 'Analytic 0960', 'Use of instance metadata tokens across instances or misuse of short-lived tokens issued for different roles.', '{IaaS}', 'x-mitre-analytic--91681b37-7fc7-418c-b4fd-35bebe1d151e', 'DET0338', '[{"name": "AWS:CloudTrail", "channel": "GetCallerIdentity", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "AWS:CloudTrail", "channel": "AssumeRole", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "TokenReuseWindow", "description": "Time window where token reuse is suspicious"}, {"field": "RoleMismatchAlerting", "description": "Enable if tokens for RoleA are used in resources only RoleB should access"}]', '2026-05-01 15:26:35.892619');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (577, 'AN0785', 'Analytic 0785', 'Detection focuses on identifying anomalous regsvr32.exe executions that deviate from normal administrative or system use. Defenders may observe regsvr32.exe loading scriptlets or DLLs from unusual paths (especially temporary directories or remote URLs), command-line arguments invoking /i or /u with suspicious file references, network connections initiated by regsvr32.exe, and unsigned or untrusted DLLs being loaded shortly after regsvr32.exe invocation. Correlated sequences include regsvr32.exe process creation, module load of DLL/scriptlet, and optional outbound network traffic.', '{Windows}', 'x-mitre-analytic--50658b7e-57c5-4e31-b156-1b294574a9f2', 'DET0282', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AllowedDLLPaths", "description": "Directories where DLL loading via regsvr32.exe is expected (e.g., C:\\Windows\\System32)."}, {"field": "ScriptletExtensions", "description": "File extensions considered suspicious when executed by regsvr32.exe (e.g., .sct, .ocx)."}, {"field": "TimeWindow", "description": "Timeframe to correlate regsvr32.exe process creation with subsequent module loads and network connections."}, {"field": "ParentProcessWhitelist", "description": "Parent processes from which regsvr32.exe is expected (e.g., explorer.exe during legitimate COM object registration)."}]', '2026-05-01 15:26:35.211186');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (578, 'AN2002', 'Analytic 2002', 'Consider monitoring social media activity related to your organization. Suspicious activity may include personas claiming to work for your organization or recently modified accounts making numerous connection requests to accounts affiliated with your organization.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (579, 'AN0324', 'Analytic 0324', 'Creation or modification of Windows services or scheduled tasks with names or descriptions mimicking legitimate entries, followed by anomalous execution of untrusted binaries or LOLBAS.', '{Windows}', 'x-mitre-analytic--51a23f35-4a11-4119-935a-1ffebcda2839', 'DET0117', '[{"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Security", "channel": "EventCode=4698", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TaskNameSimilarityThreshold", "description": "Similarity threshold for comparing new task/service names to known legitimate names (e.g., Levenshtein distance)"}, {"field": "BinaryReputationScore", "description": "Confidence level required for allowing a binary, often from unsigned or untrusted source"}, {"field": "ExecutionContext", "description": "Whether the execution came from SYSTEM, service accounts, or user contexts"}]', '2026-05-01 15:26:35.213896');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (580, 'AN1320', 'Analytic 1320', 'Detects unauthorized modifications to login-facing web server files (e.g., index.php, login.js) typically tied to VPN, SSO, or intranet portals. Correlates suspicious file changes with remote access artifacts or web shell behavior.', '{Linux}', 'x-mitre-analytic--5233d621-6658-4338-b183-01bd73e52861', 'DET0480', '[{"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Flow", "channel": "HTTP Request Logging", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MonitoredFilePaths", "description": "Target login-related files (e.g., /var/www/html/login.php) for integrity monitoring"}, {"field": "TimeWindow", "description": "Tune detection to correlate file edits and web access within a short duration"}]', '2026-05-01 15:26:35.215181');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (581, 'AN0136', 'Analytic 0136', 'Detects firewall rule modifications or reset of logs/connection tables (e.g., `clear logging`, `erase startup-config`, `write erase`) following remote access activity on routers, switches, or VPN appliances.', '{"Network Devices"}', 'x-mitre-analytic--5258feec-def7-43e0-bbe9-459ba53d3e28', 'DET0049', '[{"name": "networkdevice:syslog", "channel": "Command Audit / Configuration Change", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "Session History Reset", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CommandPattern", "description": "e.g., `clear logging`, `no logging buffered`, `no ip domain-lookup`"}, {"field": "DeviceTypeFilter", "description": "Switches vs VPN vs routers"}]', '2026-05-01 15:26:35.216359');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (582, 'AN0054', 'Analytic 0054', 'A process loads a non-system .dylib/.so via dyld (dlopen/dlsym) from user-writable locations (~/Library, /tmp) or after the library was recently created/downloaded, often followed by network egress or persistence.', '{macOS}', 'x-mitre-analytic--52a5dffb-f3a3-45fc-97b3-2c09fed8e0b4', 'DET0018', '[{"name": "macos:unifiedlog", "channel": "dyld/unified log entries indicating image load from non-system paths", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "macos:endpointsecurity", "channel": "exec: Process execution context for loaders calling dlopen/dlsym", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_OPEN: Open of .dylib/.so in user-writable locations", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "SuspiciousDirs", "description": "~/Library, /tmp, /Users/*/.* (hidden dirs) – tune to enterprise layout."}, {"field": "UnsignedOnly", "description": "Alert only when code-signing is invalid or absent."}, {"field": "TimeWindow", "description": "Correlate write/open to module load within N minutes."}]', '2026-05-01 15:26:35.217558');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (583, 'AN1538', 'Analytic 1538', 'Correlate process execution of shutdown/reboot commands (e.g., shutdown.exe, restart-computer) with host status change logs (Event IDs 1074, 6006) and absence of related administrative context (e.g., user not in Helpdesk group).', '{Windows}', 'x-mitre-analytic--52b9bf67-304e-403f-9b81-4d4b9d974ad6', 'DET0559', '[{"name": "WinEventLog:Security", "channel": "EventCode=1074", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Defines if user has appropriate privileges to initiate shutdown/reboot."}, {"field": "TimeWindow", "description": "Unexpected shutdowns during business hours may warrant increased scrutiny."}]', '2026-05-01 15:26:35.218827');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (584, 'AN0056', 'Analytic 0056', 'Executable or binary files created without symbol tables or with stripped sections, especially by non-user shell processes or compilers invoked outside standard dev paths.', '{Linux}', 'x-mitre-analytic--52d150da-36f4-43b4-96c4-b4fe33b012a2', 'DET0019', '[{"name": "auditd:EXECVE", "channel": "EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:osquery", "channel": "hash, elf_info, file_metadata", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "StripFlags", "description": "Flag combinations in compiled binaries indicating symbol table removal"}, {"field": "DirectoryScope", "description": "Whitelist compiler output directories to reduce false positives"}, {"field": "FileSizeRange", "description": "Heuristic boundaries for abnormal small or overly large stripped binaries"}]', '2026-05-01 15:26:35.22018');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (585, 'AN1521', 'Analytic 1521', 'Series of authentication failures (Event ID 4625) targeting the same or similar user accounts over time from one or more remote IPs', '{Windows}', 'x-mitre-analytic--52dfd8de-910a-4caa-98a7-6dcf44ef903e', 'DET0551', '[{"name": "WinEventLog:Security", "channel": "EventCode=4625", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Defines the period in which multiple failed attempts are aggregated (e.g., 10 minutes)"}, {"field": "UsernamePattern", "description": "Filter for common account naming conventions, e.g., service accounts or administrator variants"}, {"field": "SourceIPThreshold", "description": "Limit on unique IPs trying to authenticate against a single account"}]', '2026-05-01 15:26:35.221385');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (586, 'AN1578', 'Analytic 1578', 'Detects creation of new container system processes via `docker run --restart`, `kubectl exec` to init containers, or modification of container init specs. Flags container images that override entrypoints to embed persistence behaviors.', '{Containers}', 'x-mitre-analytic--52ee5593-7db2-4ad0-b5f4-630ebcf2ce0f', 'DET0571', '[{"name": "docker:events", "channel": "docker run with restart=always or modifying init", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"name": "auditd:SYSCALL", "channel": "modification of entrypoint scripts or init containers", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "EntrypointOverridePattern", "description": "Patterns used to detect modified container start scripts"}, {"field": "RestartPolicyMatch", "description": "Policy values triggering alert (e.g., always, on-failure)"}, {"field": "KubeInitModPath", "description": "Path filters for `/etc/init.d/`-like behaviors inside containers"}]', '2026-05-01 15:26:35.222826');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (587, 'AN1083', 'Analytic 1083', 'Detects BusyBox or Ash shell execution from unauthorized logins or remote connections. Focus is on rare shell invocations from DCUI, SSH sessions, or remote management paths. Also watches for payload droppers or persistence artifacts using shell.', '{ESXi}', 'x-mitre-analytic--52f4a572-0d43-4684-9598-6bc8cf2bffb1', 'DET0384', '[{"name": "esxi:vmkernel", "channel": "DCUI shell start, BusyBox activity", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:auth", "channel": "Shell login or escalation", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "UserContext", "description": "Non-root use of shell (or root outside maintenance window)."}, {"field": "CommandPattern", "description": "Use of ‘nc’, ‘wget’, or dropper-like behavior in shell."}, {"field": "ShellPath", "description": "Unexpected invocation of BusyBox/ash from mounted ISO or datastore."}]', '2026-05-01 15:26:35.224562');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (588, 'AN1411', 'Analytic 1411', 'Adversary mounts external drive to /media or /mnt then accesses or copies targeted data via shell, cp, or tar.', '{Linux}', 'x-mitre-analytic--5312ddd0-dd58-4bcb-afc0-7a05a6b2df42', 'DET0511', '[{"name": "auditd:SYSCALL", "channel": "open, read, mount", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "journald:systemd", "channel": "udisks2 or udevd logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MountPathRegex", "description": "Filter for unexpected or user-defined mount locations (e.g., /media/usb*)"}, {"field": "AccessMask", "description": "Tune based on read/write access types seen during collection"}]', '2026-05-01 15:26:35.226049');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (589, 'AN0402', 'Analytic 0402', 'Launchd jobs or user processes invoking symmetric crypto APIs from the Security framework and generating outbound connections carrying randomized payloads inconsistent with normal TLS patterns.', '{macOS}', 'x-mitre-analytic--531ba452-e3b8-4064-be28-31ddd13b3478', 'DET0143', '[{"name": "macos:unifiedlog", "channel": "Process using AES/RC4 routines unexpectedly", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Encrypted connection with anomalous payload entropy", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "DoHResolvers", "description": "Legitimate DNS-over-HTTPS endpoints to avoid FP."}, {"field": "PayloadEntropyThreshold", "description": "Define entropy level at which traffic should be flagged."}]', '2026-05-01 15:26:35.227319');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (590, 'AN1523', 'Analytic 1523', 'Series of failed logins from loginwindow or sshd with repeated usernames or password prompts', '{macOS}', 'x-mitre-analytic--53336c8f-a218-462a-b97c-aac07cf96077', 'DET0551', '[{"name": "macos:unifiedlog", "channel": "authd", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AuthMechanism", "description": "Local console vs. SSH vs. remote Apple Admin tools"}, {"field": "FailurePattern", "description": "Use regex to isolate brute force messages among other log noise"}]', '2026-05-01 15:26:35.228497');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (592, 'AN1573', 'Analytic 1573', 'Applications or scripts invoking cloud storage APIs (Dropbox sync, iCloud, Google Drive client) in unexpected contexts. Defender perspective: detect sensitive file reads by non-standard applications followed by unusual encrypted uploads to external cloud storage domains.', '{macOS}', 'x-mitre-analytic--535e9bc8-b033-4aee-88e1-bd48699b7856', 'DET0570', '[{"name": "macos:unifiedlog", "channel": "execution of curl, rclone, or Office apps invoking network sessions", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "file read of sensitive directories", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "outbound HTTPS connections to cloud storage APIs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "WatchedApps", "description": "Track processes that normally should not upload data (e.g., Preview, Calculator)."}, {"field": "EntropyThreshold", "description": "High-entropy file uploads may indicate encrypted payloads designed for exfiltration."}]', '2026-05-01 15:26:35.232363');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (593, 'AN0828', 'Analytic 0828', 'Execution of utilities (dd, hdparm, sgdisk) or custom binaries attempting to overwrite disk boot structures (/dev/sda MBR sector or partition tables). Detection correlates shell execution with syscalls writing to sector 0 or disk metadata blocks.', '{Linux}', 'x-mitre-analytic--538707d4-df45-489b-97f5-0115802a701f', 'DET0297', '[{"name": "auditd:SYSCALL", "channel": "write syscalls to /dev/sd* targeting offset 0", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"name": "auditd:EXECVE", "channel": "Execution of dd/sgdisk with arguments writing to sector 0 or partition table", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetDevices", "description": "Define specific device paths to monitor (e.g., /dev/sda, /dev/nvme0n1)."}, {"field": "OffsetThreshold", "description": "Focus on suspicious writes at disk offsets corresponding to MBR/partition structures."}]', '2026-05-01 15:26:35.233733');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (594, 'AN0902', 'Analytic 0902', 'Adversaries leverage M365 or Google Workspace APIs to create users, service accounts, or guest accounts. Follow-on behaviors include login activity, role escalation, or service principal token generation.', '{"Office Suite"}', 'x-mitre-analytic--53872bd3-7e5e-4573-ae07-6304bf7e49af', 'DET0319', '[{"name": "m365:unified", "channel": "Add user", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "m365:unified", "channel": "Add member to group", "x_mitre_data_component_ref": "x-mitre-data-component--05d5b5b4-ef93-4807-b05f-33d8c5a35bc5"}]', '[{"field": "GroupSensitivity", "description": "Only alert on additions to high-value groups (e.g., Domain Admins)"}, {"field": "GuestFlag", "description": "Tune alerts based on guest vs internal user creation"}]', '2026-05-01 15:26:35.23501');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (595, 'AN1548', 'Analytic 1548', 'Adversary installs or side-loads an IDE extension (VS Code, IntelliJ/JetBrains, Eclipse) or enables IDE tunneling. Chain: (1) IDE binary starts on a non-developer endpoint or server, often with install/force/tunnel flags → (2) extension files/registrations appear under user profile → (3) browser/IDE initiates outbound connections to extension marketplaces, update endpoints, or IDE remote/tunnel services → (4) optional child tools (ssh, node, powershell) execute under the IDE context.', '{Windows}', 'x-mitre-analytic--539a4182-ab9e-4abf-a83b-f30cf2dec770', 'DET0561', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "IDEList", "description": "Executable names/paths (e.g., code.exe, idea64.exe, eclipse.exe, jetbrains-gateway.exe) vary by version and packaging."}, {"field": "SuspiciousCLI", "description": "Flags such as --install-extension, --force, --disable-extensions, --user-data-dir, --uninstall-extension, tunnel/remote flags are tunable."}, {"field": "ServerZones", "description": "List of hosts where IDEs should never run (prod servers, DCs)."}, {"field": "AllowedHosts", "description": "Approved extension marketplaces/ide services; use to suppress benign traffic."}, {"field": "TimeWindow", "description": "Correlation horizon (e.g., 15–30m) between process start, file writes, and outbound IDE/tunnel connections."}]', '2026-05-01 15:26:35.236259');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (596, 'AN0639', 'Analytic 0639', 'Initial process using NSURLSession or similar APIs reaches out to known staging domains, followed by creation of a reverse shell or RAT connecting to a second unrelated server.', '{macOS}', 'x-mitre-analytic--53ba6028-13cd-449e-aab4-d2f9fea458a4', 'DET0228', '[{"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "tcp/udp", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "UserContext", "description": "Detect activity outside normal user behavior (e.g., automation or daemon context)"}, {"field": "EntropyScore", "description": "Optional for detecting encoded payloads delivered via stage 1"}]', '2026-05-01 15:26:35.237716');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (597, 'AN1034', 'Analytic 1034', 'Correlates Group Policy updates that configure network logon scripts with subsequent remote file execution behaviors triggered by user logons to identify potential persistence or execution chains tied to adversarial manipulation of logon scripts.', '{Windows}', 'x-mitre-analytic--53dd199d-4f38-4f12-83dd-f2d471d58a1b', 'DET0367', '[{"name": "WinEventLog:Security", "channel": "EventCode=5145", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:System", "channel": "EventCode=4016, 5312", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "TargetObject", "description": "Path to network-based script execution; tuning required for environment-specific network shares."}, {"field": "ParentProcessName", "description": "Initial execution process that launches the script; may vary depending on script language or user context."}, {"field": "TimeWindow", "description": "Acceptable time window to correlate Group Policy update with script execution (e.g., 2–10 minutes)."}, {"field": "UserContext", "description": "Account initiating execution; useful for filtering known administrative activity."}]', '2026-05-01 15:26:35.239105');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (598, 'AN1401', 'Analytic 1401', 'Detects memory-based injection by monitoring `task_for_pid`, `mach_vm_write`, and dylib injection patterns through `DYLD_INSERT_LIBRARIES` or manual memory mapping.', '{macOS}', 'x-mitre-analytic--5439d083-91d6-4369-9406-8cfb2cf5cbde', 'DET0508', '[{"name": "macos:unifiedlog", "channel": "subsystem=com.apple.security, library=libsystem_kernel.dylib", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC, ES_EVENT_TYPE_NOTIFY_MMAP", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "macos:syslog", "channel": "DYLD_INSERT_LIBRARIES anomalies", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TargetProcessSignature", "description": "Expected signing identity or origin of process being injected"}, {"field": "MachSyscallContext", "description": "Observed syscall combinations (e.g., task_for_pid followed by vm_write)"}]', '2026-05-01 15:26:35.240848');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (599, 'AN0680', 'Analytic 0680', 'Unusual or excessive database/table exports from SaaS database platforms (e.g., Snowflake, Firebase, BigQuery, Airtable) by users or apps not in known analytics or dev groups. Defender observes access patterns outside baseline working hours or with new query templates, and correlates those with audit logs or file downloads.', '{SaaS}', 'x-mitre-analytic--544c832f-4849-4fb7-a851-5f69ec0692a9', 'DET0242', '[{"name": "saas:Snowflake", "channel": "QUERY: Large or repeated SELECT * queries to sensitive tables", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:unified", "channel": "Bulk downloads or API extractions from Microsoft-hosted data repositories (e.g., Dynamics 365)", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "BaselineQueryTemplates", "description": "Query hash or shape for common BI/ETL jobs to reduce false positives"}, {"field": "OffHoursAccessWindow", "description": "Window to define after-hours activity thresholds for DB access"}]', '2026-05-01 15:26:35.242471');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (600, 'AN0697', 'Analytic 0697', 'Monitors API calls and service-specific logs for enumeration of organizational roles, permissions, and group structure, particularly outside of normal admin behavior baselines.', '{SaaS}', 'x-mitre-analytic--54ae99be-c089-4e96-97f5-52af2892ae25', 'DET0251', '[{"name": "saas:salesforce", "channel": "GET /services/data/vXX.X/groups", "x_mitre_data_component_ref": "x-mitre-data-component--8e44412e-3238-4d64-8878-4f11e27784fe"}]', '[{"field": "OrgScope", "description": "Scope to cross-team access or unfamiliar org enumeration."}, {"field": "RequestRate", "description": "Tuning for excessive group-list API calls."}]', '2026-05-01 15:26:35.243803');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (601, 'AN2037', 'Analytic 2037', 'Detects users executing commands copied from chats, tickets, or emails, including curl|bash patterns, shell script launches from temp directories, credential changes, or SSH key additions shortly after communication events.', '{Linux}', 'x-mitre-analytic--54bb8256-cbe8-4088-9cff-b03711bd7841', 'DET0899', '[{"name": "NSM:Connections", "channel": "Outbound connection after script or installer launch", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "auditd:EXECVE", "channel": "execve of curl,wget,bash,sh,python with piped or remote content", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:PATH", "channel": "odification of ~/.ssh/authorized_keys or credential files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "RemoteScriptExecutionPatterns", "description": "Organization-specific admin automation patterns to exclude"}, {"field": "TicketToExecutionWindow", "description": "Time from help desk/chat event to command execution"}]', '2026-05-01 15:26:35.244964');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (602, 'AN1452', 'Analytic 1452', 'Detection of processes executing system environment inspection operations followed by access to OS configuration APIs or registry locations that expose OS version, architecture, patch level, or hardware characteristics. Defenders observe process execution retrieving system configuration metadata immediately after process startup.', '{Windows}', 'x-mitre-analytic--54bfcc92-e04c-4eac-9aa2-c10b7574088c', 'DET0525', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TimeWindow", "description": "Detect multiple discovery commands executed in short succession."}, {"field": "UserContext", "description": "Scope alerts to unusual user accounts or service accounts."}]', '2026-05-01 15:26:35.246148');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (603, 'AN0996', 'Analytic 0996', 'Monitors execution of older or legacy interpreters (e.g., python2, bash with restricted history logging), downgrade of TLS/SSL configurations, or forced fallback to unencrypted protocols. Detects suspicious reconfiguration of kernel modules or boot loaders to reduce integrity controls.', '{Linux}', 'x-mitre-analytic--54eb86ed-2a72-41a8-b060-2750c2fee758', 'DET0350', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of downgraded interpreters such as python2 or forced fallback commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:syslog", "channel": "Kernel or daemon warnings of downgraded TLS or cryptographic settings", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "AllowedCryptoProtocols", "description": "List of TLS/SSL versions approved for use; alerts triggered if older protocols (e.g., TLS 1.0) are used."}]', '2026-05-01 15:26:35.247561');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (610, 'AN0127', 'Analytic 0127', 'Execution of discovery commands or API calls for virtualization artifacts (e.g., registry keys, device drivers, services), sleep/skipped execution behavior, or sandbox evasion DLLs before payload deployment.', '{Windows}', 'x-mitre-analytic--55808d73-7aa9-4f2c-8122-8e60bf14f4c6', 'DET0046', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TimeWindow", "description": "Time range in which multiple discovery processes or sleep/delay operations are executed to avoid sandbox detonation."}, {"field": "KnownVMArtifactList", "description": "Registry paths, DLLs, services or device names indicative of sandbox/VM environments."}]', '2026-05-01 15:26:35.258195');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (604, 'AN1000', 'Analytic 1000', 'Detects unauthorized Kerberos ticket injection by correlating service ticket (TGS - 4769) requests with absent corresponding account logons (4624) and prior Ticket Granting Ticket (TGT - 4768) activity. Highlights anomalous service ticket generation chains involving unexpected users, hosts, or times, and suspicious injection of tickets via mimikatz-like tooling into LSASS memory. Behavior also includes network lateral movement using Kerberos authentication absent expected interactive logon patterns.', '{Windows}', 'x-mitre-analytic--54ffc701-eb6c-4e3e-8615-0c6f8b327a34', 'DET0352', '[{"name": "WinEventLog:Security", "channel": "EventCode=4769", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "WinEventLog:Security", "channel": "EventCode=4768", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TimeWindow", "description": "Defines the correlation window between TGT request (4768) and TGS request (4769)"}, {"field": "HostContextScope", "description": "Adjusts the host scoping for correlation of authentication chains and ticket injection"}, {"field": "LSASSAccessAnomalyThreshold", "description": "Allows tuning of alerts for ticket injection attempts via LSASS memory access"}]', '2026-05-01 15:26:35.249889');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (605, 'AN0783', 'Analytic 0783', 'Detects sequential command-line compression utilities (e.g., gzip, tar, zip, 7z) followed by execution of unpacked files, especially in temp directories or under non-standard locations like /dev/shm or /tmp with ELF binaries.', '{Linux}', 'x-mitre-analytic--55083ce8-b00e-4501-97db-829082bdbb48', 'DET0281', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "openat", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "chmod", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "PathRegex", "description": "Flag compressed archives extracted to /tmp, /dev/shm, or user’s home dir"}, {"field": "CompressionToolPatterns", "description": "gzip, tar, bzip2, xz, 7z – tune to suppress admin packaging workflows"}, {"field": "ExecutionAfterUnpackWindow", "description": "How soon a new file is executed after it’s unpacked"}]', '2026-05-01 15:26:35.251155');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (606, 'AN1529', 'Analytic 1529', 'Detects abnormal creation of binary files with significant size that are subsequently executed or accessed by non-standard users.', '{Linux}', 'x-mitre-analytic--5523b4ab-42b1-480a-854b-819879905f8d', 'DET0553', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "FileSizeThresholdMB", "description": "Defines how large a file must be to consider it padded"}, {"field": "UserContext", "description": "Target abnormal user behavior outside of expected automation"}, {"field": "TimeWindow", "description": "Time window for correlating file creation and execution"}]', '2026-05-01 15:26:35.252317');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (607, 'AN1466', 'Analytic 1466', 'Userland processes invoking syscall-heavy libraries (libc, glibc) followed by fork, mmap, or ptrace behavior commonly associated with code injection or memory manipulation.', '{Linux}', 'x-mitre-analytic--552ff82d-467b-4aeb-a4c3-084ca24dbd3e', 'DET0529', '[{"name": "auditd:SYSCALL", "channel": "execve, fork, mmap, ptrace", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "auditd:SYSCALL", "channel": "module load or memory map path", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "SyscallType", "description": "Filter for fork, mmap, ptrace based on context"}, {"field": "ProcessName", "description": "Whitelist known daemon and scheduled task patterns"}, {"field": "MAPS Path", "description": "Tune suspicious memory map regions (e.g., /tmp/.evilshmem)"}]', '2026-05-01 15:26:35.253535');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (608, 'AN0272', 'Analytic 0272', 'Scripted or binary usage of X11 utilities (e.g., xdotool, wmctrl) or direct /proc/*/window mappings to discover open GUI windows and active desktops.', '{Linux}', 'x-mitre-analytic--557d1a5d-31ae-4600-b4ed-a456d9964a83', 'DET0097', '[{"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linus:syslog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ExecutableName", "description": "Common window management utilities can be tuned to reduce noise (e.g., xprop, xwininfo)."}, {"field": "DisplayContext", "description": "Restrict detection to processes executing under graphical sessions (e.g., DISPLAY=:0)."}]', '2026-05-01 15:26:35.254806');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (609, 'AN0630', 'Analytic 0630', 'Detects behavior where files with non-executable or misleading extensions (e.g., .jpg, .txt) are created or modified but subsequently executed as binaries based on internal file headers or abnormal parent process lineage. This includes identifying polyglot files or malformed magic bytes indicative of masquerading attempts.', '{Windows}', 'x-mitre-analytic--557e1f6e-5eeb-46ea-bcd2-5d858eea314c', 'DET0226', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "benign_extensions", "description": "List of non-executable file types commonly used to mask payloads (.jpg, .txt, .gif)"}, {"field": "monitored_directories", "description": "Targeted directories for initial access and downloads (e.g., %TEMP%, Downloads, AppData)"}, {"field": "MagicByteMismatchThreshold", "description": "Detection tolerance for mismatches between extension and file signature (magic bytes)"}, {"field": "TimeWindow", "description": "Time range between file creation and first execution"}, {"field": "ParentProcessAnomalyScore", "description": "Anomaly score threshold for suspicious parent-child process combinations"}]', '2026-05-01 15:26:35.256348');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (613, 'AN0158', 'Analytic 0158', 'Detection of a process or script that accesses a common web service to retrieve content containing obfuscated indicators of a secondary C2 server (dead drop resolver behavior).', '{Windows}', 'x-mitre-analytic--55ec66de-8146-4fd0-a423-0954d6ba33ef', 'DET0058', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "etw:Microsoft-Windows-NDIS-PacketCapture", "channel": "TLS Handshake/Network Flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TargetDomain", "description": "FQDN or IP for the hosting site of the dead drop (e.g., pastebin.com, twitter.com)"}, {"field": "TimeWindow", "description": "Defines how close in time the suspicious network and process behavior must occur"}, {"field": "UserContext", "description": "Filter by user or system accounts to reduce noise"}]', '2026-05-01 15:26:35.262649');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (614, 'AN0253', 'Analytic 0253', 'Manual or script-based installation of extension-like modules into browser config directories or IDE plugin paths, followed by suspicious network activity', '{Linux}', 'x-mitre-analytic--560f859b-2174-4655-b927-b274ad0bda3f', 'DET0092', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fileevents", "channel": "creat", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Abnormal browser traffic volume or destination", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "DirectoryPath", "description": "Common plugin or extension directories may vary by distro or browser (e.g., ~/.config/google-chrome/Default/Extensions)"}, {"field": "ExecPath", "description": "Path to scripting tools used in installation (e.g., bash, curl, unzip)"}, {"field": "TimeWindow", "description": "Tunable interval between install and first network beacon"}]', '2026-05-01 15:26:35.263884');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (615, 'AN0724', 'Analytic 0724', 'Detects file reads across locations followed by writes to temp or staging directories, often compressed or encrypted, indicating local staging behavior.', '{Windows}', 'x-mitre-analytic--561fb700-686a-4583-96a9-77a55358d357', 'DET0261', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "StagingDirList", "description": "Paths such as C:\\Temp, C:\\Windows\\Tasks, etc."}, {"field": "ArchivingToolPatterns", "description": "Matches to 7z.exe, rar.exe, zip.exe, or custom scripts."}, {"field": "TimeWindow", "description": "How long to correlate file reads followed by compression."}]', '2026-05-01 15:26:35.265137');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (616, 'AN1322', 'Analytic 1322', 'Detects unauthorized changes to locally hosted login pages on macOS (common in developer VPN environments) and links file edits to cron jobs, background scripts, or SUID binaries.', '{macOS}', 'x-mitre-analytic--564071d9-44b1-44b8-92c0-348e22e544b7', 'DET0480', '[{"name": "fs:fsusage", "channel": "Filesystem Access Logging", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "subsystem=com.apple.WebKit", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "WebRootPath", "description": "Specify custom web service directories (e.g., /Library/WebServer/Documents/)"}, {"field": "AnomalousProcess", "description": "Alert on web root changes from non-web processes or scripts"}]', '2026-05-01 15:26:35.266477');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (617, 'AN0167', 'Analytic 0167', 'Process execution of curl or wget followed by a network connection and a file created in temporary or user-specific directories.', '{macOS}', 'x-mitre-analytic--56552a3e-9934-4809-97a4-67d62f29478c', 'DET0060', '[{"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "file write/create", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "connection open", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "DirectoryTargeted", "description": "Restrict to high-risk directories like /Users/Shared, /tmp/"}, {"field": "ProcessPath", "description": "May tune based on custom tooling or MDM activity"}]', '2026-05-01 15:26:35.267752');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (618, 'AN2000', 'Analytic 2000', 'Monitor for suspicious network traffic that could be indicative of scanning, such as large quantities originating from a single source (especially if the source is known to be associated with an adversary/botnet).', '{PRE}', 'x-mitre-analytic--56622fce-489a-4ed9-b1fb-e525939667d4', 'DET0868', '[{"name": "Network Traffic", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', NULL, '2026-05-01 15:26:35.268904');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (619, 'AN1982', 'Analytic 1982', 'Consider use of services that may aid in the tracking of newly issued certificates and/or certificates in use on sites across the Internet. In some cases it may be possible to pivot on known pieces of certificate information to uncover other adversary infrastructure.(Citation: Splunk Kovar Certificates 2017) Some server-side components of adversary tools may have default values set for SSL/TLS certificates.(Citation: Recorded Future Beacon Certificates) Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Defense Evasion or Command and Control.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (621, 'AN1383', 'Analytic 1383', 'Detects non-standard compilation activity via Xcode CLI tools or bundled GCC/MONO packages writing new executable files and executing them outside dev environments (e.g., user Downloads folder).', '{macOS}', 'x-mitre-analytic--56a814a9-2b6b-4fcc-a530-e9ca62faaa17', 'DET0501', '[{"name": "macos:unifiedlog", "channel": "process activity, exec events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "networkd or socket", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "CompilerInvocationPattern", "description": "Detect calls to `xcodebuild`, `clang`, or `/Applications/Mono.app/...` from non-admin users"}, {"field": "OutputBinaryPath", "description": "Monitor for output files in user-writable paths (e.g., `~/Library/Caches`, `~/Downloads`)"}]', '2026-05-01 15:26:35.274376');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (622, 'AN1199', 'Analytic 1199', 'Detects access to known password store files (e.g., /etc/shadow, GNOME Keyring, KWallet, browser credential databases). Monitors anomalous process read attempts and suspicious API calls that attempt to extract stored credentials.', '{Linux}', 'x-mitre-analytic--571b10ce-fb7d-492e-b05a-23649ae14148', 'DET0430', '[{"name": "auditd:SYSCALL", "channel": "open/read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredFiles", "description": "Paths to password storage files (e.g., /etc/shadow, ~/.local/share/keyrings/)"}, {"field": "SuspiciousCommands", "description": "Process or command-line keywords that indicate password extraction attempts"}]', '2026-05-01 15:26:35.277603');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (623, 'AN1491', 'Analytic 1491', 'Persistent or background daemons (e.g., plist or launchd jobs) spawning high-CPU processes like xmrig or cpuminer. Outbound encrypted traffic to IPs/domains commonly used by mining proxies.', '{macOS}', 'x-mitre-analytic--57595eb2-4d20-4d99-86b3-82064b3566cf', 'DET0540', '[{"name": "macos:unifiedlog", "channel": "launchd or cron spawning mining binaries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Persistent outbound connections with consistent periodicity", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "launchd.plist_label", "description": "May be disguised with benign-looking names."}, {"field": "DestinationDomain", "description": "Varying mining pool or obfuscated destination."}]', '2026-05-01 15:26:35.279557');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (624, 'AN0829', 'Analytic 0829', 'Abnormal invocation of diskutil or asr that modifies partition tables or initializes raw devices. Monitor for IOKit system calls targeting disk headers or EFI boot sectors, correlated with elevated privileges.', '{macOS}', 'x-mitre-analytic--575a9c01-6dac-4513-86ca-e80b6e485212', 'DET0297', '[{"name": "macos:unifiedlog", "channel": "diskutil partitionDisk or eraseVolume with partition scheme modifications", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "IOKit raw disk write to EFI/boot partition sectors", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}]', '[{"field": "AdminToolWhitelist", "description": "System provisioning workflows may legitimately re-partition disks; whitelist by context."}]', '2026-05-01 15:26:35.280864');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (625, 'AN1560', 'Analytic 1560', 'Processes executing binaries named after legitimate system utilities (e.g., net.exe, findstr.exe, python.exe) from non-standard or application-specific directories, combined with file creation or modification events for such binaries. Defender correlates file writes in vulnerable directories, process execution paths inconsistent with baseline system paths, and abnormal parent-child relationships in process lineage.', '{Windows}', 'x-mitre-analytic--578c821c-f8e3-45e7-a9b4-9aed6c84309a', 'DET0564', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SuspiciousBinaryList", "description": "Common system utilities often hijacked (e.g., net.exe, cmd.exe, powershell.exe, python.exe)."}, {"field": "MonitoredDirectories", "description": "Directories where executables should not normally be written (e.g., application folders, user profile subdirs)."}, {"field": "TimeWindow", "description": "Correlation window between file creation and subsequent process execution."}, {"field": "ParentProcessBaseline", "description": "Expected parent processes for critical system binaries, deviations may indicate hijacking."}]', '2026-05-01 15:26:35.282319');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (626, 'AN1519', 'Analytic 1519', 'CLI-based export of private key material (e.g., ''crypto pki export'') with anomalous user session or AAA role escalation.', '{"Network Devices"}', 'x-mitre-analytic--57a547e1-1086-427c-9ea8-59059dec1938', 'DET0549', '[{"name": "networkdevice:syslog", "channel": "Detected CLI command to export key material", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CLICommandMatch", "description": "Regex for export commands (e.g., crypto pki export, export ssh-key)"}, {"field": "AAAUserContext", "description": "Source username or role performing export — may tune for known admins"}]', '2026-05-01 15:26:35.283747');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (627, 'AN0606', 'Analytic 0606', 'Encryption of cloud storage objects (e.g., S3 buckets) via Server-Side Encryption (SSE-C) or by replacing objects with encrypted variants. May include API patterns like PutObject with SSE-C headers.', '{IaaS}', 'x-mitre-analytic--57d8fd27-9af5-4d01-9d1a-fdde8ec0c902', 'DET0215', '[{"name": "AWS:CloudTrail", "channel": "PutObject (with SSE-C), UploadPart (SSE-C)", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}]', '[{"field": "SSEHeader", "description": "SSE-C headers indicate attacker-controlled encryption keys."}, {"field": "AffectedBucket", "description": "Prioritize logs, backups, or shared document storage buckets."}, {"field": "UserAgent", "description": "Detect scripted automation vs console-based API behavior."}]', '2026-05-01 15:26:35.284922');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (628, 'AN1953', 'Analytic 1953', 'Monitor social media traffic for suspicious activity, including messages requesting information as well as abnormal file or data transfers (especially those involving unknown, or otherwise suspicious accounts).
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (629, 'AN0113', 'Analytic 0113', 'Detects adversary activity that removes persistence artifacts such as services, registry keys, scheduled tasks, user accounts, and binaries through commands like `sc delete`, `schtasks /delete`, or `reg delete`.', '{Windows}', 'x-mitre-analytic--5882d2ff-289e-454d-9146-81306c154be3', 'DET0040', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4726, 4657", "x_mitre_data_component_ref": "x-mitre-data-component--d6257b8e-869c-41c0-8731-fdca40858a91"}, {"name": "WinEventLog:TaskScheduler", "channel": "EventCode=106", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TargetRegistryPathRegex", "description": "Filters known persistence keys like Run/RunOnce, Image File Execution Options"}, {"field": "DeletedScheduledTaskName", "description": "Monitors known or suspicious task names deleted post-persistence"}, {"field": "DeletedAccountGroupScope", "description": "Focuses on highly privileged or recently created accounts"}]', '2026-05-01 15:26:35.287545');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (630, 'AN0790', 'Analytic 0790', 'ESXi services (vmx, hostd) generating outbound HTTPS POST requests to text storage sites. Defender perspective: anomalous datastore or log reads chained with traffic to pastebin-like destinations.', '{ESXi}', 'x-mitre-analytic--58a609cb-b266-4a1a-a40f-9e4cd5d591ce', 'DET0284', '[{"name": "esxi:hostd", "channel": "datastore/log file access", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "esxi:vmkernel", "channel": "HTTPS POST connections to pastebin-like domains", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "DatastoreExfilThreshold", "description": "Threshold of bytes exfiltrated from ESXi datastore files."}, {"field": "ApprovedDestinations", "description": "Whitelist of domains approved for API communication to prevent false positives."}]', '2026-05-01 15:26:35.289028');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (631, 'AN0865', 'Analytic 0865', 'Detects unauthorized additions of users or machine accounts to privileged local or domain groups (e.g., Administrators, Remote Desktop Users).', '{Windows}', 'x-mitre-analytic--58bed5f5-6ef5-4558-9ac9-b58f8aa9888c', 'DET0310', '[{"name": "WinEventLog:Security", "channel": "EventCode=4728, 4729, 4732, 4733, 4756, 4757", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "TargetGroup", "description": "Set to detect high-privileged groups like ''Administrators'', ''Domain Admins'', or ''Remote Desktop Users''"}, {"field": "TimeWindow", "description": "Restrict detections to business hours or approved maintenance windows"}, {"field": "UserContext", "description": "Filter out known automated processes or provisioning systems"}]', '2026-05-01 15:26:35.290837');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (632, 'AN0647', 'Analytic 0647', 'Defenders may observe adversary attempts to collect or export full device configurations by detecting unusual SNMP queries, Smart Install (SMI) activity, or CLI/API commands that request running or startup configuration dumps. Correlated behaviors include high-volume read requests for sensitive OIDs, repeated use of ''show running-config'' or equivalent commands from untrusted IPs, or unexpected TFTP/SCP/FTP transfers containing configuration files. These behaviors often appear in sequence: anomalous authentication or privilege escalation, followed by bulk configuration retrieval and outbound transfer.', '{"Network Devices"}', 'x-mitre-analytic--58e73108-657e-42ce-8dad-4edc968a2b20', 'DET0233', '[{"name": "networkdevice:syslog", "channel": "Failed and successful logins to network devices outside approved admin IP ranges", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "networkdevice:cli", "channel": "Execution of commands like ''show running-config'', ''copy running-config'', or ''export config''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "Outbound SCP, TFTP, or FTP sessions carrying configuration file content", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "snmp:access", "channel": "GETBULK/GETNEXT requests for OIDs associated with configuration parameters", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AuthorizedAdminIPs", "description": "Known trusted IP addresses permitted to execute configuration dump commands."}, {"field": "NormalConfigExportRate", "description": "Baseline frequency of legitimate configuration exports; anomalies above threshold may indicate malicious activity."}, {"field": "AllowedTransferProtocols", "description": "Expected transfer methods (e.g., SCP vs. TFTP). Unexpected use of weak protocols may indicate exfiltration."}, {"field": "TimeWindow", "description": "Normal maintenance windows for authorized configuration exports; activity outside these windows may be suspicious."}]', '2026-05-01 15:26:35.292446');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (639, 'AN1161', 'Analytic 1161', 'Command-line tools (e.g., curl, rsync, wget, or custom Python scripts) used to scrape documentation systems or internal REST APIs. Unusual access patterns to knowledge base folders or shared team drives.', '{Linux}', 'x-mitre-analytic--59faf79f-831d-436b-9ce3-e5c1d338da6c', 'DET0413', '[{"name": "auditd:SYSCALL", "channel": "execve of curl, rsync, wget with internal knowledge base or IPs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "CommandRegex", "description": "Regex matching internal doc servers, knowledge base paths, or IP patterns."}, {"field": "TimeWindow", "description": "Burst access of repositories over a short time window."}]', '2026-05-01 15:26:35.303322');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (633, 'AN1210', 'Analytic 1210', 'Detection centers on DYLD_INSERT_LIBRARIES and DYLD_LIBRARY_PATH abuse. Defender perspective: monitor for modification of these environment variables in shell or plist files, file creation of dylibs in user-controlled paths, and correlation of environment variable usage with unexpected module loads by user applications. Suspicious indicators include processes with DYLD_INSERT_LIBRARIES set, execution of applications loading untrusted dylibs, and anomalies in module load history.', '{macOS}', 'x-mitre-analytic--5907bfc2-a5d6-4ff1-bba8-8b94c9835ed6', 'DET0435', '[{"name": "macos:unifiedlog", "channel": "execution of process with DYLD_INSERT_LIBRARIES set", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "create/modify dylib in monitored directories", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "loading of unexpected dylibs compared to historical baselines", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "WatchedEnvVars", "description": "macOS linker variables like DYLD_INSERT_LIBRARIES. Tunable to development environments where use may be expected."}, {"field": "BaselineDylibs", "description": "Known dylibs typically loaded by apps. Deviations highlight potential hijacking."}, {"field": "MonitoredDirectories", "description": "Locations where dylibs are monitored for tampering (e.g., /Applications, /System/Library, /tmp)."}]', '2026-05-01 15:26:35.293949');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (634, 'AN0174', 'Analytic 0174', 'Detects Python execution from non-standard user contexts or cron jobs that invoke outbound traffic, access sensitive files, or perform process injection (e.g., ptrace or /proc memory maps).', '{Linux}', 'x-mitre-analytic--59354e08-ed82-4b95-99c5-aed3996473e1', 'DET0063', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "/var/log/syslog", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "ScriptDir", "description": "Script invoked from /tmp, /var/tmp, or .hidden/ folders."}, {"field": "ScheduledContext", "description": "Execution from user cron or systemd timers outside of approved scripts."}, {"field": "NetworkActivity", "description": "Python performing HTTP/HTTPS without package updates."}]', '2026-05-01 15:26:35.295205');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (635, 'AN0102', 'Analytic 0102', 'Scripting engines (e.g., osascript, Python) initiating HTTPS requests to social media or content-sharing platforms, paired with automated response handling indicative of two-way communication.', '{macOS}', 'x-mitre-analytic--5935bda3-8d4d-44b4-aca4-8b40cf45f686', 'DET0035', '[{"name": "macos:unifiedlog", "channel": "log stream --info --predicate ''subsystem == \"com.apple.cfprefsd\"''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "web domain alerts", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ScriptEngineList", "description": "Scripting interpreters to monitor for unusual HTTP traffic (e.g., osascript, ruby, bash)"}, {"field": "SocialMediaDomainPatterns", "description": "Patterns or domains used for C2 dead drops and responses (e.g., pastebin.com, twitter.com)"}, {"field": "BurstConnectionRate", "description": "Threshold for number of short-lived HTTPS connections in a short window"}]', '2026-05-01 15:26:35.296927');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (636, 'AN0096', 'Analytic 0096', 'Detects execution of common process enumeration utilities (e.g., ps, top, htop) or access to /proc with suspicious ancestry. Correlates command usage with interactive shell context and user role.', '{Linux}', 'x-mitre-analytic--59aedd87-8373-45d3-93e3-5697e4cc7a48', 'DET0034', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "openat", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:osquery", "channel": "Process State", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "AccessedPath", "description": "Filter based on suspicious /proc directory enumeration or high-volume ls/readlink usage"}, {"field": "UserContext", "description": "Helps tune for root vs. low-priv users during interactive vs. scripted activity"}]', '2026-05-01 15:26:35.298249');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (637, 'AN1117', 'Analytic 1117', 'Startup-based persistence mechanisms within Microsoft Office Suite like template macros and home page redirects being configured through internal automation or client-side settings.', '{"Office Suite"}', 'x-mitre-analytic--59bfb473-611f-4443-9d11-f44e7ace93fb', 'DET0398', '[{"name": "m365:unified", "channel": "Set-Mailbox, Set-InboxRule, Set-MailboxFolderPermission", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "m365:mailboxaudit", "channel": "Outlook rule creation or custom form deployment", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "RuleAction", "description": "Identify rule actions that execute scripts, forward emails externally, or start external content"}, {"field": "MailboxTarget", "description": "Focus on users with sensitive roles or shared mailboxes"}, {"field": "TimeWindow", "description": "Detect persistence artifacts created shortly after credential access or login from an unusual location"}]', '2026-05-01 15:26:35.299645');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (638, 'AN0275', 'Analytic 0275', 'Unexpected write operations to BIOS/UEFI firmware regions or EFI boot partitions that do not correlate with legitimate vendor firmware updates. API calls or utilities such as fwupdate.exe or vendor flash tools executed from non-administrative or non-IT management accounts. Suspicious raw disk writes targeting System Firmware GUID partitions followed by abnormal reboot sequences.', '{Windows}', 'x-mitre-analytic--59d44906-a35e-4b0f-ab84-df3bfa6df8f9', 'DET0099', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=9", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AllowedFirmwareUpdateTools", "description": "Legitimate vendor tools permitted to perform firmware flashing or BIOS updates."}, {"field": "TimeWindow", "description": "Expected time periods for approved firmware updates, used for correlating suspicious activity outside patch cycles."}, {"field": "KnownGoodFirmwareHashes", "description": "Baseline hashes of vendor BIOS/UEFI firmware for integrity comparison."}]', '2026-05-01 15:26:35.301808');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (640, 'AN0214', 'Analytic 0214', 'AppleScript or system calls to activate WiFi/Bluetooth interfaces (`networksetup`, `blueutil`), followed by exfiltration via AirDrop, cloud sync, or network socket.', '{macOS}', 'x-mitre-analytic--5a05483c-fb3b-4240-bf90-c1873b6bd392', 'DET0077', '[{"name": "macos:unifiedlog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "interface_details ", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "Protocol", "description": "Protocol used for exfil (e.g., AirDrop, mDNS, Apple File Service)."}, {"field": "InterfaceActivityWindow", "description": "Time period between interface activation and transfer."}]', '2026-05-01 15:26:35.304607');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (641, 'AN1189', 'Analytic 1189', 'Detects unusual outbound connections to web services from uncommon processes using SSL/TLS, particularly those exhibiting high outbound data volume or persistence.', '{Windows}', 'x-mitre-analytic--5a10a19a-035e-469e-8ec5-fafb1f0f0fe6', 'DET0425', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "SSL/TLS Inspection or PCAP", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ProcessName", "description": "To tune for unexpected or uncommon executables initiating network connections"}, {"field": "DataTransferThreshold", "description": "Volume of outbound data in short time window (e.g., >1MB in <5 min)"}, {"field": "TimeWindow", "description": "Look for connections persisting outside of normal business hours"}]', '2026-05-01 15:26:35.306325');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (642, 'AN0648', 'Analytic 0648', 'Processes accessing LSASS memory or SAM registry hives outside of trusted security tools, often followed by file creation or lateral movement. Detects unauthorized access to sensitive OS subsystems for credential extraction.', '{Windows}', 'x-mitre-analytic--5a5d5ff5-e2bb-4ba9-9f95-504c86b1a1cf', 'DET0234', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Security", "channel": "EventCode=4662", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}]', '[{"field": "AccessMask", "description": "Set to detect full access rights (0x1F0FFF) or modify based on tool behavior."}, {"field": "TimeWindow", "description": "Define how soon access to LSASS is followed by suspicious file or registry activity."}, {"field": "ParentProcessFilter", "description": "Allowlist known security tools or system processes accessing LSASS."}]', '2026-05-01 15:26:35.308148');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (643, 'AN1181', 'Analytic 1181', 'Use ESXi syslogs to track abnormal DNS query patterns from management agents or VMs. Identify high-frequency, low-TTL, or unresolvable domains as suspicious. Correlate with unusual management plane process activity.', '{ESXi}', 'x-mitre-analytic--5a652a8f-a8e1-4010-bc2b-2ffaa2838333', 'DET0419', '[{"name": "esxi:syslog", "channel": "Frequent DNS queries with high entropy names or NXDOMAIN results", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ResolverConfigPaths", "description": "Expected resolver settings for ESXi hosts"}, {"field": "DomainWhitelist", "description": "Trusted external domains for hypervisor operations"}]', '2026-05-01 15:26:35.309557');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (644, 'AN0515', 'Analytic 0515', 'Use of native/mac tools (sharing -l, smbutil view, mount_smbfs) or scripts to enumerate SMB shares across many hosts, followed by outbound SMB connections observed in PF/Zeek logs.', '{macOS}', 'x-mitre-analytic--5a9238a9-acd0-44f0-bd41-f86ef433775b', 'DET0182', '[{"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC: Process execution of \"sharing -l\", \"smbutil view\", \"mount_smbfs\"", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Command line contains smbutil view //, mount_smbfs //", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Firewall", "channel": "Outbound connections to 139/445 to multiple destinations", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "connection: SMB connections to multiple internal hosts", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "BurstHostThreshold", "description": "Minimum unique SMB destinations (e.g., ≥3–5 in smaller mac fleets)."}, {"field": "TimeWindow", "description": "Correlation window between exec and SMB connections (default 10m)."}, {"field": "AllowedMgmtTools", "description": "Jamf/IT scripts legitimately running smbutil/mount_smbfs."}]', '2026-05-01 15:26:35.310801');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (645, 'AN0480', 'Analytic 0480', 'Bash, Swift, or Objective-C programs enumerate system profile, I/O registry, or inspect kernel extensions to identify VM artifacts', '{macOS}', 'x-mitre-analytic--5a92bf3c-1832-453b-8ac9-24f8688d6faf', 'DET0168', '[{"name": "macos:unifiedlog", "channel": "exec or spawn of ''system_profiler'', ''ioreg'', ''kextstat'', ''sysctl'', or calls to sysctl API", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExecutionBurst", "description": "Threshold of sequential system checks or tools used in a short time"}, {"field": "ToolName", "description": "Specific tools used for querying device and system metadata"}]', '2026-05-01 15:26:35.312047');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (646, 'AN0325', 'Analytic 0325', 'Creation or modification of `systemd` service units or cron jobs using deceptive naming and untrusted command paths, often followed by lateral network activity or privilege escalation.', '{Linux}', 'x-mitre-analytic--5a9c1860-23ae-455e-bcab-0e0f91af5548', 'DET0117', '[{"name": "auditd:CONFIG_CHANGE", "channel": "/var/log/audit/audit.log", "x_mitre_data_component_ref": "x-mitre-data-component--faa34cf6-cf32-4dc9-bd6a-8f7a606ff65b"}, {"name": "linux:osquery", "channel": "scheduled/real-time", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "linux:cron", "channel": "cron activity", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}]', '[{"field": "UnitFilePath", "description": "Unusual or user-space paths for systemd unit files"}, {"field": "ServiceNameDeviation", "description": "Detect units with names similar to legitimate ones (e.g., `networks.service` instead of `network.service`)"}, {"field": "ExecStartPath", "description": "Track uncommon or suspicious binaries in `ExecStart=` directives"}]', '2026-05-01 15:26:35.313651');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (647, 'AN0619', 'Analytic 0619', 'Unusual or unauthorized processes accessing microphone APIs (e.g., winmm.dll, avrt.dll) followed by audio file writes to user-accessible or temp directories.', '{Windows}', 'x-mitre-analytic--5aaad268-48fb-4826-9f68-b666e1b4a3bf', 'DET0221', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Time span in which the process accesses audio APIs and writes files, to reduce false positives."}, {"field": "TargetProcess", "description": "Set of approved processes known to legitimately use microphone (e.g., Zoom, Teams)."}, {"field": "WriteDirectory", "description": "Allowlist of paths where legitimate apps store audio (e.g., user media folders)."}]', '2026-05-01 15:26:35.314868');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (648, 'AN1484', 'Analytic 1484', 'sshd, socat, or custom binaries initiating port forwarding or encapsulating traffic (e.g., RDP, SMB) through SSH or HTTP. Defender sees abnormal connect/bind syscalls, encrypted traffic on ports typically used for non-encrypted services, and outlier traffic volume patterns.', '{Linux}', 'x-mitre-analytic--5acd81f3-466a-472d-bb1f-9bda231ac4c0', 'DET0538', '[{"name": "auditd:SYSCALL", "channel": "socket/connect calls showing SSH processes forwarding arbitrary ports", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "linux:syslog", "channel": "sshd sessions with unusual port forwarding parameters", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "linux:osquery", "channel": "socat, ssh, or nc processes opening unexpected ports", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ForwardingFlags", "description": "Specific sshd config flags indicating port forwarding."}, {"field": "ProtocolBaseline", "description": "Define expected application protocols by port to catch tunneling mismatches."}]', '2026-05-01 15:26:35.3161');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (649, 'AN0475', 'Analytic 0475', 'Direct write access to /dev/mem or /sys/firmware combined with usage of firmware flashing utilities (e.g., flashrom).', '{Linux}', 'x-mitre-analytic--5b1514b3-e35b-4ea8-bcc1-b8e492d6d3cd', 'DET0167', '[{"name": "auditd:SYSCALL", "channel": "write access to /dev/mem or /sys/firmware/efi/efivars", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"name": "auditd:SYSCALL", "channel": "execution of known flash tools (e.g., flashrom, fwupd)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ToolName", "description": "Custom or renamed firmware tools may require pattern matching"}]', '2026-05-01 15:26:35.317551');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (650, 'AN0122', 'Analytic 0122', 'Detection of queries to instance metadata services (e.g., AWS IMDS, Azure Metadata Service) for availability zone, region, or network geolocation details. Correlation with non-management accounts or non-standard workloads may indicate adversary reconnaissance.', '{IaaS}', 'x-mitre-analytic--5b41efa6-7410-403b-ac07-89e262fa17ca', 'DET0043', '[{"name": "AWS:CloudTrail", "channel": "GetMetadata, DescribeInstanceIdentity", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "azure:vpcflow", "channel": "HTTP requests to 169.254.169.254 or Azure Metadata endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MetadataQueryAllowList", "description": "Expected services that query cloud metadata APIs. Any additional sources may be malicious."}]', '2026-05-01 15:26:35.318804');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (651, 'AN1222', 'Analytic 1222', 'Detection of anomalous registry modifications to Subject Interface Packages (SIPs) or trust provider DLL mappings, unexpected loading of non-Microsoft cryptographic modules, or attempts to redirect WinVerifyTrust validation logic. Defender view focuses on registry tampering, suspicious DLL loads into trusted processes, and abnormal trust validation failures correlated across event streams.', '{Windows}', 'x-mitre-analytic--5b6f6588-3434-4199-b16f-af44ae546c3d', 'DET0442', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:CodeIntegrity", "channel": "EventCode=3033", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "RegistryPathBaselines", "description": "Monitor for changes in Registry paths."}, {"field": "TimeWindow", "description": "Correlate between changes in Registry values, system files, and modules loaded."}]', '2026-05-01 15:26:35.320097');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (652, 'AN0213', 'Analytic 0213', 'Use of `rfkill`, `nmcli`, or low-level tools (e.g., `iw`, `hcitool`, `pppd`) to enable alternate interfaces followed by data transfer via non-primary NICs.', '{Linux}', 'x-mitre-analytic--5b9f2d26-e84c-49a3-8586-a7367580b802', 'DET0077', '[{"name": "auditd:SYSCALL", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "CommandPattern", "description": "Match known interface manipulation utilities or driver invocations."}, {"field": "NetworkDevice", "description": "Tunable to non-default or rarely used interfaces (e.g., wlan1, hci0)."}]', '2026-05-01 15:26:35.321393');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (653, 'AN0187', 'Analytic 0187', 'Chain: (1) unified logs report IOUSBHost/IOThunderbolt device arrival; (2) diskarbitrationd attaches a new volume; (3) optional: config profile manipulation or new network interface MAC obtains a lease. Correlate unifiedlogs (subsystems: IOUSBHost, IOKit, diskarbitrationd), FSEvents, and DHCP/Zeek.', '{macOS}', 'x-mitre-analytic--5bbe0089-4927-4415-bff7-14a3ba5543c0', 'DET0069', '[{"name": "macos:unifiedlog", "channel": "Device attached|enumerated VID/PID", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "mounted|appeared|DA: disk* attached", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "NSM:Flow", "channel": "MAC not in allow-list acquiring IP (DHCP)", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ManagedUSBPolicy", "description": "MDM profile expectations for external media and Thunderbolt mode; deviations alert."}, {"field": "KnownAppleAccessories", "description": "VID/PID for corporate-issued docks/keyboards."}]', '2026-05-01 15:26:35.322957');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (654, 'AN1182', 'Analytic 1182', 'Process execution that probes user activity artifacts (e.g., desktop files, registry history) following recent user login/unlock events.', '{Windows}', 'x-mitre-analytic--5bd6658f-4391-4d77-bed8-9b141b0fa3ae', 'DET0420', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4800, 4801", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "TimeWindow", "description": "Window between user unlock and access to user history"}, {"field": "UserContext", "description": "Focus on non-system accounts doing user activity probing"}]', '2026-05-01 15:26:35.324646');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (655, 'AN0443', 'Analytic 0443', 'Automated and repetitive triggering of SMS messages through OTP/account verification fields on SaaS platforms, leveraging background messaging APIs such as Twilio, AWS SNS, or Amazon Cognito to generate traffic toward attacker-controlled numbers.', '{SaaS}', 'x-mitre-analytic--5beb62fd-7dac-485f-828c-72cf151124a8', 'DET0156', '[{"name": "saas:application", "channel": "High-frequency invocation of SMS-related API endpoints from publicly accessible OTP or verification forms (e.g., Twilio: SendMessage, Cognito: AdminCreateUser) with irregular destination patterns.", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:audit", "channel": "Repeated requests to SMS-generating endpoints using anomalous or new user agents, IP ranges, or geographies.", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Defines the rolling window over which SMS API invocation frequency is measured. Tunable based on average platform traffic."}, {"field": "SMSFrequencyThreshold", "description": "Number of SMS requests per endpoint or per user that should trigger investigation. Should align with business logic and user behavior."}, {"field": "DestinationCountryCodeFilter", "description": "Monitors if requests target known high-risk, revenue-sharing regions. Tunable to reflect SMS tariff rates or abuse history."}, {"field": "UserAgentAnomalyThreshold", "description": "Defines outlier score or list of unknown/automated user agents submitting forms."}, {"field": "IPGeoVarianceScore", "description": "Tracks abnormal geographic spread of traffic sourcing OTP triggers."}]', '2026-05-01 15:26:35.326369');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (656, 'AN0820', 'Analytic 0820', 'User opens a downloaded document/installer leading to EndpointSecurity file create in ~/Downloads or ~/Library paths then an exec of a suspicious utility (osascript, bash/zsh, curl, chmod, open with -a Terminal). Correlates File Creation with subsequent process exec and, optionally, quarantine/LSQuarantine events.', '{macOS}', 'x-mitre-analytic--5becf65d-da9f-46e1-8edc-eea05c9dc6cb', 'DET0294', '[{"name": "macos:unifiedlog", "channel": "process_exec: image in {/bin/bash,/bin/zsh,/usr/bin/osascript,/usr/bin/python*,/usr/bin/curl,/usr/bin/ssh,/usr/bin/open} AND parent in {Preview, TextEdit, Microsoft Word, Microsoft Excel, AdobeReader, Archive Utility, Finder}", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_CREATE: path under /Users/*/(Downloads|Desktop|Library/*/Containers|Library/Group Containers) AND extension in SuspiciousExtensions", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "TimeWindow", "description": "Correlation window between file create and exec (e.g., ≤10m)."}, {"field": "QuarantineRequired", "description": "Require com.apple.quarantine attribute present on the file for higher fidelity."}, {"field": "ParentApps", "description": "Approved document viewers/editors to anchor lineage."}]', '2026-05-01 15:26:35.32784');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (657, 'AN1942', 'Analytic 1942', 'Monitor for suspicious network traffic that could be indicative of adversary reconnaissance, such as rapid successions of requests indicative of web crawling and/or large quantities of requests originating from a single source (especially if the source is known to be associated with an adversary). Analyzing web metadata may also reveal artifacts that can be attributed to potentially malicious activity, such as referer or user-agent string HTTP/S fields.', '{PRE}', 'x-mitre-analytic--5c5afe0d-b967-49ac-8c3e-eeb9cc01667d', 'DET0810', '[{"name": "Application Log", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', NULL, '2026-05-01 15:26:35.32939');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (658, 'AN0268', 'Analytic 0268', 'Modifications to SSO/SAML user attributes (e.g., `isAdmin`, `role`, MFA bypass, App assignments) often through CLI, API, or rogue IdP apps.', '{"Identity Provider"}', 'x-mitre-analytic--5c69f3b9-8f73-455e-8eb1-5281cd6ce6d5', 'DET0096', '[{"name": "saas:okta", "channel": "User Attribute Modified / Role Assignment Changed", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "RoleAssignmentBaseline", "description": "Expected user-role pairings per app or org unit."}, {"field": "APIUsageContext", "description": "Caller identity or IP address ranges for identity admin actions."}]', '2026-05-01 15:26:35.330586');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (659, 'AN0419', 'Analytic 0419', 'Forged SAML tokens in IaaS environments often manifest as cross-cloud or cross-account authentication without matching STS events. Defenders may see AssumeRole or GetFederationToken API usage without a corresponding SAML assertion log from the trusted IdP.', '{IaaS}', 'x-mitre-analytic--5c6e9102-b3ef-4eaa-85c1-bb5702df0f45', 'DET0148', '[{"name": "AWS:CloudTrail", "channel": "AssumeRoleWithSAML", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "CloudTrail:Signin", "channel": "SAML login without corresponding IdP authentication log", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "CrossAccountUsage", "description": "Flag SAML tokens used across unexpected accounts or cloud tenants."}]', '2026-05-01 15:26:35.331733');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (660, 'AN0793', 'Analytic 0793', 'Monitor mail server logs (Postfix, Sendmail, Exim) for anomalous From headers mismatching authenticated SMTP identities. Detect abnormal relay attempts, spoofed envelope-from values, or large-scale outbound campaigns targeting internal users.', '{Linux}', 'x-mitre-analytic--5c7a8194-f0cb-498a-98c6-5928859bf79f', 'DET0286', '[{"name": "auditd:SYSCALL", "channel": "execve: Processes executing sendmail/postfix with forged headers", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "Application:Mail", "channel": "Mismatch between authenticated username and From header in email", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "KnownRelayHosts", "description": "Filter trusted relays or automated notification systems from impersonation alerts."}]', '2026-05-01 15:26:35.333137');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (661, 'AN1588', 'Analytic 1588', 'Detection focuses on monitoring registry modifications under HKLM\SOFTWARE\Microsoft\Netsh that indicate the addition of helper DLLs, followed by anomalous child process activity or module load behavior initiated by netsh.exe. These behaviors are rarely legitimate and may represent an adversary establishing persistence.', '{Windows}', 'x-mitre-analytic--5ca1b37f-31c9-414b-9a31-9f80f553c44a', 'DET0575', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TimeWindow", "description": "Defines the time window in which correlated registry and execution events are considered suspicious (e.g., within 10 minutes)"}, {"field": "NetshChildProcessWhitelist", "description": "List of expected or approved child processes spawned by netsh.exe in the enterprise environment"}, {"field": "DLLLoadPath", "description": "Directory or filename heuristics to distinguish benign DLLs from malicious helper DLLs"}]', '2026-05-01 15:26:35.334314');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (662, 'AN0502', 'Analytic 0502', 'Adversary uses a tool like Ruler to configure a malicious Outlook folder Home Page that loads a remote or embedded HTML payload upon folder interaction. Execution chain begins with Outlook launching, a specific folder being accessed, and a suspicious child process being spawned or COM-based execution invoked.', '{Windows}', 'x-mitre-analytic--5ce49e4b-a67f-46ea-b48d-f08f7b942fb4', 'DET0177', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Application", "channel": "Outlook logs indicating failure to load or render HTML page in Home Page view", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:PowerShell", "channel": "Execution of PowerShell script to enumerate or remove malicious Home Page folder config", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TargetFolder", "description": "Home Page can be configured on any folder like Calendar, Inbox, or custom folders"}, {"field": "HTMLPayloadLocation", "description": "The Home Page URL may point to internal or external content, hosted on trusted or unknown domains"}, {"field": "ChildProcessName", "description": "Execution may result in launch of scripting hosts (e.g., mshta.exe, wscript.exe) from outlook.exe"}, {"field": "TimeWindow", "description": "Execution may occur only when the specific folder is accessed after launch, not immediately at startup"}, {"field": "FormViewBehavior", "description": "Behavior may vary if the folder''s form view is customized or suppressed via GPO"}]', '2026-05-01 15:26:35.335577');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (663, 'AN1602', 'Analytic 1602', 'ESXi shell or scheduled tasks initiating outbound HTTPS to known public services without inbound return or loggable response, used to fetch instructions.', '{ESXi}', 'x-mitre-analytic--5ce50294-f89c-4158-b5f2-7ca257a88837', 'DET0581', '[{"name": "esxi:hostd", "channel": "CLI network calls", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ScheduledTaskName", "description": "Can tune for task names used to execute curl-based outbound requests"}, {"field": "DestinationIP", "description": "Scoped by environment to exclude known legitimate CDNs"}]', '2026-05-01 15:26:35.336822');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (664, 'AN0254', 'Analytic 0254', 'Adversary launches built-in system tools (e.g., whoami, query user, net user) or scripts that enumerate user account information via local execution or remote API queries (e.g., WMI, PowerShell).', '{Windows}', 'x-mitre-analytic--5d024a50-97d8-4b81-8cc6-3db4fff2712c', 'DET0093', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ParentProcessContext", "description": "Identify if enumeration originates from non-interactive shell or system service"}, {"field": "TimeWindow", "description": "Tune temporal grouping of enumeration + lateral movement attempts"}, {"field": "UserContext", "description": "Flag unexpected users issuing enumeration commands (e.g., service accounts)"}]', '2026-05-01 15:26:35.337966');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (665, 'AN0420', 'Analytic 0420', 'Forged SAML tokens may be used on Windows systems to authenticate to federated apps without normal Kerberos activity. Defenders may detect anomalous event correlation, where access to SaaS/O365 via SAML occurs without prior TGT requests or user logons.', '{Windows}', 'x-mitre-analytic--5d2820b1-af59-4ca2-9f9e-b5bc76f55395', 'DET0148', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:ADFS", "channel": "Token issuance events showing anomalous claims or issuers", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}]', '[{"field": "ClaimAnomalyThreshold", "description": "Number of unusual claims in a SAML token (e.g., excessive privileges)."}]', '2026-05-01 15:26:35.339342');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (666, 'AN1372', 'Analytic 1372', 'Correlates control-plane API actions disabling cloud-native monitoring or sensor agents (CloudTrail, GuardDuty, Security Hub, Defender, monitoring agents), role abuse preceding disablement, or instance agent uninstall events', '{IaaS}', 'x-mitre-analytic--5d329e39-a38b-47cd-8d3d-fa7515280fd7', 'DET0497', '[{"name": "AWS:CloudTrail", "channel": "Delete* / Stop*: DeleteAlarms, StopLogging, or DisableMonitoring API calls", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "APIActions", "description": "Customizable list of cloud provider API calls related to monitoring/alerting disablement."}, {"field": "UserContext", "description": "Distinguishes adversary actions from authorized DevOps/CloudOps activities."}]', '2026-05-01 15:26:35.341189');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (673, 'AN0413', 'Analytic 0413', 'Destruction via `rm -rf`, overwrite with `dd` or `srm`, often executed by script in /tmp or /private/tmp, may also involve file overwrite to political or decoy image data.', '{macOS}', 'x-mitre-analytic--5e1b310a-ce3d-4271-83e0-87cd2862f959', 'DET0146', '[{"name": "macos:unifiedlog", "channel": "exec rm -rf|dd if=/dev|srm|file unlink", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "macos:unifiedlog", "channel": "process.*exit.*code", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "CommandPattern", "description": "Focus on high-risk patterns in temporary directories or key system paths."}, {"field": "EntropyChangeRate", "description": "Optional anomaly detection on overwritten files with high-entropy payloads."}]', '2026-05-01 15:26:35.352728');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (667, 'AN0690', 'Analytic 0690', 'Detects creation of cloud instances, services, or resources in normally unused or unsupported regions, especially following initial account access or credential use from known regions. Correlates resource provisioning across regions with absence of historical usage and alerting from standard logging services (e.g., GuardDuty not enabled in that region).', '{IaaS}', 'x-mitre-analytic--5d4419cc-6925-4f7d-a247-e0a4634fea90', 'DET0247', '[{"name": "AWS:CloudTrail", "channel": "RunInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "AWS:CloudTrail", "channel": "CreateBucket", "x_mitre_data_component_ref": "x-mitre-data-component--59ec10d9-546b-4b8e-bccb-fa85f71e5055"}, {"name": "CloudTrail:GetCallerIdentity", "channel": "GetCallerIdentity", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "AWS:VPCFlowLogs", "channel": "High outbound traffic from new region resource", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "UnusedRegionList", "description": "List of regions historically unused by the organization (can vary per tenant/project)"}, {"field": "TimeWindow", "description": "Time interval for correlating activity following account access"}, {"field": "AllowedServiceList", "description": "Whitelist of services allowed in secondary/DR regions"}, {"field": "OutboundTrafficThreshold", "description": "Volume threshold to flag suspicious outbound activity"}]', '2026-05-01 15:26:35.342899');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (668, 'AN0286', 'Analytic 0286', 'Detects network share disconnection attempts using command-line tools like `net use /delete`, PowerShell `Remove-SmbMapping`, and correlation with process lineage and SMB session teardown activity.', '{Windows}', 'x-mitre-analytic--5d47e6b2-04fb-45ab-be98-7de1baabf508', 'DET0103', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "SMB2_LOGOFF/SMB_TREE_DISCONNECT", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Adjustable window to correlate CLI disconnection command with SMB session teardown (e.g., 5 mins)"}, {"field": "UserContext", "description": "Used to filter on non-interactive users or highly privileged accounts"}, {"field": "ProcessCommandLineRegex", "description": "Patterns to match `net use \\\\host\\share /delete`, `Remove-SmbMapping`, or suspicious batched disconnections"}, {"field": "NetworkShareNamePattern", "description": "Tunable list of shares likely targeted (e.g., ADMIN$, C$, IPC$)"}]', '2026-05-01 15:26:35.344628');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (669, 'AN1615', 'Analytic 1615', 'Detection of enumeration of identity entities through cloud provider APIs where principals retrieve account metadata such as IAM users or roles in rapid succession.', '{IaaS}', 'x-mitre-analytic--5d7158ce-17f5-4643-bde2-c0a4f2ba0b73', 'DET0587', '[{"name": "AWS:CloudTrail", "channel": "DescribeUsers / ListUsers / GetUser", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}]', '[{"field": "API_Method", "description": "Tune based on which IAM APIs are used and their frequency."}, {"field": "CallerType", "description": "Differentiate user-initiated from automated/scripted enumeration."}]', '2026-05-01 15:26:35.346096');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (670, 'AN1060', 'Analytic 1060', 'Detects lateral discovery or container breakout attempts using netcat, curl, or custom binaries probing other services within the same namespace or VPC subnet.', '{Containers}', 'x-mitre-analytic--5d7b1be3-1c8a-40bf-a4d2-85e26dd82d76', 'DET0376', '[{"name": "ebpf:syscalls", "channel": "socket connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "ebpf:syscalls", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "containerd:runtime", "channel": "container-level outbound traffic events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ExecutablePath", "description": "Custom or renamed versions of tools may use different paths"}, {"field": "TimeWindow", "description": "Aggregation interval for identifying anomalous traffic"}, {"field": "NetworkDestinationCount", "description": "Tunable count of unique destinations to classify discovery"}]', '2026-05-01 15:26:35.347505');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (671, 'AN0384', 'Analytic 0384', 'Unusual direct disk access attempts (e.g., use of \\.\PhysicalDrive notation), abnormal writes to MBR/boot sectors, and installation of kernel drivers that grant raw disk access. Correlate anomalous process creation with disk modification attempts and driver loads.', '{Windows}', 'x-mitre-analytic--5dc85538-115c-4c56-878a-39caaba91e74', 'DET0137', '[{"name": "WinEventLog:Security", "channel": "EventCode=4673", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "WinEventLog:Sysmon", "channel": "Raw disk write access via \\\\.\\PhysicalDrive* or \\\\.\\C:", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}]', '[{"field": "ProcessWhitelist", "description": "Legitimate disk imaging or backup tools may trigger raw disk access — must be excluded per environment."}, {"field": "TimeWindow", "description": "Correlate disk access, driver load, and process execution within a short timeframe to minimize false positives."}]', '2026-05-01 15:26:35.349839');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (672, 'AN1467', 'Analytic 1467', 'Execution of processes that link to CoreServices or Foundation APIs followed by creation of memory regions, code execution, or abnormal library injection.', '{macOS}', 'x-mitre-analytic--5e02fe2a-7659-4871-b79e-7ea57373aa37', 'DET0529', '[{"name": "macos:unifiedlog", "channel": "launch and dylib load", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "API Framework Name", "description": "Filter on CoreServices, Cocoa, Foundation framework usage"}, {"field": "Execution Context", "description": "Tune to exclude known developer tools or test environments"}]', '2026-05-01 15:26:35.351451');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (674, 'AN1406', 'Analytic 1406', 'Detects use of session cookies or authentication tokens from unusual user agents or locations. Identifies token reuse without reauthentication or attempts to bypass MFA using previously stolen cookies.', '{SaaS}', 'x-mitre-analytic--5e1d71ce-5653-4580-a609-9832c88e2c87', 'DET0509', '[{"name": "saas:googleworkspace", "channel": "login with reused session token and mismatched user agent or IP", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "saas:okta", "channel": "session.token.reuse", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "TokenReuseTimeWindow", "description": "Max allowed delta between token issuance and second use"}, {"field": "UserAgentAnomalyScore", "description": "Deviation score from normal browser/device fingerprint"}, {"field": "GeoLocationAnomalyScore", "description": "Deviation in IP region or ASN per user profile"}]', '2026-05-01 15:26:35.353909');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (675, 'AN0111', 'Analytic 0111', 'Inspect unified logs for anomalous DNS resolutions triggered by non-network applications. Flag repeated connections to newly registered or algorithmically generated domains. Correlate with endpoint process telemetry.', '{macOS}', 'x-mitre-analytic--5e225927-bf50-4261-b1ae-d65e803da0b8', 'DET0039', '[{"name": "macos:unifiedlog", "channel": "DNS query with pseudo-random subdomain patterns", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:unifiedlog", "channel": "Unexpected applications generating outbound DNS queries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "NewDomainThreshold", "description": "Age of domain registration considered suspicious (e.g., < 30 days)"}, {"field": "DNSQueryVolume", "description": "Number of queries per process per time window"}]', '2026-05-01 15:26:35.355266');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (676, 'AN0151', 'Analytic 0151', 'Outlook or Word used to forward suspicious internal attachments with macro content. Defender observes attachment forwarding, auto-opening behaviors, or macro prompt interactions.', '{"Office Suite"}', 'x-mitre-analytic--5e3f407f-192b-4e6f-aab0-e0682da3a4a9', 'DET0054', '[{"name": "m365:unified", "channel": "SendOnBehalf, MessageSend, AttachmentPreviewed", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Security", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "MacroExecutionWindow", "description": "Timing between mail open and macro invocation"}, {"field": "AttachmentNameHeuristics", "description": "Patterns of known internal spearphishing lures (e.g., invoice, HR_policy)"}]', '2026-05-01 15:26:35.357052');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (677, 'AN1534', 'Analytic 1534', 'Detection focuses on identifying unauthorized file creation or modification within `/etc/emond.d/rules/` or `/private/var/db/emondClients`, which indicate attempts to register a malicious emond rule. Correlate with process execution of `/sbin/emond` and any launched commands it invokes, especially during boot or login events. Anomalies may include rules created by non-root users or unexpected shell commands executed by emond.', '{macOS}', 'x-mitre-analytic--5e4aea30-f04b-4f1e-b68a-f2f3a95e5066', 'DET0555', '[{"name": "macos:unifiedlog", "channel": "file create or modify in /etc/emond.d/rules or /private/var/db/emondClients", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "execution of /sbin/emond with child processes launched", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "rule definitions written to emond rule plists", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "command execution triggered by emond (e.g., shell, curl, python)", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "PathPrefix", "description": "Paths such as `/etc/emond.d/rules/` and `/private/var/db/emondClients` may vary slightly or be symlinked in some setups"}, {"field": "TimeWindow", "description": "The time range for correlating rule file creation to emond execution may be tuned based on system performance and usage"}, {"field": "ParentProcessFilter", "description": "Defenders may wish to restrict alerts to emond processes not spawned from trusted system update or provisioning tools"}, {"field": "CommandPatternList", "description": "List of known suspicious commands or binaries used by adversaries (e.g., reverse shells, persistence scripts)"}]', '2026-05-01 15:26:35.358732');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (678, 'AN1379', 'Analytic 1379', 'Outbound traffic from host management services or guest-to-host interactions over unusual interfaces (e.g., backdoor API endpoints or external VPN tunnels).', '{ESXi}', 'x-mitre-analytic--5e7eea18-14f5-4d76-b5cc-bc63a0e5ce65', 'DET0499', '[{"name": "esxi:vmkernel", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "esxi:vpxd", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "InterfaceName", "description": "May vary based on ESXi build and should be filtered to suppress known interfaces."}, {"field": "FallbackIPRanges", "description": "Environment-specific ranges to ignore (e.g., DR tunnels or out-of-band mgmt)."}]', '2026-05-01 15:26:35.360448');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (679, 'AN0993', 'Analytic 0993', 'Detect curl/wget commands saving executable/script payloads to /tmp or /var/tmp followed by execution. Monitor packet captures or IDS/IPS alerts for injected responses or mismatched content types.', '{Linux}', 'x-mitre-analytic--5e8af32c-5246-43e1-a7d9-c4d263c7b135', 'DET0349', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of curl or wget writing files to /tmp/* followed by chmod or execution", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "File creation of suspicious scripts/binaries in temporary directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Injected content responses with unexpected script/malware signatures", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TempDirectories", "description": "Directories such as /tmp and /var/tmp where injected files are often written."}]', '2026-05-01 15:26:35.36199');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (692, 'AN1001', 'Analytic 1001', 'Registry modifications to HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon\SpecialAccounts\UserList setting user visibility to 0, or creation of user accounts not shown on login screen. Defender view: correlation of account creation with registry edits that mark users hidden.', '{Windows}', 'x-mitre-analytic--6039c777-6a85-4df4-86b9-40d95796046e', 'DET0353', '[{"name": "WinEventLog:Security", "channel": "EventCode=4720", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "AccountScope", "description": "Restrict monitoring to privileged or unexpected accounts."}, {"field": "BaselineHiddenUsers", "description": "Whitelist accounts that are intentionally hidden by administrators."}]', '2026-05-01 15:26:35.381892');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (680, 'AN0188', 'Analytic 0188', 'Unusual inbound email activity where attachments or embedded URLs are delivered to users followed by execution of new processes or suspicious document behavior. Detection involves correlating email metadata, file creation, and network activity after a phishing message is received.', '{Windows}', 'x-mitre-analytic--5ea048cd-f1d5-4da2-9128-10c53ee337c8', 'DET0070', '[{"name": "m365:unified", "channel": "Send/Receive: Emails with suspicious sender domains, spoofed headers, or anomalous attachment types", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SuspiciousFileTypes", "description": "Attachment types considered high risk (e.g., .exe, .js, .vbs, .scr, macro-enabled docs)."}, {"field": "AllowedSenders", "description": "Whitelist of known trusted senders to reduce false positives."}]', '2026-05-01 15:26:35.363864');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (681, 'AN1092', 'Analytic 1092', 'Detects suspicious gratuitous ARP responses or inconsistent IP-to-MAC mappings using auditd and packet capture. Behavioral focus is on unsolicited replies overriding legitimate ARP ownership.', '{Linux}', 'x-mitre-analytic--5ee16525-5e86-4634-aa75-37468c4034c4', 'DET0387', '[{"name": "auditd:SYSCALL", "channel": "setsockopt, ioctl modifying ARP entries", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "Gratuitous ARP replies with mismatched IP-MAC binding", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AllowedARPUpdates", "description": "Expected legitimate IP-to-MAC updates for servers or virtual routers."}, {"field": "AlertThreshold", "description": "Number of anomalous ARP packets per second before triggering detection."}]', '2026-05-01 15:26:35.365287');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (682, 'AN0347', 'Analytic 0347', 'Processes use base64/xxd/openssl/python Objective‑C APIs to encode data (seen in EndpointSecurity exec events or Unified Logs) → quick outbound connections with large bytes_out or HTTP POSTs carrying Base64/MIME bodies.', '{macOS}', 'x-mitre-analytic--5eefb166-8f2b-45e0-b5c8-bf71984dec08', 'DET0124', '[{"name": "macos:unifiedlog", "channel": "process command line contains base64, -enc, openssl enc -base64", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "PF:Logs", "channel": "outbound flows with bytes_out >> bytes_in", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "http: HTTP body contains long Base64 sections", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AllowedDeveloperIDs", "description": "Signed/allowed developer binaries routinely using encoding."}, {"field": "EntropyThreshold", "description": "Payload entropy cutoff."}, {"field": "TimeWindow", "description": "Exec → egress window."}]', '2026-05-01 15:26:35.366531');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (683, 'AN1336', 'Analytic 1336', 'A high volume of authentication failures using a single password (or small set) across many different user accounts within a defined time window', '{Windows}', 'x-mitre-analytic--5ef73ed0-313e-4b9b-b616-8c2d02f4151a', 'DET0487', '[{"name": "WinEventLog:Security", "channel": "EventCode=4625, 4771, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "PasswordReuseThreshold", "description": "Number of distinct accounts a password is used against before alerting"}, {"field": "TimeWindow", "description": "Window over which the correlation is measured (e.g., 10 mins)"}, {"field": "TargetGroupFilter", "description": "Limit detection to sensitive or monitored user groups (e.g., Admins)"}]', '2026-05-01 15:26:35.367837');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (684, 'AN0981', 'Analytic 0981', 'Invocation of built-in commands like screencapture or use of undocumented APIs from suspicious parent processes.', '{macOS}', 'x-mitre-analytic--5f1a4795-74e5-49b9-85bb-e186ca699648', 'DET0346', '[{"name": "macos:unifiedlog", "channel": "process: exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLineRegex", "description": "Customize regex for flag detection (e.g., `screencapture -x`) based on usage patterns"}, {"field": "ParentProcessName", "description": "May vary depending on expected screencapture behavior (Terminal vs remote agent)"}]', '2026-05-01 15:26:35.369083');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (685, 'AN1506', 'Analytic 1506', 'Detects login and usage patterns deviating from typical Microsoft 365 or Google Workspace user profiles.', '{"Office Suite"}', 'x-mitre-analytic--5f1ffd26-01f7-47fc-b544-130fc14c0bd2', 'DET0546', '[{"name": "m365:signinlogs", "channel": "UserLogin", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "gcp:audit", "channel": "login.event", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "BusinessHours", "description": "Used to identify logins outside of expected work times."}, {"field": "OfficeProductivityToolBaseline", "description": "Defines expected application usage per department or role."}]', '2026-05-01 15:26:35.370323');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (686, 'AN0586', 'Analytic 0586', 'Adversary launches high-entropy process or malformed app bundle causing repeated application crashes and system slowdowns.', '{macOS}', 'x-mitre-analytic--5f2cc434-5edc-4f36-927a-eb48ee72aa6e', 'DET0208', '[{"name": "macos:unifiedlog", "channel": "Repeated process crashes logged by CrashReporter or system instability logs in com.apple.console", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "Spike in CPU or memory use from non-user-initiated processes", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "CrashCountThreshold", "description": "Number of app crashes within monitoring window"}, {"field": "PayloadEntropyThreshold", "description": "Used for high-entropy binaries often observed in DoS malware samples"}]', '2026-05-01 15:26:35.371597');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (693, 'AN1581', 'Analytic 1581', 'Detects user activity that shares or syncs files with external domains via link generation, OneDrive external sharing, or file transfer actions involving non-whitelisted partner tenants.', '{"Office Suite"}', 'x-mitre-analytic--60b2d6f4-1bf0-4c52-8923-ac8e3b8088d4', 'DET0573', '[{"name": "m365:unified", "channel": "SharingSet", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}, {"name": "m365:unified", "channel": "AnonymousLinkCreated", "x_mitre_data_component_ref": "x-mitre-data-component--e214eb6d-de8f-4154-9015-6d47915fbed1"}, {"name": "m365:unified", "channel": "FileAccessed", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ExternalDomainList", "description": "Known partner or adversarial cloud identities/domains"}, {"field": "TimeWindow", "description": "Duration between file access and external sharing"}, {"field": "SharingMethod", "description": "Type of link (anonymous, internal, organization-wide) to alert on"}]', '2026-05-01 15:26:35.383239');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (687, 'AN1078', 'Analytic 1078', 'Detects creation or renaming of accounts with names that closely match known service, root, or admin accounts. Behavior often follows account discovery or deletion, attempting to blend into system activity logs using trusted name conventions.', '{Linux}', 'x-mitre-analytic--5f584d00-63b5-44c5-b629-ff238f5b9931', 'DET0383', '[{"name": "auditd:SYSCALL", "channel": "adduser", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "auditd:SYSCALL", "channel": "usermod, or account rename system calls", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "linux:osquery", "channel": "Listing of /etc/passwd and /etc/shadow metadata", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "AllowedSystemAccounts", "description": "Whitelist of legitimate service accounts used for validation."}, {"field": "LevenshteinThreshold", "description": "Edit distance sensitivity between created account and existing account names."}, {"field": "ScriptInitiatorDetection", "description": "Whether to flag account creation events triggered from suspicious scripts or shell histories."}]', '2026-05-01 15:26:35.373223');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (688, 'AN0874', 'Analytic 0874', 'Detection of HTML-based downloads via Safari/Chrome that create obfuscated files (e.g., .zip, .app, .js) in user directories and are followed by suspicious executions from preview or launch services.', '{macOS}', 'x-mitre-analytic--5f8b5ef5-8b4a-4713-a694-dc0746669a73', 'DET0313', '[{"name": "macos:unifiedlog", "channel": "File Events", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "gatekeeper/quarantine database", "channel": "LaunchServices quarantine", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "QuarantineFlagCheck", "description": "Whether downloaded file has a quarantine flag and is bypassed via Gatekeeper"}, {"field": "BlobKeywordAlertList", "description": "JavaScript strings that may indicate smuggling: msSaveBlob, download.href, createObjectURL"}]', '2026-05-01 15:26:35.375007');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (689, 'AN0510', 'Analytic 0510', 'Detection correlates file creation or modification of `.lnk` (shortcut) files in autostart locations with anomalous parent-child process lineage or unsigned binaries. Defenders should watch for LNK creation/modification events outside of known software installations, patch events, or OS updates. Flag shortcut targets pointing to suspicious locations or unknown binaries, particularly those written by script interpreters or spawned from phishing delivery chains.', '{Windows}', 'x-mitre-analytic--5f9fdff8-55ed-4b1e-8889-46b376ce7149', 'DET0180', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "TargetPathRegex", "description": "Tunable regex to flag suspicious shortcut target paths (e.g., temp folder, base64 in target, unusual executable names)"}, {"field": "TimeWindow", "description": "Time window used to correlate shortcut creation with process execution (e.g., 5-minute window)"}, {"field": "UserContextScope", "description": "Filter for expected administrative installs versus end-user initiated shortcut creation"}, {"field": "ZoneIdentifierThreshold", "description": "Configurable value to filter LNK files tagged with external source markers (e.g., ZoneId=3 for Internet)"}]', '2026-05-01 15:26:35.377795');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (690, 'AN0077', 'Analytic 0077', 'Detects applications such as Automator, AppleScript, or LaunchDaemons invoking HTTP/S traffic to non-standard domains or using suspicious headers (e.g., Base64 in URIs or cookie fields).', '{macOS}', 'x-mitre-analytic--5ff3ae40-d326-4eae-9bc5-c77ddcb6cb6e', 'DET0027', '[{"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:unifiedlog", "channel": "log stream --predicate", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SuspiciousParentProcess", "description": "Non-browser parent of web traffic (e.g., AppleScript, bash)"}, {"field": "URIEntropyThreshold", "description": "Unusually encoded data in GET/POST URIs"}]', '2026-05-01 15:26:35.379438');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (691, 'AN0234', 'Analytic 0234', 'Defenders can detect suspicious cloud instance deletions by correlating events across authentication, instance lifecycle, and account activity. From a defender’s perspective, behaviors of interest include instances deleted shortly after creation, deletions initiated by new or rarely used accounts, deletions following snapshot creation, and deletions originating from anomalous geolocations or access keys. These may indicate adversarial attempts to destroy forensic evidence or evade detection.', '{IaaS}', 'x-mitre-analytic--602def5b-49e4-4c64-afe6-1476eac13e67', 'DET0084', '[{"name": "AWS:CloudTrail", "channel": "TerminateInstances", "x_mitre_data_component_ref": "x-mitre-data-component--1361e324-b594-4c0e-a517-20cee32b8d7f"}, {"name": "AWS:CloudTrail", "channel": "DescribeInstances", "x_mitre_data_component_ref": "x-mitre-data-component--45fd904d-6eb0-4b50-8478-a961f09f898b"}, {"name": "azure:activity", "channel": "MICROSOFT.COMPUTE/VIRTUALMACHINES/DELETE", "x_mitre_data_component_ref": "x-mitre-data-component--7561ed50-16cb-4826-82c7-c1ddca61785e"}]', '[{"field": "UserContext", "description": "Identity of the user/service account performing deletions; tuned to exclude automation or known administrative workflows."}, {"field": "TimeWindow", "description": "Threshold for detecting rapid instance lifecycle events (e.g., creation and deletion within minutes)."}, {"field": "GeoLocation", "description": "Region or source IP where the delete request originated; can be tuned to align with enterprise cloud geography."}, {"field": "RateThreshold", "description": "Number of deletions per user/account in a defined window; tuned for organizations with high elasticity."}]', '2026-05-01 15:26:35.380719');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (778, 'AN1984', 'Analytic 1984', 'Monitor for contextual data about a malicious payload, such as compilation times, file hashes, as well as watermarks or other identifiable configuration information. In some cases, malware repositories can also be used to identify features of tool use associated with an adversary, such as watermarks in [Cobalt Strike](https://attack.mitre.org/software/S0154) payloads.(Citation: Analyzing CS Dec 2020)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (694, 'AN0578', 'Analytic 0578', 'Detects interactive or scripted abuse of cmd.exe, batch files, or shell invocation chains. Focuses on parent-child relationships (e.g., cmd.exe launched from unusual parents), anomalous command-line parameters, and chaining with discovery, credential access, or lateral movement behaviors.', '{Windows}', 'x-mitre-analytic--60d70569-0d28-4d98-957c-4676b2411685', 'DET0202', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "EDR:scriptblock", "channel": "Process Tree + Script Block Logging", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "ParentProcessName", "description": "Cmd.exe launched from uncommon parents (e.g., msedge.exe, winword.exe) may indicate abuse."}, {"field": "TimeWindow", "description": "Cmd or .bat execution during non-working hours may indicate automation or C2 activity."}, {"field": "CommandLinePattern", "description": "Flags suspicious switches (e.g., /c ping, /k whoami) or command chaining (&&, ^)."}, {"field": "ScriptStoragePath", "description": "Batch file execution from %TEMP%, C:\\Users\\Public, or external drives."}, {"field": "UserContext", "description": "Flags admin-level users executing cmd outside expected baselines."}]', '2026-05-01 15:26:35.384942');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (695, 'AN0427', 'Analytic 0427', 'Detects use of unencrypted protocols (e.g., TFTP, FTP, HTTP) to transfer configuration files, routing tables, or logs to untrusted IP addresses, especially using administrative commands like `copy run ftp:`.', '{"Network Devices"}', 'x-mitre-analytic--611778c2-9de4-4066-b7d1-78752891c32e', 'DET0149', '[{"name": "networkdevice:cli", "channel": "CLI command logs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "flow records", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "PCAP inspection", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ProtocolCommandWatchlist", "description": "Flag commands like `copy`, `archive tar`, or `upload` directed at external hosts."}, {"field": "DestinationIPBlocklist", "description": "Define external IP ranges unauthorized to receive router/switch configs."}]', '2026-05-01 15:26:35.386317');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (696, 'AN0983', 'Analytic 0983', 'Detects processes or binaries executed from trusted directories (e.g., System32) or using trusted names (e.g., svchost.exe) where the metadata, hash, or parent process does not align with legitimate activity patterns.', '{Windows}', 'x-mitre-analytic--61256fb2-d490-4e1d-b308-665a2d68ec64', 'DET0347', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "trusted_directory_list", "description": "Paths such as C:\\Windows\\System32 that adversaries may abuse"}, {"field": "process_baseline_age", "description": "Time window to determine process novelty (e.g., 30 days)"}]', '2026-05-01 15:26:35.387669');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (697, 'AN1400', 'Analytic 1400', 'Detects ptrace- or memfd-based process injection through audit logs capturing system calls (e.g., ptrace, mmap) targeting running processes along with suspicious file descriptors or memory writes.', '{Linux}', 'x-mitre-analytic--61282e0a-3eae-4358-8821-6c8318961e24', 'DET0508', '[{"name": "auditd:SYSCALL", "channel": "ptrace, mmap, process_vm_writev", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:procfs", "channel": "/proc/[pid]/maps, /proc/[pid]/mem", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "TargetPIDThreshold", "description": "Limit to sensitive or unexpected processes being targeted (e.g., sshd, init)"}, {"field": "TimeWindow", "description": "Correlate mmap or writev usage to process access within a short timeframe"}]', '2026-05-01 15:26:35.388902');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (698, 'AN1240', 'Analytic 1240', 'Account created via CLI using ''username'' command or REST API. Detectable through AAA logging or CLI history telemetry.', '{"Network Devices"}', 'x-mitre-analytic--614594ba-9590-4fa9-871c-3e092882c74c', 'DET0447', '[{"name": "networkdevice:syslog", "channel": "username <user> privilege <level>", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}]', '[{"field": "PrivilegeLevel", "description": "Some devices allow unprivileged user creation—adjust based on role risk"}, {"field": "RemoteSessionFlag", "description": "Creation via Telnet, SSH, or serial console affects detection priority"}]', '2026-05-01 15:26:35.39081');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (699, 'AN0503', 'Analytic 0503', 'Malicious HTML or script is rendered as a Home Page for a specific Outlook folder. Outlook accesses that folder, loads remote content, and executes embedded JavaScript or ActiveX/COM logic resulting in unauthorized actions or local execution.', '{"Office Suite"}', 'x-mitre-analytic--616755c6-e83d-46ce-ad76-ac706074a575', 'DET0177', '[{"name": "m365:unified", "channel": "Folder configuration updated with external or HTML-formatted Home Page via Set-MailboxFolder", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:messagetrace", "channel": "Inbound email triggering Outlook to auto-access folder tied to malicious Home Page", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AuditPolicyScope", "description": "Home Page customization may not be audited unless detailed message or folder auditing is enabled"}, {"field": "FolderAccessRate", "description": "Anomalous access to folders not usually interacted with can signal triggering of malicious view"}, {"field": "ExternalURLAllowlist", "description": "Mail clients may restrict remote Home Page content unless domain is explicitly allowed"}]', '2026-05-01 15:26:35.392446');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (712, 'AN0166', 'Analytic 0166', 'Shell-based tools (curl, wget, scp) initiate connections to external domains followed by creation of executable files on disk.', '{Linux}', 'x-mitre-analytic--62d55c57-54a3-4c6f-8d0d-2684fa26c347', 'DET0060', '[{"name": "auditd:SYSCALL", "channel": "connect, execve, write", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "file creation/modification", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "iptables:LOG", "channel": "TCP connections", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ToolName", "description": "Match on curl, wget, rsync, etc. based on environment"}, {"field": "DownloadExtension", "description": "Tunable filter to limit to suspicious file types (.sh, .bin, .elf)"}]', '2026-05-01 15:26:35.41279');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (700, 'AN1520', 'Analytic 1520', 'Anomalous high-volume access to customer records in CRM software by a non-CRM admin user account, especially following initial authentication from a rare location or device. Behavior includes abnormal access to PII fields or data exports within a short time window.', '{SaaS}', 'x-mitre-analytic--616bc2d5-5c4d-4efa-9490-c77213be1de1', 'DET0550', '[{"name": "saas:salesforce", "channel": "DataExport, RestAPI, Login, ReportExport", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:signinlogs", "channel": "UserLoggedIn", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "TimeWindow", "description": "Duration over which bulk CRM queries occur (e.g., 1 minute, 5 minutes); varies by organization usage pattern"}, {"field": "UserContext", "description": "User''s CRM role, department, or job function (e.g., non-sales user accessing customer PII)"}, {"field": "AnomalousExportThreshold", "description": "Number of CRM objects (contacts, deals, logs) accessed or exported above normal"}, {"field": "SourceLocation", "description": "Rare or impossible geolocation/IP address for legitimate CRM user access"}]', '2026-05-01 15:26:35.393893');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (701, 'AN0267', 'Analytic 0267', 'Modifications to user accounts via `dscl`, `pwpolicy`, or System Preferences CLI (`sysadminctl`) that alter user groups, enable root, or bypass MDM restrictions.', '{macOS}', 'x-mitre-analytic--616ccbf4-08f2-4b54-8e41-a8e362e31827', 'DET0096', '[{"name": "macos:unifiedlog", "channel": "com.apple.accountsd, com.apple.opendirectoryd", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "ModifiedUserList", "description": "Track known non-system user UIDs or service accounts."}, {"field": "GroupMembershipChanges", "description": "List of sensitive groups (admin, _developer, _analyticsd)."}]', '2026-05-01 15:26:35.395291');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (702, 'AN0580', 'Analytic 0580', 'Detects suspicious registry modifications under `HKLM\SYSTEM\CurrentControlSet\Control\Print\Monitors\*\Driver`, DLL loads by `spoolsv.exe` of non-standard or unsigned modules, and abnormal usage of the `AddMonitor` API by non-installation processes. This pattern often indicates an attempt to persist a malicious DLL via the print monitor mechanism, particularly when correlated with creation of files in `C:\Windows\System32` not tied to known patches or installations.', '{Windows}', 'x-mitre-analytic--61729716-59f3-433e-a678-101c18040851', 'DET0204', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Application", "channel": "API call to AddMonitor invoked by non-installer process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "TargetDLLDirectory", "description": "Expected directory path for legitimate monitor DLLs (e.g., C:\\Windows\\System32)"}, {"field": "SignedImageValidation", "description": "Enable/disable signature validation on DLLs loaded by spoolsv.exe"}, {"field": "UserContextScope", "description": "Define whether only SYSTEM/user installs are expected to make changes to the port monitor registry keys"}, {"field": "TimeWindow", "description": "Timeframe between registry modification and subsequent spoolsv.exe DLL load"}, {"field": "AddMonitorCallContext", "description": "Filter on calling process of AddMonitor API to detect anomalies outside installer/updater"}]', '2026-05-01 15:26:35.396951');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (703, 'AN2065', 'Analytic 2065', 'Detection identifies execution of scripts or applications containing invisible Unicode payloads reconstructed at runtime, correlated with abnormal AppleScript, JavaScript for Automation, or shell execution and subsequent process or network behavior inconsistent with visible file content. ', '{macOS}', 'x-mitre-analytic--6195e912-ed73-4ec7-a03b-097631ec0b26', 'DET0920', '[{"name": "NSM:Flow", "channel": "log entries indicating network connection initiation on macOS", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "macos:unifiedlog", "channel": "Execution of osascript, sh, bash, zsh, installer, open", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macOS:unifiedlog", "channel": "looking for file access to scripts with abnormal encoding patterns", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ExecutionContext", "description": "Use of abnormal AppleScript or JavaScript functions (such as eval()) not typically expected"}, {"field": "UnicodeCharacterSet", "description": "Specific unicode ranges monitored (zero-width, PUA, bidi) "}]', '2026-05-01 15:26:35.39929');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (704, 'AN1609', 'Analytic 1609', 'Unexpected creation or modification of files with `com.apple.ResourceFork` extended attributes containing unusually large or non-standard data. Defender perspective: detection of resource forks in contexts where they are uncommon, especially when paired with process execution or network activity.', '{macOS}', 'x-mitre-analytic--619804e7-5ae7-4c6e-b1bb-e1d10a22cc87', 'DET0584', '[{"name": "macos:unifiedlog", "channel": "File creation or modification with com.apple.ResourceFork extended attribute", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:unifiedlog", "channel": "Execution of commands like `ls -l@`, `xattr -l`, or custom tools interacting with resource forks", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "Process creation involving binaries interacting with resource fork data", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ResourceForkSizeThreshold", "description": "Adjust thresholds for ''unusually large'' resource fork data based on baseline usage in the environment."}, {"field": "MonitoredDirectories", "description": "Scope monitoring to sensitive directories such as /Users, /Applications, or temporary paths."}, {"field": "CorrelatedActivityWindow", "description": "Time window for correlating resource fork activity with subsequent execution or network activity."}]', '2026-05-01 15:26:35.400498');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (711, 'AN1062', 'Analytic 1062', 'Abnormal loading of kernel modules, direct tampering with /dev, /proc, or LD_PRELOAD behaviors hiding processes or files.', '{Linux}', 'x-mitre-analytic--62cf396f-01d6-4ab0-a3f5-bf75d90c2c40', 'DET0377', '[{"name": "auditd:EXECVE", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:syslog", "channel": "kmod", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "MonitoredDirectories", "description": "Directories where kernel modules or tampering could be staged (e.g., /lib/modules/)."}, {"field": "ModuleNamePattern", "description": "Regex or heuristic match to anomalous module names (e.g., suspicious entropy or gibberish)."}, {"field": "LD_PRELOAD", "description": "Monitor presence of suspicious preload values that mask processes or files."}]', '2026-05-01 15:26:35.410959');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (705, 'AN0185', 'Analytic 0185', 'Chain: (1) a new external device is recognized by Windows (USB/Thunderbolt/PCIe) or a new block device appears; (2) within a short window, the same user/session spawns processes or the OS mounts a new volume; (3) optional follow-on activity such as HID keystroke injection, DMA driver load, or new network interface MAC on DHCP. Correlate Security EID 6416 / Kernel-PnP with sysmon and DHCP/network metadata.', '{Windows}', 'x-mitre-analytic--61d89912-f74e-4fde-ae7a-591e8c7c5739', 'DET0069', '[{"name": "WinEventLog:Security", "channel": "EventCode=6416", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:System", "channel": "Kernel-PnP 410/400 device install, disk added", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "wineventlog:dhcp", "channel": "DHCP Lease Granted", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TrustedDeviceVIDPID", "description": "Vendor/Product IDs that are approved (e.g., keyboards, mice). Unknown/rare VID:PID raise risk."}, {"field": "ExpectedBusTypes", "description": "Allow-listed bus types for server classes (e.g., USB disabled on DCs)."}, {"field": "TimeWindow", "description": "Correlation window between device recognition and follow-on process/mount/network activity (e.g., 10m–60m)."}, {"field": "TrustedMACs", "description": "Known NIC/USB-NIC MAC addresses allowed by policy."}]', '2026-05-01 15:26:35.401674');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (706, 'AN1172', 'Analytic 1172', 'Detects file movement or outbound TFTP/FTP transfers from ESXi host initiated via shell commands or injected scripts, particularly from scratch partitions or /tmp.', '{ESXi}', 'x-mitre-analytic--61e3802a-c95c-43c2-8749-139e0f750169', 'DET0416', '[{"name": "esxi:shell", "channel": "/root/.ash_history", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "mirror/SPAN port", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TransferTargetDomainOrIP", "description": "Public IPs or domains not belonging to known ESXi mgmt infra"}, {"field": "SourceDirectoryFilter", "description": "Monitor transfers from /tmp/, /etc/, /vmfs/volumes/"}]', '2026-05-01 15:26:35.40296');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (707, 'AN0139', 'Analytic 0139', 'Creation or modification of files in directories known to be excluded from AV scanning (e.g., C:\Windows\Temp, Exchange server directories, or default AV exclusions). Defender perspective: correlate file creation with execution behavior or anomalous parent processes writing to excluded paths.', '{Windows}', 'x-mitre-analytic--620cae28-1874-462d-a2e4-47ddd75098ea', 'DET0051', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ExcludedPaths", "description": "List of directories excluded from scanning in the environment (customizable per organization)."}, {"field": "ProcessAllowlist", "description": "Legitimate processes typically writing to excluded paths to minimize false positives."}]', '2026-05-01 15:26:35.404177');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (708, 'AN0673', 'Analytic 0673', 'Monitor for security commands and API calls interacting with the Keychain, as well as file access attempts to stored certificates and private keys in ~/Library/Keychains or /Library/Keychains.', '{macOS}', 'x-mitre-analytic--62285936-d8a3-4b18-b3b4-a521fbef10ec', 'DET0240', '[{"name": "macos:unifiedlog", "channel": "process calling security find-certificate, export, or import", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:keychain", "channel": "~/Library/Keychains, /Library/Keychains", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ApplicationAllowList", "description": "Whitelist legitimate apps that interact with Keychain to reduce false positives."}]', '2026-05-01 15:26:35.405629');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (709, 'AN0095', 'Analytic 0095', 'Identifies adversary behavior that launches commands or invokes APIs to enumerate active processes (e.g., tasklist.exe, Get-Process, or CreateToolhelp32Snapshot). Detects execution combined with parent process lineage, network session context, or remote origin.', '{Windows}', 'x-mitre-analytic--625983e7-9736-44f4-98ba-f372b3a3d236', 'DET0034', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "ParentProcessName", "description": "Used to scope suspicious discovery from non-interactive or non-standard parent processes like Office macros, WMI, or script engines"}, {"field": "CommandLinePattern", "description": "Adversaries may obfuscate or vary process discovery commands (e.g., aliases, PowerShell variants)"}, {"field": "TimeWindow", "description": "Helps detect bursty discovery behavior within a short timeframe"}]', '2026-05-01 15:26:35.407512');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (710, 'AN0784', 'Analytic 0784', 'Identifies archive utilities (e.g., ditto, unzip, xar, pkgutil) used to extract payloads to non-standard paths, then correlates with execution or file permission changes (e.g., `chmod +x`) and process spawns from decompressed location.', '{macOS}', 'x-mitre-analytic--62afd8a1-550d-43a6-a56a-7d5ae5abbcf6', 'DET0281', '[{"name": "macos:unifiedlog", "channel": "Process launch", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "filesystem events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "fs:fsusage", "channel": "file open/write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "DecompressionPathMatch", "description": "Target unusual extraction paths (~/Library/, /tmp/, /private/tmp/)"}, {"field": "ToolBinaryNames", "description": "List of decompression utilities used in the environment"}, {"field": "FollowOnExecutionDelta", "description": "Time between decompression and first binary execution"}]', '2026-05-01 15:26:35.40939');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (720, 'AN0246', 'Analytic 0246', 'Keylogging on legacy network devices via unauthorized system image modification or remote capture of console keystrokes (telnet, SSH) through altered firmware or man-in-the-middle key sniffing.', '{"Network Devices"}', 'x-mitre-analytic--63a1b615-8389-4776-a79c-6db04037a7b7', 'DET0089', '[{"name": "networkdevice:syslog", "channel": "Image Upgrade / Configuration Change", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"name": "NSM:Flow", "channel": "packet capture or DPI logs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "FirmwareVersion", "description": "Baseline hash or expected version for config/image integrity"}, {"field": "Protocol", "description": "Scope to plaintext channels or low-assurance SSH versions"}]', '2026-05-01 15:26:35.42357');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (713, 'AN1019', 'Analytic 1019', 'Detection of excessive or programmatic access to Confluence spaces or pages, particularly by privileged users, through a combination of access logs, API usage, and identity context. Correlates logon sessions, user roles, and abnormal document viewing or export behavior. Identifies burst access patterns and tools/scripts abusing the Confluence API for mass enumeration or data scraping.', '{SaaS}', 'x-mitre-analytic--62f43db8-4701-49b9-bb0e-a8fde37e5d07', 'DET0358', '[{"name": "saas:confluence", "channel": "access.content", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:confluence", "channel": "logon", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "saas:confluence", "channel": "REST API access from non-browser agents", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Defines the time span (e.g., 5m, 1h) in which excessive access behavior becomes suspicious."}, {"field": "UserContext", "description": "Privileged user roles (e.g., domain admins) should be excluded or flagged if found accessing documentation repositories."}, {"field": "AccessThreshold", "description": "The number of pages viewed or exported by a single user before triggering detection logic."}, {"field": "AgentFilter", "description": "User agent strings that may indicate scripted, automated, or non-interactive access methods."}]', '2026-05-01 15:26:35.41432');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (714, 'AN0309', 'Analytic 0309', 'Detection correlates message events in email and collaboration tools (e.g., Outlook, Teams) that contain regex-like patterns resembling credentials, API keys, or tokens. Anomalous forwarding or bulk copy activity of chat/email content containing secrets is flagged. Suspicious behavior includes users pasting secrets into direct messages or attaching config files with passwords.', '{"Office Suite"}', 'x-mitre-analytic--631da3e4-5ecd-4dc9-966a-1c2633f8f24c', 'DET0111', '[{"name": "m365:unified", "channel": "MessageSend, MessageRead, or FileAttached events containing credential-like patterns", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "RegexPatterns", "description": "Customizable credential-detection regex (e.g., API_KEY=, bearer token formats) depending on enterprise apps in use"}, {"field": "AllowedDomains", "description": "Exclude known trusted domains or automated system-to-system messages"}, {"field": "TimeWindow", "description": "Adjust correlation period for bulk credential sharing events"}]', '2026-05-01 15:26:35.415653');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (715, 'AN1627', 'Analytic 1627', 'Detects use of timestamp-altering commands like `touch -a -m -t` or `touch -r`, particularly when executed by unusual users or in suspicious directories.', '{Linux}', 'x-mitre-analytic--632f7aef-f848-4147-95fa-2052bd373576', 'DET0591', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "MonitoredCommandList", "description": "Commands like `touch -r`, `debugfs`, `stat` used in sequence"}, {"field": "FilePathRegex", "description": "Suspicious paths like `/tmp/`, `/var/lib/`, `/mnt/esxi/`"}, {"field": "DeltaThreshold", "description": "Mismatch between timestamp and file activity time"}]', '2026-05-01 15:26:35.416843');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (716, 'AN1004', 'Analytic 1004', 'Unusual or unauthorized external remote access attempts (e.g., RDP, VPN, Citrix) → repeated failed logins followed by a successful session from uncommon geolocations or outside business hours → subsequent internal lateral movement or data exfiltration activities.', '{Windows}', 'x-mitre-analytic--63583dcb-dbdc-4b9d-a261-3129de12327e', 'DET0354', '[{"name": "WinEventLog:Security", "channel": "EventCode=4776, 4625", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "WinEventLog:Application", "channel": "VPN, Citrix, or remote access gateway logs showing external IP addresses", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "BusinessHours", "description": "Normal business hours for logon activity."}, {"field": "KnownRemoteIPs", "description": "List of approved external IPs or VPN endpoints."}, {"field": "FailedLogonThreshold", "description": "Number of failed logons before raising suspicion (e.g., >5)."}, {"field": "GeoIPWhitelist", "description": "Geographic regions allowed for remote access."}, {"field": "TimeWindow", "description": "Time window to correlate failed attempts and success (e.g., 15m)."}]', '2026-05-01 15:26:35.417994');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (717, 'AN0905', 'Analytic 0905', 'Detects shell-based enumeration of active connections using `netstat`, `lsof -i`, or AppleScript-based system discovery.', '{macOS}', 'x-mitre-analytic--635f834e-ee46-496f-aec4-23dbef04451b', 'DET0320', '[{"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ShellCommandWatchlist", "description": "Matches terminal commands like `lsof -i`, `netstat`, or scripts issued via Automator or AppleScript."}, {"field": "TerminalBinaryDenylist", "description": "Tracks execution of networking discovery tools by apps outside Terminal.app or iTerm."}]', '2026-05-01 15:26:35.419183');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (718, 'AN0026', 'Analytic 0026', 'Correlates launchd plist modifications with subsequent unauthorized script execution or anomalous parent-child process trees involving user agents.', '{macOS}', 'x-mitre-analytic--636b1cca-1fc4-4909-ac33-c2b2a7d69e02', 'DET0010', '[{"name": "macos:unifiedlog", "channel": "Modification of ~/Library/LaunchAgents or /Library/LaunchDaemons plist", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Execution of launchctl with suspicious arguments", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PlistNamePattern", "description": "Regex pattern matching known rogue or unrecognized launchd plist names"}, {"field": "ParentProcessBaseline", "description": "Expected parent-child relationships during plist-triggered execution"}]', '2026-05-01 15:26:35.420376');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (719, 'AN0978', 'Analytic 0978', 'Monitor for unexpected privilege elevation operations via SAML assertion manipulation, role injection, or changes to identity mappings that result in access escalation.', '{"Identity Provider"}', 'x-mitre-analytic--6385ccc0-f1a9-4198-997e-dec943e88db7', 'DET0345', '[{"name": "azure:signinlogs", "channel": "unusual role assumption or elevation path", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "AuthorizedRoleMappings", "description": "Roles or groups that should never be assumed outside designated paths"}, {"field": "TimeWindow", "description": "Time between assertion issuance and critical privilege use"}]', '2026-05-01 15:26:35.421779');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (721, 'AN0780', 'Analytic 0780', 'Monitor launchd service definitions and property list (.plist) modifications for non-standard executables. Detect unauthorized processes registered as launch daemons or agents.', '{macOS}', 'x-mitre-analytic--63d21290-b858-4c4e-9447-31d623048048', 'DET0279', '[{"name": "macos:unifiedlog", "channel": "Unexpected processes registered with launchd", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Modification of LaunchAgents or LaunchDaemons plist files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "PlistAllowlist", "description": "Known launch agents/daemons expected to be modified by updates or IT tools"}, {"field": "PayloadEntropyThreshold", "description": "Entropy level for detecting suspicious binary payloads in launchd services"}]', '2026-05-01 15:26:35.427154');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (722, 'AN1180', 'Analytic 1180', 'Monitor unified DNS logs for abnormal domain queries with low lexical similarity to known domains, repeated failed lookups, and random string structures. Cross-check with process logs to confirm unusual origins (non-browser apps).', '{macOS}', 'x-mitre-analytic--63de336c-105c-4e8f-aefc-420a3eac32e9', 'DET0419', '[{"name": "macos:unifiedlog", "channel": "High entropy domain queries with multiple NXDOMAINs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:unifiedlog", "channel": "Unexpected apps performing repeated DNS lookups", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ReputationFeedWhitelist", "description": "Exclude trusted CDN and cloud provider domains"}, {"field": "LexicalScoreThreshold", "description": "Adjust score for word-based vs. letter-based DGAs"}]', '2026-05-01 15:26:35.428729');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (723, 'AN0668', 'Analytic 0668', 'Detects disabling or reconfiguration of syslog or rsyslog services. Monitors sudden stops in logging daemons and suspicious execution of kill or service stop commands targeting syslog processes.', '{Linux}', 'x-mitre-analytic--63e17792-17f5-48ae-8002-da6b62b4bcaa', 'DET0239', '[{"name": "auditd:SYSCALL", "channel": "execve: service stop syslog, systemctl stop rsyslog, kill -9 syslog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:osquery", "channel": "unexpected termination of syslog or rsyslog processes", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "SyslogServiceName", "description": "Service name for syslog daemon, which can differ across distributions."}]', '2026-05-01 15:26:35.430516');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (724, 'AN0931', 'Analytic 0931', 'Remote Desktop (RDP) logon by a user followed by unusual process execution, file access, or lateral movement activity within a short timeframe.', '{Windows}', 'x-mitre-analytic--63fcb4be-f5c2-47da-951d-cd1b4f1a2cc0', 'DET0327', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4778, EventCode=4779", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Temporal threshold to correlate login with post-login activity (e.g., 5 minutes)"}, {"field": "UserContext", "description": "Tune for non-admin users or service accounts expected to use RDP"}, {"field": "ProcessList", "description": "Define suspicious post-login processes such as cmd.exe, powershell.exe, certutil.exe"}, {"field": "HostAccessPatterns", "description": "Scope detection to uncommon or first-time access between source and destination hosts"}]', '2026-05-01 15:26:35.431849');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (725, 'AN1472', 'Analytic 1472', 'Detects behavioral sequence where an adversary gains elevated privileges and clears event logs using native binaries (e.g., wevtutil), PowerShell, or direct file deletion of .evtx files.', '{Windows}', 'x-mitre-analytic--6482fa33-322b-47e4-a9f7-c2bcc92d132a', 'DET0532', '[{"name": "WinEventLog:Security", "channel": "EventCode=1102", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=23", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "TimeWindow", "description": "Time range between log-clearing command and 1102 event; tunable to reduce false positives"}, {"field": "UserContext", "description": "Filter by admin/elevated users; allow tuning to detect abuse of high-privilege accounts"}, {"field": "CommandLinePattern", "description": "Match common variations of log-clearing commands like `Remove-EventLog`, `wevtutil cl`"}, {"field": "TargetLogName", "description": "Scope detection to Security, System, Application, or custom logs based on environment"}]', '2026-05-01 15:26:35.433069');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (726, 'AN1483', 'Analytic 1483', 'Processes such as plink.exe, ssh.exe, or netsh.exe establishing outbound network connections where traffic patterns show encapsulated protocols (e.g., RDP over SSH). Defender observations include anomalous process-to-network relationships, large asymmetric data flows, and port usage mismatches.', '{Windows}', 'x-mitre-analytic--64c6aa46-a824-4c8e-8462-d0a58b78acfb', 'DET0538', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AllowedTools", "description": "Whitelist legitimate tunneling tools (e.g., used by admins)."}, {"field": "DataAsymmetryThreshold", "description": "Ratio of sent vs received bytes that indicates tunneling activity."}, {"field": "TimeWindow", "description": "Correlate process creation with network connection within N seconds."}]', '2026-05-01 15:26:35.434288');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (744, 'AN1147', 'Analytic 1147', 'Detection of file access from mounted SMB shares followed by copy or exfil commands from Terminal or script interpreter processes.', '{macOS}', 'x-mitre-analytic--67ca77c9-074f-4c93-9592-cabe9ba8a831', 'DET0410', '[{"name": "macos:unifiedlog", "channel": "filesystem and process events", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "fs:fsusage", "channel": "open/read/mount operations", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}]', '[{"field": "ProcessPath", "description": "Script interpreters may vary (e.g., zsh, bash, python, osascript)."}, {"field": "SharePath", "description": "Network drive mount points may differ across enterprises."}]', '2026-05-01 15:26:35.462033');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (727, 'AN0162', 'Analytic 0162', 'Correlate unauthorized or anomalous file modifications, deletions, or metadata changes with suspicious process execution or API calls. Detect abnormal changes to structured data (e.g., database files, logs, financial records) outside expected business process activity.', '{Windows}', 'x-mitre-analytic--64d6b35c-4785-4e2b-bc93-1f54f626a7a7', 'DET0059', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "MonitoredFilePaths", "description": "List of critical data directories or files; environment-specific tuning required."}, {"field": "TimeWindow", "description": "Threshold for correlating process execution with rapid data changes."}, {"field": "AuthorizedProcesses", "description": "Expected processes permitted to modify business-critical data."}]', '2026-05-01 15:26:35.435646');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (728, 'AN1981', 'Analytic 1981', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (729, 'AN0779', 'Analytic 0779', 'Detect unusual invocations of systemctl, service, or init scripts creating or modifying daemons. Monitor audit logs for execution of binaries from unexpected paths linked to service start/stop activity.', '{Linux}', 'x-mitre-analytic--65691cb3-a2b3-4c48-91d2-7088a047ebef', 'DET0279', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "systemctl start/enable with uncommon binary paths", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "ServiceBinaryPaths", "description": "Valid directories for service binaries to filter out benign changes"}, {"field": "UserContext", "description": "Expected accounts performing service management (e.g., root/admin)"}]', '2026-05-01 15:26:35.438378');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (730, 'AN0756', 'Analytic 0756', 'Adversary modifies tenant policy through changes to federation configuration, trust settings, or identity provider additions in Microsoft 365/AzureAD via Portal, PowerShell, or Graph API. Includes setting authentication to federated or updating federated domains.', '{"Identity Provider"}', 'x-mitre-analytic--65a1926d-e504-4153-b19f-555e8a06e5a5', 'DET0270', '[{"name": "m365:unified", "channel": "Set federation settings on domain|Set domain authentication|Add federated identity provider", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "azure:signinlogs", "channel": "OperationName=SetDomainAuthentication OR Set-FederatedDomain", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "OperationName", "description": "Identify rare modification operations that are not part of standard admin lifecycle."}, {"field": "InitiatedBy", "description": "Filter by known administrators or service principals. Flag unknown initiators."}, {"field": "UserAgent", "description": "Detect scripted modifications (e.g., PowerShell/Graph API vs Azure Portal)."}, {"field": "TimeWindow", "description": "Correlate tenant policy changes with new sign-ins or token forgery attempts."}]', '2026-05-01 15:26:35.43991');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (731, 'AN1553', 'Analytic 1553', 'macOS environmental validation behavioral chain: (1) System profiling through system_profiler, sysctl, and hardware discovery commands, (2) Network interface and configuration enumeration for geolocation and network environment validation, (3) Application installation and version discovery for software environment fingerprinting, (4) Security feature detection (SIP, Gatekeeper, XProtect status), (5) Conditional payload execution based on macOS-specific environmental criteria and System Integrity Protection bypass validation', '{macOS}', 'x-mitre-analytic--65abf5f4-ddb9-4eac-a926-1bef5d6b5c63', 'DET0562', '[{"name": "macos:unifiedlog", "channel": "process execution events for system discovery utilities (system_profiler, sysctl, networksetup, ioreg) with parameter analysis", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fileevents", "channel": "File system access events with kFSEventStreamEventFlagItemRemoved, kFSEventStreamEventFlagItemRenamed flags for environmental artifact collection (/System/Library, /usr/sbin, plist files)", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "MacOSDiscoveryTools", "description": "macOS-specific system discovery utilities commonly used for environmental validation"}, {"field": "SecurityFeatureEnumeration", "description": "Security features and configurations typically validated by macOS execution guardrails"}, {"field": "HardwareFingerprintBaseline", "description": "Normal hardware discovery patterns to distinguish from environmental validation attempts"}, {"field": "SIPBypassIndicators", "description": "Patterns indicating attempts to validate or bypass System Integrity Protection"}]', '2026-05-01 15:26:35.441627');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (732, 'AN1508', 'Analytic 1508', 'Abuse of extensible server modules (e.g., Apache, Nginx, Tomcat) to load rogue plugins that initiate bash, connect to C2, or spawn reverse shells.', '{Linux}', 'x-mitre-analytic--65f89c21-d42a-4028-9865-122ea1079a77', 'DET0547', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Module registration or stacktrace logs indicating segmentation faults or unknown module errors", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Outbound connections from web server binaries (apache2, nginx, php-fpm) to unknown external IPs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ServerBinaryPath", "description": "Alternate install paths like /opt/httpd or user-compiled binaries"}, {"field": "OutboundPortRange", "description": "Tunable to match expected versus suspicious outbound traffic patterns"}]', '2026-05-01 15:26:35.443228');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (733, 'AN1316', 'Analytic 1316', 'Cause→effect chain: (1) unified logs show application open/click or crash for Safari/Chrome/Office/Preview/archiver, (2) file write/extraction into ~/Downloads, /private/var/folders/* or ~/Library, (3) parent app spawns osascript/bash/zsh/curl/python or opens a quarantined app with Gatekeeper prompts, (4) network egress from child.', '{macOS}', 'x-mitre-analytic--66107cd1-c123-4ad5-bb0b-62d8a9a451a6', 'DET0478', '[{"name": "macos:unifiedlog", "channel": "opened document|clicked link|EXC_BAD_ACCESS|abort|LSQuarantine", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "fs:fileevents", "channel": "create/write/rename in user-writable paths", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:osquery", "channel": "exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "new outbound connection from exploited lineage", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "10–30 minute correlation window."}, {"field": "HighRiskChildren", "description": "osascript, bash, zsh, curl, python, open -a Terminal, installer, tccutil misuse."}, {"field": "QuarantineSignals", "description": "Flag new apps lacking com.apple.quarantine or with quarantine=''0081'' (downloaded then auto-opened)."}]', '2026-05-01 15:26:35.444729');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (734, 'AN1955', 'Analytic 1955', 'Monitor and analyze traffic patterns and packet inspection associated to protocol(s) that do not follow the expected protocol standards and traffic flows (e.g extraneous packets that do not belong to established flows, gratuitous or anomalous traffic patterns, anomalous syntax, or structure). Consider correlation with process monitoring and command line to detect anomalous processes execution and command line arguments associated to traffic patterns (e.g. monitor anomalies in use of files that do not normally initiate connections for respective protocol(s)).
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (735, 'AN1462', 'Analytic 1462', 'Execution of files with reversed filename extensions using Unicode RTLO character. Frequently used to deceive Gatekeeper and users in Safari or Mail-based phishing.', '{macOS}', 'x-mitre-analytic--667326a7-1f31-4ef1-92c1-6cb5241dadcf', 'DET0527', '[{"name": "macos:unifiedlog", "channel": "subsystem=com.apple.lsd", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:quarantine", "channel": "/var/log/quarantine.log", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "FilenameDisplay", "description": "Whether user-facing tools display the spoofed name or the true extension"}, {"field": "GatekeeperBypassFlag", "description": "Whether the execution bypassed translocation or quarantine checks"}, {"field": "UserContext", "description": "Scope detection to untrusted or non-admin users"}]', '2026-05-01 15:26:35.447675');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (736, 'AN0778', 'Analytic 0778', 'Monitor for abnormal creation or modification of Windows services (e.g., via sc.exe, PowerShell, or API calls) that load non-standard executables. Correlate registry changes in service keys with service creation events and process execution to detect service abuse for persistence or execution.', '{Windows}', 'x-mitre-analytic--667c21d2-2f92-42d6-aaea-b46974f63c8d', 'DET0279', '[{"name": "WinEventLog:Security", "channel": "EventCode=4697", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "ServiceAllowlist", "description": "Known good services and installers that regularly modify or create services"}, {"field": "TimeWindow", "description": "Threshold for correlating service creation with unusual process execution"}]', '2026-05-01 15:26:35.44903');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (737, 'AN0210', 'Analytic 0210', 'Detects embedded or emulated VBScript/VBA execution via Wine-based apps, Office for Mac abusing cross-platform .NET features, or macros dropped and invoked via AppleScript or third-party automation tools.', '{macOS}', 'x-mitre-analytic--668bc76f-04cc-4274-8a66-cfa00e83ef14', 'DET0076', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate ''eventMessage contains \"wscript\" OR \"vbs\"''", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:syslog", "channel": "system.log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ScriptLocation", "description": "Script run from ~/Downloads, ~/Library, or /tmp/"}, {"field": "EmulationContext", "description": "Wine or CrossOver launching legacy Windows scripting engines."}, {"field": "UserContext", "description": "VB execution from non-standard or shared users on endpoint."}]', '2026-05-01 15:26:35.450345');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (771, 'AN1190', 'Analytic 1190', 'Detects command-line tools, agents, or scripts making outbound HTTPS connections to popular web services like Discord, Slack, Dropbox, or Graph API in an unusual context.', '{Linux}', 'x-mitre-analytic--6e053521-1d6d-493f-8cd5-34f9a5992fc7', 'DET0425', '[{"name": "auditd:SYSCALL", "channel": "connect/sendto", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "conn.log, ssl.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ParentProcess", "description": "Unusual parent-child process behavior initiating external comms (e.g., bash > curl)"}, {"field": "HostnamePattern", "description": "Destination hostnames (e.g., *.dropboxapi.com, *.graph.microsoft.com)"}, {"field": "RequestFrequency", "description": "Repeated requests at unusual intervals, suggesting beaconing"}]', '2026-05-01 15:26:35.503404');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (738, 'AN0899', 'Analytic 0899', 'Adversaries create user accounts via identity provider APIs or admin portals (e.g., Azure AD, Okta). These accounts may be assigned elevated privileges or used in chained authentication. Detection monitors Add User activity from suspicious IPs or automation sources, followed by role/permission escalation.', '{"Identity Provider"}', 'x-mitre-analytic--668f1c2b-1a5e-4269-92d9-f7126764dd4e', 'DET0319', '[{"name": "azure:audit", "channel": "Add user", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "azure:audit", "channel": "Add member to role", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "azure:signinlogs", "channel": "Login from newly created account", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "IPAddress", "description": "Filter on IPs outside known admin networks or geographies"}, {"field": "RoleThreshold", "description": "Raise alert if total admins exceeds historical baseline"}, {"field": "ServicePrincipalFlag", "description": "Differentiate between user and service principal creation"}]', '2026-05-01 15:26:35.452583');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (739, 'AN0319', 'Analytic 0319', 'Detects use of dscl or id/group commands to enumerate local system groups, often by post-exploitation tools or persistence checks.', '{macOS}', 'x-mitre-analytic--66923fbc-1d4d-4945-89dd-102a8e2c6122', 'DET0114', '[{"name": "macos:unifiedlog", "channel": "process:exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLineContains", "description": "Match on specific dscl paths like ''/Groups'' or known enumeration options."}, {"field": "InteractiveSession", "description": "Used to scope out enumeration from user terminals versus background utilities."}]', '2026-05-01 15:26:35.453942');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (740, 'AN0541', 'Analytic 0541', 'Detection of anti-malware quarantining or flagging a tool, followed by a new binary written to disk with a similar function or name and a resumed process chain.', '{Linux}', 'x-mitre-analytic--66bab948-9baa-4f5c-b259-333eb2ac08ad', 'DET0189', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open, rename", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "linux:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "EDR:detection", "channel": "ThreatDetected, QuarantineLog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "PathWatchlist", "description": "Tunable list of directories often abused for dropped binaries (e.g., /tmp, ~/.cache, /opt/soft/)."}, {"field": "ProcessAncestryDepth", "description": "Limit how far up the tree to trace tool modification behavior for detection."}]', '2026-05-01 15:26:35.455337');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (741, 'AN1108', 'Analytic 1108', 'Unexpected file creation in web directories followed by web server processes (e.g., w3wp.exe) spawning command shells or script interpreters (e.g., cmd.exe, powershell.exe)', '{Windows}', 'x-mitre-analytic--66c98f78-2848-43f4-a69d-5562f03712ec', 'DET0394', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "NSM:Flow", "channel": "Inbound HTTP POST with suspicious payload size or user-agent", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "WebRootPath", "description": "Custom web server directory depending on IIS or third-party hosting environment"}, {"field": "ParentProcess", "description": "Different server binaries (e.g., php-cgi.exe, apache.exe) that may launch scripts"}]', '2026-05-01 15:26:35.457234');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (742, 'AN1069', 'Analytic 1069', 'Detects rogue Wi-Fi access points broadcasting the same SSID as legitimate APs with stronger signal strength, unexpected MAC/BSSID values, or inconsistent encryption settings. Correlates authentication attempts, captive portal redirections, and anomalous traffic flows through unauthorized APs.', '{"Network Devices"}', 'x-mitre-analytic--670462e3-6c3e-4779-af75-2a0424a5d221', 'DET0379', '[{"name": "WLANLogs:Association", "channel": "Multiple APs advertising the same SSID but with different BSSID/MAC or encryption type", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "Probe responses from unauthorized APs responding to client probe requests", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "networkdevice:syslog", "channel": "Failed authentication requests redirected to non-standard portals", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "KnownSSIDs", "description": "Baseline of authorized SSIDs; deviations may indicate rogue AP."}, {"field": "AllowedBSSIDs", "description": "Whitelist of BSSID/MAC addresses mapped to corporate SSIDs."}, {"field": "SignalStrengthThreshold", "description": "Used to flag unusually strong signals from unexpected APs."}, {"field": "CaptivePortalDomains", "description": "Trusted login domains; unrecognized portals may be malicious."}]', '2026-05-01 15:26:35.458911');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (743, 'AN0160', 'Analytic 0160', 'Detection of a process or script that accesses a common web service to retrieve content containing obfuscated indicators of a secondary C2 server (dead drop resolver behavior).', '{macOS}', 'x-mitre-analytic--671050c7-7e86-4be7-9ab4-aa9c763fad44', 'DET0058', '[{"name": "macos:unifiedlog", "channel": "subsystem: com.apple.network", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "process_events/socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TargetService", "description": "Known services abused for D2 (e.g., iCloud, Dropbox)"}, {"field": "UserContext", "description": "Useful to isolate rare users accessing web services for C2"}, {"field": "TimeWindow", "description": "Max time gap between dead drop resolver fetch and follow-on traffic"}]', '2026-05-01 15:26:35.460641');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (772, 'AN0746', 'Analytic 0746', 'Abuse of cloud messaging platforms to send mass spam or consume quota-based resources.', '{SaaS}', 'x-mitre-analytic--6e5bfc6b-3f07-426b-ac9f-6a8cc6b591c3', 'DET0267', '[{"name": "m365:unified", "channel": "SendMessage", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "saas:application", "channel": "High-volume API calls or traffic via messaging or webhook service", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MessageRateThreshold", "description": "Max allowable outbound message rate per user/account"}, {"field": "APIKeyList", "description": "Known authorized API clients for messaging usage"}]', '2026-05-01 15:26:35.504766');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (745, 'AN0349', 'Analytic 0349', 'Unusual modification or creation of loginwindow-related plist files in ''~/Library/Preferences/ByHost'' correlated with unauthorized application paths and execution upon login.', '{macOS}', 'x-mitre-analytic--67d1900f-9e02-4290-a14c-6d32be508d19', 'DET0125', '[{"name": "macos:unifiedlog", "channel": "Execution of process launched via loginwindow session restore", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:filesystem", "channel": "Modification or creation of files matching ''com.apple.loginwindow.*.plist'' in ~/Library/Preferences/ByHost", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "LoginWindow context with associated PID linked to reopened plist paths", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "macos:endpointsecurity", "channel": "es_event_file_rename_t or es_event_file_write_t", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "UserContext", "description": "Restrict to targeted users or unexpected users writing to plist"}, {"field": "FilePathPattern", "description": "Allow tuning for alternative persistence paths or directory redirection"}, {"field": "TimeWindow", "description": "Correlate plist write and process execution within logon window"}, {"field": "BinaryAnomalyScore", "description": "Optional scoring of launched binary based on code signing, entropy, and known safe apps"}]', '2026-05-01 15:26:35.463914');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (746, 'AN1622', 'Analytic 1622', 'Adversary modifies externally-facing web content by accessing and overwriting hosted HTML/JS/CSS files, typically following web shell deployment, credential abuse, or exploitation of web application vulnerabilities.', '{Windows}', 'x-mitre-analytic--67febd8b-36fe-4f72-8647-95fe449ecb5d', 'DET0590', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Connections", "channel": "Unusual POST requests to admin or upload endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "target_directory", "description": "Web root folder varies by environment, e.g., C:\\inetpub\\wwwroot"}, {"field": "UserContext", "description": "May vary based on which service account hosts the website"}, {"field": "TimeWindow", "description": "Time between webshell upload and file overwrite may vary"}]', '2026-05-01 15:26:35.465288');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (747, 'AN0616', 'Analytic 0616', 'Detects USB device insertion followed by high-volume or sensitive file access and staging activity by suspicious processes or accounts.', '{Windows}', 'x-mitre-analytic--67ff7cc5-7b9b-4d15-b115-b55c3d164c64', 'DET0220', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:System", "channel": "EventCode=2003", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "SensitiveFilePathRegex", "description": "Match data staging or export paths (e.g., *.docx, *.csv, *.db) to USB volume letters."}, {"field": "UserContext", "description": "Limit to users who do not normally use removable devices (e.g., service accounts)."}, {"field": "TimeWindow", "description": "Correlate events within a short period following USB insert (e.g., 5–10 minutes)."}]', '2026-05-01 15:26:35.466772');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (748, 'AN0311', 'Analytic 0311', 'Monitoring modification and execution of user or system logon scripts such as in registry Run keys or startup folders.', '{Windows}', 'x-mitre-analytic--682bd971-c540-4c16-a25a-b928201a320d', 'DET0112', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:TaskScheduler", "channel": "EventCode=106", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}]', '[{"field": "TargetObject", "description": "Registry path that may vary by user or policy configuration."}, {"field": "ParentProcessName", "description": "Can be tuned to known parent processes to reduce false positives."}, {"field": "TimeWindow", "description": "Logon activity clustered during specific user shifts."}]', '2026-05-01 15:26:35.468066');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (749, 'AN1574', 'Analytic 1574', 'Unusual ESXi processes (vmx, hostd) reading datastore files and generating outbound HTTPS traffic toward external cloud storage endpoints. Defender perspective: anomalous datastore activity followed by network transfers to Dropbox, AWS S3, or other storage services.', '{ESXi}', 'x-mitre-analytic--682f84f1-5571-4d41-b071-53c8f72a88f1', 'DET0570', '[{"name": "esxi:hostd", "channel": "datastore file access", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "esxi:vmkernel", "channel": "network flows to external cloud services", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "DatastoreTransferThreshold", "description": "Threshold for outbound data exfiltration from ESXi datastore files."}, {"field": "ApprovedStorageServices", "description": "Whitelist of sanctioned storage providers used by admins for backup operations."}]', '2026-05-01 15:26:35.469458');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (750, 'AN1443', 'Analytic 1443', 'Detects anomalous Kerberos activity such as forged or stolen tickets by correlating malformed fields in logon events, RC4-encrypted TGTs, or TGS requests without corresponding TGT requests. Also detects suspicious processes accessing LSASS memory for ticket extraction.', '{Windows}', 'x-mitre-analytic--685b05a6-92a3-417d-a917-8e7689e43237', 'DET0522', '[{"name": "WinEventLog:Security", "channel": "EventCode=4672, 4634", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "TicketLifetimeThreshold", "description": "Threshold for Kerberos TGT lifetimes deviating from domain defaults."}, {"field": "EncryptionTypes", "description": "Monitor for downgraded encryption types (e.g., RC4) in Kerberos tickets."}, {"field": "ProcessAllowlist", "description": "List of expected processes accessing LSASS; deviations may be suspicious."}]', '2026-05-01 15:26:35.470683');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (751, 'AN1413', 'Analytic 1413', 'Detects non-browser processes that establish encrypted outbound connections (e.g., TLS/SSL) to unfamiliar or atypical destinations for the host/user, following a data staging or compression event.', '{Windows}', 'x-mitre-analytic--6869578d-d3e8-4a3c-9717-0a188dc0bafe', 'DET0512', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "ssl.log - Certificate Analysis", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Correlates file access, encryption, and network transmission within a timeframe (e.g., 5 minutes)."}, {"field": "CertificateIssuerDenylist", "description": "Blocks or flags untrusted certificate authorities in SSL/TLS handshakes."}, {"field": "BinaryAllowlist", "description": "Whitelist for known-good applications allowed to use encrypted outbound traffic."}]', '2026-05-01 15:26:35.472137');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (752, 'AN1258', 'Analytic 1258', 'Non-standard port/protocol pairings or low-entropy ICMP traffic resembling tunneling patterns (e.g., fixed-size pings with delays).', '{"Network Devices"}', 'x-mitre-analytic--688ed638-d3ba-47dc-baa7-16b16a9fe9c8', 'DET0457', '[{"name": "NSM:Firewall", "channel": "ICMP/UDP protocol anomaly", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "conn.log, icmp.log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ProtocolEntropyThreshold", "description": "ICMP/UDP packet content entropy filter to identify encoded payloads."}, {"field": "SessionDurationThreshold", "description": "Long ICMP/UDP sessions beyond expected limits (e.g., >5min)."}]', '2026-05-01 15:26:35.473982');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (753, 'AN2024', 'Analytic 2024', 'Monitor logged domain name system (DNS) data for purchased domains that can be used during targeting. Reputation/category-based detection may be difficult until the categorization is updated. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Initial Access and Command and Control. 
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (754, 'AN0989', 'Analytic 0989', 'Monitors for processes reading sensitive files then immediately initiating unusual outbound connections or bulk transfer sessions over persistent sockets, particularly with encrypted or binary payloads.', '{Linux}', 'x-mitre-analytic--6914dd62-46a6-4de4-9c0b-afe1cb5b075d', 'DET0348', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "conn.log + files.log + ssl.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "session stats with bytes_out > bytes_in", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "OutboundEntropyScore", "description": "Threshold for high-entropy payloads indicative of encoded or encrypted exfil data."}, {"field": "ConnectionDuration", "description": "Defines length of time over which transfer size must be aggregated to trigger detection."}]', '2026-05-01 15:26:35.477001');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (755, 'AN0358', 'Analytic 0358', 'Adversary uses renamed container images, injects files into containers with misleading names or metadata (e.g., renamed system binaries), and executes them during startup or scheduled jobs.', '{Containers}', 'x-mitre-analytic--6927a2ad-c56f-4e87-9392-6e3eef07e57e', 'DET0127', '[{"name": "containerd:runtime", "channel": "/var/log/containers/*.log", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "docker:events", "channel": "docker.events.json", "x_mitre_data_component_ref": "x-mitre-data-component--b597a220-6510-4397-b0d8-342cd2c58827"}, {"name": "ebpf:syscalls", "channel": "file_write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "ImageLabelMismatch", "description": "Tune detection based on mismatch between image name and labels"}, {"field": "StartupScriptLocation", "description": "Detect binaries added or modified in startup path (e.g., /entrypoint.sh)"}, {"field": "ProcessNamePattern", "description": "Allow tuning based on suspicious binary naming inside containers"}]', '2026-05-01 15:26:35.478317');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (756, 'AN0660', 'Analytic 0660', 'Detection of changes to /etc/rc.local.d/local.sh or rc.local during post-boot script execution with abnormal commands or additions.', '{ESXi}', 'x-mitre-analytic--69562961-14e6-42a7-9f8a-24ac00f6404e', 'DET0237', '[{"name": "esxi:syslog", "channel": "boot logs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:shell", "channel": "admin command usage", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "script_section", "description": "Tunable script section edited by adversary (beginning, end, inline)"}, {"field": "command_type", "description": "Nature of embedded command or payload affects detection scope"}, {"field": "execution_trigger", "description": "Boot vs. manual script re-invocation"}]', '2026-05-01 15:26:35.480628');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1548, 'AN0815', 'Analytic 0815', 'Detects registration of new PTA agents, conditional access changes disabling hybrid MFA enforcement, or suspicious updates to AD FS token-signing configurations.', '{"Identity Provider"}', 'x-mitre-analytic--e1063b92-9be0-4d25-9df5-bae4171c8153', 'DET0293', '[{"name": "azure:signinlogs", "channel": "Register PTA Agent or Modify AD FS trust", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:unified", "channel": "New agent registration by non-admin user", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "PrivilegedRoles", "description": "Roles authorized to configure PTA/AD FS integrations."}]', '2026-05-01 15:26:36.664222');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (757, 'AN0198', 'Analytic 0198', 'Detects remote write activity across cloud VMs or object storage buckets within the same region/account that correlate with data aggregation across hosts.', '{IaaS}', 'x-mitre-analytic--696b98e8-10fd-4c7a-bb80-302baca34e60', 'DET0071', '[{"name": "AWS:CloudTrail", "channel": "GetObject, CopyObject", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"name": "AWS:VPCFlowLogs", "channel": "Traffic between instances", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "esxi:hostd", "channel": "process execution across cloud VM", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "BucketNamePatterns", "description": "Destination naming convention used for staging (e.g., temp-store)"}, {"field": "IAMContext", "description": "IAM role or user performing multi-host write ops"}, {"field": "TransferWindow", "description": "Burst of high-volume inter-VM transfers indicating staging"}]', '2026-05-01 15:26:35.481992');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (758, 'AN1040', 'Analytic 1040', 'Execution of file enumeration commands (e.g., ''dir'', ''tree'') from non-standard processes or unusual user contexts, followed by recursive directory traversal or access to sensitive locations.', '{Windows}', 'x-mitre-analytic--69d9d158-aa43-4b73-b9a4-f1a2dc6c13c1', 'DET0370', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "CommandLineRegex", "description": "Allows tuning based on tools/scripts used for enumeration (e.g., tree, dir /s /b)"}, {"field": "UserContext", "description": "Scoping for standard vs elevated or service accounts"}, {"field": "TimeWindow", "description": "Defines burst activity over short periods (e.g., >50 directory queries in 30s)"}]', '2026-05-01 15:26:35.483401');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (759, 'AN0560', 'Analytic 0560', 'Execution of `ifconfig`, `ip a`, or access to `/proc/net/` indicating collection of local interface and route configuration.', '{Linux}', 'x-mitre-analytic--6a57daad-9d2c-4851-a46e-b6ebac607a4c', 'DET0195', '[{"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLinePattern", "description": "Match regex for variations in enumeration syntax (e.g., `ip -4 addr show`)"}, {"field": "InteractiveShellIndicator", "description": "Differentiate scripted versus interactive sessions"}]', '2026-05-01 15:26:35.48478');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (760, 'AN0060', 'Analytic 0060', 'Correlates zsh shell configuration file changes (e.g., ~/.zshrc, ~/.zlogin, /etc/zprofile) with execution of unauthorized binaries or unexpected network activity triggered on Terminal.app launch.', '{macOS}', 'x-mitre-analytic--6acf01f9-723e-499b-8774-3fa689a36ded', 'DET0020', '[{"name": "macos:unifiedlog", "channel": "launch of Terminal.app or shell with non-standard environment setup", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_WRITE, targeting .zshrc, .zlogin, .zprofile", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "FileTargetList", "description": "Customizable list of shell config files considered sensitive for detection."}, {"field": "PayloadEntropyThreshold", "description": "Used to distinguish benign from potentially obfuscated commands written to config files."}, {"field": "UserContext", "description": "Scoping based on user login class, e.g., administrative vs standard users."}]', '2026-05-01 15:26:35.486045');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (761, 'AN1477', 'Analytic 1477', 'Detects unauthorized wireless associations by monitoring wpa_supplicant logs, NetworkManager events, and system calls related to interface state changes. Anomalies include repeated association failures, new SSIDs outside baselined values, and rogue AP connections.', '{Linux}', 'x-mitre-analytic--6ad3d8bb-fc6f-45fb-b44e-871c263230d8', 'DET0536', '[{"name": "linux:syslog", "channel": "New Wi-Fi connection established or repeated association failures", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "auditd:SYSCALL", "channel": "ioctl: Changes to wireless network interfaces (up, down, reassociate)", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AllowedSSIDRegex", "description": "Regex-based whitelist of corporate SSIDs; anomalous matches indicate suspicious activity."}, {"field": "RetryThreshold", "description": "Number of failed association attempts allowed before triggering detection."}]', '2026-05-01 15:26:35.487188');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (762, 'AN1540', 'Analytic 1540', 'Identify use of ''shutdown'', ''reboot'', or ''osascript'' system shutdown invocations within unified logs and track unexpected shutdown sequences initiated by GUI or script. Cross-reference with user activity or absence thereof.', '{macOS}', 'x-mitre-analytic--6b11c208-4dbf-4d52-9254-524e622c6250', 'DET0559', '[{"name": "macos:unifiedlog", "channel": "shutdown -h now or reboot", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "System shutdown or reboot requested", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "LaunchMechanism", "description": "Scripted vs interactive shutdowns."}, {"field": "LogGranularity", "description": "May vary depending on macOS version and unified log verbosity."}]', '2026-05-01 15:26:35.488594');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (769, 'AN0199', 'Analytic 0199', 'Detects adversary use of logon script configuration via Group Policy or user object attributes, followed by script execution post-authentication. Behavior includes modification of script path or file, then process execution under user logon context.', '{Windows}', 'x-mitre-analytic--6dae9309-90a7-4b4e-b764-9486a7ba4390', 'DET0072', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:System", "channel": "EventCode=1502, 1503", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "script_path_keywords", "description": "Defenders may tune for known script locations such as NETLOGON, SYSVOL, or \\domain\\sysvol\\*.bat/.ps1"}, {"field": "execution_time_window", "description": "May be scoped to user logon hours or first X minutes post-authentication"}, {"field": "user_context", "description": "Organizations may focus on specific users/groups with high privilege or remote access"}]', '2026-05-01 15:26:35.499576');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (763, 'AN0094', 'Analytic 0094', 'Defenders can observe suspicious replacement or tampering of system accessibility binaries (e.g., utilman.exe, sethc.exe, osk.exe) and anomalous modifications to registry keys used to redirect accessibility programs (such as IFEO keys). Additionally, execution of cmd.exe or other suspicious binaries triggered from the login screen by SYSTEM can be correlated as part of a behavior chain.', '{Windows}', 'x-mitre-analytic--6b5b9cd2-f6ba-4ed5-bea2-30edbf85501e', 'DET0033', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "TimeWindow", "description": "Time between registry modification and suspicious binary execution (e.g., < 1 hour) can be tuned."}, {"field": "TargetBinaryNames", "description": "Specific binaries monitored (e.g., utilman.exe, sethc.exe) can be adjusted per OS version and risk tolerance."}, {"field": "ParentProcess", "description": "Parent process of cmd.exe (e.g., winlogon.exe) may vary across legitimate and adversarial cases."}, {"field": "UserContext", "description": "Context of SYSTEM account execution vs. administrative sessions may influence tuning."}, {"field": "CommandLineContains", "description": "Tunable patterns such as launching cmd.exe, powershell, or LOLBins from accessibility binaries."}]', '2026-05-01 15:26:35.490411');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (764, 'AN1498', 'Analytic 1498', 'Applications or launchd services invoking RSA or public-key routines from the Security framework, followed by outbound SSL/TLS sessions with unrecognized certs or anomalous handshakes. Defender observes unified logs of API calls and suspicious network entropy.', '{macOS}', 'x-mitre-analytic--6b63caad-5d8d-4f23-be77-4e81d8904da6', 'DET0543', '[{"name": "macos:unifiedlog", "channel": "Process invoking SecKeyCreateRandomKey or asymmetric crypto APIs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "TLS connections with abnormal handshake sequence or self-signed cert", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TrustedDoHEndpoints", "description": "Known legitimate DoH/SSL endpoints."}, {"field": "PayloadEntropyThreshold", "description": "Entropy scoring for outbound payloads."}]', '2026-05-01 15:26:35.492155');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (765, 'AN1219', 'Analytic 1219', 'Detects firmware or script relocation attempts (e.g., CLI-based `copy`, `move`, or `rename`) between temporary partitions and config startup folders on routers or switches.', '{"Network Devices"}', 'x-mitre-analytic--6b8a97fe-4e51-4409-9eab-f2795eb2ec74', 'DET0439', '[{"name": "networkdevice:syslog", "channel": "command audit", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "StartupConfigPath", "description": "Targeted config folders like flash:/startup-config or nvram:"}, {"field": "CommandPatternMatch", "description": "e.g., `copy tftp flash`, `rename`, `move flash:/old.bin flash:/new.bin`"}]', '2026-05-01 15:26:35.493594');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (766, 'AN0850', 'Analytic 0850', 'Exploitation of system or application vulnerability (e.g., CVE-based exploit) followed by service crash, restart, or repeated failure within a short time frame, impacting application/system availability.', '{Windows}', 'x-mitre-analytic--6bb68520-c27e-435a-86b5-eb2ce7841cb2', 'DET0304', '[{"name": "WinEventLog:Application", "channel": "EventCode=1000", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:System", "channel": "EventCode=7031, 7034", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "TimeWindow", "description": "Time window between repeated service crashes or restarts (e.g., 5 crashes within 1 hour)"}, {"field": "TargetApplication", "description": "Critical applications to monitor based on environment (e.g., web server, database, VPN)"}]', '2026-05-01 15:26:35.494979');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (767, 'AN1335', 'Analytic 1335', 'Identifies abuse of odbcconf.exe to execute malicious DLLs using the REGSVR command flag. Behavior chain: (1) Process creation of odbcconf.exe with /REGSVR or /A {REGSVR ...} arguments → (2) DLL load by odbcconf.exe of non-standard or unsigned modules → (3) Optional follow-on process creation or network activity from loaded DLL.', '{Windows}', 'x-mitre-analytic--6c0a2e08-debd-46e6-bb5f-5159ad8f12ad', 'DET0486', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ParentProcessName", "description": "List of approved processes that may legitimately invoke odbcconf.exe"}, {"field": "AllowedCommandPatterns", "description": "Known-good odbcconf.exe arguments in the environment"}, {"field": "TimeWindow", "description": "Time range for correlating module loads and network activity after odbcconf.exe execution"}, {"field": "ApprovedModuleHashes", "description": "Baseline of legitimate DLLs loaded by odbcconf.exe"}]', '2026-05-01 15:26:35.496924');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (768, 'AN1544', 'Analytic 1544', 'Detection of valid account misuse through SSH logins, sudo/su abuse, and service account anomalies outside expected patterns.', '{Linux}', 'x-mitre-analytic--6cf46787-028d-4ac8-9dfa-58682edb3625', 'DET0560', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "sshd or PAM logins", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "UserContext", "description": "Identify logins to root or sudoers not aligned with normal usage profiles."}, {"field": "HostDensityThreshold", "description": "Number of unique systems a user authenticates to in a time window."}, {"field": "LoginMethod", "description": "Trigger on rarely used access methods such as password instead of SSH key."}]', '2026-05-01 15:26:35.498308');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (773, 'AN1033', 'Analytic 1033', 'Detects adversary behavior where a file with a benign-looking first extension (e.g., .txt, .jpg) ends with a dangerous second extension (e.g., .exe, .scr), and is subsequently executed. The behavior chain includes file creation with misleading naming and user or system-initiated process execution from the disguised file.', '{Windows}', 'x-mitre-analytic--6eab694d-ea06-4487-99c4-0e21279530e8', 'DET0366', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "benign_extensions", "description": "List of extensions typically used to masquerade malicious files (.txt, .jpg, .doc, .pdf)"}, {"field": "dangerous_extensions", "description": "List of true executable extensions that may be abused (.exe, .scr, .hta, .lnk)"}, {"field": "monitored_paths", "description": "Specific directories to focus on (e.g., Downloads folder, %TEMP%, Desktop)"}, {"field": "TimeWindow", "description": "Duration between file creation and process execution to correlate activity"}, {"field": "UserContext", "description": "Whether the behavior occurs in a standard user session or elevated context"}]', '2026-05-01 15:26:35.506382');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (774, 'AN1375', 'Analytic 1375', 'A process creates a brand‑new logon session/token (LogonUser*/LsaLogonUser) and then assigns/impersonates it (SetThreadToken/ImpersonateLoggedOnUser) to run actions under that freshly created security context. Chain: (1) suspicious command or script block (e.g., runas /netonly, PowerShell P/Invoke of LogonUser) → (2) ETW/API evidence of LogonUser*/SetThreadToken → (3) Security 4624 New Logon (often LogonType=9 NewCredentials or 2/3 from a non‑interactive parent) with no interactive desktop → (4) sysmon 1 process(es) executing with the new LogonId/SID different from the parent process → (5) optional privileged ops/lateral movement.', '{Windows}', 'x-mitre-analytic--6eab700a-548f-48aa-8821-163682fe8bbe', 'DET0498', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "etw:Microsoft-Windows-Security-Auditing", "channel": "api_call: LogonUser(A|W), LsaLogonUser, SetThreadToken, ImpersonateLoggedOnUser", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "TimeWindow", "description": "Correlation window between LogonUser*/SetThreadToken and the first spawned process (default 5–10 minutes)."}, {"field": "SuspiciousLogonTypes", "description": "Which 4624 LogonTypes to treat as high risk (e.g., 9 NewCredentials, 3 Network when sourced locally)."}, {"field": "AllowedImpersonators", "description": "Processes/accounts legitimately creating tokens (e.g., winlogon.exe, lsass.exe, IIS worker, trusted service accounts)."}, {"field": "ParentChildUserMismatch", "description": "Whether to alert on any SID/LogonId mismatch between parent/child not in allow-list."}, {"field": "IntegrityEscalationDelta", "description": "Minimum integrity level jump (e.g., Medium→High/System) to raise severity."}]', '2026-05-01 15:26:35.50858');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (775, 'AN0608', 'Analytic 0608', 'Detects adversary manipulation of Extra Window Memory (EWM) in a GUI process, where the attacker uses SetWindowLong or SetClassLong to redirect function pointers to injected shellcode stored in shared memory, then triggers execution via a window message like SendNotifyMessage.', '{Windows}', 'x-mitre-analytic--6ec034ac-289d-48d1-b310-021dfbf7087b', 'DET0217', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "etw:Microsoft-Windows-Win32k", "channel": "SetWindowLong, SetClassLong, NtUserMessageCall, SendNotifyMessage, PostMessage", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetWindowClassRegex", "description": "Regex to scope suspicious or uncommon GUI class names registered by user-created processes"}, {"field": "ExecutionTriggerWindowMessage", "description": "API calls like SendNotifyMessage or PostMessage that deliver execution to the shellcode location"}, {"field": "SharedSectionWriteThreshold", "description": "Set byte count thresholds on suspicious memory writes to known shared sections"}, {"field": "TimeWindowSetWindowLongToMessageTrigger", "description": "Define max time (e.g., <10s) between API call to set window memory and the message call to trigger it"}]', '2026-05-01 15:26:35.510729');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (776, 'AN0920', 'Analytic 0920', 'Detects files or processes where execution results in frequent re-creation or modification of ELF binaries or interpreter scripts, often using chmod + execve with abnormal entropy.', '{Linux}', 'x-mitre-analytic--6ed3efbf-c060-4c7f-8d8b-0e93f65a0790', 'DET0324', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "mmap", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "auditd:SYSCALL", "channel": "chmod", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "WriteExecThreshold", "description": "Tune to alert on write followed by chmod + exec in quick succession."}, {"field": "FileEntropyDeviation", "description": "Detect high deviation from average entropy score of baseline ELF/script files."}, {"field": "ExecutionFrequency", "description": "Abnormal burst executions of file with identical functionality but varying hash."}]', '2026-05-01 15:26:35.513016');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (777, 'AN0916', 'Analytic 0916', 'Detection of anomalous driver and firmware interactions, including unsigned or unexpected firmware updates, driver loads linked to hardware components, and suspicious use of privileged APIs to read/write firmware or controller memory.', '{Windows}', 'x-mitre-analytic--6f2fdf37-f603-4264-aed1-24fe2d1aa094', 'DET0323', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "firmware:integrity ", "channel": "Firmware integrity verification failures or mismatches against expected UEFI/firmware image baselines", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}]', '[{"field": "KnownGoodFirmwareHashes", "description": "Environment-specific list of baseline firmware images for integrity comparison"}, {"field": "DriverAllowList", "description": "Drivers approved for loading in production environments"}, {"field": "TimeWindow", "description": "Correlation period between firmware modification attempt and abnormal driver or process behavior"}]', '2026-05-01 15:26:35.51442');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (779, 'AN0248', 'Analytic 0248', 'Detection of file write-access to USB-mount directories (e.g., /media/, /run/media/) followed by same-file access or execution on another host.', '{Linux}', 'x-mitre-analytic--6f8fdb88-56d1-454e-9a35-3b7170011ca2', 'DET0090', '[{"name": "auditd:SYSCALL", "channel": "write/open, FIM audit", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "Removable media mount notification", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "MountPathPattern", "description": "Typical mount paths to monitor (e.g., /media/usb*, /run/media/username/*)."}, {"field": "TimeWindowBetweenHosts", "description": "Tunable detection window to correlate read/write between different hosts within a short interval (e.g., <15m)."}]', '2026-05-01 15:26:35.516946');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (780, 'AN0274', 'Analytic 0274', 'Behavioral chain: (1) An actor creates or modifies a BITS job via bitsadmin.exe, PowerShell BITS cmdlets, or COM; (2) the job performs HTTP(S)/SMB network transfers while the owning user is logged on; (3) upon job completion/error, BITS launches a notify command (SetNotifyCmdLine) from svchost.exe -k netsvcs -s BITS, often establishing persistence by keeping long-lived jobs. The strategy correlates process creation, command/script telemetry, BITS-Client operational events, and network connections initiated by BITS.', '{Windows}', 'x-mitre-analytic--6fba9520-c6ce-4a8f-8005-d33546a10406', 'DET0098', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:System", "channel": "EventCode=7036", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "TimeWindow", "description": "Correlation window linking job creation, transfer, and notify execution (e.g., 30m–24h depending on environment and BITS retry behavior)."}, {"field": "ExpectedUpdateHosts", "description": "Allow-list of corporate update/CDN endpoints that legitimately use BITS (WSUS, MEMCM, vendor updaters)."}, {"field": "SuspiciousCliSwitches", "description": "BITSAdmin flags of interest (/transfer, /addfile, /SetNotifyCmdLine, /resume, /setcustomheaders, /setminretrydelay)."}, {"field": "NotifyCmdBlockList", "description": "Known risky binaries or folders (e.g., %TEMP%\\*.exe, powershell.exe, cmd.exe) used as BITS notify commands."}, {"field": "UserContext", "description": "Scope by interactive users, service accounts, or high-value targets (admins/servers) to reduce benign noise."}, {"field": "ExternalNetCIDRs", "description": "Definition of external/non-corp destinations for network correlation."}, {"field": "JobLifetimeThreshold", "description": "Maximum age or retry count for benign jobs before flagging persistence (e.g., >3 days or retry>20)."}]', '2026-05-01 15:26:35.518416');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (781, 'AN1487', 'Analytic 1487', 'Detects suspicious OAuth application integrations within Office 365 or Google Workspace environments, such as new app registrations, unexpected consent grants, or privilege assignments. Defenders should correlate between application creation/modification events and associated user or service principal activity to identify persistence via app integrations.', '{"Office Suite"}', 'x-mitre-analytic--6feb9746-7b2c-4f6f-92c9-bfdb14eddddc', 'DET0539', '[{"name": "m365:unified", "channel": "Add app role assignment grant to user: Consent to application by privileged or unexpected accounts", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "azure:audit", "channel": "Consent to application: OAuth application consent granted to service principal", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "PrivilegedUserList", "description": "Defines which accounts are authorized to consent or register applications; deviations indicate possible adversary persistence."}, {"field": "ApplicationScopeThreshold", "description": "Defines which OAuth scopes are considered risky (e.g., Mail.ReadWrite, Files.ReadWrite.All)."}]', '2026-05-01 15:26:35.519808');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (782, 'AN1438', 'Analytic 1438', 'Detects log-clearing behavior by correlating suspicious command execution targeting log files under /var/log/, anomalous deletions or truncations of system logs, and unusual child processes (e.g., shell pipelines or redirections).', '{Linux}', 'x-mitre-analytic--6ffa0db8-a088-4e7a-b8e5-50a204762cca', 'DET0520', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "TimeWindow", "description": "The time window used to correlate log file interaction and suspicious command execution."}, {"field": "LogFilePathPattern", "description": "Regex pattern used to match monitored log file paths (e.g., /var/log/auth.log)."}, {"field": "UserContext", "description": "User or group (e.g., root) that should trigger higher severity detection."}]', '2026-05-01 15:26:35.521017');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (783, 'AN0846', 'Analytic 0846', 'Adversary enumeration of local user accounts using Net.exe, WMI, or PowerShell.', '{Windows}', 'x-mitre-analytic--6ffbdad6-3d60-452b-9e04-a8292d0125e9', 'DET0303', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLinePattern", "description": "Detects variations of ''net user'', ''net localgroup'', ''Get-LocalUser''."}, {"field": "UserContext", "description": "Restrict monitoring to low-privileged or unexpected users executing enumeration."}, {"field": "TimeWindow", "description": "Tune for bursts of enumeration commands in short succession."}]', '2026-05-01 15:26:35.522362');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (784, 'AN0588', 'Analytic 0588', 'Container orchestrator logs show crashlooping pods, repeated resource exhaustion, or malicious binaries with infinite loops consuming systemd/cgroup limits.', '{Containers}', 'x-mitre-analytic--7027622a-7a33-4189-a500-c54eef3467b6', 'DET0208', '[{"name": "kubernetes:events", "channel": "CrashLoopBackOff, OOMKilled, container restart count exceeds threshold", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "docker:events", "channel": "Container exited with non-zero code repeatedly in short period", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "RestartCountThreshold", "description": "Number of container restarts within a time window"}, {"field": "ContainerImageEntropy", "description": "Payload entropy of container image as an anomaly factor"}]', '2026-05-01 15:26:35.52427');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (785, 'AN2043', 'Analytic 2043', 'Detects processes or users modifying Windows Defender Firewall profiles, policies, or rules followed by measurable network exposure changes. Correlates firewall management execution, registry/policy mutation, service state changes, and subsequent inbound or outbound connectivity inconsistent with baseline administration.', '{Windows}', 'x-mitre-analytic--702db8b6-641f-4526-a0d0-a5a62c499508', 'DET0901', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"name": "WinEventLog:System", "channel": "EventCode=7036", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=5156, 5157", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AuthorizedAdminAccounts", "description": "Known administrators allowed to manage host firewall settings"}, {"field": "MaintenanceWindow", "description": "Approved change windows where firewall modifications are expected"}, {"field": "ExposureCorrelationWindow", "description": "Time window to correlate firewall change with new connections/listeners"}, {"field": "SensitivePorts", "description": "Ports of concern such as RDP, SMB, WinRM, SSH, custom admin ports"}, {"field": "AllowedManagementParents", "description": "Expected parent processes such as SCCM, Intune agent, GPO client"}, {"field": "RuleScopeThreshold", "description": "Detect widening from subnet/local scope to Any/0.0.0.0/0"}]', '2026-05-01 15:26:35.526014');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (786, 'AN0400', 'Analytic 0400', 'Processes that typically do not perform cryptographic operations loading symmetric encryption libraries (e.g., bcryptprimitives.dll, aes.dll), then initiating outbound connections with high-entropy payloads. Defender correlates process creation, DLL load, and anomalous encrypted traffic patterns.', '{Windows}', 'x-mitre-analytic--704bd588-a82b-4139-92ef-6dc6a48581c8', 'DET0143', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AllowedCryptoProcesses", "description": "Processes normally expected to use symmetric crypto (e.g., disk encryption, secure messaging)."}, {"field": "EntropyThreshold", "description": "Minimum payload entropy score for flagging unusual encrypted sessions."}, {"field": "TimeWindow", "description": "Correlation window between module load and encrypted connection creation."}]', '2026-05-01 15:26:35.527888');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (787, 'AN1341', 'Analytic 1341', 'Repeated failed authentication attempts to container APIs, control planes, or login shells across many user names using same password', '{Containers}', 'x-mitre-analytic--70500794-7d3d-4538-8e88-ed6d5e998a8a', 'DET0487', '[{"name": "kubernetes:audit", "channel": "Failed login", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "OrchestrationScope", "description": "Detect spray attempts scoped to single pod vs full cluster"}, {"field": "ServiceAccountFilter", "description": "Limit detection to non-service accounts to reduce noise"}]', '2026-05-01 15:26:35.529452');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (788, 'AN0535', 'Analytic 0535', 'Detection of attempts to disable or tamper with Windows Event Logging. This includes stopping or disabling the EventLog service, modifying registry keys related to EventLog and Autologger, using `auditpol` or `wevtutil` to disable categories or clear audit policies, and detecting suspicious gaps or resets in event logs. Defenders observe registry changes, service state changes, process execution of disabling commands, and anomalies in event record sequences.', '{Windows}', 'x-mitre-analytic--705168ad-1701-453c-9aea-c75029492b89', 'DET0187', '[{"name": "WinEventLog:System", "channel": "EventCode=7035", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "WinEventLog:Security", "channel": "EventCode=1102", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AuthorizedAdminAccounts", "description": "List of accounts authorized to legitimately modify audit policies or disable services."}, {"field": "TimeWindow", "description": "Correlation window between registry modification, service stop, and audit policy commands."}, {"field": "ServiceNames", "description": "Customizable set of monitored services such as EventLog, Sysmon, or custom loggers."}]', '2026-05-01 15:26:35.530672');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (789, 'AN1997', 'Analytic 1997', 'Monitor network data for uncommon data flows. Processes utilizing the network that do not normally have network communication or have never been seen before are suspicious.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (790, 'AN0897', 'Analytic 0897', 'Office or scripting applications initiating unusual HTTPS traffic to code repository APIs with high outbound-to-inbound ratios. Defender perspective: monitor for sensitive file access in combination with network connections to github.com, gitlab.com, or bitbucket.org.', '{macOS}', 'x-mitre-analytic--70b2ab8e-f18e-4cb5-8149-4ba2c334df69', 'DET0318', '[{"name": "macos:unifiedlog", "channel": "execution of curl, git, or Office processes with network connections", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "read of user document directories", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "outbound HTTPS connections to code repository APIs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MonitoredApplications", "description": "Applications not expected to upload large data sets to repos (Word, Excel, Preview)."}]', '2026-05-01 15:26:35.53328');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (791, 'AN0532', 'Analytic 0532', 'Repeated or automated access to user document directories or clipboard using shell scripts or utilities like xclip/pbpaste. Detectable via auditd syscall logs or osquery file events.', '{Linux}', 'x-mitre-analytic--70df3731-9576-4450-bd32-0f52cc8f0ec3', 'DET0186', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "AccessPath", "description": "Tunable location for sensitive files like /home/*/Documents."}, {"field": "ScriptInterpreterList", "description": "Shells or scripting engines to monitor (e.g., bash, python, perl)."}]', '2026-05-01 15:26:35.534577');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (792, 'AN0944', 'Analytic 0944', 'Detects usage of `at` command to schedule jobs, followed by job execution and modification of job files under /var/spool/cron/atjobs.', '{Linux}', 'x-mitre-analytic--70e28077-c8a6-425f-94c7-a74a7140c7ce', 'DET0333', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "AtJobPath", "description": "Monitoring additional paths (e.g., tmp-mounted spool dirs) for modified at jobs."}, {"field": "ScheduleLatency", "description": "Expected delay between at job creation and execution."}, {"field": "JobScriptEntropy", "description": "High entropy or obfuscation in at job payloads."}]', '2026-05-01 15:26:35.535962');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (793, 'AN0328', 'Analytic 0328', 'Links inbound network access to SSHD/SMB/NFS/Databases or custom daemons with subsequent daemon crash/restart, core dump, or spawning of shells/reverse shells from the service context, indicating remote exploitation.', '{Linux}', 'x-mitre-analytic--70e3066e-6ba3-444b-8e88-dfc3575f2706', 'DET0118', '[{"name": "linux:syslog", "channel": "kernel|systemd messages indicating ''segmentation fault''|''core dumped''|''service terminated unexpectedly'' for sshd, smbd, vsftpd, mysqld, httpd, etc.", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "auditd:SYSCALL", "channel": "execve of /bin/sh,/bin/bash,/usr/bin/curl,/usr/bin/python by service accounts (e.g., apache, mysql, nobody) immediately after inbound network activity.", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Inbound connections to monitored service ports from external or unusual internal sources; rapid follow-on lateral connections from the same host.", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ServiceNames", "description": "Linux daemons to watch (sshd, smbd, nfsd, httpd/nginx, mysqld, postgres, redis)."}, {"field": "CoreDumpPaths", "description": "Paths indicating crash artifacts (/var/crash, /var/lib/systemd/coredump)."}, {"field": "ShellSpawnAllowlist", "description": "Paths/users allowed to spawn shells from services (default: empty)."}, {"field": "TimeWindow", "description": "Correlation window (default 10m)."}]', '2026-05-01 15:26:35.53712');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (794, 'AN1424', 'Analytic 1424', 'Token retrieval from instance metadata endpoints such as AWS IMDS or Azure IMDS, followed by API usage using the obtained token from non-standard applications.', '{IaaS}', 'x-mitre-analytic--70f6482e-e93b-45a5-9b8c-ba7fd0c8220a', 'DET0515', '[{"name": "AWS:CloudTrail", "channel": "GetInstanceIdentityDocument or IMDSv2 token requests", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"name": "AWS:CloudTrail", "channel": "Use of temporary credentials issued from IMDS access", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "UserAgent", "description": "May need tuning for known automation tools versus unexpected curl usage"}, {"field": "TimeWindow", "description": "Correlate retrieval and use of token within expected timeout window"}]', '2026-05-01 15:26:35.538305');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (795, 'AN1951', 'Analytic 1951', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (796, 'AN1591', 'Analytic 1591', 'Creation of email forwarding/redirect rules in Exchange Online via New-InboxRule or transport rule cmdlets, including auto-forwarding address field usage.', '{"Office Suite"}', 'x-mitre-analytic--710aa303-3e9f-4170-95a4-b2caf5f827fd', 'DET0576', '[{"name": "m365:unified", "channel": "New-InboxRule, Set-InboxRule", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"name": "m365:messagetrace", "channel": "X-MS-Exchange-Organization-AutoForwarded", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ForwardingSMTPAddress", "description": "Destination domain may vary; commonly tuned per org policies."}, {"field": "ActorId", "description": "Differentiate service/admin users vs standard user population."}]', '2026-05-01 15:26:35.542045');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (797, 'AN0465', 'Analytic 0465', 'Defenders may observe unauthorized or anomalous changes to NAT configurations, including the addition of new translation rules or modifications to existing ones. Suspicious behaviors include sudden introduction of NAT mappings bridging segmented networks, new port address translation rules that obscure true source IPs, or traffic flows inconsistent with expected network design. Multi-event correlation includes detecting configuration changes on routers/firewalls, followed by traffic traversing unexpected internal/external address pairs.', '{"Network Devices"}', 'x-mitre-analytic--72033f2d-a943-40be-862c-051317ec541c', 'DET0163', '[{"name": "networkdevice:config", "channel": "NAT table modification (add/update/delete rule)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "Source/destination IP translation inconsistent with intended policy", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "Time correlation window between NAT rule change and unexpected traffic; adjustable to align with change management practices."}, {"field": "AuthorizedNATRules", "description": "Whitelist of approved NAT policies and rules; prevents false positives from legitimate operations."}, {"field": "TrafficVolumeThreshold", "description": "Threshold for abnormal traffic across NAT; tuned to differentiate testing from large-scale exfiltration or bridging."}, {"field": "InterfaceScope", "description": "Specific interfaces or zones monitored for NAT translation; allows tuning for internal vs. external-facing boundaries."}]', '2026-05-01 15:26:35.543631');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (798, 'AN0225', 'Analytic 0225', 'Adversary exploits public admin services on routers/firewalls/switches. Chain: anomalous HTTP/SNMP/SmartInstall inputs → device syslog errors/restarts → config changes/CLI spawn → egress to attacker C2.', '{"Network Devices"}', 'x-mitre-analytic--72298803-0644-477f-be89-01b173202577', 'DET0080', '[{"name": "networkdevice:controlplane", "channel": "Syslog from edge devices with HTTP 500s on mgmt portal, SmartInstall events, unexpected CLI commands", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "NetFlow/sFlow for odd egress to Internet from mgmt plane", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MgmtPorts", "description": "List of admin services to watch (8443, 443, 161/udp, 4786, 22)."}, {"field": "TrustedAdmins", "description": "Admin source ranges to allow."}]', '2026-05-01 15:26:35.544966');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (800, 'AN0137', 'Analytic 0137', 'An adversary writes or drops a malicious Office Add-in (e.g., WLL, XLL, COM) to a trusted directory or modifies registry keys to load malicious add-ins on Office application launch. Upon user opening Word or Excel, the add-in is automatically loaded, triggering execution of the payload, often spawning scripting engines or anomalous child processes.', '{Windows}', 'x-mitre-analytic--7263a8a8-a06f-4bdc-a021-3529ad683f9d', 'DET0050', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "AddInExtension", "description": "Malicious add-ins may have varying extensions (.wll, .xll, .dll, .vsto)"}, {"field": "TrustedPath", "description": "Office trusted add-in paths may differ across enterprise configurations"}, {"field": "RegistryPath", "description": "Registry keys used to load add-ins may be version- and app-specific"}, {"field": "ChildProcessName", "description": "Office processes spawning mshta.exe, powershell.exe, or rundll32.exe are abnormal"}, {"field": "TimeWindow", "description": "Add-in loading may occur only during Office launch windows"}]', '2026-05-01 15:26:35.548485');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (801, 'AN1145', 'Analytic 1145', 'Monitoring of file access to network shares (e.g., C$, Admin$) followed by unusual read or copy operations by processes not typically associated with such activity (e.g., PowerShell, certutil).', '{Windows}', 'x-mitre-analytic--72ba4979-f786-4205-a5da-90874e12813f', 'DET0410', '[{"name": "WinEventLog:Security", "channel": "EventCode=5145", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ShareName", "description": "Organizations may use custom share paths outside of default C$, Admin$, etc."}, {"field": "ProcessName", "description": "Common toolsets vary; defenders should tailor to unusual processes for their environment."}, {"field": "TimeWindow", "description": "Time of day and access duration may need to be tuned to reduce false positives."}]', '2026-05-01 15:26:35.549777');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (802, 'AN1277', 'Analytic 1277', 'Password spraying or brute force attempts across user pool within short time intervals', '{"Identity Provider"}', 'x-mitre-analytic--72bf9819-b0b5-43ab-9c2d-195abe8165b8', 'DET0463', '[{"name": "azure:signinlogs", "channel": "Sign-in logs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "UsernameSprayThreshold", "description": "Max number of accounts targeted from a single IP"}, {"field": "GeoAnomaly", "description": "Mismatch between user location and request location"}]', '2026-05-01 15:26:35.551158');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (803, 'AN0350', 'Analytic 0350', 'Adversary attempts to gain persistence by modifying ~/.ssh/authorized_keys via shell, text editor, echo or redirected output.', '{Linux}', 'x-mitre-analytic--72dd4fd9-b6cb-4704-b845-0632fe224995', 'DET0126', '[{"name": "auditd:SYSCALL", "channel": "write | PATH=/home/*/.ssh/authorized_keys", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Temporal window to correlate file writes and suspicious process launches (e.g., <60s)"}, {"field": "UserContext", "description": "Expected user-to-process correlation (e.g., root writing to non-root authorized_keys)"}, {"field": "TargetPath", "description": "Custom SSH path or user home variation (e.g., /etc/skel/.ssh/)"}]', '2026-05-01 15:26:35.552588');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (804, 'AN0093', 'Analytic 0093', 'Use of chflags hidden or SetFile -a V commands to hide files, or creation of hidden files with leading ''.''. Defender view: monitoring process execution and file metadata changes setting UF_HIDDEN attribute.', '{macOS}', 'x-mitre-analytic--73931643-7fae-409c-98b3-00bd88e246e0', 'DET0032', '[{"name": "macos:unifiedlog", "channel": "Execution of chflags hidden or SetFile -a V", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "File metadata updated with UF_HIDDEN flag", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "HiddenAttributeScope", "description": "Restrict detection to non-standard directories where hidden flags are unexpected."}]', '2026-05-01 15:26:35.553886');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (805, 'AN0255', 'Analytic 0255', 'Adversary runs commands like `whoami`, `id`, `w`, or `cat /etc/passwd` from non-interactive or scripting contexts to enumerate system user details.', '{Linux}', 'x-mitre-analytic--73b31f73-bc47-45c1-9c02-fd8eaacb2f9b', 'DET0093', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLineRegex", "description": "Tune detection based on argument presence (e.g., `cat /etc/passwd` vs. `cat` alone)"}, {"field": "ShellContext", "description": "Identify if command issued via cron, systemd, or reverse shell"}, {"field": "AccessFrequency", "description": "Define how often user/account commands are expected on endpoint"}]', '2026-05-01 15:26:35.555171');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (806, 'AN0086', 'Analytic 0086', 'Outlook form execution upon message receipt or client launch results in automated code execution within user session. Form definitions deviate from standard templates and include script logic or COM object calls embedded in form fields.', '{"Office Suite"}', 'x-mitre-analytic--73ec21b3-5679-44a9-bac3-943060bed786', 'DET0029', '[{"name": "m365:unified", "channel": "Unusual form activity within Outlook client, including load of non-default forms", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:messagetrace", "channel": "Inbound email triggers execution of mailbox-stored custom form", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AuditPolicyScope", "description": "Not all tenants may enable audit logs of custom form activity or COM component usage in Office"}, {"field": "MessageSenderAnomalyThreshold", "description": "Ruler-style delivery may come from external accounts with forged headers or low reputation"}, {"field": "FormExecutionRate", "description": "Frequency of form triggers may be anomalously high compared to baseline Outlook usage"}]', '2026-05-01 15:26:35.556915');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (807, 'AN0368', 'Analytic 0368', 'Detects file exfiltration using tools like curl, scp, or custom binaries over protocols such as FTP, HTTP/S, or DNS tunneling, especially outside baseline user behavior.', '{Linux}', 'x-mitre-analytic--7402eb3b-9349-478a-a8e9-7ee72c4b67c5', 'DET0131', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Flow", "channel": "NetFlow/Zeek conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ProtocolType", "description": "Flag unexpected protocols (e.g., HTTP on port 53 or FTP traffic from non-standard tools)."}, {"field": "UserContext", "description": "Scope for privilege escalation or service account behavior."}, {"field": "FileExtensionSensitivity", "description": "Track movement of file types of interest (e.g., `.csv`, `.sql`, `.key`)."}]', '2026-05-01 15:26:35.558683');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (808, 'AN0269', 'Analytic 0269', 'Addition of new users or changes to role permissions (e.g., ReadOnly -> Admin) via API or vSphere Client, particularly from non-jumpbox IPs.', '{ESXi}', 'x-mitre-analytic--74565d24-df58-49b6-86e0-01a03d6dc2a7', 'DET0096', '[{"name": "esxi:vpxa", "channel": "vim.SessionManager.login / vim.AccountManager.createUser", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}]', '[{"field": "VMAdminAccountName", "description": "Expected account name patterns for ESXi/vCenter admins."}, {"field": "NetworkAccessLocation", "description": "Expected IPs/subnets for legitimate ESXi access."}]', '2026-05-01 15:26:35.560323');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (809, 'AN1943', 'Analytic 1943', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (810, 'AN0554', 'Analytic 0554', 'Suspicious rule creation within Outlook or Exchange clients, including auto-move or delete conditions tied to incident or security alert keywords. Defender perspective: correlation between missing inbound emails and newly added mailbox rules.', '{"Office Suite"}', 'x-mitre-analytic--747a2974-0c77-4c47-9c02-2775025327c6', 'DET0192', '[{"name": "m365:unified", "channel": "Transport rule or inbox rule creation events", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "RuleScope", "description": "Decide whether to monitor individual mailbox rules, org-wide transport rules, or both."}]', '2026-05-01 15:26:35.562896');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (811, 'AN0005', 'Analytic 0005', 'Detects pub/sub traffic over unusual ports, high-frequency topic publications, and connections to known-bad or dynamic broker endpoints outside allowlisted infrastructure.', '{"Network Devices"}', 'x-mitre-analytic--748f457a-5dfa-431b-b5a0-3d5e1d56ebbb', 'DET0002', '[{"name": "NSM:Flow", "channel": "mqtt.log, xmpp.log, amqp.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "BrokerReputationList", "description": "Dynamic blocklist or threat intel feed for C2 brokers"}, {"field": "PayloadLengthThreshold", "description": "Exfil-style long topic messages vs telemetry-style short messages"}]', '2026-05-01 15:26:35.564097');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (812, 'AN0591', 'Analytic 0591', 'Use of domain accounts via sssd or winbind for logon activity outside of typical patterns, especially on sensitive systems or with lateral movement tools.', '{Linux}', 'x-mitre-analytic--74aade7b-b61a-46d0-a68b-33fba4f09f6e', 'DET0210', '[{"name": "auditd:SYSCALL", "channel": "pam_authenticate, sshd", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "linux:syslog", "channel": "sssd / sudo logs", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "HostnameScope", "description": "Filter to high-value systems (e.g., domain-joined servers)."}, {"field": "AccountDomain", "description": "Identify trusted domains versus external or misconfigured domains."}]', '2026-05-01 15:26:35.565431');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (813, 'AN1299', 'Analytic 1299', 'Detects script or binary modification within shared NFS/SMB directories followed by process execution from those paths.', '{Linux}', 'x-mitre-analytic--7518f788-43dd-440a-955c-870cdb7dea26', 'DET0471', '[{"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Flow", "channel": "smb_files.log", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}]', '[{"field": "MountPath", "description": "Mount path of monitored shared volumes (e.g., /mnt/shared)."}, {"field": "FilenamePattern", "description": "Pattern matching of abnormal or disguised filenames."}]', '2026-05-01 15:26:35.566715');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (814, 'AN0825', 'Analytic 0825', 'Detects unauthorized edits to system configuration profiles, unexpected certificate trust changes, or abnormal ARP/DNS patterns indicative of interception.', '{macOS}', 'x-mitre-analytic--7535f2e7-d7bb-4e92-8a63-36cd9ccc01be', 'DET0296', '[{"name": "macos:unifiedlog", "channel": "Configuration profile modified or new profile installed", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "TLS downgrade or inconsistent DNS answers", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ProfileIdentifiers", "description": "Known good vs suspicious configuration profiles per enterprise baseline."}, {"field": "TLSVersionThreshold", "description": "Minimum TLS version accepted in network traffic inspection."}]', '2026-05-01 15:26:35.567974');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (815, 'AN0573', 'Analytic 0573', 'Detects attempts to enumerate VMs via hypervisor tools like `virsh`, `VBoxManage`, or `qemu-img`. Defender correlates suspicious command invocations with parent process lineage and unexpected users.', '{Linux}', 'x-mitre-analytic--753ec5a6-9327-452e-ab9c-62b7206c24aa', 'DET0199', '[{"name": "auditd:SYSCALL", "channel": "execve: process_name IN (\"virsh\", \"VBoxManage\", \"qemu-img\") AND command IN (\"list\", \"info\")", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "NonRootAccounts", "description": "Monitor non-root users invoking hypervisor management utilities."}, {"field": "KnownAdminScripts", "description": "Whitelist of scripts expected to run VM enumeration as part of routine operations."}]', '2026-05-01 15:26:35.569225');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (818, 'AN0200', 'Analytic 0200', 'Abuse of systemctl to execute commands or manage systemd services. Defender perspective: correlate suspicious service creation or modification with execution of systemctl subcommands such as start, enable, or status. Detect cases where systemctl is used to load services from unusual locations (e.g., /tmp, /dev/shm) or where new service units are created outside of expected administrative workflows.', '{Linux}', 'x-mitre-analytic--756d5795-ef61-4115-80d2-f2e7440dff56', 'DET0073', '[{"name": "auditd:EXECVE", "channel": "execution of systemctl with subcommands start, stop, enable, disable", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "open/write of .service unit files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:EXECVE", "channel": "systemctl spawning managed processes", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:CONFIG_CHANGE", "channel": "creation or modification of systemd services", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "MonitoredPaths", "description": "Paths to monitor for service unit files, typically /etc/systemd/system and /usr/lib/systemd/system. Adversaries may use uncommon locations such as /tmp."}, {"field": "SuspiciousSubcommands", "description": "Focus on systemctl subcommands start, enable, or daemon-reload when used outside expected change windows."}, {"field": "CorrelationWindow", "description": "Time window to correlate service file modification with subsequent systemctl execution."}]', '2026-05-01 15:26:35.574789');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (819, 'AN0154', 'Analytic 0154', 'Detection of unexpected additions or modifications to system-wide certificate stores or execution of commands adding certificates to trusted stores.', '{Linux}', 'x-mitre-analytic--759c073c-2c40-484b-af47-8426ec5d5a3e', 'DET0056', '[{"name": "auditd:SYSCALL", "channel": "open, write: File modifications under /etc/ssl/certs, /usr/local/share/ca-certificates, or /etc/pki/ca-trust/source/anchors", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:EXECVE", "channel": "execve: Execution of update-ca-certificates or trust anchor modification commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CertificatePaths", "description": "Paths monitored for certificate modifications; can be tuned depending on Linux distribution."}, {"field": "AdminAccounts", "description": "Expected user accounts with privileges to install root certificates; anomalies outside this context are suspicious."}]', '2026-05-01 15:26:35.576367');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (820, 'AN0722', 'Analytic 0722', 'SaaS platforms may show forged credentials as unusual API keys, tokens, or session cookies being used without corresponding authentication. Correlated patterns include simultaneous valid sessions from multiple geographies, unusual API calls with new tokens, or bypass of expected MFA enforcement.', '{SaaS}', 'x-mitre-analytic--75d43d9f-7b54-4cd4-a6d9-523f8f9a60ff', 'DET0260', '[{"name": "m365:unified", "channel": "Session creation without MFA or login event", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}, {"name": "saas:auth", "channel": "API requests made with tokens not associated with expected user logins", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}]', '[{"field": "GeoLocationAlerts", "description": "Trigger on logins from unusual or high-risk geographies."}, {"field": "TokenReplayThreshold", "description": "Detect multiple simultaneous uses of the same forged credential."}]', '2026-05-01 15:26:35.577726');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (821, 'AN0767', 'Analytic 0767', 'An adversary leverages built-in tools such as certutil.exe, powershell.exe, or copy.exe to decode, reassemble, or extract hidden malicious content from obfuscated containers or encoded formats. The decoding utility often spawns shortly after file staging or download and may be chained with script interpreters or further payload execution.', '{Windows}', 'x-mitre-analytic--75f05a04-103c-432a-afd6-8a8987b4370e', 'DET0275', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "ToolName", "description": "May vary across environments (e.g., certutil, powershell, copy, expand, 7zip)"}, {"field": "FileExtensionFilter", "description": "Targets may use .txt, .cer, .enc, .b64, .zip, etc. to disguise payloads"}, {"field": "CommandLineRegex", "description": "Command syntax varies between base64 decoding, copy /b, and expand switches"}, {"field": "TimeWindow", "description": "Deobfuscation typically follows staging/download within a short timeframe"}]', '2026-05-01 15:26:35.579263');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (822, 'AN0316', 'Analytic 0316', 'Detects AS-REP roasting attempts by monitoring for Kerberos AS-REQ/AS-REP authentication patterns where preauthentication is disabled (Event ID 4768 with Pre-Auth Type 0). Correlates these requests with subsequent service ticket activity (Event ID 4769) and anomalies such as requests using weak RC4 encryption (etype 0x17). Excessive enumeration of accounts with ''Do not require Kerberos preauthentication'' set in Active Directory is another key detection point.', '{Windows}', 'x-mitre-analytic--7687688c-f91c-4487-948e-1d5b372fcdac', 'DET0113', '[{"name": "WinEventLog:Security", "channel": "EventCode=4768", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PreAuthDisabledAccountsBaseline", "description": "Baseline of accounts legitimately configured without Kerberos preauthentication; deviations may indicate adversary enumeration."}, {"field": "TGTRequestThreshold", "description": "Number of AS-REQ/AS-REP exchanges per account within a short timeframe; higher counts may indicate AS-REP roasting."}, {"field": "AllowedEncryptionTypes", "description": "Permitted Kerberos encryption algorithms; RC4 usage (etype 0x17) should be closely monitored."}, {"field": "TimeWindow", "description": "Correlation window for linking AS-REQs, AS-REPs, and subsequent service ticket requests."}]', '2026-05-01 15:26:35.580452');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (823, 'AN2022', 'Analytic 2022', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (824, 'AN0813', 'Analytic 0813', 'Execution of renamed or dropped files with a trailing space to deceive users or analysts, especially in LaunchAgents or LaunchDaemons.', '{macOS}', 'x-mitre-analytic--773188c7-6191-4ba4-ad39-b67ed8578dd9', 'DET0292', '[{"name": "macos:unifiedlog", "channel": "process events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "filesystem activity", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "FilenamePattern", "description": "Tunable regex or path rule to match common masquerade attempts (e.g., ''Terminal .app'')."}, {"field": "TargetPath", "description": "Analytic can be scoped to key directories (e.g., /Users/Library/LaunchAgents/)."}, {"field": "UserContext", "description": "Focus detection on suspicious user sessions or service creation under non-admin users."}]', '2026-05-01 15:26:35.582923');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (825, 'AN0416', 'Analytic 0416', 'Container process executes destructive file operations inside volume mounts or host paths. Includes `rm -rf /mnt/volumes/`, container breakout followed by host deletion attempts.', '{Containers}', 'x-mitre-analytic--7735a0b1-f3bc-44fc-a909-75738e77bded', 'DET0146', '[{"name": "auditd:SYSCALL", "channel": "unlink, unlinkat, rmdir", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "docker:events", "channel": "container exec rm|container stop --force", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "MountPoint", "description": "Identify when deletions occur inside persistent or shared volume paths."}, {"field": "ContainerImage", "description": "Correlate destructive behavior with unknown or untrusted container sources."}]', '2026-05-01 15:26:35.584082');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (826, 'AN1559', 'Analytic 1559', 'Detection of CLI commands that disable history logging such as ''no logging''. Anomalous lack of new commands in session logs while activity persists is a strong signal.', '{"Network Devices"}', 'x-mitre-analytic--77450309-6789-4025-9817-d908c4ac9e5b', 'DET0563', '[{"name": "networkdevice:cli", "channel": "Commands like ''no logging'' or equivalents that disable session history", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "DeviceVendors", "description": "Command syntax differs across Cisco, Juniper, Fortinet, etc., requiring vendor-aware tuning."}]', '2026-05-01 15:26:35.585255');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (827, 'AN1382', 'Analytic 1382', 'Detects GCC or Clang invoked on suspicious file paths (e.g., /tmp/, ~/Downloads) with output to executable binaries, followed by execution or outbound traffic from these binaries.', '{Linux}', 'x-mitre-analytic--774d555e-b94b-4dbd-bc3b-fb60d55e6e2d', 'DET0501', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open,create", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "CompilerBinaryPath", "description": "Specify path and binaries for detection (e.g., `/usr/bin/gcc`, `/opt/mingw/bin/gcc`)"}, {"field": "FilePermissionProfile", "description": "Match uncommon chmod behavior post-compilation (e.g., +x in `/tmp` or home directories)"}]', '2026-05-01 15:26:35.586426');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (828, 'AN0288', 'Analytic 0288', 'Detects modification of PAM configuration files, unauthorized new PAM modules, and suspicious process execution accessing PAM-related binaries. Correlates file modification events in /etc/pam.d/ with process execution of unauthorized binaries.', '{Linux}', 'x-mitre-analytic--776b9173-cbe0-4d1e-8ac9-af19b3db9dd7', 'DET0104', '[{"name": "auditd:SYSCALL", "channel": "open, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WatchedPaths", "description": "Critical PAM directories and configuration files monitored for modification."}]', '2026-05-01 15:26:35.587667');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (829, 'AN0715', 'Analytic 0715', 'Execution of known or custom VNC/remote desktop daemons or tunneling agents that initiate external communication after launch', '{Linux}', 'x-mitre-analytic--77769a6d-f3f4-42f1-a9a7-0d1096563115', 'DET0259', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "outbound connections to RMM services or to unusual destination ports", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "binary_name", "description": "Custom-compiled or renamed VNC servers (e.g., x11vnc, tightvncserver) may require local tuning"}, {"field": "OutboundIPRange", "description": "Destination IP or ASN may shift depending on geolocation of cloud-hosted RMM backends"}]', '2026-05-01 15:26:35.588998');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (830, 'AN0812', 'Analytic 0812', 'Detection of file execution where the file name contains a trailing space to masquerade as a known executable. Adversaries may exploit the way command line interpreters handle file names with trailing whitespace.', '{Linux}', 'x-mitre-analytic--778e2c18-2b26-4dd4-b4b2-3f8310d57a07', 'DET0292', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "application or system execution logs", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "ExecutableNameTrailingSpace", "description": "This detection may vary based on how different shells and file systems treat trailing spaces. Normalize or regex-match file names with trailing space."}, {"field": "UserContext", "description": "Monitor for untrusted or lower-privileged users executing suspicious scripts with disguised names."}, {"field": "TimeWindow", "description": "Tune for execution patterns during off-hours to reduce false positives."}]', '2026-05-01 15:26:35.590923');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (850, 'AN1118', 'Analytic 1118', 'Recurring network exfiltration initiated by scheduled or script-based processes exhibiting time-based regularity and consistent external destinations.', '{Windows}', 'x-mitre-analytic--79600919-afe8-4ac9-946c-147d85af6cfe', 'DET0399', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:System", "channel": "EventCode=106, 200", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}]', '[{"field": "TimeWindow", "description": "Duration threshold to consider a connection repetitive (e.g., same hour daily)"}, {"field": "DestIPAllowlist", "description": "Known external destinations to exclude (e.g., approved SFTP/backup servers)"}, {"field": "ParentProcessBaseline", "description": "Allowlisted job runners or scripts known to schedule legitimate transfers"}]', '2026-05-01 15:26:35.620103');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (831, 'AN1482', 'Analytic 1482', '1) pkg/notarization installs from atypical sources or with Gatekeeper/AMFI warnings; 2) new Mach-O written into /Applications or ~/Library paths or substitution of signed components; 3) first run from installer spawns unsigned children or exfil.', '{macOS}', 'x-mitre-analytic--779b2e27-9318-46a3-aeec-765f5fb09de3', 'DET0537', '[{"name": "macos:unifiedlog", "channel": "installer or system_installd ''PackageKit: install succeeded/failed'' with non-notarized or unknown signer", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:osquery", "channel": "launchd, processes", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:endpointsecurity", "channel": "write, rename", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Flow", "channel": "New egress from app just installed to unknown update endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AllowedTeamIDs", "description": "Apple Developer Team IDs permitted in your fleet."}, {"field": "TrustedDMGs", "description": "Known DMG/Pkg sources and hashes."}, {"field": "TimeWindow", "description": "Install→first-run correlation window (default 2h)."}, {"field": "RiskScoreThreshold", "description": "Adjust alert sensitivity based on org tolerance."}]', '2026-05-01 15:26:35.592659');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (832, 'AN1637', 'Analytic 1637', 'Detects adversary abuse of SaaS platform vulnerabilities to bypass logging, monitoring, or consent boundaries. Defender perspective focuses on abnormal application integration events, missing audit logs, or API calls from unauthorized service principals that align with exploitation attempts.', '{SaaS}', 'x-mitre-analytic--77c3b78a-fb34-4040-9dda-057e8eca3362', 'DET0595', '[{"name": "m365:unified", "channel": "ApplicationModified, ConsentGranted: Unexpected app consent or modification events linked to security evasion", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MonitoredApps", "description": "Applications and integrations expected in the environment; deviations may be suspect."}, {"field": "ConsentAnomalyThreshold", "description": "Threshold for anomalous OAuth or app consent events before flagging exploitation."}]', '2026-05-01 15:26:35.59435');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (833, 'AN1550', 'Analytic 1550', 'Adversary adds IDE extensions or plugins (VS Code, JetBrains Toolbox/EAP, Eclipse) via GUI or CLI, possibly via managed profiles. Chain: process start with install/update flags → plist/extension folder changes under ~/Library/Application Support/Code or ~/Library/Application Support/JetBrains → outbound connections to marketplaces/tunnel services → optional helper (ssh/node) spawned.', '{macOS}', 'x-mitre-analytic--77d3146f-2066-40a9-872e-ec05d7a4d6d1', 'DET0561', '[{"name": "macos:unifiedlog", "channel": "Execution of Code.app, idea, JetBrainsToolbox, eclipse with install/extension flags", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Writes under ~/Library/Application Support/Code*/extensions or JetBrains plugins", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "Outbound connections from IDE processes to marketplace/tunnel domains", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "PlistLocations", "description": "Per-app preference domains and plugin directories vary by version."}, {"field": "MDMProfiles", "description": "If MDM installs extensions, allowlist those events to avoid FPs."}, {"field": "TimeWindow", "description": "Correlation range between install and first beacon."}]', '2026-05-01 15:26:35.595966');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (834, 'AN1290', 'Analytic 1290', 'Detects rogue DHCP server activity and anomalous DHCP OFFER/ACK messages assigning unexpected DNS or gateway values. Detection correlates DHCP server role changes, DHCP exhaustion warnings, and sudden network configuration changes across endpoints.', '{Windows}', 'x-mitre-analytic--780021a3-d3e6-4c5b-a976-1c3715b990e2', 'DET0468', '[{"name": "WinEventLog:System", "channel": "EventCode=1341, 1342, 1020, 1063", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "DHCP OFFER or ACK with unauthorized DNS/gateway parameters", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AuthorizedDHCPServers", "description": "List of known DHCP servers; unexpected sources are suspicious."}, {"field": "TimeWindow", "description": "Interval to correlate DHCP OFFER/ACK anomalies with subsequent misconfigurations."}]', '2026-05-01 15:26:35.59728');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (835, 'AN0947', 'Analytic 0947', 'Creation or modification of cloud virtual machine images (AMIs, custom images) with persistence mechanisms, followed by infrastructure provisioning that uses these implanted images.', '{IaaS}', 'x-mitre-analytic--7845facb-50f2-4d32-ae00-6766b9410681', 'DET0334', '[{"name": "AWS:CloudTrail", "channel": "RegisterImage", "x_mitre_data_component_ref": "x-mitre-data-component--b008766d-f34f-4ded-b712-659f59aaed6e"}, {"name": "AWS:CloudTrail", "channel": "ModifyImageAttribute", "x_mitre_data_component_ref": "x-mitre-data-component--071a09b1-8945-46fd-8bb7-6bcc89400963"}, {"name": "AWS:CloudTrail", "channel": "RunInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}]', '[{"field": "IAMRole", "description": "Roles that are allowed to register and modify images should be scoped narrowly."}, {"field": "ImageTagRegex", "description": "Expected tags or naming patterns for images (e.g., ''golden-image'', ''base-image'')."}, {"field": "LaunchWindow", "description": "Time interval between image creation and instance launch."}]', '2026-05-01 15:26:35.598512');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (836, 'AN0382', 'Analytic 0382', 'Detects hosts transmitting large volumes of SMTP, IMAP, or POP3 traffic to external IPs or relays that aren''t associated with the enterprise mail infrastructure.', '{"Network Devices"}', 'x-mitre-analytic--784b7a50-cdc5-4161-8b52-2be5e5de19ac', 'DET0135', '[{"name": "NSM:Flow", "channel": "smtp.log, conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ExternalMailRelayFilter", "description": "Dest IPs not matching sanctioned SMTP/IMAP relays"}, {"field": "OutflowToInflowRatio", "description": "Outbound email bytes vastly exceed response"}]', '2026-05-01 15:26:35.600653');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (859, 'AN1493', 'Analytic 1493', 'Unauthorized instance creation in unmonitored or unused regions. Burst of compute-intensive jobs in spot instances or sudden spike in resource usage in legitimate VMs.', '{IaaS}', 'x-mitre-analytic--7a5e5aff-8395-4b4e-9072-dd765dae7d19', 'DET0540', '[{"name": "AWS:CloudTrail", "channel": "RunInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "AWS:CloudWatch", "channel": "Unusual CPU burst or metric anomalies", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "Region", "description": "Adversaries may deploy resources in rarely used or misconfigured regions."}, {"field": "TagKey", "description": "Used to evade detection with benign-looking tags or names."}]', '2026-05-01 15:26:35.634868');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (837, 'AN1447', 'Analytic 1447', 'Detects modification of System Integrity Protection (SIP) or code signing enforcement policies through csrutil or kernel variable tampering. Correlates execution of csrutil disable commands with subsequent policy state changes and anomalous unsigned process executions.', '{macOS}', 'x-mitre-analytic--7853421f-8eb4-49c3-9943-077430b97037', 'DET0523', '[{"name": "macos:unifiedlog", "channel": "csrutil disable", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "g_CiOptions modification or SIP state change", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "macos:unifiedlog", "channel": "Unsigned binary execution following SIP change", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PolicyPaths", "description": "Track configuration files and kernel extensions tied to SIP enforcement"}, {"field": "AllowedUsers", "description": "Restrict or expand which privileged accounts are monitored for SIP/CSRUTIL changes"}, {"field": "TimeWindow", "description": "Define correlation between csrutil execution and unsigned process activity"}]', '2026-05-01 15:26:35.601928');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (838, 'AN0635', 'Analytic 0635', 'Applications making outbound connections on non-standard ports or launchd services bound to ports inconsistent with system baselines.', '{macOS}', 'x-mitre-analytic--785c44d0-7e5b-4d3e-a3cd-0c5e96b8891b', 'DET0227', '[{"name": "macos:unifiedlog", "channel": "outbound TCP/UDP traffic over unexpected port", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:unifiedlog", "channel": "launchd services binding to non-standard ports", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "BaselinePortProfiles", "description": "Define expected macOS service port usage (e.g., AirDrop, Bonjour)."}]', '2026-05-01 15:26:35.603186');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (839, 'AN0919', 'Analytic 0919', 'Identifies self-modifying executables that exhibit changes in binary hash, entropy, or memory sections during or between executions—often tied to dynamic unpacking or decryption behaviors.', '{Windows}', 'x-mitre-analytic--786c54fa-8a9f-41bc-aa22-c4a4f6a93bd7', 'DET0324', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "EntropyThreshold", "description": "Tune based on expected baseline entropy for executables; higher values may indicate polymorphic packing."}, {"field": "TimeWindow", "description": "Correlate rapid process spawn + image load activity suggesting mutation engine usage."}, {"field": "ParentProcessPatterns", "description": "Define expected or suspicious parent-child chains (e.g., script runner -> encoded PE)"}]', '2026-05-01 15:26:35.604315');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (840, 'AN0471', 'Analytic 0471', 'Detects use of `clear history` or `clear logging` commands on network device CLI to remove past activity logs.', '{"Network Devices"}', 'x-mitre-analytic--7879313f-abf1-487a-b4d3-813f385ddce3', 'DET0165', '[{"name": "networkdevice:syslog", "channel": "CLI command audit", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandPattern", "description": "Support detection of known variants: ''clear history'', ''clear logging'', etc."}, {"field": "DeviceType", "description": "Router, switch, firewall—may have different CLI behaviors."}]', '2026-05-01 15:26:35.605702');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (841, 'AN1423', 'Analytic 1423', 'Access and retrieval of container service account tokens followed by unauthorized API requests using those tokens to interact with the Kubernetes API server or internal services.', '{Containers}', 'x-mitre-analytic--78821450-c84f-498f-abf2-b43211fa4218', 'DET0515', '[{"name": "kubernetes:audit", "channel": "GET or LIST requests to /var/run/secrets/kubernetes.io/serviceaccount/ followed by access to the Kubernetes API server", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "TimeWindow", "description": "Adjust based on how quickly tokens are expected to be used post-access"}, {"field": "UserContext", "description": "Tuning for known service accounts that legitimately access the API"}]', '2026-05-01 15:26:35.607359');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (842, 'AN1252', 'Analytic 1252', 'Detects behavioral chains where PowerShell is launched with encoded commands, unusual parent processes, or suspicious modules loaded, potentially followed by network connections or child process spawning. Supports detection of both direct (powershell.exe) and indirect (.NET automation) invocations.', '{Windows}', 'x-mitre-analytic--78864416-9ea3-4285-aab4-ecf31c935253', 'DET0455', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=400, 403", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "CommandLinePattern", "description": "Regex pattern for encoded, obfuscated, or hidden PowerShell arguments (e.g., ''-enc'', ''-nop'')."}, {"field": "ParentProcessName", "description": "Filter based on abnormal parents like Excel, WinWord, or mshta spawning PowerShell."}, {"field": "TimeWindow", "description": "Scope detection to off-hours, lateral movement timeframes, or non-maintenance windows."}, {"field": "LoadedModuleList", "description": "Tuneable to monitor rare or never-before-seen .NET assemblies tied to PowerShell abuse."}, {"field": "ScriptBlockLengthThreshold", "description": "Adjustable threshold for length of script blocks logged by Event ID 4104 (useful for filtering noise)."}]', '2026-05-01 15:26:35.609119');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (843, 'AN0720', 'Analytic 0720', 'On Linux systems, forged credentials may be injected into browser session files, curl/wget headers, or token caches in memory. Detection can leverage auditd to track processes accessing sensitive files (~/.mozilla, ~/.config/chromium, ~/.aws/credentials) and correlate with suspicious outbound connections.', '{Linux}', 'x-mitre-analytic--789849fe-7e94-4fd0-904b-02f8c9c0a696', 'DET0260', '[{"name": "auditd:SYSCALL", "channel": "Processes reading credential or token cache files", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "Outbound requests with forged tokens/cookies in headers", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CredentialFilePaths", "description": "Define which credential and session files should trigger monitoring."}]', '2026-05-01 15:26:35.610659');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (844, 'AN0229', 'Analytic 0229', 'Adversary modifies internal UI messages (e.g., login banners, desktop wallpapers) or hosted intranet web pages by creating or altering content files using scripts or unauthorized access. Often preceded by privilege escalation or web shell deployment.', '{Windows}', 'x-mitre-analytic--78c505c6-25a1-4cc5-b44a-0574aa019f01', 'DET0082', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "FilePathPattern", "description": "Location of web content or system UI config files that may vary across deployments (e.g., %SystemRoot%\\Web, %APPDATA%\\wallpaper.jpg)"}, {"field": "TimeWindow", "description": "Allowed hours for file/content modification events; defacement likely occurs during off-hours"}, {"field": "UserContext", "description": "System or domain accounts used to perform the modifications may be anomalous"}]', '2026-05-01 15:26:35.612076');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (845, 'AN0317', 'Analytic 0317', 'Detects attempts to enumerate local groups via Net.exe, PowerShell, or native API calls that precede lateral movement or privilege abuse.', '{Windows}', 'x-mitre-analytic--78f4f0fe-55ef-4598-85ac-865cba1920d3', 'DET0114', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Time window between group enumeration and lateral movement or privilege escalation activity."}, {"field": "UserContext", "description": "Whether the process was executed by a privileged or low-privilege account."}]', '2026-05-01 15:26:35.613809');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (846, 'AN0411', 'Analytic 0411', 'Adversary spawns command-line tools (e.g., del, cipher /w, SDelete) or scripts to recursively delete or overwrite user/system files. This may be correlated with abnormal file IO activity, registry writes, or tampering in critical system directories.', '{Windows}', 'x-mitre-analytic--791dfdd4-b04d-498a-accc-ee9e2acc7b14', 'DET0146', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=23", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "TargetFilename", "description": "Filter file deletion activity to sensitive locations (e.g., %System32%, Documents, DB paths)."}, {"field": "ProcessCommandLine", "description": "Tune for aggressive overwrite flags (e.g., /w, /q, /s) or temp file overwrites."}, {"field": "VolumeThreshold", "description": "Threshold of unique file deletions or modifications within time window."}, {"field": "TimeWindow", "description": "Correlate rapid file delete/overwrite behavior from same process/user."}]', '2026-05-01 15:26:35.615049');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (847, 'AN0745', 'Analytic 0745', 'High CPU usage by unauthorized containers running mining binaries or public proxy tools.', '{Containers}', 'x-mitre-analytic--791ea4ff-7a49-4aa7-a41c-51288031e0f0', 'DET0267', '[{"name": "containerd:events", "channel": "New container with suspicious image name or high resource usage", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "prometheus:metrics", "channel": "Container CPU/Memory usage exceeding threshold", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "container:cni", "channel": "Outbound network traffic to mining proxies", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ImageName", "description": "Suspicious or unknown container image used"}, {"field": "CPUQuotaThreshold", "description": "Container-level resource limits"}]', '2026-05-01 15:26:35.616336');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (848, 'AN0243', 'Analytic 0243', 'Monitors suspicious usage of Windows API calls like SetWindowsHookEx, GetKeyState, or polling functions within non-UI service processes, combined with Registry or driver modifications.', '{Windows}', 'x-mitre-analytic--7924d1b1-a512-425f-b397-9e9b9887b21b', 'DET0089', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TargetImage", "description": "Scope to sensitive GUI/session processes like winlogon.exe or osk.exe"}, {"field": "AccessMask", "description": "Can be tuned to 0x1fffff for full-access injection detection"}, {"field": "TimeWindow", "description": "Tunable for sustained polling or multiple registry edits in short succession"}]', '2026-05-01 15:26:35.617532');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (849, 'AN1607', 'Analytic 1607', 'Adversary creates users via IAM/IdP API or portal (e.g., Azure AD, Okta). Detection involves monitoring API calls, admin action logs, and correlation with role assignments.', '{"Identity Provider"}', 'x-mitre-analytic--7947aae5-fd76-403c-8c73-1300dff7d30f', 'DET0583', '[{"name": "azure:audit", "channel": "Add user", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}]', '[{"field": "AdminThreshold", "description": "Trigger alert only when account is assigned privileged roles"}, {"field": "AutomationExemptions", "description": "Exclude accounts from known automation processes or provisioning pipelines"}]', '2026-05-01 15:26:35.618764');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (879, 'AN0109', 'Analytic 0109', 'Correlate high-frequency or anomalous DNS query activity with processes that do not normally generate network requests (e.g., Office apps, system utilities). Detect pseudo-random or high-entropy domain lookups indicative of domain generation algorithms (DGAs).', '{Windows}', 'x-mitre-analytic--7cf1b4ad-95e8-4bf0-8b2f-fc3c14938656', 'DET0039', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "EntropyThreshold", "description": "Adjust based on environment to differentiate DGAs from legitimate CDNs"}, {"field": "TimeWindow", "description": "Interval for correlating bursts of DNS queries from the same process"}]', '2026-05-01 15:26:35.666146');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (851, 'AN0942', 'Analytic 0942', 'Detects execution of AutoHotKey or AutoIT interpreters or compiled scripts used for unauthorized automation, command execution, or payload delivery, correlated with anomalous process lineage, command-line arguments, or script creation events.', '{Windows}', 'x-mitre-analytic--7975ae39-8c6b-45cc-9280-98e94b666c85', 'DET0332', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "TimeWindow", "description": "Tuning this helps identify automation behavior outside expected user work hours."}, {"field": "ParentProcessName", "description": "Used to isolate cases where AHK or AutoIT scripts are spawned by suspicious or unusual processes."}, {"field": "ScriptExtension", "description": "Extensions such as .ahk, .au3, or unknown .exe names compiled from these."}, {"field": "ChildProcessCount", "description": "Threshold for number of spawned children to detect automation or modular malware behavior."}]', '2026-05-01 15:26:35.621363');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (852, 'AN0910', 'Analytic 0910', 'Execution of QEMU, KVM, or VirtualBox processes with unusual flags (e.g., ''-nographic'', ''-snapshot''). File creation of VM images in atypical directories. Defender view: monitoring audit logs for process executions and file modifications linked to hidden virtualization.', '{Linux}', 'x-mitre-analytic--79ba9430-eeb0-4fce-9757-bb81fc2a43d5', 'DET0321', '[{"name": "auditd:SYSCALL", "channel": "execve calls for qemu-system*, kvm, or VBoxHeadless", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "File creations of *.qcow2, *.vdi, *.vmdk outside standard VM directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ImageDirectoryWhitelist", "description": "Legitimate VM image storage paths to reduce false positives."}, {"field": "UserContext", "description": "Correlate suspicious VM execution with non-admin or service accounts."}]', '2026-05-01 15:26:35.622829');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (853, 'AN0561', 'Analytic 0561', 'Execution of `ifconfig`, `networksetup`, or `system_profiler` to query IP/MAC/interface configuration and status.', '{macOS}', 'x-mitre-analytic--79c196d7-abb8-4766-a875-4acafc6f059d', 'DET0195', '[{"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ScriptedContext", "description": "Scripted tools (e.g., bash calling `ifconfig`) vs GUI-initiated inspection"}, {"field": "ExecutionFrequency", "description": "Enumerations executed frequently or across multiple interfaces may indicate enumeration loops"}]', '2026-05-01 15:26:35.62465');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (854, 'AN0144', 'Analytic 0144', 'Detects excessive outbound traffic to remote host over HTTP(S) from uncommon or previously unseen processes.', '{Windows}', 'x-mitre-analytic--79c7d394-e772-479c-acf9-ddd05b8a68b9', 'DET0053', '[{"name": "NSM:Flow", "channel": "HTTP ", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "OutboundByteThreshold", "description": "Defines threshold ratio of outbound to inbound bytes that signals possible obfuscation"}, {"field": "ProcessAllowlist", "description": "List of known legitimate network clients to exclude from anomaly checks"}]', '2026-05-01 15:26:35.627427');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (855, 'AN1070', 'Analytic 1070', 'Adversaries collecting local files via PowerShell, WMI, or direct file API calls often include recursive file listings, targeted file reads, and temporary file staging.', '{Windows}', 'x-mitre-analytic--79ecfad5-3439-4a04-919a-236d47652ba0', 'DET0380', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "TargetFilePathRegex", "description": "Allows tuning for file extensions or paths of sensitive data (e.g., *.xls, *.db, *.pdf)."}, {"field": "ParentProcessFilter", "description": "Used to scope monitoring to suspicious parent/child process trees like PowerShell or WMI spawning file reads."}]', '2026-05-01 15:26:35.629507');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (856, 'AN0283', 'Analytic 0283', 'Detects use of tools/scripts accessing input devices like /dev/input/* or evdev via suspicious processes lacking GUI context.', '{Linux}', 'x-mitre-analytic--79f3bf7a-cf35-442c-b707-ba4dabd6ed62', 'DET0102', '[{"name": "auditd:SYSCALL", "channel": "open, read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "ptrace, ioctl", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "ProcessName", "description": "Unusual process accessing device files"}, {"field": "DevicePath", "description": "Typically /dev/input/*, but tunable to exact endpoint config"}]', '2026-05-01 15:26:35.630931');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (857, 'AN1283', 'Analytic 1283', 'Detection of default account usage such as Guest or Administrator performing interactive or remote logons on systems outside of installation or maintenance windows.', '{Windows}', 'x-mitre-analytic--7a3dd710-39a7-4327-8d3b-150c50b2c680', 'DET0465', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "UserContext", "description": "Default usernames like ''Administrator'' or ''Guest'' may be renamed or disabled by the organization. Detection logic should account for name changes."}, {"field": "TimeWindow", "description": "Restrict detection to unusual hours or outside of expected maintenance windows."}]', '2026-05-01 15:26:35.63235');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (858, 'AN0682', 'Analytic 0682', 'Detection of persistent login hooks configured via defaults or plist modifications that result in execution of scripts or binaries at user login, breaking expected parent-child process lineage.', '{macOS}', 'x-mitre-analytic--7a424183-94ca-4dc1-a03b-610d174aa973', 'DET0244', '[{"name": "macos:unifiedlog", "channel": "loginwindow or tccd-related entries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:plist", "channel": "/var/root/Library/Preferences/com.apple.loginwindow.plist", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "login_hook_path", "description": "Path of script or binary assigned to login hook; may vary by environment"}, {"field": "user_context", "description": "Login hook may be applied to specific user accounts; tune by privilege level"}, {"field": "time_window", "description": "Correlate plist file modification to execution within a short timeframe"}, {"field": "parent_process_name", "description": "Expected parent process (e.g., loginwindow); anomalies can indicate masquerading"}]', '2026-05-01 15:26:35.633572');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (860, 'AN0657', 'Analytic 0657', 'Phishing attachment detection on macOS through correlation of Mail app logs, file creation in user directories, and abnormal process execution (e.g., Preview.app or Mail.app spawning Terminal or scripting binaries). Network traffic after attachment interaction is also monitored.', '{macOS}', 'x-mitre-analytic--7a6192b4-997a-4526-bb3d-76664bc31274', 'DET0236', '[{"name": "macos:unifiedlog", "channel": "Inbound messages with attachments from suspicious domains", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "Execution of Terminal, osascript, or other interpreters originating from Mail or Preview", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Attachment files written to ~/Downloads or temporary folders", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ExecutionDelayThreshold", "description": "Time delay between attachment download and execution considered suspicious."}, {"field": "SuspiciousParentApps", "description": "Parent processes expected to rarely spawn child processes (e.g., Mail.app, Preview.app)."}]', '2026-05-01 15:26:35.636073');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (861, 'AN1463', 'Analytic 1463', 'Execution of user-downloaded or created scripts with hidden extensions due to RTLO character insertion in filename, often present in desktop environments or phishing campaigns.', '{Linux}', 'x-mitre-analytic--7a72f91d-9c16-4724-b87d-3e5448f81b51', 'DET0527', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "event-based", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "desktop:file_manager", "channel": "nautilus, dolphin, or gvfs logs", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ExtensionMismatch", "description": "Filter based on mismatched visible extension vs. magic bytes or mime-type"}, {"field": "ProcessLineage", "description": "Correlation between file open and subsequent script interpreter invocation"}, {"field": "FilenameEntropy", "description": "Suspicious Unicode sequences or byte entropy in filenames"}]', '2026-05-01 15:26:35.637493');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (862, 'AN1471', 'Analytic 1471', 'Credential-related configuration changes in productivity apps, such as API key creation in Google Workspace, app tokens in Slack, or user-level OAuth credentials in M365.', '{SaaS}', 'x-mitre-analytic--7a9088cb-cfe8-4a4a-979c-1ef7678179f2', 'DET0531', '[{"name": "gcp:audit", "channel": "API Key Created, OAuth Client Registered", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "m365:unified", "channel": "Set-Mailbox, Set-AppPassword, Add-MailboxPermission", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}]', '[{"field": "OAuthClientRedirectURIBaseline", "description": "Detect suspicious redirect URI mismatches in new clients."}, {"field": "TokenScopeSensitivity", "description": "Highlight credentials granting excessive read/write org-wide."}]', '2026-05-01 15:26:35.638882');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (863, 'AN0607', 'Analytic 0607', 'Detection focuses on unauthorized modification of Mach-O binaries to include LC_LOAD_DYLIB headers pointing to malicious dylibs. Behavior is identified via a chain of file metadata changes, removal of code signatures, and subsequent anomalous dylib loads at runtime. Correlation of file changes with lack of authorized updates and process memory mapping of unrecognized or unsigned libraries is crucial.', '{macOS}', 'x-mitre-analytic--7aaf568b-bc31-4fb0-8543-12ee281a0b85', 'DET0216', '[{"name": "macos:unifiedlog", "channel": "Process memory maps new dylib (dylib_load event)", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "macos:unifiedlog", "channel": "Mach-O binary modified or LC_LOAD_DYLIB segment inserted", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Code signature validation fails or is absent post-binary modification", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "TimeWindow", "description": "Correlates binary modification and dylib load within a defined time interval (e.g., 1 hour)"}, {"field": "DylibPathRegex", "description": "Regular expression to match known malicious or uncommon library paths"}, {"field": "UnsignedDylibThreshold", "description": "Number of unsigned or unrecognized dylibs mapped into memory per process"}, {"field": "UserContext", "description": "Scope monitoring to non-admin users or sensitive system directories"}]', '2026-05-01 15:26:35.640798');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (864, 'AN1492', 'Analytic 1492', 'Ephemeral or unauthorized container instantiation using public images (e.g., from DockerHub) that initiate high CPU usage shortly after startup. Often scheduled via Kubernetes or Docker socket abuse.', '{Containers}', 'x-mitre-analytic--7ac026eb-9a3b-49fe-b7ec-7261cb6d6191', 'DET0540', '[{"name": "containerd:events", "channel": "create", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Outbound traffic to mining pool upon container launch", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ImageSource", "description": "May vary depending on where the image is pulled from (registry or custom URL)."}, {"field": "Namespace", "description": "Helps differentiate attacker-created namespaces."}]', '2026-05-01 15:26:35.642807');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (865, 'AN1613', 'Analytic 1613', 'Enumeration of users and groups through suspicious shell commands or unauthorized access to /etc/passwd or /etc/shadow.', '{Linux}', 'x-mitre-analytic--7b0d80c0-807e-46b1-b3f7-fd3e4f3aceba', 'DET0587', '[{"name": "auditd:SYSCALL", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AccessedFile", "description": "Tune based on file paths such as ''/etc/passwd'', ''/etc/group'', ''/etc/shadow''."}, {"field": "ParentProcessName", "description": "Filter known admin processes to reduce false positives."}]', '2026-05-01 15:26:35.644468');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (866, 'AN0479', 'Analytic 0479', 'Shell script or binary uses multiple system commands (e.g., dmidecode, lscpu, lspci) in quick succession to detect virtualization environment', '{Linux}', 'x-mitre-analytic--7b4b3b54-d992-4f03-922a-6eec96c9342e', 'DET0168', '[{"name": "auditd:SYSCALL", "channel": "execve of system tools like dmidecode, lspci, lscpu, dmesg, systemd-detect-virt", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Burst of system info commands within X seconds"}, {"field": "CommandPattern", "description": "Regex or substring matching virtualization artifact checks"}]', '2026-05-01 15:26:35.646224');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (867, 'AN0692', 'Analytic 0692', 'IAAS (Cloud images/VMs): A new VM/instance is launched from a non-approved or newly-seen image (AMI/GCP Image/Azure Image). On first boot, cloud-init/user-data or embedded agents download code, spawn system utilities, or open outbound C2/mining traffic. The analytic correlates Instance/Image Creation → Instance Start → in-guest Process/Command Execution and/or anomalous network traffic.', '{Windows}', 'x-mitre-analytic--7b711402-12f7-4985-93df-2693eaf9ebdb', 'DET0248', '[{"name": "AWS:CloudTrail", "channel": "RunInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "azure:activity", "channel": "Microsoft.Compute/virtualMachines/write: imageReference publisher NOT IN allowlist OR plan is new/unknown", "x_mitre_data_component_ref": "x-mitre-data-component--b5b0e8ae-7436-4951-950a-7b83c4dd3f2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "New VM egress to crypto-mining pools or non-approved Internet ranges within minutes of boot", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ApprovedImageCatalog", "description": "Set of golden images/owners and digest/IDs allowed to launch."}, {"field": "UserDataInspection", "description": "Whether to alert when userData/cloud-init contains exec or download directives."}, {"field": "FirstBootWindow", "description": "Time after start considered first-boot (e.g., ≤30m) for correlation."}, {"field": "VMTagScope", "description": "Restrict detection to prod or internet-facing subnets to reduce noise."}]', '2026-05-01 15:26:35.647688');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (868, 'AN0847', 'Analytic 0847', 'Enumeration of local users or groups via file access (/etc/passwd) or commands like id, groups.', '{Linux}', 'x-mitre-analytic--7b87b63c-0936-48b5-8017-47bf5561e6f9', 'DET0303', '[{"name": "auditd:PATH", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AccessedFile", "description": "Monitors sensitive file access such as ''/etc/passwd'', ''/etc/group''."}, {"field": "ExecutionScope", "description": "Restrict detection to user-initiated sessions or specific parent processes."}]', '2026-05-01 15:26:35.649108');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (869, 'AN0663', 'Analytic 0663', 'Adversary gains shell access or uploads a malicious script to deface hosted web content in Nginx, Apache, or other services.', '{Linux}', 'x-mitre-analytic--7b95ffd7-165d-4435-97b6-4508b9328d89', 'DET0238', '[{"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "apache:access_log", "channel": "Unusual HTTP POST or PUT requests to paths such as ''/uploads/'', ''/admin/'', or CMS plugin folders", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "linux:syslog", "channel": "Unauthorized sudo or shell access, especially leading to file changes in /var/www or /srv/http", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UploadPathRegex", "description": "Regex for CMS-specific upload directories subject to defacement (e.g., wp-content/uploads)."}, {"field": "FileExtensionScope", "description": "Types of files to monitor for defacement (e.g., .html, .php, .jsp)."}]', '2026-05-01 15:26:35.650306');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (870, 'AN0485', 'Analytic 0485', 'On Linux, defenders may observe forged cookie activity as unauthorized modifications to browser cookie databases (e.g., ~/.mozilla/firefox/*/cookies.sqlite, ~/.config/chromium/Default/Cookies) or scripted injection of session tokens. Suspicious usage includes curl/wget commands embedding forged cookies in headers, correlated with abnormal session activity in SaaS or IaaS logs.', '{Linux}', 'x-mitre-analytic--7b981ab1-eb5f-4ad0-a819-90db819a4431', 'DET0171', '[{"name": "auditd:SYSCALL", "channel": "Unusual processes accessing or modifying cookie databases", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "CredentialFilePaths", "description": "Paths to cookie/session storage files to monitor."}]', '2026-05-01 15:26:35.651545');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (871, 'AN1096', 'Analytic 1096', 'Correlation of file creation/modification of `.desktop` files within XDG autostart directories, followed by execution of processes at user login initiated by the desktop environment. Malicious entries typically include suspicious Exec paths or anomalous names and are not associated with installed packages.', '{Linux}', 'x-mitre-analytic--7bd7f602-0f85-4e96-bd40-ae4a6f490b32', 'DET0390', '[{"name": "auditd:SYSCALL", "channel": "creat", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:EXECVE", "channel": "Process execution via .desktop Exec path from /etc/xdg/autostart or ~/.config/autostart", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "Write or modify .desktop file in XDG autostart path", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "linux:auth", "channel": "User login event followed by unexpected process tree", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "ExecCommandPattern", "description": "Regex or allowlist of expected Exec paths within .desktop files. Deviations may be suspicious."}, {"field": "AutostartDirectory", "description": "May vary by user config (e.g., $XDG_CONFIG_HOME). Must enumerate actual values per system."}, {"field": "TimeWindow", "description": "Correlate file creation/mod + exec within login window (e.g., 0–5 min of user logon)."}, {"field": "UserContext", "description": "Should filter to non-system users, as XDG persistence typically targets interactive sessions."}, {"field": "PackageOriginBaseline", "description": "Compare .desktop entries to known package sources (e.g., `dpkg -S`). Unexpected origins may be suspicious."}]', '2026-05-01 15:26:35.653794');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (872, 'AN1131', 'Analytic 1131', 'Configuration changes to virtual TAP/mirror policies that forward traffic to unapproved destinations. Detection correlates management plane API calls with mirrored traffic observation.', '{IaaS}', 'x-mitre-analytic--7becb616-f907-4533-a425-08ca42440e3f', 'DET0403', '[{"name": "AWS:CloudTrail", "channel": "CreateTrafficMirrorSession or ModifyTrafficMirrorTarget", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "AWS:VPCFlowLogs", "channel": "Traffic observed on mirror destination instance", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Detect mirror session creation followed by mirrored traffic within X seconds (e.g., 60s)"}, {"field": "MirrorDestinationCIDR", "description": "Define suspicious or external mirror targets (e.g., non-enterprise ranges)"}, {"field": "UserIdentity", "description": "Flag traffic mirror activity by non-privileged or unexpected IAM roles"}]', '2026-05-01 15:26:35.655146');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (873, 'AN0843', 'Analytic 0843', 'A source performs a short closed-port sequence; the host then modifies iptables/nftables/ufw rules or starts a daemon binding a new socket, followed by a successful connection from the same source.', '{Linux}', 'x-mitre-analytic--7bf8954f-5028-419d-b93f-9c6bfe6e5086', 'DET0302', '[{"name": "auditd:SYSCALL", "channel": "execve: Commands that alter firewall or start listeners: iptables|nft|ufw|firewall-cmd|pfctl|systemctl start sshd/telnet/dropbear; raw-socket/libpcap tools (tcpdump, tshark, nmap --raw).", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "socket/bind: New bind() to a previously closed port shortly after the sequence.", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Knock pattern: repeated REJ/S0 across ≥MinSequenceLen ports from same src_ip then SF success.", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ServicePort", "description": "Candidate port expected to open after knock (e.g., 22/2323)."}, {"field": "KnockTolerance", "description": "Max seconds between hits inside the sequence."}, {"field": "MgmtAllowList", "description": "Automation allowed to change firewall/daemon state (config mgmt, orchestration)."}]', '2026-05-01 15:26:35.656976');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (874, 'AN0373', 'Analytic 0373', 'File lock acquired via open() + flock() or lockf() on predictable path (e.g., /tmp/.lock123) followed by conditional early exit or divergent process behavior.', '{Linux}', 'x-mitre-analytic--7c0e4ffa-7f95-41de-9e3b-de2ad4a7a9ae', 'DET0132', '[{"name": "auditd:SYSCALL", "channel": "open, flock, fcntl, unlink", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "exit_group", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "lockfile_path_regex", "description": "Detect patterns like /tmp/.lock*, /var/run/*lock used by malware."}, {"field": "exit_code", "description": "Track specific exit codes (e.g., 1, 2) that signal lock acquisition failure."}, {"field": "TimeWindow", "description": "Correlate lockfile access + early process termination within N seconds."}]', '2026-05-01 15:26:35.658716');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (875, 'AN1346', 'Analytic 1346', 'Behavioral chain: (1) third-party interactive login or mobileconfig-based device enrollment; (2) privilege use or admin group change; (3) lateral movement mounts/ssh. Correlate unified logs and network telemetry.', '{macOS}', 'x-mitre-analytic--7c28e2f5-c944-4974-810f-81bcfdc8b6cc', 'DET0488', '[{"name": "macos:unifiedlog", "channel": "loginwindow or sshd successful login events", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "macos:unifiedlog", "channel": "Group membership change for admin or wheel", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "NSM:Flow", "channel": "ssh/smb connections to internal resources from third-party devices", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ManagedDeviceList", "description": "Known corp devices; treat unknown devices as higher risk."}]', '2026-05-01 15:26:35.660249');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (876, 'AN0895', 'Analytic 0895', 'Processes such as PowerShell, Git, or curl initiating outbound HTTPS POST requests to known code repository APIs (e.g., github.com, gitlab.com) immediately following large file reads. Defender view: correlation between file access of sensitive directories (e.g., Documents, Finance) and abnormal data uploads to repository domains.', '{Windows}', 'x-mitre-analytic--7c7f0049-96af-4acc-9c58-9f8e661adb63', 'DET0318', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredDomains", "description": "List of external code repository domains to monitor (github.com, gitlab.com, bitbucket.org)."}, {"field": "ExfilVolumeThreshold", "description": "Threshold for outbound data volume per session to flag suspicious uploads."}]', '2026-05-01 15:26:35.661639');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (877, 'AN0504', 'Analytic 0504', 'Detection of VNC service or executable starting unexpectedly, followed by user session creation and interactive desktop activity (mouse/keyboard simulation).', '{Windows}', 'x-mitre-analytic--7c91d6c7-4591-41b1-9c08-0c0660b07d24', 'DET0178', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "NSM:Flow", "channel": "port 5900 inbound", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "Correlate VNC process with user logon activity within defined time span"}, {"field": "VNCBinaryList", "description": "Trackable VNC executable names (e.g., vncserver.exe, winvnc.exe)"}, {"field": "LogonType", "description": "Limit detection to interactive logons (type 10)"}]', '2026-05-01 15:26:35.663472');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (878, 'AN0040', 'Analytic 0040', 'Detects staging of sensitive files into temporary or public directories, compression with 7zip/WinRAR, or batch copy prior to exfiltration.', '{Windows}', 'x-mitre-analytic--7cb2010a-e502-4117-94f3-fa3bd8d64a34', 'DET0014', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "StagingDirectoryList", "description": "Temp folders or user profile staging directories"}, {"field": "CompressionToolList", "description": "7z.exe, rar.exe, zip.exe paths"}, {"field": "TimeWindow", "description": "Temporal bounds for detecting batch staging activities"}]', '2026-05-01 15:26:35.664901');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (887, 'AN0098', 'Analytic 0098', 'Detects process enumeration using `esxcli system process list` or `ps` on ESXi shell or via unauthorized SSH sessions. Correlates with interactive sessions and abnormal user roles.', '{ESXi}', 'x-mitre-analytic--7e029a7f-beb5-4da9-9d75-8fcfc812103b', 'DET0034', '[{"name": "esxi:shell", "channel": "interactive shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:auth", "channel": "user session", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "User", "description": "Admins are expected to run these commands—flag if non-admin or unknown users do"}]', '2026-05-01 15:26:35.678591');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (880, 'AN0334', 'Analytic 0334', 'Correlated user account modification (reset, disable, deletion) events with anomalous process lineage (e.g., PowerShell or net.exe from an interactive session), especially outside of IT admin change windows or by non-admin users.', '{Windows}', 'x-mitre-analytic--7d0595b9-eca7-488d-bbc2-ed02ff4ced9b', 'DET0120', '[{"name": "WinEventLog:Security", "channel": "EventCode=4723, 4724, 4740", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Account performing the operation (e.g., Domain Admins vs. local users)"}, {"field": "TimeWindow", "description": "Alert only on actions outside of maintenance windows"}, {"field": "ParentProcessName", "description": "Detect suspicious process lineage (e.g., powershell.exe launching net.exe)"}]', '2026-05-01 15:26:35.667416');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (881, 'AN0742', 'Analytic 0742', 'Abnormal CPU/memory usage by unauthorized processes with outbound connections to known mining pools or using cron jobs/scripts to maintain persistence.', '{Linux}', 'x-mitre-analytic--7d099bc4-1a19-4aa3-b12b-a9390e98408a', 'DET0267', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:procfs", "channel": "Sustained high /proc/[pid]/stat usage", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "NSM:Flow", "channel": "Outbound traffic to mining pools or proxies", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ProcessPath", "description": "Location of resource-heavy binaries (e.g., /tmp/.xmr)"}, {"field": "CPUThreshold", "description": "Acceptable baseline for CPU overuse"}, {"field": "KnownMiningDomains", "description": "List of domains/IPs for known cryptomining services"}]', '2026-05-01 15:26:35.669149');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (882, 'AN1255', 'Analytic 1255', 'ICMP or raw socket traffic generated by user-mode processes like bash, Python, or nc, typically using `ping`, `hping3`, or crafted packets via libpcap or scapy.', '{Linux}', 'x-mitre-analytic--7d0a3871-8cee-47bd-8829-637e132c98f7', 'DET0457', '[{"name": "auditd:SYSCALL", "channel": "sendto/connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "icmp.log, weird.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "RawSocketExecutionPath", "description": "Uncommon programs using raw sockets (e.g., netcat, Python, nmap)."}, {"field": "TimeWindow", "description": "Tunable window for correlating execution with network events (e.g., 2m)."}]', '2026-05-01 15:26:35.670462');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (883, 'AN0017', 'Analytic 0017', 'Cloud login from atypical geolocation or user-agent string, followed by resource enumeration or infrastructure manipulation using cloud CLI/API', '{IaaS}', 'x-mitre-analytic--7d4732f8-989c-4425-81c4-aa3e1bcb8d0e', 'DET0008', '[{"name": "AWS:CloudTrail", "channel": "ConsoleLogin, AssumeRole, ListResources", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "gcp:audit", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "IPGeoRiskScore", "description": "Tunable scoring system for evaluating geo-divergent or TOR-origin logins"}, {"field": "UserAgentFingerprint", "description": "Flag rare CLI tools or browser-based sessions"}, {"field": "SessionDuration", "description": "Threshold for how long between login and API access"}, {"field": "CloudResourceScope", "description": "Limit monitoring to high-value resource groups or sensitive tenants"}]', '2026-05-01 15:26:35.671695');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (884, 'AN0689', 'Analytic 0689', 'Processes accessing TCC-protected input APIs or polling HID services without user interaction, or dynamically loaded keylogging frameworks using accessibility privileges', '{macOS}', 'x-mitre-analytic--7d5eb9bd-5e53-4cf8-b86d-7136bbf8f673', 'DET0246', '[{"name": "macos:unifiedlog", "channel": "com.apple.securityd, com.apple.tccd", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "macos:osquery", "channel": "query: process_events, launchd, and tcc.db access", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AccessibilityAPIUsage", "description": "Detection of programs requesting access to input monitoring (e.g., CGEventTap)"}, {"field": "TCCBypassAttempt", "description": "Alert if TCC settings are altered or bypassed"}, {"field": "SignedBinaryCheck", "description": "Tunable based on developer signing status (legitimate software vs unsigned)"}]', '2026-05-01 15:26:35.674576');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (885, 'AN0492', 'Analytic 0492', 'Automated or scripted HTTP/TLS flooding from one VM or cloud instance against another service, exploiting compute-based billing or exhaustion of service infrastructure.', '{IaaS}', 'x-mitre-analytic--7dbd928f-da93-4cbf-af73-ac5987a7858a', 'DET0173', '[{"name": "AWS:CloudTrail", "channel": "AuthorizeSecurityGroupIngress", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"name": "AWS:VPCFlowLogs", "channel": "Unusual volume of inbound packets from single source across short time interval", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "AWS:CloudWatch", "channel": "Sustained spike in CPU usage on EC2 instance with web service role", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "VPCFlowBurstRate", "description": "Threshold for traffic burst on target service port"}, {"field": "EC2CPUThreshold", "description": "Compute saturation level for alerting (e.g., >90% for 3 minutes)"}]', '2026-05-01 15:26:35.676022');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (886, 'AN1160', 'Analytic 1160', 'Programmatic or excessive access to file shares, SharePoint, or database repositories by users not typically interacting with them. This includes abnormal access by privileged accounts, enumeration of large numbers of files, or downloads of sensitive content in bursts.', '{Windows}', 'x-mitre-analytic--7dce56f3-43db-4787-ae13-bd2ce6851088', 'DET0413', '[{"name": "WinEventLog:Security", "channel": "EventCode=5145", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"name": "m365:unified", "channel": "Accessed SharePoint files or pages", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}]', '[{"field": "UserContext", "description": "Privileged users may be excluded if they routinely perform admin actions on SharePoint or file shares."}, {"field": "AccessVolumeThreshold", "description": "The number of files accessed or pages retrieved in a short window to flag as abnormal."}, {"field": "TimeWindow", "description": "The time range (e.g., 5 minutes, 1 hour) in which burst access patterns are considered anomalous."}]', '2026-05-01 15:26:35.677343');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (888, 'AN1496', 'Analytic 1496', 'Processes not typically associated with encryption loading asymmetric crypto libraries (e.g., rsaenh.dll, crypt32.dll) and subsequently initiating outbound TLS/SSL connections with abnormal certificate chains or handshakes. Defender correlates process creation, module load, and unusual encrypted sessions.', '{Windows}', 'x-mitre-analytic--7e1c7338-11d5-4ab4-aefc-bbd81e26068d', 'DET0543', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AllowedCryptoProcesses", "description": "Whitelist browsers, mail clients, or apps expected to use asymmetric crypto."}, {"field": "CertificateAuthorityList", "description": "Baseline CA list for validating abnormal certs."}, {"field": "HandshakeTimeout", "description": "Detection of incomplete or malformed handshakes."}]', '2026-05-01 15:26:35.680183');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (889, 'AN0326', 'Analytic 0326', 'Creation of LaunchAgents or LaunchDaemons with names resembling known system services but executing non-Apple signed code or scripts.', '{macOS}', 'x-mitre-analytic--7e3c05c9-5e49-416c-a0c9-eb7631ea5e7e', 'DET0117', '[{"name": "fs:fileevents", "channel": "/Library/LaunchDaemons/*.plist, ~/Library/LaunchAgents/*.plist", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "subsystem=com.apple.launchservices", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "PlistLabelSimilarity", "description": "Detect plists with labels that closely resemble legitimate ones (e.g., `com.apple.updates.plist`)"}, {"field": "UnsignedBinaryExecution", "description": "Toggle sensitivity for unsigned binaries or scripts launched by daemons"}, {"field": "UserContext", "description": "Scope detection based on whether LaunchAgent ran in user or system context"}]', '2026-05-01 15:26:35.681549');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (890, 'AN1177', 'Analytic 1177', 'Multi-stage Windows DACL manipulation behavioral chain: (1) Process creation of permission-modifying utilities (icacls.exe, takeown.exe, attrib.exe, cacls.exe) or PowerShell ACL cmdlets, (2) Command-line analysis revealing privilege escalation intent through suspicious parameters (/grant, /takeown, /T, Set-Acl), (3) DACL modification events (4670) correlating with process execution, (4) Subsequent file access attempts (4663) indicating successful permission bypass, (5) Potential follow-on persistence or lateral movement activities', '{Windows}', 'x-mitre-analytic--7e4ac594-c46c-4c7e-ba6d-9a457ab1e767', 'DET0418', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4656, 4658", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:WMI", "channel": "EventCode=5857, 5858, 5860, 5861", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}]', '[{"field": "TemporalCorrelationWindow", "description": "Time window for correlating process creation (4688/sysmon 1) with DACL changes (4670) and subsequent access (4663) - default 300 seconds, adjust based on system performance and network latency"}, {"field": "SensitivePathWhitelist", "description": "Environment-specific critical directories requiring enhanced monitoring (e.g., C:\\Windows\\System32, C:\\Program Files, %USERPROFILE%\\AppData) - customize per organizational security requirements"}, {"field": "AuthorizedAdministratorAccounts", "description": "User accounts and service accounts authorized to perform legitimate DACL modifications - update to reflect current administrative staff and automated processes"}, {"field": "SuspiciousCommandLinePatterns", "description": "Regex patterns for detecting malicious intent in permission modification commands - tune to reduce false positives while maintaining detection efficacy"}, {"field": "BusinessHoursThreshold", "description": "Time-based risk scoring modifier for permission changes occurring outside standard business hours - adjust based on organizational work patterns"}, {"field": "PowerShellScriptBlockSizeThreshold", "description": "Minimum PowerShell script block size for ACL-related content analysis - balance between detection coverage and log volume"}, {"field": "FileAccessFrequencyBaseline", "description": "Statistical baseline for normal file access patterns post-permission change - establish through historical analysis and update periodically"}, {"field": "WMIMethodInvocationWhitelist", "description": "Approved WMI classes and methods for legitimate permission operations (e.g., Win32_SecurityDescriptor) - maintain based on authorized management tools"}]', '2026-05-01 15:26:35.68284');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (891, 'AN1331', 'Analytic 1331', 'Identify repeated DNS resolutions where the same domain name returns multiple IPs in short succession, combined with low TTL values and high query volume from unusual processes. Correlate with process lineage (e.g., Office apps spawning abnormal DNS lookups).', '{Windows}', 'x-mitre-analytic--7e6e9c0e-737e-43ac-8cdd-5edbff4d6424', 'DET0485', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DNSQueryBurstThreshold", "description": "Number of unique IPs returned per domain in a short window"}, {"field": "TimeWindow", "description": "Adjust correlation timeframe for fast flux detection (e.g., 5–10 minutes)"}]', '2026-05-01 15:26:35.684166');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (892, 'AN1010', 'Analytic 1010', 'Detect abnormal use of email clients (e.g., Outlook, Thunderbird) showing mass arrival of messages or repetitive attachments being locally stored. Correlate message volume with file creation activity in mail cache directories.', '{"Office Suite"}', 'x-mitre-analytic--7e9cb99b-4040-4b73-bd70-1bd68ae0f373', 'DET0355', '[{"name": "m365:exchange", "channel": "MailDelivery: High-frequency delivery of messages or attachments to a single recipient", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "UserContext", "description": "Context for distinguishing between VIP or sensitive recipients and general users."}]', '2026-05-01 15:26:35.68549');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (893, 'AN0357', 'Analytic 0357', 'Adversary creates disguised launch daemons or apps with misleading names and bundle metadata (e.g., Info.plist values inconsistent with binary path or icon). Launch is correlated with user logon or persistence setup.', '{macOS}', 'x-mitre-analytic--7ebea786-db9c-439d-9caf-d0dd740047f3', 'DET0127', '[{"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fileevents", "channel": "/var/log/install.log", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "InfoPlistDiscrepancy", "description": "Mismatch between bundle metadata and file system path/name"}, {"field": "LaunchAgentPath", "description": "Unusual LaunchDaemon/LaunchAgent paths can be tuned per org"}, {"field": "ExecutionTrigger", "description": "Window between install and first execution (e.g., at user login)"}]', '2026-05-01 15:26:35.686701');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (901, 'AN1369', 'Analytic 1369', 'Detection of adversary behavior that disables or modifies security tools, including killing AV/EDR processes, stopping services, altering Sysmon registry keys, or tampering with exclusion lists. Defenders observe process/service termination, registry modification, and abnormal absence of expected telemetry.', '{Windows}', 'x-mitre-analytic--7faf6f37-f074-4b9d-be19-618c3516486d', 'DET0497', '[{"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=5", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "ProcessNameExclusions", "description": "List of expected administrative tools/processes to prevent false positives."}, {"field": "TimeWindow", "description": "Defines correlation window linking process termination, registry edits, and service stoppage."}, {"field": "ServiceNames", "description": "Customizable list of security service names per enterprise deployment."}]', '2026-05-01 15:26:35.700604');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (894, 'AN2038', 'Analytic 2038', 'Detects suspicious interactions with security products followed by service crashes, unexpected restarts, driver unloads, telemetry gaps, or tamper-state changes. Correlates exploit precursor behavior with immediate degradation of defensive services and follow-on process execution.', '{Windows}', 'x-mitre-analytic--7ec436a3-dd31-4d23-a51b-0e03d3c474bd', 'DET0900', '[{"name": "WinEventLog:System", "channel": "EventCode=7035", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CrashCorrelationWindow", "description": "Time between suspicious interaction and security service failure"}, {"field": "ProtectedServiceList", "description": "Security agents/services expected to remain stable"}, {"field": "TelemetryGapThreshold", "description": "Acceptable heartbeat silence duration"}]', '2026-05-01 15:26:35.688015');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (895, 'AN0428', 'Analytic 0428', 'Detection of raw access to physical drives, modification of boot records (MBR/VBR), and suspicious file creation or alteration within the EFI System Partition (ESP). Correlates privileged process execution with low-level disk modification and unexpected driver or firmware interactions.', '{Windows}', 'x-mitre-analytic--7edc8ff6-0616-4fab-a7b7-1bd3d08cc0b1', 'DET0150', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=9", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "KnownGoodMBRHashes", "description": "Baseline hashes of clean MBR/VBR sectors for comparison"}, {"field": "ESPFileWhitelist", "description": "Approved EFI executables within ESP directories"}, {"field": "TimeWindow", "description": "Correlation window between privileged access, raw disk modification, and EFI file creation"}]', '2026-05-01 15:26:35.68945');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (896, 'AN0361', 'Analytic 0361', 'Suspicious invocation of GUI utilities or scripts with suppressed or redirected windowing options. Defender view: detection of X11 or Wayland calls to spawn windows that do not appear on active displays, or use of nohup/screen/tmux to mask interactive shells.', '{Linux}', 'x-mitre-analytic--7ef0d746-f233-4b41-b999-43a6b1484574', 'DET0128', '[{"name": "auditd:EXECVE", "channel": "Execution of GUI-related binaries with suppressed window/display flags", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "Use of fork/exec with DISPLAY unset or redirected", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "DisplayScope", "description": "Restrict monitoring to interactive GUI contexts rather than server/headless processes."}]', '2026-05-01 15:26:35.691085');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (897, 'AN0194', 'Analytic 0194', 'Detects file transfers or mounting operations from remote hosts followed by write actions into a local staging directory, often using SMB or remote shell activity.', '{Windows}', 'x-mitre-analytic--7efd6a7b-d7c0-4922-a1df-c492c0a2d3f8', 'DET0071', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Microsoft-Windows-SMBClient/Security", "channel": "EventCode=31001", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"name": "WinEventLog:PowerShell", "channel": "CommandLine=copy-item or robocopy from UNC path", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "StagingDirectory", "description": "Common directories such as C:\\Temp, Downloads, or hidden folders used for remote staging"}, {"field": "RemotePathPatterns", "description": "UNC paths like \\\\10.* or \\\\domain\\share indicating lateral data staging"}, {"field": "CopyToolPatterns", "description": "Usage of robocopy, xcopy, copy-item, or scheduled tasks performing cross-host copies"}]', '2026-05-01 15:26:35.692668');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (898, 'AN0293', 'Analytic 0293', 'Execution of hash cracking binaries or scripts (e.g., john, hashcat) following access to shadow file or dumped hashes', '{Linux}', 'x-mitre-analytic--7efdc4e3-8a2e-4d0d-8ced-03155f2c55ac', 'DET0105', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "auth.log or custom tool logs", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ShadowAccessPattern", "description": "Access to /etc/shadow or known dumped hash files"}, {"field": "CrackingBinaryPath", "description": "Tool path or name associated with hash cracking"}, {"field": "CPUUsageThreshold", "description": "Sustained CPU load post-credential dump can be an indicator"}]', '2026-05-01 15:26:35.694007');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (899, 'AN1486', 'Analytic 1486', 'VMware daemons or user processes encapsulating traffic (e.g., guest VMs tunneling via hostd). Defender sees network services inside ESXi creating flows inconsistent with management plane traffic, such as SSH forwarding or DNS-over-HTTPS from management interfaces.', '{ESXi}', 'x-mitre-analytic--7f128f2c-5b38-4088-9026-e251237f8add', 'DET0538', '[{"name": "esxi:vpxd", "channel": "ESXi processes relaying traffic via SSH or unexpected ports", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "esxcli:network", "channel": "listening sockets bound with non-standard encapsulated protocols", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ESXiServiceProfiles", "description": "Baseline allowed services and expected ports for ESXi management."}]', '2026-05-01 15:26:35.69558');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (900, 'AN0205', 'Analytic 0205', '`socat`, `ssh`, `iptables`, or `ncat` invoked from user space or cron jobs to create port forwarding, reverse shells, or inter-host tunnels between compromised Linux systems. Behavior is typically paired with socket activity and high entropy traffic.', '{Linux}', 'x-mitre-analytic--7f269271-6800-4d20-b9f7-6c38cecac6f0', 'DET0075', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "Internal connection logging", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "UserContext", "description": "Alert on unexpected users executing inter-host relay tools (e.g., `www-data`, `backup`)."}, {"field": "PortRange", "description": "Adjust to watch for commonly misused internal TCP/UDP ports."}, {"field": "ProcessPattern", "description": "Shell pipelines or wrapped invocations like `bash -c ''socat ...''`"}]', '2026-05-01 15:26:35.699146');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (903, 'AN0857', 'Analytic 0857', 'File reads or process executions involving insecurely stored credential files (e.g., config files with password fields) by non-root or anomalous users followed by ssh authentication attempts.', '{Linux}', 'x-mitre-analytic--7ff5d08a-5d4d-4260-85ee-fdb6a244f258', 'DET0307', '[{"name": "auditd:SYSCALL", "channel": "open/read of sensitive config or secret files", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:EXECVE", "channel": "grep/cat/awk on files with password fields", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:syslog", "channel": "authentication success after file access", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "RegexPatterns", "description": "Patterns like password, secret, token can be expanded or customized"}, {"field": "UserContextScope", "description": "Scope of users monitored (e.g., root vs all users)"}, {"field": "TimeWindow", "description": "Time between suspicious file access and credential use"}]', '2026-05-01 15:26:35.703418');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (904, 'AN1459', 'Analytic 1459', 'Detects adversarial archiving activity through invocation of utilities like tar, gzip, bzip2, or openssl used in non-administrative or unusual contexts. Correlates command execution patterns with file creation of compressed/encrypted outputs in staging directories (e.g., /tmp, /var/tmp).', '{Linux}', 'x-mitre-analytic--8018e3a6-ab64-4fe2-9771-ca129091bc17', 'DET0526', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of tar, gzip, bzip2, or openssl with output redirection", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:FILE", "channel": "create: Creation of files ending in .tar, .gz, .bz2, .zip in /tmp or /var/tmp", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ArchiveCommands", "description": "List of archiving/encryption utilities considered sensitive in the monitored environment."}, {"field": "SuspiciousDirectories", "description": "Paths where archive creation is suspicious (e.g., /tmp, user home directories)."}, {"field": "TimeWindow", "description": "Temporal window to correlate command execution with file creation events."}]', '2026-05-01 15:26:35.704763');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (905, 'AN0454', 'Analytic 0454', 'Detect user account logon attempts that trigger multiple MFA challenges through enterprise identity integrations, especially if MFA push requests are generated without successful interactive login.', '{macOS}', 'x-mitre-analytic--801a3652-8772-4b69-8a13-d870be653ef0', 'DET0160', '[{"name": "macos:unifiedlog", "channel": "authd generating multiple MFA token requests", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "DeviceEnrollmentStatus", "description": "Exclude unmanaged macOS devices that use different MFA providers"}]', '2026-05-01 15:26:35.706189');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (906, 'AN0896', 'Analytic 0896', 'Processes like git, curl, or python scripts executing commands that package files (tar, gzip) followed by HTTPS uploads to code repository endpoints. Defender view: detect unusual git push activity or scripted HTTPS requests outside normal developer work hours.', '{Linux}', 'x-mitre-analytic--8049e0b4-961b-499f-9204-45fa9b7117be', 'DET0318', '[{"name": "auditd:EXECVE", "channel": "git push, curl -X POST", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "open/read of sensitive directories", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "large outbound HTTPS uploads to repo domains", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "WorkHours", "description": "Baseline normal developer activity periods to reduce false positives."}, {"field": "RepoDomainList", "description": "Known allowed internal or external repository domains."}]', '2026-05-01 15:26:35.708042');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (907, 'AN1551', 'Analytic 1551', 'Windows environmental validation behavioral chain: (1) Rapid system discovery reconnaissance through WMI queries, registry enumeration, and network share discovery, (2) Environment-specific artifact collection (hostname, domain, IP addresses, installed software, hardware identifiers), (3) Cryptographic operations or conditional logic based on collected environmental values, (4) Selective payload execution contingent on environmental validation results, (5) Temporal correlation between discovery activities and subsequent execution or network communication', '{Windows}', 'x-mitre-analytic--8089daf3-72b0-4714-b800-2856f27dc21c', 'DET0562', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4648", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:WMI", "channel": "EventCode=5857, 5858, 5860, 5861", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "DiscoveryTimeWindow", "description": "Maximum time window for correlating multiple discovery activities indicating reconnaissance phase - adjust based on normal system behavior (default: 300 seconds)"}, {"field": "DiscoveryActivityThreshold", "description": "Minimum number of different discovery techniques within time window to trigger detection - balance between false positives and coverage (default: 4 activities)"}, {"field": "CryptographicLibraryWhitelist", "description": "Approved cryptographic libraries and modules for legitimate organizational use - maintain based on approved software inventory"}, {"field": "WMIQueryComplexityThreshold", "description": "Complexity score for WMI queries indicating reconnaissance vs. legitimate administration - tune based on administrative patterns"}, {"field": "EnvironmentalArtifactList", "description": "Environment-specific values commonly targeted by guardrails (hostnames, domains, network shares) - customize for organizational environment"}, {"field": "ExecutionDelayBaseline", "description": "Statistical baseline for normal delay between discovery and execution activities - establish through historical analysis"}]', '2026-05-01 15:26:35.709768');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (908, 'AN0097', 'Analytic 0097', 'Monitors execution of ps, top, or launchctl with unusual parent processes or from terminal scripts. Also detects AppleScript-based process listing or `system_profiler SPApplicationsDataType` misuse.', '{macOS}', 'x-mitre-analytic--80939714-6d17-4cc0-accd-3e1d634846bc', 'DET0034', '[{"name": "macos:unifiedlog", "channel": "process launch", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "Process Context", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "ParentApp", "description": "Tunable to detect discovery from non-UI tools or script-based execution (osascript, zsh, cron)"}]', '2026-05-01 15:26:35.711227');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (916, 'AN0759', 'Analytic 0759', 'Processes that normally do not initiate network connections establishing outbound encrypted TLS/SSL sessions, especially with asymmetric traffic volumes (client sending more than receiving) or non-standard certificate chains. Defender observations correlate process creation with unexpected network encryption libraries being loaded.', '{Windows}', 'x-mitre-analytic--81233639-a08b-4a56-a5d4-ac2f9ae94a2b', 'DET0273', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "AllowedEncryptedProcesses", "description": "Whitelist processes expected to use TLS (e.g., browsers, mail clients)."}, {"field": "EntropyThreshold", "description": "Payload randomness threshold to distinguish C2 encryption from legitimate traffic."}, {"field": "TimeWindow", "description": "Correlation window between process creation, module load, and encrypted connection."}]', '2026-05-01 15:26:35.722009');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (909, 'AN0880', 'Analytic 0880', 'Adversaries create the ''Office Test\Special\Perf'' registry key and specify a malicious DLL path that is auto-loaded when an Office application starts. This DLL is injected into the Office process memory space and can provide persistent execution without requiring macro enablement.', '{Windows}', 'x-mitre-analytic--80be1bd7-b4e8-4d1b-b294-56b1c073bbe0', 'DET0315', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Microsoft-Office-Alerts", "channel": "Unexpected DLL or component loaded at Office startup", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "RegistryPath", "description": "Path to ''Office test\\Special\\Perf'' may vary by Office version, 32/64-bit, or architecture (HKCU vs HKLM)"}, {"field": "DLLPath", "description": "Injected DLL may reside in different user-writable locations (e.g., %APPDATA%, %TEMP%, or network shares)"}, {"field": "OfficeProcessName", "description": "Process name (e.g., winword.exe, excel.exe) may vary by Office deployment and usage"}, {"field": "TimeWindow", "description": "Time between DLL registry creation and first Office execution may vary depending on user activity"}, {"field": "UserContext", "description": "Malicious DLL may target only specific users, necessitating correlation with interactive logon sessions"}]', '2026-05-01 15:26:35.712926');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (910, 'AN0761', 'Analytic 0761', 'Applications or launchd jobs initiating encrypted TLS traffic to rare external hosts. Defender observes unified logs showing ssl/TLS API calls by processes not baseline-approved, and payload entropy suggesting encrypted C2 sessions.', '{macOS}', 'x-mitre-analytic--80c5c2fd-eb3a-4678-9d3b-6147a90284de', 'DET0273', '[{"name": "macos:unifiedlog", "channel": "Encrypted session initiation by unexpected binary", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:unifiedlog", "channel": "Process invoking SSL routines from Security framework", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DoHResolvers", "description": "Known legitimate DoH endpoints to reduce false positives."}, {"field": "PayloadEntropyThreshold", "description": "High-entropy traffic deviations used to detect concealed channels."}]', '2026-05-01 15:26:35.714239');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (911, 'AN1585', 'Analytic 1585', 'Execution of built-in or AppleScript-based system enumeration via `arp`, `netstat`, `ping`, and discovery of `/etc/hosts` contents.', '{macOS}', 'x-mitre-analytic--80c7f835-116d-4fa1-817a-08965efef16c', 'DET0574', '[{"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ExecutionUser", "description": "Limit detection to suspicious users or automation contexts"}, {"field": "CommandSignature", "description": "Adapt for expected enumeration tooling used in IT"}]', '2026-05-01 15:26:35.715595');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (912, 'AN0654', 'Analytic 0654', 'Suspicious modification of file artifacts (e.g., logs, ISO templates) on ESXi datastores, followed by beaconing or POST operations to external IPs potentially hiding payloads in file-like traffic.', '{ESXi}', 'x-mitre-analytic--80caf81c-0714-4fa5-8b77-8e2144e316b9', 'DET0235', '[{"name": "esxi:vmkernel", "channel": "Storage access and file ops", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "esxi:hostd", "channel": "Service initiated connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Transferred file observations", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "FilenamePattern", "description": "Tune for likely stego file names (e.g., wallpaper.jpg, template.iso)."}, {"field": "UnusualDestinationIP", "description": "Destination outside vCenter management subnet."}]', '2026-05-01 15:26:35.716794');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (913, 'AN2018', 'Analytic 2018', 'Monitor call logs from corporate devices to identify patterns of potential voice phishing, such as calls to/from known malicious phone numbers.', '{PRE}', 'x-mitre-analytic--80e453fd-8191-474a-b577-7a575ef5fe87', 'DET0886', '[{"name": "Application Log", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', NULL, '2026-05-01 15:26:35.718167');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (914, 'AN0816', 'Analytic 0816', 'Detects API calls registering or updating hybrid identity connectors, modification of cloud-to-on-premises federation trust, and unusual token issuance logs.', '{IaaS}', 'x-mitre-analytic--80e4f847-a149-423b-a179-cbcf4afd06b9', 'DET0293', '[{"name": "AWS:CloudTrail", "channel": "UpdateFederationSettings or RegisterHybridConnector", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "MonitoredFederations", "description": "Federation trusts and connectors relevant to hybrid identity setup."}]', '2026-05-01 15:26:35.719478');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (915, 'AN0182', 'Analytic 0182', 'PowerShell or script execution with parameters that suppress errors or ignore user interrupts, such as `-ErrorAction SilentlyContinue`. Defender perspective: detecting discrepancies between suppressed error arguments and continued execution behavior.', '{Windows}', 'x-mitre-analytic--80e9341d-7ea4-4684-8f27-54566e996ce6', 'DET0067', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredCmdlets", "description": "List of PowerShell cmdlets where suppressed error handling is suspicious (e.g., Invoke-Expression, Invoke-WebRequest)."}, {"field": "ErrorActionThreshold", "description": "Frequency of suppressed error actions within time window that should trigger detection."}]', '2026-05-01 15:26:35.720685');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (917, 'AN0072', 'Analytic 0072', 'Abuse of Linux Electron binaries by modifying app.asar or config JS files and spawning unexpected child processes (bash, curl, python).', '{Linux}', 'x-mitre-analytic--8129e7b8-eaa1-4459-ba70-ebf6d68ca16c', 'DET0025', '[{"name": "auditd:SYSCALL", "channel": "execve: Electron-based binary spawning shell or script interpreter", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AsarIntegrityCheck", "description": "Baseline of expected asar package signatures per app."}, {"field": "SuspiciousChildProcesses", "description": "Flag shells/python spawned from Electron parent."}]', '2026-05-01 15:26:35.723815');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (918, 'AN2017', 'Analytic 2017', 'Once adversaries have provisioned compromised infrastructure (ex: a server for use in command and control), internet scans may help proactively discover compromised infrastructure. Consider looking for identifiable patterns such as services listening, certificates in use, SSL/TLS negotiation features, or other response artifacts associated with adversary C2 software.(Citation: ThreatConnect Infrastructure Dec 2020)(Citation: Mandiant SCANdalous Jul 2020)(Citation: Koczwara Beacon Hunting Sep 2021)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (919, 'AN0687', 'Analytic 0687', 'Behavior chain involving unexpected API calls to capture keyboard input, driver loads for keyloggers, or remote use of smart card authentication via logon sessions not initiated by local user interaction', '{Windows}', 'x-mitre-analytic--8180320e-ab62-44e5-afae-eba6ba23d769', 'DET0246', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "AccessMask", "description": "Tunable based on what memory-level access the keylogger uses (e.g., 0x10 for read)"}, {"field": "ProcessNameExclusions", "description": "Legitimate accessibility tools may use similar API calls (e.g., Magnifier.exe)"}, {"field": "TimeWindow", "description": "Define how quickly access + registry mod + smart card use must co-occur"}]', '2026-05-01 15:26:35.72722');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (920, 'AN0218', 'Analytic 0218', 'Detection of hijacked VNC or SSH sessions on macOS where adversaries take over an existing session rather than authenticating directly. Indicators include process execution from active sessions without new logon events, manipulation of TTY sessions, or anomalous network activity tied to dormant sessions.', '{macOS}', 'x-mitre-analytic--81889314-3404-4cfb-a650-52a5898b6f31', 'DET0079', '[{"name": "macos:unifiedlog", "channel": "Authentication inconsistencies where commands are executed without corresponding login events", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "macos:unifiedlog", "channel": "Execution of processes linked to hijacked sessions (e.g., anomalous parent-child process lineage)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Suspicious long-lived or reattached remote desktop sessions from unexpected IPs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "SessionIdleThreshold", "description": "Time threshold for inactive sessions flagged as suspicious when commands suddenly resume."}]', '2026-05-01 15:26:35.728518');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (921, 'AN0287', 'Analytic 0287', 'Detects modification of LSASS and authentication DLLs, suspicious registry changes to password filter packages, and abnormal process access to lsass.exe. Correlates registry modifications, DLL loads, and process handle access events.', '{Windows}', 'x-mitre-analytic--818b46ce-9c93-47c9-a649-8bc5d3b734a5', 'DET0104', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "MonitoredRegistryKeys", "description": "Specific LSASS and password filter registry paths monitored for modification."}, {"field": "TimeWindow", "description": "Correlation window between registry change, DLL load, and lsass.exe access."}]', '2026-05-01 15:26:35.730008');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (922, 'AN1511', 'Analytic 1511', 'Processes that normally do not initiate network communications suddenly making outbound HTTPS connections with high outbound-to-inbound data ratios. Defender view: correlation between process creation logs (e.g., Word, Excel, PowerShell) and subsequent anomalous network traffic volumes toward common web services (Dropbox, Google Drive, OneDrive).', '{Windows}', 'x-mitre-analytic--81b1e9a7-b6f4-4cca-b07a-3498ab4abd4a', 'DET0548', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "MonitoredServices", "description": "List of legitimate web services to baseline (Dropbox, OneDrive, Google Drive)."}, {"field": "ExfilVolumeThreshold", "description": "Outbound data threshold for flagging unusual activity, tunable by environment."}, {"field": "TimeWindow", "description": "Aggregation period to calculate anomalies in outbound data volume."}]', '2026-05-01 15:26:35.731275');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (923, 'AN0548', 'Analytic 0548', 'Detects suspicious MFA method changes, such as registration of weaker factors (e.g., SMS), or removal of MFA requirements for specific accounts or groups.', '{SaaS}', 'x-mitre-analytic--81c940cd-633b-4f88-9f8f-f6837a7026bc', 'DET0190', '[{"name": "saas:zoom", "channel": "DisableMFA or RegisterNewFactor", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "AcceptedFactors", "description": "Configured MFA factors allowed in SaaS environment; tuned to organizational policies."}]', '2026-05-01 15:26:35.732639');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (924, 'AN0186', 'Analytic 0186', 'Chain: (1) udev / kernel logs show hot-plug (USB/Thunderbolt/PCIe); (2) block device created by udisks/diskarbitration; (3) optional: new network interface or DHCP lease observed. Correlate /var/log/messages|syslog, auditd SYSCALL open/creat on /dev, and DHCP/Zeek.', '{Linux}', 'x-mitre-analytic--81cd2610-bc6c-46bf-8d3c-d6e30c7f51c8', 'DET0069', '[{"name": "auditd:SYSCALL", "channel": "mknod,open,openat", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "linux:syslog", "channel": "usb * new|thunderbolt|pci .* added|block.*: new .* device", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "LEASE_GRANTED", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "BlocklistDeviceStrings", "description": "Indicators such as ''RubberDucky'', ''BadUSB'', unfamiliar USB-NIC chipsets."}, {"field": "ServerClassesNoUSB", "description": "Hosts where any USB attach should alert (DCs, hypervisors)."}, {"field": "DHCPVlanScopes", "description": "Scopes allowed to issue leases for corp endpoints vs. guest/IoT."}]', '2026-05-01 15:26:35.733871');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (925, 'AN0115', 'Analytic 0115', 'Detects deletion of launch agents (~/Library/LaunchAgents/) and launch daemons (/Library/LaunchDaemons/), especially after suspicious process execution or when tied to known persistence methods.', '{macOS}', 'x-mitre-analytic--81d64cae-ddd2-4512-9c8a-9a574b968c52', 'DET0040', '[{"name": "macos:unifiedlog", "channel": "log stream", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "LaunchDaemonPath", "description": "Common plist file paths for persistence: ~/Library/LaunchAgents/*.plist"}, {"field": "CorrelatedProcessImage", "description": "Ties deletion to parent process (e.g., suspicious AppleScript runner)"}]', '2026-05-01 15:26:35.735303');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (926, 'AN0614', 'Analytic 0614', 'Detection of Windows container escape attempts by observing processes accessing host directories, symbolic link abuse, or privilege escalation attempts. Defenders may detect anomalous process execution with access to system-level directories outside of container boundaries.', '{Windows}', 'x-mitre-analytic--81e2b983-2159-47d1-9ec1-a5c863faa1a7', 'DET0219', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "RestrictedHostDirs", "description": "Critical system paths containers should not access (e.g., C:\\Windows, C:\\ProgramData)."}]', '2026-05-01 15:26:35.736517');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (927, 'AN1968', 'Analytic 1968', 'If infrastructure or patterns in the malicious web content related to malvertising have been previously identified, internet scanning may uncover when an adversary has staged malicious web content. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on other phases of the adversary lifecycle, such as [Drive-by Compromise](https://attack.mitre.org/techniques/T1189) or [Exploitation for Client Execution](https://attack.mitre.org/techniques/T1203).', '{PRE}', 'x-mitre-analytic--81f695b5-7621-4a82-8036-536c6687b5b4', 'DET0836', '[{"name": "Internet Scan", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--0dcbbf4f-929c-489a-b66b-9b820d3f7f0e"}]', NULL, '2026-05-01 15:26:35.737754');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (928, 'AN1329', 'Analytic 1329', 'OAuth token granted to external app followed by download of high-volume files in OneDrive/Google Drive', '{SaaS}', 'x-mitre-analytic--8226ce94-1f5b-4ab0-b0bc-92f1d225eaa4', 'DET0484', '[{"name": "m365:unified", "channel": "FileAccessed, FileDownloaded, ConsentGranted", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}]', '[{"field": "AppRegistrationNamePattern", "description": "Pattern of suspicious OAuth app names (e.g., `rclone`, `mega`, `backup*`)"}, {"field": "DownloadThresholdMB", "description": "Flag file downloads over X MB (e.g., >100MB) within short intervals"}]', '2026-05-01 15:26:35.739204');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (929, 'AN0450', 'Analytic 0450', 'Detect abnormal MFA activity within cloud service provider logs, such as repeated generation of MFA challenges for the same user session or mismatched MFA device and login origin.', '{IaaS}', 'x-mitre-analytic--824db63f-2a2c-4e3e-8e7d-49110cc63173', 'DET0160', '[{"name": "AWS:CloudTrail", "channel": "AssumeRole or ConsoleLogin with repeated MFA failures followed by repeated MFA requests", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "FailedLoginThreshold", "description": "Number of failed logins before raising detection"}]', '2026-05-01 15:26:35.741114');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (930, 'AN1273', 'Analytic 1273', 'Hidden file system use through APFS containers or custom plist configuration. Defender view: anomalous use of hdiutil or diskutil to attach hidden partitions, modification of plist entries tied to system volumes, or suspicious raw disk access.', '{macOS}', 'x-mitre-analytic--82908b5f-fa84-4420-bb1c-cc77e12e9d3c', 'DET0461', '[{"name": "macos:unifiedlog", "channel": "Execution of diskutil or hdiutil attaching hidden partitions", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Hidden volume attachment or modification events", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "MonitoredPlistPaths", "description": "Adjust to target only relevant plist files linked to volume mounting."}, {"field": "ProcessScope", "description": "Restrict monitoring to sensitive processes like diskutil and hdiutil."}]', '2026-05-01 15:26:35.743153');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (931, 'AN0627', 'Analytic 0627', 'Detects central router or switch config management tools (e.g., FortiManager, Cisco Prime) triggering device reboots or config pushes using abnormal accounts or IPs.', '{"Network Devices"}', 'x-mitre-analytic--82acd5d4-70e1-4f3e-b059-15bdc55cf4bf', 'DET0223', '[{"name": "networkdevice:syslog", "channel": "config push events", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Device-to-Device Deployment Flows", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "PushSourceAllowList", "description": "Devices or IPs allowed to push firmware or scripts"}, {"field": "AuthUserPattern", "description": "Expected CLI or API user performing configuration"}]', '2026-05-01 15:26:35.744645');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (932, 'AN0649', 'Analytic 0649', 'Processes opening /proc/*/mem or /proc/*/maps targeting credential-storing services like sshd or login. Behavior often includes high privilege escalation and memory inspection tools such as gcore or gdb.', '{Linux}', 'x-mitre-analytic--82cdec5a-52af-4489-b002-b0256e5ba60e', 'DET0234', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "ptrace", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetProcessName", "description": "Define sensitive targets (e.g., sshd, login) being memory-read."}, {"field": "ToolProcessName", "description": "Flag use of memory dump tools like gcore, gdb, pmap."}]', '2026-05-01 15:26:35.746172');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (933, 'AN0426', 'Analytic 0426', 'Detects shell-based scripts accessing configuration files or snapshots and transmitting them over unencrypted protocols such as FTP or HTTP to non-management IPs.', '{ESXi}', 'x-mitre-analytic--82f3feb5-f17e-4c1c-b67d-c8331d220905', 'DET0149', '[{"name": "esxi:hostd", "channel": "event stream", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "flow records", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "http.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "VMConfigAccessPathWatchlist", "description": "Locations of VMX/CFG/SNAPSHOT files that should not be accessed by non-admin shells."}, {"field": "OutboundProtocolProfile", "description": "Expected network protocols for guest and host interfaces."}]', '2026-05-01 15:26:35.748472');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (934, 'AN1446', 'Analytic 1446', 'Monitors execution of administrative utilities (e.g., bcdedit.exe) or registry modifications that disable Driver Signature Enforcement (DSE) or enable Test Signing. Correlates command-line activity, registry changes, and subsequent process executions that bypass signing enforcement.', '{Windows}', 'x-mitre-analytic--83067587-4426-44cb-89de-f2b948c91104', 'DET0523', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "MonitoredExecutables", "description": "Expand or restrict monitored utilities (e.g., bcdedit.exe, reg.exe) based on enterprise usage"}, {"field": "RegistryPaths", "description": "Customize registry paths tied to Driver Signing enforcement depending on OS version"}, {"field": "TimeWindow", "description": "Correlation window between registry modification and subsequent unsigned binary execution"}]', '2026-05-01 15:26:35.749838');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (935, 'AN1297', 'Analytic 1297', 'ESXi hosts initiating connections from non-standard daemons mimicking HTTP/HTTPS or SNMP traffic, but with irregular payload formats or expired/unsigned TLS certificates.', '{ESXi}', 'x-mitre-analytic--8307d1d4-4f50-481b-9126-3b145fd68a73', 'DET0470', '[{"name": "esxi:hostd", "channel": "Service-Based Network Connection", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Content", "channel": "TLS Fingerprint and Certificate Analysis", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TLSFingerprintMatch", "description": "Allows matching against known-good or known-bad JA3/JA3S hashes."}, {"field": "AllowedServicePorts", "description": "Tune for expected network ports per ESXi role."}]', '2026-05-01 15:26:35.751081');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (936, 'AN0422', 'Analytic 0422', 'Forged SAML tokens may be leveraged to access O365 apps such as Outlook or SharePoint. Defenders should monitor for token replay across multiple clients or access attempts to privileged mailboxes without prior interactive login.', '{"Office Suite"}', 'x-mitre-analytic--8359e4ed-c4a1-4734-a3dd-e2d3eb33bc90', 'DET0148', '[{"name": "m365:exchange", "channel": "Mailbox access using SAML token without corresponding MFA event", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "m365:sharepoint", "channel": "File access with forged or anomalous SAML claims", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "ReplayDetectionThreshold", "description": "Number of times a token is reused within short timeframe."}]', '2026-05-01 15:26:35.7524');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (937, 'AN1120', 'Analytic 1120', 'LaunchAgent or launchd recurring jobs initiating data transfer to consistent external IPs or domains with repeat timing signatures.', '{macOS}', 'x-mitre-analytic--837bd639-c291-4e42-b737-6a21d6bf8fd5', 'DET0399', '[{"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:launchd", "channel": "launchd.plist and logs", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}, {"name": "macos:unifiedlog", "channel": "networkd or com.apple.network", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AgentPathPatterns", "description": "Regex for job locations like ~/Library/LaunchAgents/"}, {"field": "RepeatIntervalDelta", "description": "Time-based logic to determine schedule (e.g., ~24h ± 5m)"}, {"field": "UserHomeJobs", "description": "Transfers originating from non-admin user context"}]', '2026-05-01 15:26:35.75368');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (938, 'AN0992', 'Analytic 0992', 'Detect suspicious file creations and process executions triggered by browser activity (e.g., injected payloads written to %AppData% or Temp directories, then executed). Correlate network anomalies with subsequent local process creation or script execution.', '{Windows}', 'x-mitre-analytic--8384d942-2f83-4968-9959-fd2f55afb311', 'DET0349', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Unexpected script or binary content returned in HTTP response body", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MonitoredExtensions", "description": "File extensions to flag (exe, dll, js, vbs, sh, etc.)."}, {"field": "SuspiciousParentProcesses", "description": "Browser processes (chrome.exe, firefox.exe, edge.exe, etc.) monitored as possible parents for malicious activity."}, {"field": "RedirectList", "description": "List of suspicious domains or URLs used for malicious redirects."}]', '2026-05-01 15:26:35.75523');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (939, 'AN0412', 'Analytic 0412', 'Massive recursive deletions or overwrites via `rm -rf`, `shred`, `dd`, or wiper binaries. May include unlink syscalls, deletion of known config/data paths, or sequential overwrite patterns.', '{Linux}', 'x-mitre-analytic--839d7053-fc62-433a-8eb2-ed87605160f7', 'DET0146', '[{"name": "auditd:SYSCALL", "channel": "unlink, unlinkat, openat, write", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExecutablePath", "description": "Focus on binaries like shred, dd, wipe, custom wipers, or bash execution chains."}, {"field": "DeletedPathPattern", "description": "Tune for critical mount points or home/data directories."}, {"field": "SyscallBurstRate", "description": "Rate of unlink/unlinkat syscalls to indicate mass deletion in a short period."}]', '2026-05-01 15:26:35.757208');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (940, 'AN0114', 'Analytic 0114', 'Detects removal of persistence artifacts such as crontab entries, systemd service units, and malicious user accounts through commands like `crontab -r`, `rm /etc/systemd/system/*.service`, or `userdel`.', '{Linux}', 'x-mitre-analytic--83a2f3c2-24c5-466d-8453-aa52802c2991', 'DET0040', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "file deletion", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "ServicePathMatch", "description": "Targets suspicious or orphaned unit files in /etc/systemd/system/"}, {"field": "CronUserScope", "description": "Focus on crontab activity from root or uncommon users"}, {"field": "UserDeletionActivity", "description": "Looks for userdel or passwd deletion"}]', '2026-05-01 15:26:35.75923');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (941, 'AN0231', 'Analytic 0231', 'Modification of user desktop backgrounds, login screen messages, or system banners by adversaries using admin privileges or script execution. May coincide with tampering in /Library/Desktop Pictures/ or use of AppleScript.', '{macOS}', 'x-mitre-analytic--83d3222d-6a35-401d-95b5-a09f0eac2201', 'DET0082', '[{"name": "macos:unifiedlog", "channel": "loginwindow or desktopservices modified settings or files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "osascript or AppleScript invocation modifying UI", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "ScriptNames", "description": "Uncommon scripts like AppleScript variants or osascript for wallpaper changes"}, {"field": "UserContext", "description": "Normal users should not alter global visual settings"}]', '2026-05-01 15:26:35.761058');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (942, 'AN1057', 'Analytic 1057', 'Detects processes performing network enumeration (e.g., port scans, service probing) by correlating process creation, socket connections, and sequential destination IP probing within a time window.', '{Windows}', 'x-mitre-analytic--84299e85-2a7e-4f78-9767-3d29aa58857a', 'DET0376', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ScanRateThreshold", "description": "Defines the number of unique destination IPs or ports accessed within a time window that may indicate a scan."}, {"field": "KnownScannerExeList", "description": "List of binaries allowed to scan or used by IT (e.g., Nmap, Nessus)."}, {"field": "TimeWindow", "description": "Temporal bounds for correlating sequential connections (e.g., 60 seconds)."}]', '2026-05-01 15:26:35.763047');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (943, 'AN0265', 'Analytic 0265', 'Account attribute changes (e.g., password set, group membership, servicePrincipalName, logon hours) correlated with unusual process lineage or timing, indicating privilege escalation or persistence via valid accounts.', '{Windows}', 'x-mitre-analytic--842ba5ee-dcd0-42bd-9ef8-867a4ab1c703', 'DET0096', '[{"name": "WinEventLog:Security", "channel": "EventCode=4738, 4728, 4670", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Time between suspicious process and account change (e.g., 5m)."}, {"field": "HighPrivilegeGroupList", "description": "Customize group list (e.g., Domain Admins, Enterprise Admins) to monitor."}, {"field": "SubjectTargetMismatch", "description": "Flag if account modifier != modified user (potential hijack)."}]', '2026-05-01 15:26:35.764893');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (944, 'AN0126', 'Analytic 0126', 'Inconsistencies between process command-line arguments logged at creation time and subsequent process behavior. Defender perspective: monitoring for processes launched in a suspended state, followed by memory modifications (e.g., WriteProcessMemory targeting the PEB) that overwrite arguments before execution resumes. Detection also includes observing anomalous behaviors from processes whose logged arguments do not align with executed activity (e.g., network connections, file writes, or registry modifications).', '{Windows}', 'x-mitre-analytic--84ad99e5-4e6e-4d07-93ae-9e55e6f99707', 'DET0045', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "SuspendedProcessWindow", "description": "Time window in which a process remains in suspended state before being modified. Tunable based on baseline activity in the environment."}, {"field": "SensitiveProcesses", "description": "List of critical processes (e.g., explorer.exe, lsass.exe) where argument spoofing is highly suspicious. Can be customized per organization."}, {"field": "BehavioralCorrelationWindow", "description": "Time span in which to correlate command-line inconsistencies with anomalous behavior such as network activity or registry modification."}]', '2026-05-01 15:26:35.76658');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (963, 'AN0063', 'Analytic 0063', 'Use of launchctl to stop services or kill critical background processes (e.g., securityd, com.apple.*), typically followed by command-line tools like rm or diskutil. Behavioral chain: Terminal or remote shell + launchctl bootout/disable + process termination + follow-on modification.', '{macOS}', 'x-mitre-analytic--86ea7b9c-c017-463d-b5d5-377f6dbfae1e', 'DET0021', '[{"name": "macos:unifiedlog", "channel": "launchctl disable or bootout calls", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "auditd:SYSCALL", "channel": "execve of launchctl or pkill", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ServiceLabel", "description": "Launch daemon label or name targeted by command"}, {"field": "LaunchType", "description": "Whether the command disables or boots out the service"}]', '2026-05-01 15:26:35.797439');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (945, 'AN1288', 'Analytic 1288', 'Execution of Microsoft-signed scripts (e.g., pubprn.vbs, installutil.exe, wscript.exe, cscript.exe) used to proxy execution of untrusted or external binaries. Behavior is detected through command-line process lineage, child process spawning, and unsigned payload execution from signed parent.', '{Windows}', 'x-mitre-analytic--84e969fd-a0ee-425f-a7dd-ae10e170d45a', 'DET0466', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ParentProcessName", "description": "Environment-specific paths to script interpreters like wscript.exe, cscript.exe, pubprn.vbs, or installutil.exe."}, {"field": "TimeWindow", "description": "Time delta between signed script execution and suspicious child process creation."}, {"field": "ChildCommandLineRegex", "description": "Regex pattern used to detect malicious payload execution (e.g., download cradle, PowerShell decode)."}, {"field": "SignedToUnsignedTransition", "description": "Indicates whether the parent is signed by Microsoft but child is unsigned or unknown."}]', '2026-05-01 15:26:35.768206');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (946, 'AN0558', 'Analytic 0558', 'Execution of control.exe or rundll32.exe with parameters pointing to CPL files, especially from non-standard directories or newly created files, followed by suspicious child process execution or registry modifications registering new Control Panel items.', '{Windows}', 'x-mitre-analytic--8581bca4-9d34-4c78-87f7-29244581d140', 'DET0194', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}]', '[{"field": "CPLPathRegex", "description": "Regex to match CPL file paths; tune to exclude legitimate CPLs in System32"}, {"field": "ParentProcessName", "description": "Helps filter known parent processes that legitimately use control.exe"}, {"field": "NewFileTimeWindow", "description": "Time delta between CPL file creation and execution to detect rapid execution of newly dropped files"}, {"field": "RegistryKeyAllowlist", "description": "Whitelist of known good CPL registry entries"}]', '2026-05-01 15:26:35.769925');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (947, 'AN1476', 'Analytic 1476', 'Detects anomalous wireless connections such as unexpected SSID associations, failed or repeated authentication attempts, and connections outside of known geofenced networks. Defenders should monitor wireless connection logs and event codes for network discovery, authentication, and association events.', '{Windows}', 'x-mitre-analytic--8586fd06-9801-473e-8ea6-d3da0ec82267', 'DET0536', '[{"name": "WinEventLog:Microsoft-Windows-WLAN-AutoConfig", "channel": "EventCode=8001, 8002, 8003", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=4776, 4625", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "KnownSSIDList", "description": "Defines approved Wi-Fi SSIDs for the environment; deviations may indicate malicious connection attempts."}, {"field": "GeoLocationContext", "description": "Correlates expected physical location of systems with observed Wi-Fi connections to detect anomalies."}]', '2026-05-01 15:26:35.771392');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (948, 'AN1454', 'Analytic 1454', 'Execution of system info utilities like `systemsetup`, `sw_vers`, `uname`, or `sysctl` by terminal or scripted processes.', '{macOS}', 'x-mitre-analytic--85a20f4b-4171-4450-a34f-17725d44aad9', 'DET0525', '[{"name": "macos:unifiedlog", "channel": "log show --predicate ''process == <utility>''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ParentProcess", "description": "Determine if script or terminal executed the command."}, {"field": "FrequencyThreshold", "description": "Number of discovery commands in a short window."}]', '2026-05-01 15:26:35.773035');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (949, 'AN1436', 'Analytic 1436', 'Adversaries inject VBA macros into Office templates such as Normal.dotm or Personal.xlsb or redirect Office template load path via registry key (GlobalDotName) to gain persistence. Template macros trigger execution of malicious code on application startup.', '{Windows}', 'x-mitre-analytic--85b4c967-56bc-4990-b3e2-7e40f3ef1852', 'DET0519', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Microsoft-Office-Alerts", "channel": "Office application warning or alert on macro execution from template", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TemplatePath", "description": "Path to Normal.dotm, Personal.xlsb, or Excel/Word startup templates may vary by Office version and user"}, {"field": "RegistryPath", "description": "GlobalDotName or equivalent registry keys may differ across Office versions or deployments"}, {"field": "TimeWindow", "description": "Office process creation and macro execution timing after system or user login"}, {"field": "UserContext", "description": "May be scoped to high-value users or those with access to sensitive templates"}]', '2026-05-01 15:26:35.774977');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (950, 'AN0773', 'Analytic 0773', 'Detection of new admin or role assignment actions within Microsoft 365/O365 environments to elevate access for persistence or lateral movement.', '{"Office Suite"}', 'x-mitre-analytic--8601dbfa-8767-4328-8809-1930b53b5e31', 'DET0277', '[{"name": "m365:unified", "channel": "Add member to role, Set-Mailbox", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "OfficeRoleType", "description": "Admin role type or application role granted"}, {"field": "TimeWindow", "description": "Time between initial login and privilege change"}, {"field": "ActionOrigin", "description": "Was the role assignment local or via federated SSO account"}]', '2026-05-01 15:26:35.776602');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (951, 'AN0006', 'Analytic 0006', 'Adversary uses built-in tools such as ''net user /add /domain'' or PowerShell to create a domain user account. The behavior chain includes: (1) suspicious process execution on a domain controller followed by (2) user account creation event (Event ID 4720) on the same host.', '{Windows}', 'x-mitre-analytic--86103b48-cd6d-447d-aef4-807e10355506', 'DET0003', '[{"name": "WinEventLog:Security", "channel": "EventCode=4720", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Detection triggers when Event ID 4720 follows a suspicious process within 2 minutes."}, {"field": "ParentProcessName", "description": "Allow filtering of known admin tools vs adversarial misuse (e.g., net.exe, powershell.exe)."}, {"field": "UserContext", "description": "Filter accounts with domain admin privileges creating new users vs standard helpdesk roles."}, {"field": "HostRole", "description": "Restrict to only domain controller hosts to reduce noise from workstations."}]', '2026-05-01 15:26:35.779533');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (952, 'AN1967', 'Analytic 1967', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Initial Access (ex: [Phishing](https://attack.mitre.org/techniques/T1566)).', '{PRE}', 'x-mitre-analytic--8619af40-05db-49a7-b7b8-476facfd4b2c', 'DET0835', NULL, NULL, '2026-05-01 15:26:35.78115');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (953, 'AN0345', 'Analytic 0345', 'Process invokes a standard encoder (e.g., PowerShell -enc, certutil -encode, base64 via .NET/Invoke-Expression) or emits long Base64/hex literals → shortly followed by outbound network egress with high bytes_out:bytes_in ratio or HTTP headers/payloads containing Base64/MIME blocks.', '{Windows}', 'x-mitre-analytic--861ee805-c979-44c9-8b0c-86bd3a6f5872', 'DET0124', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "M365Defender:DeviceNetworkEvents", "channel": "NetworkConnection: bytes_sent >> bytes_received anomaly", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "PayloadEntropyThreshold", "description": "Shannon entropy cutoff to consider payload suspicious (e.g., > 4.5–5.0 for HTTP body)."}, {"field": "B64LengthThreshold", "description": "Min continuous Base64 token length in command lines/script blocks to alert (e.g., > 100 chars)."}, {"field": "TimeWindow", "description": "Correlation window between encoding event and egress (default 10m)."}, {"field": "KnownAdminTools", "description": "Legitimate tools (e.g., backup agents) that routinely encode/compress data."}, {"field": "BytesOutToInRatio", "description": "Minimum ratio to treat flow as asymmetric (e.g., ≥ 4:1)."}]', '2026-05-01 15:26:35.782477');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (954, 'AN1599', 'Analytic 1599', 'Suspicious process initiating outbound connections to web services without corresponding response or return traffic, indicative of one-way command channels.', '{Windows}', 'x-mitre-analytic--8626f553-efed-4418-bbc6-b9fa83b0b315', 'DET0581', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "etw:Microsoft-Windows-WinINet", "channel": "WinINet API telemetry", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "DestinationDomain", "description": "Can tune for popular web services (e.g., googleapis.com, github.com) based on threat actor tooling"}, {"field": "TimeWindow", "description": "May adjust temporal window to catch beaconing patterns (e.g., every 10-30 mins)"}, {"field": "ProcessName", "description": "Environment-specific tuning to exclude expected update or telemetry tools"}]', '2026-05-01 15:26:35.783821');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (955, 'AN0552', 'Analytic 0552', 'Alterations to plist configuration files (RulesActiveState.plist, SyncedRules.plist, UnsyncedRules.plist, MessageRules.plist) that define email hiding or filtering rules. Defender perspective: unexpected changes in these files associated with Mail.app processes.', '{macOS}', 'x-mitre-analytic--863a9028-6b2a-46c6-b696-dd310937fbf9', 'DET0192', '[{"name": "macos:unifiedlog", "channel": "Modifications to Mail.app plist files controlling message rules", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Mail.app executing with parameters updating rules state", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WatchedPlistFiles", "description": "Adjust to monitor only rule-related plist files relevant to the environment."}]', '2026-05-01 15:26:35.785093');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (956, 'AN0226', 'Analytic 0226', 'Execution of trusted, Microsoft-signed binaries such as `rundll32.exe`, `msiexec.exe`, or `regsvr32.exe` used to execute externally hosted, unsigned, or suspicious payloads through command-line parameters or network retrieval.', '{Windows}', 'x-mitre-analytic--865c00d7-fc01-4ce6-8fc8-d7a84f2ded36', 'DET0081', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ParentProcessName", "description": "Used to profile unexpected parent-child relationships (e.g., regsvr32.exe not launched by explorer.exe)"}, {"field": "SignedBinaryList", "description": "List of known signed binaries allowed for execution (e.g., msiexec.exe, regsvr32.exe)"}, {"field": "CommandLineRegex", "description": "Regex to match suspicious arguments, such as URLs, script paths, or DLL entrypoints"}, {"field": "RemoteDomainAllowlist", "description": "Filter to suppress activity contacting legitimate enterprise domains"}]', '2026-05-01 15:26:35.786354');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1025, 'AN1405', 'Analytic 1405', 'Detects automation macros or VBA scripts in documents that access browser file paths, read cookie data, or attempt to exfiltrate browser session tokens over HTTP.', '{"Office Suite"}', 'x-mitre-analytic--916993bd-600a-43e2-abbf-30c56be84459', 'DET0509', '[{"name": "m365:unified", "channel": "RunMacro", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "MacroTargetPath", "description": "Files or directories macros are attempting to access"}, {"field": "HTTPDestinationIPList", "description": "List of IPs or domains that are uncommon for macro-based HTTP POSTs"}]', '2026-05-01 15:26:35.893872');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (957, 'AN1168', 'Analytic 1168', 'Automated abuse of cloud-hosted applications (e.g., web apps, REST endpoints, internal APIs) causing compute exhaustion, high 5xx error rates, or frequent autoscaling triggers logged in app insights or cloudwatch.', '{IaaS}', 'x-mitre-analytic--867239cd-7939-446c-9efb-b2a7a5bd5403', 'DET0415', '[{"name": "AWS:CloudWatch", "channel": "Elevated 5xx response rates in application logs or gateway layer", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "AWS:CloudTrail", "channel": "InvokeFunction", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"name": "AWS:CloudMetrics", "channel": "Autoscaling, memory/cpu alarms, or instance unhealthiness", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "HTTP5xxRateThreshold", "description": "Ratio of 5xx error codes over requests indicating resource exhaustion."}, {"field": "FunctionInvocationRate", "description": "Spike in lambda/API gateway executions indicating scripted behavior."}, {"field": "AutoscaleEventCount", "description": "Triggers linked to app DoS where legitimate scaling is mimicked."}]', '2026-05-01 15:26:35.787517');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (958, 'AN0482', 'Analytic 0482', 'Defenders may observe adversary attempts to alter or replace a network device’s operating system image through anomalous CLI commands, unexpected firmware updates, integrity check failures, or mismatches in version and checksum validation. Suspicious behavior includes modification of image files on storage, OS version output inconsistent with baselines, unexpected reloads or reboots after image replacement, and changes to boot configuration that load non-standard system images.', '{"Network Devices"}', 'x-mitre-analytic--868abb22-3d6c-4172-bf38-9e3c1aba4dae', 'DET0170', '[{"name": "networkdevice:cli", "channel": "Execution of commands to load, copy, or replace system images (e.g., ''copy tftp flash'', ''boot system'')", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:config", "channel": "Configuration changes to boot variables, startup image paths, or checksum verification failures", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "AuthorizedAdminAccounts", "description": "Defines trusted administrator accounts allowed to modify system images; deviations indicate possible malicious modification."}, {"field": "ApprovedFirmwareVersions", "description": "Whitelist of validated vendor OS images; unexpected versions may suggest adversarial tampering."}, {"field": "TimeWindow", "description": "Correlation window for detecting config changes followed by firmware updates or reboots."}, {"field": "ChecksumBaseline", "description": "Baseline cryptographic hashes of approved system images; deviations may indicate compromise."}]', '2026-05-01 15:26:35.78895');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (959, 'AN2013', 'Analytic 2013', 'If infrastructure or patterns in the malicious web content related to SEO poisoning or [Drive-by Target](https://attack.mitre.org/techniques/T1608/004) have been previously identified, internet scanning may uncover when an adversary has staged web content supporting a strategic web compromise. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on other phases of the adversary lifecycle, such as [Drive-by Compromise](https://attack.mitre.org/techniques/T1189) or [Exploitation for Client Execution](https://attack.mitre.org/techniques/T1203).', '{PRE}', 'x-mitre-analytic--86a212ef-8e7b-4c51-9e7f-492da2283294', 'DET0881', '[{"name": "Internet Scan", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--0dcbbf4f-929c-489a-b66b-9b820d3f7f0e"}]', NULL, '2026-05-01 15:26:35.790843');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (960, 'AN0864', 'Analytic 0864', 'A tampered app/pkg/notarized update is installed via installer, softwareupdated, Homebrew, or vendor updater; new Mach-O or bundle contents appear in /Applications, /Library, /usr/local or /opt/homebrew; first run spawns sh/zsh/osascript/curl and makes egress to unfamiliar domains; AMFI/Gatekeeper may log signature/notarization problems.', '{macOS}', 'x-mitre-analytic--86a87684-5fd5-4778-be36-5dfa07a4246d', 'DET0309', '[{"name": "macos:unifiedlog", "channel": "pkginstalld/softwareupdated/Homebrew install transactions", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:endpointsecurity", "channel": "exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "New/rare egress to non-approved update hosts after install", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AllowedTeamIDs", "description": "Apple Developer Team IDs allowed for enterprise."}, {"field": "BrewTapsAllowList", "description": "Trusted Homebrew taps."}, {"field": "TimeWindow", "description": "Default 90 minutes."}]', '2026-05-01 15:26:35.792598');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (961, 'AN0575', 'Analytic 0575', 'Detects VM enumeration attempts using virtualization utilities such as VirtualBox (`VBoxManage`) or Parallels CLI. Defender observes abnormal invocation of VM listing commands correlated with non-admin users or unusual parent processes.', '{macOS}', 'x-mitre-analytic--86bb41b4-5c8a-4407-b788-8f6ea8457860', 'DET0199', '[{"name": "macos:unifiedlog", "channel": "process_name IN (\"VBoxManage\", \"prlctl\") AND command CONTAINS (\"list\", \"show\")", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Adjust sensitivity depending on whether the command is executed by admin or non-admin users."}, {"field": "ExecutionTimeWindow", "description": "Restrict alerts to unusual times when VM management is not expected."}]', '2026-05-01 15:26:35.79453');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (962, 'AN0441', 'Analytic 0441', 'Unusual screensaver (.scr) executions correlated with recent registry modifications to HKCU\Control Panel\Desktop values such as SCRNSAVE.exe, ScreenSaveTimeout, and ScreenSaveActive. Detection focuses on PE image paths not consistent with known legitimate screensavers and triggered after user inactivity timeout.', '{Windows}', 'x-mitre-analytic--86dbac4c-1cba-4056-84a1-604eefbb11ac', 'DET0154', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TimeWindow", "description": "Adjust the user inactivity threshold that defines ''screensaver trigger window''; shorter timeouts may increase sensitivity."}, {"field": "SuspiciousPathRegex", "description": "Allow tuning based on expected paths for legitimate .scr files vs suspicious locations (e.g., user temp directories)."}, {"field": "ParentProcessAllowList", "description": "Allowlisting known legitimate initiators of .scr files (e.g., user32.dll context) to reduce false positives."}, {"field": "RegistryEditorProcessName", "description": "Monitor for registry modification performed by unusual processes (e.g., powershell.exe, reg.exe)."}]', '2026-05-01 15:26:35.796185');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (964, 'AN1481', 'Analytic 1481', '1) Package manager or curl/wget installs/upgrades from non-approved repos or unsigned packages; 2) new ELF written into PATH directories or replacement of existing binaries/libraries; 3) first run leads to unexpected child processes or outbound connections.', '{Linux}', 'x-mitre-analytic--86f2dfd5-7073-4178-8c83-8628ecf087d4', 'DET0537', '[{"name": "auditd:SYSCALL", "channel": "execve, unlink", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open, rename", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "journald:package", "channel": "dpkg/apt install, remove, upgrade events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "NSM:Flow", "channel": "First-time egress to unknown registries/mirrors immediately after install", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ApprovedRepos", "description": "Allow-listed APT/YUM repo URLs and GPG key fingerprints."}, {"field": "PathScope", "description": "Directories to watch for new ELF writes (e.g., /usr/bin, /usr/local/bin, /lib*/, /opt/*/bin)."}, {"field": "MinBinarySize", "description": "Ignore tiny helper files; default >16KB."}, {"field": "TimeWindow", "description": "Install→first-run correlation window (default 2h)."}]', '2026-05-01 15:26:35.798711');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (965, 'AN1055', 'Analytic 1055', 'Track creation or update of SaaS automation scripts (e.g., Google Workspace Apps Script). Detect when these scripts are bound to user events such as file opens or account modifications, and correlate with subsequent abnormal API calls that exfiltrate or modify user data.', '{SaaS}', 'x-mitre-analytic--8708dc0b-8eeb-4a3d-8770-2fab30f46682', 'DET0374', '[{"name": "saas:appsscript", "channel": "Create / Update: Deployment of scripts with event-driven triggers", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "saas:googledrive", "channel": "FileOpen / FileAccess: Event-driven script triggering on user file actions", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ScriptScope", "description": "Which SaaS apps or APIs can be legitimately automated in the environment"}, {"field": "TriggerTypes", "description": "Event-driven triggers (e.g., on file open, on user creation) considered suspicious"}]', '2026-05-01 15:26:35.800141');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (966, 'AN1950', 'Analytic 1950', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (967, 'AN0393', 'Analytic 0393', 'Detects deletion of suspicious files (e.g., payloads, temp exes, scripts) via `rm`, `unlink`, or secure deletion tools like `shred`, especially when performed by unexpected users or shortly after execution.', '{Linux}', 'x-mitre-analytic--874f0437-1aab-4cfe-a30a-7586c0602b6f', 'DET0140', '[{"name": "auditd:SYSCALL", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PathRegex", "description": "Pattern matching known attacker staging directories or hidden file paths."}, {"field": "TimeWindow", "description": "Deletion shortly after process execution or privilege escalation."}, {"field": "SecureDeletionTool", "description": "Uncommon presence or use of `shred`, `wipe`, or `srm`."}]', '2026-05-01 15:26:35.802567');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (968, 'AN1586', 'Analytic 1586', 'ESXi shell or SSH access issuing `esxcli network diag ping` or viewing routing tables to identify connected hosts.', '{ESXi}', 'x-mitre-analytic--88041144-900d-4968-9e8a-8f1f63ae8417', 'DET0574', '[{"name": "esxi:hostd", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ESXCommandPattern", "description": "Match specific diag/debug commands abused for recon"}, {"field": "RemoteUserShell", "description": "Detect unauthorized shell use or user context (e.g., root over SSH)"}]', '2026-05-01 15:26:35.803989');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (969, 'AN0143', 'Analytic 0143', 'Detect sudo activity with NOPASSWD in /etc/sudoers or disabling tty_tickets, followed by immediate privileged commands (e.g., echo ''Defaults !tty_tickets'' >> /etc/sudoers).', '{macOS}', 'x-mitre-analytic--8825b589-3a6a-483a-9fc0-a4d00b1183ab', 'DET0052', '[{"name": "macos:unifiedlog", "channel": "exec or sudo usage with NOPASSWD context or echo modifying sudoers", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "Terminal process killed (killall Terminal) immediately after sudoers modification", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "admin_user_context", "description": "Define allowed users who may modify sudoers without investigation"}, {"field": "terminal_restart_window", "description": "Time window after sudoers file change to monitor for Terminal restarts"}]', '2026-05-01 15:26:35.806692');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (970, 'AN1941', 'Analytic 1941', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (971, 'AN1635', 'Analytic 1635', 'Detects exploitation of macOS security and integrity services, such as Gatekeeper, XProtect, or EDR agents. Defender observations include unsigned processes attempting privileged operations, abnormal termination of security daemons, or modification of system integrity logs.', '{macOS}', 'x-mitre-analytic--88d9dbea-cc85-4c94-a368-e5c1a603854b', 'DET0595', '[{"name": "macos:unifiedlog", "channel": "Abnormal terminations of com.apple.security.* or 3rd-party security daemons", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:osquery", "channel": "execve: Unsigned or unnotarized processes launched with high privileges", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SecurityDaemons", "description": "Monitored Apple and third-party EDR/AV daemon names."}, {"field": "UnsignedProcessThreshold", "description": "Number of unsigned high-privilege executions before alerting."}]', '2026-05-01 15:26:35.810435');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1060, 'AN1978', 'Analytic 1978', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during exfiltration (ex: [Transfer Data to Cloud Account](https://attack.mitre.org/techniques/T1537)).', '{PRE}', 'x-mitre-analytic--97ec7ade-18b7-43b7-b267-85470862b6ac', 'DET0846', NULL, NULL, '2026-05-01 15:26:35.947189');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (972, 'AN0951', 'Analytic 0951', 'Monitors binary modification in /Applications and system library paths. Detects unsigned or improperly signed binaries executed after modification. Tracks Gatekeeper or notarization bypass attempts tied to modified binaries.', '{macOS}', 'x-mitre-analytic--88eaf8ce-b48d-4329-a147-dd5d065cead2', 'DET0336', '[{"name": "macos:unifiedlog", "channel": "binary modified or replaced", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "execution of modified binary without valid signature", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ApplicationPaths", "description": "Tune which application and library directories are monitored for tampering"}, {"field": "SignatureVerificationDepth", "description": "Define strictness of code-signing validation checks"}]', '2026-05-01 15:26:35.811993');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (973, 'AN0675', 'Analytic 0675', 'Detects forged Kerberos Silver Tickets by identifying anomalous Kerberos service ticket activity such as malformed fields in logon events, TGS requests without interaction with the KDC, and access attempts using service accounts outside expected hosts/resources. Also monitors suspicious processes accessing LSASS memory for credential dumping.', '{Windows}', 'x-mitre-analytic--88ece783-08bc-41e6-a000-a63f540768cc', 'DET0241', '[{"name": "WinEventLog:Security", "channel": "EventCode=4672, 4634", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Kerberos", "channel": "Kerberos TGS-REQ anomalies without KDC validation (Silver Ticket behavior)", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "ServiceAccountScope", "description": "Expected mapping of service accounts to specific resources; deviations may indicate Silver Ticket use."}, {"field": "TicketValidationBaseline", "description": "Expected TGS issuance patterns including KDC validation; anomalies may signal forged tickets."}, {"field": "ProcessAllowlist", "description": "Known processes that legitimately interact with LSASS; others may indicate dumping attempts."}, {"field": "TimeWindow", "description": "Correlate Kerberos requests within a tunable timeframe to reduce false positives."}]', '2026-05-01 15:26:35.813837');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (974, 'AN1194', 'Analytic 1194', 'CLI or automated utilities accessing raw device volumes or flash storage directly (e.g., via `copy flash:`, `format`, or `partition` commands).', '{"Network Devices"}', 'x-mitre-analytic--892f06ae-6a95-438b-8219-49b3384a4d24', 'DET0426', '[{"name": "networkdevice:cli", "channel": "command logging", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandScope", "description": "Limit detection to volume-level commands (e.g., `format`, `copy`, `mount`, `erase`)."}, {"field": "DeviceTypeFilter", "description": "Filter by internal vs. removable volume interactions (e.g., flash, SD card)."}]', '2026-05-01 15:26:35.815206');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (975, 'AN1386', 'Analytic 1386', 'Hidden files via ''chflags hidden'' or Apple-specific attributes, LaunchAgents/LaunchDaemons placed in non-standard hidden directories. Defender view: detect command execution modifying file flags and unusual plist creation in hidden paths.', '{macOS}', 'x-mitre-analytic--8963772e-2ee5-421e-aec0-b952d05d4efc', 'DET0502', '[{"name": "macos:unifiedlog", "channel": "Execution of chflags hidden or setfile -a V", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "Creation of LaunchAgents/LaunchDaemons in hidden or non-standard directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "HiddenDirectories", "description": "List of directories monitored for hidden plist or agent placement."}]', '2026-05-01 15:26:35.81652');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (976, 'AN0589', 'Analytic 0589', 'Registry read access associated with suspicious or non-interactive processes querying system config, installed software, or security settings.', '{Windows}', 'x-mitre-analytic--8986f2ab-2e6d-4c68-99ac-6a1c5f29fb7b', 'DET0209', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TargetRegistryPath", "description": "Focus detection on registry hives or keys likely to reveal environment info (e.g., HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion)."}, {"field": "ParentProcess", "description": "May tune for suspicious parent processes such as cmd.exe, wscript.exe, or mshta.exe."}, {"field": "TimeWindow", "description": "Controls how closely registry access must follow process creation for correlation."}]', '2026-05-01 15:26:35.817756');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (977, 'AN0832', 'Analytic 0832', 'Detects execution of archiving utilities (tar, gzip, bzip2, xz, zip, openssl) followed by suspicious archive file creation. Correlates archive creation in temporary or staging directories with execution of commands involving compression or encryption options.', '{Linux}', 'x-mitre-analytic--89cfa3ac-22c9-462f-a6a5-b142124e22a5', 'DET0298', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of tar, gzip, bzip2, xz, zip, or openssl with compression/encryption arguments", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:FILE", "channel": "create: Creation of archive files in /tmp, /var/tmp, or user home directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ArchiveCommands", "description": "List of archiving utilities considered suspicious."}, {"field": "MonitoredDirectories", "description": "Paths where archive creation is flagged as unusual (e.g., /tmp, /var/tmp)."}, {"field": "TimeWindow", "description": "Correlation window for linking utility execution with archive creation."}]', '2026-05-01 15:26:35.819162');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1000, 'AN0201', 'Analytic 0201', 'Anomalous access to cloud web applications using session tokens without corresponding MFA/credential validation, often from unusual locations or device fingerprints.', '{IaaS}', 'x-mitre-analytic--8d43ac43-de80-4815-b992-6f49519ed340', 'DET0074', '[{"name": "AWS:CloudTrail", "channel": "SessionToken used without preceding MFA or login event", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "AWS:CloudTrail", "channel": "ConsoleLogin", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "TimeWindow", "description": "How far back to check for legitimate MFA or login events before token usage"}, {"field": "IPGeolocationDistance", "description": "Threshold for flagging geographically impossible logins"}]', '2026-05-01 15:26:35.857224');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (978, 'AN0340', 'Analytic 0340', 'Creation or modification of Login Items using AppleScript or Service Management Framework. Detection focuses on file creation/modification of `backgrounditems.btm`, new executables in `Contents/Library/LoginItems/`, use of `SMLoginItemSetEnabled` API, or suspicious processes triggered post-login without user interaction. Behavioral pivot includes anomalous AppleEvents, suspicious parent-child process pairs, and login-triggered execution chains.', '{macOS}', 'x-mitre-analytic--89e3509c-d732-4826-ac78-baea8fbf0834', 'DET0121', '[{"name": "macos:unifiedlog", "channel": "Post-login execution of unrecognized child process from launchd or loginwindow", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Modification of backgrounditems.btm or creation of LoginItems subdirectory in .app bundle", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Invocation of SMLoginItemSetEnabled by non-system or recently installed application", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "macos:unifiedlog", "channel": "AppleScript creating login item via ''System Events'' dictionary", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "TimeWindow", "description": "Correlate file and process activity within a defined interval post-login (e.g., 0–5 minutes)"}, {"field": "UserContext", "description": "Distinguish between system users, interactive users, and daemon contexts"}, {"field": "ExecutableAllowlist", "description": "Define known-good login items to suppress false positives"}, {"field": "PathRegexExclusion", "description": "Exclude common enterprise paths (e.g., Jamf, MDM-managed apps)"}]', '2026-05-01 15:26:35.820448');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (979, 'AN0389', 'Analytic 0389', 'Detects credential harvesting via userland API hooking (e.g., SetWindowsHookEx, IAT, or inline patching) by correlating memory modifications with hook installation functions and suspicious module loads in credential-sensitive processes like lsass.exe, explorer.exe, or winlogon.exe.', '{Windows}', 'x-mitre-analytic--89e3c3a3-249e-4af3-8885-92c228d88b02', 'DET0139', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "TargetProcess", "description": "Credential-sensitive targets (e.g., explorer.exe, winlogon.exe) may vary by environment"}, {"field": "AccessMask", "description": "Tuning for access rights like 0x1FFFFF for full access vs. thread injection"}, {"field": "TimeWindow", "description": "Correlate memory access and hook setup in short windows (5–10 seconds)"}]', '2026-05-01 15:26:35.821949');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (980, 'AN1332', 'Analytic 1332', 'Monitor resolver logs and auditd events for domains resolving to a rotating set of IPs within very short TTL intervals. Correlate high query rates from non-browser applications (e.g., python, curl).', '{Linux}', 'x-mitre-analytic--8a226737-e2a7-4b70-8964-98c47444a638', 'DET0485', '[{"name": "auditd:SYSCALL", "channel": "socket/connect", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TTLThreshold", "description": "Minimum TTL value considered suspicious (e.g., < 60 seconds)"}, {"field": "DomainReputationFeed", "description": "External TI feed to exclude benign CDN or load balancer behavior"}]', '2026-05-01 15:26:35.824016');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (981, 'AN0513', 'Analytic 0513', 'Process or script enumerates network shares via CLI (net view/net share, PowerShell Get-SmbShare/WMI) or OS APIs (NetShareEnum/ srvsvc.NetShareEnumAll RPC) → bursts of outbound SMB/RPC connections (445/139, \\host\IPC$ / srvsvc) to many hosts inside a short window → optional follow-on file listing or copy operations.', '{Windows}', 'x-mitre-analytic--8a2537c3-9e9a-482d-81e2-281f88cf8878', 'DET0182', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=17", "x_mitre_data_component_ref": "x-mitre-data-component--b9a1578e-8653-4103-be23-cb52e0b1816e"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "etw:Microsoft-Windows-RPC", "channel": "rpc_call: srvsvc.NetShareEnum / NetShareEnumAll from non-admin or unusual processes", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "BurstHostThreshold", "description": "Minimum number of unique destination hosts over SMB within TimeWindow to treat as scanning (e.g., ≥5)."}, {"field": "TimeWindow", "description": "Correlation window between the discovery process start and SMB fan-out (default 10m)."}, {"field": "AllowedDiscoveryAccounts", "description": "Service/admin accounts legitimately running inventory scripts."}, {"field": "PipeNameAllowList", "description": "Pipes (e.g., \\PIPE\\spoolss) normally accessed by management agents; exclude from alerts."}]', '2026-05-01 15:26:35.826122');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (982, 'AN0754', 'Analytic 0754', 'vSphere API logins (vimService) or SSH to ESXi host followed by unauthorized shell commands or lateral remote logins from the ESXi host.', '{ESXi}', 'x-mitre-analytic--8a534291-3b75-45ba-9f7b-b952251a3f03', 'DET0269', '[{"name": "esxi:vmkernel", "channel": "vim.fault.*, DCUI login, SSH shell", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "esxi:shell", "channel": "Command execution trace", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SessionType", "description": "Filter by DCUI, SSH, vSphere API"}, {"field": "CommandPattern", "description": "Watch for remote access tool invocations (e.g., netcat, ssh)"}]', '2026-05-01 15:26:35.828014');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1001, 'AN1280', 'Analytic 1280', 'Enumeration of saved Wi-Fi profiles and cleartext password retrieval using `netsh wlan` or API-level access to `wlanAPI.dll`.', '{Windows}', 'x-mitre-analytic--8d58973f-7fd7-435e-86b8-58f9b399f89f', 'DET0464', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "WiFiProfileName", "description": "Filter by known saved SSID names to reduce benign usage of network diagnostics"}, {"field": "ParentProcess", "description": "Anomalous parent-child relationships may be used to spot abuse (e.g., Office → netsh)"}, {"field": "TimeWindow", "description": "Correlate profile enumeration and password dumping within short timeframe (e.g., 60 seconds)"}]', '2026-05-01 15:26:35.858902');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (983, 'AN1512', 'Analytic 1512', 'Processes (tar, curl, python scripts) accessing large file sets and initiating outbound HTTPS POST requests with payload sizes inconsistent with baseline activity. Defender perspective: detect abnormal sequence of file archival followed by encrypted uploads to external web services.', '{Linux}', 'x-mitre-analytic--8a5a1b1e-336f-41af-8f30-2fa7e8e10fab', 'DET0548', '[{"name": "auditd:EXECVE", "channel": "curl or wget with POST/PUT options", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "open/read of sensitive directories (/etc, /home/*)", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "sustained outbound HTTPS sessions with high data volume", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "MonitoredTools", "description": "Suspicious command-line utilities used for exfiltration (curl, wget, python)."}, {"field": "DataVolumeThreshold", "description": "Bytes transferred threshold per session to flag unusual uploads."}]', '2026-05-01 15:26:35.830658');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (984, 'AN1989', 'Analytic 1989', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (985, 'AN0806', 'Analytic 0806', 'Detects crontab job additions or modifications via `crontab` utility or direct edits, especially those created by interactive users executing hidden or renamed scripts.', '{macOS}', 'x-mitre-analytic--8a764f0e-4bcd-413d-bbf0-1a10cb98b598', 'DET0290', '[{"name": "macos:unifiedlog", "channel": "process: crontab edits, launch of cron job", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "fs:fsusage", "channel": "file access to /usr/lib/cron/tabs/ and cron output files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "ScriptPath", "description": "Match scheduled binary path to trusted directory baseline."}, {"field": "CronScheduleSyntax", "description": "Flags excessive frequency or wildcard-heavy cron expressions."}, {"field": "InteractiveUserContext", "description": "Limit cron job writes from interactive shells."}]', '2026-05-01 15:26:35.833829');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (986, 'AN0628', 'Analytic 0628', 'Detects anomalous use of COM objects for execution, such as Office applications spawning scripting engines, enumeration of COM interfaces via registry queries, or processes loading atypical DLLs through COM activation. Correlates process creation, module loads, and registry queries to flag suspicious COM-based code execution or persistence.', '{Windows}', 'x-mitre-analytic--8a7a7e80-c28e-42b2-a222-c1d75932c986', 'DET0224', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}]', '[{"field": "COMObjectAllowList", "description": "Legitimate COM CLSIDs and ProgIDs used by enterprise applications, to reduce false positives."}, {"field": "ParentProcessExclusions", "description": "Expected parent-child process relationships (e.g., explorer.exe spawning dllhost.exe)."}, {"field": "TimeWindow", "description": "Threshold for correlating COM object execution with subsequent process creation or DLL load."}]', '2026-05-01 15:26:35.835169');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (987, 'AN2003', 'Analytic 2003', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (988, 'AN0230', 'Analytic 0230', 'Adversary leverages root or sudo access to alter system banners, web content directories (e.g., /var/www/html), or login configurations (/etc/issue). File creation or overwrites may coincide with suspicious script execution or cron job activity.', '{Linux}', 'x-mitre-analytic--8ba0c3e2-9544-47d1-9738-757c35dc19fa', 'DET0082', '[{"name": "auditd:SYSCALL", "channel": "open/write/unlink", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "sudo or su access prior to content change", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "TargetDirectories", "description": "Paths like /var/www/html, /etc/issue, or /etc/motd may vary across distros"}, {"field": "UserContext", "description": "Non-web-admin users modifying site content or banners should be rare"}, {"field": "TimeWindow", "description": "Defacement often happens outside normal maintenance hours"}]', '2026-05-01 15:26:35.837859');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1002, 'AN0181', 'Analytic 0181', 'Execution of processes using nohup or shell redirection to ignore SIGHUP and continue running after session termination. Defender perspective: correlation between commands including nohup, disowned jobs, or `&` suffix with continued process execution after parent terminal exit.', '{Linux}', 'x-mitre-analytic--8d75d4b3-6748-4d1c-936c-129ee56a12a5', 'DET0067', '[{"name": "auditd:SYSCALL", "channel": "execve call including ''nohup'' or trailing ''&''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "process persists beyond parent shell termination", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "IgnoredSignals", "description": "Specific signals to monitor (e.g., SIGHUP, SIGINT) depending on environment baseline."}, {"field": "ProcessLifetimeThreshold", "description": "Duration a process continues running after session logout, adjustable to reduce noise from benign long-lived jobs."}]', '2026-05-01 15:26:35.860419');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (989, 'AN1035', 'Analytic 1035', 'Detects tampered hardware or firmware via anomalous host status telemetry. Behavioral chain: (1) Pre-OS or firmware components exhibit unexpected version changes, signature failures, or modified boot paths; (2) System management/firmware tools log hardware inventory drift; (3) Sensor health telemetry or boot attestation events fail baseline checks; (4) Follow-on process execution from altered firmware or unknown drivers after boot.', '{Windows}', 'x-mitre-analytic--8ba8d516-486a-4347-9a48-56a312e83897', 'DET0368', '[{"name": "WinEventLog:Security", "channel": "EventCode=1166, 7045", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "channel": "Code integrity violations in boot-start drivers or firmware", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "BaselineFirmwareVersion", "description": "Expected firmware/BIOS version for each hardware model."}, {"field": "BaselineDriverList", "description": "Approved boot-start drivers."}, {"field": "IntegrityCheckInterval", "description": "Frequency of integrity checks (e.g., daily, weekly)."}]', '2026-05-01 15:26:35.839275');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (990, 'AN0489', 'Analytic 0489', 'High-frequency, repetitive service requests (e.g., HTTP, TLS renegotiation) originating from a single or small set of source IPs targeting endpoint web services or application ports, leading to exhaustion of CPU or memory on targeted Windows services.', '{Windows}', 'x-mitre-analytic--8c03988c-3387-48e4-8013-7b9d223b8911', 'DET0173', '[{"name": "WinEventLog:Application", "channel": "Unexpected spikes in request volume, application-level errors, or thread pool exhaustion in web or API logs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "Windows:perfmon", "channel": "Sustained CPU/memory exhaustion by service process (e.g., w3wp.exe)", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "TimeWindow", "description": "Defines burst threshold (e.g., 1 min, 5 min) for connection spikes"}, {"field": "TargetServicePort", "description": "Specific ports/services likely to be abused (e.g., 80, 443, 8080)"}, {"field": "CPUThreshold", "description": "Level of sustained CPU usage considered anomalous for a given service"}]', '2026-05-01 15:26:35.841155');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (991, 'AN0264', 'Analytic 0264', 'Adversary adds a new Outlook rule with modified or obfuscated PR_RULE_MSG_NAME and PR_RULE_MSG_PROVIDER attributes using MFCMapi or Ruler. Rule is triggered when email arrives, executing embedded or external code. Mailbox audit logs or Unified Audit Log shows automated rule-triggered action without user interaction.', '{"Office Suite"}', 'x-mitre-analytic--8c0c52d0-7357-4073-84fc-d262632d268f', 'DET0095', '[{"name": "m365:unified", "channel": "Creation or modification of inbox rule outside of normal user behavior", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:messagetrace", "channel": "Inbound email matches crafted rule trigger pattern tied to persistence logic", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AuditPolicyScope", "description": "Mailbox rule changes may not be captured unless advanced audit logging is enabled"}, {"field": "RuleProviderName", "description": "Malicious rules may use spoofed or non-standard PR_RULE_MSG_PROVIDER values"}, {"field": "TriggerSubjectKeywords", "description": "Triggering emails may contain uncommon but benign-looking subjects"}, {"field": "UserContext", "description": "Target user account may be inactive or high-value (e.g., VIP, service account)"}]', '2026-05-01 15:26:35.842828');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (992, 'AN1077', 'Analytic 1077', 'Detects adversary behavior where a newly created or renamed user account closely resembles existing service or administrator accounts to blend in and avoid detection. Common patterns include prefix/suffix modifications, homoglyphs, or use of names like ''admin1'', ''adm1n'', or ''backup_help''.', '{Windows}', 'x-mitre-analytic--8c3a43bc-dd07-4e72-a987-a2dc36e162fa', 'DET0383', '[{"name": "WinEventLog:Security", "channel": "EventCode=4720", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "windows:osquery", "channel": "User enumeration with creation/last modified timestamps", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "SimilarityThreshold", "description": "Defines how close in Levenshtein or visual distance an account name must be to a legitimate one to raise an alert."}, {"field": "MonitoredAccountList", "description": "Set of known legitimate accounts to compare new account names against."}, {"field": "TimeWindow", "description": "Period within which anomalous account creation or renaming is evaluated in relation to discovery or deletion activity."}]', '2026-05-01 15:26:35.844259');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (993, 'AN0401', 'Analytic 0401', 'Unexpected processes (e.g., bash, python, custom binaries) dynamically loading libcrypto or performing AES/RC4 encryption operations, then initiating outbound sessions with abnormal byte entropy or asymmetric traffic patterns.', '{Linux}', 'x-mitre-analytic--8c64bf26-bda2-47fc-867d-bcc6a51d57a7', 'DET0143', '[{"name": "auditd:SYSCALL", "channel": "execve or socket/connect system calls from processes using crypto libraries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "System daemons initiating encrypted sessions with unexpected destinations", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "linux:osquery", "channel": "Process linked with libcrypto.so making external connections", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TrustedCryptoLibs", "description": "Baseline expected crypto libraries to suppress false positives."}, {"field": "TrafficAsymmetryRatio", "description": "Ratio of sent/received bytes indicating possible hidden C2."}]', '2026-05-01 15:26:35.845563');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (994, 'AN0235', 'Analytic 0235', 'An adversary running with SYSTEM-level privileges executes commands or accesses registry keys to dump the SAM hive or directly reads sensitive local files from the config directory. This behavior often involves sequential access to HKLM\SAM, HKLM\SYSTEM, and creation of .save or .dmp files, enabling offline hash extraction.', '{Windows}', 'x-mitre-analytic--8c881d82-21c3-482c-8895-c240360eec8e', 'DET0085', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "CommandLinePattern", "description": "Detectable variations include `reg save`, `reg.exe save`, or PowerShell equivalents for dumping SAM/SYSTEM hives."}, {"field": "TargetFilePath", "description": "Defenders can tune based on dump file path patterns (e.g., `%TEMP%\\sam.save`, `C:\\Users\\Public\\*.dmp`)."}, {"field": "RegistryPath", "description": "Tune for HKLM\\SAM, HKLM\\SYSTEM or access via direct \\Device\\Harddisk paths."}, {"field": "TimeWindow", "description": "Temporal gap between SAM and SYSTEM hive dumping can be tuned (e.g., 3 minutes)."}, {"field": "ParentProcessName", "description": "Useful for suppressing known-good access (e.g., backup tools)."}]', '2026-05-01 15:26:35.847231');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (995, 'AN0962', 'Analytic 0962', 'A user is socially engineered (web page, email, document) to open Run/PowerShell/CMD and paste an obfuscated one-liner. The chain is: (1) user context active in a browser/email/office app → (2) process creation of a command interpreter with suspicious arguments (base64/Invoke-Expression/web download/pipeline to shell) → (3) optional file drop in %TEMP% or %APPDATA% → (4) outbound network connection to an external domain. Events are correlated within a short window and with consistent user/session.', '{Windows}', 'x-mitre-analytic--8cb0a7da-942b-4771-b9d5-cf558755677a', 'DET0340', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "HTTP(S) requests with User-Agents typical of PowerShell or curl from desktop; or URIs matching paste-inspired payload hosts", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Correlation horizon from parent app (browser/email/office) to interpreter spawn (e.g., 15 minutes)."}, {"field": "ParentProcessAllowList", "description": "Legitimate automation that spawns PowerShell/CMD from Office/Email/Browser."}, {"field": "SuspiciousArgPatterns", "description": "List of command-line substrings indicating pasted one-liners (e.g., ''-enc'', ''FromBase64String'', ''IEX('', ''DownloadString'', ''Invoke-WebRequest'', ''curl|wget.*\\|\\s*(sh|bash|powershell)'')."}, {"field": "WritePaths", "description": "Directories treated as risky for first-stage drops (%TEMP%, %APPDATA%, %PUBLIC%)."}, {"field": "OutboundCIDRBlockList", "description": "Internet ranges/domains to alert on for first-run egress."}]', '2026-05-01 15:26:35.848494');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (996, 'AN0260', 'Analytic 0260', 'Detects creation or alteration of LaunchAgents or LaunchDaemons with corresponding plist modification followed by execution of associated binaries.', '{macOS}', 'x-mitre-analytic--8cbda989-39e6-4f9e-8e23-213f92b3479d', 'DET0094', '[{"name": "macos:unifiedlog", "channel": "process launch", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "disk activity on /Library/LaunchAgents or LaunchDaemons", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:osquery", "channel": "launchd_jobs", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}]', '[{"field": "PlistLabel", "description": "Labels not associated with known applications or vendors."}, {"field": "LaunchPath", "description": "Executable path outside of standard directories (/usr/bin, /Applications)."}, {"field": "JobRunInterval", "description": "Unexpected periodic job intervals (e.g., every minute)."}]', '2026-05-01 15:26:35.849706');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (997, 'AN0743', 'Analytic 0743', 'Background launch agents/daemons with high CPU use and network access to external mining services.', '{macOS}', 'x-mitre-analytic--8cbeecbb-429f-4f30-9f42-266aaa7b2c0f', 'DET0267', '[{"name": "macos:unifiedlog", "channel": "launchctl activity and process creation", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Persistent outbound traffic to mining domains", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "launchdLabel", "description": "Suspicious or unknown launch agents"}, {"field": "TrafficVolumeThreshold", "description": "Outbound bandwidth usage thresholds"}]', '2026-05-01 15:26:35.851075');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (998, 'AN1307', 'Analytic 1307', 'macOS environmental keying behavioral chain: (1) System information discovery through native utilities (system_profiler, sw_vers, hostname, dscl) and Security framework queries, (2) Hardware and software enumeration including serial numbers, installed applications, and system versions, (3) Network configuration assessment (networksetup, scutil) and wireless network discovery, (4) Keychain and security context validation, (5) Unified Logs correlation with cryptographic framework usage (CommonCrypto, Security.framework), (6) Application bundle execution following environmental validation', '{macOS}', 'x-mitre-analytic--8cd02c43-f3f5-4623-a816-cefe1f586288', 'DET0474', '[{"name": "macos:unifiedlog", "channel": "process execution events for discovery utilities (system_profiler, sw_vers, dscl, networksetup) with command-line parameter analysis", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Security framework operations including keychain access, cryptographic operations, and certificate validation", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "fs:fsevents", "channel": "file system events indicating access to system configuration files and environmental information sources", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "SystemProfilerDataTypes", "description": "Specific system_profiler data types that adversaries commonly target (SPHardwareDataType, SPSoftwareDataType, SPNetworkDataType) - customize based on threat intelligence"}, {"field": "SecurityFrameworkOperationPatterns", "description": "Security.framework and CommonCrypto API usage patterns indicating cryptographic operations for environmental keying"}, {"field": "UnifiedLogRetentionWindow", "description": "Time window for correlating discovery activities with subsequent cryptographic operations - balance between detection coverage and log volume"}, {"field": "ApplicationBundleValidationPaths", "description": "Specific application bundle paths and identifiers that might be subject to environmental validation"}, {"field": "NetworkConfigurationIdentifiers", "description": "Organization-specific network configurations, WiFi SSIDs, and network services that adversaries might validate against"}, {"field": "MacOSVersionBaseline", "description": "Expected macOS versions and configurations in environment to identify version-specific environmental targeting"}, {"field": "FSEventsFilteringCriteria", "description": "File system event filtering criteria to focus on security-relevant file access patterns while managing event volume"}]', '2026-05-01 15:26:35.85231');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (999, 'AN0601', 'Analytic 0601', 'Detection of Mach-O binaries or AppleScripts that contain nested, encoded, or run-only embedded payloads dropped at runtime.', '{macOS}', 'x-mitre-analytic--8cd6ae3d-7f14-42bf-9aff-870209fc333f', 'DET0214', '[{"name": "macos:unifiedlog", "channel": "logd:file write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "mach_o_info, file_metadata", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "ScriptFormatType", "description": "Run-only AppleScripts or signed scripting payloads may require scoped detection"}, {"field": "DroppedBinaryCount", "description": "Threshold on number of binaries created by the parent payload"}, {"field": "ParentProcessName", "description": "Allows focusing on suspicious interpreter or staging tools"}]', '2026-05-01 15:26:35.855135');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1003, 'AN1271', 'Analytic 1271', 'Anomalous creation or mounting of hidden partitions or virtual file systems. Defender view: detection of registry modifications linked to non-standard file systems, suspicious disk I/O patterns, or bootkit-like behavior where hidden volumes are accessed outside normal file system APIs.', '{Windows}', 'x-mitre-analytic--8d7fb300-189d-4654-ba66-3612a8a4cf65', 'DET0461', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "etw:Microsoft-Windows-Kernel-Storage", "channel": "Raw disk I/O operations bypassing NTFS APIs", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}]', '[{"field": "MonitoredRegistryKeys", "description": "Specify registry paths for mount points and hidden partition configs."}, {"field": "DiskIOThreshold", "description": "Tune thresholds for raw disk access outside expected drivers."}, {"field": "TimeWindow", "description": "Correlate boot-time anomalies with hidden file system mounting activity."}]', '2026-05-01 15:26:35.861962');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1004, 'AN0370', 'Analytic 0370', 'Detects access to cloud APIs or CLI tools to move or sync files from sensitive buckets to external endpoints using protocols like HTTPS or S3 APIs.', '{IaaS}', 'x-mitre-analytic--8dbd751b-a2cf-418a-b409-daae78a250f8', 'DET0131', '[{"name": "AWS:CloudTrail", "channel": "GetObject, CopyObject", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"name": "AWS:VPCFlowLogs", "channel": "Outbound data flows", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "IAMRoleContext", "description": "Detect unauthorized use of roles for cloud storage manipulation."}, {"field": "GeoDestinationThreshold", "description": "Alert on outbound flows to geo-locations not seen in training baseline."}]', '2026-05-01 15:26:35.863789');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1005, 'AN0802', 'Analytic 0802', 'Disabling or modifying sign-in or audit log collection for user activities. Defender view: policy or configuration updates removing logging coverage for critical accounts.', '{"Identity Provider"}', 'x-mitre-analytic--8e0f5333-9fc0-4f03-ae12-cf98903e08ea', 'DET0289', '[{"name": "azure:policy", "channel": "DisableAuditLogs or ConditionalAccess logging changes", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "CriticalAccounts", "description": "Tune to prioritize logging changes that affect administrative or high-value accounts."}]', '2026-05-01 15:26:35.865189');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1006, 'AN0744', 'Analytic 0744', 'Sudden spikes in cloud VM CPU usage with outbound traffic to mining pools and unauthorized instance creation.', '{IaaS}', 'x-mitre-analytic--8e1872c2-906c-4cf8-b0c7-afd448fe1c0b', 'DET0267', '[{"name": "AWS:CloudTrail", "channel": "RunInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "AWS:CloudWatch", "channel": "Sustained EC2 CPU usage above normal baseline", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "AWS:VPCFlowLogs", "channel": "Outbound flow logs to known mining pools", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "CPUUtilizationThreshold", "description": "CloudWatch alarm trigger for sustained CPU"}, {"field": "UnusualRegionList", "description": "Instances launched in unexpected regions"}]', '2026-05-01 15:26:35.866441');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1007, 'AN1479', 'Analytic 1479', 'Detects rogue or suspicious wireless access attempts by monitoring firewall, WIDS/WIPS, and controller logs. Focus is on firewall rule changes, rogue AP detection, and anomalous MAC addresses connecting to access points.', '{"Network Devices"}', 'x-mitre-analytic--8ea556b8-d6d3-430c-a438-847b00e607a5', 'DET0536', '[{"name": "NSM:Firewall", "channel": "rule_modification: New or modified firewall rules related to wireless interfaces", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"name": "WIDS:AssociationLogs", "channel": "Unauthorized AP or anomalous MAC address connection attempts", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AuthorizedAPList", "description": "Defines known access points and MAC addresses; deviations highlight rogue or unauthorized devices."}]', '2026-05-01 15:26:35.867592');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1008, 'AN1558', 'Analytic 1558', 'Detection of unset HISTFILE or modified history variables in ESXi shell sessions. Correlation of suspicious shell sessions with no recorded commands despite active usage.', '{ESXi}', 'x-mitre-analytic--8ed1a27f-3a60-441d-b92d-dc7b086db459', 'DET0563', '[{"name": "esxi:shell", "channel": "unset HISTFILE or HISTFILESIZE modifications", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AdminSessions", "description": "Differentiate root/admin shell sessions from adversarial misuse of ESXi shell."}]', '2026-05-01 15:26:35.868921');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1009, 'AN0363', 'Analytic 0363', 'Adversary enumeration of domain accounts using net.exe, PowerShell, WMI, or LDAP queries from non-domain controllers or non-admin endpoints.', '{Windows}', 'x-mitre-analytic--8f0ac116-4c8a-4819-b7c0-744e05d672c9', 'DET0129', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "LDAP Bind/Search", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CommandLinePattern", "description": "Detect variations of ''net user /domain'', ''Get-ADUser'', ''Get-ADGroupMember''."}, {"field": "TimeWindow", "description": "Tune detection for bursts of enumeration commands or search queries."}, {"field": "SourceHost", "description": "Restrict detection to non-DC or non-admin systems where such commands are unexpected."}]', '2026-05-01 15:26:35.870058');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1010, 'AN1327', 'Analytic 1327', 'Discovery via launchctl commands, or process enumeration using `ps aux | grep com.apple.` to identify daemons and services.', '{macOS}', 'x-mitre-analytic--8f654b08-222f-4fc0-83cc-ab871e290d1e', 'DET0483', '[{"name": "macos:unifiedlog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLineContent", "description": "Tune to recognize `launchctl list`, `launchctl print`, or service grep strings."}, {"field": "ProcessParent", "description": "Filter known benign automation or MDM agent invocations."}]', '2026-05-01 15:26:35.871239');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1011, 'AN0599', 'Analytic 0599', 'Detection of executables or scripts containing hidden embedded resources or secondary payloads, often with anomalies in file size vs. functionality or dropped child binaries.', '{Windows}', 'x-mitre-analytic--8f84fc52-ab74-443b-b618-aa1c0941377a', 'DET0214', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "EDR:file", "channel": "File Metadata Analysis (PE overlays, entropy)", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "OverlaySizeThreshold", "description": "Threshold in bytes where appended sections to binaries are considered suspicious"}, {"field": "ProcessTreeDepth", "description": "Controls how far child process lineage is analyzed for dropped embedded payloads"}, {"field": "TimeWindow", "description": "Defines correlation interval between file write and process execution"}]', '2026-05-01 15:26:35.872539');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1012, 'AN0707', 'Analytic 0707', 'Detect abnormal access to unified logs via log show or fs_usage targeting system log files. Monitor for execution of shell utilities (cat, grep) against /var/log/system.log and for plist modifications enabling verbose logging.', '{macOS}', 'x-mitre-analytic--8f998965-ad70-4ec6-8bc1-85831edc0497', 'DET0255', '[{"name": "macos:unifiedlog", "channel": "Execution of log show, fs_usage, or cat targeting system.log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "open: Access to /var/log/system.log or related security event logs", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "DebugToolsContext", "description": "Allowlist developers or administrators expected to review logs during debugging."}]', '2026-05-01 15:26:35.874289');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1013, 'AN0387', 'Analytic 0387', 'Execution of destructive CLI commands such as ''erase startup-config'', ''erase flash:'' or ''format disk'' on routers/switches. Detect privilege level escalation preceding destructive commands.', '{"Network Devices"}', 'x-mitre-analytic--8faa753d-ec3f-4694-9a33-03ce4ccb722f', 'DET0137', '[{"name": "networkdevice:cli", "channel": "erase flash:, erase startup-config, format disk", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "User privilege escalation to level 15/root prior to destructive commands", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "PrivilegedUsers", "description": "Tune to exclude approved maintenance sessions by known administrators."}, {"field": "CommandPatterns", "description": "Adjust monitored destructive command list depending on device vendor and OS."}]', '2026-05-01 15:26:35.875894');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1014, 'AN0921', 'Analytic 0921', 'Tracks modification of executables or interpreter payloads (e.g., Mach-O, dylib) that mutate across runs—using scripting engines, JIT compilers, or side-loaded plugins.', '{macOS}', 'x-mitre-analytic--8fba0b53-2aca-4cca-8856-714e0f05665b', 'DET0324', '[{"name": "macos:unifiedlog", "channel": "code signature/memory protection", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "fs:fsusage", "channel": "file open/write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_MMAP", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "ScriptEnginePatterns", "description": "Detection may vary based on whether Python/Swift/AppleScript is used to mutate payloads."}, {"field": "MachOEntropyThreshold", "description": "Entropy tuning based on expected baseline for system vs user binaries."}, {"field": "SignedBinaryChangeRate", "description": "Helps flag apps that change but maintain signed status across invocations."}]', '2026-05-01 15:26:35.877285');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1015, 'AN0051', 'Analytic 0051', 'Correlated modification of AppCompat registry keys and execution of sdbinst.exe to install custom shim databases. Followed by DLL injection via shim behavior into target application processes.', '{Windows}', 'x-mitre-analytic--8fcdd234-c8d8-4d95-b381-91c92cb319b6', 'DET0017', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "CustomShimPathAllowlist", "description": "Filter out known-good .sdb paths in AppPatch\\Custom folders"}, {"field": "TimeWindow", "description": "Tunable window for correlating registry modification and sdbinst.exe execution"}, {"field": "DLLInjectionTarget", "description": "Expected target applications or binaries for injected DLLs"}, {"field": "UserContext", "description": "Limit alerting to admin or SYSTEM-context initiated shim installations"}, {"field": "ShimCommandLinePattern", "description": "Expected or benign sdbinst.exe command-line patterns to exclude"}]', '2026-05-01 15:26:35.878701');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1016, 'AN1192', 'Analytic 1192', 'Detects guest VMs or management agents issuing HTTP(S) traffic to external services without a valid patch management or backup justification.', '{ESXi}', 'x-mitre-analytic--900bc498-4b81-43b6-bec2-3b55edc5c0ff', 'DET0425', '[{"name": "esxi:vmkernel", "channel": "network activity", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "vpxd.log", "channel": "API communication", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "RemoteIPRange", "description": "Filter to detect only external/public destinations"}, {"field": "VMContext", "description": "Exclude known backup or patch automation services"}]', '2026-05-01 15:26:35.880199');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1023, 'AN0908', 'Analytic 0908', 'Detects enumeration of cloud network interfaces, VPCs, subnets, or peer connections using CLI or SDKs (e.g., AWS CLI, Azure CLI, GCloud CLI).', '{IaaS}', 'x-mitre-analytic--914a5b13-5977-4e62-abab-9ee03e72624f', 'DET0320', '[{"name": "AWS:CloudTrail", "channel": "Describe* or List* API calls", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "azure:activity", "channel": "networkInsightsLogs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ServicePrincipalAllowlist", "description": "Allow certain automation roles to perform discovery during provisioning."}, {"field": "BurstQueryThreshold", "description": "Unusual number of Describe* or List* network API calls in a short timeframe."}]', '2026-05-01 15:26:35.891196');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1017, 'AN0505', 'Analytic 0505', 'Spawning of VNC-related processes (e.g., `x11vnc`, `vncserver`) coupled with authentication logs and port listening behavior on TCP 5900.', '{Linux}', 'x-mitre-analytic--9032a591-de05-44c2-b1f6-3d711f417cce', 'DET0178', '[{"name": "auditd:EXECVE", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "NSM:Flow", "channel": "TCP port 5900 open", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ListeningPort", "description": "Default VNC port (5900) but may vary in config"}, {"field": "ProcessNameFilter", "description": "Filter specific VNC binaries in process execution logs"}, {"field": "UserContext", "description": "Scope detection to non-service or high-privilege accounts"}]', '2026-05-01 15:26:35.881452');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1018, 'AN0346', 'Analytic 0346', 'Shell/utility (base64, xxd -p, od, openssl enc -base64, python/perl base64 libraries) encodes data → subsequent outbound connections (curl/wget/bash TCP, socat, python requests) with high asymmetry or Base64/MIME blobs in HTTP/DNS payloads.', '{Linux}', 'x-mitre-analytic--904100f0-1af9-4ded-89be-dfda7180bcbc', 'DET0124', '[{"name": "auditd:SYSCALL", "channel": "execve of base64|openssl|xxd|python|perl with arguments matching Base64 flags", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "http: HTTP body or headers contain long Base64 sections; gzip/deflate + Base64", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "EncodingToolsAllowList", "description": "Build/backup jobs that legitimately call base64/openssl."}, {"field": "EntropyThreshold", "description": "Shannon entropy for payloads (e.g., >4.5)."}, {"field": "TimeWindow", "description": "Join window between exec and egress (default 10m)."}, {"field": "OutInRatio", "description": "Bytes_out / bytes_in threshold (default 4)."}]', '2026-05-01 15:26:35.883666');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1019, 'AN1225', 'Analytic 1225', 'Detects suspicious usage of common application-layer protocols (e.g., HTTP, HTTPS, DNS, SMB) by abnormal processes, with high outbound byte counts or irregular ports, possibly indicating command and control or data exfiltration.', '{Windows}', 'x-mitre-analytic--908aa2d1-f1c0-456b-9c9f-b984b309e51c', 'DET0444', '[{"name": "NSM:Flow", "channel": "http, dns, smb, ssl logs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ProtocolList", "description": "Limit detection to app-layer protocols of interest: HTTP, DNS, SSL, SMB, RDP"}, {"field": "DataVolumeThreshold", "description": "Detects asymmetric communication volume (e.g., >90% outbound)"}, {"field": "UnusualProcessList", "description": "Track processes not normally associated with network activity"}]', '2026-05-01 15:26:35.884887');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1020, 'AN0976', 'Analytic 0976', 'Monitor audit logs for setuid/setgid bit changes, executions where UID ≠ EUID (indicative of sudo or privilege escalation), and high-integrity binaries launched by unprivileged users.', '{Linux}', 'x-mitre-analytic--90a8d89c-f54a-49dd-8734-6f85e5e3a2a5', 'DET0345', '[{"name": "auditd:SYSCALL", "channel": "setuid or setgid bit changes", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "auditd:SYSCALL", "channel": "execve with UID ≠ EUID", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "auditd:SYSCALL", "channel": "sudo or pkexec invocation", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "WatchedDirectories", "description": "Paths where unauthorized setuid binaries may be dropped"}, {"field": "UserContext", "description": "Which users are allowed to run sudo/pkexec or modify binaries"}, {"field": "TimeWindow", "description": "Duration between file permission change and elevated command execution"}]', '2026-05-01 15:26:35.886292');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1021, 'AN0748', 'Analytic 0748', 'Detects adversarial archiving by scripts or binaries calling compression libraries (libzip, zlib, bzip2). Correlates execution of Python, Perl, or compiled binaries with dynamic linking to archiving libraries and creation of compressed files in /tmp or user directories.', '{Linux}', 'x-mitre-analytic--90e51090-9857-4a28-98b9-f21401ddbe85', 'DET0268', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of python, perl, or custom binaries invoking compression libraries", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:MMAP", "channel": "load: Loading of libzip.so, libz.so, or libbz2.so by processes not normally associated with archiving", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "auditd:FILE", "channel": "create: Creation of .zip, .gz, .bz2 files in /tmp, /var/tmp, or /home directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "MonitoredLibraries", "description": "List of shared objects linked to compression/encryption."}, {"field": "ArchivePaths", "description": "Directories where archive creation is flagged as anomalous."}, {"field": "EntropyThreshold", "description": "Entropy level used to distinguish encryption from normal compression."}]', '2026-05-01 15:26:35.887671');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1022, 'AN0366', 'Analytic 0366', 'Detection of suspicious access to cloud-native secret management systems (AWS Secrets Manager, GCP Secret Manager, Azure Key Vault, HashiCorp Vault). Focuses on abnormal secret retrieval activity, such as secrets being accessed by unusual identities, from unexpected regions, outside business hours, or at high volume. Correlates API calls to secret retrieval with surrounding authentication events, role assumptions, and anomalous execution patterns.', '{IaaS}', 'x-mitre-analytic--90eca5d7-c330-4b86-bde6-de04019cbba7', 'DET0130', '[{"name": "AWS:CloudTrail", "channel": "GetSecretValue", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}]', '[{"field": "PrivilegedRoles", "description": "Set of accounts or roles allowed to retrieve secrets; deviations may indicate misuse."}, {"field": "TimeWindow", "description": "Temporal window to correlate secret access with authentication and anomalous context."}, {"field": "AccessPatterns", "description": "Expected frequency and volume of secret retrievals per user/service; anomalies may indicate exfiltration."}, {"field": "RegionConstraints", "description": "Regions in which secret access is expected; access from unusual geographies may indicate compromise."}]', '2026-05-01 15:26:35.889258');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1026, 'AN1557', 'Analytic 1557', 'Detection of PowerShell history suppression using Set-PSReadLineOption with SaveNothing or altered HistorySavePath. Correlating these options with PowerShell usage highlights adversarial evasion attempts.', '{Windows}', 'x-mitre-analytic--91870bc8-3a81-4d90-84e4-26c99b5642ef', 'DET0563', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AllowedPaths", "description": "List of acceptable PowerShell history save paths for baseline comparison."}]', '2026-05-01 15:26:35.895138');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1027, 'AN0468', 'Analytic 0468', 'Detects adversary clearing shell history using `history -c` or deleting/altering ~/.zsh_history or ~/.bash_history. Focus on sessions with missing or wiped history.', '{macOS}', 'x-mitre-analytic--9199891a-1543-4f51-be59-4fffb03dfd43', 'DET0165', '[{"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "unlink, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "TimeWindow", "description": "Duration after terminal usage where deletion or modification is considered suspicious."}, {"field": "UserContext", "description": "Flag unexpected user activity, especially from users who normally don’t use terminal."}, {"field": "HistoryFilePath", "description": "Zsh or Bash history files under the user''s home directory."}]', '2026-05-01 15:26:35.896342');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1028, 'AN2025', 'Analytic 2025', 'If infrastructure or patterns in malicious web content have been previously identified, internet scanning may uncover when an adversary has staged web content to make it accessible for targeting.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1029, 'AN1603', 'Analytic 1603', 'Detection of unauthorized changes to boot configurations pointing to TFTP servers, unusual firmware loads during netbooting, or suspicious TFTP traffic. Correlation of boot config modifications, command history logs, and unexpected system image hashes provides detection coverage for adversaries attempting to persist via malicious TFTP boot images.', '{"Network Devices"}', 'x-mitre-analytic--92004715-82f0-409d-a520-fc49720e4f3d', 'DET0582', '[{"name": "networkdevice:config", "channel": "Configuration changes referencing ''boot system tftp'' or modification of startup-config pointing to external TFTP servers", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "Boot information log showing image loaded from TFTP server instead of local storage", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"name": "NSM:Flow", "channel": "Unexpected inbound/outbound TFTP traffic for device image files", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ApprovedTFTPServers", "description": "Whitelist of TFTP servers authorized for netbooting in the environment"}, {"field": "TimeWindow", "description": "Detection correlation window between config change, TFTP activity, and system reboot"}, {"field": "BaselineBootImageHash", "description": "Expected system image hashes to validate integrity of boot images loaded via TFTP"}]', '2026-05-01 15:26:35.898874');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1030, 'AN1489', 'Analytic 1489', 'Sustained execution of resource-intensive processes (e.g., cryptocurrency miners), often launched via scheduled tasks, WMI, or PowerShell. These processes frequently establish persistent external connections and attempt to evade detection using masqueraded or renamed binaries.', '{Windows}', 'x-mitre-analytic--92157361-c2f8-45e6-9624-38a3cdb44598', 'DET0540', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=4698", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}]', '[{"field": "Image", "description": "The executable name of the miner or wrapper—can vary across campaigns."}, {"field": "DestinationIP", "description": "May differ depending on the mining pool or proxy server."}, {"field": "ParentProcessName", "description": "Useful for filtering known-good automation vs malicious task runners."}]', '2026-05-01 15:26:35.900048');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1031, 'AN0594', 'Analytic 0594', 'Direct login to cloud-hosted virtual machines via cloud-native access methods (e.g., EC2 Instance Connect, Azure Serial Console, SSM), followed by command execution or privilege escalation on the VM', '{IaaS}', 'x-mitre-analytic--926f4550-8c47-4882-afb3-1f0832c8d3b9', 'DET0211', '[{"name": "AWS:CloudTrail", "channel": "SendSSHPublicKey, StartSession (SSM), EC2InstanceConnect", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Correlates cloud login to host activity within a reasonable time span (e.g., < 60 seconds)"}, {"field": "CloudAuthMethod", "description": "Filters based on access vector: SSH key, SSM session, or Console connect"}, {"field": "SessionOriginRegion", "description": "Identifies sessions from out-of-region or untrusted networks"}, {"field": "TargetInstanceTags", "description": "Filters sensitive systems or production assets for alert tuning"}]', '2026-05-01 15:26:35.901191');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1032, 'AN0669', 'Analytic 0669', 'Detection of tampering with Apple''s Unified Logging framework or modification of system log forwarding settings. Defender observes execution of logd-related commands or defaults write to logging preferences.', '{macOS}', 'x-mitre-analytic--9274294a-dfc3-4084-b228-dfb36448f077', 'DET0239', '[{"name": "macos:unifiedlog", "channel": "defaults write com.apple.system.logging or logd manipulation", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AllowedLogConfigs", "description": "Baseline of approved logging preference modifications to reduce noise."}]', '2026-05-01 15:26:35.902386');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1033, 'AN0025', 'Analytic 0025', 'Detects inotify or auditd configuration changes that monitor system files coupled with execution of script interpreters or binaries by cron or systemd timers.', '{Linux}', 'x-mitre-analytic--92d182e9-6723-43e4-9eab-f00aa6d53153', 'DET0010', '[{"name": "auditd:SYSCALL", "channel": "Inotify watch creation or auditctl changes on /etc/cron* or /lib/systemd/system/", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "linux:syslog", "channel": "Execution of non-standard script or binary by cron", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "auditd:SYSCALL", "channel": "Execution of script interpreters by systemd timer (ExecStart)", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ExecutablePathRegex", "description": "Regex defining suspicious binary/script paths triggered by cron/systemd"}, {"field": "WatchTargetPaths", "description": "Paths monitored by auditd/inotify for suspicious event registration"}]', '2026-05-01 15:26:35.904833');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1034, 'AN1983', 'Analytic 1983', 'Monitor and analyze traffic patterns and packet inspection associated to protocol(s) that do not follow the expected protocol standards and traffic flows (e.g extraneous packets that do not belong to established flows, gratuitous or anomalous traffic patterns, anomalous syntax, or structure). Consider correlation with process monitoring and command line to detect anomalous processes execution and command line arguments associated to traffic patterns (e.g. monitor anomalies in use of files that do not normally initiate connections for respective protocol(s)).
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1035, 'AN1148', 'Analytic 1148', 'Monitor DNS queries, proxy logs, and user-agent strings for anomalous patterns associated with adversary attempts to hide infrastructure. Defenders may observe DNS resolutions to short-lived domains, abnormal WHOIS registration data, or filtering of known defensive/responder IP addresses.', '{Windows}', 'x-mitre-analytic--9311924d-7d8f-489a-8105-058a60f572fc', 'DET0411', '[{"name": "WinEventLog:Security", "channel": "EventCode=5156, 5157", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "dns:query", "channel": "Excessive lookups for domains with suspicious WHOIS or short TTL values", "x_mitre_data_component_ref": "x-mitre-data-component--ff9b665a-598b-4bcb-8b2a-a87566aa1256"}]', '[{"field": "SuspiciousDomains", "description": "List of domains registered with privacy-protected or suspicious WHOIS metadata."}, {"field": "ResponderIPs", "description": "Known incident response or scanning infrastructure IP ranges."}]', '2026-05-01 15:26:35.908383');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1036, 'AN0241', 'Analytic 0241', 'Defender observes use of CLI tools (`find`, `grep`, `ls`, `dpkg`, `rpm`, `systemctl`, `ps aux`) to discover backup agents or config files (e.g., rsnapshot, duplicity, veeam). This often includes command lines that recursively search `/etc/`, `/opt/`, or `/var/` directories for keywords like `backup`, and parent-child relationships involving shell or Python scripts.', '{Linux}', 'x-mitre-analytic--93918e31-51b1-4d85-8b16-590871c2cc1f', 'DET0088', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of discovery commands targeting backup binaries, processes, or config paths", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PATH", "channel": "Read access to known backup software configuration files (e.g., /etc/rsnapshot.conf, /opt/veeam/config.ini)", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "BackupConfigPaths", "description": "Directory paths and filenames related to backup agents"}, {"field": "ToolchainScope", "description": "Shells, interpreters, or binaries used by attacker scripts for discovery"}]', '2026-05-01 15:26:35.909812');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1037, 'AN0421', 'Analytic 0421', 'Forged SAML tokens can appear as SaaS logins where authentication succeeded without MFA, or where tokens contain claims inconsistent with the user profile. Look for concurrent sessions across different geographies with the same SAML assertion ID.', '{SaaS}', 'x-mitre-analytic--93c97a07-283e-46c5-b2ac-560db0382ea9', 'DET0148', '[{"name": "saas:access", "channel": "SAML token accepted without preceding login challenge", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "m365:unified", "channel": "Abnormal user claims or unexpected elevated role assignment in SAML assertion", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "GeoVelocityThreshold", "description": "Triggers when same SAML token used in different geographies within short timeframe."}]', '2026-05-01 15:26:35.911188');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1038, 'AN1642', 'Analytic 1642', 'Suspicious access to password manager vaults (KeePassXC, gnome-keyring, pass) via memory scraping or unauthorized file reads. Detects unusual command execution involving gdb/strace attached to password manager processes.', '{Linux}', 'x-mitre-analytic--93fd8592-d8ce-4b5e-b095-71cd66062298', 'DET0597', '[{"name": "auditd:SYSCALL", "channel": "open/read on ~/.local/share/keepassxc/* OR ~/.password-store/*", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "ptrace", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "VaultFilePaths", "description": "Linux paths to monitor for vault database files (KeePassXC, pass, gnome-keyring)."}, {"field": "TimeWindow", "description": "Correlation interval to detect multiple suspicious access events."}]', '2026-05-01 15:26:35.912907');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1071, 'AN0729', 'Analytic 0729', 'Inspect resolver and audit logs for processes initiating outbound connections to ports calculated from DNS response IPs. Abnormal ephemeral port usage shortly after DNS queries can indicate DNS calculation behavior.', '{Linux}', 'x-mitre-analytic--98f5c157-17c8-4ab8-943d-8d4c54dc3d6d', 'DET0262', '[{"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "linux:syslog", "channel": "DNS response IPs followed by connections to non-standard calculated ports", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "EphemeralPortRange", "description": "Configured ephemeral port ranges per environment to reduce false positives"}, {"field": "ResolverWhitelist", "description": "Exclude trusted resolvers or internal services from analysis"}]', '2026-05-01 15:26:35.964244');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1039, 'AN0024', 'Analytic 0024', 'Correlates unexpected modifications to WMI event filters, scheduled task triggers, or registry autorun keys with subsequent execution of non-standard binaries by SYSTEM-level processes.', '{Windows}', 'x-mitre-analytic--9418d7e2-666f-4f73-9ac7-96b32005e9b7', 'DET0010', '[{"name": "WinEventLog:Security", "channel": "EventCode=4698", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "WinEventLog:WMI", "channel": "Creation or modification of __EventFilter, __FilterToConsumerBinding, or CommandLineEventConsumer", "x_mitre_data_component_ref": "x-mitre-data-component--05645013-2fed-4066-8bdc-626b2e201dd4"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Filters triggering on SYSTEM or LOCAL SERVICE vs. user-initiated triggers"}, {"field": "TimeWindow", "description": "Correlates trigger definition and execution timing (e.g., within 5 minutes)"}, {"field": "PathAnomalyThreshold", "description": "Process or binary path deviation scoring for execution anomalies"}]', '2026-05-01 15:26:35.914131');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1040, 'AN1248', 'Analytic 1248', 'Detection monitors modification of code signing attributes, Gatekeeper/quarantine flags, and insertion of new trust certificates via security add-trusted-cert. Identifies adversary use of xattr to strip quarantine flags from downloaded binaries. Correlates with abnormal module loads bypassing SIP protections.', '{macOS}', 'x-mitre-analytic--94340be7-068e-446a-bca2-d414b66912fc', 'DET0452', '[{"name": "macos:unifiedlog", "channel": "New certificate trust settings added by unexpected process", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:unifiedlog", "channel": "xattr -d com.apple.quarantine or similar removal commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "Unsigned or ad-hoc signed process executions in user contexts", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "QuarantineBypassAllowList", "description": "List of enterprise apps where quarantine flag removal is expected"}, {"field": "CertificateAuthorityList", "description": "Baseline trusted root and intermediate CAs for comparison"}]', '2026-05-01 15:26:35.91567');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1041, 'AN0667', 'Analytic 0667', 'Correlates registry modifications to EventLog or WMI Autologger keys, suspicious use of Set-EtwTraceProvider, and Sysmon configuration changes. Defender sees interruption or redirection of ETW and log event collection.', '{Windows}', 'x-mitre-analytic--945f8192-6f4f-4183-b457-40b5c6d9b4ca', 'DET0239', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=16", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "MonitoredETWProviders", "description": "List of ETW providers to baseline and monitor for unexpected removal."}, {"field": "AuthorizedConfigChanges", "description": "Whitelist of expected admin actions modifying Sysmon or ETW configurations."}]', '2026-05-01 15:26:35.916986');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1042, 'AN0156', 'Analytic 0156', 'Detects suspicious memory access attempts targeting the `securityd` process. Observes tools invoking process memory read operations (e.g., ptrace, task_for_pid) against `securityd`. Correlates with anomalous parent process lineage, root privilege escalation, or repeated unauthorized attempts.', '{macOS}', 'x-mitre-analytic--94628b16-2443-4e66-9f7b-a61a39012a9c', 'DET0057', '[{"name": "macos:unifiedlog", "channel": "ptrace or task_for_pid", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "macos:unifiedlog", "channel": "execution of memory inspection tools (lldb, gdb, osqueryi)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AllowedDebuggers", "description": "List of authorized debugging tools permitted in dev/test environments"}, {"field": "TimeWindow", "description": "Correlation period between memory inspection and Keychain API access"}, {"field": "PrivilegedUsers", "description": "Expected set of admin accounts with legitimate debugging permissions"}]', '2026-05-01 15:26:35.91845');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1043, 'AN0979', 'Analytic 0979', 'Detect sudden privilege escalations such as IAM role changes, user-assigned privilege boundaries, or elevation via assumed roles beyond normal behavior.', '{IaaS}', 'x-mitre-analytic--9465ea54-a81a-4d00-a75d-e0b7f3392bb8', 'DET0345', '[{"name": "AWS:CloudTrail", "channel": "role privilege expansion detected", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "AWS:CloudTrail", "channel": "cross-account or unexpected assume role", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "PermittedRoleTransitions", "description": "Define valid transitions between IAM roles"}, {"field": "CrossAccountBoundary", "description": "Should flag if assumption crosses trust boundary"}]', '2026-05-01 15:26:35.919811');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1044, 'AN1050', 'Analytic 1050', 'Execution of AppleScript, bash, or launchd jobs that invoke delay functions (e.g., sleep, delay in AppleScript) with limited parent interaction and staged follow-on commands.', '{macOS}', 'x-mitre-analytic--94871740-e9ae-458a-9d09-ef0f58c05905', 'DET0372', '[{"name": "macos:unifiedlog", "channel": "launchd or osascript spawns process with delay command", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "delay/sleep library usage in user context", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ScriptPattern", "description": "AppleScript vs shell scripts differ per threat and org."}, {"field": "UserContext", "description": "Execution under user vs daemon context changes severity."}, {"field": "DelayDurationThreshold", "description": "Amount of delay that distinguishes benign usage vs evasion."}]', '2026-05-01 15:26:35.921105');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1045, 'AN0625', 'Analytic 0625', 'Detects script or binary execution initiated via JAMF, Munki, or custom MDM agents outside of baseline, or JAMF launching new Terminal or osascript processes from remote command payloads.', '{macOS}', 'x-mitre-analytic--94e3c24f-01ee-45bc-89c0-7024ada7cc66', 'DET0223', '[{"name": "macos:unifiedlog", "channel": "process and signing chain events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:jamf", "channel": "RemoteCommandExecution", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "SigningAuthorityList", "description": "Expected signing authorities for JAMF and MDM scripts"}, {"field": "RemoteCommandInterval", "description": "Frequency of remote execution from MDM servers"}]', '2026-05-01 15:26:35.92261');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1046, 'AN0404', 'Analytic 0404', 'Flows showing encrypted payloads with high entropy not matching TLS handshake patterns, particularly when occurring on non-standard ports. Defender observes NetFlow/IPFIX byte distribution anomalies or IDS/IPS detecting symmetric encryption patterns without associated key exchange.', '{"Network Devices"}', 'x-mitre-analytic--94e5fd96-1fde-41fd-863d-6ef9cb8a3e1a', 'DET0143', '[{"name": "NSM:Flow", "channel": "Flow records with entropy signatures resembling symmetric encryption", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Connections", "channel": "Symmetric encryption detected without TLS handshake sequence", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "PortProfiles", "description": "Baseline expected encryption by port/protocol."}, {"field": "TrafficVolumeThreshold", "description": "Volume thresholds for distinguishing benign VPN traffic from hidden C2."}]', '2026-05-01 15:26:35.924305');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1047, 'AN1263', 'Analytic 1263', 'Rapid login failures across different users from a single IP address, targeting SSH or PAM login with distinct username-password pairs', '{Linux}', 'x-mitre-analytic--95d381e5-f2d6-4164-9917-57f9b070333b', 'DET0460', '[{"name": "linux:syslog", "channel": "SSH failed login", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "LoginFailureRatio", "description": "Ratio of failed logins per unique user attempted"}, {"field": "AuthServiceFilter", "description": "Restrict detection to certain protocols (e.g., sshd, login, su)"}]', '2026-05-01 15:26:35.92618');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1048, 'AN0592', 'Analytic 0592', 'Domain logins using network accounts or mobile accounts via Open Directory or Active Directory plugins, especially outside business hours or on atypical endpoints.', '{macOS}', 'x-mitre-analytic--96050801-dc36-462f-982e-df2806eaa3ea', 'DET0210', '[{"name": "macos:unifiedlog", "channel": "log show --predicate ''eventMessage contains \"Authentication\"''", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "UserLocation", "description": "Geo-IP or VPN source context for abnormal remote access."}, {"field": "LogonMethod", "description": "Control for expected services (e.g., GUI login vs. SSH)."}]', '2026-05-01 15:26:35.927713');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1049, 'AN0804', 'Analytic 0804', 'Disabling or altering security and audit logs in SaaS admin panels (e.g., Slack, Zoom, Salesforce). Defender view: API calls or admin console changes that stop event exports or logging integrations.', '{SaaS}', 'x-mitre-analytic--967f7636-1547-4db7-921a-1b84f312a2cd', 'DET0289', '[{"name": "saas:audit", "channel": "Log export integration removed or disabled", "x_mitre_data_component_ref": "x-mitre-data-component--ec0612c5-2644-4c50-bcac-82586974fedd"}]', '[{"field": "IntegrationScope", "description": "Define which SaaS log integrations are required and alert if removed."}]', '2026-05-01 15:26:35.929561');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1050, 'AN0529', 'Analytic 0529', 'OAuth token usage for Exchange Online or SharePoint API access without preceding login or from unauthorized clients.', '{"Office Suite"}', 'x-mitre-analytic--9680d434-3470-4a35-bf48-1785ab14d831', 'DET0185', '[{"name": "m365:unified", "channel": "OAuthTokenIssued, FileAccessed, MailItemsAccessed", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}]', '[{"field": "ClientAppIDWhitelist", "description": "Restrict trusted Office apps authorized to request tokens"}]', '2026-05-01 15:26:35.930871');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1051, 'AN1475', 'Analytic 1475', 'Malicious VIB installation for persistence via `esxcli software vib install` using `--force` or `--no-sig-check`, enabling custom startup scripts or firewall rules. Behavior chain: (1) unsigned/suspicious VIB installation → (2) startup script or binary placed in persistent boot path → (3) persistence across reboot via /etc/rc.local.d or other boot hook).', '{ESXi}', 'x-mitre-analytic--9696a221-35b9-4576-ae75-714c902c2889', 'DET0535', '[{"name": "esxi:esxupdate", "channel": "/var/log/esxupdate.log contains VIB installed with `--force` or `--no-sig-check` and non-standard acceptance levels", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "esxi:shell", "channel": "`esxcli software vib install` with `--force` or `--no-sig-check` from shell history or `shell.log`", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:fim", "channel": "Changes to /etc/rc.local.d/local.sh or creation of unexpected startup files in persistent partitions (/etc/init.d, /store, /locker)", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "AcceptanceLevel", "description": "Some environments may intentionally permit CommunitySupported or unsigned VIBs—filter by known allowed publishers."}, {"field": "InstallCommandThreshold", "description": "Set alerting thresholds for frequency of VIB install attempts per host/user/time window."}, {"field": "StartupPathRegex", "description": "Tune regex for monitoring startup file locations based on ESXi image customization."}]', '2026-05-01 15:26:35.932261');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1052, 'AN0644', 'Analytic 0644', 'Monitors Gatekeeper, spctl, and unified log entries for binaries executed with unexpected or untrusted signatures. Correlates file metadata changes with process launches where signature validation is skipped, altered, or fails but the process still executes.', '{macOS}', 'x-mitre-analytic--969bd6a3-b89f-4279-9bd2-3fc461880308', 'DET0230', '[{"name": "macos:unifiedlog", "channel": "Code signing verification failures or bypassed trust decisions", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:unifiedlog", "channel": "Execution of binaries with unsigned or anomalously signed certificates", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DeveloperIDAllowList", "description": "Maintain list of expected Developer IDs to minimize false positives from enterprise apps"}, {"field": "TimeWindow", "description": "Correlates file signature changes with subsequent executions"}]', '2026-05-01 15:26:35.93365');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1072, 'AN0658', 'Analytic 0658', 'Detection of modified or newly created /etc/rc.local or /etc/init.d scripts followed by suspicious execution during system startup.', '{Linux}', 'x-mitre-analytic--98f8728d-ff74-47cb-b884-25071a21f77e', 'DET0237', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "boot logs", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "script_path", "description": "Specific path of init script (e.g., /etc/rc.local, /etc/init.d/*) may vary by distribution"}, {"field": "user_context", "description": "Root vs. non-root modification context depending on configuration"}, {"field": "time_window", "description": "Tuning window for script creation or modification relative to system boot"}]', '2026-05-01 15:26:35.965615');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1053, 'AN2027', 'Analytic 2027', 'Monitor for contextual data about an Internet-facing resource gathered from a scan, such as running services or ports that may buy, lease, or rent infrastructure that can be used during targeting. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1054, 'AN1286', 'Analytic 1286', 'Abuse of system-generated or default privileged accounts such as ''root'' or ''vpxuser'' logging into ESXi hosts.', '{ESXi}', 'x-mitre-analytic--96fe3582-b1a3-40e4-9e9d-bab764f2af7e', 'DET0465', '[{"name": "esxi:auth", "channel": "/var/log/auth.log", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AccountName", "description": "If ''vpxuser'' is replaced or configured differently, detection logic must reflect the change."}, {"field": "IPRange", "description": "Legitimate vCenter IP ranges may be whitelisted to avoid false positives."}]', '2026-05-01 15:26:35.936518');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1055, 'AN0998', 'Analytic 0998', 'Linux permission escalation behavioral chain: (1) Process creation of permission modification utilities (chmod, chown, chgrp, setfacl) with suspicious parameters indicating privilege escalation intent, (2) System call analysis revealing direct file metadata manipulation (chmod, fchmod, chown, fchown syscalls), (3) Extended attribute and ACL modifications targeting critical system paths, (4) Temporal correlation with subsequent file access or process execution from modified locations, (5) Anomalous permission patterns deviating from system baselines', '{Linux}', 'x-mitre-analytic--971ddd36-1ecd-46bf-b94c-22e8f05c1462', 'DET0351', '[{"name": "auditd:SYSCALL", "channel": "syscall in (chmod, fchmod, fchmodat, chown, fchown, fchownat, lchown, setxattr, lsetxattr, fsetxattr, removexattr, lremovexattr, fremovexattr)", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "auditd:PROCTITLE", "channel": "proctitle contains chmod, chown, chgrp, setfacl, or attr with suspicious parameters (777, 755, +x, -R)", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:osquery", "channel": "process execution events for permission modification utilities with command-line analysis", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SuspiciousPermissionValues", "description": "Octal permission values indicating potential malicious intent - customize based on organizational security policy (default: 777, 755, 4755, 2755, 1755 for sticky/setuid/setgid)"}, {"field": "CriticalSystemPaths", "description": "Linux filesystem paths requiring enhanced permission change monitoring - adapt to environment-specific critical directories (/etc, /usr/bin, /usr/sbin, /var, /opt, /root, /boot)"}, {"field": "AuthorizedSystemAdministrators", "description": "User accounts and service accounts authorized for system-level permission modifications - maintain current list of legitimate administrators"}, {"field": "TemporalCorrelationWindow", "description": "Time window for correlating permission changes with subsequent file access or process execution - adjust based on system performance (default: 300 seconds)"}, {"field": "RecursiveOperationThreshold", "description": "Maximum depth or file count for recursive permission operations before triggering anomaly detection (-R flag monitoring)"}, {"field": "ACLComplexityBaseline", "description": "Baseline complexity metrics for setfacl operations to detect anomalous extended ACL configurations"}, {"field": "FileAccessFrequencyBaseline", "description": "Statistical baseline for normal file access patterns post-permission modification to detect privilege abuse"}]', '2026-05-01 15:26:35.937941');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1056, 'AN0723', 'Analytic 0723', 'Forged web credentials in Office Suite contexts may appear as abnormal authentication headers in Outlook or Teams traffic, or unexplained OAuth grants in M365/Azure logs. Defenders should correlate token usage events with missing authentication flows and mismatched device/user context.', '{"Office Suite"}', 'x-mitre-analytic--9735a0b1-df29-49fe-b0f7-973c0b513e8d', 'DET0260', '[{"name": "m365:oauth", "channel": "OAuth grants or tokens issued without expected user consent", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}, {"name": "m365:signinlogs", "channel": "Token usage events with device/user mismatch", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "OAuthAppAllowlist", "description": "Approved OAuth apps and flows; flag unapproved or unexpected token grants."}]', '2026-05-01 15:26:35.940148');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1057, 'AN1067', 'Analytic 1067', 'Identifies transfer of base64, uuencoded, or high-entropy files over HTTP, FTP, or custom protocols in lateral movement or exfiltration streams.', '{"Network Devices"}', 'x-mitre-analytic--97a188cf-5851-4cb7-9bb5-17702707d52b', 'DET0378', '[{"name": "networkdevice:IDS", "channel": "content inspection / PCAP / HTTP body", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "EntropyThreshold", "description": "Adjust threshold to reduce false positives in compressed but benign data"}, {"field": "ProtocolScope", "description": "Refine by enabling inspection of specific exfil vectors (e.g., FTP, HTTP POST)"}]', '2026-05-01 15:26:35.941979');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1058, 'AN1985', 'Analytic 1985', 'Consider analyzing malware for features that may be associated with the adversary and/or their developers, such as compiler used, debugging artifacts, or code similarities. Malware repositories can also be used to identify additional samples associated with the adversary and identify development patterns over time. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Defense Evasion or Command and Control.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1059, 'AN0543', 'Analytic 0543', 'Detects registry and Group Policy modifications that disable or weaken MFA, suspicious PowerShell usage modifying MFA-related attributes, and anomalous login sessions succeeding without expected MFA challenge.', '{Windows}', 'x-mitre-analytic--97cb8df9-f100-4a64-802a-1aa2f45c26eb', 'DET0190', '[{"name": "WinEventLog:Security", "channel": "EventCode=4739", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:PowerShell", "channel": "Set-ADUser or Set-ADAuthenticationPolicy with MFA attributes disabled", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "WatchedAttributes", "description": "List of AD attributes or policy fields tied to MFA enforcement that may vary by organization."}, {"field": "TimeWindow", "description": "Correlation window between MFA policy changes and anomalous login behavior."}]', '2026-05-01 15:26:35.945195');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1061, 'AN1368', 'Analytic 1368', 'Electron/GUI or headless RAT execution followed by LaunchAgent/Daemon persistence and persistent external connections; interactive children (osascript/sh/curl) spawned by parent.', '{macOS}', 'x-mitre-analytic--97f27df6-5041-437b-9aeb-58a9bc33a376', 'DET0496', '[{"name": "macos:unifiedlog", "channel": "Process exec of remote-control apps or binaries with headless/connect flags", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "CREATE/MODIFY: Creation of LaunchAgents/Daemons plists in user/system locations", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:osquery", "channel": "CONNECT: Long-lived connections from remote-control parents to external IPs/domains", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AllowedAppBundlePaths", "description": "Legitimate remote-support apps under /Applications."}, {"field": "LaunchdAllowlist", "description": "Known-good LaunchAgents/Daemons identifiers."}, {"field": "TimeWindow", "description": "Window for correlating exec→launchd→egress events."}, {"field": "EgressHeuristics", "description": "Duration/volume thresholds for persistent sessions."}]', '2026-05-01 15:26:35.94861');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1062, 'AN0028', 'Analytic 0028', 'Correlates Power Automate or similar logic app workflows triggered by SaaS file uploads or email rules with data forwarding or anomalous access patterns.', '{SaaS}', 'x-mitre-analytic--982100e1-6d38-4d0e-b36d-7e2d2cf5a424', 'DET0010', '[{"name": "m365:unified", "channel": "Creation of Power Automate flow triggered by OneDrive or Exchange event", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "m365:unified", "channel": "Automated forwarding or file sync initiated by a logic app", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TriggerCondition", "description": "Event types that initiate SaaS automation (e.g., file add, new email)"}, {"field": "AppIdentityScope", "description": "Scopes/permissions granted to automation app accounts"}]', '2026-05-01 15:26:35.950936');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1063, 'AN2035', 'Analytic 2035', 'Detects user execution of newly received content or instructions shortly after external communication, including script launches, Office child process spawning, browser-to-script execution chains, or credential prompts followed by new logon sessions.', '{Windows}', 'x-mitre-analytic--983e1849-6af7-491e-9605-46b9bf54bbd1', 'DET0899', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "EmailToExecutionWindow", "description": "Time between message delivery and process launch"}, {"field": "OfficeChildProcessAllowlist", "description": "Approved Office child process patterns"}, {"field": "NewLogonWindow", "description": "Time after credential prompt to monitor new sessions"}]', '2026-05-01 15:26:35.952201');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1064, 'AN2010', 'Analytic 2010', 'Monitor for suspicious email activity, such as numerous accounts receiving messages from a single unusual/unknown sender. Filtering based on DKIM+SPF or header analysis can help detect when the email sender is spoofed.(Citation: Microsoft Anti Spoofing)(Citation: ACSC Email Spoofing) Monitor for references to uncategorized or known-bad sites. URL inspection within email (including expanding shortened links and identifying obfuscated URLs) can also help detect links leading to known malicious sites.(Citation: Mandiant URL Obfuscation 2023)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1065, 'AN1226', 'Analytic 1226', 'Detects suspicious curl, wget, or custom socket traffic that leverages DNS, HTTPS, or IRC-style protocols with unbalanced traffic or beacon-like intervals.', '{Linux}', 'x-mitre-analytic--989a524f-cf9a-4fcc-a21f-ac5aac46f0ed', 'DET0444', '[{"name": "NSM:Flow", "channel": "dns, ssl, conn", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "KnownPortsToMonitor", "description": "Uncommon ports for HTTPS, IRC, DNS (e.g., 8443, 5353)"}, {"field": "BeaconTimingThreshold", "description": "Detect intervals of outbound traffic within fixed timeframes"}]', '2026-05-01 15:26:35.954981');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1073, 'AN0738', 'Analytic 0738', 'Detects the use of mail utilities like `mail` or `mailx` to delete mailbox content, or file-level deletion of inbox files from `/var/spool/mail/` or `/var/mail/` following suspicious sessions.', '{Linux}', 'x-mitre-analytic--9933242a-f96e-4b3e-896f-e7335f410a4f', 'DET0266', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "unlink/unlinkat", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "MailFolderPath", "description": "Common inbox file locations like /var/spool/mail/, /var/mail/"}, {"field": "CommandPattern", "description": "Usage of mailx or echo piped to mail followed by deletion"}]', '2026-05-01 15:26:35.966852');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1066, 'AN1631', 'Analytic 1631', 'Monitoring adversary access to sensitive process memory via the /proc filesystem to extract credential material, often involving multi-step access to /proc/[pid]/mem or /proc/[pid]/maps combined with privilege escalation or credential scraping binaries.', '{Linux}', 'x-mitre-analytic--98b71f96-ae0a-47b4-bec2-156cb6e5bfcb', 'DET0593', '[{"name": "auditd:SYSCALL", "channel": "open, read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "ptrace or process_vm_readv", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "linux:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AccessedFilePath", "description": "Monitored paths such as /proc/[pid]/mem or /proc/[pid]/maps may need to be scoped based on environment"}, {"field": "ProcessName", "description": "Command-line or binary names associated with credential scraping tools may vary"}, {"field": "UserContext", "description": "Elevated user or unexpected user context accessing other process memory may indicate malicious activity"}, {"field": "TimeWindow", "description": "Correlating memory access with process creation or ptrace activity within a specific time range"}]', '2026-05-01 15:26:35.956814');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1067, 'AN0436', 'Analytic 0436', 'Unusual processes (e.g., powershell.exe, wscript.exe, mshta.exe) posting data to webhook endpoints (Discord, Slack, webhook.site) using HTTP POST/PUT requests. Defender perspective: suspicious process lineage followed by outbound HTTPS traffic to webhook domains.', '{Windows}', 'x-mitre-analytic--98bd8e15-68ea-43a3-982b-66fcd1142c9a', 'DET0153', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "WebhookDomains", "description": "Domains to monitor such as discord.com/api/webhooks, slack.com/api, webhook.site."}, {"field": "UploadSizeThreshold", "description": "Threshold for abnormal data sent via webhook requests."}, {"field": "ApprovedApps", "description": "List of approved business apps using webhooks to reduce noise."}]', '2026-05-01 15:26:35.958613');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1068, 'AN0945', 'Analytic 0945', 'Detects user or root invocation of `at` command to schedule a job, followed by job execution using LaunchServices and activity in /usr/lib/cron/at.', '{macOS}', 'x-mitre-analytic--98ce32fb-1b91-4487-9e5a-951375f2380e', 'DET0333', '[{"name": "macos:unifiedlog", "channel": "process: at, job runner", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "fs:fsusage", "channel": "file access to /usr/lib/cron/at and job execution path", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AtPermissions", "description": "Whether `at.allow` and `at.deny` are properly configured."}, {"field": "ExecutionCommand", "description": "Target binary executed via the at job."}, {"field": "RunUser", "description": "Detection of root user scheduling job with unusual command."}]', '2026-05-01 15:26:35.960016');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1069, 'AN0462', 'Analytic 0462', 'Adversary installs/uses packet-capture or raw-socket capability (WinPcap/Npcap, wpcap/packet DLLs or raw socket attach) and sets a filter. A crafted inbound packet is observed; within a short window the host process that loaded capture libraries initiates an outbound connection (e.g., reverse shell) to the packet origin.', '{Windows}', 'x-mitre-analytic--98d733c2-370b-4cd0-8ec6-226a1ca19604', 'DET0162', '[{"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "NSM:Flow", "channel": "Single, low-volume inbound packet (REJ/S0/OTH or uncommon dport/protocol) from src_ip followed by outbound SF connection to src_ip.", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Seconds to correlate inbound trigger → process library load/driver start → outbound connect (default 120s)."}, {"field": "CaptureLibIndicators", "description": "DLL/driver names to match (wpcap.dll, packet.dll, npcap.sys, npf.sys) – extend for EDR drivers in your fleet."}, {"field": "AllowedInstallers", "description": "Signed/expected processes allowed to install/start Npcap (software distribution tools)."}, {"field": "ReversePorts", "description": "Likely egress ports to watch after trigger (4444, 53, 80/443, 8080, high ephemeral)."}]', '2026-05-01 15:26:35.961611');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1070, 'AN0700', 'Analytic 0700', 'Execution of Homebrew, pip3, npm, or manually downloaded PKGs from Terminal or shell, followed by the creation of startup agents, interpreter spawns, or outbound connections to unfamiliar domains. Defender links Terminal commands to plist creation, unsigned binary launches, and `python3` or `node` processes connecting to remote endpoints.', '{macOS}', 'x-mitre-analytic--98f18ad5-0def-4ac3-8822-7538f0a8d64d', 'DET0252', '[{"name": "macos:unifiedlog", "channel": "Command line invocation of pip3, brew install, npm install from interactive Terminal", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Creation of new LaunchAgent or LoginItem plist files in ~/Library/LaunchAgents/", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "NSM:Flow", "channel": "Outbound HTTP/S initiated by newly installed interpreter process", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "StartupAgentPaths", "description": "Filter user persistence plist directories like ~/Library/LaunchAgents"}, {"field": "UnsignedBinaryAlerting", "description": "Enable alerting for new binaries lacking Apple or organization signature"}, {"field": "InstallToNetWindow", "description": "Correlate install action to interpreter-based network behavior"}]', '2026-05-01 15:26:35.962911');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1074, 'AN0434', 'Analytic 0434', 'Non-standard or rare users/locations issue CLI commands like "show clock detail" or "show timezone"; optionally followed by configuration of time/timezone or NTP sources. AAA/TACACS+ accounting and syslog correlate execution to identity, source IP, and privilege level.', '{"Network Devices"}', 'x-mitre-analytic--99ab1534-79b5-4660-83ed-3604bcb320f2', 'DET0151', '[{"name": "networkdevice:syslog", "channel": "command-exec: CLI commands containing \"show clock\", \"show clock detail\", \"show timezone\" executed by suspicious user/source", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:config", "channel": "config-change: timezone or ntp server configuration change after a time query command", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "AllowedAdminSubnets", "description": "Only alert on access from outside the NOC/management subnets."}, {"field": "KnownMaintenanceUsers", "description": "Whitelist known automation/orchestration accounts."}, {"field": "TimeWindow", "description": "Correlation window between time query and config change."}]', '2026-05-01 15:26:35.968063');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1075, 'AN0922', 'Analytic 0922', 'Unusual process (e.g., `rundll32`, `mshta`, `wscript`, or custom payloads) initiates network connection to external IPs/domains that proxy C2 traffic, often over uncommon ports or high entropy HTTP/S connections.', '{Windows}', 'x-mitre-analytic--99b2296f-dc1c-4b0e-a05a-883a0dbb1535', 'DET0325', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Microsoft-Windows-Windows Defender/Operational", "channel": "Unusual external domain access", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "DestinationASN", "description": "Adjust for known benign but high-risk infrastructure (e.g., hosting providers like DigitalOcean, OVH, etc.)."}, {"field": "ParentProcess", "description": "Detect suspicious lineage—proxy tools launched from script interpreters or LOLBins."}, {"field": "EntropyThreshold", "description": "Tune based on expected randomness in outbound request payloads."}]', '2026-05-01 15:26:35.9695');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1076, 'AN1408', 'Analytic 1408', 'Detects downloaded SVG files followed by execution of browser processes or tools like xdg-open, and rapid follow-on network connections or process spawns to interpreters like python or bash.', '{Linux}', 'x-mitre-analytic--99bfd95b-256a-4b1d-bf1d-481f47642c15', 'DET0510', '[{"name": "auditd:SYSCALL", "channel": "open, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Outbound HTTP/S", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TargetPaths", "description": "Suspicious write locations such as /tmp/, ~/Downloads/"}, {"field": "ExecutionContext", "description": "Processes spawned by browsers or svg-viewing apps that invoke interpreters"}, {"field": "NetworkDestinations", "description": "URLs/IPs contacted post-SVG access – may reflect initial C2"}]', '2026-05-01 15:26:35.970686');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1077, 'AN1039', 'Analytic 1039', 'Detect unauthorized `trap` command registrations in shell startup files (e.g., .zprofile, .bash_profile, .zshrc) followed by execution chains during user terminal interaction. Use Unified Logs and EDR telemetry to correlate shell command parsing and process tree anomalies.', '{macOS}', 'x-mitre-analytic--99c42b1f-1716-413b-8c23-5f7e1d997ab2', 'DET0369', '[{"name": "macos:unifiedlog", "channel": "Command line containing `trap` or `echo ''trap` written to login shell files", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "File write or append to .zshrc, .bash_profile, .zprofile, etc.", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "LoginShellConfigPaths", "description": "Startup files vary by shell (.bash_profile, .zshrc, etc.)"}, {"field": "TrapCommandLengthThreshold", "description": "Short benign traps may differ from longer/multi-command malicious traps"}, {"field": "ParentProcessAnomalyThreshold", "description": "Score or detect if new child process deviates from shell’s typical behavior"}]', '2026-05-01 15:26:35.972011');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1078, 'AN0923', 'Analytic 0923', '`curl`, `wget`, `ncat`, `socat`, or custom binaries initiate outbound traffic to Internet-based proxies (e.g., via VPS or CDN). Behavior may include reverse shell constructs or persistent outbound beacons.', '{Linux}', 'x-mitre-analytic--9a0c2390-f8e9-4f03-ae21-0e1e876fed89', 'DET0325', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "conn.log or http.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "alert log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "CommandLinePattern", "description": "Regex or command substring matches indicative of dynamic proxy setup."}, {"field": "ExternalIPList", "description": "Tunable list of IPs or ASNs related to known proxy/VPS abuse."}, {"field": "UserContext", "description": "Unexpected users running networking tools (e.g., www-data, apache)."}]', '2026-05-01 15:26:35.973823');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1079, 'AN0483', 'Analytic 0483', 'Forged cookies in IaaS environments may appear as authentication attempts that bypass MFA, leveraging AssumeRole or session APIs with cookies that were never legitimately issued. Defenders should correlate cloud logs for cookie-based sessions without prior valid authentication, often followed by resource access from unfamiliar IP addresses.', '{IaaS}', 'x-mitre-analytic--9a6089cc-92a7-48ea-b4a4-4d4d2b6489e3', 'DET0171', '[{"name": "AWS:CloudTrail", "channel": "Web console logins using session cookies without corresponding MFA event", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "AWS:CloudTrail", "channel": "GetSessionToken, AssumeRoleWithWebIdentity", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}]', '[{"field": "GeoVelocityThreshold", "description": "Flag logins from geographically distant locations in a short timeframe."}, {"field": "AuthorizedCookieIssuers", "description": "Expected systems and services that may legitimately mint session cookies."}]', '2026-05-01 15:26:35.975588');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1080, 'AN1575', 'Analytic 1575', 'Detects command-line or API-based creation/modification of Windows Services via `sc.exe`, `powershell.exe`, `services.exe`, or `ChangeServiceConfig`. Looks for creation/modification of autostart services via registry changes, file drops to `System32\services`, and anomalous parent-child process trees.', '{Windows}', 'x-mitre-analytic--9a65f8bc-1b81-4e05-8e8b-bfdb0d581213', 'DET0571', '[{"name": "WinEventLog:Security", "channel": "EventCode=4697", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "ServiceNamePattern", "description": "Regex patterns to flag unusual service names or binaries"}, {"field": "ParentProcessFilter", "description": "List of non-administrative processes starting service management tools"}, {"field": "RegistryPathList", "description": "Monitored autorun locations (e.g., `HKLM\\System\\CurrentControlSet\\Services`)"}]', '2026-05-01 15:26:35.978062');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1081, 'AN1632', 'Analytic 1632', 'Detects unauthorized invocation of replication operations (DCSync) via Directory Replication Service (DRS), often executed by threat actors using Mimikatz or similar tools from non-DC endpoints.', '{Windows}', 'x-mitre-analytic--9a68f1a7-65f0-4eef-a711-888bccbeb0d5', 'DET0594', '[{"name": "WinEventLog:Security", "channel": "EventCode=4662", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}, {"name": "WinEventLog:Security", "channel": "EventCode=4929", "x_mitre_data_component_ref": "x-mitre-data-component--9085a576-636a-455b-91d2-c2921bbe6d1d"}, {"name": "NSM:Content", "channel": "Traffic on RPC DRSUAPI", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Defines the correlation window for unusual account access followed by DRSUAPI traffic."}, {"field": "UserContext", "description": "Allows tuning for specific accounts known to legitimately request replication."}, {"field": "SourceIP", "description": "Expected replication should only come from known DCs; this field allows excluding trusted DCs."}]', '2026-05-01 15:26:35.979572');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1082, 'AN1576', 'Analytic 1576', 'Detects creation or modification of `systemd` service units, addition of cron jobs that invoke binaries on boot, or suspicious writes to `/etc/init.d/`. Monitors `chmod +x` and `systemctl` execution paths, especially from non-root parent processes.', '{Linux}', 'x-mitre-analytic--9a73d14c-ce3c-47c5-a6c2-3d6b49c4d009', 'DET0571', '[{"name": "auditd:SYSCALL", "channel": "write or rename to /etc/systemd/system or /etc/init.d", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execution of systemctl or service with enable/start/modify", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ServicePathRegex", "description": "Path-based filters to identify service unit files or init scripts"}, {"field": "UserContextList", "description": "List of expected user contexts that normally perform service changes"}, {"field": "CommandNameList", "description": "Binaries used to register/modify services"}]', '2026-05-01 15:26:35.980812');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1083, 'AN1412', 'Analytic 1412', 'Adversary attaches USB drive and accesses sensitive files using Finder, cp, or bash scripts.', '{macOS}', 'x-mitre-analytic--9abfb75c-2051-4549-b458-f09c4e6f4ad3', 'DET0511', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate ''eventMessage contains \"USBMSC\"''", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "fs:fsusage", "channel": "file reads/writes from /Volumes/", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "VolumePath", "description": "Tune by filtering removable media mounted under /Volumes"}, {"field": "UserContext", "description": "Correlate activity to admin or service accounts for priority"}]', '2026-05-01 15:26:35.982054');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1084, 'AN0138', 'Analytic 0138', 'Malicious Office add-ins loaded via VSTO, COM, or VBA auto-load paths. Upon launch of Word/Excel/Outlook, the add-in executes code without user action. Add-in resides in trusted directory or registered via Office COM/VBE subsystem. Behavior includes unsigned add-in execution, anomalous load context, or add-in spawning interpreter process.', '{"Office Suite"}', 'x-mitre-analytic--9ad4670e-f336-454f-960e-4f2f611f3657', 'DET0050', '[{"name": "WinEventLog:Application", "channel": "Office Add-in load errors, abnormal loading context, or unsigned add-in warnings", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Microsoft-Office/OutlookAddinMonitor", "channel": "Outlook loading add-in via unexpected load path or non-default profile context", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "UnsignedAddInBehavior", "description": "Admins may allow or block unsigned add-ins depending on GPO configuration"}, {"field": "OfficeProductVersion", "description": "Different Office versions store trusted paths and add-in configs in version-specific locations"}, {"field": "AddInTrigger", "description": "Some add-ins only load on specific actions (new document, open file, etc.)"}]', '2026-05-01 15:26:35.983458');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1085, 'AN0950', 'Analytic 0950', 'Detects modification of system or application binaries by monitoring /usr/bin, /bin, and other privileged directories. Correlates file integrity monitoring (FIM) events with unexpected process executions or service restarts.', '{Linux}', 'x-mitre-analytic--9b2ff34a-1967-46a9-b355-f9584a0715b5', 'DET0336', '[{"name": "auditd:SYSCALL", "channel": "open, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WatchedDirectories", "description": "Customize monitored directories (e.g., /usr/bin, /usr/sbin, /opt/apps) for binary tampering"}, {"field": "BaselineHashes", "description": "Maintain golden file hashes for integrity validation"}]', '2026-05-01 15:26:35.984669');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1107, 'AN1171', 'Analytic 1171', 'Detects Automator, AppleScript, or Terminal executing curl, lftp, or TFTP for binary transfer to untrusted IPs or unusual ports.', '{macOS}', 'x-mitre-analytic--9e9efdc0-82d3-4046-a4db-e97454f708a6', 'DET0416', '[{"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:unifiedlog", "channel": "log stream --predicate", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "FilePathAccessed", "description": "e.g., ~/Documents, ~/Library/logs/"}, {"field": "NetworkPortAnomaly", "description": "Non-standard FTP/TFTP ports used (e.g., FTP over 443)"}]', '2026-05-01 15:26:36.016587');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1086, 'AN1403', 'Analytic 1403', 'Detects access to known browser cookie files (e.g., `~/.mozilla/firefox/*.default/cookies.sqlite`, `~/.config/google-chrome/`) and suspicious reads of browser memory via `/proc/[pid]/mem` or ptrace.', '{Linux}', 'x-mitre-analytic--9bcedfe7-c851-418a-b709-dd8883c7fc5e', 'DET0509', '[{"name": "auditd:SYSCALL", "channel": "open or read to browser cookie storage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "ptrace syscall or access to /proc/*/mem", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "CookieFilePatterns", "description": "Regex paths to known browser cookie locations"}, {"field": "TimeWindow", "description": "Correlated time range between cookie read and web upload or process injection"}, {"field": "BrowserProcPatterns", "description": "Expected names for browser processes being accessed"}]', '2026-05-01 15:26:35.985839');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1087, 'AN1137', 'Analytic 1137', 'Detects anomalous usage of local accounts to log into a system, especially accounts not typically used interactively or outside business hours.', '{Windows}', 'x-mitre-analytic--9c53e92a-3659-4137-881a-f4002af9c688', 'DET0407', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "TimeWindow", "description": "Tune for normal business hours to reduce false positives from legitimate after-hours work."}, {"field": "UserContext", "description": "Define list of legitimate local users for interactive access."}]', '2026-05-01 15:26:35.987009');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1088, 'AN0859', 'Analytic 0859', 'Container processes accessing mounted secrets or configuration paths (e.g., /run/secrets, /mnt/config) followed by network access or credential use.', '{Containers}', 'x-mitre-analytic--9c5d279c-eb09-4592-91a4-8cf6436522b6', 'DET0307', '[{"name": "ebpf:syscalls", "channel": "open/read on secret mount paths", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "kubernetes:audit", "channel": "process execution involving curl, grep, or awk on secrets", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "cni:netflow", "channel": "outbound connection to internal or external APIs", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "SecretMountPaths", "description": "Customize based on deployment structure (e.g., /mnt/, /run/secrets/)"}, {"field": "ProcessBaselineDeviation", "description": "Tune anomaly scoring for container image deviations"}]', '2026-05-01 15:26:35.98844');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1089, 'AN1173', 'Analytic 1173', 'Detects internal hosts generating large outbound FTP/TFTP/SMB sessions to external IPs, or file transfers using non-standard ports and application mismatches (e.g., FTP over port 80).', '{"Network Devices"}', 'x-mitre-analytic--9c5ef78d-2e02-4201-ba38-ec858e8b6a6f', 'DET0416', '[{"name": "NSM:Flow", "channel": "ftp.log, conn.log, smb_files.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AppLayerProtocolMatch", "description": "e.g., FTP/SMB observed over uncommon ports"}, {"field": "OutboundDataRateThreshold", "description": "Bytes transferred outside trusted subnets >100MB"}]', '2026-05-01 15:26:35.99004');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1090, 'AN1542', 'Analytic 1542', 'Monitor CLI ''reload'' commands issued without scheduled maintenance, and correlate to TACACS+/AAA logs for privilege validation.', '{"Network Devices"}', 'x-mitre-analytic--9c70d5b3-8748-4f88-8fd8-95f79c73d250', 'DET0559', '[{"name": "networkdevice:syslog", "channel": "reload command issued", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "System reboot scheduled or performed", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "PrivilegeLevel", "description": "TACACS+/AAA role thresholds for command execution."}, {"field": "ChangeTicketCorrelation", "description": "Track change control windows or ITSM integration."}]', '2026-05-01 15:26:35.991787');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1091, 'AN1639', 'Analytic 1639', 'SSH login detected via Unified Logs, followed by unusual process execution, especially outside normal user behavior patterns.', '{macOS}', 'x-mitre-analytic--9c8ba5cd-40db-4214-8db1-b03b2d7b1690', 'DET0596', '[{"name": "macos:unifiedlog", "channel": "process = ''sshd''", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "macos:unifiedlog", "channel": "process = ''ssh'' OR eventMessage CONTAINS ''ssh''", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Time range to correlate post-SSH activities (e.g., 45s)"}, {"field": "UserContext", "description": "Define authorized users to reduce false positives"}, {"field": "CommandLineKeywords", "description": "Suspicious terms like reverse shells, base64, curl"}]', '2026-05-01 15:26:35.993469');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1092, 'AN0940', 'Analytic 0940', 'Detection of msiexec.exe running installer packages that result in anomalous process creation. Look for unexpected binaries executed by msiexec or custom action DLLs in the temp directory.', '{Windows}', 'x-mitre-analytic--9c9db399-4f87-477b-be31-536857b7912d', 'DET0330', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "InstallerParent", "description": "Could be msiexec.exe or third-party wrapper like setup.exe."}, {"field": "ChildImagePath", "description": "Payload paths vary based on where installer extracts to (e.g., %TEMP%, C:\\Users\\Public)."}, {"field": "ExecutionTimeWindow", "description": "Threshold for how soon a payload must run after msiexec to be considered related."}]', '2026-05-01 15:26:35.994829');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1093, 'AN0617', 'Analytic 0617', 'Detects USB block device mount followed by file access in sensitive directories or high-volume copy operations by user-controlled processes.', '{Linux}', 'x-mitre-analytic--9cf3c7bb-296e-445a-ba30-012060b9ccac', 'DET0220', '[{"name": "auditd:SYSCALL", "channel": "open, read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "Kernel Device Events - USB Block Devices", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "MountPath", "description": "Look for /media/, /mnt/, /run/media/ paths associated with removable storage."}, {"field": "CopyCommandSignature", "description": "Detect rsync, cp, tar, zip activity writing to USB mount point."}, {"field": "AccessRateThreshold", "description": "Define abnormal access patterns (e.g., >100 files in <5 min)."}]', '2026-05-01 15:26:35.996305');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1094, 'AN1150', 'Analytic 1150', 'Monitor unified logs for manipulation of proxy configurations, DNS resolution, or filtering rules. Adversaries may redirect responses or use trusted domains that later resolve to malicious C2 infrastructure.', '{macOS}', 'x-mitre-analytic--9cf6c89d-73f7-42f8-b5e4-c87bf3abbb7d', 'DET0411', '[{"name": "macos:unifiedlog", "channel": "System process modifications altering DNS/proxy settings", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Suspicious changes in TLS certificate responses or redirected domains", "x_mitre_data_component_ref": "x-mitre-data-component--0dcbbf4f-929c-489a-b66b-9b820d3f7f0e"}]', '[{"field": "TrustedHostingProviders", "description": "Known hosting/CDN providers often abused to hide malicious C2 infrastructure."}]', '2026-05-01 15:26:35.99761');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1095, 'AN1954', 'Analytic 1954', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1096, 'AN1605', 'Analytic 1605', 'Adversary invokes ''useradd'', ''adduser'', or equivalent system commands or scripts to create local users. Detection focuses on command execution and audit trail of passwd/shadow file modifications.', '{Linux}', 'x-mitre-analytic--9d70d90c-f318-4318-a18d-e4775ffa229e', 'DET0583', '[{"name": "auditd:SYSCALL", "channel": "useradd or adduser executed", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "auditd:SYSCALL", "channel": "chmod/chown to /etc/passwd or /etc/shadow", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "BinaryPath", "description": "Custom scripts or renamed binaries may evade simple path-based detection"}, {"field": "ExecutionTime", "description": "Account creation outside maintenance windows may indicate compromise"}]', '2026-05-01 15:26:36.000381');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1097, 'AN0050', 'Analytic 0050', 'Adversary attempts to detect monitoring agents such as Little Snitch, KnockKnock, or other system daemons via process listing (`ps -e`), application folder checks, and system extension listing.', '{macOS}', 'x-mitre-analytic--9d76d84b-6393-45cf-b872-eb5921508ee3', 'DET0016', '[{"name": "macos:unifiedlog", "channel": "execution of security-agent detection or enumeration commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ToolNameMatch", "description": "Adversary may search for specific software names; defenders can tune based on local deployments"}]', '2026-05-01 15:26:36.001685');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1098, 'AN0618', 'Analytic 0618', 'Detects external volume mount with Finder, Terminal, or script-initiated file copy from user profiles, sensitive folders, or cloud storage sync directories to USB.', '{macOS}', 'x-mitre-analytic--9d7fd025-d8eb-48ab-8fca-df6b09761aec', 'DET0220', '[{"name": "macos:unifiedlog", "channel": "Volume Mount + Process Trace + File Read", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "fs:fsusage", "channel": "Disk Activity Tracing", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DriveLabelFilter", "description": "Flag removable volumes with suspicious or default names (e.g., NO NAME, BACKUP_01)."}, {"field": "ScriptExecutionContext", "description": "Watch for shell or AppleScript execution tied to USB copy."}, {"field": "VolumeMountFrequency", "description": "Detect repeated or abnormal device mounts during work hours."}]', '2026-05-01 15:26:36.004321');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1099, 'AN1313', 'Analytic 1313', 'Adversaries using WinRM to remotely execute commands, launch child processes, or access WMI. The detection chain includes service use, network activity, remote session logon, and process creation within a short temporal window.', '{Windows}', 'x-mitre-analytic--9dab17bf-62c7-4187-90f4-7335790df7c0', 'DET0477', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:WinRM", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "NSM:Connections", "channel": "Inbound on ports 5985/5986", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "Defines max time between remote shell creation and child process execution (e.g., 60 seconds)"}, {"field": "UserContext", "description": "Scope to unexpected remote user logons (non-admins, service accounts)"}, {"field": "CommandLineAnomalyScore", "description": "Score for suspicious command usage via WinRM (e.g., encoded PowerShell)"}, {"field": "KnownAdminHosts", "description": "List of trusted systems allowed to use WinRM legitimately"}]', '2026-05-01 15:26:36.00568');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1100, 'AN2040', 'Analytic 2040', 'Detects crafted activity resulting in crashes or impairment of endpoint security extensions, network filters, launch daemons, or telemetry agents. Correlates process activity, system extension state changes, and telemetry interruption.', '{macOS}', 'x-mitre-analytic--9df50fd3-bbad-43ce-b511-1bf995f1b583', 'DET0900', '[{"name": "macos:unifiedlog", "channel": "Crash or abnormal termination of security agent or system extension host", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "macos:unifiedlog", "channel": "Extension disabled, unloaded, failed to start", "x_mitre_data_component_ref": "x-mitre-data-component--f5a9a1dd-82f9-41a3-85b8-13e5b9cd6c79"}, {"name": "NSM:Flow", "channel": "Traffic spike preceding control crash", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ExtensionList", "description": "Protected security system extensions"}, {"field": "CrashBurstThreshold", "description": "Multiple failures in short interval"}]', '2026-05-01 15:26:36.007494');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1108, 'AN0415', 'Analytic 0415', 'Adversary destroys virtual disks (VMDK), images, or VMs by invoking `vim-cmd`, deleting datastore contents, or purging snapshots.', '{ESXi}', 'x-mitre-analytic--9ea1e329-691a-43a7-b56d-affbc00fb9e7', 'DET0146', '[{"name": "esxi:vmkernel", "channel": "file delete|datastore purge", "x_mitre_data_component_ref": "x-mitre-data-component--3acecdde-c327-4498-9bb8-33a2e63c6c57"}]', '[{"field": "DatastorePath", "description": "Targeted deletion of critical VMDKs or VM configuration files."}, {"field": "InitiatingUser", "description": "Detect deletions from users outside normal maintenance windows."}]', '2026-05-01 15:26:36.017955');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1101, 'AN1432', 'Analytic 1432', 'Identifies CLI interpreter access (e.g., Cisco IOS, Juniper JUNOS) via `enable` mode or scripting-capable sessions used by uncommon accounts or from unknown IPs.', '{"Network Devices"}', 'x-mitre-analytic--9e03886b-155c-4483-9d92-dad6a7d8543b', 'DET0516', '[{"name": "networkdevice:cli", "channel": "shell command", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "authentication & authorization", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "UserRole", "description": "Which roles or privilege levels should be monitored for interpreter misuse."}, {"field": "DeviceType", "description": "Support filtering for routers, switches, firewalls depending on network segmentation."}]', '2026-05-01 15:26:36.008956');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1102, 'AN0157', 'Analytic 0157', 'Detects adversaries attempting to attach debuggers or memory dump utilities to credential storage daemons analogous to macOS `securityd`. Observes ptrace syscalls, /proc/<pid>/mem access, or gcore dumps against sensitive processes. Correlates anomalies with privilege escalation or credential dumping attempts.', '{Linux}', 'x-mitre-analytic--9e0af3ac-dfeb-48c3-8d15-5f9edd69be69', 'DET0057', '[{"name": "auditd:SYSCALL", "channel": "ptrace attach", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "auditd:FILE", "channel": "/proc/*/mem read attempt", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:EXECVE", "channel": "gcore, gdb, strings, hexdump execution", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "MonitoredProcesses", "description": "List of credential storage daemons (e.g., securityd, gnome-keyring, kwallet) monitored for memory access attempts"}, {"field": "CorrelationDepth", "description": "Defines how many chained events (process execution + syscall + file read) to correlate before raising an alert"}, {"field": "PrivilegeContext", "description": "Expected user/group context for processes allowed to access protected memory"}]', '2026-05-01 15:26:36.010316');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1103, 'AN0064', 'Analytic 0064', 'Attacker disables VM-related services or stops VMs forcibly to target vmdk or logs. Behavioral chain: esxcli or vim-cmd stop + audit log showing user privilege use + datastore file manipulation.', '{ESXi}', 'x-mitre-analytic--9e12e1f0-1547-4008-8755-2b3bc1c00279', 'DET0021', '[{"name": "esxi:hostd", "channel": "Stop VM or disable service events via vim-cmd", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "esxi:hostd", "channel": "Log entries indicating VM powered off or forcibly terminated", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "VMName", "description": "Targeted virtual machine name"}, {"field": "InitiatorUser", "description": "User who issued stop or disable command"}]', '2026-05-01 15:26:36.011555');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1104, 'AN1109', 'Analytic 1109', 'File creation of unauthorized script (e.g., .php, .sh) in /var/www/html followed by execution of unexpected system utilities (e.g., curl, bash, nc) by apache/nginx', '{Linux}', 'x-mitre-analytic--9e80763b-5287-451f-b2ab-37168b159387', 'DET0394', '[{"name": "auditd:SYSCALL", "channel": "new file created in /var/www/html, /srv/http, or similar web root", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "apache2 or nginx spawning sh, bash, or python interpreter", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "POST requests to .php, .jsp, .aspx files with high entropy body", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "WebRootPath", "description": "Web server root varies by distro and hosting configuration"}, {"field": "PayloadEntropyThreshold", "description": "Base64 or XOR encoded shells may exceed this value"}, {"field": "TimeWindow", "description": "Correlate file creation with process spawn within X seconds"}]', '2026-05-01 15:26:36.012907');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1105, 'AN0022', 'Analytic 0022', 'Developer or CI invokes package managers/compilers (apt/yum + build-essential, npm/yarn/pnpm, pip/pip3, gem, cargo, go, maven/gradle). These write executable or script files into PATH or project dirs and immediately execute embedded lifecycle hooks (preinstall/postinstall, setup.py, npm scripts) that spawn shells or curl/wget, followed by egress to unfamiliar registries or domains.', '{Linux}', 'x-mitre-analytic--9e95639e-633f-47cf-b343-3ea771c19192', 'DET0009', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "rename, chmod", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "journald:package", "channel": "dpkg/apt or yum/dnf transaction logs (install/update of build tools)", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "NSM:Flow", "channel": "First-time egress to new registries/CDNs post-install/build", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ApprovedRepos", "description": "Allowed APT/YUM repos and GPG keys for build tools."}, {"field": "PathScope", "description": "Monitor /usr/local/bin, /usr/bin, /opt/*/bin, ~/.local/bin, node_modules/.bin, .venv/bin, .cargo/bin, .gradle, .m2."}, {"field": "TimeWindow", "description": "Default 90 minutes for write→exec→egress linkage."}]', '2026-05-01 15:26:36.014146');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1106, 'AN1371', 'Analytic 1371', 'Detection of adversary disabling endpoint security tools by unloading launch agents/daemons, modifying configuration profiles, or disabling Gatekeeper/XProtect/logging settings, or removing endpoint agents followed by telemetry loss.', '{macOS}', 'x-mitre-analytic--9e9a5111-038b-4c68-a8bc-6d094723def4', 'DET0497', '[{"name": "macos:unifiedlog", "channel": "Execution of launchctl unload, kill, or removal of security agent daemons", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Modification of system configuration profiles affecting security tools", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "DaemonNames", "description": "Expected security agent daemons (e.g., com.crowdstrike.falcon.Agent)."}, {"field": "TimeWindow", "description": "Detection correlation period for multiple security tool disable actions."}]', '2026-05-01 15:26:36.015428');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1109, 'AN0633', 'Analytic 0633', 'Processes initiating outbound connections on uncommon ports or using protocols inconsistent with the assigned port. Correlating process creation with subsequent network connections reveals anomalies such as svchost.exe or Office applications using high, atypical ports.', '{Windows}', 'x-mitre-analytic--9ea7f21e-700f-4900-a1d4-dfc171d399fe', 'DET0227', '[{"name": "WinEventLog:Security", "channel": "EventCode=5156, 5157", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PortThresholds", "description": "Define what constitutes a ''non-standard port'' based on organizational baselines (e.g., allow 443/80/22 but flag 8088/587/3389 changes)."}, {"field": "ProcessAllowList", "description": "Processes normally allowed to use non-standard ports (e.g., custom apps)."}, {"field": "TimeWindow", "description": "Correlate process creation and network activity within N seconds."}]', '2026-05-01 15:26:36.019159');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1110, 'AN2019', 'Analytic 2019', 'Internet scanners may be used to look for patterns associated with malicious content designed to collect host hardware information from visitors.(Citation: ThreatConnect Infrastructure Dec 2020)(Citation: ATT ScanBox)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1111, 'AN0088', 'Analytic 0088', 'Detects suspicious updates to conditional access or MFA enforcement policies in identity providers such as Entra ID, Okta, or JumpCloud. Focus is on removal of policy blocks, addition of broad exclusions, or registration of adversary-controlled MFA methods, followed by anomalous login activity that takes advantage of the modified policies.', '{"Identity Provider"}', 'x-mitre-analytic--9eb2a081-e252-4009-a16e-90c9a85f70f1', 'DET0030', '[{"name": "azure:activity", "channel": "Update conditionalAccessPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "saas:okta", "channel": "Conditional Access policy rule modified or MFA requirement disabled", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TargetedApplications", "description": "Specific SaaS or cloud apps most sensitive to conditional access changes."}, {"field": "RiskThresholds", "description": "Risk scores or signals that may be tuned for anomaly detection in login behavior."}, {"field": "UserContext", "description": "Business roles or expected MFA patterns per user/group to reduce false positives."}]', '2026-05-01 15:26:36.021461');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1112, 'AN2023', 'Analytic 2023', 'Monitor for queried domain name system (DNS) registry data that may compromise third-party DNS servers that can be used during targeting. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1113, 'AN0021', 'Analytic 0021', 'Adversary manipulates dependencies/dev tools used by developers or CI: a package manager (npm/yarn/pnpm, pip/pipenv, nuget/dotnet, chocolatey/winget, maven/gradle) or a compiler/IDE downloads or restores content; files are written under project paths and execution paths (node_modules, packages, .nuget, .gradle, .m2, %AppData%\npm, %UserProfile%\.cargo\bin, temp build dirs). First run of newly written components triggers scripts (preinstall/postinstall), shell/PowerShell spawning, or loader DLLs, followed by network egress to non-approved registries/CDNs.', '{Windows}', 'x-mitre-analytic--9ec9d296-173f-4e47-8bc4-d20d558e6e18', 'DET0009', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "channel": "Invalid/Unsigned image when developer tool launches newly installed binaries", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "NSM:Flow", "channel": "First-time outbound connections to package registries or unknown hosts immediately after restore/build", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "Correlate file write by package manager to first execution and egress (default 90 minutes)."}, {"field": "ApprovedRegistries", "description": "Allow-listed registries (e.g., registry.npmjs.org, pypi.org, nuget.org, maven.apache.org, company proxies/CDNs)."}, {"field": "DevHosts", "description": "Limit analytics to engineering endpoints/CI agents to reduce noise."}, {"field": "TrustedPublishers", "description": "Code-signing publishers acceptable for dev tools."}]', '2026-05-01 15:26:36.024648');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1120, 'AN1972', 'Analytic 1972', 'Consider use of services that may aid in the tracking of certificates in use on sites across the Internet. In some cases it may be possible to pivot on known pieces of certificate information to uncover other adversary infrastructure.(Citation: Splunk Kovar Certificates 2017)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1114, 'AN0431', 'Analytic 0431', 'A process (often spawned by a shell, interpreter, or malware implant) executes time discovery via commands (date, timedatectl, hwclock, cat /etc/timezone, /proc/uptime) or direct syscalls (time(), clock_gettime) and is (optionally) followed by scheduled task creation/modification (crontab, at) or conditional sleep logic.', '{Linux}', 'x-mitre-analytic--9f2278c6-2e45-42fb-a1f9-00f02d496c53', 'DET0151', '[{"name": "auditd:SYSCALL", "channel": "type=EXECVE or SYSCALL for /bin/date, /usr/bin/timedatectl, /sbin/hwclock, /bin/cat /etc/timezone, /bin/cat /proc/uptime", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "Rules capturing clock_gettime, time, gettimeofday syscalls when enabled", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "linux:syslog", "channel": "sudo/date/timedatectl execution by non-standard users", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "linux:cron", "channel": "cron activity", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}]', '[{"field": "AuditRulesSyscalls", "description": "Scope of syscalls (time, clock_gettime, gettimeofday) monitored; may be performance-sensitive."}, {"field": "AllowedBinaries", "description": "List of legitimate automation/orchestration tools frequently querying time."}, {"field": "TimeWindow", "description": "Correlation window (e.g., 5–20 minutes) to link time discovery to follow-on cron/at changes."}, {"field": "UserContextScope", "description": "Ignore root-owned maintenance agents if desired; focus on interactive or newly created users."}]', '2026-05-01 15:26:36.026118');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1115, 'AN0576', 'Analytic 0576', 'Cause→effect chain: (1) A user or service launches an indirection utility (e.g., forfiles.exe, pcalua.exe, wsl.exe, scriptrunner.exe, ssh.exe with -o ProxyCommand/LocalCommand). (2) That utility spawns a secondary program/command (PowerShell, cmd, msiexec, regsvr32, curl, arbitrary EXE) and/or opens outbound network connections. (3) Optional precursor modification of SSH config to persist LocalCommand/ProxyCommand. Correlate process creation, command/script content, file access to %USERPROFILE%\.ssh\config, and network connections from the utility or its child.', '{Windows}', 'x-mitre-analytic--9f3aea30-e100-432a-8aa0-959bd7f4e069', 'DET0200', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "TimeWindow", "description": "Correlation window between indirect launcher and spawned child/network activity (e.g., 10–30 minutes)."}, {"field": "AllowedUtilities", "description": "Utilities permitted on admin/Jumphosts (forfiles, wsl, ssh) to reduce noise."}, {"field": "HighRiskChildren", "description": "Child images that indicate abuse (powershell.exe, cmd.exe, rundll32.exe, regsvr32.exe, mshta.exe, msiexec.exe, curl.exe, bitsadmin.exe)."}, {"field": "UserContext", "description": "Raise severity when the actor is a standard/interactive user on a workstation rather than a server or CI agent."}, {"field": "DestCIDRs", "description": "Known-good egress networks for SSH/WSL activity to suppress expected admin automations."}]', '2026-05-01 15:26:36.027519');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1116, 'AN0615', 'Analytic 0615', 'Detection of ESXi escape attempts by monitoring for anomalies in hypervisor logs such as unexpected VM operations, privilege escalation events, or attempts to load malicious kernel modules within the hypervisor environment.', '{ESXi}', 'x-mitre-analytic--9f5f193f-6aef-4586-a047-492b0c651001', 'DET0219', '[{"name": "esxi:vmkernel", "channel": "VM exit/entry anomalies, unexpected hypercalls, or kernel module loading", "x_mitre_data_component_ref": "x-mitre-data-component--23e4ee78-26f3-4fcf-ba43-ab953962f96c"}]', '[{"field": "AllowedKernelModules", "description": "Modules permitted in the hypervisor. Loading any module outside of this list may indicate compromise."}]', '2026-05-01 15:26:36.029601');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1117, 'AN1303', 'Analytic 1303', 'Detects suspicious registration of new password filter DLLs into the authentication process. Correlates registry modifications to LSASS Notification Packages with subsequent DLL creation and loading events. Observes anomalous file placement of DLLs in system directories followed by LSASS loading the new filter during logon/password change activity.', '{Windows}', 'x-mitre-analytic--9fb6bb78-418a-483f-ae23-518ffde414d1', 'DET0472', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "RegistryPath", "description": "Specific registry path monitored for modification (e.g., HKLM\\SYSTEM\\CurrentControlSet\\Control\\Lsa\\Notification Packages)."}, {"field": "AllowedDLLs", "description": "Known and approved password filter DLLs; deviations from baseline may indicate malicious injection."}, {"field": "TimeWindow", "description": "Time window for correlating registry modification, file creation, and module load events."}, {"field": "FilePathPatterns", "description": "Expected directories for legitimate password filter DLLs; anomalous paths may signal compromise."}]', '2026-05-01 15:26:36.030936');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1118, 'AN0536', 'Analytic 0536', 'Drive enumeration using PowerShell (`Get-PSDrive`), `wmic logicaldisk`, or Win32 API indicative of local volume enumeration by non-admin users or executed outside of baseline system inventory scripts.', '{Windows}', 'x-mitre-analytic--9ffd3332-fcc0-440d-b717-ef98e140c543', 'DET0188', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "user_context", "description": "Non-system accounts performing drive enumeration may be higher fidelity indicators"}, {"field": "parent_process_name", "description": "Baseline parent-child process lineage can help distinguish admin tools from malicious scripts"}]', '2026-05-01 15:26:36.032154');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1119, 'AN1298', 'Analytic 1298', 'Detects adversary tampering of shared directories via file drops (e.g., malicious LNK, EXE, VBS) followed by user execution or suspicious network activity.', '{Windows}', 'x-mitre-analytic--a0554596-7100-4f8b-a4dd-165f528fe6a1', 'DET0471', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=5145", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}]', '[{"field": "SharedPathPrefix", "description": "Defines monitored shared directories (e.g., \\\\server\\HR\\)."}, {"field": "ExecutableExtensions", "description": "Monitored file types dropped in shared paths (e.g., .lnk, .exe, .vbs)."}]', '2026-05-01 15:26:36.033399');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1122, 'AN1095', 'Analytic 1095', 'Detects DLL injection through correlation of memory allocation and writing to remote process memory (e.g., VirtualAllocEx, WriteProcessMemory), followed by remote thread creation (e.g., CreateRemoteThread) that loads a suspicious or unsigned DLL using LoadLibrary or reflective loading.', '{Windows}', 'x-mitre-analytic--a06e9154-5584-4f5d-be47-b420d79674c7', 'DET0389', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=17", "x_mitre_data_component_ref": "x-mitre-data-component--b9a1578e-8653-4103-be23-cb52e0b1816e"}]', '[{"field": "InjectedDLLSignatureStatus", "description": "Whether the DLL is unsigned, untrusted, or loaded from a non-standard path"}, {"field": "TimeWindow", "description": "Temporal correlation threshold between memory operations and thread creation"}, {"field": "TargetProcessList", "description": "List of sensitive or high-value processes targeted for injection (e.g., explorer.exe, winlogon.exe)"}, {"field": "ParentProcessAnomalyThreshold", "description": "Degree of deviation from expected parent-child lineage"}]', '2026-05-01 15:26:36.03709');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1123, 'AN0258', 'Analytic 0258', 'Detects creation or modification of scheduled tasks using schtasks.exe, at.exe, or COM objects followed by execution of outlier processes tied to the scheduled job.', '{Windows}', 'x-mitre-analytic--a0714b4d-5dbf-499e-a737-7b00478267ee', 'DET0094', '[{"name": "WinEventLog:Security", "channel": "EventCode=4698", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "TaskAuthor", "description": "Unexpected user or account context initiating the task."}, {"field": "CommandLineRegex", "description": "Suspicious binaries or script usage tied to scheduled tasks."}, {"field": "ExecutionWindow", "description": "Lookback window to correlate process execution after task registration."}]', '2026-05-01 15:26:36.038436');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1124, 'AN1130', 'Analytic 1130', 'Discovery of connected SaaS applications, APIs, or configurations within platforms like Salesforce, Slack, or Zoom. Defender perspective includes enumeration of available integrations, abnormal querying of service metadata, and follow-on attempts to exploit or persist via discovered services.', '{SaaS}', 'x-mitre-analytic--a0730d9f-0a05-4153-8c6a-6f04f9f7346c', 'DET0402', '[{"name": "saas:adminapi", "channel": "ListIntegrations, ListServices: Repeated service discovery requests from accounts without administrative responsibilities", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"name": "saas:auth", "channel": "Login, TokenGranted: Discovery actions tied to anomalous login sessions or tokens", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "IntegrationDiscoveryThreshold", "description": "Number of SaaS integrations enumerated before triggering detection."}, {"field": "ServiceAccountScope", "description": "Expected permissions for service accounts to distinguish benign from malicious discovery."}]', '2026-05-01 15:26:36.040231');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1125, 'AN0551', 'Analytic 0551', 'Suspicious creation or modification of inbox rules through PowerShell (New-InboxRule, Set-InboxRule) to automatically delete, move, or hide emails. Defender perspective: unusual rule activity correlated with mailbox access and filtering patterns.', '{Windows}', 'x-mitre-analytic--a09ed72b-be04-475f-8c0a-11ed47b40bd1', 'DET0192', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "m365:unified", "channel": "New-InboxRule or Set-InboxRule events recorded in Exchange Online", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "SuspiciousKeywords", "description": "Keywords like ''phish'', ''malware'', ''suspicious'' used in inbox rules to hide emails."}, {"field": "UserContext", "description": "Scope mailbox monitoring to high-value users such as executives or admins."}]', '2026-05-01 15:26:36.041993');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1126, 'AN0376', 'Analytic 0376', 'Creation of VSCode tunnel configuration file combined with interactive remote session via code CLI or ssh with JetBrains gateway.', '{Linux}', 'x-mitre-analytic--a0a0f8e9-7a55-4450-8569-7a0e1c0aac0b', 'DET0133', '[{"name": "auditd:SYSCALL", "channel": "execve on code or jetbrains-gateway with remote flags", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open: Write to ~/.vscode-cli/code_tunnel.json", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Connections to *.devtunnels.ms or tunnels.api.visualstudio.com", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "PathRegex", "description": "Regex patterns for user home directory file paths may vary by distro or user."}, {"field": "TunnelCLIFlags", "description": "Tunnel flags used by CLI tools can be customized or obfuscated by adversaries."}, {"field": "Username", "description": "The Linux user account associated with tunnel initiation; may vary across developer environments"}, {"field": "TunnelArtifactPath", "description": "The filepath to the .vscode-cli/code_tunnel.json file may vary by distribution or IDE version"}, {"field": "CommandLineFlags", "description": "Different IDEs or wrapper scripts may launch with different tunnel-related CLI options (e.g., --remote, --host)"}]', '2026-05-01 15:26:36.04377');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1127, 'AN0810', 'Analytic 0810', 'Detects login to admin consoles (e.g., Microsoft 365 Admin Center) from unrecognized users, devices, or geolocations followed by non-API data review or configuration read actions that suggest GUI dashboard use.', '{"Office Suite"}', 'x-mitre-analytic--a0bfcae2-1936-466d-91b4-f72fcae730b6', 'DET0291', '[{"name": "m365:signinlogs", "channel": "UserLoginSuccess", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "m365:unified", "channel": "ViewAdminReport", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "m365:unified", "channel": "Read-only configuration review from GUI", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "AdminRoleList", "description": "Roles allowed to access dashboard views"}, {"field": "DashboardNavigationSequence", "description": "Pageview paths or clickstreams indicating use of GUI admin console"}, {"field": "GeoLocationRisk", "description": "List of high-risk regions or unexpected geos"}]', '2026-05-01 15:26:36.046079');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1128, 'AN0474', 'Analytic 0474', 'Firmware flash utility invoked with elevated privileges followed by raw access to firmware device path or changes to boot configuration.', '{Windows}', 'x-mitre-analytic--a0ecdd41-a051-4ada-9ec1-c29dc0c4ac61', 'DET0167', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:Microsoft-Windows-Kernel-Boot", "channel": "Firmware integrity validation failed or boot configuration tampered", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}]', '[{"field": "ParentImage", "description": "Common legitimate flash tool chains can be allowlisted"}, {"field": "CommandLine", "description": "Flags indicating silent or forced flash may vary"}]', '2026-05-01 15:26:36.048441');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1129, 'AN1279', 'Analytic 1279', 'Excessive login attempts followed by success from SaaS apps like O365, Dropbox, etc.', '{SaaS}', 'x-mitre-analytic--a1436a64-ffc4-4e39-a7c8-140e78336ffa', 'DET0463', '[{"name": "m365:unified", "channel": "Sign-in logs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AppName", "description": "Detect brute force attempts targeting specific apps"}, {"field": "UserGroup", "description": "Limit alert scope to high-value user groups"}]', '2026-05-01 15:26:36.050036');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1130, 'AN1102', 'Analytic 1102', 'Adversary runs ''system_profiler SPApplicationsDataType'' or queries plist files to enumerate software via Terminal or scripts.', '{macOS}', 'x-mitre-analytic--a1619e8f-10aa-46ab-8776-898e8c3d5b43', 'DET0392', '[{"name": "macos:unifiedlog", "channel": "Execution of system_profiler or osascript invoking enumeration", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "Command line arguments including SPApplicationsDataType", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AppScope", "description": "Whether enumeration targets user apps or system apps."}, {"field": "ProcessGroup", "description": "Parent process or scripting environment (e.g., Python, osascript)."}]', '2026-05-01 15:26:36.051401');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1131, 'AN0435', 'Analytic 0435', 'Detection focuses on adversaries placing or modifying malicious dylibs in locations searched by legitimate applications. From the defender’s perspective, observable patterns include unexpected creation or modification of dylib files in application bundle paths, unusual module loads by processes compared to historical baselines, and execution of applications loading dylibs from suspicious directories (e.g., /tmp, user-controlled paths). Correlation across file system changes, process execution, and module loads provides high-fidelity detection.', '{macOS}', 'x-mitre-analytic--a1e502e2-d940-4c71-9eac-893e7a3025e3', 'DET0152', '[{"name": "macos:unifiedlog", "channel": "process execution events with dylib load activity", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "macos:unifiedlog", "channel": "create/modify dylib files in monitored directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "replace existing dylibs", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "MonitoredDirectories", "description": "Application bundle directories (e.g., /Applications/*/Contents/MacOS, /Library/Frameworks). Adversaries may use non-standard paths like /tmp."}, {"field": "BaselineDylibs", "description": "Historical record of dylibs typically loaded by applications. Deviations should be flagged."}, {"field": "CorrelationWindow", "description": "Timeframe to correlate dylib file modification with subsequent process execution and module loads."}]', '2026-05-01 15:26:36.052898');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1132, 'AN1414', 'Analytic 1414', 'Detects staged file access (e.g., archive or obfuscation), followed by an encrypted outbound connection (TLS/HTTPS) from unusual processes such as curl/wget, Python scripts, or custom binaries.', '{Linux}', 'x-mitre-analytic--a2309590-988e-4116-85e6-59bfc5357726', 'DET0512', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "ssl.log, conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "auditd:SYSCALL", "channel": "open, read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ConnectionDestinationScope", "description": "Restrict outbound connections to non-corporate domains or IPs."}, {"field": "FileAccessExtensionList", "description": "List of extensions considered sensitive or exfil-worthy (e.g., .zip, .db, .xlsx)."}, {"field": "SSLClientProcessBaseline", "description": "Define normal encrypted-traffic-capable binaries."}]', '2026-05-01 15:26:36.054196');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1133, 'AN1212', 'Analytic 1212', 'Detects adversary activity aimed at accessing LSA Secrets, including registry key export of HKEY_LOCAL_MACHINE\SECURITY\Policy\Secrets or memory scraping via tools such as Mimikatz or PowerSploit''s Invoke-Mimikatz.', '{Windows}', 'x-mitre-analytic--a29288f5-c5d8-4e2d-8370-c4e21a64fc95', 'DET0437', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TargetObject", "description": "Target registry paths like HKLM\\SECURITY\\Policy\\Secrets or variants can be tuned depending on OS version or registry redirection settings."}, {"field": "ImageLoaded", "description": "Module names such as `lsasrv.dll`, `sechost.dll`, or suspicious DLLs loaded by user processes may require tuning for known-good service operations."}, {"field": "AccessMask", "description": "Tuning based on whether processes are using specific sensitive access rights (e.g., 0x2 or 0x4)."}, {"field": "TimeWindow", "description": "Temporal window between registry access and command-line tool execution."}]', '2026-05-01 15:26:36.055628');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1134, 'AN1260', 'Analytic 1260', 'Adversary adds federated identity provider (IdP) or modifies tenant domain authentication from Managed to Federated. Detected via API, PowerShell, or Admin Portal through federation events like `Set domain authentication`, `Add federated identity provider`, or `Update-MsolFederatedDomain`.', '{"Identity Provider"}', 'x-mitre-analytic--a2d3072a-0f3a-46a1-a92e-f0d7ae030b48', 'DET0458', '[{"name": "m365:unified", "channel": "Set federation settings on domain|Set domain authentication|Add federated identity provider", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "azure:signinlogs", "channel": "OperationName=SetDomainAuthentication OR Update-MsolFederatedDomain", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "OperationName", "description": "Identify rare trust-modification operations (SetDomainAuthentication, Update-MsolFederatedDomain)."}, {"field": "InitiatedBy", "description": "Flag federated trust changes performed by unknown users, service principals, or tokens."}, {"field": "UserAgent", "description": "Separate scripted/API interactions from GUI-based administrative changes."}, {"field": "TimeWindow", "description": "Correlate trust change to federated login or SAML token injection within short window."}]', '2026-05-01 15:26:36.057551');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1135, 'AN0380', 'Analytic 0380', 'Detects non-interactive or script-driven email transmission using tools like `sendmail`, `mailx`, or custom SMTP scripts by background processes, especially when sending attachments or large payloads.', '{Linux}', 'x-mitre-analytic--a311af7c-2302-4113-8cc3-d5d599fa908a', 'DET0135', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "smtp.log, conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TransferSizeThreshold", "description": "Bytes transferred via SMTP session"}, {"field": "ScriptNameFilter", "description": "e.g., base64 encoded mailer scripts or one-liners in cron"}]', '2026-05-01 15:26:36.059439');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1136, 'AN0273', 'Analytic 0273', 'Processes that utilize AppleScript, `CGWindowListCopyWindowInfo`, or `NSRunningApplication` APIs to list active application windows and foreground processes.', '{macOS}', 'x-mitre-analytic--a31400ee-ac3e-408e-aa4d-fb2b470142ab', 'DET0097', '[{"name": "macos:unifiedlog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AppleScriptTarget", "description": "Tunable to ignore benign scripting like automation by known apps."}, {"field": "ParentProcess", "description": "Useful to suppress expected automation processes."}]', '2026-05-01 15:26:36.060953');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1137, 'AN2064', 'Analytic 2064', 'Detection identifies execution of scripts containing high concentrations of invisible Unicode characters followed by decoding or interpretation behaviors (e.g., base64 decode, eval) and subsequent process or network activity. Emphasis is placed on mismatch between file entropy/structure and execution output.', '{Linux}', 'x-mitre-analytic--a32c4f38-feaf-4291-9dad-3043114b4d37', 'DET0920', '[{"name": "auditd:SYSCALL", "channel": "stat and lstat syscall results on files, including inode and permission info", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "auditd:EXECVE", "channel": "execve of script/interpreter (bash, python, node) with suspicious encoded or non-printable content", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "DecodeUtility", "description": "May include base64"}, {"field": "EntropyThreshold", "description": "Useful for tuning sections containing high entropy indicative of Unicode sequences"}]', '2026-05-01 15:26:36.06231');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1138, 'AN0751', 'Analytic 0751', 'SSH session from new source IP followed by interactive shell or privilege escalation (e.g., sudo, su) and outbound lateral connection.', '{Linux}', 'x-mitre-analytic--a366262a-ba79-4b74-be16-0b139d546651', 'DET0269', '[{"name": "linux:syslog", "channel": "sshd: Accepted password/publickey", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "auditd:SYSCALL", "channel": "execve, USER_CMD", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SourceIP", "description": "Limit to new/unexpected SSH source IPs"}, {"field": "CommandList", "description": "Flag suspicious post-SSH command patterns"}]', '2026-05-01 15:26:36.064009');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1139, 'AN0298', 'Analytic 0298', 'Correlation of inbound emails with embedded links followed by user-driven browser navigation to suspicious or obfuscated domains. Detection chain includes malicious URL in email → user click recorded in Office logs → browser process spawning unusual child processes (e.g., PowerShell, cmd) or download activity.', '{Windows}', 'x-mitre-analytic--a39fccda-e5ea-49de-80f9-d67ae3b8c799', 'DET0107', '[{"name": "m365:unified", "channel": "Send/Receive: Inbound emails containing embedded or shortened URLs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "SuspiciousTLDs", "description": "List of monitored top-level domains commonly abused in phishing (e.g., .xyz, .top, .tk)."}, {"field": "URLShortenerDomains", "description": "Domains like bit.ly, tinyurl.com flagged for deeper expansion/inspection."}, {"field": "ClickToExecutionWindow", "description": "Time threshold between URL click and suspicious process execution."}]', '2026-05-01 15:26:36.065218');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1140, 'AN1005', 'Analytic 1005', 'Repeated SSH, VPN, or RDP gateway authentication attempts from external IPs → subsequent successful logon → remote shell or lateral movement activity (e.g., scp/sftp).', '{Linux}', 'x-mitre-analytic--a3bca3ec-fd25-4b9d-bbce-9575ba96b8ef', 'DET0354', '[{"name": "auditd:SYSCALL", "channel": "ssh logins or execve of remote commands", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "NSM:Connections", "channel": "Failed password or accepted password for SSH users", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "connection: Inbound connections to SSH or VPN ports", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "KnownSSHClients", "description": "Legitimate IPs or client fingerprints for SSH/VPN."}, {"field": "FailedLogonThreshold", "description": "Number of failed SSH logins to trigger alert."}, {"field": "TimeWindow", "description": "Correlation window for failed attempts and success."}]', '2026-05-01 15:26:36.066532');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1141, 'AN1387', 'Analytic 1387', 'Abuse of VMFS or ESXi shell to hide datastore files, renaming/moving VMDK or VMX files into hidden directories. Defender view: anomalous ESXi shell commands or file operations obscuring VM artifacts.', '{ESXi}', 'x-mitre-analytic--a3c087a6-b7dc-464f-9e84-278bf3076ed1', 'DET0502', '[{"name": "esxi:shell", "channel": "mv, rename, or chmod commands moving VM files into hidden directories", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:syslog", "channel": "Datastore file hidden or renamed unexpectedly", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "VMFileScope", "description": "Restrict to VMDK, VMX, or log files critical for VM operations."}]', '2026-05-01 15:26:36.067907');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1142, 'AN1296', 'Analytic 1296', 'Unsigned or suspicious applications initiating network traffic claiming to be browser, mail, or cloud clients. Detects impersonation via TLS fingerprint and User-Agent string deviation.', '{macOS}', 'x-mitre-analytic--a4119120-396e-4993-8f9d-bc7b5fc94e7e', 'DET0470', '[{"name": "macos:unifiedlog", "channel": "Outbound Traffic", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "macos:osquery", "channel": "Process Execution + Hash", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "NSM:Content", "channel": "HTTP Header Metadata", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ParentProcessFilter", "description": "Limit detections to children of suspicious binaries."}, {"field": "HeaderAnomalyScore", "description": "Threshold for deviation from expected headers (User-Agent, Host)."}]', '2026-05-01 15:26:36.069258');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1143, 'AN1072', 'Analytic 1072', 'Adversary use of bash/zsh or AppleScript to locate files and exfil targets like user keychains or documents.', '{macOS}', 'x-mitre-analytic--a48f36c7-e946-4270-ae23-1a2e52ae2e24', 'DET0380', '[{"name": "macos:unifiedlog", "channel": "process:spawn", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "read/write", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "UserContext", "description": "Useful for excluding known admin or scheduled jobs."}, {"field": "TargetVolume", "description": "Focus monitoring on removable drives or external paths."}]', '2026-05-01 15:26:36.070488');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1144, 'AN0220', 'Analytic 0220', 'Adversary exploits Apache/Nginx/app servers. Chain: (1) suspicious requests in access logs → (2) spike of 5xx or WAF blocks → (3) web server or interpreter (apache2/nginx/php-fpm/node/python) spawns /bin/sh, curl, wget, socat, or writes webshell → (4) outbound callback.', '{Linux}', 'x-mitre-analytic--a4ce8f28-db09-4b0d-bb8d-a77ba3cef3c0', 'DET0080', '[{"name": "ApplicationLog:WebServer", "channel": "/var/log/httpd/access_log, /var/log/apache2/access.log, /var/log/nginx/access.log with exploit indicators and burst errors", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "HTTP payloads with SQLi/LFI/JNDI/deserialization indicators", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "WebProcList", "description": "server/interpreter names to watch (apache2, httpd, nginx, php-fpm, uwsgi, gunicorn, node)."}, {"field": "ChildToolList", "description": "post-exploitation binaries (sh, bash, curl, wget, python, perl, socat, nc)."}, {"field": "BurstThreshold", "description": "Rate of errors/requests per src_ip/uri to flag reconnaissance/exploit spray."}, {"field": "TimeWindow", "description": "Exec/network correlation window."}]', '2026-05-01 15:26:36.071878');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1145, 'AN1377', 'Analytic 1377', 'Creation of outbound connections on alternate ports or using covert transport (e.g., ICMP, DNS) from non-network-intensive processes, following known disruption or blocked traffic.', '{Linux}', 'x-mitre-analytic--a50c90f1-51b1-4948-8945-4b89735d4750', 'DET0499', '[{"name": "auditd:SYSCALL", "channel": "outbound connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "alternate ports", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ProtocolType", "description": "Can filter for rare fallback channel types (e.g., ICMP, DNS over HTTP)."}, {"field": "UserContext", "description": "Tuning by user (e.g., root vs. service account) helps suppress noise."}]', '2026-05-01 15:26:36.073531');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1146, 'AN0772', 'Analytic 0772', 'Behavioral chain of a user being granted elevated privileges or roles in Entra ID or Okta following suspicious login or account creation activity.', '{"Identity Provider"}', 'x-mitre-analytic--a52321d0-5961-497b-8212-61602e05420b', 'DET0277', '[{"name": "m365:audit", "channel": "Add member to role, Add app role assignment", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "AdminRoleThreshold", "description": "Number of accounts allowed to hold sensitive roles like Global Admin"}, {"field": "RoleAssignmentMethod", "description": "Mechanism by which role was added (PowerShell, API, UI)"}, {"field": "GrantContext", "description": "Expected user-to-role mapping defined by org policy"}]', '2026-05-01 15:26:36.075284');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1147, 'AN0058', 'Analytic 0058', 'Inbound binary payloads transferred over HTTP/S with compressed or encoded headers, lacking signature markers or metadata indicative of compiler/toolchain.', '{"Network Devices"}', 'x-mitre-analytic--a53e2979-2c41-44bc-b46e-13a19305e00d', 'DET0019', '[{"name": "NSM:Flow", "channel": "http.log, files.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MIMEType", "description": "Tune for octet-stream or mismatched Content-Type headers"}, {"field": "PayloadSize", "description": "Payload threshold for executable-sized artifacts"}, {"field": "TransferEncoding", "description": "Suspicious base64 or chunked encoding not matching normal app behavior"}]', '2026-05-01 15:26:36.077795');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1173, 'AN0970', 'Analytic 0970', 'Kernel or userland processes generating high-rate network traffic (ICMP, UDP, TCP SYN) beyond expected interface throughput or user behavior norms.', '{Linux}', 'x-mitre-analytic--a94c1081-d66b-4009-95a9-247721fcd394', 'DET0343', '[{"name": "auditd:SYSCALL", "channel": "connect or sendto system call with burst pattern", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SyscallBurstCount", "description": "Threshold of repeated socket calls within a short interval indicating flood behavior."}, {"field": "UserContext", "description": "Restrict to non-admin user traffic unless elevated access is detected."}]', '2026-05-01 15:26:36.115766');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1148, 'AN0222', 'Analytic 0222', 'Adversary exploits containerized app via ingress or service. Chain: (1) suspicious request in ingress/app logs → (2) container process spawns a shell/exec/sidecar (kubectl exec/docker exec) → (3) egress to Internet or metadata service (169.254.169.254).', '{Containers}', 'x-mitre-analytic--a57ad75c-331e-4607-b358-61f4cddb8a5d', 'DET0080', '[{"name": "ApplicationLog:Ingress", "channel": "Kubernetes NGINX/Envoy ingress controller logs with anomalous payloads and 5xx spikes", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "docker:events", "channel": "Docker/Kubernetes audit of exec/attach (kubectl exec) or unexpected child processes inside container", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Requests towards cloud metadata or command & control from pod IPs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "IngressNamespaces", "description": "Namespaces that are Internet-facing."}, {"field": "MetadataEndpoints", "description": "Cloud metadata IPs/hostnames for exfil of credentials."}, {"field": "TimeWindow", "description": "Join period between ingress request and pod exec/egress."}]', '2026-05-01 15:26:36.079562');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1149, 'AN1220', 'Analytic 1220', 'Execution of SyncAppvPublishingServer.vbs through wscript.exe with a command-line containing embedded PowerShell, proxying malicious PowerShell execution through a Microsoft-signed VBScript interpreter to evade detection and restrictions.', '{Windows}', 'x-mitre-analytic--a59042de-ecac-45bf-a852-af3df41b86d8', 'DET0440', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "CommandLineRegex", "description": "Detects embedded PowerShell commands in SyncAppvPublishingServer.vbs invocation, e.g., `{powershell -nop -enc ...}`"}, {"field": "ScriptInterpreter", "description": "May vary between `wscript.exe`, `cscript.exe`, or called via `cmd.exe`"}, {"field": "PowerShellObfuscationScore", "description": "Used to detect encoding, obfuscation, or entropy level in embedded PowerShell payloads"}, {"field": "TimeWindow", "description": "Time delta between VBScript proxy invocation and PowerShell payload execution"}]', '2026-05-01 15:26:36.081172');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1150, 'AN0257', 'Analytic 0257', 'Adversary executes CLI commands like `show users`, `show ssh`, or attempts to dump AAA user lists from routers or switches.', '{"Network Devices"}', 'x-mitre-analytic--a5cc0eac-af18-4fe2-ac06-88a5cfddf014', 'DET0093', '[{"name": "networkdevice:syslog", "channel": "aaa privilege_exec", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "networkdevice:syslog", "channel": "eventlog", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CLICommandBaseline", "description": "Expected command set per device role/user role combination"}, {"field": "DeviceRoleSensitivity", "description": "Correlate access with core vs. edge vs. management plane sensitivity"}, {"field": "CommandFrequencyThreshold", "description": "Detect burst usage of `show` or `debug` commands by non-admin users"}]', '2026-05-01 15:26:36.08273');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1151, 'AN1028', 'Analytic 1028', 'Abuse of Regsvcs.exe or Regasm.exe to execute arbitrary code embedded in .NET assemblies via [ComRegisterFunction]/[ComUnregisterFunction]. Behavioral chain: (1) Process creation of regsvcs/regasm with suspicious assembly paths/flags → (2) Assembly/DLL load inside regsvcs/regasm → (3) Registry writes to HKCR\CLSID/ProgID during COM registration → (4) Optional child process or network activity spawned by installer/registration code.', '{Windows}', 'x-mitre-analytic--a5e9fb06-ab75-415d-beff-206aa059e096', 'DET0361', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AssemblyPathRegex", "description": "Environment-specific paths to flag (e.g., %TEMP%, Downloads, OneDrive, SMB shares). Helps suppress known-good installers."}, {"field": "SuspiciousFlags", "description": "Arguments like /unregister (/u), /codebase, /regfile which may indicate abuse. Tune per enterprise use of regasm/regsvcs."}, {"field": "ParentProcessAllowList", "description": "Legitimate parents (e.g., setup.exe, msiexec.exe). Analyst can prune false positives from Office or script hosts."}, {"field": "KnownGoodAssemblies", "description": "Hashes or publisher info for approved assemblies commonly registered in the environment."}, {"field": "RegistryKeyAllowList", "description": "Approved CLSIDs/ProgIDs written during sanctioned software installs."}, {"field": "TimeWindow", "description": "Correlation window (e.g., 5–10 min) between file drop → regasm/regsvcs exec → registry writes → child activity."}, {"field": "SignedToUnsignedTransition", "description": "Alert if Microsoft-signed regasm/regsvcs loads or triggers unsigned assemblies/children."}]', '2026-05-01 15:26:36.084071');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1152, 'AN1388', 'Analytic 1388', 'Malicious macros or embedded objects hidden within Office documents by renaming streams or using hidden OLE objects. Defender view: detection of hidden macro streams or objects in documents correlated with anomalous execution.', '{"Office Suite"}', 'x-mitre-analytic--a6299804-cf50-4496-a242-1394ff89c147', 'DET0502', '[{"name": "m365:unified", "channel": "Detection of hidden macro streams or SetHiddenAttribute actions", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MacroScope", "description": "Tune detection to specific Office apps and document types where macros are disallowed."}]', '2026-05-01 15:26:36.085586');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1153, 'AN0318', 'Analytic 0318', 'Detects enumeration of local groups using common binaries (groups, getent, cat /etc/group) or scripting with suspicious lineage.', '{Linux}', 'x-mitre-analytic--a62a2b36-00e9-481c-9a3a-14c14cd42dae', 'DET0114', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ProcessName", "description": "Detection tuning for binaries like `groups`, `getent`, `awk`, or `cut` that may be used in pipelines."}, {"field": "ParentProcess", "description": "Used to determine whether enumeration was triggered by a script or terminal."}]', '2026-05-01 15:26:36.086792');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1154, 'AN2016', 'Analytic 2016', 'Much of this takes place outside the visibility of the target organization, making detection difficult for defenders. 
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1194, 'AN1998', 'Analytic 1998', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.', '{PRE}', 'x-mitre-analytic--ac4bf64e-da14-4416-8961-f0736eb4d9be', 'DET0866', NULL, NULL, '2026-05-01 15:26:36.146308');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1155, 'AN0153', 'Analytic 0153', 'Detection of unauthorized modifications to Windows root certificate stores by monitoring registry keys, certificate installation processes, and creation of new certificate entries not in baseline trusted lists.', '{Windows}', 'x-mitre-analytic--a65545d7-fa1b-4d6f-b19c-fa03862c6210', 'DET0056', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TrustedRootHashList", "description": "Baseline list of root certificate hashes; defenders can tune based on organizational certificate policies."}, {"field": "MonitoredProcesses", "description": "Processes associated with certificate management that should be flagged if executed by non-admin users or in unusual contexts."}, {"field": "TimeWindow", "description": "Correlation window for registry modifications, certificate installation, and process creation to strengthen detection."}]', '2026-05-01 15:26:36.089264');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1156, 'AN0881', 'Analytic 0881', 'Office application auto-loads a non-standard DLL during startup triggered via Office Test Registry key, often without macro warning banners. DLL persistence mechanism circumvents traditional macro defenses.', '{"Office Suite"}', 'x-mitre-analytic--a677cebe-06e8-4993-bd4c-6a6884862444', 'DET0315', '[{"name": "m365:unified", "channel": "Non-standard Office startup component detected (e.g., unexpected DLL path)", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "m365:office", "channel": "Startup execution includes non-default component", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TrustedLocationBypass", "description": "DLL may be placed in location trusted by Office configuration or signed to evade alerts"}, {"field": "AuditPolicyScope", "description": "Only specific tenants or users may have Office auditing enabled at granular DLL load level"}]', '2026-05-01 15:26:36.090825');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1157, 'AN1164', 'Analytic 1164', 'Detects AppleScript execution via ''osascript'', NSAppleScript/OSAScript APIs, and abnormal application control events across user sessions. Focuses on causal chains such as osascript spawning child processes, script-induced keystrokes, or API-backed dialog spoofing.', '{macOS}', 'x-mitre-analytic--a67ac8ec-2748-4fe6-8dd7-bd570af1e104', 'DET0414', '[{"name": "macos:unifiedlog", "channel": "process: spawn, exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ScriptInvocationParent", "description": "Identify rare or suspicious parent processes launching AppleScript (e.g., Safari, Mail, msedge)."}, {"field": "TimeWindow", "description": "Flag AppleScript execution during user-inactive hours, especially for automation frameworks."}, {"field": "AppleEventActionType", "description": "Filter AppleEvent-based automation involving UI interaction, keystrokes, or remote control."}, {"field": "TargetApplicationSet", "description": "Scope AppleScript use toward security-sensitive apps (e.g., Terminal, ssh, Keychain Access)."}, {"field": "ExecutionPathRegex", "description": "Restrict to unusual paths like /tmp/, ~/Library/, or embedded in Automator workflows."}]', '2026-05-01 15:26:36.09235');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1158, 'AN1024', 'Analytic 1024', 'Encrypted traffic or ICMP tunneling from border routers to internal routers or unknown external IPs. Forwarded traffic shows consistent hop-to-hop relaying without matching configured VPN or expected network topology.', '{"Network Devices"}', 'x-mitre-analytic--a691ee45-94bf-4244-a286-b80c21859d2e', 'DET0359', '[{"name": "NSM:Flow", "channel": "Relayed session pathing (multi-hop)", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Firewall", "channel": "Outbound encrypted traffic", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "networkdevice:syslog", "channel": "Custom firmware or routing changes", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}]', '[{"field": "VPNConfigWhitelist", "description": "Define allowed internal router communication paths."}, {"field": "ICMPPayloadEntropy", "description": "High entropy ICMP payloads may indicate tunneling activity."}, {"field": "RelayChainSignature", "description": "Track known multi-hop pattern signatures or port hopping techniques."}]', '2026-05-01 15:26:36.094674');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1159, 'AN1480', 'Analytic 1480', '1) New or updated software is delivered/installed from atypical sources or with signature/hash mismatches; 2) installer/updater writes binaries to unexpected paths or replaces existing signed files; 3) first run causes unsigned/abnormally signed modules to load or child processes to execute, optionally followed by network egress to new destinations.', '{Windows}', 'x-mitre-analytic--a6b1e74e-6c05-4d9f-928c-63ddf558798b', 'DET0537', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "channel": "CodeIntegrity reports ''Invalid image hash'' or ''Unsigned image'' for new/updated binaries", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "NSM:Flow", "channel": "First-time egress from host after new install to unknown update endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "Correlation window between install events and first-run activity (default 2h; adjust for staged rollouts)."}, {"field": "TrustedPublishers", "description": "Publisher/Signer allow-list to suppress expected updates."}, {"field": "TrustedUpdateHosts", "description": "Known update CDNs/APIs (e.g., download.microsoft.com) to reduce egress false positives."}, {"field": "RiskScoreThreshold", "description": "Score cut-off for alerting when combining path, signer, and reputation features."}]', '2026-05-01 15:26:36.09656');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1165, 'AN1233', 'Analytic 1233', 'Dynamic or static port forwarding rules added to route traffic through an internal host, or configuration changes to proxy firewall rules not aligned with baselined policy.', '{"Network Devices"}', 'x-mitre-analytic--a79ae1d1-1a8d-427d-aa6d-261ea63d5650', 'DET0445', '[{"name": "NSM:Firewall", "channel": "Policy Change / Rule Update", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"name": "NSM:Flow", "channel": "Flow Creation (NetFlow/sFlow)", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "networkdevice:cli", "channel": "Interface commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "RuleType", "description": "Focus on new allow/permit rules with dynamic NAT or port forwarders."}, {"field": "ChangeUser", "description": "Flag any non-admins initiating proxy config changes."}, {"field": "FlowVolumeDelta", "description": "Detect sharp changes in bi-directional traffic patterns."}]', '2026-05-01 15:26:36.104205');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1160, 'AN1315', 'Analytic 1315', 'Cause→effect chain: (1) User app/browser/archiver logs an open/click or abnormal exit, (2) new executable/script/archive extracted into $HOME/Downloads, /tmp, or ~/.cache, (3) parent app spawns shell/interpreter (bash/sh/python/node/curl/wget) or desktop file, and (4) new outbound connection(s) from the child lineage.', '{Linux}', 'x-mitre-analytic--a6e7697d-f0b8-4fcc-b32a-fec5b28cd8f7', 'DET0478', '[{"name": "linux:syslog", "channel": "opened document|clicked link|segfault|abnormal termination|sandbox", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "creat", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "rename,chmod", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "new outbound connection from browser/office lineage", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "5–20 minute correlation window."}, {"field": "UserPaths", "description": "$HOME/Downloads, /tmp, ~/.cache, ~/.config/autostart, ~/.local/share."}, {"field": "HighRiskChildren", "description": "bash, sh, zsh, python*, perl, node, curl, wget, xdg-open, kde-open, gio open, unzip/tar extraction leading to exec."}, {"field": "PkgUpdaters", "description": "Allow-list snap/flatpak/packagekit/apt workers to reduce false positives."}]', '2026-05-01 15:26:36.097792');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1161, 'AN1571', 'Analytic 1571', 'Unusual processes (e.g., powershell.exe, excel.exe) accessing large local files and subsequently initiating HTTPS POST requests to domains associated with cloud storage services (e.g., dropbox.com, drive.google.com, box.com). Defender perspective: correlation between file reads in sensitive directories and high outbound traffic volume to known storage APIs.', '{Windows}', 'x-mitre-analytic--a74c34c2-f4bf-4bd0-9f23-7c04c45b93ca', 'DET0570', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CloudStorageDomains", "description": "List of monitored domains for cloud services (dropbox.com, drive.google.com, onedrive.live.com)."}, {"field": "ExfilVolumeThreshold", "description": "Data volume threshold (e.g., >10MB in single session) used to flag abnormal transfers."}, {"field": "UserContext", "description": "User accounts permitted to use sanctioned cloud services versus unexpected accounts."}]', '2026-05-01 15:26:36.099191');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1162, 'AN0331', 'Analytic 0331', 'Detects execution of image viewers or PowerShell scripts accessing or decoding files with mismatched MIME headers or embedded script-like byte patterns; often correlated with suspicious parent-child process lineage and outbound connections.', '{Windows}', 'x-mitre-analytic--a7666a4d-ece8-4e5b-ae85-d2987f14b950', 'DET0119', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ParentProcessImage", "description": "Tune to identify image editors/viewers invoking script interpreters (e.g., `mspaint.exe` > `powershell.exe`)"}, {"field": "MimeHeaderMismatchTolerance", "description": "Adjust tolerance for image file headers that do not match file extensions or content structure"}, {"field": "TimeWindow", "description": "Define the temporal range to correlate decoding → execution → network beaconing"}]', '2026-05-01 15:26:36.100417');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1163, 'AN0801', 'Analytic 0801', 'Cloud API events where logging services are stopped, deleted, or modified in a way that disables audit visibility. Defender view: unauthorized StopLogging, DeleteTrail, or UpdateSink operations correlated with privileged user activity.', '{IaaS}', 'x-mitre-analytic--a788e3ed-8faf-4443-bb26-fd530ca930d1', 'DET0289', '[{"name": "AWS:CloudTrail", "channel": "Stop logging for an existing CloudTrail", "x_mitre_data_component_ref": "x-mitre-data-component--ec0612c5-2644-4c50-bcac-82586974fedd"}, {"name": "gcp:config", "channel": "UpdateSink request modifying log export destinations", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "AdminRoles", "description": "Define which roles are authorized to stop or modify logging."}, {"field": "RegionScope", "description": "Adjust monitoring to ensure multi-region logging tampering is caught."}]', '2026-05-01 15:26:36.101813');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1164, 'AN0741', 'Analytic 0741', 'Persistent high CPU utilization combined with suspicious command-line execution (e.g., mining tools or obfuscated scripts) and outbound connections to mining/proxy networks.', '{Windows}', 'x-mitre-analytic--a789e535-cab9-49b4-9685-c10a5d3642b4', 'DET0267', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "Windows:perfmon", "channel": "High sustained CPU usage by a single process", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Duration threshold for sustained CPU activity (e.g., >15 minutes)"}, {"field": "DestinationIPList", "description": "Known mining pool IPs or proxy service endpoints"}, {"field": "ExecutableNamePatterns", "description": "Regex list of suspicious or known mining tools"}]', '2026-05-01 15:26:36.103014');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1166, 'AN0894', 'Analytic 0894', 'Disabling of security macros or safe mode settings within Word/Excel/Outlook. Detect registry edits or configuration file changes that weaken macro enforcement.', '{"Office Suite"}', 'x-mitre-analytic--a807fb55-1c4f-4353-90d6-1a05aa05f2c9', 'DET0317', '[{"name": "m365:unified", "channel": "MacroSecuritySettingsChanged or SafeModeDisabled", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "ApplicationScope", "description": "Specify which Office applications are monitored for macro security configuration changes."}]', '2026-05-01 15:26:36.105705');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1167, 'AN0645', 'Analytic 0645', 'Detects adversarial abuse of systemd timers by correlating file creation/modification of .timer and .service units in system directories with the execution of abnormal child processes launched by ''systemd'' (PID 1), especially as root.', '{Linux}', 'x-mitre-analytic--a80f58c9-deb2-45ed-a8fb-4f3df5082874', 'DET0231', '[{"name": "auditd:SYSCALL", "channel": "creat, open, write on /etc/systemd/system and /usr/lib/systemd/system", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "execve logging for /usr/bin/systemctl and systemd-run", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}]', '[{"field": "TimerIntervalThreshold", "description": "The interval threshold used to determine if a newly created timer is unusually frequent or immediate (e.g., < 5 minutes)."}, {"field": "ParentProcessID", "description": "Whether the child process has a parent PID of 1, indicating systemd as the invoker. Can be tuned to include known benign cases."}, {"field": "UserContext", "description": "User under which the timer/service is created or executed (e.g., root vs. non-root)."}, {"field": "TimerCreationPath", "description": "The path where the timer or service file is created; system-wide vs. user space can be scoped."}]', '2026-05-01 15:26:36.107374');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1168, 'AN0948', 'Analytic 0948', 'Detects anomalous use of macOS XPC services for code execution. Monitors for processes invoking privileged XPC daemons with abnormal parameters, unexpected binaries communicating over NSXPCConnection, or helper tools executing code outside of their expected parent process lineage. Correlates process access attempts to system-level daemons, privilege escalations via XPC misconfigurations, and injection of malicious payloads through inter-process communication.', '{macOS}', 'x-mitre-analytic--a8284241-0d8e-42da-b86d-48f0d660df6c', 'DET0335', '[{"name": "macos:unifiedlog", "channel": "Unexpected NSXPCConnection calls by non-Apple-signed or abnormal binaries", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "macos:unifiedlog", "channel": "execve: Helper tools invoked through XPC executing unexpected binaries", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "XPC messages requesting privileged actions from untrusted or unsigned clients", "x_mitre_data_component_ref": "x-mitre-data-component--b9a1578e-8653-4103-be23-cb52e0b1816e"}]', '[{"field": "AllowedXPCClients", "description": "Maintain allowlist of binaries permitted to invoke specific XPC services to minimize false positives."}, {"field": "TimeWindow", "description": "Threshold for correlating abnormal XPC requests with subsequent privilege escalation or process creation."}, {"field": "UnsignedBinaryAlertLevel", "description": "Adjust sensitivity of alerts for unsigned or non-Apple-signed clients initiating XPC communication."}]', '2026-05-01 15:26:36.108982');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1169, 'AN0971', 'Analytic 0971', 'Excessive outbound traffic via `ping`, `curl`, or custom scripts indicating flooding behavior, especially with no UI context or user interaction.', '{macOS}', 'x-mitre-analytic--a82a14f4-6fc9-43b5-b183-68af3cb075a2', 'DET0343', '[{"name": "macos:unifiedlog", "channel": "process created with repeated ICMP or UDP flood behavior", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "sudden burst in outgoing packets from same PID", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "BurstTimeWindow", "description": "Tunable range (e.g., 15s, 30s) for detecting packet floods."}]', '2026-05-01 15:26:36.110289');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1170, 'AN1285', 'Analytic 1285', 'Use of known default service accounts or root-level cloud accounts performing authentication or changes to IAM policy.', '{"Identity Provider"}', 'x-mitre-analytic--a8ed4e86-c79a-40db-84e5-1b4cf0e917d3', 'DET0465', '[{"name": "AWS:CloudTrail", "channel": "ConsoleLogin or AssumeRole", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AccountList", "description": "Organizations may rename or rotate default IAM accounts; detection logic should be updated with any renamed or aliased default identities."}, {"field": "GeoLocation", "description": "Authentication attempts from unusual geographic regions should trigger anomaly detection."}]', '2026-05-01 15:26:36.11154');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1171, 'AN0481', 'Analytic 0481', 'Defenders should monitor for suspicious enumeration of cloud infrastructure components via APIs or CLI tools. Observable behaviors include repeated listing or description operations for compute instances, snapshots, storage buckets, and volumes. From a defender’s perspective, risky activity is often identified by new or untrusted identities making discovery calls (e.g., DescribeInstances, ListBuckets, az vm list, gcloud compute instances list), enumeration from unusual geolocations or IPs, or rapid multi-service discovery in sequence. Correlating discovery API usage with later snapshot creation or instance modification provides further context of adversary behavior.', '{IaaS}', 'x-mitre-analytic--a9372c6a-8d3b-420a-ad9d-8ef8d284205f', 'DET0169', '[{"name": "AWS:CloudTrail", "channel": "DescribeInstances", "x_mitre_data_component_ref": "x-mitre-data-component--45fd904d-6eb0-4b50-8478-a961f09f898b"}, {"name": "AWS:CloudTrail", "channel": "ListBuckets", "x_mitre_data_component_ref": "x-mitre-data-component--fcc4811f-9cc8-4db5-8097-4d8242a380de"}, {"name": "AWS:CloudTrail", "channel": "DescribeDBInstances", "x_mitre_data_component_ref": "x-mitre-data-component--2a80d95f-08c4-48e3-833e-151ef19d90f5"}]', '[{"field": "UserContext", "description": "Identity performing the discovery operation; tuned to filter known administrative or inventory accounts."}, {"field": "GeoLocation", "description": "Source region or IP of discovery requests; tuned to expected operational regions to detect unusual access."}, {"field": "TimeWindow", "description": "Correlation period to link enumeration calls with subsequent provisioning or exfiltration activity."}, {"field": "APIThreshold", "description": "Rate or volume of discovery calls; tuned to suppress noise from inventory management tools."}]', '2026-05-01 15:26:36.112905');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1172, 'AN0335', 'Analytic 0335', 'Password changes or account deletions via ''passwd'', ''userdel'', or ''chage'' preceded by interactive shell or remote command execution from non-privileged accounts.', '{Linux}', 'x-mitre-analytic--a941dd04-5626-4091-9eed-300d7d7f0a1f', 'DET0120', '[{"name": "auditd:SYSCALL", "channel": "SYSCALL record where exe contains passwd/userdel/chage and auid != root", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "Accepted password or publickey for user from remote IP", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "ExecPath", "description": "Binary path for passwd or userdel, which may vary by distro"}, {"field": "NonRootUIDThreshold", "description": "Alert only if auid != root or expected service account"}]', '2026-05-01 15:26:36.114304');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1174, 'AN0176', 'Analytic 0176', 'Unquoted service or shortcut paths that contain spaces and allow path interception by higher-level executables. Defender observes registry service configurations with unquoted paths, file creation of executables in parent directories of unquoted paths, and subsequent process execution from unexpected locations.', '{Windows}', 'x-mitre-analytic--a972f507-cf1b-4e2f-acdc-877a7891b7cf', 'DET0064', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "MonitoredServices", "description": "List of critical services to check for unquoted paths in ImagePath registry keys."}, {"field": "SuspiciousBinaryList", "description": "Executables with names matching potential interception targets (e.g., program.exe, net.exe)."}, {"field": "TimeWindow", "description": "Correlation interval between file creation in parent directories and execution of unquoted path process."}, {"field": "BaselineServiceConfig", "description": "Known good service paths for comparison against modified or unquoted values."}]', '2026-05-01 15:26:36.117057');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1175, 'AN1353', 'Analytic 1353', 'Suspicious enumeration of attached peripherals via WMI, PowerShell, or low-level API calls potentially chained with removable device interactions.', '{Windows}', 'x-mitre-analytic--a986c8fd-6779-4769-895a-e6d167d9f1a9', 'DET0491', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "CommandLineRegex", "description": "Regex patterns for device enumeration utilities (e.g., ''Get-PnpDevice'', ''wmic path Win32_USBController'')"}, {"field": "TimeWindow", "description": "Time threshold for grouping device discovery with follow-on access or manipulation"}, {"field": "UserContext", "description": "Filter privileged or service accounts known to legitimately execute enumeration scripts"}]', '2026-05-01 15:26:36.118378');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1176, 'AN0538', 'Analytic 0538', 'Disk enumeration via `diskutil list` or `system_profiler SPStorageDataType` run outside of user login or not associated with system inventory tools', '{macOS}', 'x-mitre-analytic--a98fc9c5-9c4c-47c5-a773-d68b523c7304', 'DET0188', '[{"name": "macos:unifiedlog", "channel": "process launch of diskutil or system_profiler with SPStorageDataType", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "log messages related to disk enumeration context or Terminal session", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "launch_agent_context", "description": "Unexpected use of disk enumeration tools from GUI apps or LaunchAgents may indicate abuse"}, {"field": "volume_name_filter", "description": "Filter known baseline volume names or identifiers used by common device configurations"}]', '2026-05-01 15:26:36.11961');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1177, 'AN1939', 'Analytic 1939', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1178, 'AN1099', 'Analytic 1099', 'Monitor for runtime manipulation by observing changes in application bundles, unexpected signing modifications, and runtime API calls that inject or alter how data is displayed. Detect alterations in CFNetwork or CoreFoundation frameworks responsible for rendering data.', '{macOS}', 'x-mitre-analytic--a9c30b9d-6810-47d3-8bf5-ca787836e7ef', 'DET0391', '[{"name": "macos:unifiedlog", "channel": "Unexpected application binary modifications or altered signing status", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:osquery", "channel": "CALCULATE: Mismatch in file integrity of critical macOS applications", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "AllowedApps", "description": "Whitelisted applications expected to handle sensitive runtime data."}, {"field": "SignatureEnforcement", "description": "Policy enforcement for validating application code signing integrity."}]', '2026-05-01 15:26:36.122101');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1179, 'AN0764', 'Analytic 0764', 'Correlation of registry key modification for Run/RunOnce with abnormal parent-child process relationships and outlier execution at user logon or system startup', '{Windows}', 'x-mitre-analytic--aa12f037-f724-43a6-97ca-e2e706859c1a', 'DET0274', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "ParentProcessName", "description": "Customize based on expected parent-child process lineage for autostarts"}, {"field": "StartupRegistryPath", "description": "May vary based on organization policy or installed software"}]', '2026-05-01 15:26:36.123709');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1180, 'AN1546', 'Analytic 1546', 'Detection of valid account abuse in IdP logs via geographic anomalies, impossible travel, risky sign-ins, and multiple MFA attempts or failures.', '{"Identity Provider"}', 'x-mitre-analytic--aa255cdc-0b49-4ad3-951d-eab5582da56f', 'DET0560', '[{"name": "saas:okta", "channel": "Sign-in logs / audit events", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "MFAFailureCount", "description": "Threshold of failed MFA attempts before alerting."}, {"field": "RiskScoreThreshold", "description": "Custom threshold based on calculated identity risk."}, {"field": "IPGeoVelocity", "description": "Detect impossible travel (logins from two distant geolocations within short time)."}]', '2026-05-01 15:26:36.125215');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1195, 'AN0891', 'Analytic 0891', 'Cloud control plane actions disabling security services (CloudTrail logging, GuardDuty, Security Hub). Detect IAM role abuse correlating with service disable events.', '{IaaS}', 'x-mitre-analytic--ac692681-2851-41b4-aff9-4b5efc4c40c8', 'DET0317', '[{"name": "AWS:CloudTrail", "channel": "StopLogging, DeleteTrail, or DisableSecurityService", "x_mitre_data_component_ref": "x-mitre-data-component--ec0612c5-2644-4c50-bcac-82586974fedd"}]', '[{"field": "ServiceScope", "description": "Specify which cloud services (logging, monitoring, threat detection) must never be disabled."}]', '2026-05-01 15:26:36.147658');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1181, 'AN1015', 'Analytic 1015', 'Execution of utilities (e.g., ping, tracert, Test-NetConnection) or scripted methods to test Internet connectivity by interacting with external IPs/domains.', '{Windows}', 'x-mitre-analytic--aa2dc7aa-0cc5-4a75-96b2-8c089c46944b', 'DET0357', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Security", "channel": "EventCode=5156, 5157", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "DestinationIP", "description": "Tunable external IP ranges or domains used to verify Internet access (e.g., 8.8.8.8, example.com)"}, {"field": "TimeWindow", "description": "Cluster rapid test connections with command execution in < 60 seconds"}, {"field": "UserContext", "description": "Filter out known admin/script contexts to reduce false positives"}]', '2026-05-01 15:26:36.126639');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1182, 'AN1433', 'Analytic 1433', 'Detection focuses on unauthorized manipulation of .NET AppDomainManager behavior. Defenders may observe suspicious creation of new AppDomains within trusted processes, anomalous loading of assemblies via non-standard configuration files, or registry/environment variable changes redirecting AppDomainManager to malicious assemblies. Correlated events include config file tampering, new process creation of .NET host processes (e.g., w3wp.exe, powershell.exe) with modified runtime parameters, and module loads of unusual or unsigned .NET DLLs.', '{Windows}', 'x-mitre-analytic--aa3484d0-d7ae-40e2-8a44-6b963883a35d', 'DET0517', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TargetProcesses", "description": "List of monitored .NET host processes (e.g., powershell.exe, w3wp.exe, svchost.exe)."}, {"field": "AssemblyWhitelist", "description": "Known benign .NET assemblies expected to load via AppDomainManager."}, {"field": "ConfigFilePaths", "description": "Directory paths where configuration tampering should be monitored (application directories, system32, program files)."}, {"field": "TimeWindow", "description": "Correlation period between file modification of config/environment settings and subsequent anomalous module load."}]', '2026-05-01 15:26:36.128127');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1183, 'AN1231', 'Analytic 1231', 'AppleScript, LaunchAgents, or remote login services (`ssh`, `networksetup`) establishing proxy tunnels or dynamic port forwards to external IPs or alternate local hosts.', '{macOS}', 'x-mitre-analytic--aace8c0e-4534-432b-9a84-6e01c19570b7', 'DET0445', '[{"name": "macos:unifiedlog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Firewall", "channel": "pf firewall logs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "connection attempts", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TargetDomain", "description": "Identify suspicious domains often associated with CDN-routed or anonymized endpoints (e.g., Cloudflare, Fastly)."}, {"field": "AppleScriptUsage", "description": "Alert when AppleScript or Automator tools are used for network tunneling tasks."}, {"field": "LaunchAgentSource", "description": "Monitor for LaunchAgents executing proxy tools or dynamic ports."}]', '2026-05-01 15:26:36.129669');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1184, 'AN1587', 'Analytic 1587', 'Execution of discovery commands like `show cdp neighbors`, `show arp`, and other interface-level introspection on Cisco or Juniper devices.', '{"Network Devices"}', 'x-mitre-analytic--aad71d3e-93b0-4cb6-8240-274369f8ad34', 'DET0574', '[{"name": "networkdevice:syslog", "channel": "syslog facility LOCAL7 or trap messages", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandList", "description": "Device-specific recon commands to monitor based on make/model"}, {"field": "PrivLevel", "description": "Trigger detection for privilege escalation prior to recon commands"}]', '2026-05-01 15:26:36.130913');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1185, 'AN1043', 'Analytic 1043', 'Execution of esxcli commands to enumerate datastore, configuration files, or directory structures by unauthorized or remote users.', '{ESXi}', 'x-mitre-analytic--aaddc766-52bb-428b-98c4-3a742d10befa', 'DET0370', '[{"name": "esxi:shell", "channel": "Shell Access/Command Execution", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:hostd", "channel": "vSphere File API Access", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "CLICommandPattern", "description": "Match on esxcli storage|filesystem commands"}, {"field": "AccessSource", "description": "Limit alerting to non-vCenter or remote IPs"}]', '2026-05-01 15:26:36.132253');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1186, 'AN0161', 'Analytic 0161', 'Detection of a process or script that accesses a common web service to retrieve content containing obfuscated indicators of a secondary C2 server (dead drop resolver behavior).', '{ESXi}', 'x-mitre-analytic--aae03a6c-b308-49cb-bb85-7be4a5c2a4bb', 'DET0058', '[{"name": "esxi:vobd", "channel": "Network Events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Firewall", "channel": "Outbound Connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "DestinationIP", "description": "Identifies unusual IP destinations embedded in traffic"}, {"field": "Protocol", "description": "Used to detect uncommon protocols (e.g., DNS over HTTPS)"}, {"field": "TimeWindow", "description": "Used to correlate outbound web requests with process execution"}]', '2026-05-01 15:26:36.133467');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1196, 'AN1451', 'Analytic 1451', 'Crafted ‘synful knock’ patterns toward routers/switches (same src hits interface/broadcast/network address on same port in short order) followed by ACL/telnet/SSH enablement or module change. Detect device image/ACL updates then a new mgmt session.', '{"Network Devices"}', 'x-mitre-analytic--ac933d77-bdb6-45ed-8fb5-87bae6f225cb', 'DET0524', '[{"name": "networkdevice:syslog", "channel": "Config/ACL/line vty changes, service enable (telnet/ssh/http(s)), module reloads", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "Port-knock pattern from one src to device unicast,broadcast,network addresses on same port within TimeWindowKnock", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "MgmtPortSet", "description": "Ports whose sudden enablement should alert (23, 22, 2323, 80/443, 4786)."}, {"field": "DeviceRole", "description": "Applies different thresholds to core/edge/branch devices."}]', '2026-05-01 15:26:36.148845');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1187, 'AN1111', 'Analytic 1111', 'Detects abuse of AuthorizationExecuteWithPrivileges API to gain elevated privileges via user credential prompts, typically through invocation of /usr/libexec/security_authtrampoline. Detection involves correlation of API usage, binary reputation, and prompt context.', '{macOS}', 'x-mitre-analytic--aae53d47-1f26-426b-9e50-848f186fed99', 'DET0395', '[{"name": "macos:unifiedlog", "channel": "Execution of /usr/libexec/security_authtrampoline or child processes originating from non-trusted binaries triggering credential prompts", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Calls to AuthorizationExecuteWithPrivileges() observed via Apple System Logger or security_auditing tools", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "macos:unifiedlog", "channel": "User credential prompt events without associated trusted installer package", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "BinaryReputationList", "description": "Allow list of trusted binaries invoking elevation prompts"}, {"field": "TimeWindow", "description": "Temporal correlation threshold between API call and credential prompt"}, {"field": "PromptContextValidation", "description": "Heuristic filters to determine whether a prompt context matches known legitimate installers"}]', '2026-05-01 15:26:36.13459');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1188, 'AN0177', 'Analytic 0177', 'Defenders may detect abuse of container administration commands by observing anomalous use of management utilities (`docker exec`, `kubectl exec`, or API calls to kubelet) correlated with unexpected process creation inside containers. Behavioral chains include unauthorized API requests followed by command execution within running pods or containers, often originating from unusual user accounts, automation scripts, or IP addresses outside the expected cluster management plane.', '{Containers}', 'x-mitre-analytic--ab1122c5-f459-4097-8ba7-f5a7960d2da5', 'DET0065', '[{"name": "docker:daemon", "channel": "docker exec or docker run with unexpected command/entrypoint", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "kubernetes:apiserver", "channel": "kubectl exec or kubelet API calls targeting running pods", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AuthorizedAdminUsers", "description": "Expected admin accounts allowed to use exec commands; anomalies outside this list indicate possible abuse."}, {"field": "ExecFrequencyThreshold", "description": "Defines how often `docker exec` or `kubectl exec` is normally observed; sudden spikes may indicate adversary behavior."}, {"field": "SourceIPRange", "description": "Expected IP ranges for management actions (e.g., cluster control plane). Requests from external/unexpected ranges may indicate compromise."}, {"field": "NamespaceScope", "description": "Defines which namespaces typically allow exec operations; anomalous activity outside these may indicate lateral movement."}]', '2026-05-01 15:26:36.137473');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1189, 'AN1993', 'Analytic 1993', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Initial Access (ex: [Phishing](https://attack.mitre.org/techniques/T1566)).', '{PRE}', 'x-mitre-analytic--ab74118c-05e1-4acd-b1c2-445d1f7c5fd1', 'DET0861', NULL, NULL, '2026-05-01 15:26:36.138874');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1190, 'AN0967', 'Analytic 0967', 'Detection of xclip or xsel access to clipboard buffers outside of user terminal context, especially when chained to staging (gzip, base64) or network exfiltration (curl, scp).', '{Linux}', 'x-mitre-analytic--ab9a4c72-f7ce-4721-8c9f-c5d9c966b600', 'DET0341', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ClipboardCommand", "description": "Tool used (xclip, xsel, custom clipboard-read binary)."}, {"field": "CorrelationWindow", "description": "Temporal window to chain staging or network activity with clipboard access."}, {"field": "TTYLinked", "description": "Was access linked to interactive user TTY?"}]', '2026-05-01 15:26:36.140558');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1191, 'AN1029', 'Analytic 1029', 'Detection of AppCert DLL abuse involves correlating registry modifications to the AppCertDLLs key with subsequent unexpected DLL load behavior during process creation events. Specifically, defenders can observe abnormal DLLs being loaded into standard Windows processes after changes to the ''AppCertDLLs'' registry value. Monitoring CreateProcess-family API executions with injected DLLs and linking those DLLs back to recent registry edits is key to identifying misuse. This is often accompanied by elevated privileges and potential lateral movement or discovery behavior.', '{Windows}', 'x-mitre-analytic--abe61118-51b2-45ad-93bc-9215dad25b25', 'DET0362', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TargetObject", "description": "Registry path for AppCertDLLs may vary by control set or group policy context"}, {"field": "ImageLoaded", "description": "Loaded DLLs may differ by malware family or environment"}, {"field": "ParentImage", "description": "Parent processes to monitor for DLL injection can be tuned to exclude known-good cases"}, {"field": "TimeWindow", "description": "Time correlation between registry modification and DLL load events may vary"}]', '2026-05-01 15:26:36.142337');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1192, 'AN1239', 'Analytic 1239', 'Account created in a running container (e.g., via ''useradd'' or by modifying /etc/passwd directly). Detectable via runtime telemetry (e.g., Falco or eBPF hooks).', '{Containers}', 'x-mitre-analytic--ac204e03-5c8c-4e29-929c-780145a98669', 'DET0447', '[{"name": "ebpf:syscalls", "channel": "useradd or /etc/passwd modified inside container", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ContainerContext", "description": "Distinguish between ephemeral containers and long-lived service containers"}, {"field": "NamespaceScope", "description": "Determine if account was added inside host, user, or PID namespace"}]', '2026-05-01 15:26:36.143736');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1193, 'AN1505', 'Analytic 1505', 'Detects unexpected access or usage of cloud productivity tools (e.g., downloading large numbers of files, creating external shares) by internal users.', '{SaaS}', 'x-mitre-analytic--ac36f883-9a5b-4796-9f2e-18f1cce8fc0b', 'DET0546', '[{"name": "m365:unified", "channel": "FileAccessed, SharingSet", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "gcp:audit", "channel": "drive.activity", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "FileDownloadThreshold", "description": "Defines excessive access based on number or size of downloads."}, {"field": "SharingPolicyViolationThreshold", "description": "Defines external sharing behaviors that violate policy."}]', '2026-05-01 15:26:36.144978');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1197, 'AN0344', 'Analytic 0344', 'Detects mounting of external volumes followed by high-volume or sensitive file access via Finder, terminal, or third-party apps (e.g., rsync, zip).', '{macOS}', 'x-mitre-analytic--acaabb0b-6cfc-45cd-8bd9-08ad49e1096c', 'DET0123', '[{"name": "macos:unifiedlog", "channel": "Volume Mount + File Read", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "fs:fsusage", "channel": "file system activity monitor", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "VolumeNamePattern", "description": "Detect suspicious or unrecognized drive labels (e.g., UNTITLED, BACKUP_VOL)."}, {"field": "ProcessOrigin", "description": "Detect CLI-based copy operations vs. expected GUI usage."}, {"field": "UserSessionCheck", "description": "Alert if process and session context are mismatched (e.g., script from screensaver context)."}]', '2026-05-01 15:26:36.150054');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1198, 'AN2031', 'Analytic 2031', 'Detection of HTTP outbound requests with inconsistent or spoofed User-Agent headers from command-line tools (e.g., curl, wget, python requests) following interactive user shells or scheduled jobs outside of normal user session behavior.', '{Linux}', 'x-mitre-analytic--acabb18b-e2d6-4531-92bb-4165f0a16595', 'DET0898', '[{"name": "NSM:Flow", "channel": "http.log, conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "auditd:SYSCALL", "channel": "outbound connections", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "HeaderSignatureMatch", "description": "Specific HTTP header anomalies or patterns (e.g., spoofed User-Agent)."}, {"field": "UserAgentFingerprint", "description": "Flag browser-based sessions"}]', '2026-05-01 15:26:36.151483');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1199, 'AN0964', 'Analytic 0964', 'User pastes an obfuscated command into Terminal.app/iTerm2 that decodes or downloads code and executes. Detects Terminal/iTerm2 spawning bash/zsh/python with suspicious pipeline/base64 patterns followed by file writes in ~/Library or /tmp and outbound network connections.', '{macOS}', 'x-mitre-analytic--acf0fdbb-6fbf-42c0-acc4-75a545c24f90', 'DET0340', '[{"name": "macos:unifiedlog", "channel": "exec: ParentImage in (Terminal, iTerm2) AND Image in (/bin/zsh,/bin/bash,/usr/bin/python*) AND CommandLine matches ''(curl|wget).*(\\||\\|\\s*sh|bash)|base64 -D|python -c''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "Interpreter exec with suspicious arguments as above", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "create: New files in /tmp or ~/Library/Application Support/* with executable or script extensions", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Egress to non-approved networks from host after terminal exec", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ParentAppScope", "description": "Terminal apps to treat as user-paste origins (Terminal, iTerm2, VSCode integrated terminal)."}, {"field": "CommandPatternList", "description": "macOS-specific one-liner traits (pbpaste|base64 -D|curl ... | sh)."}, {"field": "AllowListedDevUsers", "description": "Developers/automation accounts expected to run such commands."}]', '2026-05-01 15:26:36.152632');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1200, 'AN0424', 'Analytic 0424', 'Detects file access or compression utilities followed by outbound connections using curl, wget, ftp, or custom binaries communicating over unencrypted protocols.', '{Linux}', 'x-mitre-analytic--ad5fb8d4-7f1c-4442-a4e5-96592364c4cc', 'DET0149', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "http.log, ftp.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "flow records", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "SensitiveDirectoryWatchlist", "description": "Flag access to paths known to store sensitive or regulated data."}, {"field": "ProcessBaseline", "description": "Define which binaries are allowed to communicate externally using HTTP/FTP."}, {"field": "TimeWindow", "description": "Correlates process/file/network within a defined time window."}]', '2026-05-01 15:26:36.153787');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1201, 'AN0336', 'Analytic 0336', 'Execution of dscl or sysadminctl commands to disable, delete, or modify users combined with anomalous process ancestry or terminal session launch.', '{macOS}', 'x-mitre-analytic--adbe8ef2-15e5-4fb9-83d8-4c67b7b1be78', 'DET0120', '[{"name": "macos:unifiedlog", "channel": "command includes dscl . delete or sysadminctl --deleteUser", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "successful sudo or authentication for account not normally associated with admin actions", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "CommandLinePattern", "description": "Allow variation in dscl/sysadminctl command structure"}, {"field": "AnomalousUserFlag", "description": "Detect new or rarely seen users performing user removal"}]', '2026-05-01 15:26:36.154909');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1202, 'AN1167', 'Analytic 1167', 'Repetitive triggering of GUI or backend application workflows that cause increased CPU/memory usage, logged in unified logs as spin reports or crash dumps.', '{macOS}', 'x-mitre-analytic--ade844ef-f156-4db2-bc11-9dbdc006c8d6', 'DET0415', '[{"name": "macos:unifiedlog", "channel": "Application errors or resource contention from excessive frontend or script invocation", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:osquery", "channel": "Rapid spawning of resource-heavy applications (e.g., Preview, Safari, Office)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SpinReportCount", "description": "Threshold for number of system spin/crash reports in a defined window."}, {"field": "HeavyAppReopenRate", "description": "Frequency of user or script reopening GUI-heavy apps."}]', '2026-05-01 15:26:36.156524');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1203, 'AN0984', 'Analytic 0984', 'Detects renamed binaries or scripts placed into trusted paths like /usr/bin or /lib with mismatched metadata or unexpected creation/modification times.', '{Linux}', 'x-mitre-analytic--adf3e421-95ec-4b5a-9c00-0262cb888c0a', 'DET0347', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "rename", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "linux:osquery", "channel": "Filesystem modifications to trusted paths", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "monitored_paths", "description": "Set of system or application directories considered sensitive or trusted"}, {"field": "hash_validation_window", "description": "Timeframe during which a newly created file should have its hash validated (e.g., within 5 minutes of write)"}]', '2026-05-01 15:26:36.158264');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1204, 'AN1105', 'Analytic 1105', 'Multiple AWS CloudTrail events indicating temporary privilege escalation via PassRole and AssumeRole targeting newly created services or non-interactive infrastructure.', '{IaaS}', 'x-mitre-analytic--adfcc782-0285-43ef-af18-127dd60d1dff', 'DET0393', '[{"name": "AWS:CloudTrail", "channel": "PassRole", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "targetRoleName", "description": "Define which roles are allowed to be assumed or passed; restrict highly privileged roles."}, {"field": "TimeWindow", "description": "Time range between PassRole and AssumeRole events to link the privilege chain."}, {"field": "invokingService", "description": "Restrict which services are authorized to invoke role passing (e.g., Lambda, EC2)."}]', '2026-05-01 15:26:36.159793');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1205, 'AN0932', 'Analytic 0932', 'Execution of CMSTP.exe with arguments pointing to suspicious or remote INF/SCT/DLL payloads, optionally followed by outbound network connections to untrusted IPs, process injection via COM interfaces (CMSTPLUA, CMLUAUTIL), registry modifications registering malicious profiles, or creation of suspicious INF/DLL/SCT files prior to execution.', '{Windows}', 'x-mitre-analytic--ae250934-772b-43a5-9a29-9cbd92972858', 'DET0328', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "INFPathRegex", "description": "Regex for identifying suspicious INF files; adjust to suppress known safe profiles"}, {"field": "ExternalIPAllowlist", "description": "Domains or IP ranges allowed for CMSTP network connections"}, {"field": "COMInterfaceGUIDs", "description": "Set of auto-elevated COM interface GUIDs to flag (e.g., CMSTPLUA, CMLUAUTIL)"}, {"field": "RegistryKeyAllowlist", "description": "Known good registry entries for CMSTP profile registration"}, {"field": "TimeWindow", "description": "Correlate CMSTP execution with subsequent network activity or process creation within N seconds"}]', '2026-05-01 15:26:36.161085');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1206, 'AN1958', 'Analytic 1958', 'Internet scanners may be used to look for patterns associated with malicious content designed to collect host information from visitors.(Citation: ThreatConnect Infrastructure Dec 2020)(Citation: ATT ScanBox)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1207, 'AN1311', 'Analytic 1311', 'Monitors Mail.app database or maildir file access, automation via AppleScript, and abnormal mail rule creation using scripting or UI automation frameworks.', '{macOS}', 'x-mitre-analytic--ae581308-5c1f-40b9-ae6e-51c375821476', 'DET0476', '[{"name": "macos:unifiedlog", "channel": "Mail or AppleScript subsystem", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:endpointsecurity", "channel": "es_event_open, es_event_exec", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "ScriptProcessNameList", "description": "Script interpreters or automation tools (osascript, Automator, etc.)"}, {"field": "WatchedMailFiles", "description": "Mail.app SQLite DB or .emlx directory"}]', '2026-05-01 15:26:36.164472');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1208, 'AN0455', 'Analytic 0455', 'Cause→effect chain: (1) a user or service spawns a shell/PowerShell that queries local/domain password policy via commands/cmdlets (e.g., `net accounts`, `Get-ADDefaultDomainPasswordPolicy`, `secedit /export`); (2) optional directory/LDAP reads from DCs; (3) same principal performs adjacent Discovery or credential-related actions within a short window. Correlate sysmon process creation with PowerShell ScriptBlock and Security logs.', '{Windows}', 'x-mitre-analytic--ae82099a-0baf-4887-953c-67ef5e2d4470', 'DET0161', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Security", "channel": "EventCode=4662", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}]', '[{"field": "TimeWindow", "description": "Correlation window between policy query and adjacent suspicious activity (e.g., 15–30 minutes)."}, {"field": "PrivilegedUserAllowList", "description": "Accounts (e.g., Helpdesk) allowed to run policy queries routinely."}, {"field": "HostRoleScope", "description": "Limit alerts on DCs/management servers; raise on user workstations/VDI."}, {"field": "PS_ScriptBlockPatterns", "description": "Cmdlet/function names to treat as high-signal in your environment."}]', '2026-05-01 15:26:36.165627');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1209, 'AN1358', 'Analytic 1358', 'Detects abuse of UNIX domain sockets, pipes, or message queues for unauthorized code execution. Correlates unexpected socket creation with suspicious binaries, abnormal shell pipelines, or injected processes establishing IPC channels.', '{Linux}', 'x-mitre-analytic--ae8e028c-2c3a-4ac0-964f-d0b59533190d', 'DET0493', '[{"name": "auditd:SYSCALL", "channel": "socket: Suspicious creation of AF_UNIX sockets outside expected daemons", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open: Access to named pipes or FIFO in /tmp or /dev/shm by unexpected processes", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "SocketPathBaseline", "description": "Expected UNIX socket paths used by system services and applications."}, {"field": "FIFOAccessPatterns", "description": "Legitimate processes expected to open pipes in shared directories."}]', '2026-05-01 15:26:36.166794');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1210, 'AN0379', 'Analytic 0379', 'Detects unauthorized use of SMTP/IMAP/POP3 by suspicious binaries (e.g., PowerShell, rundll32) to exfiltrate data or beacon via email, often bypassing proxy or content filters.', '{Windows}', 'x-mitre-analytic--aef3d563-19f5-4d52-b7ad-4c4abadcb568', 'DET0135', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "smtp.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ProcessImageName", "description": "Limit to uncommon clients (e.g., scripts or CLI tools using .NET SMTP libraries)"}, {"field": "DestPortFilter", "description": "Typically 25, 587, 993, 995, or 465 – flag anomalies"}, {"field": "AttachmentType", "description": "Flag suspicious attachments (e.g., .zip, .7z, .bin)"}]', '2026-05-01 15:26:36.167995');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1211, 'AN0734', 'Analytic 0734', 'Detects JavaScript for Automation (JXA) via osascript or compiled scripts using OSAKit APIs. Flags execution involving system modification, inter-process scripting, or browser abuse.', '{macOS}', 'x-mitre-analytic--af3dff40-40be-40dd-9a0e-a47cf052880b', 'DET0264', '[{"name": "macos:unifiedlog", "channel": "log stream with predicate ''eventMessage CONTAINS \"osascript\"''", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:syslog", "channel": "/var/log/system.log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ScriptLocation", "description": "Execution of JXA from user-controlled paths like ~/Downloads or /Volumes."}, {"field": "ParentProcess", "description": "osascript invoked by third-party apps (VSCode, browsers, etc.)."}, {"field": "APIInvocation", "description": "Use of OSAKit API by apps not typically scripting-enabled."}]', '2026-05-01 15:26:36.169158');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1212, 'AN0339', 'Analytic 0339', 'Deletion or disablement of user accounts in platforms like Okta, Salesforce, or Zoom with anomalies in admin session attributes or mass actions within short duration.', '{SaaS}', 'x-mitre-analytic--af7bff30-45c5-4baf-9ced-68208b7ae836', 'DET0120', '[{"name": "saas:okta", "channel": "user.lifecycle.delete, user.account.lock", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "BulkActionThreshold", "description": "Trigger if multiple deletions occur within a short period"}, {"field": "SessionDeviceType", "description": "Alert on deletions initiated from unfamiliar device contexts"}]', '2026-05-01 15:26:36.170308');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1213, 'AN0674', 'Analytic 0674', 'Monitor for abnormal certificate enrollment events in identity platforms, unexpected use of token-signing certificates, and unusual CA configuration modifications.', '{"Identity Provider"}', 'x-mitre-analytic--af8d3a12-dafb-4e40-8017-7d20d9e77d55', 'DET0240', '[{"name": "azure:signinlogs", "channel": "Add certificate credential, Update certificate credential", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "m365:unified", "channel": "certificate added or modified in application credentials", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "GeoContext", "description": "Detect certificate-related changes occurring from unusual geographic locations."}, {"field": "Thresholds", "description": "Adjust enrollment/issuance request volume thresholds per tenant size."}]', '2026-05-01 15:26:36.17147');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1214, 'AN1380', 'Analytic 1380', 'Privileged or rarely used accounts performing bulk access to SharePoint files or metadata over a short time window, indicating potential scripted collection of sensitive internal documents.', '{Windows}', 'x-mitre-analytic--afb1860a-e29a-4ce8-9524-ab371c5f8d4f', 'DET0500', '[{"name": "m365:unified", "channel": "FileAccessed, FileDownloaded, SearchQueried", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "azure:signinlogs", "channel": "UserLogin, ConditionalAccessPolicyEvaluated", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "m365:sharepoint", "channel": "Multiple file download operations on a site by a privileged account in a short time window", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}]', '[{"field": "UserContext", "description": "Can be adjusted to focus on specific high-privilege or rarely-used service accounts"}, {"field": "TimeWindow", "description": "Defines the aggregation period for multiple download events (e.g., 10 minutes)"}, {"field": "DownloadThreshold", "description": "Minimum number of documents accessed/downloaded to trigger alert"}, {"field": "SiteScope", "description": "Limit detection to sensitive SharePoint sites such as HR, Finance, Engineering"}]', '2026-05-01 15:26:36.172926');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1215, 'AN1625', 'Analytic 1625', 'Adversary modifies content in cloud-hosted websites (e.g., AWS S3-backed, Azure Blob-hosted sites) by gaining access to management consoles or APIs and uploading altered HTML/JS files.', '{IaaS}', 'x-mitre-analytic--afd585f3-20fa-4bd8-8930-243cb5dbe5f8', 'DET0590', '[{"name": "AWS:CloudTrail", "channel": "PutObject", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "AWS:CloudTrail", "channel": "ListBuckets", "x_mitre_data_component_ref": "x-mitre-data-component--fcc4811f-9cc8-4db5-8097-4d8242a380de"}, {"name": "AWS:CloudTrail", "channel": "GetObject, CopyObject", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}]', '[{"field": "bucket_name", "description": "Website bucket name varies per org"}, {"field": "region", "description": "Adversary may target multi-region failover setups"}, {"field": "IAMRole", "description": "Attack may leverage stolen cross-account roles or elevated policies"}]', '2026-05-01 15:26:36.174459');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1216, 'AN0175', 'Analytic 0175', 'Detects Python script or interpreter execution on ESXi hosts via embedded BusyBox shells, nested installations, or dropped files via SSH or datastore mount. Flags unusual scripting or post-compromise enumeration behavior.', '{ESXi}', 'x-mitre-analytic--aff39b79-72c6-4cf9-8ddf-1332252580d5', 'DET0063', '[{"name": "esxi:vobd", "channel": "/var/log/vobd.log", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "esxi:hostd", "channel": "/var/log/hostd.log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ExecutionSource", "description": "Script loaded from mounted datastore, SSH upload, or dropped via guest-to-host tools."}, {"field": "HostUser", "description": "Python launched under root or unknown user."}, {"field": "InstallPath", "description": "Custom Python binaries or packages in non-default paths (/tmp/python/bin/python3)."}]', '2026-05-01 15:26:36.175803');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1217, 'AN1191', 'Analytic 1191', 'Detects user agents or background services making unauthorized or unscheduled web API calls to cloud/web services over HTTPS.', '{macOS}', 'x-mitre-analytic--aff88199-cad0-47f8-b065-0ad7a86ec8a7', 'DET0425', '[{"name": "macos:unifiedlog", "channel": "process + network activity", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "process_events, socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ProcessSignature", "description": "Unsigned or user-modified apps communicating with cloud services"}, {"field": "ConnectionInterval", "description": "Beacon-like pattern of regular outbound communication"}]', '2026-05-01 15:26:36.177367');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1218, 'AN1419', 'Analytic 1419', 'Detects exploitation attempts targeting vulnerable kernel drivers or OS components, often followed by unusual process or token behavior.', '{Windows}', 'x-mitre-analytic--b01d212c-112a-47fb-8883-78bb623ee34b', 'DET0514', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "DriverNamePattern", "description": "Targeted BYOVD drivers may vary based on campaign and tooling."}, {"field": "TimeWindow", "description": "Controls temporal linking of driver load → process spawn → privilege use."}, {"field": "ParentProcessPath", "description": "Parent-child relationships vary by exploitation vector (e.g., LOLBin vs. dropper)."}]', '2026-05-01 15:26:36.178503');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1219, 'AN0661', 'Analytic 0661', 'Detection of modified boot-time configuration scripts that persist malicious CLI commands across reboots.', '{"Network Devices"}', 'x-mitre-analytic--b053dbd4-ad1e-45e1-a6b7-af2a5d931c82', 'DET0237', '[{"name": "networkdevice:syslog", "channel": "startup-config", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "networkdevice:syslog", "channel": "system boot logs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "firmware_family", "description": "Device type or OS determines specific init script location"}, {"field": "config_line_pattern", "description": "Regex or pattern matching approach to detect suspicious CLI"}, {"field": "reboot_time_window", "description": "Time window between config change and first boot post-modification"}]', '2026-05-01 15:26:36.179727');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1220, 'AN0084', 'Analytic 0084', 'Virtual instances or workloads generating sustained outbound data rates, often to TOR, VPN, or proxy endpoints. Often coincides with unusual IAM usage or deployed scripts (e.g., cron jobs using proxy clients).', '{IaaS}', 'x-mitre-analytic--b0d018e2-0384-4e27-92ed-c9b181999fa9', 'DET0028', '[{"name": "AWS:CloudTrail", "channel": "StartInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "AWS:VPCFlowLogs", "channel": "egress > 90th percentile or frequent connection reuse", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "InstanceType", "description": "High-throughput instance types are more likely to be targeted for hijacking."}, {"field": "TrafficEgressThreshold", "description": "Customize detection thresholds based on cloud provider quotas or billing alerts."}]', '2026-05-01 15:26:36.180889');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1221, 'AN1946', 'Analytic 1946', 'Monitor for suspicious network traffic that could be indicative of probing for email addresses and/or usernames, such as large/iterative quantities of authentication requests originating from a single source (especially if the source is known to be associated with an adversary/botnet). Analyzing web metadata may also reveal artifacts that can be attributed to potentially malicious activity, such as referer or user-agent string HTTP/S fields.', '{PRE}', 'x-mitre-analytic--b123fe68-1da5-4c80-b4f0-f3d476891e11', 'DET0814', '[{"name": "Network Traffic", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', NULL, '2026-05-01 15:26:36.182203');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1222, 'AN0129', 'Analytic 0129', 'Execution of scripts or binaries that check for virtualization indicators (e.g., system_profiler, ioreg -l, kextstat), combined with delay functions or anomalous launchd activity.', '{macOS}', 'x-mitre-analytic--b12639b9-5daa-46aa-a21f-521f6962f042', 'DET0046', '[{"name": "macos:unifiedlog", "channel": "execution of system_profiler, ioreg, kextstat with argument patterns related to VM/sandbox checks", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "dynamic loading of sleep-related functions or sandbox detection libraries", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ProcessCommandPattern", "description": "Detection regex or substring matching sandbox-related checks"}, {"field": "SleepThreshold", "description": "Maximum duration of sleep execution before alert (e.g., > 5 minutes)"}]', '2026-05-01 15:26:36.183406');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1229, 'AN1470', 'Analytic 1470', 'Cloud API usage to create/import SSH keys or generate new access keys (CreateAccessKey, ImportKeyPair, CreateLoginProfile) from non-console access or unusual principals.', '{IaaS}', 'x-mitre-analytic--b31afcb5-1690-43f1-acbb-3e2936e48616', 'DET0531', '[{"name": "AWS:CloudTrail", "channel": "CreateAccessKey, ImportKeyPair, CreateLoginProfile, CreateKeyPair", "x_mitre_data_component_ref": "x-mitre-data-component--18b236d8-7224-488f-9d2f-50076a0f653a"}, {"name": "gcp:audit", "channel": "iam.serviceAccounts.keys.create, os-login.sshPublicKeys.add", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "CallerIdentityContext", "description": "Track root, federated identities, and STS tokens separately."}, {"field": "NewCredentialUsageWindow", "description": "Time between key creation and first use (default: 5 min)."}, {"field": "IAMRoleBaseline", "description": "Expected services/accounts allowed to create keys."}]', '2026-05-01 15:26:36.194172');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1223, 'AN0300', 'Analytic 0300', 'Correlation of Mail.app logs with Safari/Chrome activity. Suspicious behavior includes email links → Safari/Chrome accessing newly registered or lookalike domains → osascript or Terminal spawned unexpectedly.', '{macOS}', 'x-mitre-analytic--b18b93d1-3f63-4788-8e26-68db032995e0', 'DET0107', '[{"name": "macos:unifiedlog", "channel": "Received messages with embedded or shortened URLs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "Browser processes launching unexpected interpreters (osascript, bash)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Connections to suspicious domains with mismatched certificate or unusual patterns", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CertificateAnomalies", "description": "Flag self-signed or mismatched TLS certificates from spearphishing domains."}, {"field": "ExecutionDelayThreshold", "description": "Suspicious delay between URL click and malicious process spawn."}]', '2026-05-01 15:26:36.184557');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1224, 'AN0961', 'Analytic 0961', 'Defenders may observe unauthorized modifications to encryption-related configuration files, firmware, or crypto modules on network devices. Suspicious patterns include changes to cipher suite configurations, unexpected firmware updates affecting crypto libraries, disabling of hardware cryptographic accelerators, or reductions in key length policies. Correlating configuration changes with anomalies in encrypted traffic characteristics (e.g., weaker ciphers or sudden plaintext transmission) strengthens detection.', '{"Network Devices"}', 'x-mitre-analytic--b192336c-4a85-4322-9ae8-fd6eb6b7747b', 'DET0339', '[{"name": "networkdevice:config", "channel": "Configuration change events referencing encryption, TLS/SSL, or IPSec settings", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Flow", "channel": "Traffic patterns showing downgrade from strong encryption (AES-256) to weaker or plaintext protocols", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "snmp:status", "channel": "Status change in cryptographic hardware modules (enabled -> disabled)", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "CipherSuiteWhitelist", "description": "List of approved encryption algorithms and key lengths; customizable to organizational policy."}, {"field": "TimeWindow", "description": "Correlation period between configuration changes and abnormal traffic; adjustable to reduce false positives."}, {"field": "AuthorizedFirmwareSources", "description": "Known trusted sources of firmware updates; deviations indicate possible compromise."}, {"field": "TrafficEntropyThreshold", "description": "Baseline entropy measurements of encrypted traffic; deviations may reveal weakening of encryption."}]', '2026-05-01 15:26:36.186937');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1225, 'AN0392', 'Analytic 0392', 'Detects adversary behavior deleting artifacts (e.g., dropped payloads, evidence files) using native or external utilities (e.g., del, erase, SDelete). Detects deletion events correlated with unusual process lineage or timing post-execution.', '{Windows}', 'x-mitre-analytic--b1ee9791-91f8-4788-9e08-c40eedbcf08b', 'DET0140', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=23", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindow", "description": "Defines correlation window after suspicious binary execution or login session."}, {"field": "FilePathPattern", "description": "Focuses on deletion of temp files, malware staging dirs, or known indicators."}, {"field": "UserContext", "description": "Privilege level or impersonated user deleting sensitive files."}]', '2026-05-01 15:26:36.188134');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1226, 'AN0011', 'Analytic 0011', 'Modification of PATH or HOME environment variables through shell config files, launchctl, or /etc/paths.d entries, combined with process execution from attacker-controlled directories. Defender correlates file changes in /etc/paths.d with process execution resolving to malicious binaries.', '{macOS}', 'x-mitre-analytic--b2261c7f-664b-400c-b8ba-8b5bc3bac75a', 'DET0004', '[{"name": "macos:unifiedlog", "channel": "File modification in /etc/paths.d or user shell rc files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Process execution path inconsistent with baseline PATH directories", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WatchedPathsDirs", "description": "Monitor /etc/paths.d and $HOME for unauthorized entries."}, {"field": "TrustedExecutables", "description": "Baseline applications expected in user PATH directories."}]', '2026-05-01 15:26:36.189612');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1227, 'AN0721', 'Analytic 0721', 'Forged credentials on macOS may be visible through Unified Logs showing abnormal access to Keychain or browser session files. Correlated with anomalous web session usage from Safari or Chrome processes outside typical user context.', '{macOS}', 'x-mitre-analytic--b2569010-23c0-4dd8-9e53-3537c1e89efc', 'DET0260', '[{"name": "macos:unifiedlog", "channel": "Access to Keychain items or browser credential stores", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "macos:unifiedlog", "channel": "Web sessions initiated with newly forged tokens", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}]', '[{"field": "AuthorizedKeychainApps", "description": "List applications that normally request Keychain credentials."}]', '2026-05-01 15:26:36.19119');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1228, 'AN0603', 'Analytic 0603', 'Encryption via custom or open-source tools (e.g., openssl, gpg, aescrypt) recursively targeting user or system directories. Also includes overwrite of existing data and ransom note drops.', '{Linux}', 'x-mitre-analytic--b2f444b1-e434-40e1-9501-6b66a05a0201', 'DET0215', '[{"name": "auditd:SYSCALL", "channel": "openat, write, rename, unlink", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "FilenamePattern", "description": "Look for creation of ransom note files (e.g., READ_ME.txt, HELP_DECRYPT.html)."}, {"field": "SyscallBurstRate", "description": "High write/open/unlink activity in short intervals indicates encryption attempts."}, {"field": "DirectoryTargeted", "description": "Correlate activity in /home, /etc, /opt, or mounted volumes."}]', '2026-05-01 15:26:36.192671');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1231, 'AN0247', 'Analytic 0247', 'Behavioral sequence where removable media is mounted, files are written/updated, and subsequently read/executed on a separate host, suggesting removable-media relay communication.', '{Windows}', 'x-mitre-analytic--b355ae5d-3cd6-4594-8bd9-8fed59e02326', 'DET0090', '[{"name": "WinEventLog:System", "channel": "EventCode=1006", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "RemovableDriveLetter", "description": "Adjust drive letters used in detection (e.g., E:, F:, G:) depending on enterprise usage."}, {"field": "WriteToReadTimeWindow", "description": "Tunable window for file write on one host followed by file read or execution on another (e.g., within 10 minutes)."}, {"field": "FileNamePattern", "description": "Common naming schemes for payload, tasking, or exfil files (e.g., task.txt, beacon.log, data.bin)."}]', '2026-05-01 15:26:36.19682');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1232, 'AN0875', 'Analytic 0875', 'Detects suspicious execution of network monitoring tools (e.g., Wireshark, tshark, Microsoft Message Analyzer), driver loading indicative of promiscuous mode, or non-admin user privilege escalation to access NICs for capture.', '{Windows}', 'x-mitre-analytic--b3579b0f-7daf-40bd-af1c-f5cd020942e6', 'DET0314', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "ToolNames", "description": "Adjust list of known sniffing tools based on environment and known administrator usage."}, {"field": "TimeWindow", "description": "Tune time of day or frequency of capture sessions to reduce false positives from authorized use."}]', '2026-05-01 15:26:36.197998');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1233, 'AN0670', 'Analytic 0670', 'Detection of syslog configuration tampering using esxcli system syslog config set or reload. Defender correlates command execution with absence of syslog forwarding activity.', '{ESXi}', 'x-mitre-analytic--b3828af6-912b-493b-b621-3448a8f07972', 'DET0239', '[{"name": "esxi:hostd", "channel": "esxcli system syslog config set or reload", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SyslogServerBaseline", "description": "Expected syslog destination servers for ESXi hosts."}]', '2026-05-01 15:26:36.199129');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1234, 'AN0798', 'Analytic 0798', 'Cause→effect chain: (1) Browser/Office/reader process logs crash/segfault or abnormal sandbox message, (2) new executable/script/write occurs in $HOME (Downloads, ~/.cache, /tmp), (3) unexpected child like curl/wget/bash/python opens network connections soon after.', '{Linux}', 'x-mitre-analytic--b3b58ac5-6b60-4c34-9842-46f5ee517bcb', 'DET0287', '[{"name": "linux:syslog", "channel": "browser/office crash, segfault, abnormal termination", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "creat", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "rename,chmod", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NetFlow:Flow", "channel": "new outbound connections from exploited process tree", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "5–20m correlation window."}, {"field": "UserPaths", "description": "HOME write targets: ~/Downloads, ~/.config/autostart, ~/.local/share, /tmp."}, {"field": "HighRiskChildren", "description": "bash, sh, python, perl, node, curl, wget, socat, openssl, xxd."}, {"field": "PackageUpdaters", "description": "Allow-list common updaters (snap, flatpak, packagekit) to reduce FP."}]', '2026-05-01 15:26:36.200276');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1235, 'AN0360', 'Analytic 0360', 'Suspicious use of scripting parameters or registry edits to hide process windows (e.g., powershell.exe -WindowStyle Hidden, or registry modifications pushing window positions off screen). Defender view: correlation of hidden execution with anomalous process lineage or hVNC-like CreateDesktop API calls.', '{Windows}', 'x-mitre-analytic--b3bad14e-39a8-4e90-b3e3-46974fd9c2bd', 'DET0128', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "HiddenProcessScope", "description": "Restrict to processes where hidden execution is unexpected (e.g., PowerShell, cmd, wscript)."}, {"field": "ParentProcessCorrelation", "description": "Correlate hidden execution with suspicious parent processes to reduce false positives."}]', '2026-05-01 15:26:36.201546');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1236, 'AN0523', 'Analytic 0523', 'Monitors tampering with audit logs, volumes, or mounted storage often used for side-channel logging (e.g., /var/log inside containers) post-compromise.', '{Containers}', 'x-mitre-analytic--b3d533fc-010a-4ee8-b234-80f98e2443a0', 'DET0184', '[{"name": "docker:daemon", "channel": "container file operations", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "ebpf:syscalls", "channel": "Unexpected container volume unmount + file deletion", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "LogMountPaths", "description": "Tune based on how logs are exported (bind-mount, overlay)"}, {"field": "ContainerLabelScope", "description": "Limit detection to suspicious containers or runtime classes"}]', '2026-05-01 15:26:36.202621');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1237, 'AN0278', 'Analytic 0278', 'Detects execution of Lua interpreters or scripts (.lua), especially when correlated with suspicious parent processes or file drop events, indicating malicious use of embedded scripting.', '{Windows}', 'x-mitre-analytic--b3ea7945-a7ef-421c-be84-af86b2b95ae5', 'DET0101', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ParentProcessName", "description": "May vary depending on delivery vector (e.g., explorer.exe, cmd.exe, rundll32.exe)"}, {"field": "TimeWindow", "description": "Used to correlate file drop and execution of Lua scripts in close succession."}]', '2026-05-01 15:26:36.203856');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1238, 'AN1495', 'Analytic 1495', 'Monitor registry modifications to `HKLM\SYSTEM\CurrentControlSet\Control\Lsa\Security Packages` or `...\OSConfig\Security Packages`, especially insertions of new DLL entries. Correlate this with subsequent DLL module loads into `lsass.exe`. Track unsigned or anomalous DLLs loading into LSASS using image load auditing. LSASS loads unsigned DLL due to AuditLevel=8 registry configuration or System reboot followed by DLL load into lsass.exe', '{Windows}', 'x-mitre-analytic--b4a380ed-cc16-47cd-8fe1-44ccf4cad097', 'DET0542', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Controls how long after registry modification to expect a DLL load into LSASS (e.g., after reboot)"}, {"field": "DLLSignatureValidation", "description": "Use to detect unsigned DLLs or those not matching known trusted publisher certificates"}, {"field": "CustomSSPNameList", "description": "Define allowed SSP values for your org to reduce false positives"}, {"field": "BootContextCorrelation", "description": "Whether detection should correlate boot-time registry and process events"}]', '2026-05-01 15:26:36.205229');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1239, 'AN0566', 'Analytic 0566', 'Unsigned or user-space apps initiate TLS connections with one hostname and HTTP headers requesting a different domain, commonly abused in CDN-resident domain fronting techniques.', '{macOS}', 'x-mitre-analytic--b4cf91ba-a22b-49b4-978e-32c3e1301c74', 'DET0196', '[{"name": "macos:unifiedlog", "channel": "network, socket, and http logs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UnsignedBinary", "description": "Helps tune detection when unsigned apps initiate fronted sessions."}, {"field": "HostHeaderMatch", "description": "Threshold to flag inconsistent domain targeting in encrypted sessions."}, {"field": "SOCKSPortAnomaly", "description": "Alert on unusual ports used in HTTPS+SOCKS activity patterns."}]', '2026-05-01 15:26:36.20691');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1240, 'AN1439', 'Analytic 1439', 'Detects adversary clearing log files on macOS by correlating calls to shell utilities (e.g., echo >, rm, truncate) targeting files in /var/log/ with unusual context (non-administrative users or abnormal process lineage).', '{macOS}', 'x-mitre-analytic--b4e2440e-8956-4ae6-94cb-da859f407f27', 'DET0520', '[{"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "truncate, unlink, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "TimeWindow", "description": "Duration in which process activity and file I/O should be temporally linked."}, {"field": "LogFilePathPattern", "description": "Tunable path filter for macOS logs such as /var/log/system.log or /var/log/asl.log."}, {"field": "UserContext", "description": "Detects higher risk when log deletion is performed by unusual users (e.g., interactive vs. system users)."}]', '2026-05-01 15:26:36.209752');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1241, 'AN0125', 'Analytic 0125', 'Manual or scripted installation of Chrome extensions using user scripts or config files, followed by unexpected network connections from browser processes.', '{Linux}', 'x-mitre-analytic--b5020e23-475e-4f74-a943-787e090d3e2f', 'DET0044', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "Browser connections to known C2 or dynamic DNS domains", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExtensionDir", "description": "Location of Chrome/Chromium extensions under user profile may vary"}, {"field": "DomainWatchlist", "description": "Custom list of suspicious destination domains for browser traffic"}]', '2026-05-01 15:26:36.211183');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1242, 'AN1041', 'Analytic 1041', 'Use of file enumeration commands (e.g., ''ls'', ''find'', ''locate'') executed by suspicious users or scripts accessing broad file hierarchies or restricted directories.', '{Linux}', 'x-mitre-analytic--b50bf863-644a-48c2-85a3-2c633f135650', 'DET0370', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PATH", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "FilePathDepth", "description": "Max depth of recursive access to tune noise vs anomaly"}, {"field": "UserContext", "description": "Helpful to exclude known scripts or automation accounts"}]', '2026-05-01 15:26:36.212945');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1243, 'AN0974', 'Analytic 0974', 'Detects usage of shared memory directories (/dev/shm, /run/shm) for temporary storage of obfuscated, encoded, or executable data without persistence to disk.', '{Linux}', 'x-mitre-analytic--b521510b-83bc-46a2-8fc8-65a6975bcfca', 'DET0344', '[{"name": "auditd:SYSCALL", "channel": "open, write, unlink", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "linux:osquery", "channel": "file_events.path", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "PathPrefix", "description": "Shared memory mount path used (e.g., /dev/shm/ or /run/shm/)"}, {"field": "FilenameRegex", "description": "Regex to match non-standard, suspicious, or encoded filenames"}, {"field": "ExecCorrelationWindow", "description": "Time window to correlate process execution from shared memory directories"}]', '2026-05-01 15:26:36.21422');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1244, 'AN1596', 'Analytic 1596', 'Detect attempts to enumerate kernel modules through lsmod, modinfo, or inspection of /proc/modules and /dev entries. Focus on unusual execution contexts such as unprivileged users or processes outside expected administrative workflows.', '{Linux}', 'x-mitre-analytic--b55c3339-2d4c-4392-8d26-c257ea2f1bb9', 'DET0579', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of lsmod, modinfo, or cat /proc/modules", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:FS", "channel": "read: File access to /proc/modules or /sys/module/", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "KnownAdminUsers", "description": "Limit detection noise by filtering expected kernel module inspection by root or system maintenance scripts."}]', '2026-05-01 15:26:36.215692');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1245, 'AN0883', 'Analytic 0883', 'Execution of destructive utilities (dd, shred, wipe) targeting block devices, or processes invoking syscalls to directly overwrite /dev/sd* or /dev/nvme* partitions. Correlate abnormal file write attempts with shell process execution and block device access.', '{Linux}', 'x-mitre-analytic--b55c84a0-d045-43f6-a5a9-e8f6edbd275e', 'DET0316', '[{"name": "auditd:SYSCALL", "channel": "open/write syscalls to block devices (/dev/sd*, /dev/nvme*)", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"name": "auditd:EXECVE", "channel": "Execution of dd, shred, or wipe with arguments targeting block devices", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetDevices", "description": "Exclude removable drives or designated partitions that may be overwritten during maintenance."}, {"field": "EntropyThreshold", "description": "Tune detection for pseudorandom write patterns to reduce false positives during high-volume I/O."}]', '2026-05-01 15:26:36.216959');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1246, 'AN1964', 'Analytic 1964', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1247, 'AN1350', 'Analytic 1350', 'Behavioral chain: (1) delegated administration offers/relationships created or modified by partner tenants; (2) mailbox delegation/impersonation enabled; (3) follow-on access from partner IPs.', '{"Office Suite"}', 'x-mitre-analytic--b5985d46-1d54-4a6d-81c8-0b577b5d8d17', 'DET0488', '[{"name": "m365:unified", "channel": "Add-DelegatedAdmin, Set-PartnerOfRecord, Add-MailboxPermission, Set-OrganizationRelationship", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "azure:signinlogs", "channel": "InteractiveUser, NonInteractiveUser", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "MailboxDelegateAllowList", "description": "Specific mailboxes third-parties may manage."}]', '2026-05-01 15:26:36.219713');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1248, 'AN0148', 'Analytic 0148', 'Delivery of suspicious internal communication (e.g., Thunderbird, Evolution) using compromised internal accounts. Sequence of: unexpected user activity + mail transfer logs + download or execution of attachments.', '{Linux}', 'x-mitre-analytic--b5b53b9d-f72b-4cd5-946b-d1ddfdad3c0f', 'DET0054', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "Application:Mail", "channel": "smtpd$.*$: .*from=[.*@internaldomain.com](mailto:.*@internaldomain.com) to=[.*@internaldomain.com](mailto:.*@internaldomain.com)", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "linux:syslog", "channel": "curl|wget|python .*http", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "SubjectLineAnomaly", "description": "Deviation from typical internal email subjects"}, {"field": "AttachmentType", "description": "Executable types allowed or flagged by mail relay"}]', '2026-05-01 15:26:36.221061');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1249, 'AN0643', 'Analytic 0643', 'Detects execution of binaries signed with unusual or recently issued certificates, correlation of process execution with abnormal publisher metadata, and mismatched certificate chains. Monitors for revoked or unknown code signing certificates used in high-privilege contexts.', '{Windows}', 'x-mitre-analytic--b5d77678-fff4-41cd-9e77-d3f82243240a', 'DET0230', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "AllowedCertificateAuthorities", "description": "Define trusted issuers to suppress noise from legitimate enterprise signing chains"}, {"field": "TimeWindow", "description": "Correlation window for detecting execution of binaries with newly observed or anomalous certificates"}, {"field": "CertificateAgeThreshold", "description": "Baseline normal age of certificates; flag very recent or expired certificates"}]', '2026-05-01 15:26:36.222486');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1250, 'AN0425', 'Analytic 0425', 'Detects abnormal outbound HTTP/FTP connections by local scripts or binaries outside of standard browser activity, following access to local documents or user data.', '{macOS}', 'x-mitre-analytic--b608c89f-ce2c-4993-8522-7b2731851606', 'DET0149', '[{"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "log stream - file subsystem", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "http.log, ftp.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ScriptedClientAllowlist", "description": "Defines allowed automated agents that may transmit HTTP or FTP data (e.g., backup tools)."}, {"field": "PayloadInspectionKeywordList", "description": "Terms or patterns indicating structured or sensitive data leaving via HTTP/FTP."}]', '2026-05-01 15:26:36.224108');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1251, 'AN1568', 'Analytic 1568', 'Detects USB HID device enumeration under `/sys/bus/usb/devices/` and rapid keystroke injection resulting in command execution such as bash or Python scripts launched without interactive user activity.', '{Linux}', 'x-mitre-analytic--b61673d6-244f-4888-9370-1a3ef391a6c2', 'DET0568', '[{"name": "auditd:SYSCALL", "channel": "execve: parent process is usb/hid device handler, child process bash/python invoked", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "New HID device enumeration with type ''keyboard'' followed by immediate input injection", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "USBVendorIDs", "description": "Track suspicious or unapproved USB vendor/product IDs."}, {"field": "ScriptExecutionThreshold", "description": "Time threshold for script execution after HID injection, e.g., less than 10 seconds."}]', '2026-05-01 15:26:36.225942');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1252, 'AN0800', 'Analytic 0800', 'Correlates suspicious removal or modification of the com.apple.quarantine extended attribute, manipulation of LSFileQuarantineEnabled values in Info.plist, and unexpected process execution of unsigned or non-notarized binaries. Also monitors abnormal trust validation failures in unified logs and unusual activity in QuarantineEvents database entries.', '{macOS}', 'x-mitre-analytic--b6516e8b-fd18-4c92-8701-1762d8321168', 'DET0288', '[{"name": "macos:unifiedlog", "channel": "xattr -d com.apple.quarantine or similar attribute removal commands", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "macos:unifiedlog", "channel": "Trust validation failures or bypass attempts during notarization and code signing checks", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "Changes to LSFileQuarantineEnabled field in Info.plist", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "QuarantineBypassAllowList", "description": "Legitimate enterprise update tools or deployment frameworks that may strip quarantine flags"}, {"field": "CertificateAuthorityList", "description": "Baseline trusted Apple Developer IDs and enterprise certs used for code signing"}, {"field": "TimeWindow", "description": "Time correlation window for xattr modification followed by suspicious process execution"}]', '2026-05-01 15:26:36.227389');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1253, 'AN0863', 'Analytic 0863', 'A compromised package/update (deb/rpm/tarball/AppImage/vendor updater) is installed, writing/overwriting files in /usr/local/bin, /usr/bin, /opt, or ~/.local; first run executes unexpected shells/curl/wget and connects to unapproved hosts. Correlate package/updater execution → file writes/replace → first-run child processes → egress.', '{Linux}', 'x-mitre-analytic--b6f88f17-e80f-4c75-99a5-f752880196aa', 'DET0309', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "journald:package", "channel": "dpkg/apt/yum/dnf transaction logs; vendor updaters in systemd journals", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "NSM:Flow", "channel": "New outbound flows to non-approved vendor hosts post install", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "PathScope", "description": "Monitored install paths (/usr/local, /usr/bin, /opt/*, ~/.local/bin, /var/lib/systemd)."}, {"field": "ApprovedRepos", "description": "Allow-listed APT/YUM repos and GPG keys for vendor updates."}, {"field": "TimeWindow", "description": "Default 90 minutes."}]', '2026-05-01 15:26:36.228623');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1254, 'AN1579', 'Analytic 1579', 'Detects assignment of high-privilege roles to user or service accounts via Kubernetes RoleBinding or ClusterRoleBinding objects, especially outside of CI/CD automation or from unknown IPs.', '{Containers}', 'x-mitre-analytic--b721ae18-79fc-4b82-8991-93980b14ded5', 'DET0572', '[{"name": "kubernetes:audit", "channel": "create or update events for RoleBinding or ClusterRoleBinding objects", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "UserAgent", "description": "Filter expected sources of automated role assignment (e.g., CI/CD tooling)"}, {"field": "RoleName", "description": "Scope to privileged roles like cluster-admin, edit, admin"}, {"field": "TimeWindow", "description": "Detect after-hours or irregular-time assignments"}, {"field": "UserContext", "description": "Define known service accounts and privileged operators to reduce noise"}]', '2026-05-01 15:26:36.229777');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1255, 'AN2029', 'Analytic 2029', 'Process execution without GUI context (e.g., powershell.exe, wscript.exe) generates HTTP traffic with a spoofed User-Agent mimicking a legitimate browser. No corresponding UI application (e.g., msedge.exe) is active or in parent lineage. The User-Agent deviates from known enterprise baselines or contains spoofed platform indicators.  User-Agent strings can be gathered with API calls such as `ShellExecuteW` to open the default browser on a socket to receive an HTTP reply, or by hard coding the User-Agent string for a specific browser.', '{Windows}', 'x-mitre-analytic--b73489af-2e95-4f41-b82e-327a84da2a1d', 'DET0898', '[{"name": "NSM:Flow", "channel": "Inbound HTTP POST with suspicious payload size or user-agent", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "API Calls", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "HeaderSignatureMatch", "description": "Specific HTTP header anomalies or patterns (e.g., spoofed User-Agent)."}, {"field": "UserAgentFingerprint", "description": "Flag browser-based sessions"}, {"field": "NonBrowserProcessList", "description": "List of non-browser binaries expected not to initiate web requests (e.g., powershell.exe, cscript.exe)"}]', '2026-05-01 15:26:36.232178');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1256, 'AN1324', 'Analytic 1324', 'Detection of token duplication and impersonation attempts by correlating suspicious command-line executions (e.g., runas) with API calls to DuplicateToken, DuplicateTokenEx, ImpersonateLoggedOnUser, or SetThreadToken. The chain includes the initial command execution or in-memory API invocation → token handle duplication or thread token assignment → a new or existing process assuming the impersonated user''s context.', '{Windows}', 'x-mitre-analytic--b76aeebb-3915-48ed-ac35-6af54c88c3bb', 'DET0482', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "ETW:Token", "channel": "api_call: DuplicateTokenEx, ImpersonateLoggedOnUser, SetThreadToken", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "AllowedSystemProcesses", "description": "Whitelist of known processes that legitimately duplicate tokens (e.g., services.exe)."}, {"field": "TimeWindow", "description": "Time interval between API call and subsequent impersonated process (e.g., 5m)."}, {"field": "UserContextFilter", "description": "Filter for service accounts or known administrative accounts that perform legitimate impersonation."}, {"field": "ParentProcessAnomalyThreshold", "description": "Threshold for parent-child process lineage anomalies indicating token theft."}]', '2026-05-01 15:26:36.233544');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1257, 'AN1238', 'Analytic 1238', 'Account created using esxcli commands. Sequence includes esxcli execution and successful modification to account DB.', '{ESXi}', 'x-mitre-analytic--b7a63a7c-e8c2-4a25-becf-299ea45996e5', 'DET0447', '[{"name": "esxi:vmkernel", "channel": "esxcli system account add", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandOrigin", "description": "Console sessions vs SSH vs vSphere CLI session may affect alert fidelity"}]', '2026-05-01 15:26:36.235011');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1258, 'AN0585', 'Analytic 0585', 'Malicious script or binary causes repeated kernel panics, OOM kills, or systemd service restarts targeting services like nginx, httpd, sshd.', '{Linux}', 'x-mitre-analytic--b7e4a6de-8ff3-4711-aa83-97533adec211', 'DET0208', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Out of memory killer invoked or kernel panic entries", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "journald:systemd", "channel": "Repeated service restart attempts or unit failures", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ServiceName", "description": "Targeted daemon/service such as sshd, nginx, mysql"}, {"field": "RestartThreshold", "description": "Number of restarts in short succession to trigger alert"}, {"field": "OOMKillCount", "description": "Count of OOM kills over a time window"}]', '2026-05-01 15:26:36.236431');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1259, 'AN0391', 'Analytic 0391', 'Detects DYLD_INSERT_LIBRARIES abuse to hook credential-sensitive applications by correlating process spawns with unauthorized library injection and monitoring changes to the __TEXT segment (code) of credential handling binaries.', '{macOS}', 'x-mitre-analytic--b8141218-1f71-4b65-a611-7c9c55038c4c', 'DET0139', '[{"name": "macos:unifiedlog", "channel": "DYLD event subsystem", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "fs:fsusage", "channel": "File Access Monitor", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "Memory Mappings", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "DYLDInjectedPath", "description": "Tunable based on naming patterns or location of malicious dylibs"}, {"field": "ParentProcessName", "description": "Hooking attempts may stem from terminal.app, bash, or AppleScript-based launchers"}]', '2026-05-01 15:26:36.237968');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1260, 'AN1561', 'Analytic 1561', 'Registry access to system language keys (e.g., HKLM\SYSTEM\CurrentControlSet\Control\Nls\Language) or suspicious processes invoking locale-related APIs (e.g., GetUserDefaultUILanguage, GetSystemDefaultUILanguage, GetKeyboardLayoutList). Defender visibility focuses on anomalous or non-standard processes issuing these queries, especially when run by unknown binaries or scripts.', '{Windows}', 'x-mitre-analytic--b8685b0b-f96e-41a4-8e01-eec252756447', 'DET0565', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "ETW", "channel": "Calls to GetUserDefaultUILanguage, GetSystemDefaultUILanguage, GetKeyboardLayoutList", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "ParentProcessAllowList", "description": "Defines trusted processes allowed to query registry language keys or APIs. Unexpected parent-child process chains may indicate adversary use."}, {"field": "QueryThreshold", "description": "Frequency threshold for language registry or API calls within a set time window."}]', '2026-05-01 15:26:36.239499');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1261, 'AN0506', 'Analytic 0506', 'Detection of VNC-based remote control via `screensharingd` activity in Unified Logs along with concurrent remote login activity or suspicious user interaction.', '{macOS}', 'x-mitre-analytic--b88251d3-6406-4512-a55f-a6bc3493e2ad', 'DET0178', '[{"name": "macos:unifiedlog", "channel": "authentication", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:firewall", "channel": "inbound connection to port 5900", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "AuthenticationPredicate", "description": "Unified log predicate to refine suspicious screensharing access"}, {"field": "TimeWindow", "description": "Time between VNC connection and follow-on activity (e.g., 30s)"}, {"field": "UserActivitySpike", "description": "Mouse/keyboard interaction spike immediately post-VNC login"}]', '2026-05-01 15:26:36.241274');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1262, 'AN0087', 'Analytic 0087', 'Detects modifications to IAM conditions or policies that alter authentication behavior, such as adding permissive trusted IPs, removing MFA requirements, or changing regional access restrictions. Behavioral detection focuses on anomalous policy updates tied to privileged accounts and subsequent suspicious logon activity from previously blocked regions or devices.', '{IaaS}', 'x-mitre-analytic--b88f87d2-4a64-44a2-937e-85a929203843', 'DET0030', '[{"name": "AWS:CloudTrail", "channel": "PutUserPolicy, PutGroupPolicy, PutRolePolicy, CreatePolicyVersion", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "MonitoredIAMConditions", "description": "Specific condition keys (SourceIp, RequestedRegion, MFAAuthenticated) tuned per environment."}, {"field": "TimeWindow", "description": "Correlates policy modification with follow-on logins from newly permitted sources."}, {"field": "PrivilegedAccounts", "description": "List of administrative accounts to prioritize when monitoring for conditional access changes."}]', '2026-05-01 15:26:36.242833');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1263, 'AN0927', 'Analytic 0927', 'A process/script constructs or references a custom/alphabet translation table (e.g., 64/85/32+ arbitrary chars, XOR/base-N loops) or emits long high-entropy strings that do NOT validate as standard Base64/Hex → shortly after, the same process (or its child) generates outbound traffic with asymmetric bytes_out:bytes_in, fixed-size beacons, or protocol/header mismatches (e.g., Content-Type says JSON but body fails JSON parse / contains non-standard alphabet).', '{Windows}', 'x-mitre-analytic--b8dea721-8e0d-4bcd-bde4-6609afd595e5', 'DET0326', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "m365:defender", "channel": "NetworkConnection: high out:in ratio, periodic beacons, protocol mismatch", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "EntropyThreshold", "description": "Minimum Shannon entropy for the suspected token/payload (e.g., >4.8)."}, {"field": "TokenLengthThreshold", "description": "Minimum continuous token length to treat as potential non-standard payload (e.g., ≥120 chars)."}, {"field": "BytesOutToInRatio", "description": "Out:In ratio considered suspicious (e.g., ≥4:1)."}, {"field": "FixedPacketStdDevThreshold", "description": "Std. dev. threshold (size or interval) to mark packets as ''uniform'' (beacon-like)."}, {"field": "TimeWindow", "description": "Correlation window from encode routine to egress (default 10m)."}, {"field": "KnownLegitEncoders", "description": "Legitimate in-house/custom encoders to suppress."}]', '2026-05-01 15:26:36.244096');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1264, 'AN1242', 'Analytic 1242', 'Detection focuses on abnormal or unauthorized cloud instance creation events. From a defender’s perspective, suspicious behavior includes VM/instance creation by rarely used or newly created accounts, creation events from unusual geolocations, or rapid sequences of snapshot creation followed by instance creation and mounting. Unexpected network or IAM policy changes applied to new instances can indicate adversarial use rather than legitimate provisioning.', '{IaaS}', 'x-mitre-analytic--b8ec766b-cfb9-4ef8-bd46-655f0b820ad3', 'DET0449', '[{"name": "AWS:CloudTrail", "channel": "RunInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "AWS:CloudTrail", "channel": "DescribeInstances", "x_mitre_data_component_ref": "x-mitre-data-component--45fd904d-6eb0-4b50-8478-a961f09f898b"}, {"name": "azure:activity", "channel": "MICROSOFT.COMPUTE/VIRTUALMACHINES/WRITE", "x_mitre_data_component_ref": "x-mitre-data-component--b5b0e8ae-7436-4951-950a-7b83c4dd3f2c"}]', '[{"field": "UserContext", "description": "IAM user, service account, or role creating the instance. Tuned to allowlist known automation services."}, {"field": "GeoLocation", "description": "Region or source IP where the creation request originates. Helps detect cross-region or unusual location abuse."}, {"field": "RateThreshold", "description": "Number of instances created per user or account in a time window. Tuned for environments with elastic scaling."}, {"field": "TaggingPolicy", "description": "Expected tags (e.g., owner, purpose, cost center) for new instances. Deviations may indicate adversarial creation."}]', '2026-05-01 15:26:36.245446');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1265, 'AN0762', 'Analytic 0762', 'VMware management daemons or guest processes initiating encrypted connections outside expected vCenter, update servers, or internal comms. Defender identifies hostd or vpxa initiating outbound TLS flows with uncommon destinations.', '{ESXi}', 'x-mitre-analytic--b94bb114-7532-4934-9955-9c7031109b9e', 'DET0273', '[{"name": "esxi:vpxd", "channel": "TLS session established by ESXi service to unapproved endpoint", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "esxi:vmkernel", "channel": "Inspection of sockets showing encrypted sessions from non-baseline processes", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AllowedMgmtHosts", "description": "Baseline approved endpoints for vCenter or update services."}]', '2026-05-01 15:26:36.247288');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1266, 'AN1230', 'Analytic 1230', 'User-space tools (e.g., `socat`, `ncat`, `iptables`, `ssh`) used in non-standard ways to establish reverse shells, port-forwarding, or inter-host connections. Often chained with uncommon outbound destinations or SSH tunnels.', '{Linux}', 'x-mitre-analytic--b95a3fbf-3d6c-4ead-8421-ff9c07ca4019', 'DET0445', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Connection Tracking", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "CommandLinePattern", "description": "Shell piping into tools like `socat`, `ncat`, or `openssl` for tunnel creation."}, {"field": "OutboundPortRange", "description": "Flag connections made from internal systems to uncommon high ports externally."}, {"field": "ProcessUserContext", "description": "Capture low-privilege or unexpected users executing system-level network tools."}]', '2026-05-01 15:26:36.248585');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1267, 'AN1022', 'Analytic 1022', 'LaunchAgents or LaunchDaemons initiate persistent Tor or relay processes that make encrypted outbound connections. May be paired with sandbox bypasses or unsigned executables communicating over SOCKS proxies.', '{macOS}', 'x-mitre-analytic--b97a1c6e-bb02-4e14-ae57-6a9e96512657', 'DET0359', '[{"name": "macos:unifiedlog", "channel": "process, socket, and DNS logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "process_events + launchd", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "macos:unifiedlog", "channel": "forwarded encrypted traffic", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "LaunchdLabel", "description": "Regex for masking patterns in LaunchAgents with proxy behavior."}, {"field": "UnsignedBinary", "description": "Allow for exceptions for known unsigned binaries."}, {"field": "SOCKSPortUsage", "description": "Monitor local 9050/9150 activity and rerouted system traffic."}]', '2026-05-01 15:26:36.249802');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1268, 'AN0681', 'Analytic 0681', 'Defenders may observe attempts to alter cryptographic settings on network devices that reduce key strength or allowable cipher suites. Suspicious indicators include configuration changes that downgrade encryption algorithms, key length parameters, or the disabling of strong encryption in favor of legacy ciphers. These activities often appear as CLI commands modifying crypto policies, firmware changes affecting crypto libraries, or unexpected updates to key management files. Correlation across device config logs and traffic analysis showing weaker ciphers provides higher confidence of malicious key space reduction.', '{"Network Devices"}', 'x-mitre-analytic--b9e42cd6-da26-4e57-b628-aca0fb1bb3f3', 'DET0243', '[{"name": "networkdevice:config", "channel": "Configuration changes referencing ''crypto'', ''key length'', ''cipher'', or downgrade of encryption settings", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "networkdevice:cli", "channel": "Execution of CLI commands altering crypto parameters (e.g., ''crypto key generate rsa modulus 512'')", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "Observed downgrade in negotiated cipher suites or TLS/SSH versions across sessions", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AllowedKeyLengths", "description": "Defines the minimum acceptable encryption key sizes; tunable to organizational policy."}, {"field": "CipherSuiteBaseline", "description": "Baseline list of approved cipher suites for network sessions; deviations may indicate tampering."}, {"field": "AuthorizedAdminAccounts", "description": "Whitelisted accounts for executing crypto configuration changes; ensures alerts only trigger on unauthorized actions."}, {"field": "TimeWindow", "description": "Time correlation period between configuration change and anomalous traffic downgrade; adjustable to reduce noise."}]', '2026-05-01 15:26:36.251045');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1269, 'AN0943', 'Analytic 0943', 'Detects creation of scheduled tasks via `at.exe` or WMI `Win32_ScheduledJob` class, followed by execution of anomalous processes by svchost.exe or taskeng.exe.', '{Windows}', 'x-mitre-analytic--b9f79a81-9fee-47f2-bef8-a9f64fde935e', 'DET0333', '[{"name": "WinEventLog:Security", "channel": "EventCode=4698", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TaskUser", "description": "Unusual users creating jobs (e.g., non-admin accounts or service users)."}, {"field": "ExecutionTimeWindow", "description": "Delay between task registration and execution."}, {"field": "CommandLinePattern", "description": "Unexpected script or binary execution (e.g., cmd.exe /c PowerShell payload)."}]', '2026-05-01 15:26:36.252368');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1270, 'AN1366', 'Analytic 1366', 'Chain of remote access tool behavior: (1) initial execution of remote-control/assist agent or GUI under user context; (2) persistence via service or autorun; (3) long-lived outbound connection/tunnel to external infrastructure; (4) interactive control signals such as shell or file-manager child processes spawned by the RAT parent.', '{Windows}', 'x-mitre-analytic--ba2056ee-77d7-49d4-a993-5806506964df', 'DET0496', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Correlation period binding start→persistence→egress→child (default 15m, adjust per environment)."}, {"field": "UserContext", "description": "Differentiate help-desk/jump hosts and admin accounts from standard endpoints."}, {"field": "ProcessAllowlist", "description": "Known-good remote support tools; suppress expected events while still correlating anomalous sequences."}, {"field": "InstallPathRegex", "description": "Alert when services/agents execute from user-writable or temp paths."}, {"field": "ExternalIPAllowlist", "description": "Vendors’ support clouds/CDNs to reduce false positives on egress detection."}, {"field": "ShellSpawnRegex", "description": "Define which child shells from GUI parents are acceptable versus suspicious."}, {"field": "EgressHeuristics", "description": "Thresholds for session duration, connection counts, and bytes_out/bytes_in ratio."}]', '2026-05-01 15:26:36.253659');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1271, 'AN1310', 'Analytic 1310', 'Detects file access to mbox/maildir files in conjunction with curl/wget/postfix execution, or anomalous shell scripts harvesting user mail directories.', '{Linux}', 'x-mitre-analytic--ba43428d-b5d2-4815-a614-42ff1ea816a9', 'DET0476', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:syslog", "channel": "postfix/smtpd", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "linux:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WatchedMailDirs", "description": "Specify user mail directories (/var/mail, ~/Maildir)"}, {"field": "ProcessNameList", "description": "Tune based on local mail clients or curl usage in environment"}, {"field": "TimeWindow", "description": "Define how close together access and exfil events must occur"}]', '2026-05-01 15:26:36.255036');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1272, 'AN0994', 'Analytic 0994', 'Monitor unified logs for processes spawned from Safari or other browsers that immediately load scripts or executables. Detect file drops in ~/Library/Caches or ~/Downloads that execute shortly after being written.', '{macOS}', 'x-mitre-analytic--ba6a9282-30e0-491c-90a7-35bf4ad25ba3', 'DET0349', '[{"name": "macos:unifiedlog", "channel": "Child processes of Safari, Chrome, or Firefox executing scripting interpreters", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "File creation of unsigned binaries/scripts in user cache or download directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Content injection observed in HTTPS responses with mismatched certificates or altered payloads", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MonitoredDirectories", "description": "macOS-specific directories where malicious payloads may be written."}]', '2026-05-01 15:26:36.256744');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1273, 'AN0338', 'Analytic 0338', 'O365 UnifiedAuditLog entries for Remove-Mailbox or Set-Mailbox with account disable or delete actions correlated with suspicious login locations or MFA bypass.', '{"Office Suite"}', 'x-mitre-analytic--ba6c8c55-ee38-4219-a426-a3f1e04c7a8a', 'DET0120', '[{"name": "m365:unified", "channel": "Remove-Mailbox, Set-Mailbox", "x_mitre_data_component_ref": "x-mitre-data-component--d6257b8e-869c-41c0-8731-fdca40858a91"}, {"name": "m365:signinlogs", "channel": "Sign-in from anomalous location or impossible travel condition", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "RoleAssignment", "description": "Determine if operation was delegated to expected admin group"}, {"field": "GeoThreshold", "description": "Trigger on unusual geographic login sources"}]', '2026-05-01 15:26:36.26015');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1274, 'AN1980', 'Analytic 1980', 'Consider use of services that may aid in the tracking of newly issued certificates and/or certificates in use on sites across the Internet. In some cases it may be possible to pivot on known pieces of certificate information to uncover other adversary infrastructure.(Citation: Splunk Kovar Certificates 2017) Some server-side components of adversary tools may have default values set for SSL/TLS certificates.(Citation: Recorded Future Beacon Certificates)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1275, 'AN1159', 'Analytic 1159', 'Use of configuration backup utilities or CLI access to dump plaintext passwords, local user hashes, or SNMP strings.', '{"Network Devices"}', 'x-mitre-analytic--badcc199-683b-41f5-9522-9710969cff15', 'DET0412', '[{"name": "linux:syslog", "channel": "CLI access to ''show running-config'', ''show password'', or ''cat config.txt''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "large transfer from management IPs to unauthorized host", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ManagementInterfaceIPs", "description": "IP ranges authorized to perform credential dumps"}, {"field": "CommandPattern", "description": "Regex patterns for suspicious CLI commands"}]', '2026-05-01 15:26:36.263709');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1276, 'AN0310', 'Analytic 0310', 'Detection monitors SaaS collaboration tools (e.g., Slack, Zoom, Jira) for messages or files containing credential-like patterns, or for suspicious API calls retrieving bulk chat histories by non-admin users. Identifies adversary behavior chains where chat logs are queried via APIs or integration bots to systematically extract sensitive material.', '{SaaS}', 'x-mitre-analytic--bafd38ad-aebd-40f1-9f17-bd63a1c74ba9', 'DET0111', '[{"name": "saas:slack", "channel": "chat.postMessage, files.upload, or discovery API calls involving token/credential regex", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:okta", "channel": "Unusual OAuth app requesting message-read scopes for Slack/Teams/Jira", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "IntegrationScope", "description": "Tune to ignore known enterprise bots with message-read access (e.g., DLP scanners)"}, {"field": "RegexPatterns", "description": "Customizable regex for detecting secret formats (JWT, OAuth tokens, SSH keys)"}, {"field": "UserContext", "description": "Correlate with user role to filter developers vs standard users"}]', '2026-05-01 15:26:36.265085');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1277, 'AN0495', 'Analytic 0495', 'Detects exploitation attempts against macOS authentication frameworks such as OpenDirectory or Keychain. Defender perspective includes abnormal crashes in opendirectoryd, unauthorized Keychain API usage, and unusual sudo or login events. Correlation links unexpected process behavior with credential access anomalies.', '{macOS}', 'x-mitre-analytic--bb339113-e807-45fe-99c4-ed8348e51b36', 'DET0174', '[{"name": "macos:unifiedlog", "channel": "opendirectoryd crashes or abnormal authentication errors", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:osquery", "channel": "execve: Processes unexpectedly invoking Keychain or authentication APIs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WatchedAPIs", "description": "List of authentication and Keychain-related APIs to monitor for unauthorized access."}, {"field": "CrashCorrelationWindow", "description": "Time window for correlating authentication service crashes with subsequent suspicious access."}]', '2026-05-01 15:26:36.266641');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1278, 'AN0826', 'Analytic 0826', 'Detects unauthorized firmware or configuration changes enabling adversary-in-the-middle positioning (e.g., route injection, DNS spoofing, SSL downgrade). Behavioral analytics focus on sudden changes to routing tables or image file integrity failures.', '{"Network Devices"}', 'x-mitre-analytic--bb3daf14-f237-4688-a319-a4d7570e407e', 'DET0296', '[{"name": "NSM:Flow", "channel": "Unexpected route changes or duplicate gateway advertisements", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "networkdevice:config", "channel": "Configuration file modified or replaced on network device", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "RoutingPolicyBaseline", "description": "Expected routing and BGP/OSPF paths for validation."}, {"field": "FirmwareChecksum", "description": "Baseline image checksum per device type used to detect tampering."}]', '2026-05-01 15:26:36.267991');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1279, 'AN0249', 'Analytic 0249', 'Correlates removable volume mounts (disk arbitration) with file I/O events on that volume, followed by same file execution shortly after insert.', '{macOS}', 'x-mitre-analytic--bb687663-4b26-46ef-a176-e188f538d399', 'DET0090', '[{"name": "macos:unifiedlog", "channel": "com.apple.diskarbitration", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}, {"name": "fs:fsusage", "channel": "open/write/exec calls", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "VolumeNameFilter", "description": "Known suspicious USB volume labels or types (e.g., NO NAME, SECUREDATA)."}, {"field": "ProcessContext", "description": "Unusual processes accessing USB drives (e.g., bash, Python, unsigned binaries)."}]', '2026-05-01 15:26:36.269378');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1280, 'AN0696', 'Analytic 0696', 'Identifies unauthorized access or enumeration of administrative roles, security groups, or distribution groups via Exchange/SharePoint/Teams APIs or role discovery scripts.', '{"Office Suite"}', 'x-mitre-analytic--bb94692e-e73c-449c-a17e-0658bebbfd93', 'DET0251', '[{"name": "m365:exchange", "channel": "Get-RoleGroup, Get-DistributionGroup", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "m365:sharepoint", "channel": "Enumerate ACLs/role bindings", "x_mitre_data_component_ref": "x-mitre-data-component--8d8c7cac-94cf-4726-8989-cab33851168c"}]', '[{"field": "AccessScope", "description": "Adjust based on tenant-level vs. site-level group visibility."}, {"field": "ScriptExecutionContext", "description": "Detect script-based role listing (e.g., Graph API call chains)."}]', '2026-05-01 15:26:36.270776');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1281, 'AN0290', 'Analytic 0290', 'Detects suspicious configuration changes in IdP authentication flows such as enabling reversible password encryption, MFA bypass, or policy weakening. Correlates policy modification events with unusual administrative activity.', '{"Identity Provider"}', 'x-mitre-analytic--bbaa7fb3-974c-41ef-9cec-a0789a66445c', 'DET0104', '[{"name": "azure:policy", "channel": "UpdatePolicy", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "m365:unified", "channel": "Set-ADUser OR Set-ADAccountControl", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "PolicyBaseline", "description": "Expected authentication-related policy configurations to compare against."}]', '2026-05-01 15:26:36.272213');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1282, 'AN0624', 'Analytic 0624', 'Detects remote scripts or binaries deployed via Puppet, Chef, Ansible, or shell scripts from orchestration servers executing outside maintenance windows or in unmanaged nodes.', '{Linux}', 'x-mitre-analytic--bbb8adb2-434a-483e-af3c-4843241e2158', 'DET0223', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DeployingHostAllowList", "description": "Approved orchestration or jump box IPs"}, {"field": "ScriptExecutionBaseline", "description": "Expected scripts, interpreters, or package managers used"}]', '2026-05-01 15:26:36.273962');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1415, 'AN0839', 'Analytic 0839', 'Monitor for in-process mmap + mprotect + execve/execveat activity where memory permissions are changed from writable to executable inside the same process without a corresponding ELF on disk.', '{Linux}', 'x-mitre-analytic--cfdd2422-7e68-417a-9298-062bac59df0c', 'DET0300', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:MMAP", "channel": "memory region with RWX permissions allocated", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "ProcessNameScope", "description": "Uncommon for service binaries to call memfd_create; detection tuned for high-risk processes."}, {"field": "RWXMemoryThreshold", "description": "Adjust threshold for allowed RWX allocations to reduce false positives in JIT runtimes."}]', '2026-05-01 15:26:36.469674');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1283, 'AN0009', 'Analytic 0009', 'Abnormal modification of the PATH environment variable or registry keys controlling system paths, combined with execution of binaries named after legitimate system tools from user-writable directories. Defender correlates registry modifications, file creation of suspicious binaries, and process execution paths inconsistent with baseline system directories.', '{Windows}', 'x-mitre-analytic--bbd003ec-4208-48bb-9ad5-b9dd627fdd14', 'DET0004', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredRegistryKeys", "description": "PATH environment keys under HKCU and HKLM to monitor for changes."}, {"field": "SuspiciousBinaryList", "description": "List of high-value system binaries commonly hijacked (e.g., net.exe, python.exe, powershell.exe)."}, {"field": "TimeWindow", "description": "Correlation window between PATH modification and execution of a hijacked binary."}]', '2026-05-01 15:26:36.275788');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1284, 'AN0179', 'Analytic 0179', 'Behavioral chain: (1) browser/office/GUI mail client opens a URL, (2) outbound connection to untrusted domain, (3) a new file is saved in $HOME/Downloads, /tmp, or cache immediately after.', '{Linux}', 'x-mitre-analytic--bbfa2ed1-f8d5-44cf-9da8-5e3fed544172', 'DET0066', '[{"name": "auditd:SYSCALL", "channel": "execve: Execs of chromium, google-chrome, firefox, libreoffice with http(s) in cmdline", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "auditd:SYSCALL", "channel": "open,creat,rename: Writes in $HOME/Downloads, /tmp, ~/.cache with exe/script/archive/office extensions", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Suspicious URL patterns, uncommon TLDs, URL shorteners", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Typical 10–20m between click and write."}, {"field": "UserPaths", "description": "$HOME/Downloads, /tmp, ~/.cache, ~/.local/share."}, {"field": "HighRiskExtensions", "description": "exe, elf, sh, js, py, jar, iso, img, zip, rar, xlsm, docm, xll."}, {"field": "DomainRiskScore", "description": "Heuristic or TI score threshold for domains."}]', '2026-05-01 15:26:36.277321');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1285, 'AN1302', 'Analytic 1302', 'Detects embedded macros or scripts added to shared documents or use of external references to execute code.', '{"Office Suite"}', 'x-mitre-analytic--bc143cf2-d6fb-4ea4-98a5-a2db81fc3f84', 'DET0471', '[{"name": "m365:defender", "channel": "OfficeTelemetry or DLP", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "MacroExecutionPolicy", "description": "Controls macro execution based on user or group policy."}, {"field": "SuspiciousKeywordMatch", "description": "Regex match on suspicious VBA function names or calls."}]', '2026-05-01 15:26:36.278642');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1286, 'AN0926', 'Analytic 0926', 'Changes to NAT/firewall policies enabling outbound port forwarding from internal IPs to Internet-based proxy endpoints. Log spikes in outbound flows to CDN, VPS, or anomalous ASNs with few return packets.', '{"Network Devices"}', 'x-mitre-analytic--bca44b88-4615-45b8-8fb9-ce934c65c8be', 'DET0325', '[{"name": "Firewall Audit Logs", "channel": "Outbound NAT Rule Changes", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"name": "NSM:Flow", "channel": "Outbound flow records", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "networkdevice:syslog", "channel": "Dynamic route changes", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "FlowThreshold", "description": "Number of flows or bytes transferred per minute—flag surges to unrecognized ASNs."}, {"field": "DestinationIPCategory", "description": "Proxy destination categories: CDN, TOR exit node, anonymous hosting."}, {"field": "ConfigChangeUser", "description": "Track if unexpected user or automation changed NAT/forwarding rules."}]', '2026-05-01 15:26:36.280333');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1287, 'AN1391', 'Analytic 1391', 'Detects symmetric key-based encryption operations (e.g., AES via Python, AppleScript, or OpenSSL) followed by unusual outbound connections from non-browser applications or scripted tools.', '{macOS}', 'x-mitre-analytic--bcab4073-2316-4685-be6c-fb5ab92b22be', 'DET0503', '[{"name": "macos:unifiedlog", "channel": "log stream process subsystem", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:unifiedlog", "channel": "log stream network activity", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ApplicationProfileBaseline", "description": "Expected outbound connection profiles per app."}, {"field": "EncryptionRoutinePattern", "description": "Indicators of manual encryption operations (e.g., script strings invoking AES)."}]', '2026-05-01 15:26:36.281832');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1288, 'AN0173', 'Analytic 0173', 'Detects native Python or framework-based execution from Terminal, embedded apps, or launchd jobs. Flags network calls, persistence writes, or system enumeration after Python launch.', '{macOS}', 'x-mitre-analytic--bcac4672-778d-4b35-8b75-eaaf84b91853', 'DET0063', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate ''eventMessage contains \"python\"''", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:syslog", "channel": "system.log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ExecutionPath", "description": "Detects python scripts from ~/Downloads/, /Volumes/, or /tmp/."}, {"field": "ScriptName", "description": "Obfuscated or high entropy script names."}, {"field": "SpawnChain", "description": "Chained behavior: Python → bash → curl or Python → osascript."}]', '2026-05-01 15:26:36.283109');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1416, 'AN1266', 'Analytic 1266', 'Multiple sign-in failures against cloud-based applications using username/password combinations leaked from unrelated domains', '{SaaS}', 'x-mitre-analytic--cfff571f-eb6b-41e2-a447-f69bc07aa77a', 'DET0460', '[{"name": "saas-app:auth", "channel": "login_failure", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "UserAccountOverlap", "description": "Correlate credentials reused across multiple SaaS platforms"}, {"field": "FailedAttemptsPerIP", "description": "Number of failed logins from same IP before alerting"}]', '2026-05-01 15:26:36.471012');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1289, 'AN1076', 'Analytic 1076', 'Detects adversary use of suspended process creation, using the CREATE_SUSPENDED flag via CreateProcess, followed by unmapping the memory of the child process (NtUnmapViewOfSection) and replacing it with malicious code via VirtualAllocEx/WriteProcessMemory, then SetThreadContext and ResumeThread to begin execution within the hollowed process.', '{Windows}', 'x-mitre-analytic--bcb01d01-66f6-47bb-9ca1-46b4ce686ad4', 'DET0382', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "NtUnmapViewOfSection, VirtualAllocEx, WriteProcessMemory, SetThreadContext, ResumeThread", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "HollowedImageNamePattern", "description": "Regex to match common decoy executables used for hollowing (e.g., ''svchost.exe'', ''notepad.exe'')"}, {"field": "TimeWindow_ProcessCreateToResume", "description": "Temporal threshold for unmap/write/execute sequence (e.g., within 5–10 seconds)"}, {"field": "SuspendedProcessStartFlag", "description": "CreateProcess flag used to identify suspended thread creation"}, {"field": "MemoryWriteSizeThreshold", "description": "Minimum byte size to flag suspicious memory overwrite in hollowed process"}]', '2026-05-01 15:26:36.285413');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1290, 'AN1638', 'Analytic 1638', 'SSH login from a remote system (via sshd), followed by user context execution of suspicious binaries or privilege escalation behavior.', '{Linux}', 'x-mitre-analytic--bcc6bec5-63c7-4084-9d2f-da8b58d0f621', 'DET0596', '[{"name": "auditd:EXECVE", "channel": "EXECVE", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "NSM:Flow", "channel": "TCP port 22 traffic", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "Defines correlation window from login to first post-SSH process (e.g., 60s)"}, {"field": "SuspiciousProcessList", "description": "List of binaries considered unusual in SSH context (e.g., nc, base64, bash -i)"}, {"field": "UsernameFilter", "description": "Accounts of interest for SSH logins (e.g., root, admin)"}]', '2026-05-01 15:26:36.287094');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1291, 'AN1294', 'Analytic 1294', 'Untrusted processes creating outbound TLS/HTTPS connections with malformed certificates or header fields, often mismatched with target service behavior. Detects protocol impersonation attempts via traffic metadata analysis and host process lineage.', '{Windows}', 'x-mitre-analytic--bcf48294-2388-4ae6-be22-f9038c54e1db', 'DET0470', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "SSL/TLS Handshake Analysis", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "IssuerOrgFilter", "description": "Organizations in certificate issuer fields to allowlist or monitor."}, {"field": "UserContext", "description": "Restrict detection to non-system users or external-facing applications."}, {"field": "HeaderSignatureMatch", "description": "Specific HTTP header anomalies or patterns (e.g., missing User-Agent)."}]', '2026-05-01 15:26:36.288513');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1292, 'AN0456', 'Analytic 0456', 'Chain: (1) interactive/non-interactive `chage -l`, `grep`/`cat` of PAM config (e.g., `/etc/pam.d/common-password`, `/etc/security/pwquality.conf`); (2) optional reads of `/etc/login.defs`; (3) same user performs account enumeration or password change attempts shortly after. Use auditd `execve` and file read events plus shell history collection.', '{Linux}', 'x-mitre-analytic--bcf6e9cb-fee9-4efd-8998-03de4908448b', 'DET0161', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open,openat,read", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "linux:syslog", "channel": "sudo chage|grep pam_pwquality|cat /etc/login.defs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "MonitoredPaths", "description": "Exact PAM/QoP config files used by your distro (Debian vs. RHEL paths differ)."}, {"field": "ServiceAccountsExclude", "description": "System daemons that legitimately parse policies on boot."}, {"field": "TerminalType", "description": "TTY vs. non-interactive—raise risk for non-interactive remote execution."}]', '2026-05-01 15:26:36.29046');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1293, 'AN0430', 'Analytic 0430', 'Untrusted or unusual process/script (cmd.exe, powershell.exe, w32tm.exe, net.exe, custom binaries) queries system time/timezone (e.g., w32tm /tz, net time \\host, Get-TimeZone, GetTickCount API) and (optionally) is followed within a short window by time-based scheduling or conditional execution (e.g., schtasks /create, at.exe, PowerShell Start-Sleep with large values).', '{Windows}', 'x-mitre-analytic--bd34c127-9956-4616-999d-229f30512f74', 'DET0151', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "High-frequency or suspicious sequence of QueryPerformanceCounter/GetTickCount API calls from a non-standard process lineage", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:TaskScheduler", "channel": "EventCode=106", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "WinEventLog:TaskScheduler", "channel": "Task registration/execution shortly after a time discovery event", "x_mitre_data_component_ref": "x-mitre-data-component--7b375092-3a61-448d-900a-77c9a4bde4dc"}, {"name": "EDR:Telemetry", "channel": "Process lineage and API usage enrichment (GetSystemTime, GetTimeZoneInformation, NtQuerySystemTime)", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "TimeWindow", "description": "Correlation window (e.g., 5–15 minutes) between time discovery and follow-on scheduling/conditional actions."}, {"field": "AllowedParents", "description": "Legitimate parent processes (e.g., corporate scripts, management agents) that frequently call time APIs."}, {"field": "CommandlineKeywordList", "description": "Extend/restrict keyword list for time queries (e.g., custom PS functions, .NET calls)."}, {"field": "UserContextScope", "description": "Restrict to non-service, non-administrative, or newly created/rare users."}, {"field": "ProcessPrevalenceThreshold", "description": "Frequency threshold to exclude common estate-wide benign usage."}]', '2026-05-01 15:26:36.292164');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1294, 'AN0666', 'Analytic 0666', 'Adversary uses compromised instance credentials or web application access to deface content hosted in S3 buckets, Azure Blob Storage, or GCP Buckets.', '{IaaS}', 'x-mitre-analytic--bd893675-a17e-4c3b-bec4-ffbad6986c73', 'DET0238', '[{"name": "CloudTrail:PutObject", "channel": "PutObject", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "AWS:CloudTrail", "channel": "GetObject, CopyObject", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}]', '[{"field": "BucketNameRegex", "description": "Patterns of S3 or GCP buckets used for static website hosting may vary by organization."}, {"field": "IAMRoleContext", "description": "Some uploads may appear benign unless enriched with user/role metadata."}]', '2026-05-01 15:26:36.293902');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1295, 'AN0014', 'Analytic 0014', 'Execution of renamed common utilities (e.g., `bash`, `nc`, `python`, `sh`) from atypical directories or with names intended to deceive defenders or EDRs.', '{Linux}', 'x-mitre-analytic--bd8beea8-48c8-41dc-8991-f8c739d10c70', 'DET0005', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "event-based", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "linux:syslog", "channel": "cron activity", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ExecutionPath", "description": "Path anomalies such as execution from /dev/shm, /tmp, or user home directories"}, {"field": "ParentProcessContext", "description": "Unusual lineage such as scripts invoking renamed tools"}, {"field": "TimeWindow", "description": "Correlate between file rename and immediate execution"}]', '2026-05-01 15:26:36.295335');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1296, 'AN1370', 'Analytic 1370', 'Detects kill/systemctl/service commands against EDR, auditd, falco, osquery, rsyslog, journald, or agent processes; configuration edits disabling startup; module unload attempts; abrupt cessation of logs after privileged shell execution.', '{Linux}', 'x-mitre-analytic--bda03bab-3f0b-4bd0-8a8f-77bcb2b1ee7d', 'DET0497', '[{"name": "auditd:SYSCALL", "channel": "execve: systemctl stop, service stop, or kill -9 on security daemons (e.g., falcon-sensor, auditd)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:CONFIG_CHANGE", "channel": "delete: Modification of systemd unit files or config for security agents", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "AgentServiceNames", "description": "List of endpoint protection service names (varies across deployments)."}, {"field": "AllowedAdminAccounts", "description": "Accounts permitted to legitimately stop or reconfigure services."}]', '2026-05-01 15:26:36.297046');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1297, 'AN1016', 'Analytic 1016', 'Execution of ping, traceroute, or curl/wget against public IPs/domains to verify Internet reachability.', '{Linux}', 'x-mitre-analytic--bdba541c-3a01-4a6d-95ae-15e283f2909b', 'DET0357', '[{"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "network", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "DomainPatterns", "description": "Regex for common test domains like example.com, google.com"}, {"field": "ProtocolType", "description": "Adjust focus to ICMP, HTTP, or mixed protocol testing"}]', '2026-05-01 15:26:36.298348');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1298, 'AN0929', 'Analytic 0929', 'EndpointSecurity/Unified Logs show processes generating custom alphabets or long high-entropy, non-standard tokens → network logs (PF/Zeek/EDR) show asymmetric beacons, protocol mismatches, or periodic fixed-size posts.', '{macOS}', 'x-mitre-analytic--bdc546bb-9d92-489e-8aa8-8de1bd08f320', 'DET0326', '[{"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC: arguments contain long, non-standard tokens / custom alphabets", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "PF:Logs", "channel": "high out:in ratio or fixed-size periodic flows", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "http: suspicious long tokens with custom alphabets in body/headers", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "EntropyThreshold", "description": "Payload entropy minimum."}, {"field": "TokenLengthThreshold", "description": "Minimum suspicious token length."}, {"field": "BytesOutToInRatio", "description": "Asymmetry threshold."}, {"field": "TimeWindow", "description": "Correlation window."}, {"field": "AllowedSignedBinaries", "description": "Signed binaries that legitimately implement custom encoders."}]', '2026-05-01 15:26:36.299813');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1299, 'AN0574', 'Analytic 0574', 'Detects enumeration of VMs using PowerShell (`Get-VM`), VMware Workstation (`vmrun.exe`), or Hyper-V (`VBoxManage.exe`). Defender observes suspicious command lines executed by unexpected users or outside normal administrative sessions.', '{Windows}', 'x-mitre-analytic--be2239de-ae8e-442d-a9f6-d34460b94e94', 'DET0199', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExpectedAdminAccounts", "description": "Defines which accounts are authorized to execute VM discovery commands."}, {"field": "RoutineScripts", "description": "Whitelist of approved administrative scripts that legitimately invoke VM enumeration."}]', '2026-05-01 15:26:36.301087');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1300, 'AN1594', 'Analytic 1594', 'Detection of suspicious enumeration of cloud storage objects via API calls such as AWS S3 ListObjectsV2, Azure List Blobs, or GCP ListObjects. Correlate access with account role, user context, and prior authentication activity to identify anomalous usage patterns (e.g., unusual account, unexpected regions, or large-scale enumeration in short time windows).', '{IaaS}', 'x-mitre-analytic--be55aa59-62b5-40cd-bab2-dbc4de80da0e', 'DET0578', '[{"name": "AWS:CloudTrail", "channel": "ListObjectsV2", "x_mitre_data_component_ref": "x-mitre-data-component--fcc4811f-9cc8-4db5-8097-4d8242a380de"}, {"name": "AWS:CloudTrail", "channel": "GetObject, CopyObject", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}]', '[{"field": "TimeWindow", "description": "Correlation window (e.g., multiple enumeration calls within 5 minutes) may indicate automated discovery versus normal user activity."}, {"field": "UserContext", "description": "Expected service accounts and IAM roles that regularly enumerate storage; deviations may indicate suspicious activity."}, {"field": "RegionScope", "description": "Unusual enumeration of buckets across multiple geographic regions in short succession may indicate adversary reconnaissance."}]', '2026-05-01 15:26:36.302393');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1301, 'AN0848', 'Analytic 0848', 'Enumeration of macOS local users using dscl, id, dscacheutil, or /etc/passwd access.', '{macOS}', 'x-mitre-analytic--be680af0-8d5f-482c-9042-f5d4921e65f8', 'DET0303', '[{"name": "macos:unifiedlog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLine", "description": "Monitor dscl . list /Users, dscacheutil -q user, id -un."}, {"field": "InteractiveSession", "description": "Focus on enumeration from non-console users or untrusted apps."}]', '2026-05-01 15:26:36.303683');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1417, 'AN1342', 'Analytic 1342', 'Failed authentication attempts across user mailboxes using identical or common passwords (e.g., OWA brute attempts)', '{"Office Suite"}', 'x-mitre-analytic--cfffc717-79f1-4aea-9e68-475ef52db11d', 'DET0487', '[{"name": "m365:exchange", "channel": "FailedLogin", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "MailboxAccessAttempts", "description": "Threshold on mailbox login failures by same IP"}, {"field": "EmailPatternAnalysis", "description": "Match target usernames to common spray dictionaries"}]', '2026-05-01 15:26:36.472517');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1303, 'AN1620', 'Analytic 1620', 'Detection of suspicious use of `tscon.exe` or equivalent methods to hijack legitimate RDP sessions. Defenders can observe anomalies such as session reassignments without corresponding authentication, processes spawned in the context of hijacked sessions, or unusual RDP network traffic flows that deviate from expected baselines.', '{Windows}', 'x-mitre-analytic--be773ad4-9e5f-4063-910a-99a3cab90582', 'DET0588', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "ExpectedRDPHosts", "description": "Whitelist of systems and accounts authorized to use RDP; deviations indicate possible hijacking."}, {"field": "TimeWindow", "description": "Time threshold for correlating logon events with session reassignment and process execution."}, {"field": "SessionIDMapping", "description": "Environment-specific mapping of user accounts to session IDs; inconsistencies may reveal hijacking."}]', '2026-05-01 15:26:36.306627');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1304, 'AN1169', 'Analytic 1169', 'Detects FTP, SMB, or TFTP traffic initiated by suspicious processes like PowerShell, cmd.exe, or rundll32.exe—especially with large outbound file transfers or unbalanced traffic volume.', '{Windows}', 'x-mitre-analytic--befbbdad-a17b-41f2-bb24-5cb477c5cc50', 'DET0416', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "ftp.log, smb_files.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ProcessImageFilter", "description": "Limit to non-standard FTP clients or suspicious binaries (e.g., cmd, mshta)"}, {"field": "DataFlowDirectionThreshold", "description": "Ratio of outbound:inbound bytes; e.g., >90% outbound"}, {"field": "FilenamePattern", "description": "Suspicious file extensions or naming (e.g., .zip, .rar, random hash names)"}]', '2026-05-01 15:26:36.308635');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1305, 'AN0818', 'Analytic 0818', 'Detects suspicious changes to SAML/OAuth federation configurations, such as new signing certificates, altered endpoints, or claims issuance rules granting elevated privileges.', '{SaaS}', 'x-mitre-analytic--bf166688-0c78-43a5-bb87-3159c1b86584', 'DET0293', '[{"name": "saas:okta", "channel": "Federation configuration update or signing certificate change", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "FederationEndpoints", "description": "Federation/SAML endpoints monitored for modification."}]', '2026-05-01 15:26:36.310418');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1306, 'AN0152', 'Analytic 0152', 'Detection of adversary attempts to enumerate Group Policy settings through suspicious command execution (gpresult), PowerShell enumeration (Get-DomainGPO, Get-DomainGPOLocalGroup), and abnormal LDAP queries targeting groupPolicyContainer objects. Defenders observe unusual process lineage, script execution, or LDAP filter activity against domain controllers.', '{Windows}', 'x-mitre-analytic--bf5772b8-86b4-4d73-bbff-6abb5da9edac', 'DET0055', '[{"name": "WinEventLog:Security", "channel": "EventCode=4661", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "query: High-volume LDAP traffic with filters targeting groupPolicyContainer attributes", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Defines the correlation window to link suspicious PowerShell activity, gpresult execution, and LDAP enumeration."}, {"field": "UserContext", "description": "Identifies accounts expected to perform GPO enumeration (administrators vs. standard users)."}, {"field": "CommandLinePatterns", "description": "Patterns for detecting suspicious gpresult or PowerShell cmdlets; tunable to reduce noise in environments where these tools are common."}]', '2026-05-01 15:26:36.311794');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1307, 'AN1293', 'Analytic 1293', 'Defenders may observe adversary attempts to patch system images by monitoring for anomalous file transfers (TFTP, SCP, FTP) of image files, unauthorized CLI commands altering boot system variables, integrity check mismatches between running and baseline OS images, and runtime memory manipulation attempts. Suspicious sequences include uploading a new image, modifying boot parameters, and subsequent reload/reboot of the device. In-memory patching attempts may manifest as debug commands or boot loader manipulation inconsistent with normal administrative activity.', '{"Network Devices"}', 'x-mitre-analytic--bf64c48c-5834-426c-be21-6db0efbc7909', 'DET0469', '[{"name": "networkdevice:cli", "channel": "Execution of privileged commands such as ''copy tftp flash'', ''boot system'', or ''debug memory''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:config", "channel": "Configuration changes to startup image paths, boot loader parameters, or debug flags", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "firmware:runtime", "channel": "Debug or memory access commands indicating attempts to alter OS instructions in memory", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}]', '[{"field": "ApprovedFirmwareVersions", "description": "Whitelist of validated vendor OS versions; deviations may indicate tampering."}, {"field": "AuthorizedAdminAccounts", "description": "Trusted admin accounts permitted to update images; anomalies suggest compromise."}, {"field": "ChecksumBaseline", "description": "Baseline hash of approved images; used for detecting file tampering."}, {"field": "TimeWindow", "description": "Correlation period for detecting chained behaviors (file upload → boot config change → reboot)."}]', '2026-05-01 15:26:36.313097');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1308, 'AN0089', 'Analytic 0089', 'Execution of binaries with invalid digital signatures, where metadata claims code is signed but validation fails. Behavior is often correlated with suspicious parent processes or unexpected execution paths.', '{Windows}', 'x-mitre-analytic--bf6b3f42-a7a5-4e6d-840a-e892aa74916c', 'DET0031', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Windows Defender", "channel": "Operational log", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SignatureValidationResult", "description": "Allow tuning to include ''invalid'', ''expired'', or ''untrusted root'' based on environment tolerance"}, {"field": "ParentProcessName", "description": "Helps tune false positives by limiting to suspicious parent process executions"}, {"field": "TimeWindow", "description": "Defines correlation window between metadata check and process execution"}]', '2026-05-01 15:26:36.314348');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1309, 'AN1241', 'Analytic 1241', 'Detects the redirection of syscall execution flow via modification of VDSO code stubs or GOT entries to load and execute a malicious shared object through mmap and ptrace.', '{Linux}', 'x-mitre-analytic--bfc7e981-ca7e-4b1b-a692-65a8867a7a89', 'DET0448', '[{"name": "auditd:SYSCALL", "channel": "ptrace, mmap, mprotect, open, dlopen", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "auditd:memprotect", "channel": "change from PROT_READ|PROT_WRITE to PROT_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "auditd:file-events", "channel": "open of suspicious .so from non-standard paths", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "linux:osquery", "channel": "child process invoking dynamic linker post-ptrace", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SuspiciousSharedObjectPathRegex", "description": "Regex to filter dynamic library paths outside of `/lib`, `/usr/lib`, etc. (e.g., `/tmp`, `/dev/shm`)"}, {"field": "TimeWindow_PtraceToMmap", "description": "Max delay allowed between ptrace attach and mmap/mprotect execution in target process"}, {"field": "ExecMemoryProtectionThreshold", "description": "Flag when executable memory mappings deviate from normal runtime behavior"}, {"field": "AnomalousParentProcessList", "description": "Parent processes unlikely to legitimately call ptrace (e.g., nginx, apache2, sshd)"}]', '2026-05-01 15:26:36.315826');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1310, 'AN1202', 'Analytic 1202', 'Monitor email message traces and headers for failed SPF, DKIM, or DMARC checks indicating spoofed sender identities. Correlate abnormal sender domains or mismatched return-paths with elevated spoofing likelihood.', '{Windows}', 'x-mitre-analytic--c0055eb3-5579-48a8-b9d3-df6dd67bc388', 'DET0431', '[{"name": "m365:messagetrace", "channel": "AuthenticationDetails=fail OR SPF=fail OR DKIM=fail OR DMARC=fail", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "SpoofScoreThreshold", "description": "Defines sensitivity to SPF/DKIM/DMARC failures; higher thresholds reduce false positives but may miss stealthier spoofing."}, {"field": "MonitoredDomains", "description": "Specifies which domains to enforce strict validation against; enterprise-specific tuning may be required."}]', '2026-05-01 15:26:36.317321');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1311, 'AN1962', 'Analytic 1962', 'Monitor network data for uncommon data flows. Processes utilizing the network that do not normally have network communication or have never been seen before are suspicious.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1312, 'AN0232', 'Analytic 0232', 'Adversary modifies ESXi host login banner or MOTD file (/etc/motd), either through SSH or host console access. May involve configuration file overwrite or API calls from compromised vSphere clients.', '{ESXi}', 'x-mitre-analytic--c024ed9a-02bf-436d-93f5-444e45124e2f', 'DET0082', '[{"name": "ESXiLogs:messages", "channel": "changes to /etc/motd or /etc/vmware/welcome", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "esxi:hostd", "channel": "modification of config files or shell command execution", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "LoginBannerFilePath", "description": "Target file paths (e.g., /etc/motd) may be changed via symbolic link or override"}, {"field": "AccessOrigin", "description": "ESXi hostd vs. SSH-based defacement origin may affect visibility"}]', '2026-05-01 15:26:36.319739');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1313, 'AN0390', 'Analytic 0390', 'Detects credential interception via malicious LD_PRELOAD-based shared libraries loaded into ssh, sudo, or scp processes. Correlates environment variable injection, unexpected library loads, and memory patching behavior.', '{Linux}', 'x-mitre-analytic--c031c27b-4d05-406a-8538-04ce1df41d35', 'DET0139', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "LD_PRELOAD Logging", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "InjectedLibraryName", "description": "Watch for user-defined suspicious .so files (e.g., libhook.so, libshadow.so)"}, {"field": "TargetProcessName", "description": "Hooked binaries vary by use case (e.g., ssh, login, gdm)"}]', '2026-05-01 15:26:36.321119');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1455, 'AN1509', 'Analytic 1509', 'Malicious use of webserver plugins (e.g., for nginx, PHP, Node.js) that execute AppleScript or open network sockets.', '{macOS}', 'x-mitre-analytic--d5af4c93-632c-41c3-a101-6e9e534d7d01', 'DET0547', '[{"name": "macos:unifiedlog", "channel": "Script interpreter invoked by nginx/apache worker process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Web server process initiating outbound TCP connections not tied to normal server traffic", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ParentBinaryPath", "description": "If homebrew or manually compiled nginx/httpd used, baseline accordingly."}]', '2026-05-01 15:26:36.527285');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1314, 'AN0383', 'Analytic 0383', 'Detection of unauthorized modification of Active Directory SID-History attributes to escalate privileges. This chain involves: (1) privileged operations or API calls to DsAddSidHistory or related AD modification functions, (2) observed attribute changes in SID-History (Event ID 5136), (3) new logon sessions where the token includes unexpected or privileged SID-History values, and (4) follow-on resource access using elevated privileges derived from SID-History injection.', '{Windows}', 'x-mitre-analytic--c061d938-cafa-4e9d-8729-29d63ba633ad', 'DET0136', '[{"name": "WinEventLog:Security", "channel": "EventCode=5136", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:Security", "channel": "EventCode=4720, 4738", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "etw:Microsoft-Windows-Directory-Services-SAM", "channel": "api_call: Calls to DsAddSidHistory or related RPC operations", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "AllowedSIDHistoryChanges", "description": "Approved migration windows or known SID-History population events."}, {"field": "TimeWindow", "description": "Correlation window between attribute change and suspicious logon activity (default 15–30 minutes)."}, {"field": "PrivilegedSIDList", "description": "List of sensitive SIDs (e.g., Enterprise Admins, Domain Admins) that should never appear in SID-History."}, {"field": "UserContextFilter", "description": "Exclude trusted migration service accounts or pre-approved administrative tasks."}, {"field": "AnomalousSIDCountThreshold", "description": "Raise alerts when a token contains more than X SID-History entries (default X=2)."}]', '2026-05-01 15:26:36.32244');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1315, 'AN1474', 'Analytic 1474', 'Unauthorized modification of TCC.db followed by elevated process execution under a trusted parent (e.g., Finder, SystemUIServer) or via launchctl environment override. Also includes identification of SIP being disabled, which is highly uncommon and a prerequisite for this abuse path.', '{macOS}', 'x-mitre-analytic--c0766f2c-e282-44a1-8dcf-1575d77658da', 'DET0534', '[{"name": "macos:unifiedlog", "channel": "Execution of binaries with TCC protected access under unexpected parent processes such as Finder.app, SystemUIServer, or nsurlsessiond", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Modification or replacement of /Library/Application Support/com.apple.TCC/TCC.db or ~/Library/Application Support/com.apple.TCC/TCC.db", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Execution of launchctl with setenv or bootout targeting TCC.db or AppleScript under Finder context", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "System Integrity Protection (SIP) state reported as disabled", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "ParentProcessName", "description": "May vary across macOS versions and user contexts; defenders can tune for known benign cases."}, {"field": "TCCModificationPath", "description": "Custom user paths or redirected SQLite DBs may require alternate matching logic."}, {"field": "TimeWindow", "description": "Temporal proximity between launchctl setenv and subsequent privileged access can be tuned."}, {"field": "SIPStateCheckInterval", "description": "Frequency of SIP integrity checks may vary based on system hardening policies."}]', '2026-05-01 15:26:36.324268');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1316, 'AN1097', 'Analytic 1097', 'Monitor for runtime data manipulations by detecting suspicious modification of application binaries, API hooking, or unexpected behavior from processes responsible for rendering or displaying data. Correlate registry edits, process creation, and unexpected binary hash mismatches.', '{Windows}', 'x-mitre-analytic--c07e8730-b5cf-4a74-be3a-938184af42df', 'DET0391', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "MonitoredPaths", "description": "Directory paths of business-critical applications where runtime manipulations are most impactful."}, {"field": "HashBaseline", "description": "Expected cryptographic hashes of application binaries used for runtime data display."}]', '2026-05-01 15:26:36.325788');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1317, 'AN1445', 'Analytic 1445', 'Detects attempts to forge or replay Kerberos tickets by monitoring Unified Logs for anomalous kinit/klist activity and correlating unusual authentication sequences.', '{macOS}', 'x-mitre-analytic--c08ad617-cc0d-4435-9168-08c762048503', 'DET0522', '[{"name": "macos:unifiedlog", "channel": "Unusual Kerberos TGS-REQ without TGT or anomalous ticket lifetime", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "TicketRequestPatterns", "description": "Expected sequence of TGT followed by TGS requests; deviations may indicate forgery."}, {"field": "TicketLifetime", "description": "Expected ticket lifetimes; anomalies may indicate Golden or Silver Tickets."}]', '2026-05-01 15:26:36.327042');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1318, 'AN1100', 'Analytic 1100', 'Adversary spawns a process or script to enumerate installed software using WMI, registry, or PowerShell, potentially followed by additional discovery or evasion behavior.', '{Windows}', 'x-mitre-analytic--c0bbe0a5-680f-487b-8f5f-27703efb52b7', 'DET0392', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "Execution of ''Get-WmiObject Win32_Product'' or similar PowerShell cmdlets", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindow", "description": "Detection may be scoped to multiple discovery commands within a short timeframe."}, {"field": "ParentProcess", "description": "Tuning based on whether discovery activity stems from suspicious versus approved management tools."}]', '2026-05-01 15:26:36.328201');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1319, 'AN1444', 'Analytic 1444', 'Detects suspicious access to SSSD secrets database and Kerberos key material indicating ticket theft or replay attempts. Correlates anomalous file access with unusual Kerberos service ticket requests.', '{Linux}', 'x-mitre-analytic--c101374a-ce7a-46d7-b7d4-c64fbdf1f685', 'DET0522', '[{"name": "auditd:SYSCALL", "channel": "Access to /var/lib/sss/secrets/secrets.ldb or .secrets.mkey", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:syslog", "channel": "Unusual kinit or klist activity", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}]', '[{"field": "SecretsAccessThreshold", "description": "Alert threshold for frequency of access to Kerberos secrets files."}, {"field": "UnusualServiceAccounts", "description": "Baseline accounts normally performing Kerberos requests; anomalies flagged."}]', '2026-05-01 15:26:36.329558');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1320, 'AN1056', 'Analytic 1056', 'Monitor for creation or modification of udev rules files in key directories (/etc/udev/rules.d/, /lib/udev/rules.d/, /usr/lib/udev/rules.d/). Look for RUN+= or IMPORT keys invoking suspicious binaries or scripts. Correlate this with process execution from systemd-udevd context, and file writes near udev reload/restart events. Combine this with unexpected background process spawning from udevd-related forks.', '{Linux}', 'x-mitre-analytic--c1167779-9df4-4387-b777-4da097c6b033', 'DET0375', '[{"name": "auditd:SYSCALL", "channel": "chmod, write, create, open", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:CONFIG_CHANGE", "channel": "udev rule reload or trigger command executed", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "UdevRulePath", "description": "Path to udev rules (may vary by distro or user configuration)"}, {"field": "SuspiciousRunPattern", "description": "Regex or string pattern to flag suspicious command executions in RUN+="}, {"field": "TimeWindow", "description": "Max interval between rule change and execution to correlate activity"}, {"field": "ParentProcess", "description": "Expected parent of RUN-invoked commands (e.g., systemd-udevd)"}]', '2026-05-01 15:26:36.330801');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1321, 'AN1101', 'Analytic 1101', 'Adversary invokes ''dpkg -l'', ''rpm -qa'', or other package managers via shell or script to enumerate installed software.', '{Linux}', 'x-mitre-analytic--c14042f6-5ebd-42a2-b293-b2367b300fb6', 'DET0392', '[{"name": "auditd:SYSCALL", "channel": "Execution of dpkg, rpm, or other package manager with list flag", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:shell", "channel": "Manual invocation of software enumeration commands via interactive shell", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ScriptName", "description": "Path to the wrapper script that invokes enumeration commands."}, {"field": "TTYContext", "description": "Scope detection to interactive vs. background shell contexts."}]', '2026-05-01 15:26:36.332975');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1322, 'AN0525', 'Analytic 0525', 'Detects deletion or hiding of security-related mail rules, audit mailboxes, or calendar/log sync artifacts indicative of tampering post-intrusion.', '{"Office Suite"}', 'x-mitre-analytic--c15d6b5e-bbb7-4dc7-8b59-8ce2c0663c05', 'DET0184', '[{"name": "m365:exchange", "channel": "Remove-InboxRule, Clear-Mailbox", "x_mitre_data_component_ref": "x-mitre-data-component--faa34cf6-cf32-4dc9-bd6a-8f7a606ff65b"}, {"name": "m365:unified", "channel": "PurgeAuditLogs, Remove-MailboxAuditLog", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TargetMailboxScope", "description": "Limit by VIP mailboxes or external-facing users"}, {"field": "AuditLogDepth", "description": "Tune for log deletion following lateral movement"}]', '2026-05-01 15:26:36.334178');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1323, 'AN0823', 'Analytic 0823', 'Detects suspicious DNS/ARP poisoning attempts, unauthorized modifications to registry/network configuration, or abnormal TLS downgrade activity. Correlates changes in system configuration with subsequent unusual network flows or authentication events.', '{Windows}', 'x-mitre-analytic--c15f60a8-6e58-460f-8dcf-1bce272b5eaf', 'DET0296', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "MonitoredRegistryPaths", "description": "Specific network stack and DNS registry keys that vary by enterprise configuration."}, {"field": "DowngradeCipherList", "description": "List of weak/legacy ciphers tuned per environment for TLS downgrade detection."}, {"field": "TimeWindow", "description": "Correlation period between config changes and abnormal network connections."}]', '2026-05-01 15:26:36.335452');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1324, 'AN0463', 'Analytic 0463', 'Process creates a raw/packet socket and attaches a (e)BPF filter (setsockopt SO_ATTACH_FILTER/ATTACH_BPF or bpf(BPF_PROG_LOAD)). Immediately after a matching inbound packet, the same process binds/connects outward to a remote host (reverse shell or beacon).', '{Linux}', 'x-mitre-analytic--c19f8f89-76f9-4345-8bb6-a065fba50bff', 'DET0162', '[{"name": "auditd:SYSCALL", "channel": "socket(AF_PACKET|AF_INET, SOCK_RAW, *), setsockopt(… SO_ATTACH_FILTER|SO_ATTACH_BPF …), bpf(cmd=BPF_PROG_LOAD), open/openat path=\"/dev/bpf*\" (BSD/macOS-like) or setcap cap_net_raw.", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "family=AF_PACKET or protocol raw; process name not in allowlist.", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Rare inbound packet characteristics (ICMP/UDP/TCP to uncommon port) from src_ip followed ≤TimeWindow by outbound SF from same host to src_ip.", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "UserContext", "description": "Flag raw-socket activity outside privileged daemons (root-only by default)."}, {"field": "MinPayloadEntropy", "description": "If using packet content (Zeek), treat high-entropy single-packet triggers as suspicious."}, {"field": "AFPacketAllowList", "description": "System services allowed to open AF_PACKET (dhclient, keepalived, LLDP, monitoring agents)."}]', '2026-05-01 15:26:36.336652');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1325, 'AN0207', 'Analytic 0207', 'ESXi shell execution of tools/scripts (`nc`, `socat`, `perl`) relaying network traffic to other internal hosts, especially when initiated by unauthorized users or VMs.', '{ESXi}', 'x-mitre-analytic--c1fd84b0-953d-463b-a293-3d6aa81e4589', 'DET0075', '[{"name": "esxi:shell", "channel": "/var/log/shell.log", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "esxi:vmkernel", "channel": "/var/log/vmkernel.log", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "CLICommandPattern", "description": "Watch for chained shell commands building local-to-local connections."}, {"field": "VMInitiator", "description": "Correlate to which VM initiated the traffic tunnel; unexpected VM behavior may be suspicious."}, {"field": "ConnectionDirectionality", "description": "Unusual east-west communication patterns among VMs."}]', '2026-05-01 15:26:36.337817');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1475, 'AN1618', 'Analytic 1618', 'Account enumeration via bulk access to user directory features or hidden APIs.', '{SaaS}', 'x-mitre-analytic--d85db7b4-5eb1-4781-b92c-a18102a568dc', 'DET0587', '[{"name": "gcp:audit", "channel": "Directory API Access", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "EndpointURL", "description": "Tune based on enumeration from directory endpoints such as /users, /groups."}, {"field": "UserAgent", "description": "Detect scripted enumeration via curl/wget or unknown tools."}]', '2026-05-01 15:26:36.557771');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1326, 'AN1243', 'Analytic 1243', 'Monitor kernel module load/unload activity via modprobe, insmod, rmmod, or direct manipulation of /lib/modules. Correlate with installation of kernel headers, compilation commands, or downloads of .ko files. Detect anomalies in unsigned module loading or repeated module load attempts under non-root users.', '{Linux}', 'x-mitre-analytic--c221d379-1dcb-4ca7-908e-59f6ed7afaed', 'DET0450', '[{"name": "auditd:SYSCALL", "channel": "Execution of insmod, modprobe, or rmmod commands by non-standard users or outside expected timeframes", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "Access or modification to /lib/modules or creation of .ko files", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "linux:osquery", "channel": "New or modified kernel object files (.ko) within /lib/modules directory", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "UserContext", "description": "Scope detection to non-root or unexpected users performing module-related activity"}, {"field": "TimeWindow", "description": "Limit alerts to module activity outside approved change windows"}, {"field": "FilePathRegex", "description": "Adjust regex pattern for directories to monitor depending on kernel version or distro"}]', '2026-05-01 15:26:36.339112');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1327, 'AN0341', 'Analytic 0341', 'Behavioral correlation of privileged registry key creation under the W32Time TimeProviders path combined with a new DLL written to disk and potential process activity by LocalService. Indicates abuse of Time Providers for persistence.', '{Windows}', 'x-mitre-analytic--c223f997-8323-40c2-98c9-38a8a1779db4', 'DET0122', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "RegistryPathScope", "description": "May need to be tuned to only monitor `W32Time\\TimeProviders` subkey path for performance optimization"}, {"field": "UserContext", "description": "Should focus on activity from administrative or SYSTEM accounts"}, {"field": "TimeWindow", "description": "Controls correlation window between registry modification and DLL drop"}, {"field": "DllPathEntropyThreshold", "description": "Used for anomaly scoring on DLL path patterns (e.g., random names or temp directories)"}]', '2026-05-01 15:26:36.340684');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1328, 'AN0037', 'Analytic 0037', 'Access to browser artifact locations (e.g., Chrome, Edge, Firefox) by processes like PowerShell, cmd.exe, or unknown tools, followed by file reads, decoding, or export operations indicating enumeration of bookmarks, autofill, or history databases.', '{Windows}', 'x-mitre-analytic--c233a50c-0fdb-412b-85f6-8ff71a3539b9', 'DET0013', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TargetPathRegex", "description": "Location of browser data folders like %APPDATA%\\Google\\Chrome\\User Data or %APPDATA%\\Mozilla\\Firefox"}, {"field": "ParentProcess", "description": "Used to exclude known browser maintenance or backup processes"}, {"field": "ScriptBlockPattern", "description": "Used to detect suspicious PowerShell commands targeting browser data"}]', '2026-05-01 15:26:36.34208');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1329, 'AN1306', 'Analytic 1306', 'Linux environmental keying behavioral chain: (1) System information gathering through native commands (uname, hostname, id, whoami, ifconfig/ip) and file system enumeration, (2) Network configuration discovery (route tables, DNS settings, network interfaces), (3) Filesystem and mount point analysis for target-specific directories or devices, (4) Process and service enumeration to identify target-specific software, (5) Cryptographic library usage correlation with collected environmental data, (6) Payload execution following successful environmental validation', '{Linux}', 'x-mitre-analytic--c24eb4e0-f23a-4d93-b2e0-7f5e7cae44f6', 'DET0474', '[{"name": "auditd:SYSCALL", "channel": "execve syscalls for discovery commands (uname, hostname, id, whoami, ps, netstat, mount) with command-line parameter analysis", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:syslog", "channel": "kernel messages related to cryptographic operations, module loading, and filesystem access patterns", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "DiscoveryCommandSequenceThreshold", "description": "Number of distinct discovery commands within time window to trigger detection - adjust based on normal system administration patterns in environment"}, {"field": "ProcessAncestryDepth", "description": "Depth of process parent-child relationships to analyze for discovery activity clustering - balance between detection efficacy and performance"}, {"field": "CryptographicLibraryIndicators", "description": "Shared libraries and system calls indicating cryptographic operations (libcrypto, libssl, openssl) - customize based on environment-specific crypto tools"}, {"field": "TargetSpecificFilesystems", "description": "Organization-specific mount points, network filesystems, or device paths that adversaries might validate against"}, {"field": "AuthorizedDiscoveryUsers", "description": "User accounts and service accounts authorized for extensive system discovery operations - maintain for false positive reduction"}, {"field": "NetworkConfigurationBaseline", "description": "Normal network interface configurations and routing tables to identify anomalous network discovery patterns"}, {"field": "ContainerContextIdentifiers", "description": "Container runtime identifiers and namespace patterns to detect environmental assessment targeting container environments"}]', '2026-05-01 15:26:36.3435');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1330, 'AN1227', 'Analytic 1227', 'Detects applications using abnormal protocols or high volume traffic not previously associated with the process image, such as Automator or AppleScript invoking curl or python sockets.', '{macOS}', 'x-mitre-analytic--c2b959ca-75f4-4291-9812-0b065e7bb395', 'DET0444', '[{"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:unifiedlog", "channel": "log stream", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SocketParentProcessMatch", "description": "Non-browser processes opening sockets to external IPs"}, {"field": "DataFlowImbalanceRatio", "description": "High outbound/inbound ratio indicating C2 beacon"}]', '2026-05-01 15:26:36.344856');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1348, 'AN0369', 'Analytic 0369', 'Detects non-native file transfer via curl, Python scripts, or AppleScript using uncommon protocols like FTP, SMTP, or DNS exfiltration through mDNSResponder abuse.', '{macOS}', 'x-mitre-analytic--c545f39e-d1a2-4b0e-bdf1-6a84226557e9', 'DET0131', '[{"name": "macos:unifiedlog", "channel": "log stream (subsystem: com.apple.system.networking)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ProtocolUnusualnessScore", "description": "Weight rarely-used protocols in user space."}, {"field": "ExecutableBaselining", "description": "Track which binaries usually call curl/nc and alert on deviation."}]', '2026-05-01 15:26:36.371148');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1331, 'AN0693', 'Analytic 0693', 'Remote/API driven creation **and** start of a container whose image is not on an allow‑list (or is tagged `latest`), executed by a non-admin principal, and/or started with risky runtime attributes (e.g., `--privileged`, host PID/NET namespaces, sensitive host path mounts, capability adds). Correlates *create* ➜ *start* ➜ first network/process actions from that container within a short time window.', '{Containers}', 'x-mitre-analytic--c345908d-4f74-4341-a203-8c76be2a136b', 'DET0249', '[{"name": "docker:daemon", "channel": "container_create,container_start", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "containerd:runtime", "channel": "CRI CreateContainer/StartContainer with privileged=true OR added capabilities OR host* namespaces", "x_mitre_data_component_ref": "x-mitre-data-component--5fe82895-28e5-4aac-845e-dc886b63be2e"}, {"name": "ebpf:syscalls", "channel": "process execution or network connect from just-created container PID namespace", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "docker:events", "channel": "remote API calls to /containers/create or /containers/{id}/start", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "known_images", "description": "Environment-specific allow-list of approved images (with digests)."}, {"field": "known_admins", "description": "Service accounts or CI/CD users permitted to deploy containers."}, {"field": "TimeWindow", "description": "Max time between create, start, and first activity to consider events causally linked (default 5m)."}, {"field": "RiskThreshold", "description": "Minimum number of risky attributes (e.g., unknown image + privileged) to alert."}, {"field": "PrivilegedFlags", "description": "Set of runtime flags considered high risk (e.g., --privileged, --cap-add=SYS_ADMIN, hostPID, hostNetwork, /var/run/docker.sock mount)."}]', '2026-05-01 15:26:36.346324');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1332, 'AN1340', 'Analytic 1340', 'Authentication failure logs on routers/switches showing repeated use of default or common passwords across multiple accounts', '{"Network Devices"}', 'x-mitre-analytic--c35bd9de-acd9-41f9-9e4f-2a3aad461de6', 'DET0487', '[{"name": "networkdevice:syslog", "channel": "AAA or TACACS authentication failures", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AuthFailureBurst", "description": "Cluster of failed attempts in short period indicating spray"}, {"field": "InterfaceFilter", "description": "Limit detection to console/SSH vs web UI interfaces"}]', '2026-05-01 15:26:36.347585');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1333, 'AN1398', 'Analytic 1398', 'Adversary gains high integrity or special privileges (e.g., SeDebugPrivilege), locates a running browser process, opens it with write/inject rights, and modifies it (e.g., CreateRemoteThread / DLL load) to inherit cookies/tokens or establish a browser pivot. Optional step: create a new logon session or use explicit credentials, then drive the victim browser to intranet resources.', '{Windows}', 'x-mitre-analytic--c3629243-7cd6-4e56-9275-73f5752f0f08', 'DET0507', '[{"name": "WinEventLog:Security", "channel": "EventCode=4672", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Security", "channel": "EventCode=4673", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "BrowserList", "description": "Set of monitored browsers (chrome.exe, msedge.exe, firefox.exe, iexplore.exe). Adjust per fleet."}, {"field": "AccessMaskSet", "description": "Access rights implying injection (e.g., 0x1FFFFF, 0x1F3FF, VM_WRITE, VM_OPERATION, CREATE_THREAD). Tune by EDR mapping."}, {"field": "SignerAllowList", "description": "Allowed module signers within browser processes (e.g., Microsoft, Google). Helps flag unsigned/unknown ImageLoad into browsers."}, {"field": "InternalCIDR", "description": "Enterprise internal ranges or DNS suffixes to identify intranet pivoting via the browser."}, {"field": "TimeWindow", "description": "Correlation interval (e.g., 10–20 minutes) linking privilege gain → access → modification → network usage."}, {"field": "ParentAllowList", "description": "Legitimate tools that may automate browsers (e.g., Selenium drivers). Reduce FPs by allowlisting."}, {"field": "UserContext", "description": "Scope analytics to high-value users, admin workstations, or servers where browsers shouldn’t be automated."}]', '2026-05-01 15:26:36.348848');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1334, 'AN0016', 'Analytic 0016', 'Adversary uses nltest, PowerShell, or Win32/.NET API to enumerate domain trust relationships (via DSEnumerateDomainTrusts, GetAllTrustRelationships, or LDAP queries), followed by discovery or authentication staging.', '{Windows}', 'x-mitre-analytic--c3be6c4a-3b3d-4a37-a1d8-2c4df915a7aa', 'DET0007', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:PowerShell", "channel": "Get-ADTrust|GetAllTrustRelationships", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Security", "channel": "EventCode=4662", "x_mitre_data_component_ref": "x-mitre-data-component--5c6de881-bc70-4070-855a-7a9631a407f7"}]', '[{"field": "ParentImage", "description": "Tune based on expected script hosts or authorized administrators invoking trust enumeration."}, {"field": "TimeWindow", "description": "Correlate enumeration + subsequent Kerberos activity or DC interaction within a bounded window."}, {"field": "UserContext", "description": "Prioritize detection for non-admin or unexpected user accounts performing enumeration."}, {"field": "API_Name", "description": "Flag uncommon or low-prevalence API calls like DSEnumerateDomainTrusts for inspection."}]', '2026-05-01 15:26:36.351276');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1335, 'AN0092', 'Analytic 0092', 'Creation of files or directories with a leading ''.'' in privileged directories (/etc, /var, /usr/bin). Defender view: monitoring auditd logs for file creations where name begins with ''.'' and correlated with unusual user/process context.', '{Linux}', 'x-mitre-analytic--c4108797-7eb4-4ef8-8dee-c2db00695ab4', 'DET0032', '[{"name": "auditd:FILE", "channel": "File creation with name starting with ''.''", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:EXECVE", "channel": "Use of mv or cp to rename files with ''.'' prefix", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "DirectoryScope", "description": "Restrict detection to critical directories to avoid noise from benign hidden files like .ssh or .config."}]', '2026-05-01 15:26:36.352463');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1355, 'AN1562', 'Analytic 1562', 'Processes executing commands to query system locale and language settings, such as ''locale'', ''echo $LANG'', or parsing environment variables. Suspicious activity is indicated by these commands being run by unusual users, automation scripts, or non-administrative processes.', '{Linux}', 'x-mitre-analytic--c625c090-edcc-431a-a2fb-c31e4eb5f2cf', 'DET0565', '[{"name": "auditd:SYSCALL", "channel": "execve calls to /usr/bin/locale or shell execution of $LANG", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Unexpected or non-admin users executing locale commands may suggest malicious behavior."}]', '2026-05-01 15:26:36.382591');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1336, 'AN0131', 'Analytic 0131', 'Detects adversaries accessing remote mail systems (e.g., Exchange Online, O365) using stolen credentials or OAuth tokens, followed by scripted access to mailbox contents via PowerShell, AADInternals, or unattended API queries. Detection focuses on abnormal logon sessions, user agents, IP locations, and scripted or tool-based email data access.', '{Windows}', 'x-mitre-analytic--c42179a8-71c5-41ba-bbfa-d6c1a93e729b', 'DET0048', '[{"name": "azure:signinlogs", "channel": "Abnormal sign-in from scripting tools (PowerShell, AADInternals)", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "m365:purview", "channel": "MailItemsAccessed & Exchange Audit", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "UserAgentPattern", "description": "Filters user agents like ''PowerShell'', ''AADInternals'', ''python-requests'' which can vary depending on script/tool."}, {"field": "TimeWindow", "description": "Defines the temporal correlation window between login, command execution, and outbound email access."}, {"field": "KnownIPLocations", "description": "Defines baseline geo/IP address ranges to suppress known corporate access."}, {"field": "PrivilegedUserList", "description": "Defines the accounts considered privileged (admin, execs) and worthy of tighter thresholds."}]', '2026-05-01 15:26:36.353671');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1337, 'AN0671', 'Analytic 0671', 'Monitor for abnormal certificate enrollment and usage activity in Active Directory Certificate Services (AD CS), registry access to certificate storage locations, and unusual process executions that attempt to export or access private keys.', '{Windows}', 'x-mitre-analytic--c448cbb5-1256-4a00-8582-1759fb5a6e56', 'DET0240', '[{"name": "WinEventLog:Security", "channel": "EventCode=4768", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}]', '[{"field": "EKU_Thresholds", "description": "Organizations may tune which Extended Key Usage (EKU) values are considered risky."}, {"field": "TimeWindow", "description": "Defines how quickly multiple certificate enrollments from the same entity should trigger correlation alerts."}, {"field": "LogonContext", "description": "Differentiate between service accounts and interactive user accounts to reduce false positives."}]', '2026-05-01 15:26:36.355026');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1338, 'AN1197', 'Analytic 1197', 'Detects the modification or addition of Launch Agents or Startup Items to establish persistence. Adversaries may write plist or executable files to ~/Library/LaunchAgents/, /Library/StartupItems/, or similar directories and configure them to run at user or system boot. Detection requires correlating file creation or modification events with subsequent user logon or boot-time process execution.', '{macOS}', 'x-mitre-analytic--c46d9fac-eac9-479e-91d3-4f5a1066972d', 'DET0429', '[{"name": "macos:unifiedlog", "channel": "launchservices or loginwindow events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:fsevents", "channel": "/Library/StartupItems/, ~/Library/LaunchAgents/", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "directory_path", "description": "Specific paths to monitor may differ across macOS versions or enterprise baselines."}, {"field": "user_context", "description": "Different users may have unique LaunchAgents folders—tuning may be required."}, {"field": "time_window", "description": "The correlation time between file creation and process execution may need to be adjusted for boot persistence."}, {"field": "process_name", "description": "Specific startup binaries (e.g., bash, osascript) may vary across implementations."}]', '2026-05-01 15:26:36.356668');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1339, 'AN0768', 'Analytic 0768', 'The adversary uses native utilities like base64, gzip, tar, or openssl to decode, decompress, or decrypt files that were previously staged or downloaded. These tools may be chained with curl/wget and executed via bash/zsh, often to extract an embedded payload or reverse shell script.', '{Linux}', 'x-mitre-analytic--c4866ad5-310c-4a72-89b5-1e5a8683d286', 'DET0275', '[{"name": "auditd:SYSCALL", "channel": "bash/zsh of base64, tar, gzip, or openssl immediately after file write", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ShellProcessName", "description": "Shell interpreter may vary (bash, zsh, dash, sh)"}, {"field": "DecodeUtility", "description": "May include base64, openssl, gunzip, tar, uudecode"}, {"field": "ParentProcess", "description": "Expected parent process may vary in attacker chain (e.g., curl, bash, ssh)"}, {"field": "ArgumentPattern", "description": "Detection regex should support flexible patterning of decode switches"}]', '2026-05-01 15:26:36.358402');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1340, 'AN1617', 'Analytic 1617', 'Detection of enumeration activity when system processes query ESXi host account configuration or management APIs to retrieve user account listings.', '{ESXi}', 'x-mitre-analytic--c4973f27-c8db-4478-aaf8-eb73580fceec', 'DET0587', '[{"name": "esxi:vpxd", "channel": "vCenter Management", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandPattern", "description": "Tune based on known enumeration commands: ''vim-cmd vimsvc/auth/userlist''."}, {"field": "PrivilegedSession", "description": "Elevated enumeration from vpxuser or root may indicate threat activity."}]', '2026-05-01 15:26:36.360028');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1341, 'AN1343', 'Analytic 1343', 'SaaS applications receiving authentication failures for dozens of accounts using same password or login signature', '{SaaS}', 'x-mitre-analytic--c4a0d95a-2dfc-4b03-830e-d0dafca0be6f', 'DET0487', '[{"name": "saas:auth", "channel": "signin_failed", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "CloudAppScope", "description": "Restrict detection to identity providers or select high-risk SaaS platforms"}, {"field": "UserPopulationSensitivity", "description": "Adjust based on size and role of account pool"}]', '2026-05-01 15:26:36.361424');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1378, 'AN1590', 'Analytic 1590', 'Creation or modification of Apple Mail rules by accessing plist files or GUI automation (AppleScript).', '{macOS}', 'x-mitre-analytic--c93edcb2-385a-4472-a9db-ace5371250eb', 'DET0576', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "fs:plist_monitoring", "channel": "/Users/*/Library/Mail/V*/MailData/RulesActiveState.plist", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "RuleFilePath", "description": "Different Mail versions store rules in slightly different locations."}, {"field": "ScriptTrigger", "description": "AppleScript usage for GUI automation may be common in automation workflows."}]', '2026-05-01 15:26:36.416302');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1342, 'AN0786', 'Analytic 0786', 'Detection of suspicious token manipulation chains: use of token-related APIs (e.g., LogonUser, DuplicateTokenEx) or commands (runas) → spawning of a new process under a different security context (e.g., SYSTEM) → mismatched parent-child process lineage or anomalies in Event Tracing for Windows (ETW) token/PPID data → abnormal lateral or privilege escalation activity.', '{Windows}', 'x-mitre-analytic--c4cabd45-86a2-4842-9171-dff93f6ac737', 'DET0283', '[{"name": "WinEventLog:Security", "channel": "EventCode=4672, 4634", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "ETW:Token", "channel": "token_analysis: API calls such as DuplicateTokenEx or ImpersonateLoggedOnUser", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:Security", "channel": "EventCode=5136", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}]', '[{"field": "TimeWindow", "description": "Correlation time between suspicious API usage, runas, and process creation (e.g., 5–10m)."}, {"field": "AllowedServiceAccounts", "description": "Whitelist of service accounts permitted to spawn SYSTEM-level processes."}, {"field": "KnownAdminTools", "description": "Legitimate administrative utilities that trigger token changes."}, {"field": "ParentProcessAnomalyThreshold", "description": "Deviation threshold for PPID mismatches detected via ETW."}]', '2026-05-01 15:26:36.363032');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1343, 'AN0105', 'Analytic 0105', 'Detects unauthorized access to web browser credential stores (e.g., Chrome Login Data, Edge Credential Locker) by processes other than the browser itself. Correlates file reads of credential databases with subsequent API calls to `CryptUnprotectData` or memory inspection attempts.', '{Windows}', 'x-mitre-analytic--c4eb93f1-0288-4884-bdbc-800e7a8e87c3', 'DET0037', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredPaths", "description": "Browser-specific credential storage paths such as Chrome Login Data, IE Credential Locker"}, {"field": "TimeWindow", "description": "Correlation window between file read and process memory/API access"}]', '2026-05-01 15:26:36.364525');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1344, 'AN1441', 'Analytic 1441', 'Detects GUI-based credential prompts invoked via zenity/kdialog/dialog or X11 APIs from non-user-facing scripts or background shell sessions, often with authentication-related text.', '{Linux}', 'x-mitre-analytic--c4ff3b74-bba1-4129-b246-50213e77336d', 'DET0521', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:cli", "channel": "Terminal Command History", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ExecutableName", "description": "Filter zenity/kdialog prompts launched from unexpected parent shells"}, {"field": "PromptString", "description": "Look for ''password'', ''authentication required'', or similar tokens"}]', '2026-05-01 15:26:36.365765');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1345, 'AN1228', 'Analytic 1228', 'Detects application-layer tunneling or unauthorized app protocols like DNS-over-HTTPS, embedded C2 in TLS/HTTP headers, or misused SMB traffic crossing VLANs.', '{"Network Devices"}', 'x-mitre-analytic--c5117811-b262-4920-90d9-001d25b6305b', 'DET0444', '[{"name": "NSM:Flow", "channel": "conn.log, http.log, dns.log, ssl.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AppProtocolAbusePattern", "description": "Detects DNS tunneling, encrypted HTTP C2, or malformed headers"}, {"field": "NorthSouthEgressFilter", "description": "Monitor internal hosts talking externally using internal protocols (e.g., SMB)"}]', '2026-05-01 15:26:36.367213');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1346, 'AN0684', 'Analytic 0684', 'Audit VoIP/SIP logs for suspicious outbound calls or call setup messages to unusual endpoints. Correlate with user activity such as browser execution or package installation following the call.', '{Linux}', 'x-mitre-analytic--c5134555-561a-4905-8601-a6ba307fc121', 'DET0245', '[{"name": "networkdevice:syslog", "channel": "SIP REGISTER, INVITE, or unusual call destination metadata", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "CallDestinationPatterns", "description": "Regular expressions or rules for spotting abnormal call destinations"}, {"field": "UserContext", "description": "Expected users who initiate VoIP traffic vs. anomalous accounts"}]', '2026-05-01 15:26:36.36861');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1347, 'AN1348', 'Analytic 1348', 'Behavioral chain: (1) cross-account or third-party principal assumes a role into the tenant/subscription/project; (2) privileged API calls are made in short succession; (3) access originates from unfamiliar networks or geos. Correlate assume-role/federation events with sensitive API usage.', '{IaaS}', 'x-mitre-analytic--c526f8c1-95ec-494f-b7bf-49a95a803f2a', 'DET0488', '[{"name": "AWS:CloudTrail", "channel": "AssumeRole,AssumeRoleWithSAML,AssumeRoleWithWebIdentity", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "AWS:CloudTrail", "channel": "CreateUser|AttachRolePolicy|CreateAccessKey|UpdateAssumeRolePolicy|CreateLoginProfile", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "gcp:audit", "channel": "google.iam.credentials.generateAccessToken / serviceAccountTokenCreator", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "ExternalAccountAllowList", "description": "Cross-account principals permitted to assume roles; used for allow-listing."}, {"field": "SensitiveAPIs", "description": "Provider-specific list of risky APIs for scoring."}, {"field": "GeoVelocityThreshold", "description": "Detect impossible travel between partner and tenant actions."}]', '2026-05-01 15:26:36.36989');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1414, 'AN0301', 'Analytic 0301', 'Detection of OAuth consent phishing or malicious login attempts initiated through spearphishing links. Behavior chain includes inbound email with OAuth URL → consent page visited → unusual token grants logged in IdP logs.', '{"Identity Provider"}', 'x-mitre-analytic--cfc7b6bc-2ca3-4407-a835-b40bf6a98efc', 'DET0107', '[{"name": "azure:signinlogs", "channel": "ConsentGrant: Suspicious consent grants to non-approved or unknown applications", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "AllowedApps", "description": "Whitelisted apps permitted for OAuth consent grants."}, {"field": "AnomalousConsentPatterns", "description": "Patterns of consent from unusual geographies, devices, or unapproved applications."}]', '2026-05-01 15:26:36.468343');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1349, 'AN1630', 'Analytic 1630', 'Defenders may observe adversary attempts to extract configuration data from management repositories by monitoring for anomalous SNMP queries, API calls, or protocol requests (e.g., NETCONF, RESTCONF) that enumerate system configuration. Suspicious sequences include repeated queries from untrusted IPs, abnormal query types requesting sensitive configuration data, or repository access occurring outside of normal administrative maintenance windows. Abnormal authentication attempts, sudden enumeration of device inventory, or bulk data transfer of configuration files may also be observed.', '{"Network Devices"}', 'x-mitre-analytic--c5544183-4868-4a5c-ad8c-8a9359358298', 'DET0592', '[{"name": "NSM:Flow", "channel": "Unexpected or unauthorized inbound connections to SNMP, NETCONF, or RESTCONF services", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "networkdevice:syslog", "channel": "Authentication failures or unusual community string usage in SNMP queries", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AuthorizedAdminIPs", "description": "Expected IP ranges or hosts permitted to query configuration repositories; deviations may indicate compromise."}, {"field": "NormalAccessTimeWindow", "description": "Time periods when configuration queries normally occur; anomalies outside these windows may be suspicious."}, {"field": "QueryVolumeThreshold", "description": "Number of queries allowed within a given period before an anomaly is triggered."}, {"field": "ProtocolUsageBaseline", "description": "Expected usage of SNMP, NETCONF, or RESTCONF; deviations from baseline patterns may indicate misuse."}]', '2026-05-01 15:26:36.372771');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1350, 'AN1081', 'Analytic 1081', 'Detects bash, sh, zsh, or BusyBox shell execution initiated via remote sessions, unauthorized users, or embedded within secondary script interpreters. Focus is on chained behavior: shell > suspicious commands > network discovery or persistence indicators.', '{Linux}', 'x-mitre-analytic--c5556dd5-005a-4c11-b028-240fa379d827', 'DET0384', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "linux:syslog", "channel": "auth.log / secure.log", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "ExecutableName", "description": "Detect variants like /bin/sh, /usr/local/bin/zsh, /bin/busybox sh."}, {"field": "UserContext", "description": "Shell used by service accounts, root, or rare accounts."}, {"field": "ParentProcess", "description": "Shell invoked by unexpected parents (e.g., curl, mail, apache2)."}, {"field": "TimeWindow", "description": "Execution outside maintenance windows or normal activity periods."}, {"field": "CommandLinePattern", "description": "Flags use of loops, download commands, chaining (|, &&), or reverse shells."}]', '2026-05-01 15:26:36.374573');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1351, 'AN0725', 'Analytic 0725', 'Detects aggregation of files from different directories into /tmp, /mnt, or user-specified directories with archiving tools like tar or gzip.', '{Linux}', 'x-mitre-analytic--c5e7b8a9-72f6-40db-be4a-ec17386d884f', 'DET0261', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "StagingDirs", "description": "e.g., /tmp, /var/tmp, custom user dirs"}, {"field": "ArchiveUtilities", "description": "tar, gzip, zip, 7z"}, {"field": "UserThreshold", "description": "Number of files or size written in short time"}]', '2026-05-01 15:26:36.376138');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1352, 'AN0189', 'Analytic 0189', 'Monitor for malicious payload delivery through phishing where attachments or URLs in email clients (e.g., Thunderbird, mutt) result in unusual file creation or outbound network connections. Focus on correlation between mail logs, file writes, and execution activity.', '{Linux}', 'x-mitre-analytic--c5fe5b29-c56f-4c40-b880-051ec6644600', 'DET0070', '[{"name": "Application:Mail", "channel": "Inbound messages with anomalous headers, spoofed SPF/DKIM failures", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "auditd:SYSCALL", "channel": "execve: Execution of scripts or binaries sourced from mail directories (/var/mail, ~/Maildir)", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredMailPaths", "description": "System or user directories where emails/attachments are stored."}, {"field": "AttachmentHashBaseline", "description": "Known good hashes for common business document templates."}]', '2026-05-01 15:26:36.377488');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1353, 'AN0206', 'Analytic 0206', 'Execution of AppleScript or Automator services launching `ssh -L`, `socat`, or `launchctl` items that dynamically reroute traffic from one Mac endpoint to another. LaunchAgents used to establish permanent internal tunnels.', '{macOS}', 'x-mitre-analytic--c62026a7-3332-489f-bb86-30626c1b3cc8', 'DET0075', '[{"name": "macos:unifiedlog", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "pf firewall logs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:osquery", "channel": "Process Events and Launch Daemons", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "LaunchAgentPath", "description": "Directory where proxying LaunchDaemons may be dropped, e.g., `/Library/LaunchDaemons/`."}, {"field": "PortBindings", "description": "Dynamic port forwards often use ephemeral or non-standard service ports."}, {"field": "AppleScriptUsage", "description": "May trigger on less common scripting interfaces for traffic redirection."}]', '2026-05-01 15:26:36.379851');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1354, 'AN0907', 'Analytic 0907', 'Detects interactive or automated use of CLI commands like `show ip sockets`, `show tcp brief`, or SNMP queries for active sessions on routers/switches.', '{"Network Devices"}', 'x-mitre-analytic--c6208aa1-fa6e-4d9d-a284-dd0aab1ee31c', 'DET0320', '[{"name": "networkdevice:cli", "channel": "command logs", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "snmp:trap", "channel": "management queries", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "CommandPatternList", "description": "Monitors for known socket/session query strings."}, {"field": "PrivilegedUserCheck", "description": "Restrict detections to non-admin roles executing advanced queries."}]', '2026-05-01 15:26:36.381363');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1356, 'AN0080', 'Analytic 0080', 'Processes invoking network-intensive child processes or uploading large data volumes, often from non-standard user or system contexts, with evidence of long-duration TCP/UDP sessions to unusual destinations.', '{Windows}', 'x-mitre-analytic--c699a4ee-83dd-48d8-94ae-658204066ae9', 'DET0028', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Bandwidth anomalies should be assessed over 5-15 min or hourly windows depending on environment size."}, {"field": "DestinationCountry", "description": "Some organizations whitelist traffic to countries based on geolocation."}, {"field": "ProcessName", "description": "Legitimate processes using high bandwidth (e.g., backup tools) must be excluded."}]', '2026-05-01 15:26:36.38387');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1357, 'AN0116', 'Analytic 0116', 'Detects adversary removal of persistence implants (e.g., rc.local entries or crontab injections) via CLI (`rm`, `sed`, `crontab -r`) and deletion of startup or management scripts.', '{ESXi}', 'x-mitre-analytic--c6ae166f-f2ac-405a-85c2-b7f9349a1b99', 'DET0040', '[{"name": "esxi:vmkernel", "channel": "/var/log/vmkernel.log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:shell", "channel": "shell history", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "ScriptRemovalPath", "description": "e.g., /etc/rc.local, /etc/init.d/custom.sh"}, {"field": "StartupEntryClearance", "description": "Wipe or truncate of persistence locations"}]', '2026-05-01 15:26:36.385166');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1358, 'AN0414', 'Analytic 0414', 'Adversary deletes critical infrastructure: EC2 instances, S3 buckets, snapshots, or volumes using elevated IAM credentials. Frequently includes batch API calls with `Delete*` or `TerminateInstances`.', '{IaaS}', 'x-mitre-analytic--c6f35e44-459c-456b-97a7-997eb2baefb9', 'DET0146', '[{"name": "AWS:CloudTrail", "channel": "DeleteBucket, DeleteDBCluster, DeleteSnapshot, TerminateInstances", "x_mitre_data_component_ref": "x-mitre-data-component--4c41e296-b8d2-4a37-b789-eb565c87c00c"}]', '[{"field": "OperationType", "description": "Correlate multiple destructive API calls over short intervals."}, {"field": "UserAgent", "description": "Flag non-console/API clients initiating destructive behavior."}, {"field": "RegionScope", "description": "Observe whether deletions span multiple regions or org accounts."}]', '2026-05-01 15:26:36.386328');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1359, 'AN2039', 'Analytic 2039', 'Detects exploitation attempts against security daemons or kernel security modules followed by daemon termination, disabled logging, module unload, audit stoppage, or reduced endpoint telemetry. Correlates local execution or network input with control degradation.', '{Linux}', 'x-mitre-analytic--c6fb992c-387e-49ee-beaf-a1351aded262', 'DET0900', '[{"name": "auditd:EXECVE", "channel": "execve, kill, ptrace, insmod, rmmod targeting security processes", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:DAEMON", "channel": "auditd stopped, config changed, logging suspended", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "ProtectedProcessNames", "description": "Names of EDR, audit, AV, firewall daemons"}, {"field": "ModuleUnloadAllowlist", "description": "Approved maintenance unload operations"}, {"field": "HealthGapThreshold", "description": "Expected telemetry heartbeat tolerance"}]', '2026-05-01 15:26:36.387481');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1360, 'AN0712', 'Analytic 0712', 'Detects extraction or mounting of container/archive files (e.g., .iso, .vhd, .zip) that originated from the Internet but whose contained files lack Zone.Identifier MOTW tagging. Correlates file creation metadata with subsequent execution of unsigned or untrusted binaries launched outside SmartScreen or Protected View.', '{Windows}', 'x-mitre-analytic--c7172412-6e48-45a0-a1c5-2eae892c1fc7', 'DET0257', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "WatchedExtensions", "description": "Adjust monitored file types (e.g., .iso, .vhd, .zip, .gz, .rar) based on enterprise usage"}, {"field": "TimeWindow", "description": "Defines correlation window between extraction/mount and first execution of inner files"}, {"field": "TrustedExtractionTools", "description": "Whitelist known enterprise archivers and deployment mechanisms to reduce false positives"}]', '2026-05-01 15:26:36.388794');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1361, 'AN1149', 'Analytic 1149', 'Detect adversaries filtering traffic or modifying server responses to evade scanning. Monitor iptables, nftables, or proxy configurations that deny or redirect requests from known scanning agents or defensive tools.', '{Linux}', 'x-mitre-analytic--c71bf861-9b5a-4f39-a53f-bb6f45f7a971', 'DET0411', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of commands modifying iptables/nftables to block selective IPs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Altered response metadata or blocked content based on user-agent or geolocation", "x_mitre_data_component_ref": "x-mitre-data-component--1067aa74-5796-4d9b-b4f1-a4c9eb6fd9da"}]', '[{"field": "BlockedAgents", "description": "User-agent strings or scanning tools to monitor for selective filtering."}]', '2026-05-01 15:26:36.390523');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1362, 'AN1988', 'Analytic 1988', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1363, 'AN1961', 'Analytic 1961', 'Once adversaries leverage serverless functions as infrastructure (ex: for command and control), it may be possible to look for unique characteristics associated with adversary software, if known.(Citation: ThreatConnect Infrastructure Dec 2020) Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle. ', '{PRE}', 'x-mitre-analytic--c755e8b9-7e07-4e9a-95a1-bc7cb88e878a', 'DET0829', '[{"name": "Internet Scan", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--0dcbbf4f-929c-489a-b66b-9b820d3f7f0e"}]', NULL, '2026-05-01 15:26:36.393663');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1364, 'AN0271', 'Analytic 0271', 'Processes using Win32 API calls (e.g., EnumWindows, GetForegroundWindow) or scripting tools (e.g., PowerShell, VBScript) to enumerate open windows. These often appear with reconnaissance or data collection TTPs.', '{Windows}', 'x-mitre-analytic--c76d69b2-f1d4-4867-965b-886b6caf95be', 'DET0097', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AccessedFunction", "description": "Tune to focus on suspicious function calls (e.g., user32.dll!EnumWindows)."}, {"field": "UserContext", "description": "Detect behavior from non-interactive or low-privileged users where enumeration is uncommon."}, {"field": "TimeWindow", "description": "Shorten detection scope to rapid successive window enumeration attempts."}]', '2026-05-01 15:26:36.39488');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1365, 'AN0590', 'Analytic 0590', 'Detection of suspicious logon behavior using valid domain accounts across multiple hosts, off-hours, or simultaneous sessions from geographically distant locations.', '{Windows}', 'x-mitre-analytic--c7706ddb-cf88-41c7-981b-a5e1bf6cfcfc', 'DET0210', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4625, 4768, 4769", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Tune for detection of off-hours or abnormal logon spikes."}, {"field": "UserContext", "description": "Scope to sensitive domain accounts (e.g., Domain Admins)."}, {"field": "LogonType", "description": "Distinguish between interactive, service, and network logons."}]', '2026-05-01 15:26:36.396291');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1366, 'AN0490', 'Analytic 0490', 'Excessive inbound HTTP or TLS connections to services such as Apache or Nginx, causing worker thread exhaustion or segmentation faults.', '{Linux}', 'x-mitre-analytic--c7752951-1077-478d-9511-df852cba6b28', 'DET0173', '[{"name": "auditd:SYSCALL", "channel": "High frequency of accept(), read(), or SSL_read() syscalls tied to nginx/apache processes", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "NSM:Flow", "channel": "Sudden spike in incoming flows to web service ports from single/multiple IPs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "linux:syslog", "channel": "Repetitive HTTP 408, 500, or 503 errors logged within short timeframe", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ErrorCodeWindow", "description": "Tunable count of specific HTTP error codes in timeframe"}, {"field": "ConnectionRateThreshold", "description": "Defines number of connections per second considered anomalous"}]', '2026-05-01 15:26:36.397603');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1367, 'AN1047', 'Analytic 1047', 'Detect suspicious calls to sysctl or ptrace API used to determine if a process is being debugged. Monitor for processes that flood OutputDebugString equivalents or generate abnormal exceptions to evade analysis.', '{macOS}', 'x-mitre-analytic--c78d2e09-07d7-48ef-add1-bde622e502a2', 'DET0371', '[{"name": "macos:unifiedlog", "channel": "ptrace: Processes invoking ptrace with PTRACE_TRACEME flag", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "PtraceInvocationThreshold", "description": "Number of ptrace calls in a time window that should raise suspicion"}, {"field": "DevToolExclusionList", "description": "Exclude known developer tools and monitoring agents"}]', '2026-05-01 15:26:36.398866');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1368, 'AN0307', 'Analytic 0307', 'Correlation of chmod operations setting setuid/setgid bits followed by privileged process execution (EUID != UID), especially from user-writable or abnormal paths.', '{Linux}', 'x-mitre-analytic--c7d513f4-5113-4031-8125-7f145128c2e1', 'DET0110', '[{"name": "auditd:SYSCALL", "channel": "chmod, execve", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Track execution of setuid binaries where UID != EUID or executed from unexpected user context"}, {"field": "FilePathScope", "description": "Restrict detection to non-standard locations (e.g., /tmp, /home/*, /var/tmp)"}, {"field": "TimeWindow", "description": "Time delta between chmod setting setuid/gid and process execution to define a suspicious window"}]', '2026-05-01 15:26:36.400025');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1369, 'AN1284', 'Analytic 1284', 'Monitoring for SSH logins from default accounts such as ''root'', especially when login is via password and not key-based authentication.', '{Linux}', 'x-mitre-analytic--c804a181-f0be-41dd-81ce-95e0a3e5245d', 'DET0465', '[{"name": "auditd:USER_LOGIN", "channel": "USER_LOGIN", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "SSHMethod", "description": "Environments using passwordless SSH should not have password logins enabled for root or other default accounts."}, {"field": "RemoteIPWhitelist", "description": "Logins from jump boxes may be whitelisted depending on environment policies."}]', '2026-05-01 15:26:36.401268');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1370, 'AN0320', 'Analytic 0320', 'Inbound spearphishing attempts delivered via third-party services (e.g., Gmail, LinkedIn messages) leading to malicious file downloads or browser-initiated script execution. Defender view includes correlation of external service logins, unexpected file write operations, and suspicious descendant processes spawned from productivity or browser applications.', '{Windows}', 'x-mitre-analytic--c83f1d8c-ba54-4f2d-91b8-3006a2180497', 'DET0115', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "MonitoredServices", "description": "List of third-party services (e.g., Gmail, LinkedIn, Dropbox) relevant to the organization’s threat profile."}, {"field": "SuspiciousProcessPatterns", "description": "Process lineage and parent-child execution relationships considered abnormal (e.g., outlook.exe → powershell.exe)."}, {"field": "TimeWindow", "description": "Correlates file creation and outbound connection activity within a tunable time period after message receipt."}]', '2026-05-01 15:26:36.402453');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1371, 'AN1259', 'Analytic 1259', 'Adversary modifies Active Directory domain trust settings via `netdom`, `nltest`, or PowerShell to add new domain trust or alter federation. Modifications occur in AD object attributes like trustDirection, trustType, trustAttributes, often paired with SeEnableDelegationPrivilege or certificate injection.', '{Windows}', 'x-mitre-analytic--c84ed29d-c0bf-465c-9e4a-7685cd4ff444', 'DET0458', '[{"name": "WinEventLog:Security", "channel": "EventCode=5136", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:Security", "channel": "EventCode=4704", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ObjectType", "description": "Focus on `trustedDomain` or `foreignSecurityPrincipal` AD objects in trust containers."}, {"field": "AttributeModified", "description": "Monitor attributes like `trustPartner`, `trustDirection`, `trustType`, `msDS-TrustForestTrustInfo`."}, {"field": "TimeWindow", "description": "Correlate trust creation with unusual logon events or certificate modifications."}, {"field": "UserContext", "description": "Flag rare accounts or non-standard admin users performing trust changes."}]', '2026-05-01 15:26:36.405252');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1372, 'AN0019', 'Analytic 0019', 'Login to M365 or Google Workspace from CLI tools or unexpected source IPs, followed by mailbox or document access', '{"Office Suite"}', 'x-mitre-analytic--c85d0aea-06c4-4b0f-8552-0d0873394ffa', 'DET0008', '[{"name": "m365:unified", "channel": "FileAccessed, MailboxAccessed", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "m365:unified", "channel": "UserLoggedIn", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "DevicePlatformMismatch", "description": "Raise alerts on login from CLI when user typically uses web-only"}, {"field": "SensitiveDocumentAccessPattern", "description": "Track access to documents labeled as internal/confidential"}, {"field": "AccessFrequencyThreshold", "description": "Tune for high-volume document reads post login"}]', '2026-05-01 15:26:36.407238');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1373, 'AN0918', 'Analytic 0918', 'Detection of EFI/firmware manipulation attempts via abnormal driver loads, unsigned kexts, or tampered NVRAM variables associated with component firmware configuration.', '{macOS}', 'x-mitre-analytic--c89e4f72-a563-4665-9934-14b9efe88a06', 'DET0323', '[{"name": "macos:unifiedlog", "channel": "Firmware update events or kernel extension (kext) loads not signed by Apple", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}]', '[{"field": "ApprovedKextList", "description": "List of trusted and signed kexts permitted in production systems"}, {"field": "EFIHashBaseline", "description": "Known-clean EFI image hashes used for verification"}]', '2026-05-01 15:26:36.408962');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1374, 'AN0808', 'Analytic 0808', 'Detects web console login events followed by read-only or metadata retrieval activity from GUI sources (e.g., browser session, mobile client) rather than API/CLI sources. Correlates across CloudTrail, IAM identity logs, and user-agent context.', '{IaaS}', 'x-mitre-analytic--c8a50f3f-105a-4107-9781-a3d75479e93d', 'DET0291', '[{"name": "AWS:CloudTrail", "channel": "ConsoleLogin", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "AWS:CloudTrail", "channel": "Post-authentication metadata enumeration from GUI session", "x_mitre_data_component_ref": "x-mitre-data-component--e214eb6d-de8f-4154-9015-6d47915fbed1"}]', '[{"field": "UserAgentFilter", "description": "Allowlist/denylist of user agents to distinguish browser-based vs. CLI/API sessions"}, {"field": "TimeWindow", "description": "Maximum time delta between login and suspicious GUI activity"}, {"field": "PrivilegedSessionThreshold", "description": "Login attempts to dashboard using elevated IAM roles"}]', '2026-05-01 15:26:36.410549');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1375, 'AN1354', 'Analytic 1354', 'Enumeration of USB and other peripheral hardware via udevadm, lshw, or /sys or /proc interfaces in proximity to collection or mounting behavior.', '{Linux}', 'x-mitre-analytic--c8d9ad93-e4ce-4b00-89cb-8f0f6452923d', 'DET0491', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "open/read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:osquery", "channel": "hardware_events", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}]', '[{"field": "ExecutableList", "description": "Set of binaries used for peripheral enumeration (e.g., ''lshw'', ''lsusb'', ''udevadm'')"}, {"field": "UserContext", "description": "Tuning based on which users/scripts are authorized to query device state"}]', '2026-05-01 15:26:36.412049');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1376, 'AN0183', 'Analytic 0183', 'Use of nohup, disown, or AppleScript constructs to suppress process interrupts. Defender perspective: commands containing nohup or hidden background tasks (`osascript` with persistent execution) correlated with processes surviving user logouts.', '{macOS}', 'x-mitre-analytic--c9079261-caa7-4cfe-8be6-1359db599d27', 'DET0067', '[{"name": "macos:unifiedlog", "channel": "nohup, disown, or osascript execution patterns", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "background process persists beyond user logout", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WatchedShells", "description": "Shells or interpreters where nohup/disown usage is suspicious, configurable to environment."}, {"field": "PersistenceCorrelationWindow", "description": "Time window to correlate process continuation after logout with suspicious commands."}]', '2026-05-01 15:26:36.413694');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1377, 'AN0169', 'Analytic 0169', 'Network device logs show anomalous inbound file transfers or uncharacteristic flows with high payload volume to network devices with storage or automation hooks.', '{"Network Devices"}', 'x-mitre-analytic--c93951a7-7f78-40cf-a891-30d6c6a9bee6', 'DET0060', '[{"name": "NSM:Flow", "channel": "connection metadata", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "snmp:syslog", "channel": "firmware write/log event", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "PayloadVolumeThreshold", "description": "Tune based on expected update size vs anomalous bulk data transfers"}, {"field": "ProtocolUsed", "description": "Flag unexpected protocols like TFTP, FTP, HTTP"}]', '2026-05-01 15:26:36.414996');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1379, 'AN0472', 'Analytic 0472', 'Adversary registers a malicious Microsoft Exchange transport agent DLL (.NET assembly), configures it via PowerShell or Exchange Management Shell, and persists code execution by manipulating email processing logic based on rules or headers.', '{Windows}', 'x-mitre-analytic--c94b2c2b-8885-4f5e-abec-e80ab0a24f21', 'DET0166', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Application", "channel": "Exchange Transport Service loads unusual .NET assembly or errors upon transport agent execution", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "TimeWindow", "description": "May need tuning based on frequency of Exchange agent updates in environment."}, {"field": "AssemblyPath", "description": "Specific DLL paths used by Exchange for registered agents may vary between deployments."}, {"field": "CmdletInvocationThreshold", "description": "Tunable threshold for repeated use of transport agent management cmdlets."}]', '2026-05-01 15:26:36.417507');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1380, 'AN1598', 'Analytic 1598', 'Detects registration of new or modified network provider DLLs via registry changes, anomalous file creation of DLLs in system directories, and suspicious process activity (mpnotify.exe interacting with non-standard DLLs). Multi-event correlation ties registry modification events to subsequent DLL loads during user logon activity.', '{Windows}', 'x-mitre-analytic--c94f0795-ef0b-4e22-8395-bbba4f28346f', 'DET0580', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "MonitoredRegistryKeys", "description": "Specific registry keys to monitor for DLL registration (e.g., NetworkProvider Order)."}, {"field": "SuspiciousDLLPaths", "description": "Directories or file name patterns outside of normal system DLL locations."}, {"field": "TimeWindow", "description": "Window correlating registry modification, DLL creation, and subsequent logon activity."}]', '2026-05-01 15:26:36.418831');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1381, 'AN1624', 'Analytic 1624', 'Adversary modifies web-facing content on macOS via web development environments like MAMP or misconfigured Apache instances, typically with access to the hosting user account or via persistence tools.', '{macOS}', 'x-mitre-analytic--c9b3d194-843a-4f65-ad8b-4b3192571fc5', 'DET0590', '[{"name": "macos:unifiedlog", "channel": "Terminal/Editor processes modifying web folder", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "loginwindow or sshd events with external IP", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "web_root_dir", "description": "May include ~/Sites or custom Apache paths"}, {"field": "editor_name", "description": "Text editor or script modifying the files may vary (e.g., nano, VS Code)"}]', '2026-05-01 15:26:36.420058');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1382, 'AN0986', 'Analytic 0986', 'Detects malicious containers or pods using names, labels, or namespaces that mimic legitimate workloads; also checks for image layer mismatches and unauthorized resource deployments.', '{Containers}', 'x-mitre-analytic--c9bdc7a6-ff19-46e9-a534-fa2fd3e0a193', 'DET0347', '[{"name": "kubernetes:apiserver", "channel": "Resource creation and update logs", "x_mitre_data_component_ref": "x-mitre-data-component--b597a220-6510-4397-b0d8-342cd2c58827"}, {"name": "containerd:events", "channel": "Docker or containerd image pulls and process executions", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "trusted_namespace_list", "description": "List of namespaces that should not be used by unprivileged users or workloads"}, {"field": "image_baseline_hashes", "description": "Reference hashes of approved container images"}]', '2026-05-01 15:26:36.421236');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1383, 'AN0861', 'Analytic 0861', 'Detection focuses on identifying unauthorized or anomalous changes to compute infrastructure components. Defender perspective: monitor for creation, deletion, or modification of instances, volumes, and snapshots outside of approved change management windows; correlate abnormal activity such as rapid snapshot creation followed by new instance mounts, or repeated infrastructure changes by rarely used accounts. Flagging activity linked to unusual geolocation, API client, or automation script is suspicious.', '{IaaS}', 'x-mitre-analytic--c9be9fb3-460f-42bc-9b56-3bb88839aeab', 'DET0308', '[{"name": "AWS:CloudTrail", "channel": "RunInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "AWS:CloudTrail", "channel": "TerminateInstances", "x_mitre_data_component_ref": "x-mitre-data-component--1361e324-b594-4c0e-a517-20cee32b8d7f"}, {"name": "AWS:CloudTrail", "channel": "ModifyVolume", "x_mitre_data_component_ref": "x-mitre-data-component--d46272ce-a0fe-4256-855e-738de7bb63ee"}, {"name": "AWS:CloudTrail", "channel": "DeleteVolume, ModifyVolume", "x_mitre_data_component_ref": "x-mitre-data-component--3acecdde-c327-4498-9bb8-33a2e63c6c57"}, {"name": "AWS:CloudTrail", "channel": "CreateVolume", "x_mitre_data_component_ref": "x-mitre-data-component--dad75cc7-5bae-4175-adb4-ca1962d8650e"}, {"name": "AWS:CloudTrail", "channel": "CreateSnapshot", "x_mitre_data_component_ref": "x-mitre-data-component--3da222e6-53f3-451c-a239-0b405c009432"}, {"name": "AWS:CloudTrail", "channel": "DeleteSnapshot", "x_mitre_data_component_ref": "x-mitre-data-component--16e07530-764b-4d83-bae0-cdbfc31bf21d"}, {"name": "AWS:CloudTrail", "channel": "ModifySnapshotAttribute", "x_mitre_data_component_ref": "x-mitre-data-component--f1eb6ea9-f3ab-414f-af35-2d5427199984"}, {"name": "AWS:CloudWatch", "channel": "unexpected IAM user or role assuming privileges for instance/snapshot operations", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}]', '[{"field": "ChangeWindow", "description": "Approved maintenance or deployment windows. Helps reduce false positives by distinguishing scheduled activity."}, {"field": "UserContext", "description": "IAM user, role, or service account performing the operation. Tunable to allowlist known automation services."}, {"field": "RateThreshold", "description": "Number of infrastructure changes (e.g., snapshot creations) in a defined period. Adjusted based on workload scale."}, {"field": "GeoLocation", "description": "Region or source IP where changes originate. Useful for tuning alerts to account for multi-region deployments."}]', '2026-05-01 15:26:36.422579');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1384, 'AN2001', 'Analytic 2001', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1418, 'AN0135', 'Analytic 0135', 'Detects removal of Remote Login or Screen Sharing logs in Unified Logging, deletion of `com.apple.UTun`, or suspicious Terminal use of `rm`, `sudo pfctl -F all` to clear network state/config history.', '{macOS}', 'x-mitre-analytic--d01951d8-aae8-48b6-afd3-68c86fc167b1', 'DET0049', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate ''eventMessage contains \"loginwindow\" or \"pfctl\"''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "FilenameMatch", "description": "e.g., *com.apple.UTun*, *RemoteManagement* log files"}, {"field": "TimeDeltaFromLogin", "description": "Correlate deletion with recent SSH or GUI remote login session"}]', '2026-05-01 15:26:36.474279');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1385, 'AN0204', 'Analytic 0204', 'Anomalous process (e.g., `rundll32`, `svchost`, `cmd`) initiates connections to internal peer hosts not seen in typical communication baselines, used to proxy or forward traffic internally, often using SMB, RPC, or high ports.', '{Windows}', 'x-mitre-analytic--ca56c2df-0338-4325-964a-0f775d986277', 'DET0075', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "Windows Firewall Log", "channel": "SMB over high port", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "InternalConnectionPattern", "description": "Tune based on known host-to-host communications that are rare (e.g., workstation-to-workstation)."}, {"field": "DestinationPort", "description": "Focus on unusual internal traffic on ports like 1080, 8080, 4444, or SMB over non-standard ports."}, {"field": "TimeWindow", "description": "Correlate unusual traffic bursts with new process execution."}]', '2026-05-01 15:26:36.425725');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1386, 'AN0497', 'Analytic 0497', 'Detection of anomalous ROMMON image changes or upgrades, unexpected reboots following firmware updates, and unauthorized use of firmware upgrade commands or TFTP transfers. Correlation of config modification, privilege escalation, and boot cycle anomalies provides visibility into ROMMON tampering attempts.', '{"Network Devices"}', 'x-mitre-analytic--ca649f9b-2a1f-4d45-b61b-33ac38d6a4ee', 'DET0175', '[{"name": "networkdevice:config", "channel": "Log entries indicating ROMMON image upgrade commands (boot system, upgrade rom-monitor)", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"name": "networkdevice:syslog", "channel": "Unexpected reload, crashinfo, or boot message not tied to scheduled maintenance", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "NSM:Flow", "channel": "Outbound or inbound TFTP file transfers of ROMMON or firmware binaries", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ApprovedROMMONVersions", "description": "Baseline ROMMON image versions authorized for the environment"}, {"field": "TimeWindow", "description": "Correlation window between ROMMON update command, TFTP file transfer, and device reboot"}, {"field": "AdminUserContext", "description": "Expected privileged accounts allowed to execute ROMMON upgrade commands"}]', '2026-05-01 15:26:36.427046');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1387, 'AN0683', 'Analytic 0683', 'Monitor call log records from corporate devices for unusual or unauthorized numbers, especially repeated calls to/from known malicious phone numbers. Correlate with subsequent system events (e.g., browser navigation, remote management tool execution).', '{Windows}', 'x-mitre-analytic--caa11058-4906-48b4-ab3f-a650aab6968d', 'DET0245', '[{"name": "ApplicationLog:CallRecords", "channel": "Outbound or inbound calls to high-risk or blocklisted numbers", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "PhoneNumberBlocklist", "description": "List of known malicious or suspicious phone numbers; must be tuned per environment"}, {"field": "TimeWindow", "description": "Threshold for correlating call events with subsequent suspicious system activity"}]', '2026-05-01 15:26:36.428131');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1388, 'AN1003', 'Analytic 1003', 'User creation or modification via dscl with IsHidden=1, UID<500, or plist edits to com.apple.loginwindow Hide500Users flag. Defender view: correlation of hidden account attributes with login screen exclusion.', '{macOS}', 'x-mitre-analytic--cabc275f-5097-4d2e-aabe-b49a31ba87b9', 'DET0353', '[{"name": "macos:unifiedlog", "channel": "Execution of dscl . create with IsHidden=1", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "Modification of /Library/Preferences/com.apple.loginwindow plist", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Creation of user account with UID <500", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "UIDThreshold", "description": "Tune detection based on acceptable UID ranges for hidden/system accounts."}, {"field": "PlistScope", "description": "Restrict plist monitoring to com.apple.loginwindow to reduce false positives."}]', '2026-05-01 15:26:36.430302');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1389, 'AN1395', 'Analytic 1395', 'Detection of shell commands that leverage encoded execution, command chaining, excessive piping, or unusual token patterns indicative of obfuscation.', '{Linux}', 'x-mitre-analytic--cad9e775-f40f-42fb-8e86-c7aba249a8e4', 'DET0505', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "process_events.command_line", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandLineTokenCount", "description": "Tuning value for token or argument count in shell invocations"}, {"field": "EncodedExecRegex", "description": "Environment-specific regex patterns for encoded or eval''d command lines"}, {"field": "GlobPatternAnomalies", "description": "Shell-specific globbing or directory traversal string detection"}]', '2026-05-01 15:26:36.431521');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1390, 'AN1257', 'Analytic 1257', 'VMCI (Virtual Machine Communication Interface) traffic between guest and host, or between VMs, originating from non-management tools or unauthorized binaries.', '{ESXi}', 'x-mitre-analytic--cae917e6-7542-41d0-8b03-ad2b7ab1eb01', 'DET0457', '[{"name": "esxi:vmkernel", "channel": "VMCI syslog entries", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "VMCIBackdoorProcess", "description": "Monitor for non-vSphere or VMware-native processes using VMCI."}, {"field": "GuestToHostCommPattern", "description": "Baseline pattern of guest-to-host traffic vs anomaly (unexpected port, volume)."}]', '2026-05-01 15:26:36.432697');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1391, 'AN1616', 'Analytic 1616', 'Detection of identity directory enumeration through API calls or administrative queries retrieving multiple account objects within a short interval.', '{"Identity Provider"}', 'x-mitre-analytic--cb177f89-c8a4-4233-a2e4-3fdd02dccba1', 'DET0587', '[{"name": "azure:signinlogs", "channel": "Graph API Query", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"name": "saas:okta", "channel": "User Enumeration Events", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "QueryType", "description": "Detect user vs role enumeration. Tune based on query scope."}, {"field": "AppContext", "description": "Correlate enumeration with unexpected app registrations or identities."}]', '2026-05-01 15:26:36.433823');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1392, 'AN0305', 'Analytic 0305', 'ESXi daemons (e.g., hostd, vpxa) are wrapped or impersonated to send large outbound traffic using gzip/Base64 encoding over SSH or HTTP. These actions follow suspicious logins or shell access.', '{ESXi}', 'x-mitre-analytic--cb428c22-0a5a-44c9-ae63-6b1bedb34fee', 'DET0108', '[{"name": "esxi:shell", "channel": "base64 or gzip use within shell session", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:vmkernel", "channel": "Outbound traffic using encoded payloads post-login", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "ESXiLogs:authlog", "channel": "Unexpected login followed by encoding commands", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AuthSourceTrustLevel", "description": "Use to scope encoded traffic suspicion to accounts that should not initiate transfers"}, {"field": "ExfilBurstThreshold", "description": "Threshold for bursty outbound traffic size deviation from baseline"}]', '2026-05-01 15:26:36.435103');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1393, 'AN0562', 'Analytic 0562', 'Use of `esxcli network` commands (e.g., `esxcli network nic list`, `esxcli network ip interface ipv4 get`) via SSH or hostd to enumerate adapter and IP information.', '{ESXi}', 'x-mitre-analytic--cb70ad2f-7c96-4669-baed-3007246b0630', 'DET0195', '[{"name": "esxi:hostd", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SSHSessionOrigin", "description": "Detection may vary based on internal vs remote terminal usage"}, {"field": "esxcliCommandDepth", "description": "Distinguish between benign status checks and deep enumeration chains"}]', '2026-05-01 15:26:36.436369');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1394, 'AN0076', 'Analytic 0076', 'Detects curl, wget, Python requests, or custom HTTP clients communicating over non-standard ports, with repetitive or beacon-like patterns or POST-heavy behavior to rare domains.', '{Linux}', 'x-mitre-analytic--cba23232-7fae-47df-bd83-0ca5a5066373', 'DET0027', '[{"name": "NSM:Flow", "channel": "http.log, conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLinePatternMatch", "description": "curl or wget in scripts with suspicious domains or silent flags"}, {"field": "BeaconIntervalWindow", "description": "Fixed-timed HTTP callbacks with 60±5s jitter"}]', '2026-05-01 15:26:36.437506');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1395, 'AN1276', 'Analytic 1276', 'Multiple authentication failures for valid or invalid users followed by success from same IP/user', '{Linux}', 'x-mitre-analytic--cba73580-034b-4cdd-84a2-22704d520e9c', 'DET0463', '[{"name": "auditd:USER_LOGIN", "channel": "USER_AUTH", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Period of brute force activity correlation (e.g., 5 mins)"}, {"field": "IPWhitelist", "description": "Exclude known monitoring IPs or jump boxes"}, {"field": "LoginSource", "description": "Filter SSH vs. local logins"}]', '2026-05-01 15:26:36.438771');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1396, 'AN0052', 'Analytic 0052', 'A process (often LOLBin or user-launched program) loads a DLL from a user-writable/UNC/Temp path or unsigned/invalid signer. Within a short window the DLL is (a) newly written to disk, (b) spawned as follow-on execution (rundll32/regsvr32), or (c) establishes outbound C2.', '{Windows}', 'x-mitre-analytic--cc5f309c-6eb0-4f96-ba1a-0f4fd3bc1b79', 'DET0018', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "channel": "CodeIntegrity/WDAC events indicating unsigned/invalid DLL loads", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "TimeWindow", "description": "Correlation window between file write → module load → network (e.g., 0–20 minutes)."}, {"field": "SuspiciousPathRegex", "description": "Regex for user-writable/UNC/temp paths to flag (e.g., %TEMP%, %APPDATA%, \\\\*\\share\\)."}, {"field": "UnsignedOnly", "description": "Alert only when SignatureStatus != Valid to reduce noise."}, {"field": "RareSignerThreshold", "description": "Frequency threshold for unseen/rare signers in last N days."}, {"field": "MinFileSizeKB", "description": "Ignore tiny DLL stubs to cut noise."}]', '2026-05-01 15:26:36.440498');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1397, 'AN1122', 'Analytic 1122', 'Detects local daemons or scripts generating outbound DNS queries with long or frequent subdomains, indicative of DNS tunneling via tools like `iodine`, `dnscat2`, or `dig` from cronjobs or reverse shells.', '{Linux}', 'x-mitre-analytic--cc8183e1-9de4-469a-9117-79bf2e986e31', 'DET0400', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "dns.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "SubdomainEntropyScore", "description": "Detects encoded payloads or randomness in DNS labels"}, {"field": "DaemonAllowList", "description": "Allowlisted system daemons expected to perform frequent lookups"}]', '2026-05-01 15:26:36.442354');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1398, 'AN2011', 'Analytic 2011', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during exfiltration (ex: [Transfer Data to Cloud Account](https://attack.mitre.org/techniques/T1537)).', '{PRE}', 'x-mitre-analytic--cce3f1e3-a688-4519-bd9b-0ec5ba57bc11', 'DET0879', NULL, NULL, '2026-05-01 15:26:36.444065');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1399, 'AN0739', 'Analytic 0739', 'Detects removal of Apple Mail artifacts via AppleScript or direct deletion of mailbox content in ~/Library/Mail/, especially when preceded by Remote Login or C2-related API access.', '{macOS}', 'x-mitre-analytic--cd10c7fd-edef-4f85-aff3-9eaa35906b18', 'DET0266', '[{"name": "macos:unifiedlog", "channel": "log stream", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "ScriptCommandMatch", "description": "AppleScript references to Mail.app and delete commands"}, {"field": "LibraryPathMatch", "description": "Files within ~/Library/Mail/V*/ folders"}]', '2026-05-01 15:26:36.445585');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1400, 'AN0119', 'Analytic 0119', 'Unusual process or API usage attempting to query system locale, timezone, or keyboard layout (e.g., calls to GetLocaleInfoW, GetTimeZoneInformation). Detection can be enhanced by correlating with processes not typically associated with system configuration queries, such as unknown binaries or scripts.', '{Windows}', 'x-mitre-analytic--cd4d2b49-6a27-41a7-ab20-d2a3791142bd', 'DET0043', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "etw:Microsoft-Windows-Kernel-Base", "channel": "GetLocaleInfoW, GetTimeZoneInformation API calls", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "ParentProcessAllowList", "description": "Defines trusted processes expected to call locale APIs. Deviations may indicate adversarial activity."}, {"field": "TimeWindow", "description": "Specifies correlation window for API calls and suspicious process execution (e.g., 2m)."}]', '2026-05-01 15:26:36.447493');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1401, 'AN0924', 'Analytic 0924', 'AppleScript or terminal sessions launch tools (`curl`, `nc`, `ssh`) to external IPs not commonly accessed. Outbound connections are made by LaunchAgents/LaunchDaemons, often masquerading as system services.', '{macOS}', 'x-mitre-analytic--cd7fee55-79e6-42f4-9c68-e653cc8a1d24', 'DET0325', '[{"name": "macos:unifiedlog", "channel": "process logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "pf firewall logs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:osquery", "channel": "launchd or network_events", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "LaunchAgentPath", "description": "Detect persistence used to restart proxy after reboot."}, {"field": "ExternalPort", "description": "Often high or non-standard ports, configurable for outbound proxy detection."}, {"field": "ProcessReputation", "description": "Flag unsigned or anomalous binaries making external connections."}]', '2026-05-01 15:26:36.448976');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1402, 'AN0641', 'Analytic 0641', 'Enumeration of global address lists or email account metadata via PowerShell cmdlets (e.g., Get-GlobalAddressList) or MAPI/RPC from non-admin, non-mailserver systems.', '{Windows}', 'x-mitre-analytic--cd91348f-296f-4007-a853-6d06d8175210', 'DET0229', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLinePattern", "description": "Match variations of Get-GlobalAddressList, Get-Recipient, and related cmdlets."}, {"field": "HostRole", "description": "Suppress expected usage on Exchange servers or known IT admin consoles."}, {"field": "TimeWindow", "description": "Detect bulk execution patterns in short intervals, often used during recon."}]', '2026-05-01 15:26:36.450294');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1403, 'AN1323', 'Analytic 1323', 'Correlate suspicious registry modifications to known COM object CLSIDs with subsequent DLL loads or unexpected binary execution paths. Detect placement of COM CLSID entries under HKEY_CURRENT_USER\Software\Classes\CLSID\ overriding default HKLM paths. Flag anomalous DLL loads traced back to hijacked COM registry changes.', '{Windows}', 'x-mitre-analytic--cda93955-7500-49dd-9150-94bedae91d22', 'DET0481', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "RegistryPathScope", "description": "Defenders may tune specific monitored CLSIDs depending on known-good application behavior."}, {"field": "BinaryPathAnomalyThreshold", "description": "May require tuning based on environment to distinguish rare-but-legit COM DLLs vs suspicious ones."}, {"field": "TimeWindow", "description": "Correlating registry changes to DLL load or process execution may require configurable time window."}, {"field": "UserContextFilter", "description": "Tuning detection by isolating activity to specific user SIDs or admin-level activity may reduce false positives."}]', '2026-05-01 15:26:36.451529');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1404, 'AN0516', 'Analytic 0516', 'Correlate suspicious file transfers over SMB or Admin$ shares with process creation events (e.g., cmd.exe, powershell.exe, certutil.exe) that do not align with normal administrative behavior. Detect remote file writes followed by execution of transferred binaries.', '{Windows}', 'x-mitre-analytic--ce0f284b-f8d9-4cb0-84ad-97e1e8390d0c', 'DET0183', '[{"name": "WinEventLog:Security", "channel": "EventCode=5140", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Time period between file transfer and execution used to correlate events"}, {"field": "UserContext", "description": "Accounts allowed to perform legitimate administrative transfers"}, {"field": "FilePathWhitelist", "description": "Exclude known legitimate software update directories"}]', '2026-05-01 15:26:36.452718');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1405, 'AN1282', 'Analytic 1282', 'Use of the `security` command or Keychain API to extract known Wi-Fi passwords for target SSIDs.', '{macOS}', 'x-mitre-analytic--ce2233bb-9715-4e7b-8603-7218f8bae326', 'DET0464', '[{"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WiFiNetworkFilter", "description": "Match suspicious SSIDs being queried via `security find-generic-password -wa`"}, {"field": "ExecutionUser", "description": "Monitor root/admin usage of credential tools not linked to UI/system processes"}]', '2026-05-01 15:26:36.454103');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1406, 'AN1363', 'Analytic 1363', 'Monitor unified logs for access to payment applications, browser plug-ins, or Apple Pay services from non-standard processes. Detect anomalous use of Automator scripts or keychain extraction targeting financial account credentials.', '{macOS}', 'x-mitre-analytic--ce3ebda8-d47e-4730-a1f4-3366d33a98ab', 'DET0495', '[{"name": "macos:unifiedlog", "channel": "Non-standard processes invoking financial applications or payment APIs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Anomalous keychain access attempts targeting payment credentials", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MonitoredApps", "description": "Financial or payment applications to explicitly monitor for unauthorized use."}]', '2026-05-01 15:26:36.456537');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1407, 'AN0251', 'Analytic 0251', 'Installation or execution of a malicious browser or IDE extension, followed by abnormal registry entries or outbound network connections from the host application', '{Windows}', 'x-mitre-analytic--ce76c289-b810-44cf-b71e-afc76a70f7bf', 'DET0092', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "Image", "description": "Path of browser or IDE launching subprocesses—may vary depending on installed applications"}, {"field": "ParentImage", "description": "Legitimate parent-child process relationships for known safe extensions"}, {"field": "RegistryPath", "description": "Expected registry keys under HKCU/HKLM for installed extensions"}, {"field": "TimeWindow", "description": "Tunable interval to correlate extension install with follow-on C2 traffic"}]', '2026-05-01 15:26:36.458384');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1408, 'AN0276', 'Analytic 0276', 'Unauthorized firmware uploads to routers, switches, or firewalls via TFTP/FTP/SCP. Logs showing boot variable or startup image path changes redirecting to non-standard firmware images. Abnormal reboots or firmware rollback attempts following configuration modification events.', '{"Network Devices"}', 'x-mitre-analytic--ceb2c722-f9ec-41de-980e-d8848b1cb20c', 'DET0099', '[{"name": "networkdevice:config", "channel": "Boot image path or firmware configuration variable modified outside of maintenance windows", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"name": "networkdevice:runtime", "channel": "Firmware image uploaded via TFTP/FTP/SCP", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}]', '[{"field": "ApprovedFirmwareHashes", "description": "Known good firmware image hashes stored for validation."}, {"field": "MaintenanceWindows", "description": "Expected time periods when firmware uploads or reboots are considered normal."}, {"field": "SourceIPWhitelist", "description": "List of trusted management IPs allowed to initiate firmware uploads."}]', '2026-05-01 15:26:36.459895');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1409, 'AN1012', 'Analytic 1012', 'Burst of incomplete TCP handshakes (e.g., SYN floods) or uncorrelated ACK packets targeting the state table resulting in OS resource exhaustion.', '{Windows}', 'x-mitre-analytic--cecfe3bc-525a-431e-8ee1-5133ab8ce79c', 'DET0356', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Microsoft-Windows-TCPIP", "channel": "Connection queue overflow or failure to allocate TCP state object", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "NSM:Firewall", "channel": "High rate of inbound TCP SYN or ACK packets with missing 3-way handshake completion", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Threshold for burst traffic over short period (e.g., 30s - 2min)"}, {"field": "ConnectionRateThreshold", "description": "SYN/ACK packet rate threshold that triggers investigation"}, {"field": "ProcessParentCheck", "description": "Whether parent process of flooding tool is a known admin shell or unexpected context"}]', '2026-05-01 15:26:36.461298');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1410, 'AN0212', 'Analytic 0212', 'Execution of file transfer or network access activity through non-primary interfaces (e.g., WiFi, Bluetooth, cellular) by processes not typically associated with such behavior (e.g., rundll32, powershell, regsvr32).', '{Windows}', 'x-mitre-analytic--cf404364-1397-4f0f-9c21-cd534880722a', 'DET0077', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:System", "channel": "EventCode=5005 (WLAN), EventCode=302 (Bluetooth)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "InterfaceType", "description": "Filter for specific interface categories (e.g., WiFi, Bluetooth, 4G)."}, {"field": "FileSizeThreshold", "description": "Tunable for environment-specific large file access events pre-transfer."}, {"field": "TimeWindow", "description": "Temporal correlation window for file read followed by network activity."}]', '2026-05-01 15:26:36.462917');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1411, 'AN1938', 'Analytic 1938', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1412, 'AN2009', 'Analytic 2009', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1413, 'AN0789', 'Analytic 0789', 'Processes such as osascript, curl, or office applications sending data to text storage APIs/domains. Defender perspective: anomalous clipboard or file reads by unexpected applications immediately followed by outbound HTTPS requests to pastebin-like services.', '{macOS}', 'x-mitre-analytic--cf74f802-0080-41ff-8745-9c42af313462', 'DET0284', '[{"name": "macos:unifiedlog", "channel": "execution of curl, osascript, or unexpected Office processes", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "file read of sensitive directories", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "HTTPS POST requests to pastebin.com or similar", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "WatchedApps", "description": "Processes not normally associated with data uploads (e.g., Preview, Calculator)."}, {"field": "EntropyThreshold", "description": "High entropy detection to flag encoded or encrypted data exfiltration."}]', '2026-05-01 15:26:36.466967');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1419, 'AN0662', 'Analytic 0662', 'Adversary modifies website or application-hosted content via unauthorized file changes or script injections, often by exploiting web servers or CMS access.', '{Windows}', 'x-mitre-analytic--d02dbf1d-b6e9-4c3c-84a2-f70fec797504', 'DET0238', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Application", "channel": "Unexpected web application errors or CMS logs showing modification to index.html, default.aspx, or other public-facing files", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "target_filenames", "description": "Environment-specific naming of defacement-prone files like ''index.html'', ''main.css'', ''app.js''."}, {"field": "TimeWindow", "description": "Detection based on rapid sequence of file writes and script injections within short time intervals."}]', '2026-05-01 15:26:36.475844');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1420, 'AN0120', 'Analytic 0120', 'Detection of commands accessing locale, timezone, or language settings such as ''locale'', ''timedatectl'', or parsing /etc/timezone. Anomalous execution by unusual users or automation scripts should be flagged.', '{Linux}', 'x-mitre-analytic--d053d033-b587-4ed0-bdbc-0c6a9bdd7c82', 'DET0043', '[{"name": "auditd:SYSCALL", "channel": "execve calls to locale, timedatectl, or cat /etc/timezone", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Unexpected users running location discovery commands may indicate malicious behavior."}]', '2026-05-01 15:26:36.477184');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1421, 'AN1545', 'Analytic 1545', 'Detection of interactive and remote logins by service accounts or users at unusual times, with unexpected child process activity.', '{macOS}', 'x-mitre-analytic--d059a437-bf45-4b10-a36c-7e42e183d3c7', 'DET0560', '[{"name": "macos:unifiedlog", "channel": "loginwindow, sshd", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "macos:unifiedlog", "channel": "exec logs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "LoginOrigin", "description": "Login sourced from unexpected remote addresses."}, {"field": "ProcessTreeDepth", "description": "Track execution depth or anomalous chains post-login."}]', '2026-05-01 15:26:36.478406');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1422, 'AN1541', 'Analytic 1541', 'Detect commands such as ''esxcli system shutdown'' or ''vim-cmd vmsvc/power.shutdown'' executed outside of maintenance windows or via unusual users. Reboot logs in hostd.log and shell logs should be correlated.', '{ESXi}', 'x-mitre-analytic--d076faf3-c5bd-4e5c-93a5-8408c9e80fe1', 'DET0559', '[{"name": "esxi:hostd", "channel": "Powering off or restarting host", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}, {"name": "esxi:shell", "channel": "esxcli system shutdown or reboot invoked", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AccountRole", "description": "Administrative account context validation."}, {"field": "MaintenanceWindow", "description": "Expected times for reboot/shutdown behavior."}]', '2026-05-01 15:26:36.481001');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1423, 'AN0546', 'Analytic 0546', 'Detects PAM module modifications or removal of MFA hooks in /etc/pam.d/ configurations, correlated with successful authentications lacking MFA prompts.', '{Linux}', 'x-mitre-analytic--d0a9cbc4-d190-44fb-b067-27153e35dc49', 'DET0190', '[{"name": "auditd:SYSCALL", "channel": "open/write to /etc/pam.d/*", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Connections", "channel": "Successful login without expected MFA challenge", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "MFAHooks", "description": "Paths to organization-specific PAM modules enforcing MFA."}]', '2026-05-01 15:26:36.4825');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1424, 'AN0048', 'Analytic 0048', 'Adversary executes commands to enumerate installed antivirus, EDR, or firewall agents using WMI, registry queries, and built-in tools (e.g., tasklist, netsh, sc query). Correlated with elevated process privileges or scripting engine usage.', '{Windows}', 'x-mitre-analytic--d0d1375d-f5c2-4271-b5e7-415c478d5e86', 'DET0016', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ParentProcess", "description": "Defenders can tune based on trusted or known-good parent process relationships"}, {"field": "ImagePathContains", "description": "Regex match on adversary tool or enumeration script used"}]', '2026-05-01 15:26:36.483665');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1425, 'AN0885', 'Analytic 0885', 'Execution of CLI commands erasing file systems or storage (erase flash:, format disk, erase nvram:). Detect authentication events followed by destructive commands within the same privileged session.', '{"Network Devices"}', 'x-mitre-analytic--d0e64036-83fb-4ff7-b81b-9b67b6c6b9dc', 'DET0316', '[{"name": "networkdevice:cli", "channel": "erase flash:, erase nvram:, format disk", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "Privileged login followed by destructive command sequence", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "PrivilegedUsers", "description": "Tune to exclude approved maintenance performed by authorized administrators."}, {"field": "CommandPatterns", "description": "Expand or narrow destructive command coverage depending on vendor-specific syntax."}]', '2026-05-01 15:26:36.484959');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1426, 'AN0598', 'Analytic 0598', 'Processes on macOS initiate external connections that consistently transmit data in fixed sizes using LaunchAgents or unexpected users.', '{macOS}', 'x-mitre-analytic--d0edef63-9a98-4435-9f4b-2c577c7de41d', 'DET0213', '[{"name": "macos:unifiedlog", "channel": "com.apple.network", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_CONNECT", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "LaunchdJobContext", "description": "Agent context in which transfer occurs (e.g., user/privileged)"}, {"field": "TransferSizeMedian", "description": "Used to define what constitutes ''fixed size'' chunks"}, {"field": "TransferProtocolOutlier", "description": "Detect if protocol usage deviates from common apps for given destination"}]', '2026-05-01 15:26:36.48635');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1427, 'AN0507', 'Analytic 0507', 'Detection of adversary enumeration of domain or local group memberships via native tools such as net.exe, PowerShell, or WMI. This activity may precede lateral movement or privilege escalation.', '{Windows}', 'x-mitre-analytic--d14cc347-9e27-479d-8347-1a5950cdd70c', 'DET0179', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandLineRegex", "description": "Regex filters for matching suspicious group enumeration commands (e.g., ''net group'', ''Get-ADGroupMember'')."}, {"field": "TimeWindow", "description": "Time threshold for correlating group discovery with subsequent suspicious activity (e.g., lateral movement)."}, {"field": "UserContext", "description": "Whether the user performing discovery is in a sensitive group or running under unusual context (e.g., non-admin querying Domain Admins)."}]', '2026-05-01 15:26:36.487666');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1428, 'AN0987', 'Analytic 0987', 'Detects VIBs, scripts, or binaries placed into directories like /bin or /etc/vmware with names mimicking standard ESXi components. Also monitors unauthorized creation of services.', '{ESXi}', 'x-mitre-analytic--d16be21c-6df4-4648-91cd-36152dafa38d', 'DET0347', '[{"name": "esxi:vmkernel", "channel": "Exec", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "esxi:vmkernel", "channel": "module load", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "esxi:hostd", "channel": "Service events", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "esxi:hostd", "channel": "task creation events", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}]', '[{"field": "esxi_baseline_file_list", "description": "Known good binaries and their expected paths"}, {"field": "service_creation_alert_threshold", "description": "Threshold for unknown service names or mismatched digital signatures"}]', '2026-05-01 15:26:36.489127');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1429, 'AN0470', 'Analytic 0470', 'Detects modification or truncation of `/var/log/shell.log` used to persist ESXi shell command history. Especially suspicious shortly after login or config changes.', '{ESXi}', 'x-mitre-analytic--d17e0719-d338-47eb-a5b4-8616749584cf', 'DET0165', '[{"name": "esxi:shell", "channel": "/var/log/shell.log", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "LogFilePath", "description": "Path to shell command history on ESXi."}, {"field": "TimeWindow", "description": "Time range post-login or privileged escalation."}]', '2026-05-01 15:26:36.490728');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1430, 'AN0882', 'Analytic 0882', 'Processes attempting raw disk access via \\.\PhysicalDrive paths, abnormal file I/O to MBR/boot sectors, or loading of third-party drivers (e.g., RawDisk) that enable disk overwrite. Correlate process creation, privilege usage, and disk modification events within a short time window.', '{Windows}', 'x-mitre-analytic--d1ad1b0b-0050-4737-8993-73c2da8d143b', 'DET0316', '[{"name": "WinEventLog:Security", "channel": "EventCode=4673", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "WinEventLog:Sysmon", "channel": "Raw disk writes targeting \\\\.\\PhysicalDrive* or MBR locations", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}]', '[{"field": "ProcessWhitelist", "description": "Backup, forensics, or imaging tools may perform legitimate raw disk access — requires tuning per environment."}, {"field": "TimeWindow", "description": "Correlation threshold for process execution, driver load, and raw disk writes."}]', '2026-05-01 15:26:36.492196');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1431, 'AN1144', 'Analytic 1144', 'Detects anomalous NTLM LogonType 3 authentications that occur without accompanying domain logon events, especially from lateral systems or involving built-in administrative tools. Monitors for mismatches between source user context and system being accessed. Correlates LogonSession creation, NTLM authentications, and process/service initiation to identify suspicious use of stolen password hashes for remote access or service logon without password entry. Detects overpass-the-hash by combining Kerberos ticket issuance with NTLM-based lateral movement.', '{Windows}', 'x-mitre-analytic--d1bcc6a4-e84a-4251-b86b-e8fe2ecc0dd1', 'DET0409', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4768", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Allows tuning the correlation timeframe between authentication, session creation, and process/network activity."}, {"field": "SourceAccountAnomalyThreshold", "description": "Supports tuning detection sensitivity based on deviations from normal user login patterns or usage context."}, {"field": "LogonTypeFilter", "description": "Allows focusing detection on specific logon types (e.g., LogonType 3 for network logon, Type 10 for RDP)."}]', '2026-05-01 15:26:36.493542');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1432, 'AN1038', 'Analytic 1038', 'Correlate file modifications in shell startup scripts (e.g., .bashrc, .profile) with embedded `trap` commands and observe if those changes are followed by the unexpected execution of child processes when terminal signals (e.g., SIGINT) are triggered. Use contextual linking with user session activity to detect privilege misuse.', '{Linux}', 'x-mitre-analytic--d1d19568-2b59-4d44-9744-22d7304d2200', 'DET0369', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "Modification of user shell profile or trap registration via echo/redirection (e.g., echo \"trap ''malicious_cmd'' INT\" >> ~/.bashrc)", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "TargetShellFilePath", "description": "The path to user profile scripts (e.g., ~/.bashrc, ~/.zshrc); may differ by distro or shell type."}, {"field": "SignalTrapName", "description": "Trap signal (e.g., INT, HUP, TERM) can be environment-specific or attacker-tuned to evade."}, {"field": "TimeWindow", "description": "Temporal threshold to correlate trap insertion and process execution (e.g., 10s-5min)"}]', '2026-05-01 15:26:36.49472');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1433, 'AN0718', 'Analytic 0718', 'Forged web credentials may manifest as anomalous SAML token issuance, OpenID Connect token minting, or Zimbra pre-auth key usage. Defenders may see tokens issued without normal authentication events, multiple valid tokens generated simultaneously, or signing anomalies in IdP logs.', '{"Identity Provider"}', 'x-mitre-analytic--d1eafedb-ac64-46b0-972d-8f8759fc11b3', 'DET0260', '[{"name": "azure:signinlogs", "channel": "SAML/OIDC tokens issued without corresponding MFA or password validation", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}, {"name": "NSM:Connections", "channel": "Pre-authentication keys generated or token signing anomalies", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}]', '[{"field": "TokenLifetimeThreshold", "description": "Limit the maximum time temporary tokens are valid."}, {"field": "ExpectedAuthFlows", "description": "Define normal authentication flows (e.g., password+MFA) to baseline token issuance."}]', '2026-05-01 15:26:36.496172');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1434, 'AN1582', 'Analytic 1582', 'Detects use of built-in SaaS sharing mechanisms to transfer ownership or share access of critical data to external tenants or untrusted users through API calls or link generation features.', '{SaaS}', 'x-mitre-analytic--d1ef9a86-7781-4b9e-9178-c2e5b1782c1f', 'DET0573', '[{"name": "saas:googledrive", "channel": "drive.permission.add", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}, {"name": "saas:box", "channel": "collaboration.invite", "x_mitre_data_component_ref": "x-mitre-data-component--e214eb6d-de8f-4154-9015-6d47915fbed1"}]', '[{"field": "UserContext", "description": "Whether the user is in a high-privileged or VIP group"}, {"field": "DomainReputationList", "description": "Allowlist or blocklist of external SaaS domains"}, {"field": "PayloadVolumeThreshold", "description": "Size or number of shared files triggering alert"}]', '2026-05-01 15:26:36.497568');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1435, 'AN0869', 'Analytic 0869', 'Monitoring for discrepancies between system daemon/service state and reported health messages (e.g., syslog shows AV/IDS daemon stopped, but spoofed messages claim it is still running). Detects userland processes impersonating AV/IDS command-line outputs or modifying log forwarding configurations.', '{Linux}', 'x-mitre-analytic--d1feb97f-3683-49f5-b5a8-b54d58de3444', 'DET0311', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of binaries/scripts presenting false health messages for security daemons", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Service stop or disable messages for security tools not reflected in SIEM alerts", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "SecurityDaemonList", "description": "Names of AV/IDS/EDR daemons monitored in Linux environments."}]', '2026-05-01 15:26:36.498783');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1436, 'AN0527', 'Analytic 0527', 'OAuth or SAML access tokens reused across multiple sessions or clients without corresponding MFA or login activity.', '{"Identity Provider"}', 'x-mitre-analytic--d203b007-e462-4842-82ce-c97f52c17e39', 'DET0185', '[{"name": "azure:signinlogs", "channel": "TokenIssued, RefreshTokenUsed", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "m365:unified", "channel": "Delegated permission grants without user login event", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "MFAEnforcement", "description": "Ensure MFA context exists prior to token issuance"}, {"field": "TokenReuseWindow", "description": "Maximum acceptable window for refresh token reuse"}]', '2026-05-01 15:26:36.500005');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1437, 'AN0261', 'Analytic 0261', 'Detects unusual use of `cron` or `sleep` loops inside containers executing unfamiliar scripts or binaries repeatedly.', '{Containers}', 'x-mitre-analytic--d20d7cf8-ecac-4011-96e0-3ec862223c11', 'DET0094', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "containerd:runtime", "channel": "file change monitoring within /etc/cron.*, /tmp, or mounted volumes", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "ContainerLabel", "description": "Labels or tags indicating dev/test containers executing scheduled tasks."}, {"field": "ScriptFrequency", "description": "Repetitive invocation pattern within short container lifespan."}, {"field": "ImageSource", "description": "Unexpected container image sources creating cron entries."}]', '2026-05-01 15:26:36.502613');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1438, 'AN0423', 'Analytic 0423', 'Detects data access or staging events followed by outbound data flows using unencrypted protocols (e.g., FTP, HTTP) initiated by unexpected processes or to rare destinations.', '{Windows}', 'x-mitre-analytic--d265376d-3cdc-4e95-a8ea-4c4278860218', 'DET0149', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "http.log, ftp.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "UnencryptedProtocolList", "description": "Set of protocols considered suspicious for outbound data exfiltration (e.g., FTP, HTTP)."}, {"field": "DataTransferSizeThreshold", "description": "Defines what amount of outbound data is considered abnormal for a host/user."}, {"field": "ParentProcessDenylist", "description": "Processes that should not launch FTP/HTTP clients (e.g., winword.exe launching ftp.exe)."}]', '2026-05-01 15:26:36.5038');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1439, 'AN0890', 'Analytic 0890', 'Unusual ESXi shell commands disabling syslog forwarding or stopping hostd/vpxa daemons. Detect modifications to firewall rules on ESXi host or disabling of lockdown mode.', '{ESXi}', 'x-mitre-analytic--d2762796-1dea-448a-970a-7aeb176aa668', 'DET0317', '[{"name": "esxi:shell", "channel": "esxcli system syslog config set --loghost='''' or stopping hostd service", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:vmkernel", "channel": "Disabling or modifying firewall rules", "x_mitre_data_component_ref": "x-mitre-data-component--c97d0171-f6e0-4415-85ff-4082fdb8c72a"}]', '[{"field": "LogDestination", "description": "Tune for environment-specific log forwarding hosts."}]', '2026-05-01 15:26:36.50501');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1454, 'AN2015', 'Analytic 2015', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during [Phishing](https://attack.mitre.org/techniques/T1566), [Endpoint Denial of Service](https://attack.mitre.org/techniques/T1499), or [Network Denial of Service](https://attack.mitre.org/techniques/T1498).', '{PRE}', 'x-mitre-analytic--d52fee09-db6e-4fe5-a859-7f3d273e85f0', 'DET0883', NULL, NULL, '2026-05-01 15:26:36.525901');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1440, 'AN1295', 'Analytic 1295', 'Detection of binaries spawning encrypted sessions using OpenSSL or curl to external services with mismatched ports/protocols. Identifies behavior where internal services simulate trusted cloud service traffic patterns.', '{Linux}', 'x-mitre-analytic--d27a6df2-b2df-443e-8e01-c90243465ceb', 'DET0470', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Network Capture TLS/HTTP", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ProtocolMatchConfidence", "description": "Threshold for header-field mismatch against expected service behavior."}, {"field": "TimeWindow", "description": "Correlation window between process spawn and encrypted session."}]', '2026-05-01 15:26:36.50661');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1441, 'AN1530', 'Analytic 1530', 'Monitors for anomalous binary files written to disk with padded size and subsequent execution by user or service context.', '{macOS}', 'x-mitre-analytic--d27caeb7-7af2-4a55-9dcb-734730c0ccf1', 'DET0553', '[{"name": "macos:unifiedlog", "channel": "process:spawn", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "file write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "FileSizeThresholdMB", "description": "Padded binary threshold for file size"}, {"field": "TimeWindow", "description": "Detection correlation window for execution after file creation"}, {"field": "UserContext", "description": "Filters for specific users or groups such as admin or service accounts"}]', '2026-05-01 15:26:36.508195');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1442, 'AN0292', 'Analytic 0292', 'Use of hash-cracking tools (e.g., John the Ripper, Hashcat) after credential dumping, combined with high CPU usage or GPU invocation via unsigned binaries accessing password hash files', '{Windows}', 'x-mitre-analytic--d2a45051-b999-4969-aeb0-d7f83d453976', 'DET0105', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "HashToolName", "description": "Match execution against known cracking toolnames like hashcat.exe, john.exe, etc."}, {"field": "FilePathIndicators", "description": "Watch for access to common hash dump locations (e.g., SAM, SYSTEM, NTDS.dit)"}, {"field": "ExecutionContext", "description": "Run context: local interactive user vs. scheduled task or remote session"}]', '2026-05-01 15:26:36.509536');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1443, 'AN0849', 'Analytic 0849', 'Enumeration of local ESXi accounts using esxcli or vSphere API from unauthorized sessions.', '{ESXi}', 'x-mitre-analytic--d2bca034-2f97-4c64-ac30-e75d24886be7', 'DET0303', '[{"name": "vpxd.log", "channel": "vCenter Management", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "esxi:shell", "channel": "Shell Execution", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandPattern", "description": "Look for ''esxcli system account list'' and API calls from unusual sources."}, {"field": "SessionType", "description": "Restrict detection to interactive sessions vs. maintenance/automation jobs."}]', '2026-05-01 15:26:36.51067');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1444, 'AN0303', 'Analytic 0303', 'Custom scripts or processes encode outbound traffic using gzip, Base64, or hex prior to exfiltration via curl, wget, or custom sockets. Encoding typically occurs before or during outbound connections from non-network daemons.', '{Linux}', 'x-mitre-analytic--d32cc2a4-60ed-4761-809e-a59cde2a1881', 'DET0108', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Base64 strings or gzip in URI, headers, or POST body", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "linux:syslog", "channel": "Unusual outbound transfers from CLI tools like base64, gzip, or netcat", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindow", "description": "Tune duration of multi-stage encoding + transfer operations to account for script variability"}, {"field": "UserContext", "description": "Apply user allow/block list depending on which users normally perform CLI encoding"}]', '2026-05-01 15:26:36.511984');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1445, 'AN0033', 'Analytic 0033', 'Anomalous traffic from ESXi host management daemons (like hostd or vpxa) embedding non-standard payloads in management protocols (e.g., HTTPS) or beaconing behavior.', '{ESXi}', 'x-mitre-analytic--d3bad85b-9e86-4de8-9e4a-1666133af782', 'DET0011', '[{"name": "esxi:vmkernel", "channel": "Network activity", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "esxi:hostd", "channel": "System service interactions", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TLSFingerprintMismatch", "description": "Detects mismatched TLS client behavior vs expected for hostd/vpxa."}, {"field": "UnusualDestinationPorts", "description": "Highlight traffic from ESXi hosts to uncommon ports outside vCenter ranges."}]', '2026-05-01 15:26:36.513166');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1446, 'AN0811', 'Analytic 0811', 'Detects SaaS web login followed by dashboard or web GUI page views from unfamiliar locations, devices, or access patterns. Identifies use of sensitive reporting or configuration consoles accessed from high-risk accounts.', '{SaaS}', 'x-mitre-analytic--d3e3ed48-7402-40df-a6cc-db9b560bcfd1', 'DET0291', '[{"name": "saas:zoom", "channel": "Zoom Admin Dashboard accessed from unfamiliar IP/device", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "saas:salesforce", "channel": "Login", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "saas:box", "channel": "User navigated to admin interface", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "SaaSDashboardViewList", "description": "List of GUI pages or endpoints considered sensitive"}, {"field": "IPReputationThreshold", "description": "Reputation score or allowlist of source IPs"}, {"field": "LoginBehaviorBaseline", "description": "Typical user/device login pairings or login frequency"}]', '2026-05-01 15:26:36.514318');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1447, 'AN0583', 'Analytic 0583', 'Registry modification of the LSA Authentication Packages key followed by LSASS loading a non-standard or unsigned DLL. This includes unusual write access to `HKLM\SYSTEM\CurrentControlSet\Control\Lsa`, especially during non-installation timeframes. Correlated with `lsass.exe` loading DLLs not present in baseline or lacking valid signatures.', '{Windows}', 'x-mitre-analytic--d415367c-3624-4a68-a2b7-4734662db190', 'DET0207', '[{"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "TimeWindow", "description": "Time between registry write and DLL load; tune based on reboot cycles or scheduled maintenance"}, {"field": "ImageSignatureStatus", "description": "Allow listing of known signed LSASS-authenticated DLLs versus unknown/untrusted ones"}, {"field": "RegistryPathScope", "description": "Allow tuning for subkeys beyond just `Authentication Packages` (e.g., `Security Packages`, `Notification Packages`)"}, {"field": "UserContext", "description": "Correlate user responsible for registry edit; tune for expected administrative/service accounts"}, {"field": "ParentProcess", "description": "Validate process lineage for registry modification; expected tools like `reg.exe` or `powershell.exe`"}]', '2026-05-01 15:26:36.515451');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1448, 'AN1011', 'Analytic 1011', 'Monitor unified logs and Mail.app activity for repetitive incoming messages with attachments. Defenders should look for large volumes of incoming mail stored under ~/Library/Mail with unusual timing or repetitive subjects.', '{macOS}', 'x-mitre-analytic--d41cdfc1-2a82-4442-a1ca-177fe59b8dff', 'DET0355', '[{"name": "macos:unifiedlog", "channel": "Repetitive inbound email delivery activity logged within a short time window", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "fs:fsusage", "channel": "create: Attachment file creation in ~/Library/Mail directories", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "FileCountThreshold", "description": "Threshold for repetitive attachment files created within a defined interval."}]', '2026-05-01 15:26:36.516788');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1449, 'AN0906', 'Analytic 0906', 'Detects shell or API usage of `esxcli network ip connection list` or `netstat` to enumerate ESXi host connections.', '{ESXi}', 'x-mitre-analytic--d42c2a80-bf02-460f-b279-147940ece3a9', 'DET0320', '[{"name": "esxi:hostd", "channel": "command log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ExecutionOriginCheck", "description": "Detect commands executed outside normal management interfaces (e.g., SSH or root shell)."}, {"field": "ExpectedAdminAccessWindow", "description": "Timeframe when host connection audits are expected (e.g., maintenance windows)."}]', '2026-05-01 15:26:36.517982');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1450, 'AN0385', 'Analytic 0385', 'Processes invoking destructive commands (dd, shred, wipe) with raw device targets (e.g., /dev/sda, /dev/nvme0n1). Detect direct writes to disk partitions and abnormal superblock or bootloader modifications. Correlate shell execution with subsequent block device I/O.', '{Linux}', 'x-mitre-analytic--d442d480-cfb9-43cc-b959-2f81513b432d', 'DET0137', '[{"name": "auditd:SYSCALL", "channel": "open/write syscalls on /dev/sd* or /dev/nvme*", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}, {"name": "auditd:EXECVE", "channel": "Execution of dd, shred, wipe targeting block devices", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetDevices", "description": "Tune to exclude removable drives or test partitions commonly written by administrators."}, {"field": "EntropyThreshold", "description": "Detects large blocks of pseudorandom data being written; may need tuning for backup/crypto workloads."}]', '2026-05-01 15:26:36.520136');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1451, 'AN1513', 'Analytic 1513', 'Office apps or scripts writing files followed by xattr manipulation (to evade quarantine) and subsequent HTTPS uploads. Defender perspective: anomalous file modification + outbound TLS traffic originating from non-networking apps (Word, Excel, Preview).', '{macOS}', 'x-mitre-analytic--d49c13ed-df07-4bb3-a2dc-43411e5d402a', 'DET0548', '[{"name": "macos:unifiedlog", "channel": "execution of Office binaries with network activity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "read/write of user documents prior to upload", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "outbound TLS connections to cloud storage providers", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "WatchedApplications", "description": "Applications not expected to perform bulk data transfers (Office apps, Preview)."}]', '2026-05-01 15:26:36.521372');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1452, 'AN1601', 'Analytic 1601', 'Process using URLSession or similar API to fetch from web services without any response handling, indicative of one-way C2 channels.', '{macOS}', 'x-mitre-analytic--d49f06ba-7a81-440b-bc16-c583ba918a3d', 'DET0581', '[{"name": "macos:unifiedlog", "channel": "process, network", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:endpointsecurity", "channel": "exec events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Flag unexpected outbound activity from non-admin or system users"}, {"field": "EntropyScore", "description": "Optional if script-based obfuscation is seen in web requests"}]', '2026-05-01 15:26:36.522825');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1453, 'AN1223', 'Analytic 1223', 'Detects anomalous process execution patterns where a process''s parent terminates quickly after process creation or is re-parented to ''init'' (PID 1), often indicating double-fork or daemon-style detachment. These behaviors sever the parent-child relationship and obscure the execution origin in process tree analysis.', '{Linux}', 'x-mitre-analytic--d4a29d94-bce4-4069-a0b5-9e0e731cff97', 'DET0443', '[{"name": "auditd:SYSCALL", "channel": "fork/clone/daemon syscall tracing", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "auditd:SYSCALL", "channel": "execve of re-parented process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Maximum time between parent and child process creation and parent process termination"}, {"field": "ReparentingDetectionScope", "description": "Scope for detecting unexpected re-parenting to init/systemd"}, {"field": "ExecutableScope", "description": "Subset of monitored executables or services likely to abuse double-fork"}]', '2026-05-01 15:26:36.524456');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1456, 'AN1196', 'Analytic 1196', 'Abuse of bind mounts to obscure process directories. Defender perspective: detecting anomalous mount operations where a process’s /proc entry is remapped to another directory, often hiding malicious activity from native utilities (ps, top). Behavior chain includes: (1) execution of `mount` with `-o bind` or `-B` flags, (2) modification of /proc entries inconsistent with expected process lineage, and (3) subsequent anomalous activity from processes whose metadata no longer matches execution context.', '{Linux}', 'x-mitre-analytic--d5c81e57-37c4-4393-a202-0955af560983', 'DET0428', '[{"name": "auditd:SYSCALL", "channel": "mount system call with bind or remap flags", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "auditd:PATH", "channel": "mount target path within /proc/*", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "linux:osquery", "channel": "process metadata mismatch between /proc and runtime attributes", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "BindMountFlags", "description": "Flags or options used in mount commands (e.g., -o bind, -B). Can vary across distributions and kernels."}, {"field": "WatchedProcPaths", "description": "List of /proc paths to monitor. Tunable to reduce noise from benign bind mounts used in containers or chroot environments."}, {"field": "CorrelationWindow", "description": "Timeframe to correlate bind mount creation with anomalous process or file activity."}]', '2026-05-01 15:26:36.528676');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1457, 'AN0104', 'Analytic 0104', 'Adversary registers a Windows device to Entra ID or bypasses conditional access by adding device via Intune registration pipeline using stolen credentials.', '{Windows}', 'x-mitre-analytic--d5dc64ab-bb69-4893-a155-84d403040e1a', 'DET0036', '[{"name": "WinEventLog:Security", "channel": "Device Object Creation", "x_mitre_data_component_ref": "x-mitre-data-component--18b236d8-7224-488f-9d2f-50076a0f653a"}, {"name": "ApplicationLog:Intune/MDM Logs", "channel": "Enrollment events (e.g., MDMDeviceRegistration)", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "DeviceNamePattern", "description": "Adjust pattern matching logic for unusual or non-corporate device names"}, {"field": "UserContext", "description": "Correlate with prior logon location or device usage behavior"}, {"field": "EnrollmentMethod", "description": "Distinguish between MDM vs manual onboarding vs automated scripts"}]', '2026-05-01 15:26:36.530355');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1458, 'AN1045', 'Analytic 1045', 'Monitor for suspicious use of Windows API calls such as IsDebuggerPresent() and NtQueryInformationProcess(), or processes manually checking the BeingDebugged flag in the Process Environment Block (PEB). Detect sequences of OutputDebugStringW() calls in short intervals that may indicate debugger flooding attempts.', '{Windows}', 'x-mitre-analytic--d5f0b652-3699-45af-97e6-81e7426558bd', 'DET0371', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "NtQueryInformationProcess", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "ApiCallFrequencyThreshold", "description": "Number of repeated debug-related API calls allowed before raising an alert"}, {"field": "ProcessAllowList", "description": "Legitimate debuggers or developer tools that may trigger similar behaviors"}]', '2026-05-01 15:26:36.531838');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1459, 'AN0352', 'Analytic 0352', 'Abuse of cloud metadata APIs or CLI to push SSH public keys to authorized_keys of virtual machines.', '{IaaS}', 'x-mitre-analytic--d613771b-087c-43c4-8430-2a0bf6ebb314', 'DET0126', '[{"name": "gcp:audit", "channel": "compute.instances.setMetadata", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "MetadataFieldName", "description": "Custom metadata field (e.g., ssh-keys or custom-key)"}, {"field": "AccountType", "description": "Was it an admin, service principal, or automation user initiating?"}, {"field": "TargetRoleEscalation", "description": "Privilege level of the VM account receiving the key"}]', '2026-05-01 15:26:36.533153');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1460, 'AN1234', 'Analytic 1234', 'Adversaries attempt to read sensitive files such as /etc/passwd and /etc/shadow for credential dumping. This may involve access to the files directly via command-line utilities (e.g., cat, less), creation of backup copies, or parsing through post-exploitation frameworks. Multi-event correlation includes elevated process execution, file access/read on sensitive paths, and anomalous read behaviors tied to non-root or unusual users.', '{Linux}', 'x-mitre-analytic--d6166e3d-2e29-4097-9fb4-c66ce0616897', 'DET0446', '[{"name": "auditd:SYSCALL", "channel": "open, read", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "exe", "description": "Executable name used to access credentials (e.g., cat, cp, awk); can vary across environments"}, {"field": "user", "description": "User context under which the access occurs; typically root, but can be non-standard in attacks"}, {"field": "PATH", "description": "Target file paths (e.g., /etc/passwd, /etc/shadow); may vary in containerized or customized systems"}, {"field": "TimeWindow", "description": "Time correlation threshold for chaining access and execution events"}]', '2026-05-01 15:26:36.534416');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1461, 'AN1139', 'Analytic 1139', 'Detects abnormal or rare logins via local accounts through system or remote mechanisms such as SSH.', '{macOS}', 'x-mitre-analytic--d6288db6-ff55-4720-b0ee-7aca3e65cc72', 'DET0407', '[{"name": "macos:unifiedlog", "channel": "loginwindow or sshd", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "UserContext", "description": "Restrict expected local users by device owner or role."}, {"field": "TimeWindow", "description": "Set appropriate bounds based on endpoint usage patterns."}]', '2026-05-01 15:26:36.535722');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1462, 'AN1456', 'Analytic 1456', 'Use of cloud API calls (e.g., AWS EC2 DescribeInstances, Azure VM Inventory) to enumerate system configurations across assets.', '{IaaS}', 'x-mitre-analytic--d664b158-5035-4e0b-a069-7a5b27ce0936', 'DET0525', '[{"name": "AWS:CloudTrail", "channel": "DescribeInstances, GetConsoleOutput, DescribeImages", "x_mitre_data_component_ref": "x-mitre-data-component--2a80d95f-08c4-48e3-833e-151ef19d90f5"}]', '[{"field": "IAMRoleContext", "description": "Limit detection to non-standard identities performing these calls."}, {"field": "APIFrequency", "description": "Identify enumeration sweeps by volume."}]', '2026-05-01 15:26:36.536989');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1463, 'AN0912', 'Analytic 0912', 'Direct execution of /bin/vmx or presence of rogue .vmx files not registered in vCenter inventory. Defender perspective: anomalous commands in shell history, edits to rc.local.d/local.sh for persistence.', '{ESXi}', 'x-mitre-analytic--d677a72d-db0e-4332-a467-95b19836ef16', 'DET0321', '[{"name": "esxi:hostd", "channel": "Execution of ''/bin/vmx'' or modifications to ''/etc/rc.local.d/local.sh''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:vmkernel", "channel": "VMX startup messages without associated vCenter inventory records", "x_mitre_data_component_ref": "x-mitre-data-component--b597a220-6510-4397-b0d8-342cd2c58827"}]', '[{"field": "VMInventorySync", "description": "Cross-verify running VMs with vCenter inventory for rogue instances."}]', '2026-05-01 15:26:36.538322');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1464, 'AN0488', 'Analytic 0488', 'A trusted/signed developer utility (parent) is executed in a non-developer context and (a) spawns suspicious children (e.g., powershell.exe, cmd.exe, rundll32.exe, regsvr32.exe, wscript.exe), (b) loads unsigned/user-writable DLLs, (c) writes and then runs a new PE from user-writable paths, and/or (d) immediately makes outbound network connections.', '{Windows}', 'x-mitre-analytic--d69c9d97-17d6-4dad-a4d4-ec41e7fb34fb', 'DET0172', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:AppLocker", "channel": "AppLocker audit/blocks showing developer utilities executing scripts/binaries outside policy", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "TimeWindow", "description": "Correlation window between developer utility execution, payload write, and network egress (e.g., 0–30 minutes)."}, {"field": "AllowedUtilitiesList", "description": "Org-specific list of dev utilities legitimately used on build/dev hosts to suppress noise."}, {"field": "DeveloperHosts", "description": "List of known developer/build systems where these tools are expected; raise severity off-host."}, {"field": "SuspiciousChildList", "description": "Child processes considered high-risk when spawned by dev utilities (powershell.exe, rundll32.exe, regsvr32.exe, cmd.exe, wscript.exe, mshta.exe)."}, {"field": "RarePathRegex", "description": "Regex of user-writable or atypical paths (e.g., %TEMP%, %APPDATA%, recycle bin, public profile) for payload drops."}, {"field": "UnsignedOrInvalidSignatureOnly", "description": "Toggle to alert only when child/payload is unsigned or signature invalid to reduce noise."}, {"field": "ParentProcessAllowList", "description": "Known orchestrators (e.g., CI/CD agents) that often run these utilities legitimately."}, {"field": "NetworkReputationThreshold", "description": "Heuristic for rare/unknown destination (no DNS reputation, new domain, geo outside region)."}]', '2026-05-01 15:26:36.540024');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1465, 'AN1608', 'Analytic 1608', 'Account creation via cloud service APIs or CLI, often associated with key generation. Monitored via CloudTrail or equivalent audit logs.', '{IaaS}', 'x-mitre-analytic--d715d148-4d2d-407c-bd83-c471a4163d4e', 'DET0583', '[{"name": "AWS:CloudTrail", "channel": "CreateUser", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "AWS:CloudTrail", "channel": "AttachUserPolicy", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "Region", "description": "Alert on account creation outside expected geographies"}, {"field": "ServiceScope", "description": "Filter on creation of users scoped to sensitive services"}]', '2026-05-01 15:26:36.541779');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1466, 'AN0460', 'Analytic 0460', 'Chain: (1) SaaS admin API or PowerShell remote session reads tenant password/authentication settings (e.g., M365 Unified Audit Log ‘Cmdlet’ with `Get-MsolPasswordPolicy`/`Get-OrganizationConfig` parameters that expose password settings); (2) same session proceeds to mailbox or tenant changes.', '{SaaS}', 'x-mitre-analytic--d71a1e3e-6507-438b-9ee2-f80dc1f938d2', 'DET0161', '[{"name": "m365:unified", "channel": "Workload=AzureActiveDirectory OR Exchange AND (Operation=Cmdlet AND Parameters contains ''Password'' AND (CmdletName=''Get-*'' OR CmdletName=''Get-OrganizationConfig''))", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "SaaSAdminGroup", "description": "Known admin groups or break-glass accounts."}, {"field": "SessionAnomalyThreshold", "description": "Rate/volume of read operations per session considered anomalous."}]', '2026-05-01 15:26:36.543507');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1467, 'AN0133', 'Analytic 0133', 'Detects attempts to clear RDP/network history and modify network configuration artifacts through command execution, registry key deletion, firewall rule changes, and suspicious file deletions (e.g., Default.rdp, registry edits to Terminal Server Client keys).', '{Windows}', 'x-mitre-analytic--d71c4839-8d23-41f4-b59a-8bd2c3517d1e', 'DET0049', '[{"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "EDR:cli", "channel": "Command Line Telemetry", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Security", "channel": "Firewall Rule Modification", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}]', '[{"field": "TargetPathRegex", "description": "Filter file/registry paths like *\\Terminal Server Client\\* or *Default.rdp*"}, {"field": "TimeWindow", "description": "Correlate command/registry edits within close proximity to suspicious connection activity"}, {"field": "UserContext", "description": "Detect cleanup behavior from non-interactive or SYSTEM accounts"}]', '2026-05-01 15:26:36.544808');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1468, 'AN1392', 'Analytic 1392', 'Detects unexpected encrypted egress traffic from management services (e.g., hostd) or guest VMs utilizing symmetric encryption without traditional protocols (e.g., FTP with embedded AES ciphertext).', '{ESXi}', 'x-mitre-analytic--d73a1356-7f4f-4f54-afca-437736e5f53c', 'DET0503', '[{"name": "esxi:vmkernel", "channel": "egress log analysis", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "esxi:hostd", "channel": "execution + payload hints", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "host switch egress data", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "GuestVMExfilWatchlist", "description": "VMs with data sensitivity labels or outside normal behavior."}, {"field": "ServiceEgressProfile", "description": "Expected egress destinations and volume for core services."}]', '2026-05-01 15:26:36.54764');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1469, 'AN1153', 'Analytic 1153', 'Unusual access to bash history, registry credentials paths, or private key files by unauthorized or scripting tools, with correlated file and process activity.', '{Windows}', 'x-mitre-analytic--d76081f4-26cd-4e62-91e8-4e4a3992dd90', 'DET0412', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TimeWindow", "description": "Defines the threshold time for accessing multiple sensitive files indicating automation."}, {"field": "SuspiciousProcessList", "description": "Process names to monitor (e.g., reg.exe, cmd.exe, powershell.exe, etc.)"}]', '2026-05-01 15:26:36.549117');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1470, 'AN0903', 'Analytic 0903', 'Detects usage of commands or binaries (e.g., netstat, PowerShell Get-NetTCPConnection) and WMI or API calls to enumerate local or remote network connections.', '{Windows}', 'x-mitre-analytic--d78b4bb3-bd0a-4e43-bc19-0a7b72f6a9d3', 'DET0320', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SuspiciousParentProcesses", "description": "Non-standard binaries launching PowerShell or netstat (e.g., winword.exe spawning powershell.exe)."}, {"field": "TimeWindow", "description": "Correlates discovery behavior before lateral movement or credential access."}, {"field": "CommandPatternList", "description": "Regex or keyword patterns to match discovery utilities (e.g., `netstat`, `Get-NetTCPConnection`)."}]', '2026-05-01 15:26:36.550402');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1471, 'AN0323', 'Analytic 0323', 'Abuse of safe mode via BCD modification, boot configuration utilities (bcdedit.exe, bootcfg.exe), and registry persistence under SafeBoot keys. Defender view: suspicious boot configuration changes correlated with registry edits that enable adversary persistence or disable defenses.', '{Windows}', 'x-mitre-analytic--d7a82fc6-047b-47a8-8b3c-d6dcab00d56b', 'DET0116', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}]', '[{"field": "SafeBootRegistryPaths", "description": "Customize monitored registry paths for safe mode service additions."}, {"field": "AllowedAdminTools", "description": "Whitelist legitimate administrative use of bcdedit/bootcfg for troubleshooting."}, {"field": "TimeWindow", "description": "Correlate registry modifications and boot configuration commands within a short timeframe."}]', '2026-05-01 15:26:36.55194');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1472, 'AN1518', 'Analytic 1518', 'Access to user private key directories (e.g., /Users/*/.ssh) via Terminal, scripting engines, or non-default processes.', '{macOS}', 'x-mitre-analytic--d7a9c7c8-81a0-4988-9617-51f191ab32c8', 'DET0549', '[{"name": "macos:unifiedlog", "channel": "open/read access to private key files (id_rsa, *.pem, *.p12)", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "launch of bash/zsh/python/osascript targeting key file locations", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ProcessName", "description": "Processes reading key files (osascript, python, bash, etc.)"}, {"field": "FileAccessPath", "description": "Private key and certificate paths like /Users/*/.ssh, /Library/Keychains/"}]', '2026-05-01 15:26:36.553227');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1473, 'AN0438', 'Analytic 0438', 'Unexpected apps or scripts (osascript, curl, Automator workflows) exfiltrating data via webhooks. Defender perspective: correlation of clipboard/file read operations followed by HTTPS POST traffic to webhook services.', '{macOS}', 'x-mitre-analytic--d7f9b07f-401c-4685-a014-6a824f95f866', 'DET0153', '[{"name": "macos:unifiedlog", "channel": "execution of osascript, curl, or unexpected automation", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "file read of sensitive directories", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "HTTPS POST to known webhook URLs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "WebhookEndpoints", "description": "Webhook URLs monitored for exfiltration."}, {"field": "EntropyThreshold", "description": "High entropy payloads may indicate encoded/encrypted exfiltration."}]', '2026-05-01 15:26:36.55465');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1474, 'AN0297', 'Analytic 0297', 'Detects PE injection through a behavioral sequence where one process opens (OpenProcess) a handle to another, allocates remote memory (VirtualAllocEx), writes a PE header (MZ) or shellcode (WriteProcessMemory), then initiates a new thread (CreateRemoteThread or NtCreateThreadEx) in that process—executing injected code in memory without touching disk. Optional: injects a trampoline or shellcode that unpacks/reflectively maps the payload.', '{Windows}', 'x-mitre-analytic--d845dc30-6950-4f0c-9342-29b7a7315bd2', 'DET0106', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "PayloadEntropyThreshold", "description": "Controls for detecting high-entropy memory writes indicating shellcode or encrypted PE"}, {"field": "TargetProcessList", "description": "High-value or sensitive processes that should never have remote threads injected"}, {"field": "TimeWindow", "description": "Max allowed delay between memory write and thread execution"}, {"field": "ParentProcessAnomalyThreshold", "description": "Used to filter legitimate process hierarchies vs anomalous injection sources"}]', '2026-05-01 15:26:36.556159');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1476, 'AN0677', 'Analytic 0677', 'Database client execution (e.g., sqlcmd.exe, isql.exe) by users or from locations not tied to enterprise automation or backups. Often followed by creation of .sql/.bak/.csv files, registry artifacts for ODBC/JDBC drivers, or encrypted ZIPs. Defender sees SQL tools launched by explorer.exe, Powershell, or odd parent processes, plus file writes in user temp locations.', '{Windows}', 'x-mitre-analytic--d869b672-c3e9-446c-9e7a-c9ce5888794c', 'DET0242', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "KnownDBToolPaths", "description": "Directories where legitimate database tools are installed"}, {"field": "ExportExtensionPatterns", "description": "List of file extensions commonly used for DB exports"}, {"field": "MaxTransferVolume", "description": "Threshold for outbound data volume that may suggest large DB dumps"}]', '2026-05-01 15:26:36.559242');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1477, 'AN1390', 'Analytic 1390', 'Detects command-line utilities or scripts using encryption libraries or symmetric algorithms (e.g., OpenSSL AES, GPG, Python + PyCrypto) in conjunction with outbound file transfers or traffic to external destinations.', '{Linux}', 'x-mitre-analytic--d8978977-d2c8-4c1c-a6c1-0176330e3446', 'DET0503', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "conn.log or flow data", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "ssl.log (for TLS handshake analysis), dns.log (tunneling indicators)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "FileTransferIndicator", "description": "Threshold for transferred data size or extension type."}, {"field": "LibraryCallTracking", "description": "Hooks into use of encryption libraries like `libcrypto.so`, `pycrypto`, `gpg`."}]', '2026-05-01 15:26:36.560696');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1478, 'AN0977', 'Analytic 0977', 'Detect execution of `/usr/libexec/security_authtrampoline` or use of AuthorizationExecuteWithPrivileges API, and monitor process lineage for unusual launches of GUI apps with escalated privileges.', '{macOS}', 'x-mitre-analytic--d8b422b3-50e7-48cc-bfa1-a6e0cecf5761', 'DET0345', '[{"name": "macos:unifiedlog", "channel": "authorization execute privilege requests", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "auditd:SYSCALL", "channel": "execve with escalated privileges", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "fs:fsusage", "channel": "binary execution of security_authtrampoline", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WatchedBinaries", "description": "Specify binaries frequently targeted for privilege escalation"}, {"field": "ExecutionParent", "description": "Which applications should never be allowed to spawn elevated processes"}]', '2026-05-01 15:26:36.56197');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1479, 'AN1232', 'Analytic 1232', 'Direct use of `nc`, `socat`, or reverse tunnel scripts initiated by abnormal user contexts or unauthorized VIBs initiating connections from hypervisor to external systems.', '{ESXi}', 'x-mitre-analytic--d8cc8663-020b-4fde-a8de-a92ecf97aea4', 'DET0445', '[{"name": "esxi:shell", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:vmkernel", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "conn.log", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "CLICommand", "description": "Custom proxy or port forwarding scripts executed from ESXi shell."}, {"field": "DestinationIP", "description": "Unusual outbound connections from ESXi host, particularly to internet."}, {"field": "UserContext", "description": "Root or elevated users initiating unexpected tunnels."}]', '2026-05-01 15:26:36.563163');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1480, 'AN1502', 'Analytic 1502', 'Monitor for suspicious use of cloud-native administrative command services (e.g., AWS Systems Manager Run Command, Azure RunCommand, GCP OS Config) to execute code inside VMs. Detect anomalies such as commands/scripts executed by unexpected users, execution outside of maintenance windows, or commands initiated by service accounts not normally tied to administration. Correlate cloud control-plane activity logs with host-level execution (process creation, script execution) to validate if commands materialized inside the guest OS.', '{IaaS}', 'x-mitre-analytic--d8d5a1c0-9ba1-4735-af42-3d5b9d7a6603', 'DET0545', '[{"name": "AWS:CloudTrail", "channel": "SendCommand, StartSession, ExecuteCommand: Unexpected AWS Systems Manager command execution targeting EC2 instances", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "azure:activity", "channel": "Microsoft.Compute/virtualMachines/runCommand/action: Abnormal initiation of Azure RunCommand jobs or PowerShell/Bash payloads", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "azure:vmguest", "channel": "Unexpected execution of cloud agent processes (e.g., WindowsAzureGuestAgent.exe, ssm-agent) followed by arbitrary script or binary execution", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "UserContext", "description": "Differentiate between known admin/service accounts and non-administrative users triggering RunCommand or SSM."}, {"field": "TimeWindow", "description": "Correlate cloud control-plane API calls with host-side execution events within a bounded timeframe (e.g., 5 minutes)."}, {"field": "AllowedScripts", "description": "Whitelist approved scripts or automation invoked via RunCommand to reduce false positives."}]', '2026-05-01 15:26:36.564473');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1481, 'AN0029', 'Analytic 0029', 'Detects macros or VBA triggers set to execute on document open or close events, often correlating with embedded payloads or C2 traffic shortly after execution.', '{"Office Suite"}', 'x-mitre-analytic--d8e18081-2670-4a88-9246-59a1dc52c51c', 'DET0010', '[{"name": "m365:office", "channel": "VBA auto_open, auto_close, or document_open events", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "m365:office", "channel": "External HTTP/DNS connection from Office binary shortly after macro trigger", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MacroFunctionNames", "description": "Names of event-bound functions like Auto_Open that initiate execution"}, {"field": "TimeDeltaMacroToC2", "description": "Time threshold to correlate macro execution with outbound connections"}]', '2026-05-01 15:26:36.565733');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1482, 'AN0252', 'Analytic 0252', 'Installation of configuration profiles or plist entries associated with malicious or unauthorized browser extensions', '{macOS}', 'x-mitre-analytic--d8f9ab20-4c82-42fc-9316-91781fa9e5e1', 'DET0092', '[{"name": "macos:unifiedlog", "channel": "Execution of ''profiles install -type=configuration''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "Creation of .plist under /Library/Managed Preferences/", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:unifiedlog", "channel": "Suspicious outbound traffic from browser binary to non-standard domains", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "PlistPath", "description": "Directory path for user-specific extension configuration files"}, {"field": "CommandLine", "description": "Usage of profiles CLI tool—can be modified by legitimate tools or MDMs"}, {"field": "TimeWindow", "description": "Correlation window between configuration install and observable extension behavior"}]', '2026-05-01 15:26:36.566944');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1483, 'AN1367', 'Analytic 1367', 'Sequence of RAT agent execution, systemd persistence, and long-lived external egress; optional interactive shells spawned from the agent.', '{Linux}', 'x-mitre-analytic--d90a4f16-b5e1-4daa-bf65-91112fe02761', 'DET0496', '[{"name": "auditd:SYSCALL", "channel": "execve: Agent/headless flags (listen/connect/reverse/tunnel) or remote-control binaries spawning shells", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PATH", "channel": "WRITE: Drop of binaries/scripts in ~/.local, /tmp, or /opt tool dirs", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Bind exec→service→egress events; extend for staged deployments."}, {"field": "DaemonAllowlist", "description": "Approved .service names/paths to avoid flagging corporate agents."}, {"field": "SuspiciousChildProcesses", "description": "Define shells/interpreters considered anomalous when spawned by GUI/agent parents."}, {"field": "EgressHeuristics", "description": "Flow heuristics for long-lived, client-heavy connections post-install."}]', '2026-05-01 15:26:36.568188');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1484, 'AN0461', 'Analytic 0461', 'Chain: (1) privileged CLI sessions run read-only commands that dump AAA/password policies (e.g., `show aaa`, `show password-policy`); (2) same account changes AAA or user DB shortly after. Use network device AAA/command accounting or syslog.', '{"Network Devices"}', 'x-mitre-analytic--d93312e3-210a-4757-b638-4ed19fca8621', 'DET0161', '[{"name": "networkdevice:syslog", "channel": "cmd=''show aaa*'' OR ''show running-config | include password|aaa'' OR ''show aaa common-criteria policy all''", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ApprovedNOCSources", "description": "Jump hosts permitted to run show commands."}, {"field": "DeviceTier", "description": "Higher risk weight on edge/critical devices."}]', '2026-05-01 15:26:36.569388');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1485, 'AN1393', 'Analytic 1393', 'Detects anomalous use of Dynamic Data Exchange (DDE) for code execution, such as Office applications (WINWORD.EXE, EXCEL.EXE) spawning command interpreters, or loading unusual modules through DDEAUTO/DDE formulas. Correlates suspicious parent-child process relationships, registry keys enabling DDE, and module loads inconsistent with normal Office usage.', '{Windows}', 'x-mitre-analytic--d9383849-c91c-4eef-88a0-97c2454ca1af', 'DET0504', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}]', '[{"field": "AllowedParentChildPairs", "description": "Define legitimate parent-child relationships for Office processes to reduce false positives."}, {"field": "TimeWindow", "description": "Threshold for correlating Office process creation with subsequent command execution via DDE."}, {"field": "SuspiciousDLLList", "description": "Maintain allow/block list of DLLs that Office is expected to load."}]', '2026-05-01 15:26:36.57062');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1486, 'AN0830', 'Analytic 0830', 'Execution of destructive CLI commands such as format flash:, format disk, or equivalent vendor-specific commands that erase filesystem structures. Detection correlates AAA logs showing privileged access with immediate format/erase commands.', '{"Network Devices"}', 'x-mitre-analytic--d970c6c7-82d0-4977-9e2e-4b27af383ca5', 'DET0297', '[{"name": "networkdevice:cli", "channel": "format flash:, format disk, reformat commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "Privileged login followed by destructive format command", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "CommandPatterns", "description": "Expand detection to cover vendor-specific destructive commands."}, {"field": "PrivilegedUsers", "description": "Whitelist authorized maintenance sessions to reduce false positives."}]', '2026-05-01 15:26:36.572952');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1487, 'AN1328', 'Analytic 1328', 'Spike in object access from new IAM user or role followed by data exfiltration to external IPs', '{IaaS}', 'x-mitre-analytic--d9a1ace1-6307-4db7-925f-67057361e66a', 'DET0484', '[{"name": "AWS:CloudTrail", "channel": "GetObject, CopyObject", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"name": "AWS:CloudTrail", "channel": "AssumeRole", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "AWS:VPCFlowLogs", "channel": "Unusual volume of data transferred from S3 storage endpoints to non-corporate IPs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Timeframe for data transfer correlation (e.g., 10 minutes)"}, {"field": "ExternalIPAllowList", "description": "Known list of corporate and expected outbound IP addresses"}]', '2026-05-01 15:26:36.574656');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1501, 'AN1275', 'Analytic 1275', 'High volume of failed logon attempts followed by a successful one from a suspicious user, host, or timeframe', '{Windows}', 'x-mitre-analytic--db50537c-9234-4350-9bf0-838d4cffbd34', 'DET0463', '[{"name": "WinEventLog:Security", "channel": "EventCode=4776, 4625", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Adjustable window to correlate failed logons, e.g., 5-10 minutes"}, {"field": "UserContext", "description": "Define scope of monitored users (e.g., service accounts, admins)"}, {"field": "FailureThreshold", "description": "Count of failed logons before raising an alert (e.g., 10-15)"}]', '2026-05-01 15:26:36.59493');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1488, 'AN0579', 'Analytic 0579', 'Detects ptrace-based process injection by correlating audit logs of ptrace syscalls, memory modifications (e.g., poketext, pokedata), and suspicious register manipulation on a target process not normally debugged by the originator. Alerts on processes attempting to ptrace non-child or privileged processes, especially those followed by abnormal memory or execution behavior.', '{Linux}', 'x-mitre-analytic--d9bcfaee-d2d1-4673-b834-5c219f8dba9b', 'DET0203', '[{"name": "auditd:SYSCALL", "channel": "mmap, ptrace, process_vm_writev or direct memory ops", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "state=attached/debugged", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "TargetProcessNameFilter", "description": "List of sensitive or rarely-debugged processes (e.g., sshd, systemd, container daemons) to alert on if ptraced"}, {"field": "TimeWindowBetweenPtraceAndMemoryWrite", "description": "Threshold time (e.g., <10 seconds) between ptrace attach and pokedata syscall"}, {"field": "UserContextMismatch", "description": "Flag when UID of tracer differs from UID of target process (e.g., privilege escalation or container breakout)"}, {"field": "ProcessRelationshipConstraint", "description": "Allowlist relationships (e.g., parent-child) under which ptrace is considered benign"}]', '2026-05-01 15:26:36.576029');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1489, 'AN1250', 'Analytic 1250', 'Detects unauthorized modifications to PAM configuration files or shared object modules. Correlates file modification events under /etc/pam.d/ or /lib/security/ with unusual authentication activity such as multiple simultaneous logins, off-hours logins, or logons without corresponding physical/VPN access.', '{Linux}', 'x-mitre-analytic--d9c7e50d-4b13-4634-80f9-e8032a043414', 'DET0454', '[{"name": "auditd:SYSCALL", "channel": "open, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Connections", "channel": "simultaneous or anomalous logon sessions across multiple systems", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "MonitoredPaths", "description": "List of PAM configuration and module directories monitored (e.g., /etc/pam.d/, /lib/security/)."}, {"field": "TimeWindow", "description": "Timeframe for correlating suspicious file modifications with anomalous login events."}, {"field": "BaselineAccounts", "description": "Expected login frequency and systems per user account; deviations may indicate compromise."}]', '2026-05-01 15:26:36.577353');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1490, 'AN0870', 'Analytic 0870', 'Detection of fake or spoofed macOS Security & Privacy GUIs showing healthy status after XProtect, Gatekeeper, or AV processes are disabled. Correlates user-space UI process creation with terminated or missing security daemons.', '{macOS}', 'x-mitre-analytic--d9eb3056-115b-496a-89f7-be38470ff022', 'DET0311', '[{"name": "macos:unifiedlog", "channel": "Execution of processes mimicking Apple Security & Privacy GUIs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Termination or disabling of XProtect, Gatekeeper, or third-party AV daemons", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "TrustedDaemonList", "description": "Monitored list of macOS security daemons such as XProtect, Gatekeeper, or third-party AV."}]', '2026-05-01 15:26:36.578617');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1491, 'AN1597', 'Analytic 1597', 'Detect loading or inspection of kernel extensions (kextstat, kextfind) and file access to /System/Library/Extensions/. Monitor unexpected usage of these utilities by non-administrative users or scripts.', '{macOS}', 'x-mitre-analytic--d9ee822c-6a91-4c83-9698-779ca0bf8663', 'DET0579', '[{"name": "macos:unifiedlog", "channel": "exec: Execution of kextstat, kextfind, or ioreg targeting driver information", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "read: File access to /System/Library/Extensions/ or related kernel extension paths", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "AllowedMaintenanceTasks", "description": "Tune detection by excluding expected system diagnostic or patch-related invocations of kext utilities."}]', '2026-05-01 15:26:36.580363');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1492, 'AN2014', 'Analytic 2014', 'Once adversaries leverage the abused web service as infrastructure (ex: for command and control), it may be possible to look for unique characteristics associated with adversary software, if known.(Citation: ThreatConnect Infrastructure Dec 2020)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1493, 'AN0245', 'Analytic 0245', 'Detects unauthorized TCC access or use of Quartz Event Services (CGEventTapCreate) or IOHID for event tap installation within unexpected processes.', '{macOS}', 'x-mitre-analytic--da140e65-e30c-4cf2-8961-82fb200a7f0b', 'DET0089', '[{"name": "macos:unifiedlog", "channel": "subsystem=com.apple.TCC", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "macos:osquery", "channel": "process_events OR launchd", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "Service", "description": "com.apple.inputmonitoring, com.apple.accessibility, etc."}, {"field": "ExecutablePath", "description": "Tunable to exclude trusted endpoint monitoring tools"}]', '2026-05-01 15:26:36.583185');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1494, 'AN1426', 'Analytic 1426', 'Use of OAuth tokens by third-party apps to access user mail, calendar, or SharePoint resources where the token was granted recently or via spearphishing.', '{"Office Suite"}', 'x-mitre-analytic--da365d5b-c955-46f6-99c2-cd57a3560a57', 'DET0515', '[{"name": "m365:unified", "channel": "App-only or delegated access patterns where client_id != known enterprise apps", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}]', '[{"field": "ClientAppIDAllowList", "description": "Defenders may allow known app IDs, flag unknowns"}, {"field": "AccessVolumeThreshold", "description": "Rate of resource access by a newly consented app"}]', '2026-05-01 15:26:36.584539');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1495, 'AN0704', 'Analytic 0704', 'Monitor system APIs such as CFNetwork and SecureTransport for anomalies in transmitted data streams. Detect mismatches in file hashes or SSL/TLS downgrade attempts that enable manipulation of transmitted data.', '{macOS}', 'x-mitre-analytic--da6d7de2-a666-4fa3-aa53-54692a8167ae', 'DET0254', '[{"name": "macos:unifiedlog", "channel": "Suspicious anomalies in transmitted data integrity during application network operations", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:osquery", "channel": "CALCULATE: Integrity validation of transmitted data via hash checks", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "TLSValidationRules", "description": "Custom rules for enforcing HTTPS/TLS integrity checks to prevent downgrade manipulation."}, {"field": "AllowedApps", "description": "Whitelisted macOS apps permitted to transmit critical data."}]', '2026-05-01 15:26:36.58588');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1496, 'AN0840', 'Analytic 0840', 'Suspicious calls to dlopen(), dlsym(), or mmap with RWX flags in processes that do not typically perform dynamic module loading. Monitor anonymous memory regions executed by user processes.', '{macOS}', 'x-mitre-analytic--da7cf744-fc04-4b17-8a96-3140a4b349d6', 'DET0300', '[{"name": "macos:unifiedlog", "channel": "execve or dylib load from memory without backing file", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "suspicious dlopen/dlsym usage in non-development processes", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ApplicationScope", "description": "Developer tools may legitimately call dlopen/dlsym; narrow scope to production workloads."}, {"field": "ExecutionTimeWindow", "description": "Correlate suspicious loads with subsequent process activity in a defined window."}]', '2026-05-01 15:26:36.587305');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1497, 'AN1593', 'Analytic 1593', 'Unexpected modification of the KernelCallbackTable in a process’s PEB followed by invocation of modified callback functions (e.g., fnCOPYDATA) through Windows messages. Defender observes suspicious API call chains such as NtQueryInformationProcess → WriteProcessMemory → abnormal GUI callback execution, often correlating to anomalous process behavior such as network activity or code injection.', '{Windows}', 'x-mitre-analytic--da853af7-f2e4-45c2-b78f-3d960fff638e', 'DET0577', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "WriteProcessMemory: WriteProcessMemory targeting regions containing KernelCallbackTable addresses", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "MonitoredProcesses", "description": "GUI applications (e.g., explorer.exe, notepad.exe) where KernelCallbackTable abuse is more likely."}, {"field": "CallbackFunctions", "description": "Specific callback functions (e.g., fnCOPYDATA, fnDWORD) expected to remain stable."}, {"field": "TimeWindow", "description": "Correlation interval between WriteProcessMemory calls and execution of modified callback functions."}, {"field": "AccessMaskThresholds", "description": "Access rights values that should be flagged when targeting GUI processes."}]', '2026-05-01 15:26:36.588693');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1498, 'AN2020', 'Analytic 2020', 'Internet scanners may be used to look for patterns associated with malicious content designed to collect host software information from visitors.(Citation: ThreatConnect Infrastructure Dec 2020)(Citation: ATT ScanBox)
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1499, 'AN0570', 'Analytic 0570', 'A non-whitelisted process receives TCC camera entitlement (kTCCServiceCamera), opens AppleCamera/AVFoundation device handles, writes .mov/.mp4 artifacts to unusual locations, and/or beacons/exfiltrates soon after.', '{macOS}', 'x-mitre-analytic--db3263c7-0abc-47be-a9f3-434d255b1e0e', 'DET0197', '[{"name": "macos:unifiedlog", "channel": "Access decisions to kTCCServiceCamera for unexpected binaries", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "macos:endpointsecurity", "channel": "open: Process opens AppleCamera/IOUSB device nodes or AVFoundation frameworks", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:endpointsecurity", "channel": "exec: Exec of ffmpeg, avfoundation-based binaries, or custom signed apps accessing camera", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Process wrote large .mov/.mp4 in user temp/hidden dirs", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "TCCAllowList", "description": "Legitimate apps (Zoom, Teams, FaceTime) that are permitted to camera."}, {"field": "VideoExtensions", "description": "Mov/mp4/mkv/yuv etc., tuned to environment workloads."}, {"field": "TimeWindow", "description": "Correlation between TCC grant → file write → network egress."}, {"field": "MinFileSizeMB", "description": "Reduce FP from thumbnails/snapshots."}, {"field": "LaunchAgentPaths", "description": "Allowed persistence paths to reduce false positives when correlating with persistence."}]', '2026-05-01 15:26:36.592282');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1500, 'AN0123', 'Analytic 0123', 'Installation of a new browser extension followed by suspicious file writes or outbound network connections to untrusted domains by the browser process.', '{Windows}', 'x-mitre-analytic--db45c19b-d9d6-4794-8b49-ba232cca34b0', 'DET0044', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "UserContext", "description": "Extension installation by privileged or domain users may require higher scrutiny"}, {"field": "BrowserExecutablePath", "description": "Custom or portable browsers may not match default paths"}, {"field": "ExtensionInstallPath", "description": "Installation paths may vary by version or user profile"}]', '2026-05-01 15:26:36.593633');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1503, 'AN0655', 'Analytic 0655', 'Detection of spearphishing attachments by correlating suspicious email delivery with subsequent file creation and abnormal process execution (e.g., Office spawning PowerShell or CMD). Behavior chain includes inbound email metadata → attachment stored on disk → process execution → outbound network activity.', '{Windows}', 'x-mitre-analytic--db6995d9-68ab-4638-a430-c0a8d2daf306', 'DET0236', '[{"name": "m365:unified", "channel": "Send/Receive: Inbound emails with attachments from suspicious or spoofed senders", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AttachmentExtensions", "description": "List of high-risk extensions to monitor (e.g., .exe, .js, .vbs, .docm, .xlsm)."}, {"field": "SuspiciousParentChildPairs", "description": "Process lineage patterns considered malicious (e.g., winword.exe → powershell.exe)."}, {"field": "TimeWindow", "description": "Correlation window between email receipt, file creation, and process execution."}]', '2026-05-01 15:26:36.597563');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1504, 'AN0600', 'Analytic 0600', 'Detection of shell scripts, ELF binaries, or archives containing embedded secondary payloads, self-extracting components, or unusual compression behavior during runtime.', '{Linux}', 'x-mitre-analytic--db9b55b0-7e54-4625-92d5-fbe9ed8ac868', 'DET0214', '[{"name": "auditd:SYSCALL", "channel": "open, write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:osquery", "channel": "elf_info, hash, yara_matches", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "ebpf:syscalls", "channel": "container_file_activity", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "FileSectionCount", "description": "Tuning value for ELF binaries with appended sections or resources"}, {"field": "ScriptLength", "description": "Threshold for long shell scripts with base64-encoded binary content"}, {"field": "ExtractedFileCount", "description": "Number of files written from a single script execution"}]', '2026-05-01 15:26:36.598772');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1505, 'AN0634', 'Analytic 0634', 'Unusual daemons or user processes binding/listening on ports outside of standard ranges, or initiating client connections using mismatched protocol/port pairings.', '{Linux}', 'x-mitre-analytic--dba32c3a-1ae7-46a4-9b04-d011f37aa801', 'DET0227', '[{"name": "auditd:SYSCALL", "channel": "socket/connect syscalls", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "linux:syslog", "channel": "processes binding to non-standard ports or sshd configured on unexpected port", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "linux:osquery", "channel": "process listening or connecting on non-standard ports", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AllowedServices", "description": "Exclude ports intentionally configured for enterprise apps."}, {"field": "PayloadEntropyThreshold", "description": "Define thresholds for anomalous payload entropy to catch tunneled traffic."}]', '2026-05-01 15:26:36.600991');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1506, 'AN1206', 'Analytic 1206', 'Suspicious use of NTFS file attributes such as Alternate Data Streams (ADS) or Extended Attributes (EA) to hide data. Defender perspective: anomalous file creations or modifications containing colon syntax (file.ext:ads), API calls like ZwSetEaFile/ZwQueryEaFile, or PowerShell/Windows utilities interacting with -stream parameters. Correlation across file metadata anomalies, process lineage, and command execution provides context.', '{Windows}', 'x-mitre-analytic--dba3fe8d-6080-4efe-9b93-6eda138ac771', 'DET0432', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "etw:Microsoft-Windows-Kernel-File", "channel": "ZwSetEaFile or ZwQueryEaFile function calls", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "ADSPathWhitelist", "description": "Exclude legitimate ADS usage by system or AV tools."}, {"field": "ProcessScope", "description": "Restrict monitoring to suspicious parent processes (e.g., powershell.exe, cmd.exe, wscript.exe)."}, {"field": "TimeWindow", "description": "Correlate ADS creation with subsequent process execution to strengthen malicious context."}]', '2026-05-01 15:26:36.602198');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1507, 'AN0240', 'Analytic 0240', 'Defender observes execution of commands like `tasklist`, `sc query`, `reg query`, or PowerShell WMI/Registry queries targeting known backup products (e.g., Veeam, Acronis, CrashPlan). Behavior often includes parent-child lineage involving PowerShell or cmd.exe with discovery syntax, and enumeration of services, directories, or registry paths tied to backup software.', '{Windows}', 'x-mitre-analytic--dbc6d9ca-9502-46a0-a59b-15b050bb539c', 'DET0088', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "KnownBackupVendors", "description": "List of software vendors to match in command-line or registry queries"}, {"field": "UserContextScope", "description": "Focus on low-privilege or interactive user contexts rather than service accounts"}, {"field": "SuspiciousParentProcesses", "description": "Flag execution from scripting tools, interpreters, or LOLBins"}]', '2026-05-01 15:26:36.603639');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1508, 'AN1547', 'Analytic 1547', 'Detection of containerized service accounts or compromised kubeconfigs being used for cluster access from unexpected nodes or IPs.', '{Containers}', 'x-mitre-analytic--dc062a09-572e-41fc-bfff-f654751a6a0f', 'DET0560', '[{"name": "kubernetes:audit", "channel": "authentication.k8s.io", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "ServiceAccountScope", "description": "Validate access from expected namespaces only."}, {"field": "ClusterIPWhitelist", "description": "Permit kubeconfig usage from a limited set of IPs."}]', '2026-05-01 15:26:36.604944');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1509, 'AN0071', 'Analytic 0071', 'Abuse of trusted Electron apps (Teams, Slack, Chrome) to spawn child processes or execute payloads via malicious command-line arguments (e.g., --gpu-launcher) and modified app resources (.asar). Behavior chain: suspicious parent process (Electron app) → unusual command-line args → child process creation → optional DLL/network artifacts.', '{Windows}', 'x-mitre-analytic--dc0bf4ca-1d65-46ee-b4b1-d8f73a6e0cda', 'DET0025', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Correlation window tying app launch, file tampering, child process, and network events (5–10 minutes typical)."}, {"field": "UserContext", "description": "Flag admin/service accounts versus standard users executing Electron apps."}, {"field": "AllowedElectronApps", "description": "Baseline of Electron-based executables expected in the enterprise."}, {"field": "AllowedChildProcesses", "description": "Whitelist normal child processes (chrome.exe → crashpad_handler.exe) versus anomalies (powershell.exe)."}, {"field": "ElectronAppDomainAllowlist", "description": "Approved service domains for Teams, Slack, etc. to suppress benign traffic."}, {"field": "AsarIntegrityHash", "description": "Expected hash/signature of app.asar resources to detect tampering."}]', '2026-05-01 15:26:36.606734');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1510, 'AN0159', 'Analytic 0159', 'Detection of a process or script that accesses a common web service to retrieve content containing obfuscated indicators of a secondary C2 server (dead drop resolver behavior).', '{Linux}', 'x-mitre-analytic--dc4096a9-b89d-4bef-b20d-58cf5e87f6bf', 'DET0058', '[{"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "HTTP/TLS Logs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TargetDomain", "description": "Dead drop hosting domain (e.g., GitHub, Google Docs)"}, {"field": "PayloadEntropyThreshold", "description": "Detects high entropy in payloads signaling obfuscation"}, {"field": "TimeWindow", "description": "Causal proximity between access to resolver and follow-up connections"}]', '2026-05-01 15:26:36.608373');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1511, 'AN1091', 'Analytic 1091', 'Detects anomalous ARP traffic or cache modifications on Windows endpoints that indicate ARP poisoning. Behavioral focus is on multiple IP addresses resolving to a single MAC, or unsolicited ARP replies from unauthorized devices.', '{Windows}', 'x-mitre-analytic--dc4a80e3-7670-474f-aaf6-c051d5dda83c', 'DET0387', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "ARP cache modification attempts observed through event tracing or security baselines", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TrustedGatewayMAC", "description": "Expected MAC address for default gateways; deviations may indicate poisoning."}, {"field": "TimeWindow", "description": "Correlation interval for repeated unsolicited ARP replies."}]', '2026-05-01 15:26:36.60975');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1512, 'AN0550', 'Analytic 0550', 'Abuse of ClickOnce applications where rundll32.exe invokes dfshim.dll with ShOpenVerbApplication or dfsvc.exe spawns unexpected child processes or loads unsigned modules.', '{Windows}', 'x-mitre-analytic--dc4d944f-975a-4057-8edb-deb023db387c', 'DET0191', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Microsoft-Windows-Security-Mitigations/KernelMode", "channel": "ETW telemetry indicating ClickOnce deployment (dfsvc.exe) launching payloads", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "TimeWindow", "description": "The correlation window for dfsvc.exe/rundll32.exe execution and subsequent module loads or child processes (e.g., 0–10 minutes)."}, {"field": "KnownClickOnceApps", "description": "Whitelist of legitimate ClickOnce applications and paths."}, {"field": "SuspiciousChildList", "description": "Child processes considered abnormal when launched by dfsvc.exe or rundll32.exe."}]', '2026-05-01 15:26:36.61123');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1513, 'AN1973', 'Analytic 1973', 'Monitor for suspicious network traffic that could be indicative of probing for user information, such as large/iterative quantities of authentication requests originating from a single source (especially if the source is known to be associated with an adversary/botnet). Analyzing web metadata may also reveal artifacts that can be attributed to potentially malicious activity, such as referer or user-agent string HTTP/S fields.', '{PRE}', 'x-mitre-analytic--dc58724a-18a9-4bb9-a901-f5630963095b', 'DET0841', '[{"name": "Network Traffic", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', NULL, '2026-05-01 15:26:36.612436');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1514, 'AN0893', 'Analytic 0893', 'Execution of commands disabling AAA, logging, or security features on routers/switches. Detect privilege escalation followed by config changes that disable defense mechanisms.', '{"Network Devices"}', 'x-mitre-analytic--dc5bfda5-057d-4bec-b3e6-a6b2117a4134', 'DET0317', '[{"name": "networkdevice:syslog", "channel": "no logging buffered, no aaa new-model, disable firewall", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandPatterns", "description": "Customize destructive command list per vendor platform."}]', '2026-05-01 15:26:36.614175');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1515, 'AN0146', 'Analytic 0146', 'Flags unexpected user applications initiating long-lived HTTP(S) sessions with irregular traffic patterns.', '{macOS}', 'x-mitre-analytic--dc87f086-1764-43c2-a7bf-1a5ba2ea8191', 'DET0053', '[{"name": "macos:unifiedlog", "channel": "network flow", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:unifiedlog", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SessionDuration", "description": "Session length that exceeds average per-user expectations"}]', '2026-05-01 15:26:36.61542');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1516, 'AN1049', 'Analytic 1049', 'Shell scripts or binaries invoking repeated ''sleep'', ''ping'', or low-level syscalls (e.g., nanosleep) in short-lived execution chains with no user or system interaction. Frequently seen in malicious cron jobs or payload stagers.', '{Linux}', 'x-mitre-analytic--dcc422d4-90fc-4e2a-afd5-b4fbc3d6c4a1', 'DET0372', '[{"name": "auditd:SYSCALL", "channel": "execve or nanosleep with no stdout/stderr I/O", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PROCTITLE", "channel": "scripting loop invoking sleep/ping", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "CommandLineRegex", "description": "Environment-specific delay scripts may vary (sleep 300, ping -n 60, etc.)."}, {"field": "TimeBetweenSyscalls", "description": "Threshold for determining if delay is artificially extended."}, {"field": "UserContext", "description": "Root vs. service user context alters risk profile."}]', '2026-05-01 15:26:36.616897');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1517, 'AN1314', 'Analytic 1314', 'Cause→effect chain: (1) User-facing app (Office/PDF/archiver/browser) records an open/click or abnormal event, then (2) a downloaded file is created in a user-writable path and/or decompressed, (3) the parent user app spawns a living-off-the-land binary (e.g., powershell/cmd/mshta/rundll32/msiexec/wscript/expand/zip) or installer, and (4) immediate outbound HTTP(S)/DNS/SMB from the same lineage.', '{Windows}', 'x-mitre-analytic--dcd6253b-a986-4c8a-bd89-46389007ea83', 'DET0478', '[{"name": "WinEventLog:Application", "channel": "EventCode=1000", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Correlation window (e.g., 15 minutes) from document open to child/egress."}, {"field": "HighRiskParents", "description": "Apps that should rarely spawn OS utilities (winword.exe, excel.exe, powerpnt.exe, acrord32.exe, chrome/msedge/firefox, 7zFM.exe, winrar.exe, explorer.exe)."}, {"field": "HighRiskChildren", "description": "LOLBIN list: powershell.exe, cmd.exe, wscript.exe, cscript.exe, mshta.exe, rundll32.exe, regsvr32.exe, msiexec.exe, curl.exe, bitsadmin.exe, pcalua.exe, expand.exe, tar.exe."}, {"field": "UserPaths", "description": "Writable paths to watch: %USERPROFILE%\\Downloads, %TEMP%, %APPDATA%\\*, OneDrive/Teams cache, Office startup folders."}, {"field": "EgressAllowList", "description": "Corporate update/CDN domains and proxy egress CIDRs to suppress benign updater traffic."}]', '2026-05-01 15:26:36.619186');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1518, 'AN1402', 'Analytic 1402', 'Detects suspicious access to browser session cookie storage (e.g., Chrome’s `Cookies` SQLite DB) or memory reads of browser processes. Anomalous injection or memory dump utilities targeting browser processes such as `chrome.exe`, `firefox.exe`, or `msedge.exe`.', '{Windows}', 'x-mitre-analytic--dd105985-5d61-43f0-b69b-b4fd52632257', 'DET0509', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetProcessList", "description": "Monitored browsers (e.g., chrome.exe, firefox.exe)"}, {"field": "AccessToolList", "description": "Suspicious tools used for injection or memory access (e.g., mimikatz, procdump)"}, {"field": "TargetCookiePaths", "description": "Locations of cookie stores like `AppData\\Local\\Google\\Chrome\\User Data\\Default\\Cookies`"}]', '2026-05-01 15:26:36.620348');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1519, 'AN0788', 'Analytic 0788', 'Use of curl, wget, or custom scripts to POST data to pastebin-like services. Defender perspective: identify chained behavior where files are compressed/read followed by HTTPS POST requests to text-sharing endpoints.', '{Linux}', 'x-mitre-analytic--dd202a3f-c73b-47cf-9689-f14a8def816e', 'DET0284', '[{"name": "auditd:EXECVE", "channel": "curl -d, wget --post-data", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:SYSCALL", "channel": "read/open of sensitive file directories", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "NSM:Flow", "channel": "large HTTPS POST requests to text storage domains", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "AllowedTools", "description": "Whitelist of tools (e.g., curl for package repos) to reduce false positives."}, {"field": "WorkHours", "description": "Expected time ranges for developer interactions with external paste sites."}]', '2026-05-01 15:26:36.621767');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1520, 'AN0282', 'Analytic 0282', 'Monitors for abnormal process behavior and API calls like SetWindowsHookEx, GetAsyncKeyState, or device input polling commonly used for keystroke logging.', '{Windows}', 'x-mitre-analytic--dd283114-84d8-4b1a-a765-f3a7f378c2d1', 'DET0102', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "TargetImage", "description": "Can be scoped to sensitive GUI processes like explorer.exe or winlogon.exe"}, {"field": "TimeWindow", "description": "Time threshold for detecting multiple suspicious accesses"}]', '2026-05-01 15:26:36.623485');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1521, 'AN0221', 'Analytic 0221', 'Adversary targets macOS-hosted public services (e.g., nginx, node). Chain: suspicious inbound request → service crash/5xx → service spawns shell or writes file → new outbound connection.', '{macOS}', 'x-mitre-analytic--ddab6d30-7e37-462e-b183-39c7ceb2b986', 'DET0080', '[{"name": "macos:unifiedlog", "channel": "App/web server logs ingested via unified logging or filebeat (nginx/apache/node).", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "exec events where web process starts a shell/tooling", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "outbound egress from web host after suspicious request", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ServiceList", "description": "Names/paths of public daemons on macOS (httpd, nginx, node, java)."}, {"field": "TimeWindow", "description": "Correlation window for request → exec → egress."}]', '2026-05-01 15:26:36.625135');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1522, 'AN1606', 'Analytic 1606', 'Adversary creates new users using ''dscl'' commands, GUI tools, or by modifying user plist files. Detection includes monitoring dscl invocation and user-related plist changes.', '{macOS}', 'x-mitre-analytic--ddaf8ed8-f6bd-4eac-911c-d9fd243e87e9', 'DET0583', '[{"name": "macos:unifiedlog", "channel": "dscl . -create", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "modification to /var/db/dslocal/nodes/Default/users/", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "UsernamePattern", "description": "Attackers may use service-like names to hide malicious accounts"}, {"field": "ExecutionSource", "description": "Accounts created via Terminal vs GUI vs remote session can affect confidence"}]', '2026-05-01 15:26:36.626669');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1523, 'AN0737', 'Analytic 0737', 'Detects mailbox manipulation or deletion via PowerShell (e.g., Remove-MailboxExportRequest), file deletion from Outlook data stores (Unistore.db), or tampering with quarantined mail logs.', '{Windows}', 'x-mitre-analytic--ddbf61e2-7dad-40ef-90ef-7bec707b50fd', 'DET0266', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=23", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "m365:exchange", "channel": "Transport Rule Modification", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MailstorePath", "description": "Outlook files in AppData\\Local\\Comms\\Unistore\\data"}, {"field": "TransportRuleNames", "description": "Target suspicious rule changes (e.g., header removal)"}, {"field": "PowerShellCommandMatch", "description": "Regex match on `Remove-MailboxExportRequest` and similar Exchange cmdlets"}]', '2026-05-01 15:26:36.627992');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1524, 'AN0946', 'Analytic 0946', 'Implantation of malicious code into container images followed by registry push and use in new deployments.', '{Containers}', 'x-mitre-analytic--de0a1136-1476-4c28-bf49-004ac3ef97f7', 'DET0334', '[{"name": "docker:daemon", "channel": "docker build or docker commit commands followed by docker push to internal registry", "x_mitre_data_component_ref": "x-mitre-data-component--b008766d-f34f-4ded-b712-659f59aaed6e"}, {"name": "docker:registry", "channel": "push event of new image version from unrecognized user or context", "x_mitre_data_component_ref": "x-mitre-data-component--071a09b1-8945-46fd-8bb7-6bcc89400963"}]', '[{"field": "TimeWindow", "description": "Time threshold between image creation and use in deployment – typically rapid in adversarial activity."}, {"field": "UserContext", "description": "The expected users or service accounts performing image pushes."}, {"field": "RegistryNameRegex", "description": "Expected naming patterns for trusted registries."}]', '2026-05-01 15:26:36.6295');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1525, 'AN1643', 'Analytic 1643', 'Detection of password manager database access (1Password .opvault, LastPass caches, KeePass .kdbx) outside expected parent processes. Identifies memory scraping attempts via suspicious API calls or tools attaching to password manager processes.', '{macOS}', 'x-mitre-analytic--de1d4807-fcb5-4112-b310-ea0c4df45af2', 'DET0597', '[{"name": "macos:unifiedlog", "channel": "security OR injection attempts into 1Password OR LastPass", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "*.opvault OR *.ldb OR *.kdbx", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "unexpected memory inspection", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "VaultFileExtensions", "description": "Password manager file extensions (.opvault, .kdbx, .ldb) to monitor for anomalous access."}, {"field": "ParentProcessWhitelist", "description": "Expected parent processes that normally access password manager files, for filtering false positives."}]', '2026-05-01 15:26:36.630724');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1526, 'AN1270', 'Analytic 1270', 'Burst of failed login attempts across VM instances using leaked credential pairs from single IP in public cloud environments', '{IaaS}', 'x-mitre-analytic--de41a23b-b07d-411b-80f7-d1a8f55ba459', 'DET0460', '[{"name": "AWS:CloudTrail", "channel": "eventName=ConsoleLogin | eventType=AwsConsoleSignIn", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "InstanceIDScope", "description": "Define if detection should group logins per host or across cluster"}, {"field": "IPBehaviorHistory", "description": "Correlate against past IP reputation or behavioral profiles"}]', '2026-05-01 15:26:36.631945');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1527, 'AN1198', 'Analytic 1198', 'Monitors suspicious access to password stores such as LSASS, DPAPI, Windows Credential Manager, or browser credential databases. Detects anomalous process-to-process access (e.g., Mimikatz accessing LSASS) and correlation of credential store file reads with execution of non-standard processes.', '{Windows}', 'x-mitre-analytic--de4fe01d-96d7-4258-a1d6-6958fe50a4ed', 'DET0430', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TargetProcesses", "description": "List of sensitive processes to monitor (e.g., lsass.exe, svchost.exe)"}, {"field": "KeywordPatterns", "description": "Regex for suspicious command-line arguments such as ''dpapi'', ''credman'', ''mimikatz''"}]', '2026-05-01 15:26:36.633204');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1533, 'AN0990', 'Analytic 0990', 'Detects unauthorized applications or scripts accessing sensitive data followed by establishing encrypted outbound communication to rare external destinations or with abnormal byte ratios.', '{macOS}', 'x-mitre-analytic--deb57305-6324-404d-a9d0-00aa0c285920', 'DET0348', '[{"name": "macos:unifiedlog", "channel": "eventMessage = ''open'', ''sendto'', ''connect''", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:osquery", "channel": "socket_events", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ParentProcessAncestry", "description": "Enables defenders to tune legitimate vs. suspicious lineage (e.g., launchd → curl is uncommon)."}, {"field": "ProtocolList", "description": "Focus detection on unusual protocols (e.g., IRC, FTP, DNS over HTTPS)."}]', '2026-05-01 15:26:36.641837');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1528, 'AN1304', 'Analytic 1304', 'Correlate the creation or modification of containers using restart policies (e.g., ''always'') or DaemonSets with elevated host access, service account misuse, or privileged container contexts. Watch for manipulation of systemd units involving containers or pod scheduling targeting specific nodes or namespaces.', '{Containers}', 'x-mitre-analytic--de64bfbd-a6ed-4674-b0c5-dd485cba943b', 'DET0473', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "systemd:unit", "channel": "container run with restart policy set to ''always'' or ''unless-stopped''", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"name": "kubernetes:audit", "channel": "create", "x_mitre_data_component_ref": "x-mitre-data-component--5263cb33-08cc-4a68-820f-004e1e400d76"}, {"name": "kubernetes:audit", "channel": "create", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "restartPolicy", "description": "Tune for environments that legitimately use ''always'' or ''unless-stopped'' in trusted containers"}, {"field": "targetNamespace", "description": "Scope detection to high-risk namespaces (e.g., kube-system)"}, {"field": "nodeSelector|nodeName", "description": "Adjust if targeting known cluster configurations or test environments"}, {"field": "unitFilePath", "description": "Adapt to your OS/systemd hierarchy and container binary references"}, {"field": "TimeWindow", "description": "Adjust temporal correlation (e.g., container launch → privilege escalation)"}]', '2026-05-01 15:26:36.634466');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1529, 'AN0711', 'Analytic 0711', 'Unusual access to SSH agent sockets in /tmp/ or /private/tmp, process access to another user’s $SSH_AUTH_SOCK, and lateral SSH activity without corresponding login events. Defender view: correlation of socket access with anomalous network flows to internal systems.', '{macOS}', 'x-mitre-analytic--de71bbc0-66b2-41ae-a3f3-4911ac31b391', 'DET0256', '[{"name": "macos:unifiedlog", "channel": "Process opening SSH_AUTH_SOCK or /tmp/ssh-* socket not owned by same UID", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "macos:unifiedlog", "channel": "Execution of ssh or sftp without corresponding login event", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Session reuse without new auth event", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "SocketPathScope", "description": "Limit detection to monitored SSH agent socket directories."}, {"field": "BaselineUsers", "description": "Establish normal SSH agent ownership and expected usage for tuning."}]', '2026-05-01 15:26:36.635791');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1530, 'AN0781', 'Analytic 0781', 'Behavior chain involving abnormal registry modifications via CLI, PowerShell, WMI, or direct API calls, especially targeting persistence, privilege escalation, or defense evasion keys, potentially followed by service restart or process execution. Such as editing Notify/Userinit/Startup keys, or disabling SafeDllSearchMode.', '{Windows}', 'x-mitre-analytic--de8d67d4-9d2a-4379-be8b-3ae3f3b3ac75', 'DET0280', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "RegistryKeyPathPatterns", "description": "Environment-specific list of monitored or critical registry keys, e.g., Run, Services, Security Settings, LSASS"}, {"field": "ParentProcessAllowList", "description": "Allowlist of legitimate registry tools (e.g., regedit.exe, msiexec.exe); used to filter known safe writes"}, {"field": "TimeWindow", "description": "Correlate registry change with nearby process/service execution within a defined timeframe"}, {"field": "SignatureCheck", "description": "Flag unsigned executables or abnormal parent-child lineage performing registry modification"}]', '2026-05-01 15:26:36.637119');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1531, 'AN1977', 'Analytic 1977', 'Monitor for contextual data about a malicious payload, such as compilation times, file hashes, as well as watermarks or other identifiable configuration information. Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on post-compromise phases of the adversary lifecycle.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1532, 'AN1564', 'Analytic 1564', 'Detection of Office or document viewer processes (e.g., winword.exe) initiating network connections to remote templates or executing scripts due to manipulated template references (e.g., embedded in .docx, .rtf, or .dotm files), followed by suspicious child process creation (e.g., PowerShell).', '{Windows}', 'x-mitre-analytic--dea5f6cc-d3bb-404b-8aab-f7366988a96e', 'DET0566', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TemplateURLPatterns", "description": "Can be tuned to flag known bad domains or external resources in template fields."}, {"field": "ParentProcess", "description": "May be environment-specific; typically Word, Excel, PowerPoint."}, {"field": "TimeWindow", "description": "Correlation window for process + network activity."}, {"field": "ChildProcessAnomalyThreshold", "description": "Trigger when document-spawned child process deviates from expected profile."}]', '2026-05-01 15:26:36.640267');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1534, 'AN0933', 'Analytic 0933', 'Process chains that use native utilities (vssadmin, wbadmin, diskshadow, bcdedit, REAgentC, wmic) with arguments to delete shadow copies, disable recovery, or remove backup catalogs', '{Windows}', 'x-mitre-analytic--decb2be7-1a0a-46dd-ab48-cf6258c0185e', 'DET0329', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Microsoft-Windows-Backup", "channel": "Windows Backup Catalog deletion or catalog corruption", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "WinEventLog:System", "channel": "Service stopped or RecoveryDisabled set via REAgentC", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "TimeWindow", "description": "Used to track rapid recovery feature changes over short intervals"}, {"field": "CommandLinePattern", "description": "Can be tuned to catch variations in destructive flags (/all, /quiet, -delete)"}, {"field": "ParentProcessContext", "description": "Tune based on common parent-child chains (e.g., powershell → diskshadow)"}]', '2026-05-01 15:26:36.643212');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1535, 'AN0406', 'Analytic 0406', 'Detection of firewall tampering by monitoring processes executing netsh, PowerShell Set-NetFirewallProfile, or sc stop mpssvc. Registry modifications under HKLM\SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy also indicate adversarial actions.', '{Windows}', 'x-mitre-analytic--df0f8f0a-1e92-415d-b15e-63cea928973a', 'DET0145', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "MonitoredCommands", "description": "List of admin tools and scripts allowed to legitimately modify firewall settings."}, {"field": "AlertThreshold", "description": "Number of firewall rule changes within a time window before triggering alert."}]', '2026-05-01 15:26:36.645654');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1536, 'AN0858', 'Analytic 0858', 'Terminal-based grep or open of plist/config files containing credentials, correlated with Keychain or system login attempts.', '{macOS}', 'x-mitre-analytic--df289d0f-0f31-487e-b213-9a492d903f2c', 'DET0307', '[{"name": "macos:unifiedlog", "channel": "grep/cat on files matching credential patterns", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "open/read of *.plist or .env files", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "Keychain or user login post-access", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "KeychainToolAccess", "description": "Monitor unexpected use of security CLI or Keychain helper binaries"}, {"field": "FileTypeList", "description": "Add or remove watched file types based on system usage"}]', '2026-05-01 15:26:36.647448');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1537, 'AN0476', 'Analytic 0476', 'EFI updates executed via system processes or binaries outside of expected patch windows or using unsigned firmware packages.', '{macOS}', 'x-mitre-analytic--df32865a-79b2-4faa-abd4-3ecfa27c8a77', 'DET0167', '[{"name": "macos:unifiedlog", "channel": "com.apple.firmwareupdater activity or update-firmware binary invoked", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "boot failure events or SMC validation errors", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}]', '[{"field": "UpdateTimeWindow", "description": "Firmware updates usually occur after OS update; out-of-band patterns may indicate compromise"}]', '2026-05-01 15:26:36.648677');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1538, 'AN0753', 'Analytic 0753', 'Use of cloud-based bastion or VM console session followed by commands that initiate outbound SSH or RDP sessions from the cloud instance to other environments.', '{IaaS}', 'x-mitre-analytic--dfabf07a-8179-43f5-abf6-699202c10343', 'DET0269', '[{"name": "AWS:CloudTrail", "channel": "AWS ConsoleLogin, StartSession", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "AWS:VPCFlowLogs", "channel": "Outbound connections to port 22, 3389", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "SourceAssetTag", "description": "Limit detection to cloud admin/bastion hosts"}, {"field": "TargetPortList", "description": "Define critical remote service ports to flag"}]', '2026-05-01 15:26:36.649905');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1539, 'AN0528', 'Analytic 0528', 'Application access tokens used to call APIs (e.g., Google Workspace, Salesforce) without interactive logins, often with unusual scopes or elevated permissions.', '{SaaS}', 'x-mitre-analytic--dfad1a86-de44-40b2-95b5-9b18c4103cbb', 'DET0185', '[{"name": "saas:googleworkspace", "channel": "OAuthTokenGranted, APIRequest", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "saas:salesforce", "channel": "API login using access_token without login history", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "ApplicationScopeAllowlist", "description": "Restrict allowed API scopes for enterprise applications"}, {"field": "TokenLifetime", "description": "Threshold for detecting unusually long-lived tokens"}]', '2026-05-01 15:26:36.651184');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1540, 'AN1073', 'Analytic 1073', 'Collection of device configuration via CLI commands (e.g., `show running-config`, `copy flash`, `more`), often followed by TFTP/SCP transfers.', '{"Network Devices"}', 'x-mitre-analytic--dfe1b67a-a1c1-43f4-a043-5784a315d018', 'DET0380', '[{"name": "networkdevice:cli", "channel": "command logging", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandScope", "description": "Defines list of configuration or diagnostic commands to monitor."}, {"field": "AuthenticatedUserList", "description": "Helps reduce false positives by whitelisting known admins."}]', '2026-05-01 15:26:36.652468');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1541, 'AN0740', 'Analytic 0740', 'Detects Exchange Online or on-prem transport rule changes (e.g., header stripping) and mailbox export cleanup via `Remove-MailboxExportRequest`, as well as admin actions via Exchange PowerShell sessions.', '{"Office Suite"}', 'x-mitre-analytic--dff59103-f6d4-4580-8316-a0528768b4b3', 'DET0266', '[{"name": "m365:exchange", "channel": "Admin Audit Logs, Transport Rules", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:PowerShell", "channel": "Exchange Cmdlets", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CmdletFilter", "description": "Include `New-TransportRule`, `Set-TransportRule`, `Remove-*` actions"}, {"field": "UserRoleScope", "description": "Track role assignments for admins performing deletions"}]', '2026-05-01 15:26:36.653806');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1542, 'AN1384', 'Analytic 1384', 'Abuse of file/registry attributes to hide malicious files, directories, or services. Defender view: detection of attrib.exe setting hidden/system flags, creation of Alternate Data Streams, or registry keys altering file visibility.', '{Windows}', 'x-mitre-analytic--e01b29cd-2369-4ad5-bd91-98994f36cd1e', 'DET0502', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "FileExtensions", "description": "Filter for sensitive file types likely targeted for hiding."}, {"field": "ADSDetection", "description": "Enable or disable detection of Alternate Data Streams depending on business use."}]', '2026-05-01 15:26:36.655005');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1543, 'AN0565', 'Analytic 0565', 'Applications such as `curl`, `wget`, or custom binaries initiate HTTPS connections where the TLS SNI is mismatched or absent while HTTP Host targets CDN-available C2 endpoints.', '{Linux}', 'x-mitre-analytic--e031d1a5-92a9-46df-9467-d6899d48f57b', 'DET0196', '[{"name": "NSM:Flow", "channel": "ssl.log + http.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SNIFieldAbsent", "description": "Detect TLS sessions where SNI is empty—''domainless'' fronting."}, {"field": "AllowedTools", "description": "Environmental tuning for known binaries using alternate SNI for testing (e.g., API tests)."}, {"field": "ProcessContext", "description": "Enrich command-line arguments or parent-child lineage to detect abuse."}]', '2026-05-01 15:26:36.656747');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1544, 'AN0299', 'Analytic 0299', 'Detection of spearphishing links through mail logs and browser activity. Behavior includes email with suspicious URLs → user click recorded in mail/web proxy logs → shell or interpreter launched from browser process.', '{Linux}', 'x-mitre-analytic--e08e4dd6-cab5-41c0-b136-1bc8426c25ed', 'DET0107', '[{"name": "Application:Mail", "channel": "Inbound emails containing hyperlinks from suspicious sources", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "auditd:SYSCALL", "channel": "execve: Execution of scripts or binaries spawned from browser processes", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Outbound requests to domains not previously resolved or associated with phishing campaigns", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "MonitoredBrowsers", "description": "List of browser processes to monitor (e.g., firefox, chrome, chromium)."}, {"field": "PhishingIndicators", "description": "Custom regex patterns for detecting obfuscated or IDN homograph URLs."}]', '2026-05-01 15:26:36.658512');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1545, 'AN0555', 'Analytic 0555', 'Identify unauthorized creation, deletion, or modification of business-critical stored data such as Office documents, database files, and log archives. Detect anomalous processes modifying stored data outside of expected workflows (e.g., non-database processes modifying database files).', '{Windows}', 'x-mitre-analytic--e08eb9fa-4a45-434b-9776-277bd545f1f7', 'DET0193', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=23", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=15", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "MonitoredDirectories", "description": "Paths to sensitive stored data files such as database directories or email archives."}, {"field": "AuthorizedProcesses", "description": "List of legitimate processes expected to create, delete, or modify stored data."}, {"field": "TimeWindow", "description": "Threshold for correlating multiple suspicious file operations within a short period."}]', '2026-05-01 15:26:36.659918');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1546, 'AN0642', 'Analytic 0642', 'Suspicious querying of organization-wide directory data via Google Workspace Directory API or Outlook GAL sync in high volume from abnormal users, service accounts, or unknown device contexts.', '{"Office Suite"}', 'x-mitre-analytic--e0ad2e3d-c109-4af0-ac44-0d4cd45407c2', 'DET0229', '[{"name": "gcp:audit", "channel": "Directory API Access: users.list or groups.list", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "m365:unified", "channel": "GAL Lookup or Address Book download", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "azure:signinlogs", "channel": "Unusual Token Usage or Application Consent", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "APIQueryVolume", "description": "Set thresholds for excessive use of ''users.list'' or recursive group enumerations."}, {"field": "UserContext", "description": "Flag non-admin or previously unseen user agents requesting directory information."}, {"field": "AppSource", "description": "Distinguish between sanctioned sync tools and unauthorized scripts or OAuth tokens."}]', '2026-05-01 15:26:36.661334');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1547, 'AN0821', 'Analytic 0821', 'User or desktop application writes a new file to ~/Downloads, /tmp, or mounted removable media followed by execve of a risky interpreter/loader (bash, sh, python, perl, php, node, curl|wget piping to sh, ld.so, rdesktop, xdg-open - with unusual args). Uses auditd PATH+SYSCALL (open/creat/write/rename) with execve event linking.', '{Linux}', 'x-mitre-analytic--e0b64d4e-79e0-47b8-a95c-414e2b69406d', 'DET0294', '[{"name": "auditd:SYSCALL", "channel": "open/create/rename: name in (/home/*/Downloads/*|/tmp/*|/run/user/*|/media/*) AND ext in SuspiciousExtensions", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "execve: exe in {/bin/bash,/bin/sh,/usr/bin/python*,/usr/bin/perl,/usr/bin/php,/usr/bin/node,/usr/bin/curl,/usr/bin/wget,/usr/bin/xdg-open,/usr/bin/ssh,/usr/bin/rundll32 (wine)} AND ppid process is a document viewer/browser", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Correlation window for audit events (e.g., ≤5m)."}, {"field": "DesktopParentMap", "description": "Map common desktop apps (libreoffice, evince, firefox, chromium) for lineage anchoring."}]', '2026-05-01 15:26:36.662936');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1549, 'AN0106', 'Analytic 0106', 'Detects attempts to access browser credential stores (e.g., Firefox `logins.json`, Chrome SQLite DB) or processes (e.g., gnome-keyring-daemon). Observes unauthorized file reads and memory inspection of browser processes using ptrace or gdb.', '{Linux}', 'x-mitre-analytic--e11709c9-0203-4f76-bbfb-379ed36723ce', 'DET0037', '[{"name": "auditd:FILE", "channel": "/home/*/.mozilla/firefox/*/logins.json OR /home/*/.config/google-chrome/*/Login Data", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "ptrace attach", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "BrowserCredentialFiles", "description": "Paths of web browser credential databases to monitor"}, {"field": "AllowedDebuggers", "description": "List of expected debugging tools for dev/test environments"}]', '2026-05-01 15:26:36.665469');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1550, 'AN1075', 'Analytic 1075', 'Correlates file enumeration of XML files in the SYSVOL share with suspicious process execution that decodes or reads encrypted credentials embedded in Group Policy Preference files (e.g., Get-GPPPassword.ps1, gpprefdecrypt.py, Metasploit). Detects abnormal access to \DOMAIN\SYSVOL combined with XML file parsing or decryption logic.', '{Windows}', 'x-mitre-analytic--e14e67af-6f6e-47d6-aa19-4012ea99284c', 'DET0381', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=5145", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"name": "WinEventLog:PowerShell", "channel": "Scripts with references to XML parsing, AES decryption, or gpprefdecrypt logic", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "UserContext", "description": "Tune to exclude authorized admin users or domain controllers accessing SYSVOL"}, {"field": "TimeWindow", "description": "Adjust for correlation timing between file access and script execution"}, {"field": "KnownToolsSignature", "description": "Extend to include known GPP parsing tool names or script hashes"}, {"field": "HostType", "description": "Distinguish between expected access from DCs vs. lateral movement from workstations"}]', '2026-05-01 15:26:36.666683');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1551, 'AN0898', 'Analytic 0898', 'ESXi host processes (vmx, hostd) initiating HTTPS sessions toward external code repositories. Defender perspective: detect datastore reads followed by outbound web traffic inconsistent with administrative baselines.', '{ESXi}', 'x-mitre-analytic--e18f0682-6610-4ba8-8159-a4afea3b7974', 'DET0318', '[{"name": "esxi:hostd", "channel": "datastore file access", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "esxi:vmkernel", "channel": "HTTPS traffic to repository domains", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "DatastoreTransferThreshold", "description": "Amount of data moved from datastore to external services before raising alert."}]', '2026-05-01 15:26:36.669448');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1552, 'AN1345', 'Analytic 1345', 'Behavioral chain: (1) sshd or federated SSO logins from third-party networks or identities; (2) rapid sudo/su privilege elevation; (3) access to sensitive paths or east-west SSH. Correlate auth logs, process execution, and network flows.', '{Linux}', 'x-mitre-analytic--e19cbf11-fabf-4dfd-aeb2-1c62660ebd8f', 'DET0488', '[{"name": "auditd:SYSCALL", "channel": "execve,socket,connect,openat", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "linux:syslog", "channel": "Accepted publickey/password for * from * port * ssh2", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "NSM:Flow", "channel": "ssh connections originating from third-party CIDRs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ThirdPartyUsers", "description": "POSIX accounts assigned to vendors/partners."}, {"field": "AllowedJumpHosts", "description": "Bastion hosts permitted for third-party access."}, {"field": "MFAExpected", "description": "Flag indicating whether PAM/MFA should be present; used to score risk."}]', '2026-05-01 15:26:36.670669');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1553, 'AN0446', 'Analytic 0446', 'Detection of USB-based remote access hardware (e.g., TinyPilot, PiKVM) attached to the host via drive or peripheral enumeration, triggering vendor identifiers or unusual EDID announcements.', '{Windows}', 'x-mitre-analytic--e1e76ffd-b452-429e-8ea0-a25ba877a2b5', 'DET0159', '[{"name": "WinEventLog:System", "channel": "EventCode=2003", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "VendorID", "description": "Device vendor strings may need tuning to include additional remote hardware sources."}, {"field": "SerialNumber", "description": "Serial numbers for known implants can vary per campaign and may need expansion."}, {"field": "TimeWindow", "description": "Adjust the detection window for peripheral enumeration based on environment and operating hours."}]', '2026-05-01 15:26:36.672038');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1554, 'AN2021', 'Analytic 2021', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1555, 'AN0610', 'Analytic 0610', 'Adversary manipulation of shared library paths, environment variables, or replacement of service binaries. Defender observes suspicious modifications in /etc/ld.so.preload, service config changes, or file writes replacing existing executables.', '{Linux}', 'x-mitre-analytic--e21542c4-8df8-4c9e-8b1d-2c9bbe058386', 'DET0218', '[{"name": "auditd:SYSCALL", "channel": "open/write syscalls targeting /etc/ld.so.preload or binaries in /usr/bin", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:syslog", "channel": "Service restart with modified executable path", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "linux:osquery", "channel": "Process execution with LD_PRELOAD or modified library path", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredDirectories", "description": "Directories where binary replacement should trigger alerts."}, {"field": "EnvVarMonitors", "description": "Environment variables like LD_PRELOAD or PATH to monitor."}]', '2026-05-01 15:26:36.675442');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1556, 'AN0442', 'Analytic 0442', 'Monitor for unauthorized or unusual modifications to cloud resource hierarchies such as AWS Organizations or Azure Management Groups. Defenders may observe anomalous calls to APIs like `LeaveOrganization`, `CreateAccount`, `MoveAccount`, or Azure subscription transfers. Correlate account activity with administrative role assignments, tenant transfers, or new subscription creation that deviates from organizational baselines. Multi-event correlation should track role elevation followed by hierarchy modifications within a short time window.', '{IaaS}', 'x-mitre-analytic--e246212e-aca3-489d-a2d9-7e24f7c3516c', 'DET0155', '[{"name": "AWS:CloudTrail", "channel": "LeaveOrganization: API calls severing accounts from AWS Organizations", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}]', '[{"field": "TimeWindow", "description": "Threshold for correlating role elevation with hierarchy modification events."}, {"field": "PrivilegedRoleList", "description": "List of high-privilege roles (e.g., Global Administrator, OrganizationAccountAccessRole) used to monitor sensitive modifications."}, {"field": "SubscriptionTransferPatterns", "description": "Patterns of subscription changes that may indicate hijacking or unauthorized tenant transfers."}]', '2026-05-01 15:26:36.676988');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1557, 'AN1535', 'Analytic 1535', 'MSBuild.exe is invoked outside expected developer/build contexts or with anomalous arguments (e.g., non-canonical paths, remote shares, Base64/obfuscated property values). Within a short window, it (a) spawns high-risk LOLBins/script interpreters, (b) writes new PE/DLL/script artifacts into user-writable paths and executes them, (c) loads unsigned/user-writable modules, (d) performs memory injection/thread creation into other processes, and/or (e) initiates outbound network connections.', '{Windows}', 'x-mitre-analytic--e24b6c08-4fd0-40c7-a71a-762cc08d6085', 'DET0556', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "channel": "Unsigned/invalid signature modules or images loaded by msbuild.exe or its children", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "EDR:AMSI", "channel": "Malicious inline C#/script blobs embedded in MSBuild projects if intercepted by AMSI-aware loaders (rare but possible via chained LOLBins)", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "TimeWindow", "description": "Correlation window between msbuild.exe start, payload write, suspicious child spawn, and network (e.g., 0–30 minutes)."}, {"field": "DeveloperHosts", "description": "Tag/allowlist known developer or CI/CD hosts to reduce noise."}, {"field": "SuspiciousChildList", "description": "High-risk children (powershell.exe, rundll32.exe, regsvr32.exe, cmd.exe, wscript.exe, mshta.exe) spawned by msbuild.exe."}, {"field": "RarePathRegex", "description": "Regex of user-writable or atypical paths (e.g., %TEMP%, %APPDATA%, OneDrive sync dirs) used to drop payloads."}, {"field": "UnsignedOrInvalidSignatureOnly", "description": "Tighten alerting to cases with invalid or missing signatures on modules/children."}, {"field": "NetworkReputationThreshold", "description": "Minimum rarity/risk score for external destinations to alert."}, {"field": "BehaviorRiskScoreThreshold", "description": "Numeric threshold for fused, scored correlation (e.g., ≥70/100 triggers an alert)."}]', '2026-05-01 15:26:36.678617');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1558, 'AN0752', 'Analytic 0752', 'Remote login via ARD or SSH followed by screensharingd process activity or modification of TCC-protected files.', '{macOS}', 'x-mitre-analytic--e26778ca-0fd9-4a1b-9d1d-d8ba561b065a', 'DET0269', '[{"name": "macos:unifiedlog", "channel": "eventMessage CONTAINS ''screensharingd'' or ''AuthorizationRefCreate''", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "RemoteService", "description": "Differentiate ARD vs SSH access patterns"}, {"field": "TargetedPath", "description": "Tunable list of sensitive directories or TCC targets"}]', '2026-05-01 15:26:36.680481');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1559, 'AN0835', 'Analytic 0835', 'Behavioral sequence of unauthorized privilege escalation via permission modification: (1) chmod/chown/setfacl process execution with suspicious parameters, (2) Targeting of critical system files or unusual permission values, (3) Correlation with non-privileged user context or unusual timing patterns, (4) Follow-on file access indicating successful permission bypass', '{Linux}', 'x-mitre-analytic--e268a6cb-2264-473e-9683-fb0f33ecd793', 'DET0299', '[{"name": "auditd:SYSCALL", "channel": "syscall in (chmod, fchmod, fchmodat, chown, fchown, fchownat, setxattr, lsetxattr, fsetxattr)", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "auditd:PROCTITLE", "channel": "proctitle contains chmod, chown, setfacl, or attr commands with suspicious parameters", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SuspiciousPermissionValues", "description": "Octal permission values that indicate potential malicious intent (default: 777, 755, 4755)"}, {"field": "CriticalPathPatterns", "description": "Linux filesystem paths requiring enhanced monitoring (/etc/, /usr/bin/, /home/)"}, {"field": "AuthorizedAdminUsers", "description": "User accounts permitted to perform system-level permission modifications"}, {"field": "AnomalyThreshold", "description": "Statistical threshold for detecting unusual permission modification frequency"}]', '2026-05-01 15:26:36.681935');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1560, 'AN0774', 'Analytic 0774', 'Unusual modification of boot records (MBR, VBR) or EFI partitions not associated with legitimate patch cycles or OS upgrades. Registry or WMI events associated with firmware update tools executed from unexpected parent processes. API calls (e.g., DeviceIoControl) writing directly to raw disk sectors. Subsequent abnormal boot configuration changes followed by unsigned driver loads.', '{Windows}', 'x-mitre-analytic--e2ca60b5-82df-4e7e-8528-dd24d9a79750', 'DET0278', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=9", "x_mitre_data_component_ref": "x-mitre-data-component--73ff2dcc-24b1-4368-b9dc-706dd9e68354"}]', '[{"field": "AllowedFirmwareUpdateTools", "description": "Legitimate vendor tools or processes authorized to modify firmware or boot records."}, {"field": "TimeWindow", "description": "Correlating boot-sector modification with subsequent reboot events."}, {"field": "EntropyThreshold", "description": "Heuristic threshold for detecting obfuscated/packed boot code."}]', '2026-05-01 15:26:36.683415');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1561, 'AN1128', 'Analytic 1128', 'Enumeration of directories, applications, or service principals through APIs such as Microsoft Graph or Okta API. Defender perspective includes unexpected listing of users, roles, applications, and abnormal access to identity management endpoints.', '{"Identity Provider"}', 'x-mitre-analytic--e2dd9fee-91b7-4e32-8031-69ed4d7b927c', 'DET0402', '[{"name": "azure:audit", "channel": "ListApplications, ListServicePrincipals: Large-scale queries against identity or application objects", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"name": "azure:signinlogs", "channel": "InteractiveUserLogin: Discovery behavior linked to privileged logins from atypical IP ranges", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "QueryVolumeThreshold", "description": "Threshold for number of object enumeration calls before triggering detection."}, {"field": "PrivilegedRoleList", "description": "High-value identity roles (Global Admin, Application Admin) for targeted discovery monitoring."}]', '2026-05-01 15:26:36.684787');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1562, 'AN1098', 'Analytic 1098', 'Detect runtime manipulation by monitoring system calls for modifications to shared libraries, ELF binaries, or environment variables that affect how data is displayed. Look for suspicious writes to application directories and mismatch in binary integrity baselines.', '{Linux}', 'x-mitre-analytic--e2e39b7e-02e4-4e7a-966c-6b05721da8f7', 'DET0391', '[{"name": "auditd:SYSCALL", "channel": "open, write: File writes to application binaries or libraries at runtime", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "linux:syslog", "channel": "Execution of modified binaries or abnormal library load sequences", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "WatchedBinaries", "description": "Specific critical application binaries or libraries to monitor for unauthorized changes."}, {"field": "IntegrityCheckFrequency", "description": "Interval for verifying hashes of executables and libraries."}]', '2026-05-01 15:26:36.686078');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1563, 'AN0949', 'Analytic 0949', 'Monitors for unexpected modifications of system or application binaries, particularly signed executables. Correlates file write events with subsequent unsigned or anomalously signed process execution, and checks for tampered binaries outside normal patch cycles.', '{Windows}', 'x-mitre-analytic--e2ebd04e-074d-4b90-b94c-a43048b1c3ac', 'DET0336', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=2", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "MonitoredPaths", "description": "Define critical directories (e.g., C:\\Windows\\System32, Program Files) for binary integrity checks"}, {"field": "SignatureValidation", "description": "Adjust enforcement level of digital signature verification based on enterprise risk appetite"}, {"field": "TimeWindow", "description": "Correlate file modification with subsequent process execution within a defined time window"}]', '2026-05-01 15:26:36.687569');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1564, 'AN1264', 'Analytic 1264', 'Burst of failed authentications with rotating usernames against loginwindow or remote management service using reused breached credentials', '{macOS}', 'x-mitre-analytic--e2f104ac-b21a-4c48-8987-3e0ad73997df', 'DET0460', '[{"name": "macos:unifiedlog", "channel": "Login failure / authorization denied", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "DistinctUsernameCount", "description": "Tunable threshold for number of attempted usernames in a time window"}, {"field": "RemoteAccessFilter", "description": "Restrict behavior detection to remote login interfaces"}]', '2026-05-01 15:26:36.68907');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1565, 'AN0935', 'Analytic 0935', 'ESXi shell or vim-cmd execution that deletes all VM snapshots using vmsvc/snapshot.removeall or rm on snapshot paths', '{ESXi}', 'x-mitre-analytic--e2fb4be5-bd70-45d6-89ad-e687bc475285', 'DET0329', '[{"name": "esxi:hostd", "channel": "snapshot.removeall or snapshot file deletion", "x_mitre_data_component_ref": "x-mitre-data-component--16e07530-764b-4d83-bae0-cdbfc31bf21d"}]', '[{"field": "TargetVMNames", "description": "Limit to critical VM names to reduce false positives"}]', '2026-05-01 15:26:36.690703');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1566, 'AN0713', 'Analytic 0713', 'Defender observes unauthorized modification or creation of Python hook files such as `.pth`, `sitecustomize.py`, or `usercustomize.py` in Python `site-packages`, `dist-packages`, or user paths. This is often correlated with subsequent unexpected interpreter execution (e.g., python3 running without user interaction), changes in interpreter behavior (e.g., malicious imports), and outbound connections initiated from Python. Defender links write/modify actions on hook files with execve of python process and/or anomalous child process or network activity.', '{Linux}', 'x-mitre-analytic--e32ce63a-7c82-4115-8c50-e43113562132', 'DET0258', '[{"name": "auditd:SYSCALL", "channel": "execve: execve where exe=/usr/bin/python3 or similar interpreter", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:PATH", "channel": "write or create events on *.pth, sitecustomize.py, usercustomize.py in site-packages or dist-packages", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "auditd:CONFIG_CHANGE", "channel": "chmod or chown of hook files indicating privilege escalation or execution permission change", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "NSM:Flow", "channel": "http::request: Outbound HTTP initiated by Python interpreter", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "HookFilePathPatterns", "description": "Absolute or regex paths to Python startup files (.pth, customize.py); vary by distro or virtual environment location"}, {"field": "UserContext", "description": "Restrict alerts to non-root users, service accounts, or interactive shell sessions"}, {"field": "TimeWindow", "description": "Correlate file modification and Python execution within short time span (default: 2–5 minutes)"}, {"field": "InterpreterWhitelist", "description": "Filter out known legitimate Python executions tied to expected cron jobs or automation"}]', '2026-05-01 15:26:36.692149');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1567, 'AN0375', 'Analytic 0375', 'Detection of the creation of VSCode or JetBrains CLI tunneling profiles followed by persistent remote access via IDE-integrated tunnels, potentially authenticated via GitHub or JetBrains accounts.', '{Windows}', 'x-mitre-analytic--e3517ec0-f12a-4f64-8d10-e6bc2677f7d7', 'DET0133', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Outbound connection to *.tunnels.api.visualstudio.com or *.devtunnels.ms", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TimeWindow", "description": "Used to define the temporal proximity between tunnel profile creation and outbound connection."}, {"field": "TunnelDomainPatterns", "description": "Domain patterns for tunnel endpoints may change with IDE versions or organizations."}, {"field": "AuthorizedUserList", "description": "Helps filter tunnel usage from trusted developer accounts."}]', '2026-05-01 15:26:36.693605');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1568, 'AN0452', 'Analytic 0452', 'Monitor PAM and syslog entries for unusual frequency of login attempts that trigger MFA prompts, particularly when MFA challenges do not match expected user behavior.', '{Linux}', 'x-mitre-analytic--e36b2d32-05a8-4bcf-b7cf-58dc3ad4c0d3', 'DET0160', '[{"name": "auditd:AUTH", "channel": "pam_unix or pam_google_authenticator invoked repeatedly within short interval", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "AuthRetryThreshold", "description": "Number of retries per user allowed before detection is triggered"}]', '2026-05-01 15:26:36.694937');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1569, 'AN1184', 'Analytic 1184', 'API usage or filesystem access revealing user state or browser artifacts (e.g., Safari bookmarks, CGEventState).', '{macOS}', 'x-mitre-analytic--e3a0ea8d-0018-4603-912a-4d40d0f75390', 'DET0420', '[{"name": "macos:unifiedlog", "channel": "Execution of input detection APIs (e.g., CGEventSourceKeyState)", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "macos:unifiedlog", "channel": "Access to ~/Library/Safari/Bookmarks.plist or recent files", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "TimeWindow", "description": "Temporal correlation between login and file access"}, {"field": "UserContext", "description": "Exclude expected UI activity from login agents"}]', '2026-05-01 15:26:36.696398');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1570, 'AN1175', 'Analytic 1175', 'Detect execution of system utilities (systemctl, systemd-inhibit, systemdsleep) modifying sleep or hibernate behavior. Abnormal edits to system configuration files (e.g., /etc/systemd/sleep.conf) should be correlated with process execution to identify persistence techniques.', '{Linux}', 'x-mitre-analytic--e3bbe2c4-615d-4847-93dc-b5857fc1b384', 'DET0417', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of systemctl, loginctl, or systemd-inhibit commands related to sleep/hibernate", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:PATH", "channel": "write: File modifications to /etc/systemd/sleep.conf or related power configuration files", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "KnownMaintenanceWindows", "description": "Filter benign modifications during patching or system maintenance intervals."}]', '2026-05-01 15:26:36.697741');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1571, 'AN0242', 'Analytic 0242', 'Defender detects execution of `mdfind`, `launchctl`, or GUI-based enumeration (e.g., `/Applications/Time Machine.app`) along with command-line usage of `find`, `grep`, or `system_profiler` to identify installed backup tools like Time Machine, Carbon Copy Cloner, or Backblaze. Often triggered from Terminal sessions or within post-exploitation scripts.', '{macOS}', 'x-mitre-analytic--e3c81570-be1b-48c8-b000-b70173c5c226', 'DET0088', '[{"name": "macos:unifiedlog", "channel": "Process execution logs showing discovery commands like mdfind, system_profiler, or launchctl list", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Read access to Time Machine plist files or CCC configurations in ~/Library/Preferences/", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "InstallLocationScope", "description": "Directories or bundles where backup tools are commonly installed"}, {"field": "KnownAppPlistPaths", "description": "Plist files related to backup software configurations"}]', '2026-05-01 15:26:36.698912');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1572, 'AN0355', 'Analytic 0355', 'Adversary renames LOLBINs or deploys binaries with spoofed file names, internal PE metadata, or misleading icons to appear legitimate. File creation is followed by execution or service registration inconsistent with known usage.', '{Windows}', 'x-mitre-analytic--e3d982ec-2729-4e98-b340-affa13096fd6', 'DET0127', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}]', '[{"field": "OriginalFilenameMismatch", "description": "Compare executable file name with PE metadata OriginalFilename field"}, {"field": "KnownSystemUtilityPaths", "description": "Tune based on expected installation directories for signed binaries"}, {"field": "TimeWindow", "description": "Correlation window between file creation and service/process execution"}]', '2026-05-01 15:26:36.700096');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1573, 'AN0862', 'Analytic 0862', 'Adversary ships a tampered application or update: an updater/installer (msiexec/setup/update.exe/vendor service) writes or replaces binaries; on first run it spawns scripts/shells or unsigned DLLs and beacons to non-approved update CDNs/hosts. Detection correlates: (1) process creation of installer/updater → (2) file metadata changes in program paths → (3) first-run children and module/signature anomalies → (4) outbound connections to unexpected hosts within a short window.', '{Windows}', 'x-mitre-analytic--e3ddaba3-282b-4bd0-b316-78b724b79acd', 'DET0309', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Microsoft-Windows-CodeIntegrity/Operational", "channel": "Unsigned or invalid image for newly installed/updated binaries", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "NSM:Flow", "channel": "First-time egress to non-approved update hosts right after install/update", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TimeWindow", "description": "Correlate write→first-run→egress (default 90 minutes)."}, {"field": "ApprovedUpdateHosts", "description": "Allow-list of vendor update endpoints, enterprise proxy/cache."}, {"field": "ApprovedSigners", "description": "Code-signing publishers allowed for programs/services."}, {"field": "ProgramPaths", "description": "Monitored install locations (e.g., C:\\Program Files, C:\\ProgramData, %LOCALAPPDATA%)."}]', '2026-05-01 15:26:36.701259');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1574, 'AN1262', 'Analytic 1262', 'Multiple failed authentication attempts using distinct username/password pairs from a single IP address or session within a short time window, targeting common services like RDP or SMB', '{Windows}', 'x-mitre-analytic--e3e2d59b-220f-43b0-9891-7b299be27c50', 'DET0460', '[{"name": "WinEventLog:Security", "channel": "EventCode=4625", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "UsernameUniquenessThreshold", "description": "Minimum number of unique usernames in failed login attempts before triggering alert"}, {"field": "TimeWindow", "description": "Duration (e.g., 5 minutes) to observe the behavior chain of rapid login attempts"}, {"field": "SourceIPScope", "description": "Whether to group by full IP or CIDR block for bursty behavior from botnets"}]', '2026-05-01 15:26:36.702523');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1583, 'AN1374', 'Analytic 1374', 'Detects disabling AAA, syslog, SNMP traps, ACL logging, or security features on routers/switches/firewalls; correlates privileged login followed by configuration commit reducing visibility.', '{"Network Devices"}', 'x-mitre-analytic--e542342f-5a08-408d-b292-797bcb2da5eb', 'DET0497', '[{"name": "networkdevice:config", "channel": "write: Startup configuration changes disabling security checks", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "networkdevice:syslog", "channel": "no logging host, no aaa new-model, no snmp-server, commit", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "ConfigBaseline", "description": "Reference configuration state for detecting unauthorized modifications."}]', '2026-05-01 15:26:36.717725');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1575, 'AN0792', 'Analytic 0792', 'Monitor for anomalous email activity originating from Windows-hosted applications (e.g., Outlook) where the sending account name or display name does not match the underlying SMTP address. Detect abnormal volume of outbound messages containing sensitive keywords (e.g., ''payment'', ''wire transfer'') or anomalous login locations for accounts associated with email sending activity.', '{Windows}', 'x-mitre-analytic--e4246c20-fbe4-4750-a29e-44e3fe179bf2', 'DET0286', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "m365:unified", "channel": "SendOnBehalf/SendAs: Emails sent where the sending identity mismatches account ownership", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "KeywordList", "description": "Adjust impersonation detection keywords based on local business risk terms (e.g., ''ACH'', ''Invoice'')."}, {"field": "GeoLocationBaseline", "description": "Define trusted geographic regions for normal user email activity."}]', '2026-05-01 15:26:36.703766');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1576, 'AN0803', 'Analytic 0803', 'Disabling mailbox or tenant-level audit logging, often using Set-MailboxAuditBypassAssociation or downgrading license tiers. Defender view: sudden absence of mailbox activity logging for monitored users.', '{"Office Suite"}', 'x-mitre-analytic--e42656e7-6a0e-492e-82b6-90d0d5667993', 'DET0289', '[{"name": "m365:unified", "channel": "Set-MailboxAuditBypassAssociation or disabling Advanced Auditing", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "UserScope", "description": "Tune alerts for users where mailbox auditing should always remain enabled."}]', '2026-05-01 15:26:36.705211');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1577, 'AN1947', 'Analytic 1947', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1578, 'AN1046', 'Analytic 1046', 'Monitor access to /proc/self/status where TracerPID field is queried, as this is a common technique for debugger detection. Detect processes that attempt to trigger exceptions intentionally and monitor whether exception handling indicates presence of a debugger.', '{Linux}', 'x-mitre-analytic--e4a9dd91-3354-40c8-a55c-941d53f2ddec', 'DET0371', '[{"name": "auditd:SYSCALL", "channel": "open/read: Access to /proc/self/status with focus on TracerPID field", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "MonitoredPaths", "description": "Set of /proc paths to monitor for suspicious access"}, {"field": "SyscallThreshold", "description": "Rate of syscalls (open/read) used to detect repeated probing for debug artifacts"}]', '2026-05-01 15:26:36.708845');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1579, 'AN1974', 'Analytic 1974', 'Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on behaviors relating to the potential use of generative artificial intelligence (i.e. [Phishing](https://attack.mitre.org/techniques/T1566), [Phishing for Information](https://attack.mitre.org/techniques/T1598)).', '{PRE}', 'x-mitre-analytic--e4b35edc-f7fe-4f0d-aaaf-60fabc9d2698', 'DET0842', NULL, NULL, '2026-05-01 15:26:36.710492');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1580, 'AN0233', 'Analytic 0233', 'Execution of container orchestration commands (e.g., `docker exec`, `kubectl exec`) or API-driven interactions with running containers from unauthorized hosts or non-standard user contexts. Defender sees programmatic or interactive command execution within containers outside expected CI/CD tools or automation frameworks, often followed by file writes, privilege escalation, or lateral discovery.', '{Containers}', 'x-mitre-analytic--e4dd4100-2387-4029-a478-35aefd37c288', 'DET0083', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of container management CLIs (docker, crictl, kubectl) or interpreted shells (sh, bash, python) within container context", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "docker:events", "channel": "exec_create: docker exec events targeting running containers from non-CI sources", "x_mitre_data_component_ref": "x-mitre-data-component--5fe82895-28e5-4aac-845e-dc886b63be2e"}, {"name": "kubernetes:apiserver", "channel": "create/exec: Kubernetes API calls to exec into containers or create pods from curl, kubectl, or SDK clients", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"name": "AWS:CloudTrail", "channel": "CreatePod: Programmatic creation of new pod resources using container images not seen before in the environment", "x_mitre_data_component_ref": "x-mitre-data-component--5263cb33-08cc-4a68-820f-004e1e400d76"}, {"name": "kubernetes:audit", "channel": "Shell process (e.g., /bin/sh, /bin/bash) spawned in a container without an interactive session attached (i.e., automation anomaly)", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "AuthorizedUserAgents", "description": "List of CI/CD pipeline runners, SRE tools, or cluster mgmt agents allowed to invoke API/CLI commands in containers."}, {"field": "NewImageThreshold", "description": "Threshold for alerting on unseen container images pulled and executed. Adjust to reduce noise from frequent deploys."}, {"field": "TimeWindow", "description": "Temporal window to correlate container exec with shell spawn and network activity (default: 2 minutes)."}, {"field": "InteractiveSessionExpectation", "description": "Set whether shell spawns without TTY or PTY should be flagged — based on org deployment model."}]', '2026-05-01 15:26:36.712015');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1581, 'AN0937', 'Analytic 0937', 'Cloud API calls disabling snapshot scheduling, backup policies, versioning, followed by DeleteSnapshot/DeleteVolume operations', '{IaaS}', 'x-mitre-analytic--e50f8247-73da-4461-a560-745ed84f1209', 'DET0329', '[{"name": "AWS:CloudTrail", "channel": "DeleteSnapshot", "x_mitre_data_component_ref": "x-mitre-data-component--16e07530-764b-4d83-bae0-cdbfc31bf21d"}, {"name": "AWS:CloudTrail", "channel": "DeleteBucket, DeleteDBCluster, DeleteSnapshot, TerminateInstances", "x_mitre_data_component_ref": "x-mitre-data-component--4c41e296-b8d2-4a37-b789-eb565c87c00c"}]', '[{"field": "UserAgent", "description": "Tune for legitimate backup automation vs unknown tools"}, {"field": "ResourceType", "description": "Filter only on production images or vaults"}]', '2026-05-01 15:26:36.713972');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1582, 'AN0930', 'Analytic 0930', 'ESXi shell or scripts produce long, high-entropy tokens (non-standard alphabets) in shell.log/hostd, followed by outbound flows (NSX/Zeek) with asymmetric ratios or protocol mismatches to non-management endpoints.', '{ESXi}', 'x-mitre-analytic--e518b7e5-6e98-43f6-86c2-f45f684c650f', 'DET0326', '[{"name": "esxi:shell", "channel": "commands containing long non-standard tokens or custom lookup tables", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "esxi:hostd", "channel": "unexpected script invocations producing long encoded strings", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "network_flow: bytes_out >> bytes_in, fixed packet sizes/intervals to non-approved CIDRs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "http: HTTP bodies from ESXi host IPs containing long, non-standard tokens", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "MgmtCIDRs", "description": "CIDRs allowed for normal ESXi mgmt/backup."}, {"field": "BytesOutToInRatio", "description": "Asymmetry cutoff (e.g., ≥3)."}, {"field": "TokenLengthThreshold", "description": "Minimum token length."}, {"field": "TimeWindow", "description": "Correlation window."}]', '2026-05-01 15:26:36.715482');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1584, 'AN0836', 'Analytic 0836', 'macOS-specific permission modification behavioral chain: (1) chmod/chown/chflags process execution, (2) System Integrity Protection (SIP) bypass attempts, (3) Extended attribute (xattr) modifications, (4) Unified log correlation with file system events, (5) Subsequent access to previously restricted resources', '{macOS}', 'x-mitre-analytic--e564e2b8-542b-4003-a8b7-df9d3396f5b9', 'DET0299', '[{"name": "macos:unifiedlog", "channel": "process execution events for chmod, chown, chflags with unusual parameters or targets", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsevents", "channel": "file system events indicating permission or attribute changes", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "SIPProtectedPaths", "description": "macOS system paths protected by SIP that should never have permission modifications"}, {"field": "SuspiciousFlagCombinations", "description": "chflags parameter combinations indicating evasive behavior (uchg, schg, hidden)"}, {"field": "XattrMonitoringScope", "description": "Extended attributes to monitor for unauthorized modifications"}, {"field": "UnifiedLogRetention", "description": "Log retention period for correlating permission changes with subsequent access"}]', '2026-05-01 15:26:36.71918');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1585, 'AN1612', 'Analytic 1612', 'Detection of processes performing local or domain account enumeration by invoking account directory queries or security APIs followed by structured output of account lists. The defender observes command execution or API invocation patterns that retrieve account information and produce enumeration artifacts shortly afterward.', '{Windows}', 'x-mitre-analytic--e576eaeb-2158-40f9-8edb-c119eac56442', 'DET0587', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4798, 4799", "x_mitre_data_component_ref": "x-mitre-data-component--8e44412e-3238-4d64-8878-4f11e27784fe"}]', '[{"field": "CommandLinePattern", "description": "Match variations in enumeration commands like ''net user'', ''Get-ADUser'', ''dsquery''."}, {"field": "TimeWindow", "description": "Short burst of account enumeration commands may indicate automation."}, {"field": "UserContext", "description": "Restrict to non-admin accounts or unexpected users executing enumeration commands."}]', '2026-05-01 15:26:36.72054');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1586, 'AN0044', 'Analytic 0044', 'Detects snapshots or data stored in VMFS volumes from root CLI or remote agents.', '{ESXi}', 'x-mitre-analytic--e59e2d8c-20cb-4a77-9d8b-1d838b01bd87', 'DET0014', '[{"name": "esxi:vmkernel", "channel": "VMFS access logs", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "esxi:shell", "channel": "snapshot create/copy, esxcli", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "SnapshotFrequency", "description": "Number of snapshots in short time period"}, {"field": "AccessUserList", "description": "Non-admins or automation accounts writing to datastores"}, {"field": "CLIContext", "description": "Manual or unexpected API calls triggering snapshots"}]', '2026-05-01 15:26:36.721899');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1587, 'AN1110', 'Analytic 1110', 'Web servers (e.g., httpd) spawning abnormal processes post file upload into /Library/WebServer/Documents or /usr/local/var/www', '{macOS}', 'x-mitre-analytic--e5a0bbf3-e5d0-41f1-b757-c67eccece77b', 'DET0394', '[{"name": "macos:unifiedlog", "channel": "httpd spawning bash, zsh, python, or osascript", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "file write operations in /Library/WebServer/Documents", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "InterpreterName", "description": "Adversary may use different scripting environments"}, {"field": "ExecutionParent", "description": "Not all web servers are named httpd; may differ in custom deployments"}]', '2026-05-01 15:26:36.723772');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1588, 'AN0262', 'Analytic 0262', 'Detects modification of ESXi cron jobs, local.sh scripts, or scheduled API calls to persist custom binaries or shell scripts.', '{ESXi}', 'x-mitre-analytic--e5adcc7e-5d68-4080-bb87-e901f297485d', 'DET0094', '[{"name": "esxi:vmkernel", "channel": "Startup script and task execution logs", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "esxi:hostd", "channel": "shell access or job registration", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:cron", "channel": "manual edits to /etc/rc.local.d/local.sh or cron.d", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "StartupScriptName", "description": "Filename not matching expected initialization scripts."}, {"field": "ExecutionContext", "description": "Commands run from unexpected SSH sessions or elevated shells."}, {"field": "PersistenceInterval", "description": "Rare scheduling triggers (e.g., @reboot + hourly repetition)."}]', '2026-05-01 15:26:36.725481');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1589, 'AN0353', 'Analytic 0353', 'Direct modification of /etc/ssh/keys-<user>/authorized_keys or enabling SSH in sshd_config to support public key auth.', '{ESXi}', 'x-mitre-analytic--e5b0d0ab-a464-4e9f-a1c0-dfb08a6ef53f', 'DET0126', '[{"name": "esxi:shell", "channel": "file write or edit", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "SSHConfigPath", "description": "Could be modified SSH path in hypervisor"}, {"field": "ESXiShellActivity", "description": "Whether shell was enabled beforehand via DCUI or API"}]', '2026-05-01 15:26:36.727042');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1590, 'AN1633', 'Analytic 1633', 'Detects exploitation attempts targeting defensive security software or OS services. Defender observation includes abnormal process behavior (e.g., AV or EDR crashing unexpectedly), unsigned/untrusted modules loaded into defensive processes, or privilege escalation from security agent services. Multi-event correlation ties exploitation attempts to subsequent evasive behavior like service termination or missing logs.', '{Windows}', 'x-mitre-analytic--e5b0fcab-05e5-4687-a1a9-dd382a19980b', 'DET0595', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "DefensiveProcessList", "description": "List of defensive services/processes (e.g., AV, EDR) monitored in the environment."}, {"field": "AllowedModulePaths", "description": "Whitelisted DLL/module paths normally loaded by defensive tools."}, {"field": "CrashThreshold", "description": "Number of abnormal terminations of defensive processes tolerated before triggering an alert."}]', '2026-05-01 15:26:36.728261');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1591, 'AN0564', 'Analytic 0564', 'Suspicious outbound HTTPS connections where the TLS Server Name Indication (SNI) does not match the HTTP Host header, indicating potential use of domain fronting to mask C2 traffic via CDNs.', '{Windows}', 'x-mitre-analytic--e5cb92b6-75b0-4eed-aa1e-4ea529f50fbb', 'DET0196', '[{"name": "NSM:Connections", "channel": "TLS handshake + HTTP headers", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "SNIHostMismatch", "description": "Define acceptable mismatch ratio between SNI and HTTP Host fields based on legitimate domain usage patterns."}, {"field": "CDNAllowList", "description": "Whitelist of known safe CDN front-end domains (e.g., `cdn.company.com`)."}, {"field": "ProcessInitiator", "description": "Filter for suspicious initiators of domain fronting, e.g., scripting engines, lolbins, unknown binaries."}]', '2026-05-01 15:26:36.729725');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1592, 'AN0638', 'Analytic 0638', 'Shell script or binary initiates curl/wget request to staging domain, writes output to disk or memory, and shortly afterward launches another process that establishes new outbound connection to a different IP or hostname.', '{Linux}', 'x-mitre-analytic--e5fcc815-0ab4-4da9-aade-659b87d079da', 'DET0228', '[{"name": "auditd:SYSCALL", "channel": "execve, connect", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "iptables:LOG", "channel": "OUTBOUND", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "BinaryPath", "description": "Tune for suspicious binaries like curl, wget, python, netcat"}, {"field": "IPDistance", "description": "Detect multiple different external IPs contacted within short timeframe"}]', '2026-05-01 15:26:36.731115');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1593, 'AN1397', 'Analytic 1397', 'Detection of mshta.exe execution where command-line arguments reference remote or local HTA/script content (VBScript/JScript) followed by subsequent file creation, network retrieval, or process spawning that indicates payload execution outside standard Internet Explorer security context. Correlation includes parent process lineage, command-line inspection, and network connection creation to untrusted or anomalous endpoints.', '{Windows}', 'x-mitre-analytic--e6037bea-ba25-40bf-b681-361d4f901adb', 'DET0506', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "CommandLinePattern", "description": "Regex patterns for mshta.exe arguments referencing remote HTA/script content; may need tuning to exclude known-good internal scripts."}, {"field": "SuspiciousParentProcesses", "description": "List of parent processes considered suspicious when spawning mshta.exe (e.g., Office applications, script interpreters)."}, {"field": "AllowedHTASources", "description": "Whitelist of domains/paths from which legitimate HTAs are executed."}, {"field": "TimeWindow", "description": "Time threshold for correlating mshta.exe execution with subsequent network connections or file creations."}]', '2026-05-01 15:26:36.732213');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1594, 'AN0901', 'Analytic 0901', 'Adversaries create SaaS accounts via admin dashboards or integrations (e.g., Zoom, Salesforce, Slack). Monitor lifecycle.create or account provisioning events from non-standard sources or times.', '{SaaS}', 'x-mitre-analytic--e619c27e-3d57-489c-8ce9-cbb5f0c195bd', 'DET0319', '[{"name": "saas:zoom", "channel": "New user created", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}]', '[{"field": "ApplicationScope", "description": "Trigger only for high-privilege or sensitive applications"}, {"field": "AdminUserList", "description": "Compare actor to list of approved SaaS administrators"}]', '2026-05-01 15:26:36.73349');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1595, 'AN0995', 'Analytic 0995', 'Detection of processes launching downgraded PowerShell versions (e.g., v2) or other legacy binaries that lack logging or security features. Correlates command-line arguments, process metadata, and version fields. Monitors registry changes to Defender or HVCI keys that could indicate intentional downgrades.', '{Windows}', 'x-mitre-analytic--e61d2099-1517-4bf4-b2e6-6e61cdf94be3', 'DET0350', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "AllowedInterpreterVersions", "description": "Defines which versions of interpreters like PowerShell are permitted in the environment."}, {"field": "RegistryDefenderKeys", "description": "Specific registry paths for monitoring Defender/HVCI configurations that may vary by Windows version."}]', '2026-05-01 15:26:36.734756');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1596, 'AN0043', 'Analytic 0043', 'Detects virtual disk expansion or file copy operations to cloud buckets or mounted volumes from isolated instances.', '{IaaS}', 'x-mitre-analytic--e622500c-4217-466c-955c-82ef3217653a', 'DET0014', '[{"name": "AWS:CloudTrail", "channel": "GetObject, CopyObject", "x_mitre_data_component_ref": "x-mitre-data-component--58ef998c-f3bf-4985-b487-b1005f5c05d1"}, {"name": "gcp:audit", "channel": "Write operations to storage", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "CloudBucketList", "description": "Staging bucket or mount point for data"}, {"field": "InstanceTag", "description": "Behavior restricted to specific ephemeral instances"}, {"field": "ObjectWriteThreshold", "description": "Volume or size of files pushed in burst"}]', '2026-05-01 15:26:36.736033');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1604, 'AN0622', 'Analytic 0622', 'Abuse of mmc.exe to execute non-Microsoft or user-staged .msc files and malicious COM CLSIDs. Behavioral chain: (1) suspicious mmc.exe invocation with /a or -Embedding and non-standard .msc path → (2) COM activation of non-baseline CLSIDs by mmc.exe → (3) mmc.exe loads non-baseline DLLs (user-writable/UNC/unsigned) → (4) optional network/DNS activity from mmc.exe.', '{Windows}', 'x-mitre-analytic--e6f38f76-4e60-4b8a-881c-5d3f206e912c', 'DET0222', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Microsoft-Windows-COM/Operational", "channel": "CLSID activation events where ProcessName=mmc.exe and CLSID not in allowed baseline", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TimeWindow", "description": "Correlation window (e.g., 5–10 minutes) tying .msc creation → mmc.exe start → module loads → COM/net activity."}, {"field": "AllowedMSCList", "description": "Set of Microsoft-supplied .msc names/paths allowed in the environment to suppress noise."}, {"field": "SuspiciousMSCPathRegex", "description": "Regex for user-writable and network paths indicating risky .msc staging (Users, AppData, Downloads, Desktop, UNC)."}, {"field": "AllowedCLSIDs", "description": "Baseline of CLSIDs expected to be activated by mmc.exe; alert on unknown/new."}, {"field": "ParentProcessAllowList", "description": "Expected parents for mmc.exe (explorer.exe, services) vs. unusual (powershell, wscript, office apps)."}, {"field": "SignedToUnsignedTransition", "description": "Flag when signed mmc.exe results in loading unsigned DLLs."}, {"field": "ExternalIPAllowlist", "description": "Approved external ranges/domains to exclude when mmc.exe makes network requests."}]', '2026-05-01 15:26:36.7492');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1597, 'AN1116', 'Analytic 1116', 'Office-based persistence via Office template macros, Outlook forms/rules/homepage, or registry-persistent scripts. Adversary modifies registry keys or Office application directories to load malicious scripts at startup.', '{Windows}', 'x-mitre-analytic--e643c4aa-dc7d-43d9-b36e-f13d733f8e9a', 'DET0398', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Application", "channel": "Outlook rule creation, form load, or homepage redirection", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ParentProcessName", "description": "Tune based on expected Office process tree (e.g., WINWORD.EXE spawning cmd.exe)"}, {"field": "RegistryPath", "description": "Specific keys related to Office startup such as Outlook Today, AddIns, or Template Macros"}, {"field": "TimeWindow", "description": "Window of process execution after user login or Outlook launch"}, {"field": "UserContext", "description": "Detect persistence within high-value user mailboxes (e.g., admin, finance, C-suite)"}]', '2026-05-01 15:26:36.737305');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1598, 'AN0777', 'Analytic 0777', 'Unexpected firmware image uploads via TFTP/FTP/SCP. Configuration changes modifying boot image pointers. Logs showing boot variable redirection to non-standard images. Anomalous reboots immediately following firmware changes not tied to patch schedules.', '{"Network Devices"}', 'x-mitre-analytic--e64aebfd-8343-45ec-bdce-6681a8255637', 'DET0278', '[{"name": "networkdevice:config", "channel": "Boot variable modified to point to non-standard or unsigned image", "x_mitre_data_component_ref": "x-mitre-data-component--b9d031bb-d150-4fc6-8025-688201bf3ffd"}, {"name": "networkdevice:firmware", "channel": "Unexpected firmware image upload events via TFTP/FTP/SCP", "x_mitre_data_component_ref": "x-mitre-data-component--4dcd8ba3-2075-4f8b-941e-39884ffaac08"}]', '[{"field": "ApprovedFirmwareHashes", "description": "Known good firmware image hashes allowed for boot."}, {"field": "MaintenanceWindows", "description": "Timeframes during which firmware updates are expected."}]', '2026-05-01 15:26:36.73875');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1599, 'AN2028', 'Analytic 2028', 'Once adversaries leverage the web service as infrastructure (ex: for command and control), it may be possible to look for unique characteristics associated with adversary software, if known.(Citation: ThreatConnect Infrastructure Dec 2020) Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle, such as during Command and Control ([Web Service](https://attack.mitre.org/techniques/T1102)) or [Exfiltration Over Web Service](https://attack.mitre.org/techniques/T1567).', '{PRE}', 'x-mitre-analytic--e6500f0c-41bd-4e04-ad9d-4a3121803175', 'DET0896', '[{"name": "Internet Scan", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--0dcbbf4f-929c-489a-b66b-9b820d3f7f0e"}]', NULL, '2026-05-01 15:26:36.740367');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1600, 'AN0066', 'Analytic 0066', 'Detection of unpacking behavior through abnormal memory allocation, followed by executable code injection and execution from non-image sections.', '{Windows}', 'x-mitre-analytic--e6a7eeb3-0652-460c-b68b-f17d2ed82822', 'DET0023', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ParentProcessName", "description": "To scope detections to suspicious parent-child process relationships typical of loaders or droppers."}, {"field": "AllocationSizeThreshold", "description": "To tune for unusually large virtual memory allocations that might indicate unpacked payloads."}]', '2026-05-01 15:26:36.741964');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1601, 'AN0852', 'Analytic 0852', 'Application crash or repeated restart cycle triggered by malformed input or exploit file, observed via unified logs and process crash monitoring.', '{macOS}', 'x-mitre-analytic--e6b92e19-5bc8-414b-b200-96ed6d286388', 'DET0304', '[{"name": "macos:unifiedlog", "channel": "Crash log entries for a process receiving malformed input or known exploit patterns", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "macos:unifiedlog", "channel": "Unusual child process tree indicating attempted recovery after crash", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CrashSignature", "description": "Binary crash hash or affected dylib for distinguishing malicious faults from benign ones"}, {"field": "InputVector", "description": "File, IPC, or network-based input that may be triggering exploitation (e.g., PDF file, POST request)"}]', '2026-05-01 15:26:36.744503');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1602, 'AN0464', 'Analytic 0464', 'Process opens /dev/bpf* (libpcap) or loads NetworkExtension filter, then after a crafted inbound packet the same process initiates an outbound connection to the trigger origin.', '{macOS}', 'x-mitre-analytic--e6d04b50-7bdc-480e-9bda-291db9b270f6', 'DET0162', '[{"name": "OpenBSM:AuditTrail", "channel": "open/openat of /dev/bpf*; ioctl BIOCSETF-like operations.", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "First outbound connection from the same PID/user shortly after an inbound trigger.", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Inbound one-off packet to uncommon port → outbound SF to same src_ip within TimeWindow.", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "BPFDevicePath", "description": "Alternate BPF device paths if customized (default /dev/bpf*)."}, {"field": "DeveloperMode", "description": "Relax thresholds on known developer tooling hosts (Xcode, instrumenting tools)."}]', '2026-05-01 15:26:36.746305');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1603, 'AN1394', 'Analytic 1394', 'Detection of command-line activity exhibiting syntactic obfuscation patterns, such as excessive escape characters, base64 encoding, command concatenation, or outlier command length and entropy.', '{Windows}', 'x-mitre-analytic--e6e98024-2fa7-444c-af90-32ec5d4d2666', 'DET0505', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLineEntropyThreshold", "description": "Used to flag base64 or token-heavy command-line strings"}, {"field": "SuspiciousCharacterCount", "description": "Escape character and symbol frequency in command-line strings"}, {"field": "TimeWindow", "description": "Window between command execution and follow-up child or file write behavior"}]', '2026-05-01 15:26:36.747764');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1605, 'AN1318', 'Analytic 1318', 'Cause→effect chain in cloud consoles: (1) user clicks link then invokes instance/image creation via API, (2) instance/image originates from external AMI or unknown image, (3) instance immediately egresses or retrieves payloads.', '{IaaS}', 'x-mitre-analytic--e707cd33-8e20-4b1d-ad3f-fd3a3233fcdd', 'DET0478', '[{"name": "AWS:CloudTrail", "channel": "RunInstances,CreateImage", "x_mitre_data_component_ref": "x-mitre-data-component--b5b0e8ae-7436-4951-950a-7b83c4dd3f2c"}, {"name": "AWS:CloudTrail", "channel": "StartInstances", "x_mitre_data_component_ref": "x-mitre-data-component--f8213cde-6b3a-420d-9ab7-41c9af1a919f"}, {"name": "gcp:vpcflow", "channel": "first 5m egress to unknown ASNs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ApprovedImages", "description": "AMI/image allow-list with owners."}, {"field": "UserContext", "description": "High-risk identities (federated, external IdP)."}, {"field": "TimeWindow", "description": "5–30 minutes from console/API action to network egress."}]', '2026-05-01 15:26:36.750712');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1606, 'AN0659', 'Analytic 0659', 'Detection of edits or additions to /etc/rc.common, /Library/StartupItems, or /System/Library/StartupItems and associated script execution during login or reboot.', '{macOS}', 'x-mitre-analytic--e716b209-5b06-4bc4-843f-cbe4c51ddc0d', 'DET0237', '[{"name": "macos:unifiedlog", "channel": "process events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "fs:fsusage", "channel": "file activity", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "script_name", "description": "Name of script or LaunchDaemon plist is tunable across environments"}, {"field": "event_interval", "description": "Time window between modification and reboot/login"}, {"field": "file_permission", "description": "Permissions on modified RC files can vary between systems"}]', '2026-05-01 15:26:36.752004');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1607, 'AN1464', 'Analytic 1464', 'Execution of PubPrn.vbs via cscript.exe using the ''script:'' moniker to load and execute a remote .sct scriptlet file, bypassing signature validation and proxying remote payloads through a signed Microsoft script host.', '{Windows}', 'x-mitre-analytic--e7444be7-3c0a-4ff2-927d-f623af05936d', 'DET0528', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "CommandLineRegex", "description": "Detects ''script:'' moniker with HTTP/HTTPS URI as argument to pubprn.vbs"}, {"field": "ParentProcessName", "description": "May vary between cscript.exe, wscript.exe, or cmd.exe depending on execution method"}, {"field": "NetworkDestinationDomain", "description": "Used to detect external domains being contacted for remote scriptlet execution"}, {"field": "TimeWindow", "description": "Maximum allowed time delta between pubprn.vbs invocation and network connection or child process"}]', '2026-05-01 15:26:36.753203');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1608, 'AN1205', 'Analytic 1205', 'Correlates Office 365 or Google Workspace audit logs for spoofed sender addresses, failed email authentication, and anomalies in message delivery metadata. Defender observes failed SPF/DKIM checks and domain mismatches tied to suspicious campaigns.', '{"Office Suite"}', 'x-mitre-analytic--e7a0e155-e0bc-45b5-b0ef-98ec4f5eea63', 'DET0431', '[{"name": "saas:email", "channel": "AuthenticationFailures (SPF/DKIM/DMARC) OR Domain Mismatch", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MessageVolumeThreshold", "description": "Defines thresholds for spoofed messages volume before alerts trigger, reducing noise for isolated misconfigs."}, {"field": "TargetedUserGroups", "description": "Restricts higher-sensitivity detection to high-value groups (executives, admins, finance) for efficiency."}]', '2026-05-01 15:26:36.754468');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1609, 'AN0055', 'Analytic 0055', 'Executable or script payloads lacking symbol information and readable strings that are created or dropped by unusual or short-lived processes.', '{Windows}', 'x-mitre-analytic--e7b2c8da-d54d-446a-a7f6-062fe234a8cc', 'DET0019', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "EDR:file", "channel": "File Metadata Inspection (Low String Entropy, Missing PDB)", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "EntropyThreshold", "description": "Payloads with extremely low string entropy may indicate stripped or obfuscated binaries"}, {"field": "ParentProcessName", "description": "Used to scope or whitelist common system builders, compilers, or admin tools"}, {"field": "TimeWindow", "description": "Correlates file creation and process spawning within a short timeframe"}]', '2026-05-01 15:26:36.755952');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1610, 'AN0651', 'Analytic 0651', 'Detect the creation or modification of common media file formats (e.g., .jpg, .png, .wav) following suspicious process activity like compression or encryption, especially when paired with lateral movement or exfiltration behavior.', '{Windows}', 'x-mitre-analytic--e7be37f1-88f9-45e3-91d0-1ff37bc94892', 'DET0235', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "Session Transfer Content", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "FileExtensionFilter", "description": "Allows tuning of monitored file types (e.g., .jpg, .png, .docx)."}, {"field": "PayloadEntropyThreshold", "description": "Threshold for flagging potential hidden data in outbound payloads."}, {"field": "ExecutionToExfilTimeWindow", "description": "Time window between media creation and network transmission."}]', '2026-05-01 15:26:36.757585');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1624, 'AN1975', 'Analytic 1975', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1611, 'AN0954', 'Analytic 0954', 'Use of stolen Kerberos tickets or token impersonation resulting in logon sessions from accounts without expected interactive logon events.', '{Windows}', 'x-mitre-analytic--e7ce6bda-a4d3-43a4-afa0-34d57c34ef0d', 'DET0338', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Allows tuning of how far apart related logon and process events can be correlated"}, {"field": "UserContext", "description": "Customize for high-value or service accounts with restricted access policies"}]', '2026-05-01 15:26:36.75914');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1612, 'AN0563', 'Analytic 0563', 'CLI-based execution of interface and routing discovery commands (e.g., `show ip interface`, `show arp`, `show route`) over Telnet, SSH, or console.', '{"Network Devices"}', 'x-mitre-analytic--e7debe02-4326-48ae-aa22-59c2a847d3e7', 'DET0195', '[{"name": "networkdevice:cli", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "Username", "description": "Highlight low-privileged or non-routine users performing discovery"}, {"field": "CommandString", "description": "Allow for tuning based on command regex or frequency"}, {"field": "TransportType", "description": "SSH vs Telnet vs Console session logging scope"}]', '2026-05-01 15:26:36.760593');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1613, 'AN2034', 'Analytic 2034', 'Detects consent grants, password resets, role changes, external sharing, or token creation shortly after user interaction with messages, invites, or help desk workflows. Emphasis is placed on unusual requester relationships, new device context, or off-hours approvals.', '{SaaS}', 'x-mitre-analytic--e817eb45-0830-476d-9fd7-8e8acb14af8a', 'DET0899', '[{"name": "saas:okta", "channel": "user.account.reset_password; user.mfa.factor.activate; app.oauth2.authorize", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "saas:slack", "channel": "xternal DM or workspace invite preceding credential or approval actions", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "saas:zoom", "channel": "Unexpected contact interaction preceding follow-on admin requests", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "RequesterNoveltyDays", "description": "How long since requestor last interacted with user"}, {"field": "GeoVelocityThreshold", "description": "Distance/time anomaly for follow-on login"}, {"field": "AfterHoursDefinition", "description": "Organization-specific off-hours period"}]', '2026-05-01 15:26:36.761794');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1614, 'AN1600', 'Analytic 1600', 'Curl, wget, or custom HTTP clients initiated by uncommon user accounts or cron jobs to popular web services, with no observed response parsing logic.', '{Linux}', 'x-mitre-analytic--e83afa89-0ec1-49e7-b351-eef67b085480', 'DET0581', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "iptables:LOG", "channel": "OUTBOUND", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ParentProcess", "description": "May tune to detect unknown parents like custom scripts or reverse shells"}, {"field": "CommandLineArgs", "description": "May adjust based on known curl/wget C2 behaviors"}]', '2026-05-01 15:26:36.763027');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1615, 'AN1133', 'Analytic 1133', 'Monitor Windows Registry modifications to Winlogon keys (Shell, Userinit, Notify) that introduce new executable or DLL paths. Correlate these changes with subsequent DLL loading, image loads, or process creation originating from winlogon.exe or userinit.exe. Abnormal child process lineage or unauthorized binaries in C:\Windows\System32 may indicate abuse.', '{Windows}', 'x-mitre-analytic--e8569cdc-a018-4eee-95d9-5979cebae519', 'DET0404', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "modification to Winlogon registry keys such as Shell, Notify, or Userinit", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "Autoruns:RegistryScan", "channel": "Enumerate Winlogon subkeys for unknown or unsigned binaries", "x_mitre_data_component_ref": "x-mitre-data-component--ed0dd8aa-1677-4551-bb7d-8da767617e1b"}]', '[{"field": "TimeWindow", "description": "Time correlation between registry modification and malicious module load or process creation"}, {"field": "UserContext", "description": "Privilege level or user context under which registry changes or process executions occur"}, {"field": "BinarySignatureValidation", "description": "Whether to validate binary signatures when DLLs are loaded via Winlogon helper paths"}, {"field": "ExecutablePathScope", "description": "Scope of directories considered suspicious for helper DLLs (e.g., temp paths, non-System32 locations)"}]', '2026-05-01 15:26:36.765282');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1616, 'AN0007', 'Analytic 0007', 'Adversary with access to domain management tools (e.g., `realmd`, `samba-tool`, `ldapmodify`) creates a new domain user via command-line utilities. Behavior chain: LDAP command or script triggers → user entry added in AD via Kerberos/LDAP traffic.', '{Linux}', 'x-mitre-analytic--e86081ab-aad1-48a1-abd8-5a5c8c7c936a', 'DET0003', '[{"name": "auditd:SYSCALL", "channel": "execution of realmd, samba-tool, or ldapmodify with user-related arguments", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "TGS-REQ and AS-REQ seen for new user shortly after domain-modifying process", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "DomainToolUsed", "description": "realmd, samba-tool, ldapmodify or custom script"}, {"field": "TrafficWindow", "description": "Expected Kerberos traffic from new domain account within X minutes of command"}, {"field": "SessionType", "description": "Script execution from interactive shell vs scheduled task"}]', '2026-05-01 15:26:36.766539');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1632, 'AN1163', 'Analytic 1163', 'Access of mounted cloud shares or document repositories via browser, terminal, or Finder by users not typically interacting with those resources. Includes script-based enumeration or mass download.', '{macOS}', 'x-mitre-analytic--eac7b88d-0ee2-4fbf-9e0b-ea73c376ccb3', 'DET0413', '[{"name": "macos:unifiedlog", "channel": "access to /Volumes/SharePoint or network mount", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "curl, python scripts, rsync with internal share URLs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AccessedMountPath", "description": "Paths to sensitive volumes may differ based on org setup."}, {"field": "UserGroup", "description": "Expected user groups that typically access shared data."}]', '2026-05-01 15:26:36.788493');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1617, 'AN1032', 'Analytic 1032', 'Correlation of Registry key creation/modification events under known Run/Startup keys with new or unusual binary paths or script-based payloads. Multi-event detection includes registry modification followed by process execution from non-standard directories or abnormal parent-child process relationships.', '{Windows}', 'x-mitre-analytic--e863e865-8ecc-47ce-b736-eec54b6399d6', 'DET0365', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Microsoft-Windows-Shell-Core", "channel": "New startup folder shortcut or binary placed in Startup directory", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ImagePath", "description": "Full path of the binary/script being registered in Run keys. Tunable to exclude known software baselines."}, {"field": "RegistryKeyPath", "description": "Tunable list of startup-related registry keys to monitor more/less aggressively based on enterprise software context."}, {"field": "TimeWindow", "description": "Correlate registry key creation and process execution within this window. Defaults between 5–10 minutes."}, {"field": "UserContext", "description": "Filter for specific user SIDs or exclude known admin/script accounts."}]', '2026-05-01 15:26:36.767792');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1618, 'AN1536', 'Analytic 1536', 'Registry key modification to AppInit_DLLs value followed by anomalous DLL loading by processes importing user32.dll, especially unsigned or uncommon DLLs, suggesting unauthorized AppInit persistence or privilege escalation.', '{Windows}', 'x-mitre-analytic--e886b9c8-2187-4363-9043-1e5c60d75363', 'DET0557', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "ImagePathWhitelist", "description": "Paths or filenames of known-good DLLs to exclude from alerting"}, {"field": "UserContext", "description": "Context of the user modifying the registry key (e.g., admin vs standard user)"}, {"field": "TimeWindow", "description": "Temporal threshold for correlating registry modification and DLL load"}, {"field": "DLLSignatureStatus", "description": "Filter or flag unsigned or suspiciously signed DLLs"}]', '2026-05-01 15:26:36.76902');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1619, 'AN0640', 'Analytic 0640', 'CLI-based or API-based network call from the hypervisor to external staging host, shortly followed by a connection to a second external IP by a spawned process or scheduled task.', '{ESXi}', 'x-mitre-analytic--e8c91885-736e-4348-ba09-2acfbdd8b176', 'DET0228', '[{"name": "esxi:hostd", "channel": "CLI network calls", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "esxi:cron", "channel": "process or cron activity", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ScheduledTaskName", "description": "Detect unknown or obfuscated task names launching follow-up stages"}, {"field": "DestinationIP", "description": "Scope multiple IP destinations outside corporate ranges in short sequence"}]', '2026-05-01 15:26:36.770473');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1620, 'AN0611', 'Analytic 0611', 'Abuse of DYLD_INSERT_LIBRARIES or hijacking framework paths for malicious libraries. Defender observes processes invoking abnormal dylibs, modified plist files, or persistence entries pointing to altered binaries.', '{macOS}', 'x-mitre-analytic--e8fc16bf-6654-4912-96c9-208e4c5bbaa6', 'DET0218', '[{"name": "macos:unifiedlog", "channel": "Execution of process with DYLD_INSERT_LIBRARIES set", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "Modified application plist or binary replacement in /Applications", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Dylib loaded from abnormal location", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "AllowedDylibPaths", "description": "Baseline directories for dylib loading."}, {"field": "PlistMonitors", "description": "Specific plist files used for persistence monitoring."}]', '2026-05-01 15:26:36.771664');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1621, 'AN1469', 'Analytic 1469', 'Addition of credentials (keys, app passwords, x.509 certs) to existing cloud accounts, service principals, or OAuth apps via portal or API by non-standard identities or IP ranges.', '{"Identity Provider"}', 'x-mitre-analytic--e95d8309-8435-4c32-9ac3-38e350c170c5', 'DET0531', '[{"name": "azure:audit", "channel": "Add service principal credentials, app password added, app role assignment", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "MFABypassMechanism", "description": "App password or legacy auth activity bypassing MFA policies."}, {"field": "SourceIPAllowlist", "description": "Expected IPs allowed to perform admin identity operations."}, {"field": "ApplicationCredentialType", "description": "Track types like `client_secret`, `certificate`, `password`, `federated`."}]', '2026-05-01 15:26:36.773388');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1622, 'AN0730', 'Analytic 0730', 'Use unified logs to detect unusual DNS responses correlated with subsequent connections to calculated or non-standard ports. Monitor non-browser apps making repeated outbound connections that deviate from expected patterns.', '{macOS}', 'x-mitre-analytic--e95ed4e2-d6bc-4a6f-acbc-bdbfcbaca158', 'DET0262', '[{"name": "macos:unifiedlog", "channel": "DNS responses followed by connections to ports outside standard ranges", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "macos:unifiedlog", "channel": "Unexpected processes making network calls based on DNS-derived ports", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ProcessAllowlist", "description": "Expected processes allowed to open non-standard ports (e.g., developer tools)"}, {"field": "ConnectionVolumeThreshold", "description": "Volume of unusual connections needed before flagging as suspicious"}]', '2026-05-01 15:26:36.775233');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1623, 'AN0453', 'Analytic 0453', 'Detect anomalous OAuth or SSO logins that repeatedly generate MFA challenges, particularly where MFA approvals are denied or timed out by the user.', '{SaaS}', 'x-mitre-analytic--e96b0210-f7d5-43ac-bf73-893f243f6015', 'DET0160', '[{"name": "saas:okta", "channel": "MFAChallengeIssued", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "MFAProvider", "description": "Identify which MFA service provider logs are in use (Okta, Duo, Microsoft Authenticator)"}]', '2026-05-01 15:26:36.77684');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1625, 'AN0631', 'Analytic 0631', 'Detects when a script or binary is named with misleading or benign-looking extensions (.jpg, .doc) and is then executed via command line or a scheduled task. Includes ELF header mismatches and content-type inconsistencies on disk.', '{Linux}', 'x-mitre-analytic--e9ba7101-369f-48c6-8e6d-075ddd5744ba', 'DET0226', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:osquery", "channel": "Read headers and detect MIME type mismatch", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "benign_extensions", "description": "Linux-targeted masquerade extensions (.jpg, .pdf, .png)"}, {"field": "HeaderInspectionEnabled", "description": "Whether to parse file signatures or MIME types from file headers"}, {"field": "ExecPathScope", "description": "Monitored directory scope for adversarial execution (e.g., /tmp/, /home/username/Downloads)"}]', '2026-05-01 15:26:36.779735');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1626, 'AN0238', 'Analytic 0238', 'Detection of suspicious use of shell utilities or scripts that decode or decrypt a payload and execute it without writing to disk.', '{Linux}', 'x-mitre-analytic--e9de9003-46e9-438f-929a-94a33c2eb5bd', 'DET0087', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "UserContext", "description": "Normal usage of `base64`, `openssl`, or `gpg` varies by user/role."}, {"field": "ProcessLineage", "description": "Parent-child process chains may differ across deployments."}, {"field": "TimeWindow", "description": "Time between decode and execution is implementation-specific."}]', '2026-05-01 15:26:36.78101');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1627, 'AN0041', 'Analytic 0041', 'Detects script or user activity copying files to a central temp or /mnt directory followed by archive/compression utilities.', '{Linux}', 'x-mitre-analytic--e9ee76c8-e959-4925-8f93-4b8fb66bc9f1', 'DET0014', '[{"name": "auditd:SYSCALL", "channel": "creat", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "StagingDirectoryList", "description": "e.g., /tmp/, /var/tmp/, /mnt/"}, {"field": "ArchivingCommandPatterns", "description": "grep for ''tar'', ''zip'', ''gzip'', ''7z''"}, {"field": "UserContext", "description": "Interactive or elevated shells running archiving commands"}]', '2026-05-01 15:26:36.782244');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1628, 'AN0118', 'Analytic 0118', 'Detects abuse of verclsid.exe to execute COM objects by monitoring process creation, CLSID arguments, DLLs or scriptlet engines loaded into memory, and If the CLSID points to remote SCT/HTA content, verclsid.exe makes outbound connections.', '{Windows}', 'x-mitre-analytic--e9f451b7-1b9e-420e-983a-3442547b7180', 'DET0042', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "AllowedCLSIDs", "description": "Baseline CLSIDs frequently invoked by verclsid.exe in normal shell extension verification."}, {"field": "ParentProcessFilter", "description": "Unusual parents (e.g., winword.exe, excel.exe) spawning verclsid.exe should be treated as suspicious."}, {"field": "TimeWindow", "description": "Correlation window between verclsid.exe start, module load, and network activity."}, {"field": "ExternalIPRange", "description": "Restrict detection to external IPs not in approved ranges to cut noise."}]', '2026-05-01 15:26:36.78348');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1629, 'AN1440', 'Analytic 1440', 'Detects suspicious use of PowerShell, .NET, or script interpreters to spawn processes that mimic UAC prompts, often with credential capture dialogue boxes invoked from non-standard parent processes.', '{Windows}', 'x-mitre-analytic--ea127140-2f66-4c3d-93ab-215c210ad6c5', 'DET0521', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandLine", "description": "Tunable to detect suspicious prompts like ''Enter your password'' or ''CredentialRequired''"}, {"field": "ParentProcessName", "description": "Tune to flag UI prompts spawned from unexpected processes like cmd.exe or user scripts"}, {"field": "TimeWindow", "description": "Scope correlation of script execution and prompt appearance"}]', '2026-05-01 15:26:36.78468');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1630, 'AN1507', 'Analytic 1507', 'Installation of malicious IIS/Apache/SQL server modules that later execute command-line interpreters or establish outbound connections.', '{Windows}', 'x-mitre-analytic--ea250997-091b-4c5e-8827-a41f03e34caf', 'DET0547', '[{"name": "WinEventLog:Security", "channel": "EventCode=4698", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Application", "channel": "Unusual DLL/plugin registration for IIS/SQL/Apache or unexpected error logs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TimeWindow", "description": "Time delta between module install and process execution (e.g., persistence delay)."}, {"field": "ParentProcessName", "description": "Custom server wrapper processes or renamed webserver processes may require tuning."}]', '2026-05-01 15:26:36.785883');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1631, 'AN0062', 'Analytic 0062', 'Adversary executes systemctl or service stop targeting high-value services (e.g., mysql, sshd), possibly followed by rm or shred against data stores. Behavioral chain: sudo/su usage + stop command + /var/log/messages or syslog entries + file access/delete.', '{Linux}', 'x-mitre-analytic--ea793457-89e6-47d2-8ae1-7fd2bd814f82', 'DET0021', '[{"name": "auditd:SYSCALL", "channel": "execve of systemctl or service stop", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "unlink/unlinkat on service binaries or data targets", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}, {"name": "linux:syslog", "channel": "service stopped messages", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "TimeWindow", "description": "Window between service stop and suspicious file deletion"}, {"field": "ExecUser", "description": "Username or UID executing service stop command"}]', '2026-05-01 15:26:36.787159');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1633, 'AN1086', 'Analytic 1086', 'A process or terminal command outside of standard shell utilities reads the user''s .bash_history file. On macOS, unified logs or telemetry tools like EndpointSecurity (ESF) may observe file read APIs or terminal process lineage that shows non-user-initiated access.', '{macOS}', 'x-mitre-analytic--ead38dff-ee26-477d-be5a-69b52dc8bd50', 'DET0385', '[{"name": "macos:endpointsecurity", "channel": "open or read syscall to ~/.bash_history", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:unifiedlog", "channel": "non-shell process tree accessing bash history", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "ParentProcessCheck", "description": "Scope access to .bash_history only if parent is not Terminal.app or bash/zsh"}, {"field": "AccessFrequency", "description": "Raise priority if .bash_history is accessed multiple times in short window"}]', '2026-05-01 15:26:36.791322');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1634, 'AN1458', 'Analytic 1458', 'Detects adversarial archiving of files prior to exfiltration by correlating execution of compression/encryption utilities (e.g., makecab.exe, rar.exe, 7z.exe, powershell Compress-Archive) with subsequent creation of large compressed or encrypted files. Identifies abnormal process lineage involving crypt32.dll usage, command-line arguments invoking compression switches, and file write operations to temporary or staging directories.', '{Windows}', 'x-mitre-analytic--eaeb2a44-eebe-41f3-875a-a34abdc03252', 'DET0526', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "ArchiveExtensions", "description": "List of file extensions treated as suspicious when created outside of expected paths."}, {"field": "ProcessAllowlist", "description": "Known business processes permitted to use compression/encryption utilities."}, {"field": "FileSizeThresholdMB", "description": "Minimum file size for flagging archive creation to reduce noise from benign small compressions."}]', '2026-05-01 15:26:36.793101');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1635, 'AN1274', 'Analytic 1274', 'Detects anomalous network traffic on UDP 5355 (LLMNR) and UDP 137 (NBT-NS) combined with unauthorized SMB relay attempts, registry modifications re-enabling multicast name resolution, or suspicious service creation indicative of adversary-in-the-middle credential interception.', '{Windows}', 'x-mitre-analytic--eb031858-bf91-476e-8248-2c54ef0f0864', 'DET0462', '[{"name": "WinEventLog:Security", "channel": "EventCode=4697", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Security", "channel": "Registry key modification HKLM\\Software\\Policies\\Microsoft\\Windows NT\\DNSClient\\EnableMulticast", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "NSM:Flow", "channel": "Unusual responses to LLMNR (UDP 5355) or NBT-NS (UDP 137) queries from unauthorized hosts", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "Abnormal SMB authentication attempts correlated with poisoned LLMNR/NBT-NS sessions", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "TrustedResponderList", "description": "Defines expected LLMNR/NBT-NS responders to tune out legitimate services."}, {"field": "TimeWindow", "description": "Correlation period for linking poisoned name resolution with SMB relay attempts."}, {"field": "SMBServiceBaseline", "description": "Normal services and SMB relay patterns in the enterprise environment."}]', '2026-05-01 15:26:36.794538');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1636, 'AN0766', 'Analytic 0766', 'Observes creation or modification of LaunchAgent/LaunchDaemon property list files combined with anomalous plist payload execution after user logon', '{macOS}', 'x-mitre-analytic--eb0d78b0-f35d-49db-a8a5-d3cf840db6fd', 'DET0274', '[{"name": "macos:unifiedlog", "channel": "Observed loading of new LaunchAgent or LaunchDaemon plist", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "macos:unifiedlog", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:unifiedlog", "channel": "Execution of binary listed in newly modified LaunchAgent plist", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PlistKey", "description": "Organizations may use specific keys or additional payload parameters"}, {"field": "TimeWindow", "description": "Tunable based on expected delay between plist write and execution"}]', '2026-05-01 15:26:36.796225');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1637, 'AN0270', 'Analytic 0270', 'Role escalation (e.g., Editor → Owner) in cloud collaboration tools (Google Workspace, O365) or file sharing apps to maintain elevated access.', '{SaaS}', 'x-mitre-analytic--eb4a55f0-eff2-40f8-912e-43ba7e34603c', 'DET0096', '[{"name": "m365:unified", "channel": "Admin Activity > Role Change or Sharing Change", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "SharingSensitivityLabel", "description": "Threshold for labeling sensitive document access escalation."}, {"field": "CrossOrgChanges", "description": "Track changes made across organizational boundaries (e.g., guest users)."}]', '2026-05-01 15:26:36.797588');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1638, 'AN0333', 'Analytic 0333', 'Detects manipulation of PNG, JPG, or GIF files by user-initiated scripts followed by script execution or exfiltration behavior, especially from `osascript`, `python`, or `bash`, in combination with LaunchAgent persistence or curl activity.', '{macOS}', 'x-mitre-analytic--eb5334b4-8a19-4efd-a225-44a2783c6d39', 'DET0119', '[{"name": "macos:osquery", "channel": "file_events", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "network connection events", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "StegoToolNamePatterns", "description": "Adapt to known or emerging tools using stego methods on macOS (e.g., `Invoke-PSImage`, `stegsolve`)"}, {"field": "ParentScriptSources", "description": "Update list of trusted versus unknown scripting hosts launching activity tied to image handling"}]', '2026-05-01 15:26:36.79879');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1639, 'AN1516', 'Analytic 1516', 'A process (non-system or user-initiated) accesses private key files in user profile paths or system certificate stores followed by potential network connections or compression activity.', '{Windows}', 'x-mitre-analytic--eb569d45-a5b6-47df-a098-bdb26ef0597f', 'DET0549', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=5145", "x_mitre_data_component_ref": "x-mitre-data-component--f5468e67-51c7-4756-9b4f-65707708e7fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "FilePathRegex", "description": "Regex for matching key file extensions (.pem, .pfx, .ppk, etc.) or known certificate directories like C:\\Users\\*\\.ssh\\"}, {"field": "ParentProcessName", "description": "Set of known benign certificate management tools to exclude (e.g., certutil.exe, ssh.exe)"}]', '2026-05-01 15:26:36.800093');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1640, 'AN0653', 'Analytic 0653', 'Abnormal usage of Preview, ImageMagick, or binary editors to alter images/documents, followed by exfiltration or outbound connections with mismatched file MIME types or payload structure.', '{macOS}', 'x-mitre-analytic--eb6edb6d-9684-4ef7-96b2-13c087276d80', 'DET0235', '[{"name": "macos:unifiedlog", "channel": "File creation", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "macos:osquery", "channel": "process_events", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "C2 exfiltration", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ParentProcessBaseline", "description": "Allow tuning based on expected apps calling image-editing tools."}, {"field": "TimeDelta", "description": "Gap between file manipulation and outbound connection."}]', '2026-05-01 15:26:36.801328');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1641, 'AN1141', 'Analytic 1141', 'Spoofed outbound packets sent to amplification services from command-line tools or scripts, combined with abnormal outbound packet volume on known reflector ports', '{Linux}', 'x-mitre-analytic--eb7692b0-5592-4d23-ba06-fdded48a2a0d', 'DET0408', '[{"name": "auditd:SYSCALL", "channel": "Execution of spoofing tools (e.g., hping3, nping, scapy) sending UDP packets to known amplifier ports", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "Outbound UDP floods targeting common reflection services with spoofed IP headers", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "sar:network", "channel": "Outbound network saturation with minimal process activity", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "TimeWindow", "description": "Sliding interval for detecting volumetric anomalies"}, {"field": "AmplificationProtocolList", "description": "Which protocols to watch (e.g., DNS, NTP, SSDP, Memcached)"}, {"field": "ExecutionToolList", "description": "Set of binaries and scripts commonly abused for spoofing/reflection"}]', '2026-05-01 15:26:36.802479');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1642, 'AN1082', 'Analytic 1082', 'Identifies use of sh/bash/zsh in suspicious context, such as user scripts launched from non-standard apps (e.g., Preview.app), embedded in LaunchDaemons, or executed outside Terminal.app. Looks for misuse in Automator, LaunchAgents, or NSAppleScript-executed shell.', '{macOS}', 'x-mitre-analytic--ebd61e14-852c-403b-8b50-7e15a1c32d05', 'DET0384', '[{"name": "macos:unifiedlog", "channel": "log stream --predicate ''eventMessage contains \"exec\"''", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "launchd + process_events", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:syslog", "channel": "system.log, asl.log", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "ScriptLocation", "description": "Execution from /Users/Shared, ~/Library/LaunchAgents, /tmp."}, {"field": "ParentProcess", "description": "Shells spawned from Preview, Safari, or AppleScript."}, {"field": "UserRole", "description": "Detection thresholds may differ for admin vs standard users."}]', '2026-05-01 15:26:36.803703');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1643, 'AN0831', 'Analytic 0831', 'Detects adversarial archiving using built-in or third-party utilities (makecab, diantz, xcopy, certutil, 7z, WinRAR, WinZip). Correlates suspicious process creation events with command-line arguments for compression/encoding, followed by creation of archive files (.cab, .zip, .7z, .rar). Identifies anomalous loading of crypt32.dll for encryption operations or execution of diantz.exe to compress remotely staged files.', '{Windows}', 'x-mitre-analytic--ebfa3aa8-dc7c-4d56-868e-169c873b5e78', 'DET0298', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "SuspiciousExtensions", "description": "List of archive extensions considered high risk (.cab, .zip, .7z, .rar)."}, {"field": "ProcessAllowlist", "description": "Known business utilities allowed to create archives without alerting."}, {"field": "FileSizeThresholdMB", "description": "Minimum archive size threshold to filter out benign small compressions."}]', '2026-05-01 15:26:36.806606');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1644, 'AN0012', 'Analytic 0012', 'Execution of binaries where the on-disk filename does not match PE metadata such as OriginalFilename or InternalName. Often observed with renamed LOLBAS or system binaries like rundll32, powershell, or psexec.', '{Windows}', 'x-mitre-analytic--ec036273-4e90-465e-b115-a69bbb68dde4', 'DET0005', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "EDR:AMSI", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ImagePath", "description": "Filter by suspicious or non-standard directory paths"}, {"field": "PEInternalNameMismatch", "description": "Enable tuning based on mismatch rules between metadata and disk filename"}, {"field": "CommandLinePattern", "description": "Flag unusual or rare argument combinations for LOLBAS-like tools"}]', '2026-05-01 15:26:36.808401');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1645, 'AN0854', 'Analytic 0854', 'Adversary modifies GPO containers or files under SYSVOL using LDAP, ADSI, PowerShell (e.g., New-GPOImmediateTask) or GUI tools. This includes directory object changes (e.g., gPCFileSysPath), delegation assignments (SeEnableDelegationPrivilege), and SYSVOL file writes (ScheduledTasks.xml, GptTmpl.inf).', '{Windows}', 'x-mitre-analytic--ec6e1f3c-e9ff-4944-a426-863eaf9979ea', 'DET0305', '[{"name": "WinEventLog:Security", "channel": "EventCode=5136", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Security", "channel": "EventCode=4704", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ObjectDN", "description": "Focus detection on AD paths like CN=Policies,CN=System,DC=domain,DC=com."}, {"field": "TargetFilename", "description": "Target specific files like ScheduledTasks.xml or GptTmpl.inf in SYSVOL."}, {"field": "TimeWindow", "description": "Correlate GPO object change and SYSVOL file modification within N seconds."}, {"field": "UserContext", "description": "Alert on unexpected modification by non-admins or uncommon accounts."}, {"field": "CommandLine", "description": "Flag usage of GPO manipulation tools like Set-GPRegistryValue, New-GPOImmediateTask."}]', '2026-05-01 15:26:36.810003');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1646, 'AN1453', 'Analytic 1453', 'Execution of system enumeration commands such as `uname`, `df`, `uptime`, `hostname`, `lscpu`, and `cat /etc/os-release` through local terminal or scripts.', '{Linux}', 'x-mitre-analytic--eca769c3-9497-4c87-b624-4003fd1b0304', 'DET0525', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandList", "description": "Customize list of commands of interest (e.g., uname, lscpu, etc.)"}, {"field": "TerminalSessionID", "description": "Correlate sessions for behavior context."}]', '2026-05-01 15:26:36.811663');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1647, 'AN0018', 'Analytic 0018', 'Federated login using SSO or OAuth grant to cloud control plane, followed by directory or permissions enumeration', '{"Identity Provider"}', 'x-mitre-analytic--ecb9db5c-55ef-48df-8ccb-f57db8c32a08', 'DET0008', '[{"name": "Okta:SystemLog", "channel": "user.authentication.sso, app.oauth.grant", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "SSOApplicationScope", "description": "Tune based on applications federated to high-priv cloud assets"}, {"field": "ClientIDScope", "description": "Filter based on expected OIDC clients used for login"}, {"field": "LoginVelocity", "description": "Track multiple geographic logins within short windows"}]', '2026-05-01 15:26:36.813157');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1648, 'AN1053', 'Analytic 1053', 'Correlate creation or modification of serverless functions (e.g., AWS Lambda, GCP Cloud Functions, Azure Functions) with anomalous IAM role assignments or permissions escalation events. Detect subsequent executions of newly created functions that perform unexpected actions such as spawning outbound network connections, accessing sensitive resources, or creating additional credentials.', '{IaaS}', 'x-mitre-analytic--ecf190d1-5311-466f-a361-a33820b3c7b7', 'DET0374', '[{"name": "AWS:CloudTrail", "channel": "CreateFunction / UpdateFunctionConfiguration: Function creation, role assignment, or configuration change events", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "AWS:CloudTrail", "channel": "InvokeFunction: Unexpected or repeated invocation of functions not tied to known workflows", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "RoleScope", "description": "Which IAM roles or privileges are considered sensitive when applied to functions"}, {"field": "AllowedFunctions", "description": "Known baseline list of approved serverless functions to reduce false positives"}, {"field": "TimeWindow", "description": "Temporal threshold for correlating function creation with anomalous execution"}]', '2026-05-01 15:26:36.814541');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1649, 'AN1634', 'Analytic 1634', 'Detects kernel- or user-space exploitation attempts targeting auditd, AV daemons, or security monitoring agents. Defender observation includes unexpected segfaults, privilege escalation attempts from low-privileged processes, or modifications to security binaries. Correlates exploitation attempts with subsequent gaps in logging or terminated processes.', '{Linux}', 'x-mitre-analytic--ecf26d05-48ef-43b2-bfc3-4ea331be735b', 'DET0595', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of suspicious exploit binaries targeting security daemons", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Segfaults, kernel oops, or crashes in security software processes", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "WatchedBinaries", "description": "List of critical security daemons (e.g., auditd, falco, AV agents) to monitor for exploitation."}, {"field": "CrashPatterns", "description": "Regex or patterns for kernel/syslog errors correlated with exploitation attempts."}]', '2026-05-01 15:26:36.815969');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1650, 'AN0559', 'Analytic 0559', 'Execution of built-in tools (e.g., ipconfig, route, netsh) or PowerShell/WMI queries to enumerate IP, MAC, interface status, or routing configuration.', '{Windows}', 'x-mitre-analytic--edfec58e-e591-4057-a906-1baf3674d80b', 'DET0195', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ParentProcess", "description": "Filter known/legit CLI chains (e.g., explorer.exe → cmd.exe) to reduce FP"}, {"field": "UserContext", "description": "Target executions by non-admin or unexpected users"}, {"field": "TimeWindow", "description": "Cluster enumeration commands within short time windows"}]', '2026-05-01 15:26:36.817248');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1658, 'AN0695', 'Analytic 0695', 'Detects adversarial use of cloud-native APIs (e.g., AWS IAM, Azure RBAC, GCP Identity) to enumerate cloud group memberships or policy mappings via unauthorized sessions or scripts.', '{IaaS}', 'x-mitre-analytic--ef4f995e-6f20-42b7-802e-555ac54ab7b9', 'DET0251', '[{"name": "AWS:CloudTrail", "channel": "ListGroups, ListAttachedRolePolicies", "x_mitre_data_component_ref": "x-mitre-data-component--8e44412e-3238-4d64-8878-4f11e27784fe"}]', '[{"field": "UserContext", "description": "Scope to anomalous IAM principals or assume-role usage."}, {"field": "TimeWindow", "description": "Correlate enumeration activity within lateral movement prep windows."}]', '2026-05-01 15:26:36.828846');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1651, 'AN1236', 'Analytic 1236', 'Local user accounts are created via binaries like ''useradd'', ''adduser'', or by editing passwd/shadow. Behavior chain includes execution of user management binaries or modification of user database files.', '{Linux}', 'x-mitre-analytic--ee065e5f-5a04-49bd-b2b6-33b404ac37c7', 'DET0447', '[{"name": "auditd:SYSCALL", "channel": "useradd or adduser executed", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}, {"name": "auditd:SYSCALL", "channel": "write operation on /etc/passwd or /etc/shadow", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "BinaryPath", "description": "Account creation may be scripted via shell scripts, cron jobs, or remote shells"}, {"field": "ExecutionSource", "description": "Flag if commands are issued from remote sessions (e.g., sshd)"}]', '2026-05-01 15:26:36.818489');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1652, 'AN0289', 'Analytic 0289', 'Detects unauthorized additions or changes to /Library/Security/SecurityAgentPlugins and suspicious process activity attempting to hook authentication APIs. Correlates file modifications with abnormal plugin loads in authentication flows.', '{macOS}', 'x-mitre-analytic--ee0f60f3-2fb3-4857-b02e-58c69b5aab52', 'DET0104', '[{"name": "macos:unifiedlog", "channel": "SecurityAgentPlugins modification", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "macos:osquery", "channel": "process_open", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "PluginPaths", "description": "List of approved authentication plugin directories to baseline."}]', '2026-05-01 15:26:36.819824');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1653, 'AN0706', 'Analytic 0706', 'Monitor for suspicious use of commands such as cat, less, grep, or journalctl accessing /var/log/ files. Abnormal enumeration of authentication logs (auth.log, secure) or bulk access to multiple logs in short time windows should be flagged.', '{Linux}', 'x-mitre-analytic--ee468e26-d179-47ba-af8b-43118db24939', 'DET0255', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of cat, less, grep, journalctl targeting log directories (/var/log/)", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "auditd:PATH", "channel": "open: Access to sensitive log files (/var/log/auth.log, /var/log/secure, /var/log/syslog)", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "AdminMaintenanceScripts", "description": "Filter routine scripts used for log rotation or troubleshooting."}]', '2026-05-01 15:26:36.821046');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1654, 'AN0002', 'Analytic 0002', 'Detects non-standard processes (e.g., PowerShell, python.exe, rundll32.exe) making outbound connections using publish/subscribe protocols (e.g., MQTT, AMQP) over non-browser, encrypted channels, often beaconing to message brokers.', '{Windows}', 'x-mitre-analytic--ee4e3e61-e138-498b-93bf-3a5f8fea691c', 'DET0002', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "mqtt.log / xmpp.log (custom log feeds)", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "UnusualProcessList", "description": "Detect suspicious processes initiating outbound pub/sub connections"}, {"field": "TimeWindow", "description": "Define beaconing interval used for temporal correlation"}, {"field": "ProtocolPortList", "description": "Custom MQTT/XMPP port use in non-standard ranges (e.g., 1883, 5222, 5672)"}]', '2026-05-01 15:26:36.822503');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1655, 'AN1178', 'Analytic 1178', 'Correlate DNS queries that generate domains with high entropy or gibberish patterns, combined with short-lived connections from unusual processes. Monitor Sysmon DNS events and Windows Security logs for abnormal query rates and failed lookups.', '{Windows}', 'x-mitre-analytic--ee7499f8-4262-47cf-8fff-5344f60bf2cf', 'DET0419', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "EntropyThreshold", "description": "Set threshold for randomness in queried domain strings (e.g., >4.0)"}, {"field": "QueryFailureRate", "description": "Failed resolution ratio above normal baseline (e.g., >30%)"}, {"field": "TimeWindow", "description": "Duration for aggregating suspicious DNS queries (e.g., 5–10 min)"}]', '2026-05-01 15:26:36.824318');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1656, 'AN1188', 'Analytic 1188', 'Creation, deletion, or modification of security groups and firewall rules in cloud control plane logs that expand access to cloud resources beyond expected baselines. Defender view: unexpected ingress/egress rules permitting 0.0.0.0/0 or opening atypical ports, often correlated with privileged role or API key activity.', '{IaaS}', 'x-mitre-analytic--ee7c904b-144f-4dc4-87af-7eee4655899c', 'DET0424', '[{"name": "AWS:CloudTrail", "channel": "Ingress rule creation or modification for security group", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}, {"name": "AWS:CloudTrail", "channel": "Removal of restrictive egress rules from a security group", "x_mitre_data_component_ref": "x-mitre-data-component--c97d0171-f6e0-4415-85ff-4082fdb8c72a"}]', '[{"field": "AllowedIPRanges", "description": "Whitelist approved IP ranges; detect unexpected addition of 0.0.0.0/0 or untrusted CIDRs."}, {"field": "PortScope", "description": "Define expected ports for services; flag additions outside this range (e.g., SSH/RDP open to all)."}, {"field": "RoleContext", "description": "Tune alerts based on whether changes are made by break-glass or admin roles versus automation accounts."}, {"field": "TimeWindow", "description": "Correlate rule changes with subsequent suspicious network activity to reduce false positives."}]', '2026-05-01 15:26:36.826037');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1657, 'AN0321', 'Analytic 0321', 'Use of non-enterprise email or messaging services in Thunderbird, Evolution, or browsers leading to suspicious file downloads and subsequent execution. Defender view includes browser-initiated downloads of unexpected content and shell or interpreter processes launched post-download.', '{Linux}', 'x-mitre-analytic--eed7a6f2-496d-47c6-bdfd-1b885b58a651', 'DET0115', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of bash, python, or perl processes spawned by browser/email client", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Inbound messages from webmail services containing attachments or URLs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "NSM:Flow", "channel": "Outbound traffic to domains/IPs not previously resolved, occurring shortly after attachment download or link click", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "BrowserProcesses", "description": "Configured list of browsers or email clients to monitor (e.g., firefox, chromium, thunderbird)."}, {"field": "PhishingIndicators", "description": "Custom regex rules for suspicious URL patterns, file extensions, or encoded links."}]', '2026-05-01 15:26:36.827596');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1659, 'AN0365', 'Analytic 0365', 'Domain group and user enumeration via dscl or dscacheutil, or queries to directory services from non-admin endpoints.', '{macOS}', 'x-mitre-analytic--ef50b854-172a-457b-9d0e-c95d9835eaaa', 'DET0129', '[{"name": "macos:unifiedlog", "channel": "Process Execution", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "DS daemon log entries", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "CommandPattern", "description": "Match patterns such as ''dscl /Active\\ Directory/All\\ Domains -list /Users''."}, {"field": "EndpointRole", "description": "Flag this activity only on non-directory hosts or non-admin accounts."}]', '2026-05-01 15:26:36.83042');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1660, 'AN1018', 'Analytic 1018', 'Execution of `ping`, `vmkping`, or `curl` from shell or through automation jobs/scripts to verify Internet egress.', '{ESXi}', 'x-mitre-analytic--ef76221d-d5fe-4285-af27-54711e94e2b5', 'DET0357', '[{"name": "esxi:shell", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "esxi:hostd", "channel": "process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "SSHSessionOrigin", "description": "Distinguish external SSH sessions from internal admin maintenance"}, {"field": "TargetIP", "description": "Egress test destination may be filtered to known CDNs/test nodes"}]', '2026-05-01 15:26:36.831796');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1661, 'AN0509', 'Analytic 0509', 'Group membership checks via ''dscl'', ''dscacheutil'', or ''id'', typically executed via terminal or automation scripts.', '{macOS}', 'x-mitre-analytic--ef8fa56d-882e-42da-990e-2adc3a771041', 'DET0179', '[{"name": "macos:unifiedlog", "channel": "process:launch", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLine", "description": "Filters for suspicious execution of ''dscl . -read /Groups'', etc."}, {"field": "ParentProcess", "description": "Flag group enumeration from automation tools (e.g., LaunchAgents or suspicious apps)."}]', '2026-05-01 15:26:36.83301');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1662, 'AN1362', 'Analytic 1362', 'Monitor server and endpoint logs for unusual outbound network connections to cryptocurrency nodes, unauthorized scripts accessing financial systems, or automation targeting payment file formats. Detect curl/wget activity aimed at exfiltrating transaction data or credentials from financial apps.', '{Linux}', 'x-mitre-analytic--efdca1e1-5a4a-4039-99ab-1cdb7e50e52c', 'DET0495', '[{"name": "auditd:SYSCALL", "channel": "execve: Execution of curl, wget, or custom scripts accessing financial endpoints", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:syslog", "channel": "Authentication attempts into finance-related servers from unusual IPs or times", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "KnownFinanceIPs", "description": "Whitelisted IPs for finance-related traffic to reduce noise."}]', '2026-05-01 15:26:36.835154');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1663, 'AN0760', 'Analytic 0760', 'Processes like curl, wget, python, socat, or custom binaries initiating TLS/SSL sessions to non-standard destinations. Defender sees abnormal syscalls for connect(), loading of libssl libraries, and persistent outbound encrypted traffic from daemons not normally communicating externally.', '{Linux}', 'x-mitre-analytic--f0dacfba-bcc0-43cb-bad5-0cd3fe3a7f5f', 'DET0273', '[{"name": "auditd:SYSCALL", "channel": "socket/connect with TLS context by unexpected process", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "linux:syslog", "channel": "system daemons initiating TLS sessions outside expected services", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "linux:osquery", "channel": "Processes linked with libssl or crypto libraries making outbound connections", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "WhitelistedDaemons", "description": "Legitimate system services expected to use TLS (e.g., package updates)."}, {"field": "CertificateAuthorities", "description": "Trusted CAs; flag self-signed or unrecognized certs."}]', '2026-05-01 15:26:36.836549');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1664, 'AN1347', 'Analytic 1347', 'Behavioral chain: (1) delegated admin or external identity establishes session (e.g., partner/reseller DAP, B2B guest, SAML/OAuth trust); (2) role elevation or app consent/permission grant; (3) downstream privileged actions in the tenant. Correlate IdP sign-in, admin/role assignment, and consent/admin-on-behalf events.', '{"Identity Provider"}', 'x-mitre-analytic--f0e2baa2-3bb7-4587-8eae-6abddd1cf140', 'DET0488', '[{"name": "azure:signinlogs", "channel": "InteractiveUser, ServicePrincipalSignIn", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "azure:audit", "channel": "Add delegated admin / Assign admin roles / Update application consent", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "m365:unified", "channel": "Set-PartnerOfRecord / CompanyAdministrator role assignments / New-DelegatedAdminRelationship", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TrustedPartnerTenantIDs", "description": "Tenant IDs of approved partners; any others are suspicious."}, {"field": "RequiredMFA", "description": "Require MFA for partner sessions; alert on bypass or step-up failure."}, {"field": "RoleScopeAllowList", "description": "Roles third-parties may hold (e.g., Helpdesk Admin); flag broader scopes."}]', '2026-05-01 15:26:36.837944');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1665, 'AN0277', 'Analytic 0277', 'Detects malicious injection behavior involving memory allocation, remote thread queuing via APC (e.g., QueueUserAPC), and altered thread context within another live process to execute unauthorized code under legitimate context.', '{Windows}', 'x-mitre-analytic--f0fce510-b195-4688-a4ac-b78584febd08', 'DET0100', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=8", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "etw:Microsoft-Windows-Kernel-Process", "channel": "APCQueueOperations", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "APCTargetProcessList", "description": "Processes that are rarely or never valid targets for legitimate APC queuing (e.g., lsass.exe, winlogon.exe)"}, {"field": "ThreadQueueDepthThreshold", "description": "The number of APCs queued within a short time window that could signal abuse"}, {"field": "TimeWindow", "description": "Expected latency between memory allocation and thread execution through APC"}, {"field": "UserContextSensitivity", "description": "Used to filter based on expected vs unexpected user to target process pairings"}]', '2026-05-01 15:26:36.839503');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1666, 'AN0637', 'Analytic 0637', 'Initial process initiates outbound connection to first-stage C2, receives payloads or commands, then spawns or injects into a second process that establishes a new outbound connection to an unrelated destination (second-stage C2).', '{Windows}', 'x-mitre-analytic--f13ff1ad-5c7b-4136-b5cb-7a5663c3c54f', 'DET0228', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "TimeWindow", "description": "Correlate two-stage behavior occurring within a short window (e.g., 1-5 minutes)"}, {"field": "ParentProcess", "description": "Tune to exclude known legitimate updaters and management agents"}, {"field": "DestinationHostname", "description": "May be customized to exclude known corporate domains and CDNs"}]', '2026-05-01 15:26:36.84151');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1667, 'AN1539', 'Analytic 1539', 'Detect ''shutdown'', ''reboot'', or ''systemctl poweroff'' executions with auditd/syslog and absence of scheduled maintenance windows or approved user context.', '{Linux}', 'x-mitre-analytic--f1a019df-12f0-442e-9b0e-b1a82352389b', 'DET0559', '[{"name": "auditd:SYSCALL", "channel": "execve=/sbin/shutdown or /sbin/reboot", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "linux:syslog", "channel": "system is powering down", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "CommandLineMatch", "description": "Supports multiple binary names or symlinked utilities."}, {"field": "UserContext", "description": "Privileged user (e.g., root or via sudo) context matching expected roles."}]', '2026-05-01 15:26:36.843114');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1668, 'AN0853', 'Analytic 0853', 'Cloud workload exploitation leads to repeated container, service, or VM termination/restart, typically associated with CVE-based crash triggers or fuzzed payloads.', '{IaaS}', 'x-mitre-analytic--f1aae71a-6460-4c08-9aa7-49743f766a71', 'DET0304', '[{"name": "AWS:CloudTrail", "channel": "TerminateInstances", "x_mitre_data_component_ref": "x-mitre-data-component--1361e324-b594-4c0e-a517-20cee32b8d7f"}, {"name": "AWS:CloudWatch", "channel": "Repeated crash pattern within container or instance logs", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "AWS:VPCFlowLogs", "channel": "Large volume of malformed or synthetic payloads to application endpoints prior to failure", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "CrashThreshold", "description": "Number of repeated crashes or terminations observed before triggering alert"}, {"field": "ServiceID", "description": "Cloud service name, workload, or container ID to scope alerting"}]', '2026-05-01 15:26:36.844513');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1669, 'AN1957', 'Analytic 1957', 'If infrastructure or patterns in the malicious web content utilized to deliver a [Drive-by Compromise](https://attack.mitre.org/techniques/T1189) have been previously identified, internet scanning may uncover when an adversary has staged web content for use in a strategic web compromise.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1670, 'AN1068', 'Analytic 1068', 'Detects encoded PowerCLI or Base64-encoded payloads staged via datastore uploads or shell access (e.g., ESXi Shell or backdoored VIBs).', '{ESXi}', 'x-mitre-analytic--f1ec63bc-294c-471c-ae9f-4dd70f3c036a', 'DET0378', '[{"name": "esxi:vmkernel", "channel": "Datastore modification events", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "esxi:hostd", "channel": "Remote access API calls and file uploads", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}]', '[{"field": "StagingLocation", "description": "Tune based on observed adversary paths (e.g., /vmfs/volumes/...)"}, {"field": "EncodedLengthThreshold", "description": "Tune length of encoded payloads before triggering detection"}]', '2026-05-01 15:26:36.847572');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1671, 'AN1515', 'Analytic 1515', 'ESXi guest OS or management interface processes establishing unexpected external HTTPS connections. Defender perspective: monitor vmx or hostd processes making outbound web requests with significant data transfer.', '{ESXi}', 'x-mitre-analytic--f1f23910-7ecd-498b-92e8-7b5aa0d53ac8', 'DET0548', '[{"name": "esxi:vmkernel", "channel": "network session initiation with external HTTPS services", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "esxi:hostd", "channel": "file copy or datastore upload via HTTPS", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "DatastoreTransferThreshold", "description": "Threshold for outbound transfers from ESXi datastores."}]', '2026-05-01 15:26:36.848844');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1672, 'AN0065', 'Analytic 0065', 'Adversary stages a lure that references a remote resource (e.g., LNK/SCF/Office template). When the user opens/renders the file or a shell enumerates icons, the host automatically attempts SMB or WebDAV authentication to the attacker host. The chain is: (1) lure file is created or modified in a user-exposed location → (2) user or system accesses the lure → (3) host makes outbound NTLM (SMB 139/445 or WebDAV over 80/443) to an untrusted destination → (4) repeated attempts from multiple users/hosts or from privileged workstations.', '{Windows}', 'x-mitre-analytic--f2064dd1-8cdb-472e-b187-8d1ef18fb059', 'DET0022', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "NSM:Flow", "channel": "HTTP/WebDAV requests that contain NTLMSSP or PROPFIND/MOVE/OPTIONS with Authorization: NTLM", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "NSM:Flow", "channel": "Outbound connections to TCP 139,445 and HTTP/HTTPS to WebDAV endpoints from workstation subnets", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "UserLocations", "description": "Folders where lures are most effective (Desktop, Public, Downloads, Temp, Cache, Start Menu, Startup). Adjust to enterprise layout."}, {"field": "LureExtensions", "description": "File types commonly abused (.lnk, .scf, .url, .doc/.xls/.ppt/.pdf/.html). Extend for your tooling and languages."}, {"field": "UntrustedCIDR/DNS", "description": "Org-specific list of external/unknown networks or domains; used to suppress sanctioned file servers and WebDAV gateways."}, {"field": "TimeWindow", "description": "Correlation horizon (e.g., 15–30 minutes) between file access and outbound NTLM attempt."}, {"field": "WorkstationZones", "description": "Asset/zone tags that distinguish workstations from servers; helps flag workstation→workstation SMB, which is often abnormal."}, {"field": "OfficeTemplatePaths", "description": "Paths to Office templates to catch template injection references and abnormal loads."}]', '2026-05-01 15:26:36.850107');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1727, 'AN1080', 'Analytic 1080', 'Monitors for the creation of accounts inside containers using names that resemble legitimate orchestrator or backup identities to mask adversary persistence.', '{Containers}', 'x-mitre-analytic--fb767270-25ad-4fea-a8e7-8f9c57ac1fa8', 'DET0383', '[{"name": "docker:daemon", "channel": "ExecCreate + usermod or useradd", "x_mitre_data_component_ref": "x-mitre-data-component--deb22295-7e37-4a3b-ac6f-c86666fbe63d"}]', '[{"field": "ContainerContextScope", "description": "Limit detection to containers with persistent volumes or specific workloads"}, {"field": "MasqueradePatternList", "description": "Custom list of commonly abused names to blend into container environments (e.g., kubelet, cronjob_sync)"}]', '2026-05-01 15:26:36.932513');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1673, 'AN0165', 'Analytic 0165', 'Unusual or uncommon processes initiate network connections to external destinations followed by file creation (tools downloaded).', '{Windows}', 'x-mitre-analytic--f20d9241-84cc-4393-b2fb-798241da73fa', 'DET0060', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ParentProcessName", "description": "Tune for known good updaters (e.g., ChromeUpdate, OneDrive)"}, {"field": "DestinationIPCategory", "description": "Allow filtering by internal vs external IP blocks"}, {"field": "FilePathRegex", "description": "Focus on uncommon file drop paths (e.g., C:\\Users\\Public\\)"}]', '2026-05-01 15:26:36.851482');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1674, 'AN2033', 'Analytic 2033', 'Detects suspicious inbound communications or collaboration requests followed by rapid sensitive user actions such as file sharing changes, macro enablement, OAuth consent, credential submission, or financial workflow approvals that deviate from historical relationships or normal approval patterns.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1675, 'AN0646', 'Analytic 0646', 'Detects anomalous usage of ESXi Guest Operations APIs such as StartProgramInGuest, ListProcessesInGuest, ListFileInGuest, or InitiateFileTransferFromGuest. Defender perspective focuses on unusual frequency of guest API calls, invocation from unexpected management accounts, or execution outside of business hours. These correlated signals indicate adversarial abuse of ESXi administrative services to run commands on guest VMs.', '{ESXi}', 'x-mitre-analytic--f25cf3cf-53b8-4fa4-be4c-d0a7a02bf739', 'DET0232', '[{"name": "esxi:hostd", "channel": "Guest Operations API invocation: StartProgramInGuest, ListProcessesInGuest, ListFileInGuest, InitiateFileTransferFromGuest", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "ExpectedAdminUsers", "description": "Whitelist of management accounts authorized to use ESXi Guest Ops APIs."}, {"field": "TimeWindow", "description": "Business hours during which Guest Ops API usage is expected; activity outside may be suspicious."}, {"field": "OperationThreshold", "description": "Number of Guest Ops API calls considered anomalous if exceeded in a given timeframe."}, {"field": "AuthorizedVMs", "description": "List of VMs where Guest Ops usage is permitted; usage on other VMs may indicate malicious activity."}]', '2026-05-01 15:26:36.854298');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1676, 'AN0445', 'Analytic 0445', 'Detection of msiexec.exe execution where command-line arguments reference remote MSI packages, UNC paths, HTTP/HTTPS URLs, or DLLs, correlated with subsequent module loads and/or network connections to previously unseen destinations. The behavioral chain links process creation of msiexec.exe with suspicious parameters, network activity to retrieve payloads, and module loading indicative of malicious installation or DLL execution.', '{Windows}', 'x-mitre-analytic--f27c0482-fbea-47a3-9b19-7302a058a9e5', 'DET0158', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "SuspiciousCommandlinePatterns", "description": "Patterns for identifying malicious msiexec.exe usage (e.g., UNC paths, external domains, DLL execution flags)"}, {"field": "SuspiciousDestinationList", "description": "List of external domains or IP ranges considered suspicious for msiexec network connections"}, {"field": "TimeWindow", "description": "Time range in seconds/minutes for correlating msiexec.exe execution with module load and network activity"}, {"field": "LegitimateMSIHashes", "description": "Hash list of MSI packages considered known-good to reduce false positives"}]', '2026-05-01 15:26:36.855703');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1677, 'AN1361', 'Analytic 1361', 'Monitor for anomalous access to financial applications, browser-based banking sessions, or enterprise ERP systems from Windows endpoints. Detect mass emailing of payment instructions, sudden rule changes in Outlook for financial staff, or use of clipboard data exfiltration tied to cryptocurrency wallet addresses.', '{Windows}', 'x-mitre-analytic--f2aef85a-c1ea-4d1a-b359-32692c973cdc', 'DET0495', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "FinanceAppList", "description": "Baseline of finance-related executables or ERP processes to monitor closely."}, {"field": "HighRiskAccounts", "description": "Accounts belonging to finance, treasury, or executives that should be monitored with higher sensitivity."}]', '2026-05-01 15:26:36.858558');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1690, 'AN2042', 'Analytic 2042', 'Detects exploitation or abuse of SaaS security workflows resulting in disabled alerts, reduced retention, bypassed enforcement, role escalation, or tokenized persistence that weakens monitoring. Correlates unusual admin/API activity with visibility reduction.', '{SaaS}', 'x-mitre-analytic--f46639b5-4d99-4d52-8da9-112a468cc6d8', 'DET0900', '[{"name": "saas:okta", "channel": "policy.rule.update;system.log.disable;admin.role.assign", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "m365:unified", "channel": "Set-AdminAuditLogConfig;New-ApplicationAccessPolicy;ConsentToApplication", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "PrivilegedActorAllowlist", "description": "Approved admins allowed to change controls"}, {"field": "RetentionChangeThreshold", "description": "Minimum acceptable logging retention"}]', '2026-05-01 15:26:36.877237');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1678, 'AN0582', 'Analytic 0582', 'Detects abuse of container orchestration platforms (e.g., Kubernetes) where adversaries create CronJobs to maintain persistence or execute malicious Jobs across the cluster.', '{Containers}', 'x-mitre-analytic--f2c03ef0-cd36-42b8-9c2d-e25a3b1b8b1c', 'DET0206', '[{"name": "kubernetes:apiserver", "channel": "verb=create, resource=cronjobs, group=batch", "x_mitre_data_component_ref": "x-mitre-data-component--f42df6f0-6395-4f0c-9376-525a031f00c3"}, {"name": "kubernetes:events", "channel": "container start/stop activity via Docker, containerd, or CRI-O", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"name": "container:proxy", "channel": "outbound/inbound network activity from spawned pods", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "NamespaceScope", "description": "Kubernetes namespace the job is deployed to—scoping this to known trusted namespaces may reduce noise."}, {"field": "ImageRepository", "description": "The container image registry or repository the job pulls from—can be filtered by trusted registries."}, {"field": "ScheduleWindow", "description": "Time window or frequency of CronJob execution (e.g., ‘@hourly’)—jobs running at odd hours may be suspicious."}, {"field": "ExecutionCommand", "description": "The command or entrypoint executed by the Job—unexpected shell commands or interpreters may warrant inspection."}]', '2026-05-01 15:26:36.860198');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1679, 'AN0073', 'Analytic 0073', 'Abuse of macOS Electron apps by modifying app.asar bundles and spawning child processes (osascript, curl, sh) from Electron executables.', '{macOS}', 'x-mitre-analytic--f2c91a4c-1e79-4350-8a7e-94bc7b7b9a4c', 'DET0025', '[{"name": "macos:unifiedlog", "channel": "Electron app spawning unexpected child process", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:osquery", "channel": "CREATE/MODIFY: Modification of app.asar inside .app bundle", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "AllowedAppBundlePaths", "description": "Baseline of legitimate Electron app paths under /Applications."}, {"field": "SignedToUnsignedTransition", "description": "Alert when signed Electron parent spawns unsigned child."}]', '2026-05-01 15:26:36.861793');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1680, 'AN1999', 'Analytic 1999', 'Monitor and analyze traffic patterns and packet inspection associated to protocol(s) that do not follow the expected protocol standards and traffic flows (e.g extraneous packets that do not belong to established flows, gratuitous or anomalous traffic patterns, anomalous syntax, or structure). Consider correlation with process monitoring and command line to detect anomalous processes execution and command line arguments associated to traffic patterns (e.g. monitor anomalies in use of files that do not normally initiate connections for respective protocol(s)).
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1681, 'AN0581', 'Analytic 0581', 'Execution of XSL scripts via msxsl.exe or wmic.exe using embedded JScript or VBScript for proxy execution. Detection correlates process creation, command-line patterns, and module load behavior of scripting components (e.g., jscript.dll).', '{Windows}', 'x-mitre-analytic--f313053f-5898-4f47-b263-a60098f5c963', 'DET0205', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "CommandLinePattern", "description": "May need to tune based on encoded input or custom extensions (e.g., .jpeg instead of .xsl)."}, {"field": "ParentProcess", "description": "Legitimate administrative or developer tools may use msxsl; validate the parent process chain."}, {"field": "TimeWindow", "description": "Temporal correlation window between script engine DLL load and suspicious process spawn."}, {"field": "RemoteXSLDomainWhitelist", "description": "Filter known safe URLs used by enterprise for XSL transformations."}]', '2026-05-01 15:26:36.864545');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1682, 'AN1577', 'Analytic 1577', 'Detects creation or modification of `LaunchDaemon` or `LaunchAgent` plist files under `/Library/LaunchDaemons/`, `~/Library/LaunchAgents/`, or similar. Monitors execution of `launchctl`, property list edits, and file permission changes.', '{macOS}', 'x-mitre-analytic--f315abd4-7115-45ac-9466-64c23367cd41', 'DET0571', '[{"name": "macos:unifiedlog", "channel": "launchctl load/unload or plist file modification", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "fs:fsusage", "channel": "file write to launchd plist paths", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}]', '[{"field": "PlistPathList", "description": "Watched directories for LaunchDaemons and LaunchAgents"}, {"field": "PlistKeyMonitor", "description": "Monitored keys such as `RunAtLoad`, `KeepAlive`, or `ProgramArguments`"}, {"field": "UnsignedBinaryAlert", "description": "Flag execution of unsigned or non-Apple-signed binaries within plist"}]', '2026-05-01 15:26:36.865905');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1683, 'AN0388', 'Analytic 0388', 'Execution of InstallUtil.exe from .NET framework directories with arguments specifying non-standard or attacker-supplied assemblies, especially when followed by suspicious child process creation or script execution. Detection also includes correlation of newly created binaries prior to InstallUtil invocation and anomalous command-line usage compared to historical baselines.', '{Windows}', 'x-mitre-analytic--f3478623-5b5c-482e-96f1-6b225ff8fa70', 'DET0138', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "InstallUtilPathRegex", "description": "Regex pattern for InstallUtil.exe in .NET directories; tune to exclude known good administrative scripts"}, {"field": "AssemblyPathRegex", "description": "Patterns for identifying suspicious assemblies (e.g., in temp folders, user profiles)"}, {"field": "ChildProcessList", "description": "List of suspicious child processes spawned from InstallUtil.exe (e.g., cmd.exe, powershell.exe, rundll32.exe)"}, {"field": "TimeWindow", "description": "Time correlation window between file creation of assembly and its execution via InstallUtil.exe"}]', '2026-05-01 15:26:36.867055');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1684, 'AN0172', 'Analytic 0172', 'Detects Python execution via python.exe or py.exe with anomalous parent lineage (e.g., Office macros, LOLBAS), execution from unusual directories, or chained network/PowerShell/system-level activity.', '{Windows}', 'x-mitre-analytic--f392a2cb-dd4b-4585-84d5-1fa4bd65ff60', 'DET0063', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "EDR:hunting", "channel": "Advanced Hunting: DeviceProcessEvents + DeviceNetworkEvents", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ParentProcess", "description": "Non-standard processes spawning python.exe (e.g., winword.exe, mshta.exe)."}, {"field": "ScriptPath", "description": "Execution of .py from temp directories or user profile paths."}, {"field": "TimeWindow", "description": "Execution outside maintenance or patch windows."}, {"field": "UserContext", "description": "Execution by low-privileged or service accounts."}, {"field": "ChildProcess", "description": "Python spawning suspicious binaries or scripts (e.g., PowerShell, certutil)."}]', '2026-05-01 15:26:36.868249');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1685, 'AN1135', 'Analytic 1135', 'Abuse of extended attributes (xattrs) to embed hidden payloads into legitimate files. Defender perspective: detect anomalous use of setfattr or getfattr commands, or direct syscalls (setxattr, getxattr) where attributes are unusually large or contain encoded data. Behavior chain includes: (1) execution of setfattr with suspicious namespaces (user., trusted.), (2) file metadata modification inconsistent with file size/hash, and (3) subsequent process execution reading attributes followed by decoding activity.', '{Linux}', 'x-mitre-analytic--f398e8ff-8c61-4672-8ace-118b11a38515', 'DET0406', '[{"name": "auditd:SYSCALL", "channel": "setxattr or getxattr system call", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "auditd:EXECVE", "channel": "execution of setfattr or getfattr commands", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "XattrNamespaces", "description": "Namespaces monitored for suspicious activity (user., trusted., security.). Organizations may tune to reduce noise from benign use."}, {"field": "PayloadSizeThreshold", "description": "Size of xattr values above which they should be considered anomalous (e.g., >1KB)."}, {"field": "CorrelationWindow", "description": "Time window to correlate xattr modification with process execution from the same file."}]', '2026-05-01 15:26:36.869543');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1686, 'AN0569', 'Analytic 0569', 'A process opens/reads /dev/video* (V4L2), performs ioctl/read loops, writes large/continuous video artifacts to disk, and/or quickly establishes outbound connections for exfiltration.', '{Linux}', 'x-mitre-analytic--f3c5c71a-da1b-4d09-bda7-ec07b0b7c05d', 'DET0197', '[{"name": "auditd:SYSCALL", "channel": "openat/read/ioctl: openat/read/ioctl on /dev/video* by uncommon user/process", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "auditd:SYSCALL", "channel": "PATH records referencing /dev/video*", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "linux:osquery", "channel": "select: path LIKE ''/dev/video%''", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}, {"name": "linux:syslog", "channel": "sudo execution of ffmpeg/gst-launch/v4l2-ctl by non-standard user", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Flow", "channel": "http/file-xfer: Outbound transfer of large video-like MIME types soon after capture", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "SyscallSet", "description": "Which syscalls to audit (openat, read, ioctl) – performance sensitive."}, {"field": "AllowedCallers", "description": "Legitimate processes (e.g., motion, Zoom, Chrome) that access /dev/video*."}, {"field": "VideoExtensions", "description": "List of file extensions to flag (.mp4/.avi/.mov/.mkv/.yuv/.h264)."}, {"field": "MinContinuousReadCount", "description": "Minimum read/ioctl count to infer continuous capture."}, {"field": "TimeWindow", "description": "Correlate device open → file write → network exfil (e.g., 30m)."}]', '2026-05-01 15:26:36.870802');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1687, 'AN0359', 'Analytic 0359', 'Adversary places scripts or binaries with misleading names in /etc/rc.local.d or /var/spool/cron, or registers services with legitimate-sounding names not present in default ESXi builds.', '{ESXi}', 'x-mitre-analytic--f3dfb562-94ef-44ea-be4f-17ac2d0771b5', 'DET0127', '[{"name": "esxi:hostd", "channel": "registers services with legitimate-sounding names", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}, {"name": "esxi:shell", "channel": "scripts or binaries with misleading names", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "ServiceNameBaseline", "description": "Tune based on default service names vs. suspicious new entries"}, {"field": "ScriptFilePath", "description": "Watch for new binaries/scripts in boot or cron folders"}, {"field": "ExecutionContext", "description": "Determine if execution happens at boot or scheduled interval"}]', '2026-05-01 15:26:36.872248');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1688, 'AN0755', 'Analytic 0755', 'Adversary modifies Group Policy Objects (GPOs), domain trust, or directory service objects via GUI, CLI, or programmatic APIs. Behavior includes creation/modification of GPOs, delegation permissions, trust objects, or rogue domain controller registration.', '{Windows}', 'x-mitre-analytic--f403ae40-31ff-4550-b21f-e1c24315276d', 'DET0270', '[{"name": "WinEventLog:Security", "channel": "EventCode=5136", "x_mitre_data_component_ref": "x-mitre-data-component--5b8b466b-2c81-4fe7-946f-d677a74ae3db"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ObjectDN", "description": "Filter to specific AD containers (e.g., CN=Policies,CN=System,DC=domain,DC=com) for GPOs."}, {"field": "AttributeModified", "description": "Focus on high-risk attributes such as gPCFileSysPath, ntSecurityDescriptor."}, {"field": "TimeWindow", "description": "Correlate changes with suspicious process creation or privileged user logon."}, {"field": "UserContext", "description": "Alert on unexpected user or service account modifying domain policy."}]', '2026-05-01 15:26:36.874005');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1689, 'AN1373', 'Analytic 1373', 'Detects disabling container runtime security controls, removing sidecar sensors, modifying seccomp/AppArmor profiles, mounting host proc/sys paths to interfere with host logging, or killing in-container monitoring agents.', '{Containers}', 'x-mitre-analytic--f421cbe1-d42e-45e9-adad-12c6ed0a5cb8', 'DET0497', '[{"name": "kubernetes:audit", "channel": "kubectl delete or patch of security pods/admission controllers", "x_mitre_data_component_ref": "x-mitre-data-component--74fa567d-bc90-425c-8a41-3c703abb221c"}]', '[{"field": "NamespaceExclusions", "description": "Exclusion of namespaces where temporary deletion of monitoring tools is legitimate (e.g., staging)."}]', '2026-05-01 15:26:36.875656');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1691, 'AN0728', 'Analytic 0728', 'Monitor DNS query results where subsequent connections use derived or unusual port numbers not explicitly resolved, especially when tied to suspicious processes. Correlate Sysmon DNS logs (Event ID 22) with process creation and socket activity.', '{Windows}', 'x-mitre-analytic--f47f256d-686f-4553-85e2-bd4d156da1e7', 'DET0262', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "PortDeviationThreshold", "description": "Deviation from common service ports (e.g., >1024 when DNS resolved service expects 80/443)"}, {"field": "TimeWindow", "description": "Correlation window between DNS response and network connection (e.g., 5 minutes)"}]', '2026-05-01 15:26:36.878515');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1692, 'AN0001', 'Analytic 0001', 'Detects access attempts to cloud instance metadata endpoints (e.g., 169.254.169.254) from virtual machines or containerized workloads. This includes both direct access and SSRF exploitation patterns.', '{IaaS}', 'x-mitre-analytic--f4af0b1b-db51-4266-8b02-2cdfcb191f60', 'DET0001', '[{"name": "AWS:VPCFlowLogs", "channel": "Outbound connection to 169.254.169.254 from EC2 workload", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "AWS:CloudTrail", "channel": "GetInstanceIdentityDocument", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}, {"name": "ebpf:syscalls", "channel": "Process within container accesses link-local address 169.254.169.254", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "TimeWindow", "description": "Adjust temporal window for correlation of access attempts and SSRF triggers"}, {"field": "UserContext", "description": "Tune based on expected roles that access metadata APIs (e.g., root, service accounts)"}, {"field": "RequestHeaderMatch", "description": "Customize detection for HTTP Host headers indicating SSRF"}]', '2026-05-01 15:26:36.880124');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1693, 'AN0449', 'Analytic 0449', 'Monitor for excessive or anomalous MFA push notifications or token requests, especially when login attempts originate from unusual IPs or geolocations and do not correspond to legitimate user-initiated sessions.', '{"Identity Provider"}', 'x-mitre-analytic--f51edea3-e0e8-4090-8e81-a01c3394ba53', 'DET0160', '[{"name": "azure:signinlogs", "channel": "Multiple MFA challenge requests without successful primary login", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "NSM:Connections", "channel": "PushNotificationSent", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "TimeWindow", "description": "Threshold of MFA prompts per user within a short time period"}, {"field": "GeoIPAllowList", "description": "Expected login locations for workforce; deviations can be tuned"}]', '2026-05-01 15:26:36.881398');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1694, 'AN1524', 'Analytic 1524', 'Multiple failed sign-in attempts from external sources across many users followed by success from the same IP', '{"Identity Provider"}', 'x-mitre-analytic--f525a464-a4e5-40fb-831a-162af2f232e7', 'DET0551', '[{"name": "azure:signinlogs", "channel": "Sign-in logs", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "GeoRiskScore", "description": "Elevate anomalies from uncommon geolocations"}, {"field": "MFAStatus", "description": "Elevate logins missing MFA on high-value accounts"}]', '2026-05-01 15:26:36.882592');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1695, 'AN1261', 'Analytic 1261', 'Detection of container image build activity directly on the host using Docker or Kubernetes APIs. Defenders may observe Docker build requests, anomalous Dockerfile instructions (such as downloading code from unknown IPs), or creation of new images followed by immediate deployment. This behavior chain typically consists of an unexpected image creation event correlated with outbound network communication to non-standard or untrusted destinations.', '{Containers}', 'x-mitre-analytic--f568a973-fb34-41aa-950f-f46457544564', 'DET0459', '[{"name": "docker:daemon", "channel": "docker build or POST /build API request", "x_mitre_data_component_ref": "x-mitre-data-component--b008766d-f34f-4ded-b712-659f59aaed6e"}, {"name": "NSM:Flow", "channel": "outbound connections from host during or immediately after image build", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "RegistryAllowList", "description": "Defines trusted registries for image pulls/builds. Builds referencing unapproved registries may indicate adversary behavior."}, {"field": "NewImageThreshold", "description": "Threshold for number of new custom images created in a given time window. Exceeding this threshold may indicate malicious builds."}, {"field": "TimeWindow", "description": "Defines correlation window (e.g., 5m) between suspicious build activity and subsequent network traffic anomalies."}]', '2026-05-01 15:26:36.88375');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1696, 'AN1136', 'Analytic 1136', 'Abuse of extended attributes (xattrs) to hide payloads in com.apple.* or custom keys. Defender perspective: monitor suspicious use of xattr command with -w (write) and -p (print) flags, especially when followed by execution of interpreters like bash, Python, or osascript. Behavior chain includes: (1) suspicious file modification with new com.apple.* attributes, (2) attribute content inconsistent with expected metadata tags (e.g., high entropy), (3) subsequent process execution correlated with extraction of the attribute.', '{macOS}', 'x-mitre-analytic--f5a0dc9d-3dda-4e31-ad4d-0560b918b6b1', 'DET0406', '[{"name": "macos:unifiedlog", "channel": "xattr utility execution with -w or -p flags", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "extended attribute write or modification", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "WatchedXattrKeys", "description": "Specific xattr keys to monitor (e.g., com.apple.quarantine, com.apple.ResourceFork, unknown custom keys)."}, {"field": "EntropyThreshold", "description": "High entropy attribute values may indicate encoded or encrypted payloads."}, {"field": "ProcessContext", "description": "Expected legitimate applications interacting with xattrs (Finder, Spotlight) to help reduce false positives."}]', '2026-05-01 15:26:36.885087');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1697, 'AN0709', 'Analytic 0709', 'Monitor ESXi shell or API access to host logs under /var/log/. Abnormal enumeration of vmkernel.log, hostd.log, or vpxa.log by unauthorized accounts should be flagged.', '{ESXi}', 'x-mitre-analytic--f5b9ad98-3a10-4ff3-9e25-890488253bef', 'DET0255', '[{"name": "esxi:shell", "channel": "Execution of cat, tail, grep targeting /var/log/vmkernel.log or /var/log/hostd.log", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:hostd", "channel": "read: Access to sensitive log files by non-admin users", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "AdminSessions", "description": "Correlate with legitimate administrator access sessions to reduce noise."}]', '2026-05-01 15:26:36.886295');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1698, 'AN0914', 'Analytic 0914', 'Detects ELF binaries written to disk that demonstrate anomalous file size or entropy, quickly followed by execution or memory region writes into remote processes (e.g., using ptrace).', '{Linux}', 'x-mitre-analytic--f606ec01-15d2-4432-b91b-669411205015', 'DET0322', '[{"name": "auditd:SYSCALL", "channel": "write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "SYSCALL ptrace/mprotect", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}]', '[{"field": "BinarySizeThreshold", "description": "Used to flag binaries much larger than typical shell utilities or payloads"}, {"field": "MemoryWriteTargets", "description": "Which processes are allowed ptrace/mprotect – can limit to suspicious child-to-parent targeting"}, {"field": "ExecutionAfterWriteWindow", "description": "Temporal threshold for file write to execution"}]', '2026-05-01 15:26:36.887526');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1699, 'AN0099', 'Analytic 0099', 'Monitors CLI-based execution of `show process` or equivalent on routers/switches. Correlates unusual device access, unauthorized roles, or config mode changes.', '{"Network Devices"}', 'x-mitre-analytic--f6985c70-6de1-4600-aba0-5b3324184dce', 'DET0034', '[{"name": "networkdevice:cli", "channel": "CLI command", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "networkdevice:syslog", "channel": "Admin activity", "x_mitre_data_component_ref": "x-mitre-data-component--ee575f4a-2d4f-48f6-b18b-89067760adc1"}]', '[{"field": "Username", "description": "Tunable based on authorized operators for network infrastructure"}, {"field": "CommandString", "description": "Pattern match or regex scope for discovery commands"}]', '2026-05-01 15:26:36.888922');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1700, 'AN0533', 'Analytic 0533', 'Use of pbpaste, AppleScript, or third-party automation frameworks (e.g., Automator) to collect clipboard or file content in bursts. Observable via unified logs.', '{macOS}', 'x-mitre-analytic--f6ad51e5-b869-455d-acb1-ef725acb27cb', 'DET0186', '[{"name": "macos:unifiedlog", "channel": "logMessage contains pbpaste or osascript", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "subsystem=launchservices", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}]', '[{"field": "AutomationTool", "description": "Detectable script interpreters or clipboard tools (pbpaste, osascript)."}, {"field": "ClipboardCheckRate", "description": "Threshold for how often clipboard access occurs within a given time window."}]', '2026-05-01 15:26:36.890762');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1701, 'AN0117', 'Analytic 0117', 'Adversary with write access to storage modifies lifecycle policies (e.g., via PutBucketLifecycle) to schedule rapid object deletion across one or more storage buckets. This is often used to trigger impact (destruction), remove logs (defense evasion), or force extortion (ransomware).', '{IaaS}', 'x-mitre-analytic--f6f90ad5-3182-4b1a-a612-51b251a8a34c', 'DET0041', '[{"name": "AWS:CloudTrail", "channel": "PutBucketLifecycle, PutLifecycleConfiguration, SetBucketLifecycle, storage.buckets.update", "x_mitre_data_component_ref": "x-mitre-data-component--45977f14-1bcc-4ec4-ac14-a30fd3a11f44"}]', '[{"field": "LifecycleExpirationDays", "description": "Policy values setting Expiration in fewer than N days (e.g., 0–1) are highly suspicious."}, {"field": "TargetBucket", "description": "Filter by bucket types (e.g., log storage, production DB snapshots) to prioritize detection."}, {"field": "Principal", "description": "Correlate rare or anomalous IAM principals making destructive lifecycle changes."}, {"field": "TimeWindow", "description": "Link lifecycle policy change with API activity suggesting staged deletion or extortion attempt."}]', '2026-05-01 15:26:36.892358');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1702, 'AN1087', 'Analytic 1087', 'Enumeration of identity roles and users via API calls such as `Get-MsolRoleMember`, `az ad user list`, or Graph API tokens from unauthorized users or automation accounts.', '{"Identity Provider"}', 'x-mitre-analytic--f74ce996-0982-4e2a-86ee-5bce001ee9fc', 'DET0386', '[{"name": "Microsoft Entra ID Audit Logs", "channel": "RoleManagement.Read.Directory or Directory.Read.All", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}, {"name": "azure:signinlogs", "channel": "Interactive/Non-Interactive Sign-In", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "m365:defender", "channel": "Activity Log: Command Invocation", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "TokenScope", "description": "Flags excessive or abnormal use of directory read scopes by unexpected principals."}, {"field": "AppContext", "description": "Differentiate authorized automation from rogue access tokens or external tools."}, {"field": "TimeWindow", "description": "Trigger correlation across short bursts of high-volume enumeration."}]', '2026-05-01 15:26:36.894015');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1703, 'AN1584', 'Analytic 1584', 'Use of bash scripts or interactive shells to issue sequential ping, arp, or traceroute commands to map remote hosts.', '{Linux}', 'x-mitre-analytic--f794d2f4-ad8e-4e11-b374-2c35f8ca38e9', 'DET0574', '[{"name": "auditd:EXECVE", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "network", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "TargetIPRange", "description": "Tune for sensitive internal segments or known lateral targets"}, {"field": "ShellContext", "description": "Distinguish user-interactive enumeration vs. cronjob or baseline tooling"}]', '2026-05-01 15:26:36.895218');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1704, 'AN0621', 'Analytic 0621', 'Processes invoking AVFoundation or CoreAudio frameworks, accessing input devices via TCC logs or Unified Logs, followed by writing AIFF/WAV/MP3 files to disk.', '{macOS}', 'x-mitre-analytic--f79a68ff-07f4-49ba-849b-9edb636f0b39', 'DET0221', '[{"name": "macos:unifiedlog", "channel": "audio APIs", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "Apple TCC Logs", "channel": "Microphone Access Events", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "fs:fsusage", "channel": "File IO", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "FrameworkCall", "description": "CoreAudio vs. AVFoundation vs. lower-level device access APIs."}, {"field": "TargetDirectory", "description": "Suspicious file drops (e.g., ~/Library/Caches/, /tmp/, nonstandard user folders)."}, {"field": "AnomalousParent", "description": "Unexpected parent-child relationship between non-media apps and AV capture."}]', '2026-05-01 15:26:36.896396');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1705, 'AN0047', 'Analytic 0047', 'Detects unauthorized termination of system daemons or commands issued through launchctl or kill to stop competing services or malware processes. Defenders should monitor unified logs and EDR telemetry for unusual service modifications or terminations.', '{macOS}', 'x-mitre-analytic--f84124d2-8bc6-4dae-a579-f0ddb0338a2f', 'DET0015', '[{"name": "macos:unifiedlog", "channel": "launchctl unload, kill, or pkill commands affecting daemons or background services", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "process_termination: Unexpected termination of processes tied to vulnerable or high-value services", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "ProtectedServiceList", "description": "Defines macOS services (e.g., securityd, keychain-related daemons) that should never be disabled."}]', '2026-05-01 15:26:36.897596');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1706, 'AN1054', 'Analytic 1054', 'Monitor for creation of new Power Automate flows or equivalent automation scripts that trigger on user or file events. Detect anomalous actions performed by these automations, such as email forwarding, anonymous link creation, or unexpected API calls to external endpoints.', '{"Office Suite"}', 'x-mitre-analytic--f8787a86-552b-4e03-8d68-7177001a215d', 'DET0374', '[{"name": "m365:unified", "channel": "AddFlow / UpdateFlow: New automation or workflow creation events", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "m365:exchange", "channel": "New-InboxRule: Automation that triggers abnormal forwarding or external link generation", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}]', '[{"field": "UserContext", "description": "Business units or users where automation creation is expected (developers, admins)"}, {"field": "FlowActions", "description": "Specific automation actions (email forwarding, file sharing) that should be considered suspicious"}]', '2026-05-01 15:26:36.899024');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1707, 'AN0332', 'Analytic 0332', 'Detects access to media files followed by execution of scripts (bash, Python, etc.) referencing those same files, or outbound traffic triggered shortly after file read. Correlates unusual use of tools like `steghide`, `exiftool`, or image libraries.', '{Linux}', 'x-mitre-analytic--f884a712-ace6-426c-ab81-8ff33e83be92', 'DET0119', '[{"name": "auditd:SYSCALL", "channel": "open", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "connect", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "MonitoredToolsList", "description": "Define the list of steganographic or image-parsing tools to alert on (e.g., `steghide`, `imagemagick`)"}, {"field": "ScriptInterpreterMatch", "description": "Tune to detect script engines accessing media files (e.g., `python script.py image.png`)"}]', '2026-05-01 15:26:36.901469');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1708, 'AN0519', 'Analytic 0519', 'Identify lateral transfer via datastore file uploads or internal scp/ssh sessions that result in new VMX/VMDK or script files. Correlate transfer with VM execution or datastore modification.', '{ESXi}', 'x-mitre-analytic--f8857048-181f-4883-a50b-65aca5204228', 'DET0183', '[{"name": "esxi:vmkernel", "channel": "Upload of file to datastore", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}, {"name": "esxi:hostd", "channel": "scp/ssh used to move file across hosts", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}]', '[{"field": "DatastoreWhitelist", "description": "Known authorized paths for legitimate VM operations"}, {"field": "TransferProtocol", "description": "Protocols allowed for intra-VM host transfers"}]', '2026-05-01 15:26:36.902973');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1709, 'AN0991', 'Analytic 0991', 'Detects VMs sending outbound traffic through non-standard services or to unknown destinations. Exfiltration over reverse shells tunneled via VMkernel or custom payloads routed via hostd/vpxa.', '{ESXi}', 'x-mitre-analytic--f8998263-e55f-428f-b8d0-46d9e31277d2', 'DET0348', '[{"name": "esxi:vpxa", "channel": "connection attempts and data transmission logs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "esxi:vmkernel", "channel": "network stack module logs", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}, {"name": "esxi:syslog", "channel": "guest OS outbound transfer logs", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "GuestOSAllowList", "description": "Limit detection to sensitive or externally-exposed VMs handling confidential data."}, {"field": "TransferSizeThresholdMB", "description": "Minimum outbound transfer size before flagging anomalous C2-based exfiltration."}, {"field": "ProtocolAllowList", "description": "Define expected protocols for outbound data (e.g., disallow FTP/SCP over high ports)."}]', '2026-05-01 15:26:36.904667');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1710, 'AN0487', 'Analytic 0487', 'Forged cookies in SaaS environments manifest as valid web sessions without matching login activity, MFA enforcement bypass, or cookies reused across multiple devices/IPs. Defenders should look for cookie replay, concurrent sessions from multiple geographies, or session tokens generated by unrecognized apps.', '{SaaS}', 'x-mitre-analytic--f8c255ac-8ba5-4971-9e11-420a10e688ad', 'DET0171', '[{"name": "m365:unified", "channel": "Session activity without correlated login event", "x_mitre_data_component_ref": "x-mitre-data-component--ff93f688-d7a4-49cf-9c79-a14454da8428"}, {"name": "saas:access", "channel": "Multiple concurrent logins using same cookie from different locations", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "TokenReplayThreshold", "description": "Number of concurrent uses of a cookie that should trigger an alert."}, {"field": "GeoLocationAlerts", "description": "Unusual SaaS logins from geographically distant locations in short timeframes."}]', '2026-05-01 15:26:36.906169');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1725, 'AN1461', 'Analytic 1461', 'Execution of files containing right-to-left override characters (U+202E) to masquerade true file extensions. Often found in phishing payloads or file downloads.', '{Windows}', 'x-mitre-analytic--fb330f70-f0f4-4a5b-9b91-37d29a097a4c', 'DET0527', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Windows Defender", "channel": "Operational", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "FilenamePattern", "description": "RTLO variants such as \\u202E, %E2%80%AE, or byte-encoded forms"}, {"field": "ExecutionContext", "description": "Allows tuning for untrusted sources, e.g., browser downloads or email attachments"}, {"field": "TimeWindow", "description": "Defines correlation between file creation and process execution"}]', '2026-05-01 15:26:36.929729');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1711, 'AN0327', 'Analytic 0327', 'Correlates inbound network access to remote service ports (e.g., SMB/RPC 445/135, RDP 3389, WinRM 5985/5986) with near-time instability in the target service (crash, abnormal restart), suspicious child process creation under the service, and post-access lateral-movement behaviors. The chain indicates likely exploitation rather than normal administration.', '{Windows}', 'x-mitre-analytic--f8c99f4f-f61e-436c-a093-c97969c9b038', 'DET0118', '[{"name": "WinEventLog:System", "channel": "EventCode=1000", "x_mitre_data_component_ref": "x-mitre-data-component--9c2fa0ae-7abc-485a-97f6-699e3b6cf9fa"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "NSM:Flow", "channel": "Inbound connections to 445, 3389, 5985-5986 with high error/connection-reset rate, followed by new outbound sessions from the same host to internal assets within short interval.", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ServicePortSet", "description": "List of monitored service ports (default: 445,135,3389,5985,5986,1433,3306)."}, {"field": "TimeWindow", "description": "Correlation window between inbound access and crash/child-process (default: 10 minutes)."}, {"field": "AllowedAdminCIDRs", "description": "Known management networks to suppress benign admin traffic."}, {"field": "MinConnErrorRate", "description": "Percent of failed/aborted connections to treat as anomalous (default: 30%)."}]', '2026-05-01 15:26:36.907999');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1712, 'AN0279', 'Analytic 0279', 'Detects invocation of lua or luajit interpreters by users or services outside of expected packages, chained with script drop or memory artifacts.', '{Linux}', 'x-mitre-analytic--f8e77c9a-2b8c-47d2-b44a-23857d246016', 'DET0101', '[{"name": "auditd:SYSCALL", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "auditd:SYSCALL", "channel": "PATH", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "ExecutablePath", "description": "Lua interpreter path may vary based on distro or adversary staging."}, {"field": "UserContext", "description": "May need to exclude service or admin accounts that use Lua legitimately."}]', '2026-05-01 15:26:36.909686');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1713, 'AN1528', 'Analytic 1528', 'Detects the creation or execution of padded binary files (e.g., large size but minimal legitimate content) followed by process execution or lateral movement from the host.', '{Windows}', 'x-mitre-analytic--f9079cb0-76ff-4b4a-a73c-4f6572e7eef5', 'DET0553', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Security", "channel": "EventCode=4663, 4670, 4656", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "FileSizeThresholdMB", "description": "Threshold size in MB to determine suspicious padding"}, {"field": "TimeWindow", "description": "Correlation time window between file creation and execution"}, {"field": "UserContext", "description": "Scope the detection to suspicious or non-standard user accounts"}]', '2026-05-01 15:26:36.910998');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1714, 'AN0593', 'Analytic 0593', 'Login to vSphere or ESXi hosts using domain accounts, especially those associated with vpxuser or unexpected group memberships.', '{ESXi}', 'x-mitre-analytic--f931e587-28f8-4923-b054-98d6348dcafe', 'DET0210', '[{"name": "esxi:vpxd", "channel": "/var/log/vmware/vpxd.log", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "esxi:hostd", "channel": "/var/log/hostd.log", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}]', '[{"field": "AccountType", "description": "Prioritize detection on accounts with elevated access."}, {"field": "LoginInterface", "description": "Distinguish interactive UI login from API or SSH access."}]', '2026-05-01 15:26:36.912183');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1715, 'AN0909', 'Analytic 0909', 'Unusual execution of virtualization binaries (VBoxManage.exe, vmware-vmx.exe, vmwp.exe) with headless or suppressed notification arguments. Registry and service modifications linked to virtualization installs. Defender view: anomalies in process creation, service metadata, and registry writes tied to enabling hidden VMs.', '{Windows}', 'x-mitre-analytic--f94e2ae3-7c79-4796-96a1-e462828f9c13', 'DET0321', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Security", "channel": "EventCode=4657", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}]', '[{"field": "VirtualizationBinaryWhitelist", "description": "Exclude known administrative VM software usage in enterprise environments."}, {"field": "TimeWindow", "description": "Correlate registry and service modifications with VM process starts within a narrow time frame."}]', '2026-05-01 15:26:36.913903');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1716, 'AN1334', 'Analytic 1334', 'Monitor ESXi syslog and esxcli outputs for abnormal DNS resolver behavior, such as frequent domain-to-IP changes or unauthorized modifications of DNS settings used by management agents. Correlate domain lookups with short TTL values.', '{ESXi}', 'x-mitre-analytic--f9534b4a-57ef-40a0-801a-d56a217304f0', 'DET0485', '[{"name": "esxi:syslog", "channel": "Frequent DNS resolution of same domain with rotating IPs", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "ResolverConfigPaths", "description": "Whitelist of expected DNS resolvers configured on ESXi"}, {"field": "ExternalDomainWhitelist", "description": "Known trusted external domains for hypervisor services"}]', '2026-05-01 15:26:36.91535');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1726, 'AN0888', 'Analytic 0888', 'Execution of commands or APIs that disable Gatekeeper, XProtect, or system integrity protections. Detect configuration changes through unified logs. Monitor termination of system security daemons (e.g., syspolicyd).', '{macOS}', 'x-mitre-analytic--fb51dd4c-b751-4282-a447-d9f5f257b435', 'DET0317', '[{"name": "macos:unifiedlog", "channel": "spctl --master-disable, csrutil disable, or defaults write to disable Gatekeeper", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:unifiedlog", "channel": "Termination of syspolicyd or XProtect processes", "x_mitre_data_component_ref": "x-mitre-data-component--61f1d40e-f3d0-4cc6-aa2d-937b6204194f"}]', '[{"field": "AdminToolWhitelist", "description": "Developers may legitimately disable Gatekeeper; whitelist approved contexts."}]', '2026-05-01 15:26:36.931118');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1717, 'AN0302', 'Analytic 0302', 'Atypical processes (e.g., powershell.exe, regsvr32.exe) encode large outbound traffic using Base64 or other character encodings; this traffic is sent over uncommon ports or embedded in protocol fields (e.g., HTTP cookies or headers).', '{Windows}', 'x-mitre-analytic--f979bacd-580c-4948-b501-c42dd4a8cb92', 'DET0108', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "Unusual Base64-encoded content in URI, headers, or POST body", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "PayloadEntropyThreshold", "description": "Adjust to accommodate legitimate compression or encryption patterns in normal web traffic"}, {"field": "ProcessAllowlist", "description": "Define expected processes initiating outbound traffic to reduce false positives"}, {"field": "AnomalyScoreThreshold", "description": "Set threshold for how far traffic deviates from baseline protocol structure or size"}]', '2026-05-01 15:26:36.916564');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1718, 'AN0524', 'Analytic 0524', 'Tracks suspicious use of ESXi shell commands or PowerCLI to delete logs, rotate system files, or tamper with hostd/vpxa history.', '{ESXi}', 'x-mitre-analytic--f9b13a61-0110-4882-9384-3468d22ac221', 'DET0184', '[{"name": "esxi:hostd", "channel": "rm, clearlogs, logrotate", "x_mitre_data_component_ref": "x-mitre-data-component--e905dad2-00d6-477c-97e8-800427abd0e8"}]', '[{"field": "LogSourceType", "description": "Tune per vCenter, vSphere, ESXi CLI telemetry collection"}, {"field": "LogPathPattern", "description": "Target specific high-value log paths (e.g., /var/log/hostd.log)"}]', '2026-05-01 15:26:36.917905');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1719, 'AN1543', 'Analytic 1543', 'Detection of compromised or misused valid accounts via anomalous logon patterns, abnormal logon types, and inconsistent geographic or time-based activity across Windows endpoints.', '{Windows}', 'x-mitre-analytic--f9c3a686-2894-498d-9d04-7ac510752e1f', 'DET0560', '[{"name": "WinEventLog:Security", "channel": "EventCode=4624", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "WinEventLog:Security", "channel": "EventCode=4776, 4625", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "LogonType", "description": "Flag unexpected logon types (e.g., Type 10 for remote interactive logins) for sensitive accounts."}, {"field": "TimeWindow", "description": "Define acceptable hours for interactive logon activity (e.g., 9AM-6PM local)."}, {"field": "GeoIPMismatch", "description": "Trigger on location anomalies based on prior user behavior or policy."}]', '2026-05-01 15:26:36.919196');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1720, 'AN0035', 'Analytic 0035', 'Execution of Wine or LibreOffice macros with inconsistent VBA metadata. Defender perspective: file analysis showing p-code embedded without matching source streams.', '{Linux}', 'x-mitre-analytic--f9f7e5e7-edbf-442b-b4ea-d35455982ba8', 'DET0012', '[{"name": "auditd:SYSCALL", "channel": "execve calls to soffice.bin with suspicious macro execution flags", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "linux:syslog", "channel": "Discrepancies in _VBA_PROJECT p-code vs source code extracted with oletools/pcodedmp", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "ScannerTooling", "description": "Choice of OLE/P-code analysis utilities (oletools, pcodedmp, custom disassembler)."}]', '2026-05-01 15:26:36.920433');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1721, 'AN0511', 'Analytic 0511', 'Creation or modification of stored procedures invoking xp_cmdshell or CLR assemblies for command execution and persistence.', '{Windows}', 'x-mitre-analytic--f9fb1a46-02f0-4d89-a3d9-6bed04bd47be', 'DET0181', '[{"name": "WinEventLog:Application", "channel": "Stored procedure creation, modification, or xp_cmdshell invocation via SQL logs or SQL Server auditing", "x_mitre_data_component_ref": "x-mitre-data-component--9f387817-df83-432a-b56b-a8fb7f71eedd"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Application", "channel": "CLR Assembly creation, loading, or modification logs via MSSQL CLR integration", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "xp_cmdshell_invocation_threshold", "description": "Adjust if legitimate procedures use xp_cmdshell often in environment"}, {"field": "CLRAssemblyNameWhitelist", "description": "Organization-defined whitelist of legitimate CLR assemblies"}, {"field": "TimeWindow", "description": "Tune time window to correlate stored procedure creation with process execution"}]', '2026-05-01 15:26:36.921991');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1722, 'AN0952', 'Analytic 0952', 'Detects unauthorized modification of host binaries, modules, or services within ESXi. Correlates tampered files with subsequent unexpected service behavior or malicious module load attempts.', '{ESXi}', 'x-mitre-analytic--fa36a169-1cca-4887-b362-e3cceb02414f', 'DET0336', '[{"name": "esxi:hostd", "channel": "binary or module replacement event", "x_mitre_data_component_ref": "x-mitre-data-component--84572de3-9583-4c73-aabd-06ea88123dd8"}, {"name": "esxi:vmkernel", "channel": "unexpected module load", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}]', '[{"field": "MonitoredModules", "description": "Define critical ESXi binaries and kernel modules requiring integrity validation"}, {"field": "CorrelationWindow", "description": "Adjust timing correlation between binary modification and module/service anomalies"}]', '2026-05-01 15:26:36.923779');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1723, 'AN0168', 'Analytic 0168', 'Command line interface or vCLI triggers remote transfer using wget or curl, writing files into datastore paths or local tmp directories.', '{ESXi}', 'x-mitre-analytic--fac5b2df-a58d-424e-a351-7d7ca05260e8', 'DET0060', '[{"name": "esxi:hostd", "channel": "command execution", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "esxi:vmkernel", "channel": "file write", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}]', '[{"field": "ToolName", "description": "Tune for wget, curl, netcat, and scripting languages in use"}, {"field": "DatastorePath", "description": "Filter or prioritize specific paths (e.g., /vmfs/volumes/)"}]', '2026-05-01 15:26:36.925462');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1724, 'AN0020', 'Analytic 0020', 'Remote access to third-party SaaS with OAuth or API tokens post-initial compromise, followed by sensitive data access or configuration changes', '{SaaS}', 'x-mitre-analytic--fb23f9ee-cdc8-46be-8f40-3631afbaff5a', 'DET0008', '[{"name": "saas:auth", "channel": "LoginSuccess, APIKeyUse, AdminAction", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "OAuthTokenAge", "description": "Older tokens issued before password change may indicate compromise"}, {"field": "AppScope", "description": "Restrict detection to high-value or regulated SaaS apps"}]', '2026-05-01 15:26:36.927948');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1728, 'AN0215', 'Analytic 0215', 'Detects adversarial use of cloud APIs for command execution, resource control, or reconnaissance. Focuses on CLI/SDK/scripting language abuse via stolen credentials or in-browser Cloud Shells. Monitors for anomalous API calls chained with authentication context shifts (e.g., stolen token -> privileged action) and cross-service impacts.', '{IaaS}', 'x-mitre-analytic--fb933fd5-5dd8-4879-b2bb-e68bc26ff60d', 'DET0078', '[{"name": "AWS:CloudTrail", "channel": "eventName: RunInstances, CreateUser, PutRolePolicy, InvokeCommand", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "azure:activity", "channel": "operationName: Write, Access Review, RoleAssignment", "x_mitre_data_component_ref": "x-mitre-data-component--e52d89f9-1710-4708-88a5-cbef77c4cd5e"}, {"name": "Okta:SystemLog", "channel": "eventType: user.authentication.sso, app.oauth2.token.grant", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}]', '[{"field": "TimeWindow", "description": "Off-hours API usage or configuration changes are more suspicious outside business context."}, {"field": "UserAgent", "description": "Unexpected SDK usage (e.g., `boto3`, `azcopy`, unknown User-Agent strings)."}, {"field": "CredentialType", "description": "High-risk if access token or API key used outside expected geographic/IP behavior."}, {"field": "APISequence", "description": "Unusual or rapid chaining of provisioning, IAM, and execution APIs."}, {"field": "ConsoleContext", "description": "Browser-based Cloud Shell vs local CLI may indicate insider vs external use case."}]', '2026-05-01 15:26:36.93401');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1729, 'AN0217', 'Analytic 0217', 'Detection of SSH/Telnet session hijacking via discrepancies between authentication logs and active session tables. Adversary behavior includes reusing or stealing active PTY sessions, attaching to screen/tmux, or issuing commands without corresponding login events.', '{Linux}', 'x-mitre-analytic--fba8a3f5-74d0-47d2-a688-1bdcc99dae6b', 'DET0079', '[{"name": "auditd:SYSCALL", "channel": "execve: Commands executed within an SSH session where no matching logon/authentication event exists", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Connections", "channel": "Mismatch between recorded user logon and active sessions (e.g., wtmp/utmp entries without corresponding authentication in auth.log)", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}, {"name": "NSM:Flow", "channel": "Long-lived or hijacked SSH sessions maintained with no active user activity", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "MonitoredServicePorts", "description": "Ports for SSH/Telnet/RDP monitored for session hijacking; may vary by environment."}]', '2026-05-01 15:26:36.935241');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1730, 'AN0398', 'Analytic 0398', 'Use of `usleep`, `nanosleep`, or `NSTimer` calls in executables or binaries with no GUI interaction, especially followed by disk/network activity.', '{macOS}', 'x-mitre-analytic--fbbe7372-5d33-4181-a68a-e68f5da94df7', 'DET0141', '[{"name": "macos:unifiedlog", "channel": "application logs referencing NSTimer, sleep, or launchd delays", "x_mitre_data_component_ref": "x-mitre-data-component--9bde2f9d-a695-4344-bfac-f2dce13d121e"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "AppBundleIdentifier", "description": "Correlate with known/expected signed apps vs. unsigned binaries to reduce noise."}, {"field": "TimeToNextEvent", "description": "Minimum time expected between process start and observable I/O for normal apps."}]', '2026-05-01 15:26:36.936633');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1731, 'AN0955', 'Analytic 0955', 'Access tokens or SSH keys used without corresponding login shell or PAM module activity, particularly for remote execution.', '{Linux}', 'x-mitre-analytic--fbe17895-73cc-432e-8576-f6cab851feb1', 'DET0338', '[{"name": "auditd:SYSCALL", "channel": "execution of ssh, scp, or sftp using previously unseen credentials or keys", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "NSM:Connections", "channel": "Accepted publickey for user from unusual IP or without tty", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "SourceIPWhitelist", "description": "Tune for approved jump boxes or bastion hosts"}, {"field": "AuthMethod", "description": "Filter on use of password vs publickey methods for better coverage"}]', '2026-05-01 15:26:36.937995');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1732, 'AN2036', 'Analytic 2036', 'Detects user-authorized execution of downloaded content or scripts after communication prompts, including browser downloads followed by osascript, shell, or installer execution and subsequent network activity.', '{macOS}', 'x-mitre-analytic--fc19b602-2811-418f-aa98-1b49f1355743', 'DET0899', '[{"name": "macos:unifiedlog", "channel": "Execution of osascript, sh, bash, zsh, installer, open", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "NSM:Connections", "channel": "Outbound connection after script or installer launch", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "macos:unifiedlog", "channel": "Recent download opened or executed", "x_mitre_data_component_ref": "x-mitre-data-component--235b7491-2d2b-4617-9a52-3c0783680f71"}]', '[{"field": "DownloadToExecutionWindow", "description": "Time between download and launch"}, {"field": "InstallerParentAllowlist", "description": "Legitimate software deployment parents"}]', '2026-05-01 15:26:36.939562');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1733, 'AN0448', 'Analytic 0448', 'Attachment of hardware-backed USB KVM devices (e.g., TinyPilot) that enumerate new HID or serial communication interfaces with identifiable metadata.', '{macOS}', 'x-mitre-analytic--fc3e13fd-cbee-4bb0-aae7-ce1e8af7d768', 'DET0159', '[{"name": "macos:unifiedlog", "channel": "Hardware enumeration events via IOKit or USBMuxd showing TinyPilot or unknown keyboard/mouse", "x_mitre_data_component_ref": "x-mitre-data-component--3d6e6b3b-4aa8-40e1-8c47-91db0f313d9f"}]', '[{"field": "DeviceClass", "description": "Input or HID devices may be benign or malicious depending on context; tune based on environment (e.g., BYOD/dev stations)."}, {"field": "SerialCorrelationDepth", "description": "Correlating serials across multiple device insertions may reduce noise but requires tuning."}]', '2026-05-01 15:26:36.941432');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1734, 'AN1504', 'Analytic 1504', 'Detects cloud account use for API calls that exceed normal scope, such as IAM changes or access to services never used before.', '{IaaS}', 'x-mitre-analytic--fc507123-4267-4cf8-9e30-a90a89043b20', 'DET0546', '[{"name": "AWS:CloudTrail", "channel": "ConsoleLogin, AssumeRole, ListAccessKeys, CreateUser", "x_mitre_data_component_ref": "x-mitre-data-component--a953ca55-921a-44f7-9b8d-3d40141aa17e"}, {"name": "gcp:audit", "channel": "admin.googleapis.com", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "ServiceInteractionBaseline", "description": "Custom list of expected service interactions per user or role."}, {"field": "RoleSwitchRateThreshold", "description": "Frequency of assume-role operations that triggers an alert."}]', '2026-05-01 15:26:36.942977');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1735, 'AN0612', 'Analytic 0612', 'Detection of container escape attempts via bind mounts, privileged containers, or abuse of docker.sock. Defenders may observe anomalous volume mount configurations (e.g., hostPath to / or /proc), unexpected privileged container launches, or use of container administration commands to access host resources. These events typically correlate with subsequent process execution on the host outside of normal container isolation.', '{Containers}', 'x-mitre-analytic--fc9161ef-3cab-45f5-a585-d78778d72f2b', 'DET0219', '[{"name": "docker:daemon", "channel": "container create/start with privileged flag or host volume mount", "x_mitre_data_component_ref": "x-mitre-data-component--a5ae90ca-0c4b-481c-959f-0eb18a7ff953"}, {"name": "kubernetes:apiserver", "channel": "Pod spec with hostPath or privileged securityContext", "x_mitre_data_component_ref": "x-mitre-data-component--d46272ce-a0fe-4256-855e-738de7bb63ee"}]', '[{"field": "AllowedHostPaths", "description": "List of directories permitted for hostPath volumes. Any access beyond these paths may be suspicious."}, {"field": "PrivilegedContainerThreshold", "description": "Number of privileged container launches expected in the environment. Exceeding this may indicate adversary behavior."}]', '2026-05-01 15:26:36.944501');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1736, 'AN0717', 'Analytic 0717', 'Defenders may detect adversaries forging web credentials in IaaS environments by monitoring for anomalous API activity such as AssumeRole or GetFederationToken being executed by unusual principals. These events often correlate with sudden logon sessions from unfamiliar IP addresses or regions. The chain is usually secret material misuse (stolen private key or password) → API request generating a new token → access to high-value resources.', '{IaaS}', 'x-mitre-analytic--fca70138-f183-4deb-b2a4-59908c76070b', 'DET0260', '[{"name": "AWS:CloudTrail", "channel": "AssumeRole, GetFederationToken API calls by unusual or new entities", "x_mitre_data_component_ref": "x-mitre-data-component--5f7c9def-0ddf-423b-b1f8-fb2ddeed0ce3"}, {"name": "AWS:CloudTrail", "channel": "Temporary security credentials used to authenticate into management console or APIs", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "AuthorizedRoleMappings", "description": "Define expected users and roles allowed to use AssumeRole or federation APIs."}, {"field": "GeoVelocityThreshold", "description": "Alert if the same user authenticates from geographically disparate locations within a short time."}]', '2026-05-01 15:26:36.946334');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1737, 'AN1376', 'Analytic 1376', 'Establishing network connections on uncommon ports or protocols following C2 disruption or blocking. Often executed by processes that typically exhibit no network activity.', '{Windows}', 'x-mitre-analytic--fcb2ed1a-2f39-47e8-9524-95ceac0ff383', 'DET0499', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "NSM:Flow", "channel": "uncommon ports", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}]', '[{"field": "DestinationPort", "description": "Can be tuned to include unexpected or high-entropy ports not typically associated with the process."}, {"field": "ProcessName", "description": "Useful to filter benign applications vs suspicious fallback attempts."}, {"field": "DataVolumeRatio", "description": "Tunable ratio of sent/received bytes to indicate potential C2 beaconing or exfiltration."}, {"field": "TimeWindow", "description": "Adjust temporal window to match likely fallback C2 retries after primary channel fails."}]', '2026-05-01 15:26:36.94764');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1738, 'AN0915', 'Analytic 0915', 'Identifies Mach-O binaries dropped into temporary directories with abnormally high binary size or padding patterns, followed by privilege escalation, `exec`, or memory mapping of other processes.', '{macOS}', 'x-mitre-analytic--fcc2b0dc-93c4-49de-abfe-6273c24d1d89', 'DET0322', '[{"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_MMAP", "x_mitre_data_component_ref": "x-mitre-data-component--d5fca4e4-e47a-487b-873f-3d22f8865e96"}, {"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_OPEN", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "TempFilePaths", "description": "Track dropped executables in ~/Library/, /tmp/, or /private/tmp/"}, {"field": "MachOPaddingThreshold", "description": "Define padding size or section entropy anomalies in Mach-O file format"}, {"field": "FollowOnPrivilegeEscalation", "description": "Detects whether the binary attempts privilege escalation within short execution window"}]', '2026-05-01 15:26:36.948979');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1739, 'AN0405', 'Analytic 0405', 'Detects forged Kerberos Golden Tickets by correlating anomalous Kerberos ticket lifetimes, unexpected encryption types (e.g., RC4 in modern domains), malformed fields in logon/logoff events, and TGS requests without preceding TGT requests. Also monitors for abnormal patterns of access associated with elevated privileges across multiple systems.', '{Windows}', 'x-mitre-analytic--fd614a66-7e99-4a69-9070-3c11036f0335', 'DET0144', '[{"name": "WinEventLog:Security", "channel": "EventCode=4672, 4634", "x_mitre_data_component_ref": "x-mitre-data-component--39b9db72-8b48-4595-a18d-db5bbba3091b"}, {"name": "WinEventLog:Security", "channel": "EventCode=4769", "x_mitre_data_component_ref": "x-mitre-data-component--02d090b6-8157-48da-98a2-517f7edd49fc"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "TicketLifetimeThreshold", "description": "Kerberos TGT ticket lifetime exceeding default domain duration; tunable to environment-specific policies."}, {"field": "AllowedEncryptionTypes", "description": "Valid encryption algorithms for Kerberos tickets; anomalies (e.g., RC4) may indicate forgery."}, {"field": "PrivilegedAccountPatterns", "description": "Baseline of privileged accounts expected to perform Kerberos operations; deviations indicate suspicious activity."}, {"field": "ProcessAllowlist", "description": "Expected processes interacting with lsass.exe; deviations may indicate credential dumping."}]', '2026-05-01 15:26:36.950235');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1740, 'AN1996', 'Analytic 1996', 'Once adversaries leverage serverless functions as infrastructure (ex: for command and control), it may be possible to look for unique characteristics associated with adversary software, if known.(Citation: ThreatConnect Infrastructure Dec 2020) Much of this activity will take place outside the visibility of the target organization, making detection of this behavior difficult. Detection efforts may be focused on related stages of the adversary lifecycle. ', '{PRE}', 'x-mitre-analytic--fd652339-e12f-4295-b843-0665680054bd', 'DET0864', '[{"name": "Internet Scan", "channel": "None", "x_mitre_data_component_ref": "x-mitre-data-component--0dcbbf4f-929c-489a-b66b-9b820d3f7f0e"}]', NULL, '2026-05-01 15:26:36.951342');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1741, 'AN0140', 'Analytic 0140', 'Adversaries writing or moving payloads into directories configured as AV/EDR exclusion paths (e.g., /tmp, /var/lib, or custom directories from auditd exclusion rules). Defender perspective: detect file creation in paths matching known exclusions correlated with unusual parent processes.', '{Linux}', 'x-mitre-analytic--fd7bf05d-6f80-471c-99bf-7aa82ab25440', 'DET0051', '[{"name": "auditd:SYSCALL", "channel": "open or creat syscalls targeting excluded paths", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "auditd:PATH", "channel": "file path matches exclusion directories", "x_mitre_data_component_ref": "x-mitre-data-component--639e87f3-acb6-448a-9645-258f20da4bc5"}]', '[{"field": "ExcludedDirectories", "description": "System- or security-tool-configured exclusion directories where files should rarely change."}, {"field": "CorrelationWindow", "description": "Time window to correlate file creation in excluded paths with execution or network activity."}]', '2026-05-01 15:26:36.952611');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1742, 'AN1013', 'Analytic 1013', 'Flood of spoofed SYN or ACK packets causing exhaustion of OS TCP state table, potentially via user-space utilities or kernel-level DoS agents.', '{Linux}', 'x-mitre-analytic--fde025ac-a180-472c-a9b5-b4fa1e97cc75', 'DET0356', '[{"name": "auditd:SYSCALL", "channel": "Invocation of packet generation tools (e.g., hping3, nping) or fork bombs", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "NSM:Flow", "channel": "High volumes of SYN/ACK packets with unacknowledged TCP handshakes", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "TCP: possible SYN flood or backlog limit exceeded", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "AmplificationThreshold", "description": "Volume of fake TCP requests before OS begins degradation"}, {"field": "Interface", "description": "Which network interface is being targeted or impacted"}]', '2026-05-01 15:26:36.955706');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1743, 'AN1140', 'Analytic 1140', 'Outbound spoofed traffic to known amplification protocols (e.g., DNS, NTP, Memcached) combined with abnormal network traffic volume targeting remote reflectors, resulting in disproportionate traffic returned to a victim', '{Windows}', 'x-mitre-analytic--fdf11d76-3bd7-41c4-b117-7b0f17b31b17', 'DET0408', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "Windows:perfmon", "channel": "Sudden spike in outbound throughput without corresponding inbound traffic", "x_mitre_data_component_ref": "x-mitre-data-component--85a533a4-5fa4-4dba-b45d-f0717bedd6e6"}]', '[{"field": "TimeWindow", "description": "Interval for measuring sudden outbound spike or volume pattern"}, {"field": "AmplificationProtocolPorts", "description": "List of known ports used for reflection amplification (e.g., 53/DNS, 123/NTP, 11211/Memcached)"}, {"field": "PacketToByteRatio", "description": "Heuristic threshold where the response volume far outweighs the request volume"}]', '2026-05-01 15:26:36.95791');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1744, 'AN1409', 'Analytic 1409', 'Detects SVGs downloaded via browser that invoke AppleScript, osascript, or JavaScriptCore processes, followed by network egress or file drop to LaunchAgents or ~/Library.', '{macOS}', 'x-mitre-analytic--fe1cff12-9772-4ba9-92bc-c26eae79da24', 'DET0510', '[{"name": "macos:endpointsecurity", "channel": "ES_EVENT_TYPE_NOTIFY_EXEC", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "macos:unifiedlog", "channel": "subsystem: com.apple.WebKit or com.apple.WebKit.Networking", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "ScriptEngines", "description": "Scriptable binaries such as osascript, jsc, JavaScriptCore – may vary by OS version"}, {"field": "UserContext", "description": "Restrict to non-system users or only specific login sessions"}, {"field": "EmbeddedContentIndicators", "description": "SVGs embedded inside PDFs or HTML with script-based triggers"}]', '2026-05-01 15:26:36.959739');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1745, 'AN0714', 'Analytic 0714', 'Adversary installation or use of RMM software (e.g., TeamViewer, AnyDesk, ScreenConnect) followed by outbound beaconing or remote session establishment', '{Windows}', 'x-mitre-analytic--fe1e10ae-ddd2-40f0-8e62-3db88c0c8c68', 'DET0259', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}, {"name": "WinEventLog:Microsoft-Windows-Windows Firewall With Advanced Security/Firewall", "channel": "new rule allowing inbound or outbound connections for remote desktop software", "x_mitre_data_component_ref": "x-mitre-data-component--d2ff4b56-8351-4ed8-b0fb-d8605366005f"}]', '[{"field": "Image", "description": "RMM software can vary; defenders should update rules to account for additional binaries (e.g., ConnectWise, Zoho Assist)"}, {"field": "DestinationPort", "description": "RMM software may use configurable or random high ports outside of standard (e.g., 7070, 5650)"}, {"field": "ParentImage", "description": "Expected parent process may vary in different enterprise contexts"}, {"field": "TimeWindow", "description": "Correlation window for install-to-beacon or process-to-network event should match operational environment"}]', '2026-05-01 15:26:36.961519');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1746, 'AN1589', 'Analytic 1589', 'Creation of inbox rules via PowerShell (New-InboxRule) or transport rules using Exchange cmdlets. Correlates user behavior, cmdlet usage, and rule properties.', '{Windows}', 'x-mitre-analytic--fe489775-b01e-4da2-a0e2-962d1572ba09', 'DET0576', '[{"name": "WinEventLog:PowerShell", "channel": "EventCode=4103, 4104, 4105, 4106", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "m365:exchange", "channel": "Cmdlet - New-InboxRule", "x_mitre_data_component_ref": "x-mitre-data-component--b33d36e3-d7ea-4895-8eed-19a08a8f7c4f"}]', '[{"field": "UserContext", "description": "Certain service accounts or admin contexts may be expected to run these rules."}, {"field": "TimeWindow", "description": "Correlate between rule creation and follow-on message forwarding within this timeframe."}, {"field": "TargetMailbox", "description": "Whitelisted or trusted destination addresses may be tuned per org policy."}]', '2026-05-01 15:26:36.963178');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1747, 'AN1124', 'Analytic 1124', 'Detects clients issuing DNS queries with high volume, long subdomain lengths, encoded payload patterns, or to known malicious infrastructure; indicative of DNS-based C2 channels.', '{"Network Devices"}', 'x-mitre-analytic--fe648823-66c8-4cc3-8a8e-38616194464c', 'DET0400', '[{"name": "NSM:Flow", "channel": "dns.log", "x_mitre_data_component_ref": "x-mitre-data-component--3772e279-27d6-477a-9fe3-c6beb363594c"}]', '[{"field": "DomainReputationFeed", "description": "List of suspicious/malicious C2 domains"}, {"field": "QueryRatePerClient", "description": "Tunable burst rate per IP per second"}]', '2026-05-01 15:26:36.96469');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1748, 'AN0845', 'Analytic 0845', 'Router/switch receives a knock pattern (same src touches device unicast, broadcast, and network-address on same or stepped ports) followed by ACL/line-vty/service enable and the first mgmt session success.', '{"Network Devices"}', 'x-mitre-analytic--fe82e2a6-a928-4fe0-a899-fead90eabb29', 'DET0302', '[{"name": "networkdevice:syslog", "channel": "Config/ACL changes, line vty transport input changes, telnet/ssh/http(s) enable, image/feature module changes.", "x_mitre_data_component_ref": "x-mitre-data-component--a7f22107-02e5-4982-9067-6625d4a1765a"}, {"name": "NSM:Flow", "channel": "Series of denied/closed flows to distinct ports then success to mgmt port from same src_ip within TimeWindow.", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "MgmtPortSet", "description": "Mgmt ports to focus on: 22,23,2323,80,443,161,4786."}, {"field": "DeviceRole", "description": "Tighten thresholds on edge/internet-facing devices."}]', '2026-05-01 15:26:36.966022');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1749, 'AN1127', 'Analytic 1127', 'Unusual enumeration of services and resources through cloud APIs such as AWS CLI `describe-*`, Azure Resource Manager queries, or GCP project listings. Defender perspective includes anomalous API calls, unexpected volume of service enumeration, and correlation of discovery with recently compromised sessions.', '{IaaS}', 'x-mitre-analytic--fe8c1ef5-59ed-40c3-b7f6-eb560555ee22', 'DET0402', '[{"name": "AWS:CloudTrail", "channel": "DescribeInstances, DescribeServices, ListFunctions: High frequency enumeration calls or unusual user agents performing discovery", "x_mitre_data_component_ref": "x-mitre-data-component--8c826308-2760-492f-9e36-4f0f7e23bcac"}, {"name": "AWS:CloudTrail", "channel": "AssumeRole: Discovery actions tied to assumed identities outside of normal context", "x_mitre_data_component_ref": "x-mitre-data-component--b5d0492b-cda4-421c-8e51-ed2b8d85c5d0"}]', '[{"field": "EnumerationRateThreshold", "description": "Rate of API calls used to enumerate services; tuned to reduce noise from automated inventory tools."}, {"field": "UserAgentFilter", "description": "Expected user agents for cloud management tools; deviations may indicate adversarial tools."}]', '2026-05-01 15:26:36.967613');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1750, 'AN0886', 'Analytic 0886', 'Unusual service stop events, termination of AV/EDR processes, registry modifications disabling security tools, and firewall/defender configuration changes. Correlate process creation with service stop requests and registry edits.', '{Windows}', 'x-mitre-analytic--febc685b-997f-4095-b60b-5dfeefe01ae3', 'DET0317', '[{"name": "WinEventLog:Security", "channel": "EventCode=4688", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:System", "channel": "EventCode=7045", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=12", "x_mitre_data_component_ref": "x-mitre-data-component--7f70fae7-a68d-4730-a83a-f260b9606129"}]', '[{"field": "ProcessWhitelist", "description": "Exclude authorized administrative tools that stop services during maintenance."}, {"field": "ServiceNamePatterns", "description": "Refine which services are considered security-critical (e.g., AV, EDR, firewall)."}]', '2026-05-01 15:26:36.968889');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1751, 'AN1945', 'Analytic 1945', 'Much of this activity may have a very high occurrence and associated false positive rate, as well as potentially taking place outside the visibility of the target organization, making detection difficult for defenders.
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1752, 'AN1185', 'Analytic 1185', 'Detection focuses on abnormal service executions initiated via service control manager APIs, sc.exe, net.exe, or PsExec creating temporary services. Defenders observe process creation of services.exe spawning non-standard binaries, registry changes in service keys followed by rapid execution, and network connections originating from processes tied to transient services. Correlation across process lineage, registry activity, and service logs provides strong signals of malicious service execution.', '{Windows}', 'x-mitre-analytic--fedc5a7d-4ea9-4dd7-b2e0-3f10549d90db', 'DET0421', '[{"name": "WinEventLog:Security", "channel": "EventCode=4697", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=3, 22", "x_mitre_data_component_ref": "x-mitre-data-component--181a9f8c-c780-4f1f-91a8-edb770e904ba"}]', '[{"field": "ServiceBinaryAllowlist", "description": "Known binaries/services expected to be invoked via services.exe"}, {"field": "ParentProcessCorrelationWindow", "description": "Time window for correlating service creation with execution events"}, {"field": "RemoteExecutionHosts", "description": "Approved remote hosts that may trigger service execution (e.g., via PsExec)"}]', '2026-05-01 15:26:36.971673');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1753, 'AN1428', 'Analytic 1428', 'Detects the execution of scripting or command interpreters (e.g., powershell.exe, cmd.exe, wscript.exe) outside expected administrative time windows or from abnormal user contexts, often followed by encoded/obfuscated arguments or secondary execution events.', '{Windows}', 'x-mitre-analytic--fee823fd-f31e-4898-820e-322e49574438', 'DET0516', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "CommandLinePattern", "description": "Tunable to match encoded or uncommon script execution patterns specific to the environment."}, {"field": "ParentProcessName", "description": "May vary across managed/unmanaged workstations or user-driven script activity."}, {"field": "TimeWindow", "description": "Used to restrict analysis to work hours or known admin maintenance windows."}]', '2026-05-01 15:26:36.973427');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1754, 'AN0719', 'Analytic 0719', 'Forged web credentials on Windows endpoints may be detected by anomalous browser cookie files, local token cache manipulations, or tools injecting tokens into sessions. Defenders may observe processes accessing LSASS or browser credential stores unexpectedly, followed by unusual logon sessions.', '{Windows}', 'x-mitre-analytic--ff0d2f8d-1fff-4bda-94e6-c0cd50abe6ed', 'DET0260', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}, {"name": "WinEventLog:Security", "channel": "EventCode=4624, 4648", "x_mitre_data_component_ref": "x-mitre-data-component--9ce98c86-8d30-4043-ba54-0784d478d0b5"}]', '[{"field": "ProcessWhitelist", "description": "Define expected processes that access LSASS or browser credential files."}]', '2026-05-01 15:26:36.975317');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1755, 'AN0866', 'Analytic 0866', 'Detects unexpected use of usermod, gpasswd, or direct modification of /etc/group to elevate user group membership.', '{Linux}', 'x-mitre-analytic--ff692121-8bbd-4d22-8192-fe6a7dd94f57', 'DET0310', '[{"name": "auditd:SYSCALL", "channel": "SYSCALL for usermod or /etc/group file modification", "x_mitre_data_component_ref": "x-mitre-data-component--d27b0089-2c39-4b6c-84ff-303e48657e77"}]', '[{"field": "GroupName", "description": "Focus on ''sudo'', ''wheel'', or custom high-privilege groups"}, {"field": "UserContext", "description": "Account that initiated the change (e.g., service account or unrecognized user)"}, {"field": "TimeWindow", "description": "Detect elevation outside change windows"}]', '2026-05-01 15:26:36.977051');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1756, 'AN1527', 'Analytic 1527', 'Detects creation or modification of Windows Services through command-line tools (e.g., `sc.exe`, `powershell.exe`), Registry key changes under `HKLM\System\CurrentControlSet\Services`, and service execution under SYSTEM with unsigned or anomalous binary paths. Detects privilege escalation via driver installation or `CreateServiceW` usage. Correlates parent-child lineage, startup behavior, and rare service names.', '{Windows}', 'x-mitre-analytic--ffaa281c-dd99-486d-bc7f-225580f784f4', 'DET0552', '[{"name": "WinEventLog:Security", "channel": "EventCode=4697", "x_mitre_data_component_ref": "x-mitre-data-component--5297a638-1382-4f0c-8472-0d21830bf705"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=1", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=6", "x_mitre_data_component_ref": "x-mitre-data-component--3551476e-14f5-4e48-a518-e82135329e03"}]', '[{"field": "ServiceNamePattern", "description": "Regex for suspicious or uncommon service names (e.g., `svhostx`, `winhelp`, etc.)"}, {"field": "ImagePathFilter", "description": "Flag services whose image path resides in uncommon directories (e.g., `C:\\Users\\`, `C:\\Temp\\`)"}, {"field": "DriverExtensionList", "description": "Watch for `.sys` files loaded by `sc`, Registry, or `ZwLoadDriver` APIs"}, {"field": "StartupTypeChangeWindow", "description": "Temporal window to correlate Registry `Start` key changes with service creation"}, {"field": "UnsignedBinaryAlert", "description": "Raise alerts for unsigned binaries registered as services"}]', '2026-05-01 15:26:36.978641');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1757, 'AN1563', 'Analytic 1563', 'Execution of commands to query system locale and language settings, such as ''defaults read -g AppleLocale'' or ''systemsetup -gettimezone''. Unusual parent processes or execution contexts of these commands may indicate adversarial discovery.', '{macOS}', 'x-mitre-analytic--ffc71b21-982b-4fc7-8276-bd679d67bc95', 'DET0565', '[{"name": "macos:unifiedlog", "channel": "defaults read -g AppleLocale or systemsetup -gettimezone", "x_mitre_data_component_ref": "x-mitre-data-component--685f917a-e95e-4ba0-ade1-c7d354dae6e0"}, {"name": "macos:osquery", "channel": "execve", "x_mitre_data_component_ref": "x-mitre-data-component--3d20385b-24ef-40e1-9f56-f39750379077"}]', '[{"field": "ExecutionPath", "description": "Restrict or monitor processes outside of system utilities that query AppleLocale or system language settings."}]', '2026-05-01 15:26:36.980553');
INSERT INTO public.mitre_analytics (id, analytic_code, name, description, platforms, stix_id, det_code, log_source_refs, mutable_elements, created_at) VALUES (1758, 'AN0074', 'Analytic 0074', 'Correlated registry modifications under Print Processors path, followed by DLL file creation within the system print processor directory, and DLL load by spoolsv.exe. Malicious execution often occurs during service restart or system boot, with SYSTEM-level privileges.', '{Windows}', 'x-mitre-analytic--ffe7278f-7cd1-402f-a3a7-dcc7a363b031', 'DET0026', '[{"name": "WinEventLog:Sysmon", "channel": "EventCode=13, 14", "x_mitre_data_component_ref": "x-mitre-data-component--da85d358-741a-410d-9433-20d6269a6170"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=11", "x_mitre_data_component_ref": "x-mitre-data-component--2b3bfe19-d59a-460d-93bb-2f546adc2d2c"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=7", "x_mitre_data_component_ref": "x-mitre-data-component--c0a4a086-cc20-4e1e-b7cb-29d99dfa3fb1"}, {"name": "WinEventLog:Sysmon", "channel": "EventCode=10", "x_mitre_data_component_ref": "x-mitre-data-component--1887a270-576a-4049-84de-ef746b2572d6"}]', '[{"field": "TimeWindow", "description": "Correlate Registry + DLL Write + Module Load within a short boot or spooler restart window (e.g., 5 minutes)."}, {"field": "PrintProcessorDirectory", "description": "System-specific path derived from GetPrintProcessorDirectory API call; may differ across Windows versions or configurations."}, {"field": "DLLNamePattern", "description": "Some environments may use custom or non-standard DLL naming conventions for print processors. Allowlist known values."}, {"field": "SignedImageValidation", "description": "Check Authenticode signature and issuer chain for loaded DLLs to reduce false positives."}, {"field": "ServiceRestartTrigger", "description": "Monitor for spoolsv.exe restart events that trigger malicious print processor loading."}]', '2026-05-01 15:26:36.98192');
